function ACUBuildUnit(aiBrain, oACU, iCategoryToBuild, iMaxAreaToSearchForAdjacencyAndUnderConstruction, iMaxAreaToSearchForBuildLocation, iOptionalAdjacencyCategory, iOptionalCategoryBuiltUnitCanBuild, tOptionalSearchLocation)
    local sFunctionRef = 'ACUBuildUnit'
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)

    --Do we have a nearby unit of the type we want to build under construction?
    local tNearbyUnitsOfCategoryToBuild = aiBrain:GetUnitsAroundPoint(iCategoryToBuild, oACU:GetPosition(), iMaxAreaToSearchForAdjacencyAndUnderConstruction, 'Ally')
    local oNearestPartComplete

    if AiBotUtilities.IsTableEmpty(tNearbyUnitsOfCategoryToBuild) == false then
        local iClosestUnit = 10000
        local iCurDist
        for _, oUnit in tNearbyUnitsOfCategoryToBuild do
            if oUnit:GetFractionComplete() < 1 and not(oUnit[AiBotEngineer.refbDontIncludeAsPartCompleteBuildingForConstruction]) then --Dont want to assist shields for shield defence
                iCurDist = AiBotUtilities.GetTravelDistanceBetweenPositions(oUnit:GetPosition(), oACU:GetPosition(), AiBotMap.refPathingTypeAmphibious)
                if iCurDist < iClosestUnit then
                    oNearestPartComplete = oUnit
                    iClosestUnit = iCurDist
                end
            end
        end
    end
    if bDebugMessages == true then LOG(sFunctionRef..': Time='..GetGameTimeSeconds()..'; brain='..aiBrain.Nickname..'; ACU='..oACU.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oACU)..'; Is tNearbyUnitsOfCategoryToBuild empty='..tostring(AiBotUtilities.IsTableEmpty(tNearbyUnitsOfCategoryToBuild))..'; Is oNearestPartComplete valid='..tostring(AiBotUnitInfo.IsUnitValid(oNearestPartComplete))..'; ACU position='..repru(oACU:GetPosition())) end
    if AiBotUnitInfo.IsUnitValid(oNearestPartComplete) then
        if bDebugMessages == true then LOG(sFunctionRef..': Will assist part complete building='..oNearestPartComplete.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oNearestPartComplete)) end
        local tLastOrder = oACU[AiBotOrders.reftiLastOrders][oACU[AiBotOrders.refiOrderCount]]
        --if not(tLastOrder[AiBotOrders.subrefoOrderUnitTarget] == oNearestPartComplete) then --Dont need this step, as the order already takes this into account, and reissues once we get within build range
        AiBotOrders.IssueTrackedRepair(oACU, oNearestPartComplete, false, 'ACUComplB', false)
        --AiBotOrders.IssueTrackedGuard(oACU, oNearestPartComplete, false)
        --end

    else
        --No nearby under construction factory, so build one unless we allready have a queued orer to build one
        oACU[refbACUHasBeenGivenABuildOrderRecently] = true
        local bAlreadyHaveOrder = false
        AiBotOrders.UpdateRecordedOrders(oACU)
        local tLastOrder = oACU[AiBotOrders.reftiLastOrders][oACU[AiBotOrders.refiOrderCount]]
        --NOTE: Dont do location check, as we will exclude queued locations; i.e. first time this runs ACU queues land fac; second time it runs if it looks for a location to build it treats the first location as unavailable (due to the queued order) so tries somewhere else
        if tLastOrder[AiBotOrders.subrefsOrderBlueprint] and EntityCategoryContains(iCategoryToBuild, tLastOrder[AiBotOrders.subrefsOrderBlueprint]) then
            bAlreadyHaveOrder = true
        end
        if bDebugMessages == true then LOG(sFunctionRef..': tLastOrder='..reprs(tLastOrder)..'; bAlreadyHaveOrder='..tostring(bAlreadyHaveOrder)) end
        if not(bAlreadyHaveOrder) then
            local tLZData, tLZTeamData = AiBotMap.GetLandOrWaterZoneData(oACU:GetPosition(), true, oACU:GetAIBrain().AiBotTeam)
            --GetBlueprintAndLocationToBuild(aiBrain, oEngineer, iOptionalEngineerActionForDebug, iCategoryToBuild, iMaxAreaToSearch,                                   iCatToBuildBy,              tAlternativePositionToLookFrom, bLookForQueuedBuildings, oUnitToBuildBy, iOptionalCategoryForStructureToBuild, bBuildCheapestStructure, tLZData, tLZTeamData)
            local sBlueprint, tBuildLocation =                       AiBotEngineer.GetBlueprintAndLocationToBuild(aiBrain, oACU,        nil,                            iCategoryToBuild, iMaxAreaToSearchForAdjacencyAndUnderConstruction, iOptionalAdjacencyCategory, tOptionalSearchLocation,            false,                      nil,         iOptionalCategoryBuiltUnitCanBuild,    nil,                        tLZData, tLZTeamData)
            if not(tBuildLocation) then sBlueprint, tBuildLocation = AiBotEngineer.GetBlueprintAndLocationToBuild(aiBrain, oACU,          nil,                        iCategoryToBuild,    iMaxAreaToSearchForBuildLocation,                  nil,                         tOptionalSearchLocation,        false,                      nil,         iOptionalCategoryBuiltUnitCanBuild, nil,                           tLZData, tLZTeamData) end
            if bDebugMessages == true then
                local iPlateauOrZero, iLandOrWaterZone = AiBotMap.GetClosestPlateauOrZeroAndZoneToPosition(oACU:GetPosition())
                LOG(sFunctionRef..': Blueprint to build='..(sBlueprint or 'nil')..'; tBuildLocation='..repru(tBuildLocation)..'; ACU plateau and land zone based on cur position='..iPlateauOrZero..'; Land or water zone='..(iLandOrWaterZone or 'nil')..'; iMaxAreaToSearchForBuildLocation='..(iMaxAreaToSearchForBuildLocation or 'nil')..'; was iOptionalAdjacencyCategory nil='..tostring(iOptionalAdjacencyCategory == nil)..'; tLZData midpoint='..repru(tLZData[AiBotMap.subrefMidpoint])..'; Is team data empty='..tostring(AiBotUtilities.IsTableEmpty(tLZTeamData))..'; iMaxAreaToSearchForAdjacencyAndUnderConstruction='..(iMaxAreaToSearchForAdjacencyAndUnderConstruction or 'nil'))
                if sBlueprint and tBuildLocation then
                    LOG(sFunctionRef..': Can build structure at target='..tostring(aiBrain:CanBuildStructureAt(sBlueprint, tBuildLocation)))
                end
            end
            if sBlueprint and tBuildLocation then
                --If our last order was to build this unit (ignoring location)
                --Move to the target and then build on it
                local tMoveTarget = AiBotEngineer.GetLocationToMoveForConstruction(oACU, tBuildLocation, sBlueprint)
                if tMoveTarget then
                    --IssueTrackedMoveAndBuild(oUnit, tBuildLocation, sOrderBlueprint, tMoveTarget, iDistanceToReorderMoveTarget, bAddToExistingQueue)
                    AiBotOrders.IssueTrackedMoveAndBuild(oACU, tBuildLocation, sBlueprint, tMoveTarget, 2, false)
                else
                    AiBotOrders.IssueTrackedBuild(oACU, tBuildLocation, sBlueprint, false)
                end
            else
                --AiBotOrders.UpdateRecordedOrders(oACU) --now are doing this earlier on
            end
        else
            --Consider reissuing the same order if we are close
            if bDebugMessages == true then LOG(sFunctionRef..': Deciding whether to reissue order to build, last order position='..repru(tLastOrder[AiBotOrders.subreftOrderPosition])..'; Dist to ACU position='..AiBotUtilities.GetDistanceBetweenPositions(tLastOrder[AiBotOrders.subreftOrderPosition], oACU:GetPosition())..'; BUilding radius+ACU build distance - 0.1='..(oACU:GetBlueprint().Economy.MaxBuildDistance + AiBotUnitInfo.GetBuildingSize(tLastOrder[AiBotOrders.subrefsOrderBlueprint]) * 0.5 - 0.1)) end
            if AiBotUtilities.IsTableEmpty(tLastOrder[AiBotOrders.subreftOrderPosition]) == false and AiBotUtilities.GetDistanceBetweenPositions(tLastOrder[AiBotOrders.subreftOrderPosition], oACU:GetPosition()) <= oACU:GetBlueprint().Economy.MaxBuildDistance + AiBotUnitInfo.GetBuildingSize(tLastOrder[AiBotOrders.subrefsOrderBlueprint]) * 0.5 - 0.1 then
                if bDebugMessages == true then LOG(sFunctionRef..': Will attempt to reissue build order') end
                AiBotOrders.IssueTrackedClearCommands(oACU)
                AiBotOrders.IssueTrackedBuild(oACU, tLastOrder[AiBotOrders.subreftOrderPosition], tLastOrder[AiBotOrders.subrefsOrderBlueprint], false)
            end
        end
    end

    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
end

function ACUActionBuildFactory(aiBrain, oACU, iPlateauOrZero, iLandOrWaterZone, tLZData, tLZTeamData, iFactoryCategoryOverride, iEngineerActionOverride)
    local sFunctionRef = 'ACUActionBuildFactory'
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)

    local iMaxAreaToSearch = 35
    local iCategoryToBuild
    if bDebugMessages == true then LOG(sFunctionRef..': Start of code for aiBrain '..aiBrain.Nickname..' at time '..GetGameTimeSeconds()) end
    if AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.subreftoLZOrWZAlliedUnits]) and GetGameTimeSeconds() >= 60 and iPlateauOrZero > 0 and tLZTeamData[AiBotMap.subrefLZbCoreBase] then AiBotUtilities.ErrorHandler('Empty allied units table, iPlateauOrZero='..(iPlateauOrZero or 'nil')..'; iLandOrWaterZone='..(iLandOrWaterZone or 'nil')..'; Is LZTeamData empty='..tostring(AiBotUtilities.IsTableEmpty(tLZTeamData))) end
    if iFactoryCategoryOverride then iCategoryToBuild = iFactoryCategoryOverride
    else
        local iTeam = oACU:GetAIBrain().AiBotTeam
        if bDebugMessages == true then LOG(sFunctionRef..': Checking if we want to build an air factory, do we want air instead of land='..tostring(AiBotConditions.DoWeWantAirFactoryInsteadOfLandFactory(iTeam, tLZData, tLZTeamData, aiBrain))..'; Is tLZTeamData[AiBotMap.subreftoLZOrWZAlliedUnits] empty='..tostring(AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.subreftoLZOrWZAlliedUnits]))..'; tLZTeamData[CoreBase]='..tostring(tLZTeamData[AiBotMap.subrefLZbCoreBase])) end
        if AiBotConditions.DoWeWantAirFactoryInsteadOfLandFactory(iTeam, tLZData, tLZTeamData, aiBrain) then iCategoryToBuild = AiBotUnitInfo.refCategoryAirFactory
        else iCategoryToBuild = AiBotUnitInfo.refCategoryLandFactory
        end
    end

    -- ACU factory orders bypass engineer action assignment, so apply the
    -- same Dual Gap role contract here as well. Without this check an eco
    -- slot could still add an air/naval factory directly from its ACU.
    local dualGapFactoryType
    if iCategoryToBuild == AiBotUnitInfo.refCategoryLandFactory then
        dualGapFactoryType = 'land'
    elseif iCategoryToBuild == AiBotUnitInfo.refCategoryAirFactory then
        dualGapFactoryType = 'air'
    elseif iCategoryToBuild == AiBotUnitInfo.refCategoryNavalFactory then
        dualGapFactoryType = 'navy'
    end
    if dualGapFactoryType and not AiBotDualGap.CanBuildFactory(aiBrain, dualGapFactoryType) then
        if bDebugMessages then
            LOG(sFunctionRef..': Dual Gap blocked ACU '..dualGapFactoryType..' factory for role='..tostring(aiBrain.AiBotDualGapRole)..'; time='..tostring(GetGameTimeSeconds()))
        end
        AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
        return
    end

    --= (iFactoryCategoryOverride or AiBotUnitInfo.refCategoryLandFactory)
    if iCategoryToBuild == AiBotUnitInfo.refCategoryLandFactory then
        local iCurLandFacs = aiBrain:GetCurrentUnits(iCategoryToBuild)
        -- ACU factory actions bypass the normal engineer action assignment checks.
        -- In boom mode keep the first land factory, but do not let the ACU add another one.
        if AiBotOverseer.IsTeamBoomMode(aiBrain.AiBotTeam) and iCurLandFacs >= 1 then
            if not(aiBrain.AiBotBoomLoggedACULandFactoryBlock) then
                LOG('AiBot boom: blocked additional ACU land factory for army '..tostring(aiBrain.ArmyIndex or aiBrain:GetArmyIndex()))
                aiBrain.AiBotBoomLoggedACULandFactoryBlock = true
            end
            AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
            return
        end
        if iCurLandFacs >= 2 then
            iMaxAreaToSearch = 20
        elseif iCurLandFacs == 0 then
            iMaxAreaToSearch = oACU:GetBlueprint().Economy.MaxBuildDistance + AiBotUnitInfo.GetBuildingSize('ueb0101') * 0.5 + 1 --are ok with moving a very small distance to start building if it means we get adjacency
        end
    end
    --Campaign where large reclaim around ACU - increase search distance
    if AiBotMap.bIsCampaignMap and tLZData[AiBotMap.subrefTotalSignificantMassReclaim] >= 500 then
        local rNearbyRect = AiBotUtilities.GetRectAroundLocation(oACU:GetPosition(), 15)
        if AiBotMap.GetReclaimInRectangle(3, rNearbyRect) >= 200 then
            iMaxAreaToSearch = iMaxAreaToSearch + 15
            if aiBrain:GetCurrentUnits(AiBotUnitInfo.refCategoryFactory) >= 4 then iMaxAreaToSearch = iMaxAreaToSearch + 10 end
        end
    end
    local iSearchSegments = 20
    if iPlateauOrZero == 0 then
        iSearchSegments = 50
        if AiBotMap.bIsCampaignMap then
            iSearchSegments = iSearchSegments * 5
            if iEngineerActionOverride == AiBotEngineer.refActionBuildNavalFactory and aiBrain:GetCurrentUnits(AiBotUnitInfo.refCategoryNavalFactory) == 0 then
                iSearchSegments = iSearchSegments * 2
            end
        end --Issue on Aeon mission 1 where ACU doesnt build because it hasnt searched through enough of the segments
    end
    --Start of game - first factory - massively increase search segments
    if AiBotConditions.GetLifetimeBuildCount(aiBrain, AiBotUnitInfo.refCategoryFactory) == 0 then
        local iSegmentRef
        if iPlateauOrZero == 0 then
            iSegmentRef = AiBotMap.subrefWZSegments
        else
            iSegmentRef = AiBotMap.subrefLZSegments
        end
        local iTotalSegments = table.getn(tLZData[iSegmentRef])
        if (GetGameTimeSeconds() <= 10 or (tLZData[AiBotMap.subrefiCumulativeSegmentsConsideredForBuilding] or 0) < iTotalSegments * 0.75) then

            local iSegmentStart = (tLZData[AiBotMap.subrefiLastSegmentEntryConsideredForBuilding] or 0)
            if iSegmentStart < iTotalSegments * 0.75 then
                iSearchSegments = math.max(iSearchSegments, iTotalSegments * 0.75 - iSegmentStart)
            end
        end
    end
    iSearchSegments = math.floor(iSearchSegments)
    if AiBotOverseer.refiRoughTotalUnitsInGame <= 500 then iSearchSegments = iSearchSegments * 2 end

    if bDebugMessages == true then LOG(sFunctionRef..': Will try and search for '..iSearchSegments..' in iPlateauOrZero='..iPlateauOrZero..'; iLandOrWaterZone='..iLandOrWaterZone..' so ACU is picking from best location for factory, iMaxAreaToSearch='..iMaxAreaToSearch) end
    AiBotEngineer.SearchForBuildableLocationsForLandOrWaterZone(aiBrain, iPlateauOrZero, iLandOrWaterZone, iSearchSegments)
    ACUBuildUnit(aiBrain, oACU, iCategoryToBuild, iMaxAreaToSearch, iMaxAreaToSearch * 2, AiBotEngineer.tiActionAdjacentCategory[(iEngineerActionOverride or AiBotEngineer.refActionBuildLandFactory)], AiBotUnitInfo.refCategoryEngineer)

    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
end

function ACUActionAssistHydro(aiBrain, oACU, tLZOrWZData, tLZOrWZTeamData, oOptionalUnderConstructionHydro)
    --If have hydro under construction then assist the hydro if it's within build range; if not under construciton or out of build range then move towards it
    local sFunctionRef = 'ACUActionAssistHydro'
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)

    --Redundancy - make sure we have hydros in this LZ:
    local iPlateau, iLandZone = AiBotMap.GetPlateauAndLandZoneReferenceFromPosition(oACU:GetPosition(), true, oACU)
    if bDebugMessages == true then LOG(sFunctionRef..': Do we have hydro loations in iPlateau '..iPlateau..'; iLZ='..iLandZone..': Table empty='..tostring(AiBotUtilities.IsTableEmpty(tLZOrWZData[AiBotMap.subrefHydroLocations]))) end
    if AiBotUtilities.IsTableEmpty(tLZOrWZData[AiBotMap.subrefHydroLocations]) == false or oOptionalUnderConstructionHydro then
        local tNearestHydro
        local iNearestHydro = 10000
        local iCurDist
        local iBuildRange = oACU:GetBlueprint().Economy.MaxBuildDistance
        local iMinRangeToAssist = iBuildRange + 10
        local oNearestUnderConstructionHydro
        local iCompletedHydroCount = 0
        if not(oOptionalUnderConstructionHydro) or oOptionalUnderConstructionHydro:GetFractionComplete() == 1 then
            if AiBotUtilities.IsTableEmpty(tLZOrWZData[AiBotMap.subrefHydroUnbuiltLocations]) == false then
                for iHydro, tHydro in tLZOrWZData[AiBotMap.subrefHydroLocations] do
                    iCurDist = AiBotUtilities.GetDistanceBetweenPositions(tHydro, oACU:GetPosition())
                    if iCurDist < iNearestHydro then iNearestHydro = iCurDist tNearestHydro = tHydro end
                end
            end
            local tNearbyHydro = EntityCategoryFilterDown(AiBotUnitInfo.refCategoryHydro, tLZOrWZTeamData[AiBotMap.subreftoLZOrWZAlliedUnits])
            if bDebugMessages == true then LOG(sFunctionRef..': Is table of nearby hydro empty based on subreftoLZOrWZAlliedUnits='..tostring(AiBotUtilities.IsTableEmpty(tNearbyHydro))) end
            if AiBotUtilities.IsTableEmpty(tNearbyHydro) == false then
                for iHydro, oHydro in tNearbyHydro do
                    if bDebugMessages == true then LOG(sFunctionRef..': considering oHydro='..(oHydro.UnitId or 'nil')..(AiBotUnitInfo.GetUnitLifetimeCount(oHydro) or 'nil')..'; Is unit valid='..tostring(AiBotUnitInfo.IsUnitValid(oHydro))) end
                    if AiBotUnitInfo.IsUnitValid(oHydro) then
                        if oHydro:GetFractionComplete() < 1 then
                            iCurDist = AiBotUtilities.GetDistanceBetweenPositions(oHydro:GetPosition(), oACU:GetPosition())
                            if bDebugMessages == true then LOG(sFunctionRef..': iCurDist='..iCurDist..'; iNearestHydro='..iNearestHydro) end
                            --2 competing scenarios to avoid, 1 - helping a teammate's hydro that starts construction just before our hydro; 2 - having 2 hydros in our base and not helping the first one because the second is slightly closer (e.g. xander adaptive)
                            if iCurDist <= iNearestHydro or (not(oNearestUnderConstructionHydro) and (oHydro:GetAIBrain() == oACU:GetAIBrain() or iCurDist - 10 <= iNearestHydro)) then
                                iNearestHydro = iCurDist
                                tNearestHydro = oHydro:GetPosition()
                                oNearestUnderConstructionHydro = oHydro
                                if bDebugMessages == true then LOG(sFunctionRef..': Recording as the nearest hydro so far') end
                            end
                        else
                            iCompletedHydroCount = iCompletedHydroCount + 1
                        end
                    end
                end
            end
        else
            tNearestHydro = oOptionalUnderConstructionHydro:GetPosition()
            iNearestHydro = AiBotUtilities.GetDistanceBetweenPositions(oOptionalUnderConstructionHydro:GetPosition(), oACU:GetPosition())

        end
        --If we are in range of a hydro then assist it (or wait until construction is started)
        if bDebugMessages == true then LOG(sFunctionRef..': Checking if have hydro near enough to consider mvoing to and assisting, iNearestHydro='..iNearestHydro..'; iMinRangeToAssist='..iMinRangeToAssist) end
        if iNearestHydro < iMinRangeToAssist then

            local oUnderConstructionHydro = oOptionalUnderConstructionHydro or oNearestUnderConstructionHydro
            if not(oUnderConstructionHydro) then
                local tUnderConstructionHydro = aiBrain:GetUnitsAroundPoint(AiBotUnitInfo.refCategoryHydro, tNearestHydro, 5, 'Ally')
                if bDebugMessages == true then LOG(sFunctionRef..': Is table of hydros around nearest hydro point empty='..tostring(AiBotUtilities.IsTableEmpty(tUnderConstructionHydro))) end
                if AiBotUtilities.IsTableEmpty(tUnderConstructionHydro) == false then
                    for iHydro, oHydro in tUnderConstructionHydro do
                        if oHydro:GetFractionComplete() < 1 then
                            oUnderConstructionHydro = oHydro
                            break
                        end
                    end
                end
            end
            if bDebugMessages == true then LOG(sFunctionRef..': oUnderConstructionHydro='..(oUnderConstructionHydro.UnitId or 'nil')..(AiBotUnitInfo.GetUnitLifetimeCount(oUnderConstructionHydro) or 'nil')) end
            if oUnderConstructionHydro and oUnderConstructionHydro:GetFractionComplete() < 1 then
                AiBotOrders.IssueTrackedRepair(oACU, oUnderConstructionHydro, false, 'RH')
            elseif not(oUnderConstructionHydro) then
                oACU['AiBotBOHydroWait'] = ( oACU['AiBotBOHydroWait'] or 0) + 1
                if  oACU['AiBotBOHydroWait'] >= 20 then
                    ACUActionBuildPower(aiBrain, oACU)
                else
                    --Stay where we are as maybe we are waiting for an engi to start construction
                    AiBotOrders.IssueTrackedMove(oACU, oACU:GetPosition(), 3, false, 'W4C')
                end
            end
        elseif tNearestHydro and (iCompletedHydroCount == 0 or table.getn(tLZOrWZData[AiBotMap.subrefHydroLocations]) > iCompletedHydroCount) then
            --Move to be near hydro
            local tLocationNearHydro = AiBotEngineer.GetLocationToMoveForConstruction(oACU, tNearestHydro, 'ueb1102', -0.5, false)
            if tLocationNearHydro then
                AiBotOrders.IssueTrackedMove(oACU, tLocationNearHydro, 0.5, false, 'M2NH')
            else
                AiBotOrders.IssueTrackedMove(oACU, tNearestHydro, 0.5, false, 'M2H')
            end
        else
            if bDebugMessages == true then LOG(sFunctionRef..': No nearby hydro for ACU - e.g. might hapepn if called this as a redundancy action') end
        end
    else
        AiBotUtilities.ErrorHandler('Trying to buidl hydro when none nearby')
    end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
end

function ACUActionBuildAA(aiBrain, oACU, iPlateauOrZero, iLandOrWaterZone, tLZData, tLZTeamData)
    local sFunctionRef = 'ACUActionBuildAA'
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)

    local iMaxAreaToSearch = 35
    local iCategoryToBuild = AiBotUnitInfo.refCategoryGroundAA
    if bDebugMessages == true then LOG(sFunctionRef..': Start of code for aiBrain '..aiBrain.Nickname..' at time '..GetGameTimeSeconds()) end
    if AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.subreftoLZOrWZAlliedUnits]) and GetGameTimeSeconds() >= 60 and iPlateauOrZero > 0 and tLZTeamData[AiBotMap.subrefLZbCoreBase] then AiBotUtilities.ErrorHandler('Empty allied units table, iPlateauOrZero='..(iPlateauOrZero or 'nil')..'; iLandOrWaterZone='..(iLandOrWaterZone or 'nil')..'; Is LZTeamData empty='..tostring(AiBotUtilities.IsTableEmpty(tLZTeamData))) end

    local iSearchSegments = 10
    if iPlateauOrZero == 0 then
        iSearchSegments = 20
    end

    if bDebugMessages == true then LOG(sFunctionRef..': Will try and search for '..iSearchSegments..' in iPlateauOrZero='..iPlateauOrZero..'; iLandOrWaterZone='..iLandOrWaterZone..' so ACU is picking from best location for factory') end
    AiBotEngineer.SearchForBuildableLocationsForLandOrWaterZone(aiBrain, iPlateauOrZero, iLandOrWaterZone, iSearchSegments)
    ACUBuildUnit(aiBrain, oACU, iCategoryToBuild, iMaxAreaToSearch, iMaxAreaToSearch * 2)

    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
end

function ACUActionBuildPower(aiBrain, oACU)
    local sFunctionRef = 'ACUActionBuildPower'
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)

    local iCategoryToBuild = AiBotUnitInfo.refCategoryPower
    local iMaxAreaToSearch = 16
    local iOptionalAdjacencyCategory
    if aiBrain:GetCurrentUnits(AiBotUnitInfo.refCategoryAirFactory) > 0 then iOptionalAdjacencyCategory = AiBotUnitInfo.refCategoryAirFactory
    elseif aiBrain[AiBotEconomy.refiGrossEnergyBaseIncome] <= 11 then iOptionalAdjacencyCategory = AiBotUnitInfo.refCategoryLandFactory
    end
    if bDebugMessages == true then LOG(sFunctionRef..': About to tell ACU to build power; is optional adjacency category nil='..tostring(iOptionalAdjacencyCategory == nil)) end
    ACUBuildUnit(aiBrain, oACU, iCategoryToBuild, iMaxAreaToSearch, iMaxAreaToSearch * 3, iOptionalAdjacencyCategory, nil)

    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
end

function ACUActionBuildMex(aiBrain, oACU, iAreaToSearchOverride)
    local sFunctionRef = 'ACUActionBuildMex'
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)
    local iMaxAreaToSearch = iAreaToSearchOverride
    --Increase search range if still doing initial build order, as this suggests we have mexes in our initial land zone that we havent built on yet
    if not(iMaxAreaToSearch) then
        if oACU[refbDoingInitialBuildOrder] then
            if aiBrain[AiBotEconomy.refiGrossEnergyBaseIncome] >= 12 then iMaxAreaToSearch = 50
            elseif aiBrain[AiBotEconomy.refiGrossMassBaseIncome] < 6 then iMaxAreaToSearch = 30
            end
        else
            iMaxAreaToSearch = 20
        end
    end

    if bDebugMessages == true then LOG(sFunctionRef..': About to tell ACU to build a mex, iMaxAreaToSearch='..iMaxAreaToSearch..'; iAreaToSearchOverride='..(iAreaToSearchOverride or 'nil')) end
    local iMexCategoryWanted
    if aiBrain:GetEconomyStoredRatio('ENERGY') >= 0.99 and aiBrain:GetEconomyStored('MASS') >= 4000 and aiBrain[AiBotEconomy.refiGrossEnergyBaseIncome] >= 300 then iMexCategoryWanted = AiBotUnitInfo.refCategoryMex
    else iMexCategoryWanted = AiBotUnitInfo.refCategoryMex * categories.TECH1
    end
    ACUBuildUnit(aiBrain, oACU, iMexCategoryWanted, iMaxAreaToSearch, iMaxAreaToSearch * 2, nil, nil)

    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
end

function MoveACUToNearbyWaterForFactory(aiBrain, oACU, tLZOrWZData)
    local sFunctionRef = 'MoveACUToNearbyWaterForFactory'
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)

    local iTeam = aiBrain.AiBotTeam

    --Get the first WZ that has a naval fac build location
    local iClosestWZRefWithBuild
    local iClosestWZRefWithoutBuild
    local iClosestWZWithBuildLocation = 100000
    local iClosestWZWithoutBuildLocation = 100000
    for iEntry, tSubtable in tLZOrWZData[AiBotMap.subrefAdjacentWaterZones] do
        local iAdjWZ = tSubtable[AiBotMap.subrefAWZRef]
        local tAdjWZData = AiBotMap.tPondDetails[AiBotMap.tiPondByWaterZone[iAdjWZ]][AiBotMap.subrefPondWaterZones][iAdjWZ]
        if bDebugMessages == true then LOG(sFunctionRef..': Considering if we want to move to adjacent water zone '..iAdjWZ..'; Midpoint='..repru(tAdjWZData[AiBotMap.subrefMidpoint])..'; Straight line dist to ACU='..AiBotUtilities.GetDistanceBetweenPositions(tAdjWZData[AiBotMap.subrefMidpoint], oACU:GetPosition())..'; AWZ dist='..tSubtable[AiBotMap.subrefAWZDistance]..'; Is in playable area='..tostring(AiBotConditions.IsLocationInPlayableArea(tAdjWZData[AiBotMap.subrefMidpoint]))) end
        if AiBotConditions.IsLocationInPlayableArea(tAdjWZData[AiBotMap.subrefMidpoint]) then
            local tAdjWZTeamData = tAdjWZData[AiBotMap.subrefWZTeamData][iTeam]
            if bDebugMessages == true then LOG(sFunctionRef..': Does WZ contain naval build location='..tostring(tAdjWZTeamData[AiBotMap.subrefWZbContainsNavalBuildLocation])) end
            if tAdjWZTeamData[AiBotMap.subrefWZbContainsNavalBuildLocation] then
                if tSubtable[AiBotMap.subrefAWZDistance] < iClosestWZWithBuildLocation then
                    iClosestWZWithBuildLocation = tSubtable[AiBotMap.subrefAWZDistance]
                    iClosestWZRefWithBuild = iAdjWZ
                end
            else
                if tSubtable[AiBotMap.subrefAWZDistance] < iClosestWZWithoutBuildLocation then
                    iClosestWZWithoutBuildLocation = tSubtable[AiBotMap.subrefAWZDistance]
                    iClosestWZRefWithoutBuild = iAdjWZ
                end
            end
        end
    end
    local iOtherWZWanted = (iClosestWZRefWithBuild or iClosestWZRefWithoutBuild)
    if not(iOtherWZWanted) and AiBotUtilities.IsTableEmpty(tLZOrWZData[AiBotMap.subrefOtherLandAndWaterZonesByDistance]) == false then
        --Search all water zones
        for iEntry, tSubtable in tLZOrWZData[AiBotMap.subrefOtherLandAndWaterZonesByDistance] do
            if tSubtable[AiBotMap.subrefbIsWaterZone] then
                local iAdjPond = tSubtable[AiBotMap.subrefiPlateauOrPond]
                local iOtherWZ = tSubtable[AiBotMap.subrefiLandOrWaterZoneRef]
                local tOtherWZData = AiBotMap.tPondDetails[iAdjPond][AiBotMap.subrefPondWaterZones][iOtherWZ]
                if bDebugMessages == true then LOG(sFunctionRef..': considering iOtherWZ='..iOtherWZ..'; Midpoint='..repru(tOtherWZData[AiBotMap.subrefMidpoint])..'; Is in playable area='..tostring(AiBotConditions.IsLocationInPlayableArea(tOtherWZData[AiBotMap.subrefMidpoint]))) end
                if AiBotConditions.IsLocationInPlayableArea(tOtherWZData[AiBotMap.subrefMidpoint]) then
                    iOtherWZWanted = iOtherWZ
                    break
                end
            end
        end
    end
    if bDebugMessages == true then LOG(sFunctionRef..': Finished checking for adjacent water zone to move to, iOtherWZWanted='..(iOtherWZWanted or 'nil')..'; ACU pos='..repru(oACU:GetPosition())) end
    if iOtherWZWanted then
        local tAdjWZData = AiBotMap.tPondDetails[AiBotMap.tiPondByWaterZone[iOtherWZWanted]][AiBotMap.subrefPondWaterZones][iOtherWZWanted]
        AiBotOrders.IssueTrackedMove(oACU, tAdjWZData[AiBotMap.subrefMidpoint], 2, false, 'MoveToWZ'..iOtherWZWanted, false)
    else
        local tPotentialDestination = AiBotMap.GetNearestWaterToBuildNavalFactoryInPlayableArea(aiBrain, oACU:GetPosition(), 8, nil, nil, true)
        if bDebugMessages == true then LOG(sFunctionRef..': Potential water destination to move to='..repru(tPotentialDestination)) end
        if tPotentialDestination then
            AiBotOrders.IssueTrackedMove(oACU, tPotentialDestination, 2, false, 'MoveToNBL', false)
        end
    end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
end

function GetLowMexMapEarlyACUOrder(aiBrain, oACU, iPlateauOrZero, iLZOrWZ, tLZOrWZData, tLZOrWZTeamData)
    local sFunctionRef = 'GetLowMexMapEarlyACUOrder'
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)

    if bDebugMessages == true then LOG(sFunctionRef..': Start of code, aiBrain[AiBotEconomy.refiGrossEnergyBaseIncome]='..aiBrain[AiBotEconomy.refiGrossEnergyBaseIncome]..'; aiBrain[AiBotEconomy.refiGrossMassBaseIncome]='..aiBrain[AiBotEconomy.refiGrossMassBaseIncome]) end

    --more specific initial build order
    local iMexInLandZone = 0
    local iResourceMod = aiBrain[AiBotEconomy.refiBrainResourceMultiplier]
    if AiBotUtilities.IsTableEmpty(tLZOrWZData[AiBotMap.subrefLZOrWZMexLocations]) == false then iMexInLandZone = table.getn(tLZOrWZData[AiBotMap.subrefLZOrWZMexLocations]) end
    if iMexInLandZone > 0 and aiBrain[AiBotEconomy.refiGrossMassBaseIncome] < math.min(4, iMexInLandZone) * 0.2 * iResourceMod and AiBotUtilities.IsTableEmpty(tLZOrWZData[AiBotMap.subrefMexUnbuiltLocations]) == false and (not(AiBotOverseer.bNoRushActive) or not(AiBotConditions.NoRushPreventingHydroOrMex(tLZOrWZData, true))) then
        ACUActionBuildMex(aiBrain, oACU)
        --want 40 energy for every 2 mass
    elseif aiBrain[AiBotEconomy.refiGrossEnergyBaseIncome] < math.max(math.min(8, iMexInLandZone * 4 + 4), math.min(25, aiBrain[AiBotEconomy.refiGrossMassBaseIncome] * 14)) then
        local bHydroBuildOrder = false
        local tClosestHydroToACU
        local iClosestDistToACU = 100000
        local iCurHydroDist
        local bHaveUnderConstructionFirstHydro = false
        local oOptionalUnderConstructionHydro --used for redundancy
        if AiBotUtilities.IsTableEmpty(tLZOrWZData[AiBotMap.subrefHydroLocations]) == false then
            for iEntry, tHydro in tLZOrWZData[AiBotMap.subrefHydroLocations] do
                if bDebugMessages == true then LOG(sFunctionRef..': Travel dist to hydro='..AiBotUtilities.GetTravelDistanceBetweenPositions(AiBotMap.GetPlayerStartPosition(aiBrain), tHydro, AiBotMap.refPathingTypeLand)) end
                if AiBotUtilities.GetTravelDistanceBetweenPositions(AiBotMap.GetPlayerStartPosition(aiBrain), tHydro, AiBotMap.refPathingTypeLand) <= 125 then --further than normal since we are in low mass scenario
                    bHydroBuildOrder = true
                    iCurHydroDist = AiBotUtilities.GetTravelDistanceBetweenPositions(tHydro, oACU:GetPosition(), AiBotMap.refPathingTypeLand)
                    if iCurHydroDist < iClosestDistToACU then
                        iClosestDistToACU = iCurHydroDist
                        tClosestHydroToACU = {tHydro[1], tHydro[2], tHydro[3]}
                    end
                end
            end
        end
        if bHydroBuildOrder and aiBrain[AiBotEconomy.refiGrossEnergyBaseIncome] <= 10 and aiBrain:GetCurrentUnits(AiBotUnitInfo.refCategoryFactory + AiBotUnitInfo.refCategoryEngineer) > 0 then --have a hydro in the zone but havent built it yet, so want to build hydro
            ACUActionAssistHydro(aiBrain, oACU, tLZOrWZData, tLZOrWZTeamData, oOptionalUnderConstructionHydro)
        else
            ACUActionBuildPower(aiBrain, oACU)
        end
    else
        --Build factory if dont have one and have lots of mass stored, or there are other mexes we want to get
        local iCurFactories = aiBrain:GetCurrentUnits(AiBotUnitInfo.refCategoryFactory)
        if bDebugMessages == true then LOG(sFunctionRef..': iCurFactories='..iCurFactories..'; GetMexesNotNearPlayerStartingZone='..AiBotConditions.GetMexesNotNearPlayerStartingZone()) end
        if iCurFactories == 0 and (aiBrain:GetEconomyStoredRatio('MASS') >= 0.95 or tLZOrWZTeamData[AiBotMap.subrefMexCountByTech][2] + tLZOrWZTeamData[AiBotMap.subrefMexCountByTech][3] > 0 or iMexInLandZone == 0) then
            ACUActionBuildFactory(aiBrain, oACU, iPlateauOrZero, iLZOrWZ, tLZOrWZData, tLZOrWZTeamData, AiBotUnitInfo.refCategoryLandFactory)
        elseif iCurFactories == 0 and AiBotConditions.GetMexesNotNearPlayerStartingZone() > 0 then
            ACUActionBuildFactory(aiBrain, oACU, iPlateauOrZero, iLZOrWZ, tLZOrWZData, tLZOrWZTeamData, AiBotUnitInfo.refCategoryLandFactory)
        else
            --Attack (further away) nearby units
            if not(AttackNearestEnemyWithACU(iPlateauOrZero, iLZOrWZ, tLZOrWZData, tLZOrWZTeamData, oACU, 100)) then
                --Get any reclaim, if any
                if not(ConsiderNearbyReclaimForACUOrEngineer(iPlateauOrZero, iLZOrWZ, tLZOrWZData, tLZOrWZTeamData, oACU, false, 1)) then

                    --Assist upgrade if we have any
                    local oUnitToAssist
                    local iHighestFractionComplete = -1
                    if AiBotUtilities.IsTableEmpty(tLZOrWZTeamData[AiBotMap.subreftoActiveUpgrades]) == false then
                        for iUpgrading, oUpgrading in  tLZOrWZTeamData[AiBotMap.subreftoActiveUpgrades] do
                            if AiBotUnitInfo.IsUnitValid(oUpgrading) then
                                if oUpgrading:GetWorkProgress() < 1 and oUpgrading:GetWorkProgress() > iHighestFractionComplete then
                                    iHighestFractionComplete = oUpgrading:GetWorkProgress()
                                    oUnitToAssist = oUpgrading
                                end
                            end
                        end
                    end
                    if oUnitToAssist then
                        if oUnitToAssist:GetFractionComplete() < 1 then
                            AiBotOrders.IssueTrackedRepair(oACU, oUnitToAssist, false, 'LMTR', false)
                            if bDebugMessages == true then LOG(sFunctionRef..': Just given repair order to oUnitToAssist') end
                        else
                            AiBotOrders.IssueTrackedGuard(oACU, oUnitToAssist, false, 'LMGB', false)
                            if bDebugMessages == true then LOG(sFunctionRef..': Just given guard order to oUnitToAssist') end
                        end
                    else
                        --Check for capture targets
                        if AiBotUtilities.IsTableEmpty(tLZOrWZData[AiBotMap.subreftoUnitsToCapture]) == false then
                            local t1ToT2PowerToCapture = EntityCategoryFilterDown(AiBotUnitInfo.refCategoryPower - categories.TECH3 - categories.EXPERIMENTAL, tLZOrWZData[AiBotMap.subreftoUnitsToCapture])
                            local tT1PowerToCapture
                            if AiBotUtilities.IsTableEmpty(t1ToT2PowerToCapture) == false then
                                tT1PowerToCapture = EntityCategoryFilterDown(categories.TECH1,t1ToT2PowerToCapture)
                            end
                            --Get more power to support capturing if we have mass
                            if aiBrain:GetEconomyStored('MASS') >= 75 and aiBrain[AiBotEconomy.refiGrossEnergyBaseIncome] <= 14 then
                                if AiBotUtilities.IsTableEmpty(tT1PowerToCapture) == false then
                                    local oClosestCaptureTarget = AiBotUtilities.GetNearestUnit(tT1PowerToCapture, oACU:GetPosition(), true, AiBotMap.refPathingTypeAmphibious)
                                    if bDebugMessages == true then LOG(sFunctionRef..': Considering if we have a capture target, oClosestCaptureTarget='..(oClosestCaptureTarget.UnitId or 'nil')..(AiBotUnitInfo.GetUnitLifetimeCount(oClosestCaptureTarget))) end
                                    if AiBotUnitInfo.IsUnitValid(oClosestCaptureTarget) then
                                        AiBotOrders.IssueTrackedCapture(oACU, oClosestCaptureTarget, false, 'ACUCap', false)
                                    else
                                        ACUActionBuildPower(aiBrain, oACU) --redundancy
                                    end
                                else
                                    local bHydroBuildOrder = false
                                    local tClosestHydroToACU
                                    local iClosestDistToACU = 100000
                                    local iCurHydroDist
                                    local oOptionalUnderConstructionHydro --used for redundancy
                                    if AiBotUtilities.IsTableEmpty(tLZOrWZData[AiBotMap.subrefHydroLocations]) == false then
                                        for iEntry, tHydro in tLZOrWZData[AiBotMap.subrefHydroLocations] do
                                            if bDebugMessages == true then LOG(sFunctionRef..': Travel dist to hydro='..AiBotUtilities.GetTravelDistanceBetweenPositions(AiBotMap.GetPlayerStartPosition(aiBrain), tHydro, AiBotMap.refPathingTypeLand)) end
                                            if AiBotUtilities.GetTravelDistanceBetweenPositions(AiBotMap.GetPlayerStartPosition(aiBrain), tHydro, AiBotMap.refPathingTypeLand) <= 125 then --further than normal since we are in low mass scenario
                                                bHydroBuildOrder = true
                                                iCurHydroDist = AiBotUtilities.GetTravelDistanceBetweenPositions(tHydro, oACU:GetPosition(), AiBotMap.refPathingTypeLand)
                                                if iCurHydroDist < iClosestDistToACU then
                                                    iClosestDistToACU = iCurHydroDist
                                                    tClosestHydroToACU = {tHydro[1], tHydro[2], tHydro[3]}
                                                end
                                            end
                                        end
                                    end
                                    if bDebugMessages == true then LOG(sFunctionRef..': Considering if we want to build hydro instead of pgen, before doing more capturing, will check for under construction hydro if we dont have a build order already, bHydroBuildOrder='..tostring(bHydroBuildOrder)..'; Gross E='..aiBrain[AiBotEconomy.refiGrossEnergyBaseIncome]..'; Is table of hydro points on map empty='..tostring(AiBotUtilities.IsTableEmpty(AiBotMap.tHydroPoints))) end
                                    if not(bHydroBuildOrder) and aiBrain[AiBotEconomy.refiGrossEnergyBaseIncome] <= 20 and AiBotUtilities.IsTableEmpty(AiBotMap.tHydroPoints) == false then
                                        --Check for nearby hydro under construction by us (in case zones have meant hydro is a bit further away)
                                        local tNearbyHydro = aiBrain:GetUnitsAroundPoint(AiBotUnitInfo.refCategoryHydro, oACU:GetPosition(), 60, 'Ally')
                                        if bDebugMessages == true then LOG(sFunctionRef..': Is tNearbyHydro (hydro units) empty='..tostring(AiBotUtilities.IsTableEmpty(tNearbyHydro))) end
                                        if AiBotUtilities.IsTableEmpty(tNearbyHydro) == false then
                                            local iClosestHydro = 100
                                            local iCurDist
                                            for iHydro, oHydro in tNearbyHydro do
                                                if oHydro:GetFractionComplete() < 1 and oHydro:GetAIBrain() == aiBrain then
                                                    iCurDist = AiBotUtilities.GetDistanceBetweenPositions(oHydro:GetPosition(), oACU:GetPosition())
                                                    if iCurDist < iClosestHydro then
                                                        iClosestHydro = iCurDist
                                                        oOptionalUnderConstructionHydro = oHydro
                                                        bHydroBuildOrder = true
                                                        if bDebugMessages == true then LOG(sFunctionRef..': Recording oOptionalUnderConstructionHydro as oHydro='..oHydro.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oHydro)) end
                                                    end
                                                end
                                            end
                                        end
                                    end
                                    if bHydroBuildOrder and (aiBrain[AiBotEconomy.refiGrossEnergyBaseIncome] <= 10 or oOptionalUnderConstructionHydro) and aiBrain:GetCurrentUnits(AiBotUnitInfo.refCategoryFactory + AiBotUnitInfo.refCategoryEngineer) > 0 then --have a hydro in the zone but havent built it yet, so want to build hydro
                                        ACUActionAssistHydro(aiBrain, oACU, tLZOrWZData, tLZOrWZTeamData, oOptionalUnderConstructionHydro)
                                    else
                                        ACUActionBuildPower(aiBrain, oACU)
                                    end
                                end
                            else
                                --If have low power prioritise power
                                local oClosestCaptureTarget
                                if AiBotUtilities.IsTableEmpty(t1ToT2PowerToCapture) == false and AiBotConditions.HaveLowPower(aiBrain.AiBotTeam) then
                                    if AiBotUtilities.IsTableEmpty(tT1PowerToCapture) == false then
                                        oClosestCaptureTarget = AiBotUtilities.GetNearestUnit(tT1PowerToCapture, oACU:GetPosition(), true, AiBotMap.refPathingTypeAmphibious)
                                        if bDebugMessages == true then LOG(sFunctionRef..': will get closest t1 pgen to capture') end
                                    else
                                        oClosestCaptureTarget = AiBotUtilities.GetNearestUnit(t1ToT2PowerToCapture, oACU:GetPosition(), true, AiBotMap.refPathingTypeAmphibious)
                                        if bDebugMessages == true then LOG(sFunctionRef..': Will get closest T1-T2 pgen to capture') end
                                    end
                                else
                                    local tT1OrT2MassGeneration = EntityCategoryFilterDown(AiBotUnitInfo.refCategoryMex + AiBotUnitInfo.refCategoryMassFab - categories.TECH3 - categories.EXPERIMENTAL,tLZOrWZData[AiBotMap.subreftoUnitsToCapture])
                                    if AiBotUtilities.IsTableEmpty(  tT1OrT2MassGeneration) == false and AiBotConditions.HaveLowMass(aiBrain) then
                                        oClosestCaptureTarget = AiBotUtilities.GetNearestUnit(tT1OrT2MassGeneration, oACU:GetPosition(), true, AiBotMap.refPathingTypeAmphibious)
                                        if bDebugMessages == true then LOG(sFunctionRef..': will get closest mass fab or mex to cpature') end
                                    else
                                        oClosestCaptureTarget = AiBotUtilities.GetNearestUnit(tLZOrWZData[AiBotMap.subreftoUnitsToCapture], oACU:GetPosition(), true, AiBotMap.refPathingTypeAmphibious)
                                        if bDebugMessages == true then LOG(sFunctionRef..'; Will get closest unit to capture') end
                                    end
                                end
                                if bDebugMessages == true then LOG(sFunctionRef..': Considering if we have a capture target, oClosestCaptureTarget='..(oClosestCaptureTarget.UnitId or 'nil')..(AiBotUnitInfo.GetUnitLifetimeCount(oClosestCaptureTarget))) end
                                if AiBotUnitInfo.IsUnitValid(oClosestCaptureTarget) then
                                    AiBotOrders.IssueTrackedCapture(oACU, oClosestCaptureTarget, false, 'ACUCap', false)
                                end
                            end
                        end
                    end
                end
            end
        end

    end
        AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
end

function GetACUEarlyGameOrders(aiBrain, oACU)
    local sFunctionRef = 'GetACUEarlyGameOrders'
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)

    local iPlateauOrZero, iLZOrWZ = AiBotMap.GetClosestPlateauOrZeroAndZoneToPosition(oACU:GetPosition())



    local tLZOrWZData
    local tLZOrWZTeamData
    local iTeam = oACU:GetAIBrain().AiBotTeam
    local bDualGapAirHomeOnly = oACU:GetAIBrain().AiBotDualGapRole == 'top_air' or oACU:GetAIBrain().AiBotDualGapRole == 'bottom_air'
    local iResourceMod = aiBrain[AiBotEconomy.refiBrainResourceMultiplier]
    --if aiBrain.CheatEnabled then iResourceMod = AiBotTeam.tTeamData[aiBrain.AiBotTeam][AiBotTeam.refiHighestBrainResourceMultiplier] end
    if iPlateauOrZero == 0 then
        tLZOrWZData = AiBotMap.tPondDetails[AiBotMap.tiPondByWaterZone[iLZOrWZ]][AiBotMap.subrefPondWaterZones][iLZOrWZ]
        tLZOrWZTeamData = tLZOrWZData[AiBotMap.subrefWZTeamData][aiBrain.AiBotTeam]
    else
        tLZOrWZData = AiBotMap.tAllPlateaus[iPlateauOrZero][AiBotMap.subrefPlateauLandZones][iLZOrWZ]
        tLZOrWZTeamData = tLZOrWZData[AiBotMap.subrefLZTeamData][aiBrain.AiBotTeam]
    end

    -- Air/eco ACUs are economic build power, not mid-line units. If another
    -- generic ACU branch has walked one out of the core zone, send it back to
    -- its start base before considering combat or expansion orders.
    if bDualGapAirHomeOnly and not tLZOrWZTeamData[AiBotMap.subrefLZbCoreBase]
            and aiBrain.AiBotDualGapStartX and aiBrain.AiBotDualGapStartZ then
        local x = aiBrain.AiBotDualGapStartX
        local z = aiBrain.AiBotDualGapStartZ
        AiBotOrders.IssueTrackedMove(oACU, {x, GetSurfaceHeight(x, z), z}, 5, false, 'DGAirHome', true)
        AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
        return
    end

    if bDebugMessages == true then LOG(sFunctionRef..': Considering ACU for brain '..oACU:GetAIBrain().Nickname..'; Time='..GetGameTimeSeconds()..'; ACU state='..AiBotUnitInfo.GetUnitState(oACU)..'; iPlateauOrZero='..iPlateauOrZero..'; iLZOrWZ='..(iLZOrWZ or 'nil')..'; Hover label at position='..NavUtils.GetTerrainLabel(AiBotMap.refPathingTypeHover, oACU:GetPosition())..'; ACU position='..repru(oACU:GetPosition())) end


    --If have low cost mex upgrades then fork a thread to get all of these first
    if not(oACU[reftPreferredUpgrades]) then
        GetUpgradePathForACU(oACU)
    end
    if bDebugMessages == true and oACU[reftPreferredUpgrades][1] then LOG(sFunctionRef..': oACU[reftPreferredUpgrades][1]='..oACU[reftPreferredUpgrades][1]..'; Build cost mass='..(oACU:GetBlueprint().Enhancements[oACU[reftPreferredUpgrades][1]].BuildCostMass or 'nil')..'; Build time='..(oACU:GetBlueprint().Enhancements[oACU[reftPreferredUpgrades][1]].BuildTime or 'nil')..'; Has enhancement='..tostring(oACU:HasEnhancement(oACU[reftPreferredUpgrades][1]))) end
    local bQueuedEnhancement = false
    if oACU[reftPreferredUpgrades][1] and oACU:GetBlueprint().Enhancements[oACU[reftPreferredUpgrades][1]].BuildCostMass <= 10 and oACU:GetBlueprint().Enhancements[oACU[reftPreferredUpgrades][1]].BuildTime <= 10 and not(oACU:HasEnhancement(oACU[reftPreferredUpgrades][1])) then
        GetUpgradePathForACU(oACU) --Refresh to be safe
        for iEnhancement, sEnhancement in oACU[reftPreferredUpgrades] do
            if oACU:GetBlueprint().Enhancements[sEnhancement].BuildCostMass <= 10 and oACU:GetBlueprint().Enhancements[sEnhancement].BuildTime <= 10 and not(oACU:HasEnhancement(sEnhancement)) then
                if bDebugMessages == true then LOG(sFunctionRef..'; Queing up enhancement '..sEnhancement) end
                AiBotOrders.IssueTrackedEnhancement(oACU, sEnhancement, true, 'ACULCEn')
                bQueuedEnhancement = true
            else
                break
            end
        end
    end
    if not(bQueuedEnhancement) then

        --Nearby enemy units in other land zone if we already have a complete land factory
        local iSearchDistance = 40
        if AiBotMap.bIsCampaignMap then iSearchDistance = 36 end
        local bACUWantsToRun = DoesACUWantToRun(iPlateauOrZero, iLZOrWZ, tLZOrWZData, tLZOrWZTeamData, oACU)
        local bProceedWithLogic = true
        local iCurLandFacs = aiBrain:GetCurrentUnits(AiBotUnitInfo.refCategoryLandFactory)
        if iCurLandFacs >= 1 and iPlateauOrZero > 0 and (iPlateauOrZero == 0 or not(bACUWantsToRun) or AiBotUtilities.IsTableEmpty(tLZOrWZTeamData[AiBotMap.subrefTEnemyUnits]) == false) and AttackNearestEnemyWithACU(iPlateauOrZero, iLZOrWZ, tLZOrWZData, tLZOrWZTeamData, oACU, iSearchDistance) then
            if bDebugMessages == true then LOG(sFunctionRef..': ACU has enemies within 40 of it so will attack as we already have a factory complete') end
            bProceedWithLogic = false
            --Consider clearing early game flag
            if iCurLandFacs >= 2 and GetGameTimeSeconds() >= 240 / aiBrain[AiBotEconomy.refiBrainBuildRateMultiplier] and aiBrain[AiBotEconomy.refiGrossEnergyBaseIncome] >= 20 and aiBrain[AiBotEconomy.refiGrossMassBaseIncome] >= 1.4 and (oACU[refiUpgradeCount] > 0 or (aiBrain[AiBotEconomy.refiGrossEnergyBaseIncome] >= 24 and aiBrain:GetCurrentUnits(AiBotUnitInfo.refCategoryAirFactory) > 0) or bACUWantsToRun) then
                if bDebugMessages == true then LOG(sFunctionRef..': Will clear initial build order flag as are nearby enemies so not getting a chance to build everything but have several factories and decent eco') end
                oACU[refbDoingInitialBuildOrder] = false
            end
        elseif bACUWantsToRun and AiBotMap.bIsCampaignMap and iCurLandFacs >= 1 and tLZOrWZTeamData[AiBotMap.subrefbEnemiesInThisOrAdjacentLZ] then
            --Retreat from nearest enemy
            local bHaveRun = false
            local oNearestEnemy
            local iClosestDistUntilInRange = 10000
            local iCurDist
            function ConsiderNearestEnemyInZone(tCurLZTeamData)
                if AiBotUtilities.IsTableEmpty(tCurLZTeamData[AiBotMap.subrefTEnemyUnits]) == false then
                    for iUnit, oUnit in tCurLZTeamData[AiBotMap.subrefTEnemyUnits] do
                        if AiBotUnitInfo.IsUnitValid(oUnit) and oUnit:GetFractionComplete() == 1 and (oUnit[AiBotUnitInfo.refiCombatRange] or 0) > 0 then
                            iCurDist = AiBotUtilities.GetDistanceBetweenPositions(oUnit:GetPosition(), oACU:GetPosition()) - oUnit[AiBotUnitInfo.refiCombatRange]
                            if iCurDist < iClosestDistUntilInRange then
                                iClosestDistUntilInRange = iCurDist
                                oNearestEnemy = oUnit
                                if iClosestDistUntilInRange < 0 then break end
                            end
                        end
                    end
                end
            end
            ConsiderNearestEnemyInZone(tLZOrWZTeamData)
            if AiBotUtilities.IsTableEmpty(tLZOrWZData[AiBotMap.subrefLZAdjacentLandZones]) == false then
                for _, iAdjLZ in tLZOrWZData[AiBotMap.subrefLZAdjacentLandZones] do
                    local tAdjLZTeamData = AiBotMap.tAllPlateaus[iPlateauOrZero][AiBotMap.subrefPlateauLandZones][iAdjLZ][AiBotMap.subrefLZTeamData][iTeam]
                    ConsiderNearestEnemyInZone(tAdjLZTeamData)
                end
            end
            if bDebugMessages == true then LOG(sFunctionRef..'; Considering ignoring special micro, iClosestDistUntilInRange='..iClosestDistUntilInRange..'; oNearestEnemy='..(oNearestEnemy.UnitId or 'nil')..(AiBotUnitInfo.GetUnitLifetimeCount(oNearestEnemy) or 'nil')) end
            if iClosestDistUntilInRange <= 1 and oNearestEnemy then
                --We want to run
                local tRallyPoint = AiBotLand.GetNearestLandRallyPoint(tLZOrWZData, iTeam, iPlateauOrZero, iLZOrWZ, 2, true)
                if AiBotUtilities.IsTableEmpty(tRallyPoint) == false then
                    if bDebugMessages == true then LOG(sFunctionRef..': Angle to rally point tRallyPoint='..AiBotUtilities.GetAngleFromAToB(oACU:GetPosition(), tRallyPoint)..'; Angle to nearest enemy PD='..AiBotUtilities.GetAngleFromAToB(oACU:GetPosition(), oNearestEnemy:GetPosition())) end
                    if AiBotUtilities.GetAngleDifference(AiBotUtilities.GetAngleFromAToB(oACU:GetPosition(), tRallyPoint), AiBotUtilities.GetAngleFromAToB(oACU:GetPosition(), oNearestEnemy:GetPosition())) > 90 then
                        if bDebugMessages == true then LOG(sFunctionRef..': Will consider running to shield or rally point') end
                        if not(ConsiderRunningToNearestShield(oACU, tLZOrWZData, tLZOrWZTeamData, iTeam, iPlateauOrZero, iLZOrWZ)) then
                            if bDebugMessages == true then LOG(sFunctionRef..': Will override micro logic and retreat') end
                            AiBotOrders.IssueTrackedMove(oACU, tRallyPoint, 5, false, 'ACUIgnMRetr', true)
                            bHaveRun = true
                            bProceedWithLogic = false
                        end
                    end
                end
            end
            if not(bHaveRun) and AttackNearestEnemyWithACU(iPlateauOrZero, iLZOrWZ, tLZOrWZData, tLZOrWZTeamData, oACU, iSearchDistance) then
                bProceedWithLogic = false
            end
        end
        --Mod that reduces upgrade costs to negligible amount
        if bProceedWithLogic and GetGameTimeSeconds() <= 15 and (oACU:GetBlueprint().Enhancements.ResourceAllocation.BuildCostMass or 10000) <= 100 and (oACU:GetBlueprint().Enhancements.ResourceAllocation.BuildTime or 10000) <= 100 then
            local sUpgradeToGet, bIgnoreOtherUpgradeConditions = GetACUUpgradeWanted(oACU, nil, tLZOrWZData, tLZOrWZTeamData, iPlateauOrZero, not(AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefbTeamIsStallingEnergy]))
            if bDebugMessages == true then LOG(sFunctionRef..': sUpgradeToGet='..(sUpgradeToGet or 'nil')) end
            if not(sUpgradeToGet) and not(oACU:HasEnhancement('ResourceAllocation')) then sUpgradeToGet = 'ResourceAllocation' end --e.g. if in eco slot then we ignore upgrades initially
            if sUpgradeToGet == 'ResourceAllocation' or sUpgradeToGet == 'AdvancedEngineering' or sUpgradeToGet == 'ResourceAllocationAdvanced' or sUpgradeToGet == 'T3Engineering' then
                AiBotOrders.IssueTrackedEnhancement(oACU, sUpgradeToGet, false, 'ACUEGUpr1')
                bProceedWithLogic = false
            elseif oACU:HasEnhancement('ResourceAllocation') and not(oACU:HasEnhancement('AdvancedEngineering')) and oACU:GetBlueprint().Enhancements.AdvancedEngineering and GetGameTimeSeconds() <= 15 then
                --Get advanced engineering so we build faster
                sUpgradeToGet = 'AdvancedEngineering'
                AiBotOrders.IssueTrackedEnhancement(oACU, sUpgradeToGet, false, 'ACUEGUpr2')
                bProceedWithLogic = false
            end
        end
        if bDebugMessages == true then LOG(sFunctionRef..': bProceedWithLogic='..tostring(bProceedWithLogic)) end
        if bProceedWithLogic then
            --Get nearest enemy DF or IF unit if almost in range of us
            local oNearestEnemy
            local iClosestEnemyLessRangeDist = 10
            local iCurEnemyLessRangeDist
            function ConsiderEnemies(tEnemyUnits)
                if tEnemyUnits[1] then
                    for iUnit, oUnit in tEnemyUnits do
                        if not(oUnit.Dead) and (oUnit[AiBotUnitInfo.refiCombatRange] or 0) >= 4 then
                            iCurEnemyLessRangeDist = AiBotUtilities.GetDistanceBetweenPositions(oUnit:GetPosition(), oACU:GetPosition()) - oUnit[AiBotUnitInfo.refiCombatRange]
                            if iCurEnemyLessRangeDist < iClosestEnemyLessRangeDist and not(EntityCategoryContains(AiBotUnitInfo.refCategoryLandScout - AiBotUnitInfo.refCategoryCombatScout, oUnit.UnitId)) then
                                iClosestEnemyLessRangeDist = iCurEnemyLessRangeDist
                                oNearestEnemy = oUnit
                            end
                        end
                    end
                end
            end
            ConsiderEnemies(tLZOrWZTeamData[AiBotMap.subrefTEnemyUnits])
            if not(oNearestEnemy) and not bDualGapAirHomeOnly and AiBotUtilities.IsTableEmpty(tLZOrWZData[AiBotMap.subrefLZAdjacentLandZones]) == false then
                for _, iAdjLZ in tLZOrWZData[AiBotMap.subrefLZAdjacentLandZones] do
                    local tAdjLZTeamData = AiBotMap.tAllPlateaus[iPlateauOrZero][AiBotMap.subrefPlateauLandZones][iAdjLZ][AiBotMap.subrefLZTeamData][iTeam]
                    ConsiderEnemies(tAdjLZTeamData[AiBotMap.subrefTEnemyUnits])
                end
            end

            --Are we already building something?
            if bDebugMessages == true then LOG(sFunctionRef..': ACU unit state='..AiBotUnitInfo.GetUnitState(oACU)..'; oNearestEnemy='..(oNearestEnemy.UnitId or 'nil')..(AiBotUnitInfo.GetUnitLifetimeCount(oNearestEnemy) or 'nil')) end
            --If are repariing then check we have a focus unit due to bug where unit state can show as repairing when ACU is idling
            if not(oACU:IsUnitState('Building')) and (not(oACU:IsUnitState('Repairing')) or (oACU:GetWorkProgress() == 0 and not(AiBotUnitInfo.IsUnitValid(oACU:GetFocusUnit())))) and not(oACU:IsUnitState('Capturing')) and (aiBrain:GetEconomyStoredRatio('MASS') <= 0.95 or not(oACU:IsUnitState('Reclaiming'))) then
                if oNearestEnemy then --Attack enemy that is almost in range of us
                    if AttackNearestEnemyWithACU(iPlateauOrZero, iLZOrWZ, tLZOrWZData, tLZOrWZTeamData, oACU, math.max(10, iClosestEnemyLessRangeDist + oNearestEnemy[AiBotUnitInfo.refiCombatRange])) then
                        if bDebugMessages == true then LOG(sFunctionRef..': Attacking enemy with normal logic') end
                    elseif (not bDualGapAirHomeOnly or tLZOrWZTeamData[AiBotMap.subrefLZbCoreBase]) and oACU[AiBotUnitInfo.refbLastShotBlocked] then
                        AiBotOrders.IssueTrackedMove(oACU, oNearestEnemy:GetPosition(), 5, false, 'EarlyEnBlM', false)
                    elseif not bDualGapAirHomeOnly or tLZOrWZTeamData[AiBotMap.subrefLZbCoreBase] then
                        AiBotOrders.IssueTrackedAttackMove(oACU, oNearestEnemy:GetPosition(), 5, false, 'EarlyEnAM', false)
                    end
                else
                    --End early game status if we already have various units (e.g. prebuilt base or campaign)
                    if aiBrain[AiBotEconomy.refiOurHighestAirFactoryTech] >= 1 and aiBrain[AiBotEconomy.refiOurHighestLandFactoryTech] >= 1 and aiBrain[AiBotEconomy.refiGrossEnergyBaseIncome] / aiBrain[AiBotEconomy.refiBrainResourceMultiplier] >= 250 and aiBrain[AiBotEconomy.refiGrossMassBaseIncome] / aiBrain[AiBotEconomy.refiBrainResourceMultiplier] >= 2 and tLZOrWZTeamData[AiBotMap.subrefMexCountByTech][1] + tLZOrWZTeamData[AiBotMap.subrefMexCountByTech][2] * 4 + tLZOrWZTeamData[AiBotMap.subrefMexCountByTech][3] * 4 >= math.min((tLZOrWZData[AiBotMap.subrefLZOrWZMexCount] or 0), 4) then
                        if bDebugMessages == true then LOG(sFunctionRef..': We seem to have a decent base already so flagging to end early build order, will still look for action noow though') end
                        oACU[refbDoingInitialBuildOrder] = false
                    end

                    AiBotAir.UpdateTransportPlateauDropLocationShortlist(iTeam) --Redundancy

                    --local iPlateau, iLandZone = AiBotMap.GetPlateauAndLandZoneReferenceFromPosition(oACU:GetPosition(), true, oACU)

                    if bDebugMessages == true then LOG(sFunctionRef..': iPlateauOrZero='..(iPlateauOrZero or 'nil')..'; iLZOrWZ='..(iLZOrWZ or 'nil')..'; ACU pos='..repru(oACU:GetPosition())..'; Cur mexes='..aiBrain:GetCurrentUnits(AiBotUnitInfo.refCategoryMex)..'; Cur Pgens='..aiBrain:GetCurrentUnits(AiBotUnitInfo.refCategoryPower)..'; Mass stored='..aiBrain:GetEconomyStored('MASS')..'; Energy stored='..aiBrain:GetEconomyStored('ENERGY')) end
                    if (iPlateauOrZero or 0) > 0 and iLZOrWZ > 0 then
                        --Do we want to build a mex, hydro or factory?
                        if bDebugMessages == true then LOG(sFunctionRef..': Current land factories='..aiBrain:GetCurrentUnits(AiBotUnitInfo.refCategoryLandFactory)..'; Gross energy income='..aiBrain[AiBotEconomy.refiGrossEnergyBaseIncome]..'; Gross mass income='..aiBrain[AiBotEconomy.refiGrossMassBaseIncome]) end
                        local iMinEnergyPerTickWanted = 14 * iResourceMod --i.e. 6 T1 PGens given ACU gives 2 E
                        --Large maps - consider going 2nd air instead of 2nd land
                        local bGoSecondAir = false
                        local iLandTravelDistanceToEnemyBase = 100000
                        local iEnemyIsland = NavUtils.GetLabel(AiBotMap.refPathingTypeLand, tLZOrWZTeamData[AiBotMap.reftClosestEnemyBase])
                        local iOurIsland = tLZOrWZData[AiBotMap.subrefLZIslandRef]
                        if iOurIsland > 0 and iOurIsland == iEnemyIsland then
                            local iEnemyPlateau, iEnemyLandZone = AiBotMap.GetPlateauAndLandZoneReferenceFromPosition(tLZOrWZTeamData[AiBotMap.reftClosestEnemyBase])
                            if iEnemyLandZone > 0 then iLandTravelDistanceToEnemyBase = AiBotMap.GetTravelDistanceBetweenLandZones(iEnemyPlateau, iLZOrWZ, iEnemyLandZone) end
                        end

                        if bDebugMessages == true then LOG(sFunctionRef..': Considering whether to go second air, map size='..(AiBotMap.iMapSize or 'nil')..'; iLandTravelDistanceToEnemyBase='..(iLandTravelDistanceToEnemyBase or 'nil')..'; Is table of potential drop zones empty='..tostring(AiBotUtilities.IsTableEmpty(AiBotTeam.tTeamData[iTeam][AiBotTeam.reftiPotentialDropZonesByPlateau]))..'; Is transport island shortlist empty='..tostring(AiBotUtilities.IsTableEmpty(AiBotTeam.tTeamData[iTeam][AiBotTeam.reftTransportIslandDropShortlist]))..'; Travel distance using nearest allied and enemy base='..(AiBotUtilities.GetTravelDistanceBetweenPositions(tLZOrWZTeamData[AiBotMap.reftClosestFriendlyBase], tLZOrWZTeamData[AiBotMap.reftClosestEnemyBase], AiBotMap.refPathingTypeLand) or 'nil')) end
                        if AiBotMap.iMapSize >= 512 and (AiBotMap.iMapSize > 512 or iLandTravelDistanceToEnemyBase > 280) and iPlateauOrZero > 0 and (AiBotUtilities.IsTableEmpty(AiBotTeam.tTeamData[iTeam][AiBotTeam.reftiPotentialDropZonesByPlateau]) == false or AiBotUtilities.IsTableEmpty(AiBotTeam.tTeamData[iTeam][AiBotTeam.reftTransportIslandDropShortlist]) == false) then
                            if bDebugMessages == true then LOG(sFunctionRef..': Going second air due to map size or travel distance, unless have lots of mass stored and wnat a land fac quickly to spend the mass') end
                            if aiBrain:GetEconomyStoredRatio('MASS') >= 0.4 and AiBotMap.iMapSize <= 800 and aiBrain[AiBotMap.refbCanPathToEnemyBaseWithLand] and iLandTravelDistanceToEnemyBase <= 600 and aiBrain:GetCurrentUnits(AiBotUnitInfo.refCategoryLandFactory) < 2 then
                                --Dont go second air
                            elseif tLZOrWZData[AiBotMap.subrefLZOrWZMexCount] > 12 then
                                --Dont go second air as lots of mexes
                            else
                                bGoSecondAir = true
                            end
                        end
                        if not(bGoSecondAir) and AiBotMap.iMapSize >= 512 and AiBotUtilities.IsTableEmpty(AiBotTeam.tTeamData[iTeam][AiBotTeam.subreftoFriendlyHumanAndAIBrains]) == false and table.getn(AiBotTeam.tTeamData[iTeam][AiBotTeam.subreftoFriendlyHumanAndAIBrains]) >= 2 then
                            --Still consider going 2nd air if have teammates between us and enemy (all teammates, not just AiBot teammates) and are on a 10km+ map
                            if tLZOrWZTeamData[AiBotMap.refbBaseInSafePosition] then
                                bGoSecondAir = true
                                if bDebugMessages == true then LOG(sFunctionRef..': Will go second air for brain '..aiBrain.Nickname) end
                            end

                        end
                        if not(bGoSecondAir) and (aiBrain[AiBotOverseer.refbPrioritiseNavy] or aiBrain[AiBotOverseer.refbPrioritiseAir]) and AiBotConditions.DoWeWantAirFactoryInsteadOfLandFactory(iTeam, tLZOrWZData, tLZOrWZTeamData, aiBrain) then
                            bGoSecondAir = true
                            if bDebugMessages == true then LOG(sFunctionRef..': Navy or air focus, we want air fac instead of land so will go second air') end
                        end
                        --Personality override
                        if bGoSecondAir and (aiBrain[AiBotOverseer.refbPrioritiseLand] or aiBrain[AiBotOverseer.refbPrioritiseLowTech]) then bGoSecondAir = false end
                        if bDebugMessages == true then LOG(sFunctionRef..': Deciding on min energy wanted, bGoSecondAir='..tostring(bGoSecondAir)..'; Gross mass income='..aiBrain[AiBotEconomy.refiGrossMassBaseIncome]) end
                        if bGoSecondAir then
                            aiBrain[AiBotEconomy.refbGoingSecondAir] = true
                            if bDebugMessages == true then LOG(sFunctionRef..': Going second air, net energy base income='..aiBrain[AiBotEconomy.refiNetEnergyBaseIncome]..'; Energy stored='..aiBrain:GetEconomyStored('ENERGY')) end
                            if aiBrain[AiBotEconomy.refiNetEnergyBaseIncome] >= 4.5 and aiBrain:GetEconomyStored('ENERGY') >= 1800 then
                                iMinEnergyPerTickWanted = 20 * math.min(iResourceMod, aiBrain[AiBotEconomy.refiBrainBuildRateMultiplier]) --Can get away with 4 pgens in some casese, even if engineers have managed to get some tree reclaim
                            else
                                iMinEnergyPerTickWanted = 22 * math.min(iResourceMod, aiBrain[AiBotEconomy.refiBrainBuildRateMultiplier]) --ACU gives 2E, want equiv of 10 PGens, assuming build rate is same as resource rate
                            end
                        end
                        local iFactoryCap = 4 --redundancy - only intend to use in very low mass scenarios that arent low mex maps
                        if aiBrain[AiBotEconomy.refiGrossMassBaseIncome] < 0.8 * aiBrain[AiBotEconomy.refiBrainBuildRateMultiplier] and (tLZOrWZData[AiBotMap.subrefLZOrWZMexCount] or 0) <= 2 and aiBrain:GetEconomyStoredRatio('MASS') < 0.3 then
                            iMinEnergyPerTickWanted = 6 * aiBrain[AiBotEconomy.refiBrainBuildRateMultiplier]
                            iFactoryCap = 1
                        end

                        if iMinEnergyPerTickWanted <= 15 and aiBrain:GetEconomyStored('ENERGY') <= 200 and (aiBrain:GetEconomyStored('ENERGY') < 50 or aiBrain:GetEconomyStored('MASS') > math.min(75, aiBrain:GetEconomyStored('ENERGY'))) then
                            iMinEnergyPerTickWanted = iMinEnergyPerTickWanted + 2
                            if bDebugMessages == true then LOG(sFunctionRef..': Will get extra pgen as looks like we are about to stall E') end
                        end

                        local iCurLandFactories = aiBrain:GetCurrentUnits(AiBotUnitInfo.refCategoryLandFactory)
                        if bDebugMessages == true then LOG(sFunctionRef..': iCurLandFactories='..iCurLandFactories..'; AIr factories='..aiBrain:GetCurrentUnits(AiBotUnitInfo.refCategoryAirFactory)..'; iFactoryCap='..iFactoryCap..'; aiBrain[AiBotEconomy.refiGrossEnergyBaseIncome]='..aiBrain[AiBotEconomy.refiGrossEnergyBaseIncome]..'; iMinEnergyPerTickWanted='..iMinEnergyPerTickWanted) end
                        if AiBotMap.bIsLowMexMap and GetGameTimeSeconds() <= 1800 and tLZOrWZTeamData[AiBotMap.subrefMexCountByTech][3] == 0 then
                            GetLowMexMapEarlyACUOrder(aiBrain, oACU, iPlateauOrZero, iLZOrWZ, tLZOrWZData, tLZOrWZTeamData)
                        else
                            --First bomber mode - apply special build order
                            if aiBrain[AiBotOverseer.refbFirstBomber] and iCurLandFactories == 0 then
                                --If havent got pgen then build pgen
                                local iCurPGens = aiBrain:GetCurrentUnits(AiBotUnitInfo.refCategoryPower)
                                local iCurAirFac = aiBrain:GetCurrentUnits(AiBotUnitInfo.refCategoryAirFactory)
                                local iCurMex = aiBrain:GetCurrentUnits(AiBotUnitInfo.refCategoryMex)
                                if iCurPGens == 0 or (iCurPGens < 3 and AiBotUtilities.bQuietModActive) then
                                    ACUActionBuildPower(aiBrain, oACU)
                                elseif iCurAirFac == 0 then
                                    ACUActionBuildFactory(aiBrain, oACU, iPlateauOrZero, iLZOrWZ, tLZOrWZData, tLZOrWZTeamData, AiBotUnitInfo.refCategoryAirFactory)
                                elseif iCurPGens < 3 or (iCurPGens < 4 and AiBotUtilities.bQuietModActive) then
                                    ACUActionBuildPower(aiBrain, oACU)
                                elseif iCurMex < 4 and AiBotUtilities.IsTableEmpty(tLZOrWZData[AiBotMap.subrefMexUnbuiltLocations]) == false then
                                    ACUActionBuildMex(aiBrain, oACU)
                                else
                                    ACUActionBuildFactory(aiBrain, oACU, iPlateauOrZero, iLZOrWZ, tLZOrWZData, tLZOrWZTeamData, AiBotUnitInfo.refCategoryLandFactory)
                                end
                            elseif iCurLandFactories == 0 then
                                if bDebugMessages == true then LOG(sFunctionRef..': Want ACU to build a land factory') end
                                ACUActionBuildFactory(aiBrain, oACU, iPlateauOrZero, iLZOrWZ, tLZOrWZData, tLZOrWZTeamData, AiBotUnitInfo.refCategoryLandFactory)
                                --Build more factories if we have 100% E, positive net energy, have a decent amount of mass stored, and we have at least 1 pgen or hydro
                            elseif iCurLandFactories < 10 and aiBrain:GetEconomyStoredRatio('ENERGY') >= 0.99 and aiBrain:GetEconomyStored('MASS') >= 250 and aiBrain[AiBotEconomy.refiNetMassBaseIncome] > 0 and aiBrain[AiBotEconomy.refiNetEnergyBaseIncome] > 0 and aiBrain:GetCurrentUnits(AiBotUnitInfo.refCategoryFactory) < math.max(3, math.min(8, aiBrain[AiBotEconomy.refiGrossMassBaseIncome] * 0.5)) and (not(tLZOrWZTeamData[AiBotMap.refbBaseInSafePosition]) or tLZOrWZTeamData[AiBotMap.subrefiActiveMexUpgrades] >= 2) then
                                if  AiBotConditions.DoWeWantAirFactoryInsteadOfLandFactory(iTeam, tLZOrWZData, tLZOrWZTeamData, aiBrain) or (bGoSecondAir and aiBrain:GetCurrentUnits(AiBotUnitInfo.refCategoryAirFactory) == 0) then
                                    if not(bGoSecondAir) and aiBrain[AiBotEconomy.refiGrossEnergyBaseIncome] < 20 * aiBrain[AiBotEconomy.refiBrainResourceMultiplier] and (aiBrain[AiBotEconomy.refiGrossEnergyBaseIncome] <= iMinEnergyPerTickWanted or aiBrain:GetEconomyStoredRatio('ENERGY') < 0.99 or aiBrain[AiBotEconomy.refiBrainBuildRateMultiplier] >= 1.2) then
                                        if bDebugMessages == true then LOG(sFunctionRef..': want power so can build an air fac') end
                                        ACUActionBuildPower(aiBrain, oACU)
                                    else
                                        ACUActionBuildFactory(aiBrain, oACU, iPlateauOrZero, iLZOrWZ, tLZOrWZData, tLZOrWZTeamData, AiBotUnitInfo.refCategoryAirFactory, AiBotEngineer.refActionBuildAirFactory)
                                    end
                                else
                                    ACUActionBuildFactory(aiBrain, oACU, iPlateauOrZero, iLZOrWZ, tLZOrWZData, tLZOrWZTeamData, AiBotUnitInfo.refCategoryLandFactory)
                                end
                                --do we have unbuilt nearby mexes (within 2 of ACU build range)? if so then build on them
                            elseif aiBrain.CheatEnabled and iResourceMod >= 1.3 and aiBrain:GetEconomyStored('MASS') >= 90 and (iResourceMod >= 2.0 or aiBrain[AiBotEconomy.refiBrainBuildRateMultiplier] > 1.0) and aiBrain[AiBotEconomy.refiGrossEnergyBaseIncome] < iMinEnergyPerTickWanted and ((iResourceMod >= 1.5 and aiBrain[AiBotEconomy.refiGrossEnergyBaseIncome] < 6 * AiBotTeam.tTeamData[aiBrain.AiBotTeam][AiBotTeam.refiHighestBrainResourceMultiplier]) or aiBrain:GetCurrentUnits(AiBotUnitInfo.refCategoryPower) == 0) and (tLZOrWZTeamData[AiBotMap.subrefMexCountByTech][1] or 0) >= 2 then
                                --Build a couple of PGen even if nearby hydro given cheat mult
                                if bDebugMessages == true then LOG(sFunctionRef..': Want more power due to cheat mult before hydro') end
                                ACUActionBuildPower(aiBrain, oACU)
                                --High resource mods where we are going to be getting T2 on our ACU as our first upgrade - go to T2
                            elseif aiBrain[AiBotEconomy.refiGrossEnergyBaseIncome] >= 100 and oACU[refiUpgradeCount] == 0 and aiBrain[AiBotEconomy.refiNetMassBaseIncome] >= 1 and (tLZOrWZTeamData[AiBotMap.subrefiActiveMexUpgrades] > 0 or tLZOrWZTeamData[AiBotMap.subrefMexCountByTech][2] > 0) and aiBrain[AiBotEconomy.refiNetEnergyBaseIncome] >= 25 and aiBrain:GetEconomyStoredRatio('MASS') >= 0.3 and GetACUUpgradeWanted(oACU, false, tLZOrWZData, tLZOrWZTeamData, iPlateauOrZero) == 'AdvancedEngineering' and AiBotConditions.SafeToUpgradeUnit(oACU) then
                                if bDebugMessages == true then LOG(sFunctionRef..': Early T2 upgrade for high resourcem odifier games') end
                                AiBotOrders.IssueTrackedEnhancement(oACU, 'AdvancedEngineering', false, 'ACUT2')
                                --We have T2+ and want power
                            elseif oACU[refiBuildTech] >= 2 and HaveActionForACUAsEngineer(oACU, tLZOrWZData, tLZOrWZTeamData, iPlateauOrZero, iLZOrWZ) then
                                if bDebugMessages == true then LOG(sFunctionRef..': Will make use of ACU engineering suite to build power') end
                            elseif aiBrain[AiBotEconomy.refiGrossEnergyBaseIncome] >= 12 * iResourceMod and (aiBrain:GetEconomyStored('ENERGY') >= 100 or aiBrain[AiBotEconomy.refiNetEnergyBaseIncome] > -0.1) and ((tLZOrWZTeamData[AiBotMap.subrefMexCountByTech][1] + tLZOrWZTeamData[AiBotMap.subrefMexCountByTech][2] * 3 + tLZOrWZTeamData[AiBotMap.subrefMexCountByTech][3] * 9) < 5 or aiBrain:GetEconomyStoredRatio('ENERGY') >= 0.5 or aiBrain[AiBotEconomy.refiGrossEnergyBaseIncome] >= 10 * aiBrain[AiBotEconomy.refiGrossMassBaseIncome]) and ConsiderBuildingMex(tLZOrWZData, tLZOrWZTeamData, oACU, 2) then
                                --Do nothing - have bene given an order to build a neaby mex
                                if bDebugMessages == true then LOG(sFunctionRef..': Want more mex as have decent base power level, tLZOrWZTeamData[AiBotMap.subrefMexCountByTech]='..repru(tLZOrWZTeamData[AiBotMap.subrefMexCountByTech])..'; energy %='..aiBrain:GetEconomyStoredRatio('ENERGY')..'; gross mass='..aiBrain[AiBotEconomy.refiGrossMassBaseIncome]) end
                                --LOUD - consider mexes further away and get in proportion to pgens initially
                            elseif aiBrain[AiBotEconomy.refiGrossEnergyBaseIncome] < iMinEnergyPerTickWanted then

                                --Do we want to build a hydro (so get mexes first then hydro) or build pgen?


                                local bHydroBuildOrder = false
                                --On crag dunes the hydro travel distance is 102 away and going for early hydro (with 4 mexes) causes power stall; top players BO appears to be normal no-hydro BO
                                --For theta passage the travel distance is 62.5
                                --For Cadmium green its 51.9
                                local tClosestHydroToACU
                                local iClosestDistToACU = 100000

                                local iCurHydroDist
                                local bHaveUnderConstructionFirstHydro = false
                                local oOptionalUnderConstructionHydro --used for redundancy
                                if AiBotUtilities.IsTableEmpty(tLZOrWZData[AiBotMap.subrefHydroLocations]) == false then

                                    for iEntry, tHydro in tLZOrWZData[AiBotMap.subrefHydroLocations] do
                                        if bDebugMessages == true then LOG(sFunctionRef..': Travel dist to hydro='..AiBotUtilities.GetTravelDistanceBetweenPositions(AiBotMap.GetPlayerStartPosition(aiBrain), tHydro, AiBotMap.refPathingTypeLand)) end
                                        if AiBotUtilities.GetTravelDistanceBetweenPositions(AiBotMap.GetPlayerStartPosition(aiBrain), tHydro, AiBotMap.refPathingTypeLand) <= 90 then --Open palms is 85.65
                                            bHydroBuildOrder = true
                                            iCurHydroDist = AiBotUtilities.GetTravelDistanceBetweenPositions(tHydro, oACU:GetPosition(), AiBotMap.refPathingTypeLand)
                                            if iCurHydroDist < iClosestDistToACU then
                                                iClosestDistToACU = iCurHydroDist
                                                tClosestHydroToACU = {tHydro[1], tHydro[2], tHydro[3]}
                                            end
                                        end
                                    end
                                end
                                if not(bHydroBuildOrder) then
                                    --Redundancy 1 incase have a hydro registered to core zone instead of nearby and we ahve travlled to nearby zone
                                    local tNearbyHydro = aiBrain:GetUnitsAroundPoint(AiBotUnitInfo.refCategoryHydro, oACU:GetPosition(), 35, 'Ally')
                                    if bDebugMessages == true then LOG(sFunctionRef..': Is table of nearby hydros empty='..tostring(AiBotUtilities.IsTableEmpty(tNearbyHydro))) end
                                    local oCompleteHydro
                                    if AiBotUtilities.IsTableEmpty(tNearbyHydro) == false then

                                        for iHydro, oHydro in tNearbyHydro do
                                            if oHydro:GetAIBrain() == aiBrain and oHydro:GetFractionComplete() < 1 then
                                                iCurHydroDist = AiBotUtilities.GetDistanceBetweenPositions(oACU:GetPosition(), oHydro:GetPosition())
                                                if iCurHydroDist < iClosestDistToACU then
                                                    iClosestDistToACU = iCurHydroDist
                                                    tClosestHydroToACU = oHydro:GetPosition()
                                                    oOptionalUnderConstructionHydro = oHydro
                                                end
                                            else
                                                oCompleteHydro = oHydro
                                            end
                                        end
                                    end
                                    if not(oOptionalUnderConstructionHydro) and oCompleteHydro then
                                        iClosestDistToACU = AiBotUtilities.GetDistanceBetweenPositions(oACU:GetPosition(), oCompleteHydro:GetPosition())
                                        tClosestHydroToACU = oCompleteHydro:GetPosition()
                                        bHydroBuildOrder = true
                                    elseif oOptionalUnderConstructionHydro then bHydroBuildOrder = true
                                    end
                                end
                                if bDebugMessages == true then LOG(sFunctionRef..': Will adjust build order depending on if have hydro nearby. Is table of land zone hydros empty='..tostring(AiBotUtilities.IsTableEmpty(tLZOrWZData[AiBotMap.subrefHydroLocations]))..'; bHydroBuildOrder='..tostring(bHydroBuildOrder)) end
                                if not(bHydroBuildOrder) then
                                    --Per discord gameplay and training pinned build order for going land facs with no hydro:
                                    --ACU:      Landfac - 2 PG - 2 Mex - 1 PG - 2 Mex - 3 PG - Landfac - PG - Landfac
                                    if bDebugMessages == true then LOG(sFunctionRef..': No hydro locations so will build power or mex depending on income') end
                                    --LOUD special build order
                                    if (AiBotUtilities.bLoudModActive or AiBotUtilities.bQuietModActive) and aiBrain:GetCurrentUnits(AiBotUnitInfo.refCategoryMex) < math.min(4, aiBrain:GetCurrentUnits(AiBotUnitInfo.refCategoryPower)) and aiBrain:GetEconomyStored('MASS') <= math.min(200, aiBrain:GetEconomyStored('ENERGY') * 4) and ConsiderBuildingMex(tLZOrWZData, tLZOrWZTeamData, oACU, 50) then
                                        if bDebugMessages == true then LOG(sFunctionRef..': LOUD/QUIET build order = want to get mex sooner than normal') end
                                    elseif aiBrain[AiBotEconomy.refiGrossEnergyBaseIncome] < math.max(6, 2 * (tLZOrWZTeamData[AiBotMap.subrefMexCountByTech][1] + tLZOrWZTeamData[AiBotMap.subrefMexCountByTech][2] * 3 + tLZOrWZTeamData[AiBotMap.subrefMexCountByTech][3] * 9)) * iResourceMod then
                                        if bDebugMessages == true then LOG(sFunctionRef..': Want to build initial PGens') end
                                        ACUActionBuildPower(aiBrain, oACU)
                                    else
                                        local iMexInLandZone = 0
                                        if AiBotUtilities.IsTableEmpty(tLZOrWZData[AiBotMap.subrefLZOrWZMexLocations]) == false then iMexInLandZone = table.getn(tLZOrWZData[AiBotMap.subrefLZOrWZMexLocations]) end
                                        local iMaxMexesBeforeHydro = 4
                                        if iMexInLandZone > 4 and aiBrain:GetEconomyStored('MASS') >= 25 then iMaxMexesBeforeHydro = 3 end
                                        if bDebugMessages == true then LOG(sFunctionRef..': Deciding on ACU action for where no hydro nearby, gross mass income='..aiBrain[AiBotEconomy.refiGrossMassBaseIncome]..'; Gross energy income='..aiBrain[AiBotEconomy.refiGrossEnergyBaseIncome]..'; iMexInLandZone='..iMexInLandZone..'; iMinEnergyPerTickWanted='..iMinEnergyPerTickWanted..'; iCurLandFactories='..iCurLandFactories) end
                                        if aiBrain[AiBotEconomy.refiGrossMassBaseIncome] < math.min(2, iMexInLandZone) * 0.2 * iResourceMod and AiBotUtilities.IsTableEmpty(tLZOrWZData[AiBotMap.subrefMexUnbuiltLocations]) == false and (not(AiBotOverseer.bNoRushActive) or not(AiBotConditions.NoRushPreventingHydroOrMex(tLZOrWZData, true))) then
                                            if bDebugMessages == true then LOG(sFunctionRef..': Want at least 2 mexes') end
                                            ACUActionBuildMex(aiBrain, oACU)

                                        elseif aiBrain[AiBotEconomy.refiGrossEnergyBaseIncome] < 8 * iResourceMod then
                                            if bDebugMessages == true then LOG(sFunctionRef..': Want at least 4 PGens') end
                                            ACUActionBuildPower(aiBrain, oACU)
                                        elseif aiBrain[AiBotEconomy.refiGrossMassBaseIncome] < math.min(iMaxMexesBeforeHydro, iMexInLandZone) * 0.2 * iResourceMod and AiBotUtilities.IsTableEmpty(tLZOrWZData[AiBotMap.subrefMexUnbuiltLocations]) == false and (not(AiBotOverseer.bNoRushActive) or not(AiBotConditions.NoRushPreventingHydroOrMex(tLZOrWZData, true))) then
                                            if bDebugMessages == true then LOG(sFunctionRef..': Want up to iMaxMexesBeforeHydro='..iMaxMexesBeforeHydro..' mexes') end
                                            ACUActionBuildMex(aiBrain, oACU)
                                            --QUIET specific - abort build order early if are heavily stalling
                                        elseif (AiBotUtilities.bQuietModActive or AiBotUtilities.bLoudModActive) and (aiBrain[AiBotEconomy.refiNetEnergyBaseIncome] >= 4 or aiBrain:GetEconomyTrend('ENERGY') >= 4 or (aiBrain:GetEconomyStoredRatio('ENERGY') >= 0.65 and math.max(aiBrain[AiBotEconomy.refiNetEnergyBaseIncome], aiBrain:GetEconomyTrend('ENERGY')) >= 2.5)) and aiBrain[AiBotEconomy.refiGrossEnergyBaseIncome] >= 18 and aiBrain[AiBotEconomy.refiNetMassBaseIncome] <= -0.2 and aiBrain:GetEconomyStoredRatio('ENERGY') >= 0.4 and aiBrain:GetEconomyStored('MASS') <= 1 then
                                            if bDebugMessages == true then LOG(sFunctionRef..': Finish build order early as we cant spend the mass') end
                                            oACU[refbDoingInitialBuildOrder] = false
                                        elseif aiBrain[AiBotEconomy.refiGrossEnergyBaseIncome] < iMinEnergyPerTickWanted and ((aiBrain:GetEconomyStoredRatio('ENERGY') <= 0.6 or (aiBrain:GetEconomyStoredRatio('ENERGY') <= 0.75 and aiBrain[AiBotEconomy.refiNetEnergyBaseIncome] <= 3) or (aiBrain[AiBotEconomy.refiNetEnergyBaseIncome] <= 1.5 and (aiBrain[AiBotEconomy.refiNetEnergyBaseIncome] < 0.5 or aiBrain:GetEconomyStoredRatio('ENERGY') <= 0.98)) or aiBrain[AiBotEconomy.refiGrossEnergyBaseIncome] <= math.max(12 * aiBrain[AiBotEconomy.refiBrainBuildRateMultiplier], iMinEnergyPerTickWanted * 0.75)) or aiBrain:GetEconomyStoredRatio('MASS') >= 0.35) then
                                            if bDebugMessages == true then LOG(sFunctionRef..': Want basic level of power, energy stored='..aiBrain:GetEconomyStoredRatio('ENERGY')..'; Net E income='..aiBrain[AiBotEconomy.refiNetEnergyBaseIncome]..'; aiBrain:GetEconomyTrend(ENERGY)='..aiBrain:GetEconomyTrend('ENERGY')..'; Gross inc='..aiBrain[AiBotEconomy.refiGrossEnergyBaseIncome]..'; Mass %='..aiBrain:GetEconomyStoredRatio('MASS')..'; Net mass='..aiBrain[AiBotEconomy.refiNetMassBaseIncome]) end
                                            ACUActionBuildPower(aiBrain, oACU)
                                            --below are redundancy - if we have min energy per tick wanted then wouldn't expect below to trigger
                                        elseif aiBrain[AiBotEconomy.refiGrossMassBaseIncome] < math.min(4, iMexInLandZone) * 0.2 * iResourceMod and AiBotUtilities.IsTableEmpty(tLZOrWZData[AiBotMap.subrefMexUnbuiltLocations]) == false and (not(AiBotOverseer.bNoRushActive) or not(AiBotConditions.NoRushPreventingHydroOrMex(tLZOrWZData, true))) then
                                            --e.g. if went 3 mex hydro then want to get 4th mex before factory
                                            if bDebugMessages == true then LOG(sFunctionRef..': Want up to 4 mexes') end
                                            ACUActionBuildMex(aiBrain, oACU)
                                        elseif iCurLandFactories < 2 and iCurLandFactories + aiBrain:GetCurrentUnits(AiBotUnitInfo.refCategoryAirFactory) < 3 and aiBrain[AiBotMap.refbCanPathToEnemyBaseWithLand] and (not(tLZOrWZTeamData[AiBotMap.refbBaseInSafePosition]) or tLZOrWZTeamData[AiBotMap.subrefiActiveMexUpgrades] >= 2 or aiBrain:GetCurrentUnits(AiBotUnitInfo.refCategoryAirFactory) == 0) and AiBotConditions.WantMoreFactories(aiBrain.AiBotTeam, iPlateauOrZero, iLZOrWZ) and aiBrain:GetCurrentUnits(AiBotUnitInfo.refCategoryAirFactory) == 0 then
                                            if bGoSecondAir then
                                                ACUActionBuildFactory(aiBrain, oACU, iPlateauOrZero, iLZOrWZ, tLZOrWZData, tLZOrWZTeamData, AiBotUnitInfo.refCategoryAirFactory, AiBotEngineer.refActionBuildAirFactory)
                                                if bDebugMessages == true then LOG(sFunctionRef..': Want to go second air') end
                                            else
                                                if bDebugMessages == true then LOG(sFunctionRef..': Want 2 land factories') end
                                                ACUActionBuildFactory(aiBrain, oACU, iPlateauOrZero, iLZOrWZ, tLZOrWZData, tLZOrWZTeamData)
                                            end
                                        elseif aiBrain[AiBotEconomy.refiGrossMassBaseIncome] < iMexInLandZone * 0.2 * iResourceMod and AiBotUtilities.IsTableEmpty(tLZOrWZData[AiBotMap.subrefMexUnbuiltLocations]) == false and (not(AiBotOverseer.bNoRushActive) or not(AiBotConditions.NoRushPreventingHydroOrMex(tLZOrWZData, true))) then
                                            if bDebugMessages == true then LOG(sFunctionRef..': Want to build on every mex in land zone') end
                                            ACUActionBuildMex(aiBrain, oACU)
                                        elseif iCurLandFactories < 2 and AiBotMap.iMapSize <= 512 and aiBrain[AiBotMap.refbCanPathToEnemyBaseWithLand] and (not(tLZOrWZTeamData[AiBotMap.refbBaseInSafePosition]) or tLZOrWZTeamData[AiBotMap.subrefiActiveMexUpgrades] >= 2) and aiBrain:GetEconomyStored('MASS') >= 40 and iPlateauOrZero > 0 and (aiBrain:GetEconomyStored('MASS') >= 200 or AiBotConditions.WantMoreFactories(iTeam, iPlateauOrZero, iLZOrWZ)) and not(AiBotOverseer.bNoRushActive) then
                                            if bDebugMessages == true then LOG(sFunctionRef..': Dont have 2 land facs yet so will get another') end
                                            --ACUActionBuildFactory(aiBrain, oACU, iPlateauOrZero, iLandOrWaterZone, tLZData, tLZTeamData, iFactoryCategoryOverride, iEngineerActionOverride)
                                            ACUActionBuildFactory(aiBrain, oACU, iPlateauOrZero, iLZOrWZ, tLZOrWZData, tLZOrWZTeamData,     AiBotUnitInfo.refCategoryLandFactory, AiBotEngineer.refActionBuildLandFactory)

                                        else
                                            if bDebugMessages == true then LOG(sFunctionRef..': We dont have the min level of power that we want yet') end
                                            ACUActionBuildPower(aiBrain, oACU)
                                        end
                                    end

                                    --Redundancy if failed to get orer from the above
                                    if AiBotUtilities.IsTableEmpty(oACU[AiBotOrders.reftiLastOrders]) and oACU[refbDoingInitialBuildOrder] then
                                        --No hydro nearby - try building power; then try building mex; then cancel initial build order
                                        if AiBotUtilities.IsTableEmpty(tLZOrWZData[AiBotMap.subrefMexUnbuiltLocations]) == false and (not(AiBotOverseer.bNoRushActive) or not(AiBotConditions.NoRushPreventingHydroOrMex(tLZOrWZData, true))) then
                                            ACUActionBuildMex(aiBrain, oACU)
                                        end
                                        if AiBotUtilities.IsTableEmpty(oACU[AiBotOrders.reftiLastOrders]) then
                                            if bDebugMessages == true then LOG(sFunctionRef..': Will try and build power as redundancy') end
                                            ACUActionBuildPower(aiBrain, oACU)
                                            if AiBotUtilities.IsTableEmpty(oACU[AiBotOrders.reftiLastOrders]) then
                                                oACU[refbDoingInitialBuildOrder] = false
                                            end
                                        end
                                    end
                                else --Have a hydro so get more mexes initially
                                    --Max mex to build
                                    local iHydroDistToStart = AiBotUtilities.GetDistanceBetweenPositions(tClosestHydroToACU, tLZOrWZData[AiBotMap.subrefMidpoint])
                                    local iMexInLandZone = 0
                                    local oHydroToConsiderAssisting
                                    local iClosestHydroDist = 1000
                                    if AiBotUtilities.IsTableEmpty(tLZOrWZData[AiBotMap.subrefLZOrWZMexLocations]) == false then iMexInLandZone = table.getn(tLZOrWZData[AiBotMap.subrefLZOrWZMexLocations]) end
                                    if bDebugMessages == true then LOG(sFunctionRef..': Hydro is nearby, Gross mass income='..aiBrain[AiBotEconomy.refiGrossMassBaseIncome]..'; iMexInLandZone='..iMexInLandZone..'; Gross base energy income='..aiBrain[AiBotEconomy.refiGrossEnergyBaseIncome]..'; Dist of closest hydro='..iHydroDistToStart) end
                                    --Do we have a hydro underconstruction in this land zone?
                                    if aiBrain[AiBotEconomy.refiGrossEnergyBaseIncome] < 12 * iResourceMod then
                                        local tHydroInZone = EntityCategoryFilterDown(AiBotUnitInfo.refCategoryHydro, tLZOrWZTeamData[AiBotMap.subreftoLZOrWZAlliedUnits])
                                        if AiBotUtilities.IsTableEmpty(tHydroInZone) == false then
                                            local iCurHydroDist
                                            bHaveUnderConstructionFirstHydro = true
                                            for iHydro, oHydro in tHydroInZone do
                                                if oHydro:GetFractionComplete() == 1 and oHydro:GetAIBrain() == aiBrain then
                                                    bHaveUnderConstructionFirstHydro = false
                                                    break
                                                else
                                                    iCurHydroDist = AiBotUtilities.GetDistanceBetweenPositions(oHydro:GetPosition(), oACU:GetPosition())
                                                    if iCurHydroDist < iClosestHydroDist then
                                                        oHydroToConsiderAssisting = oHydro
                                                        iClosestHydroDist = iCurHydroDist
                                                    end
                                                end
                                            end
                                        end
                                    end
                                    local iMexCap = 4
                                    if iHydroDistToStart >= 50 and not(AiBotUtilities.bLoudModActive) and not(AiBotUtilities.bQuietModActive) then iMexCap = 3 end --e.g. Verdant Valley - dist is c.95, and we power-stall if going for 4 mexes (even after getting 4 trees).  Theta passage dist is 32; Canis river is 61 travel dist and 58 straight line and we also stall E for a while by getting 4 mexes
                                    local bHaveUnbuiltMexNearHydro = false
                                    if AiBotUtilities.IsTableEmpty(tLZOrWZData[AiBotMap.subrefMexUnbuiltLocations]) == false then
                                        local iDistanceThreshold = 80 - 5 * (tLZOrWZTeamData[AiBotMap.subrefMexCountByTech][1] + tLZOrWZTeamData[AiBotMap.subrefMexCountByTech][2] + tLZOrWZTeamData[AiBotMap.subrefMexCountByTech][3])

                                        for iMex, tMex in tLZOrWZData[AiBotMap.subrefMexUnbuiltLocations] do
                                            if AiBotUtilities.GetTravelDistanceBetweenPositions(tMex, tClosestHydroToACU, AiBotMap.refPathingTypeLand) <= iDistanceThreshold then
                                                bHaveUnbuiltMexNearHydro = true
                                            end
                                        end
                                    end
                                    if bDebugMessages == true then LOG(sFunctionRef..': Loud/QUIET early pgen builder check - cur pgens='..aiBrain:GetCurrentUnits(AiBotUnitInfo.refCategoryPower)..'; Mass stored='..aiBrain:GetEconomyStored('MASS')..'; Energy stored='..aiBrain:GetEconomyStored('ENERGY')) end
                                    if (AiBotUtilities.bLoudModActive or AiBotUtilities.bQuietModActive) and aiBrain:GetCurrentUnits(AiBotUnitInfo.refCategoryPower) <= 1 and aiBrain:GetCurrentUnits(AiBotUnitInfo.refCategoryMex) >= aiBrain:GetCurrentUnits(AiBotUnitInfo.refCategoryPower) and aiBrain:GetEconomyStored('ENERGY') <= math.min(2000, aiBrain:GetEconomyStored('MASS') * 20) then
                                        if bDebugMessages == true then LOG(sFunctionRef..': LOUD/QUIET build order = want to get a pgen before hydro to avoid stalling') end
                                        ACUActionBuildPower(aiBrain, oACU)
                                    elseif bHaveUnderConstructionFirstHydro and
                                            (aiBrain[AiBotEconomy.refiBrainResourceMultiplier] <= 1.2 or
                                                    (oHydroToConsiderAssisting:GetFractionComplete() <= 0.7 - math.min(0.55, 0.35 * (iClosestHydroDist - 10)/10) and (iClosestHydroDist <= 60 - math.min(50, (aiBrain[AiBotEconomy.refiBrainBuildRateMultiplier]-1)*100))) or
                                                    aiBrain:GetEconomyStored('ENERGY') <= 450 or
                                                    iClosestHydroDist <= 2 + oACU:GetBlueprint().Economy.MaxBuildDistance)
                                            and (aiBrain[AiBotEconomy.refiGrossMassBaseIncome] >= 1.2 * iResourceMod or tLZOrWZTeamData[AiBotMap.subrefMexCountByTech][1] >= math.min(3, iMexInLandZone)) then
                                        if bDebugMessages == true then LOG(sFunctionRef..': Have underconstruction hydro and equiv of 3 mexes or every mex in zone so will try and assist it, oHydroToConsiderAssisting:GetFractionComplete()='..oHydroToConsiderAssisting:GetFractionComplete()..'; iClosestHydroDist='..iClosestHydroDist..'; E stored='..aiBrain:GetEconomyStored('ENERGY')..'; Resource multiplier='..aiBrain[AiBotEconomy.refiBrainResourceMultiplier]..'; aiBrain[AiBotEconomy.refiBrainBuildRateMultiplier]='..aiBrain[AiBotEconomy.refiBrainBuildRateMultiplier]) end
                                        ACUActionAssistHydro(aiBrain, oACU, tLZOrWZData, tLZOrWZTeamData, oOptionalUnderConstructionHydro)
                                    elseif (tLZOrWZTeamData[AiBotMap.subrefMexCountByTech][1] + tLZOrWZTeamData[AiBotMap.subrefMexCountByTech][2] * 3 + tLZOrWZTeamData[AiBotMap.subrefMexCountByTech][3]) >= 5 and aiBrain[AiBotEconomy.refiGrossEnergyBaseIncome] < math.max(6, 2 * (tLZOrWZTeamData[AiBotMap.subrefMexCountByTech][1] + tLZOrWZTeamData[AiBotMap.subrefMexCountByTech][2] * 3 + tLZOrWZTeamData[AiBotMap.subrefMexCountByTech][3] * 9)) * iResourceMod then
                                        if bDebugMessages == true then LOG(sFunctionRef..': Want to build pgens or extra hydro, is oOptionalUnderConstructionHydro valid='..tostring(AiBotUnitInfo.IsUnitValid(oOptionalUnderConstructionHydro))) end
                                        if oOptionalUnderConstructionHydro then
                                            ACUActionAssistHydro(aiBrain, oACU, tLZOrWZData, tLZOrWZTeamData, oOptionalUnderConstructionHydro)
                                        else
                                            ACUActionBuildPower(aiBrain, oACU)
                                        end

                                    elseif bHaveUnbuiltMexNearHydro and aiBrain[AiBotEconomy.refiGrossMassBaseIncome] < math.min(iMexCap, iMexInLandZone) * 0.2 * aiBrain[AiBotEconomy.refiBrainBuildRateMultiplier] or (aiBrain[AiBotEconomy.refiGrossMassBaseIncome] < math.min(4, iMexInLandZone) * 0.2 * iResourceMod and aiBrain:GetEconomyStored('MASS') < 100) and (not(AiBotOverseer.bNoRushActive) or not(AiBotConditions.NoRushPreventingHydroOrMex(tLZOrWZData, true))) and ((not(AiBotUtilities.bLoudModActive) and not(AiBotUtilities.bQuietModActive)) or not(bHaveUnderConstructionFirstHydro) or not(oOptionalUnderConstructionHydro) or aiBrain:GetCurrentUnits(AiBotUnitInfo.refCategoryMex) <= 3) then
                                        if bDebugMessages == true then LOG(sFunctionRef..': We ahve mexes in land zone and we havent built on all of them so will build a mex') end
                                        ACUActionBuildMex(aiBrain, oACU)
                                        if AiBotUtilities.IsTableEmpty(oACU[AiBotOrders.reftiLastOrders]) then
                                            if AiBotOrders.bDontConsiderCombinedArmy or oACU.AiBotActive then
                                                AiBotUtilities.ErrorHandler('ACU wants to build a mex but failed to find anywhere')
                                            end
                                        end
                                    elseif aiBrain[AiBotEconomy.refiGrossEnergyBaseIncome] < 10 * iResourceMod and (iResourceMod <= 1.7 or aiBrain:GetEconomyStored('MASS') <= 80) and (iResourceMod <= 1.4 or aiBrain[AiBotEconomy.refiBrainBuildRateMultiplier] <= 1.4 or iClosestHydroDist <= 40 or aiBrain:GetEconomyStored('ENERGY') <= 450) then
                                        if bDebugMessages == true then LOG(sFunctionRef..': Will try to assist a hydro nearby') end
                                        ACUActionAssistHydro(aiBrain, oACU, tLZOrWZData, tLZOrWZTeamData, oOptionalUnderConstructionHydro)
                                    else --We ahve alreadyu confirmed we have < min energy per tick wanted earlier, so want to build pgen
                                        --Have base level of power suggesting already have hydro but we still want a bit more power
                                        if bDebugMessages == true then LOG(sFunctionRef..': Want more power to reach a base level') end
                                        ACUActionBuildPower(aiBrain, oACU)
                                    end

                                    --Redundancy if fail to get order from above
                                    if bDebugMessages == true then LOG(sFunctionRef..': Is ACU table of last orders empty after attempting above='..tostring(AiBotUtilities.IsTableEmpty(oACU[AiBotOrders.reftiLastOrders]))..'; Does ACU have a valid order='..tostring(AiBotConditions.DoesACUHaveValidOrder(oACU))) end
                                    if not(AiBotConditions.DoesACUHaveValidOrder(oACU)) and oACU[refbDoingInitialBuildOrder] and (AiBotOrders.bDontConsiderCombinedArmy or oACU.AiBotActive) then
                                        --Is it just that we want to assist a hydro and engineers havent started one yet? If so then check if we have an engineer assigned to build one, and check the game time
                                        if GetGameTimeSeconds() <= 180 and aiBrain[AiBotEconomy.refiGrossEnergyBaseIncome] < 10 * iResourceMod and AiBotUtilities.IsTableEmpty(tLZOrWZData[AiBotMap.subrefHydroLocations]) == false then
                                            ACUActionAssistHydro(aiBrain, oACU, tLZOrWZData, tLZOrWZTeamData, oOptionalUnderConstructionHydro)
                                            if bDebugMessages == true then LOG(sFunctionRef..': Assuming we are waiting for an engi to start on building a hydro, or we have no nearby mexes to our ACU') end
                                        else
                                            if bDebugMessages == true then LOG(sFunctionRef..': Failed to get order from above so will resort to backup logic') end
                                            --No hydro nearby - try building power; then try building mex; then cancel initial build order
                                            if AiBotUtilities.IsTableEmpty(tLZOrWZData[AiBotMap.subrefMexUnbuiltLocations]) == false and (not(AiBotOverseer.bNoRushActive) or not(AiBotConditions.NoRushPreventingHydroOrMex(tLZOrWZData, true))) then
                                                ACUActionBuildMex(aiBrain, oACU)
                                            end
                                            if not(AiBotConditions.DoesACUHaveValidOrder(oACU)) then
                                                ACUActionAssistHydro(aiBrain, oACU, tLZOrWZData, tLZOrWZTeamData)
                                                if not(AiBotConditions.DoesACUHaveValidOrder(oACU)) then
                                                    ACUActionBuildPower(aiBrain, oACU)
                                                    if not(AiBotConditions.DoesACUHaveValidOrder(oACU)) then
                                                        if not(AiBotMap.bIsCampaignMap) or GetGameTimeSeconds() <= 540 then oACU[refbDoingInitialBuildOrder] = false end
                                                    end
                                                end
                                            end
                                        end
                                    end
                                end
                            else
                                --Have initial power and mexes built, get second factory now subject to the cap
                                if iCurLandFactories + aiBrain:GetCurrentUnits(AiBotUnitInfo.refCategoryAirFactory) < iFactoryCap then
                                    local bWantAirFactory = AiBotConditions.DoWeWantAirFactoryInsteadOfLandFactory(iTeam, tLZOrWZData, tLZOrWZTeamData, aiBrain)
                                    if bDebugMessages == true then LOG(sFunctionRef..': Checking if want more factories, iCurLandFactories='..iCurLandFactories..'; Want more factories='..tostring(AiBotConditions.WantMoreFactories(aiBrain.AiBotTeam, iPlateauOrZero, iLZOrWZ))..'; Cur air factories='..aiBrain:GetCurrentUnits(AiBotUnitInfo.refCategoryAirFactory)..'; bWantAirFactory='..tostring(bWantAirFactory)) end
                                    if bGoSecondAir and aiBrain:GetCurrentUnits(AiBotUnitInfo.refCategoryAirFactory) == 0 then
                                        ACUActionBuildFactory(aiBrain, oACU, iPlateauOrZero, iLZOrWZ, tLZOrWZData, tLZOrWZTeamData, AiBotUnitInfo.refCategoryAirFactory, AiBotEngineer.refActionBuildAirFactory)
                                        if bDebugMessages == true then LOG(sFunctionRef..': Want ACU to go second air') end
                                    elseif iCurLandFactories < 2 and AiBotConditions.WantMoreFactories(aiBrain.AiBotTeam, iPlateauOrZero, iLZOrWZ) and iCurLandFactories + aiBrain:GetCurrentUnits(AiBotUnitInfo.refCategoryAirFactory) < 3 then
                                        if bDebugMessages == true then LOG(sFunctionRef..': Want to g et a second land factory or air factory') end
                                        if bWantAirFactory then
                                            if not(bGoSecondAir) and aiBrain[AiBotEconomy.refiGrossEnergyBaseIncome] < 20 * aiBrain[AiBotEconomy.refiBrainResourceMultiplier] then
                                                if bDebugMessages == true then LOG(sFunctionRef..': want power in order that we can build an air fac') end
                                                ACUActionBuildPower(aiBrain, oACU)
                                            else
                                                ACUActionBuildFactory(aiBrain, oACU, iPlateauOrZero, iLZOrWZ, tLZOrWZData, tLZOrWZTeamData,     AiBotUnitInfo.refCategoryAirFactory, AiBotEngineer.refActionBuildAirFactory)
                                            end
                                        else
                                            ACUActionBuildFactory(aiBrain, oACU, iPlateauOrZero, iLZOrWZ, tLZOrWZData, tLZOrWZTeamData,     AiBotUnitInfo.refCategoryLandFactory, AiBotEngineer.refActionBuildLandFactory)
                                        end
                                    elseif iCurLandFactories < 2 and AiBotMap.iMapSize <= 512 and aiBrain[AiBotMap.refbCanPathToEnemyBaseWithLand] and (not(tLZOrWZTeamData[AiBotMap.refbBaseInSafePosition]) or tLZOrWZTeamData[AiBotMap.subrefiActiveMexUpgrades] >= 2) and aiBrain:GetEconomyStored('MASS') >= 40 and iPlateauOrZero > 0 and (aiBrain:GetEconomyStored('MASS') >= 200 or AiBotConditions.WantMoreFactories(iTeam, iPlateauOrZero, iLZOrWZ)) and not(AiBotOverseer.bNoRushActive) and iCurLandFactories + aiBrain:GetCurrentUnits(AiBotUnitInfo.refCategoryAirFactory) < 2 then
                                        --ACUActionBuildFactory(aiBrain, oACU, iPlateauOrZero, iLandOrWaterZone, tLZData, tLZTeamData, iFactoryCategoryOverride, iEngineerActionOverride)
                                        if bDebugMessages == true then LOG(sFunctionRef..': Dont have 2 land facs yet so will get another') end
                                        if bWantAirFactory then
                                            ACUActionBuildFactory(aiBrain, oACU, iPlateauOrZero, iLZOrWZ, tLZOrWZData, tLZOrWZTeamData,     AiBotUnitInfo.refCategoryAirFactory, AiBotEngineer.refActionBuildAirFactory)
                                        else
                                            ACUActionBuildFactory(aiBrain, oACU, iPlateauOrZero, iLZOrWZ, tLZOrWZData, tLZOrWZTeamData,     AiBotUnitInfo.refCategoryLandFactory, AiBotEngineer.refActionBuildLandFactory)
                                        end
                                    elseif aiBrain:GetEconomyStoredRatio('MASS') >= 0.6 and (aiBrain[AiBotEconomy.refiNetMassBaseIncome] > 0.2 or aiBrain:GetEconomyStoredRatio('MASS') >= 0.9) and AiBotConditions.HaveLowPower(iTeam) and aiBrain[AiBotEconomy.refiOurHighestFactoryTechLevel] <= 1 then
                                        if bDebugMessages == true then LOG(sFunctionRef..': Lots of mass stored, low power, and we arent at T2 yet so will build more power') end
                                        ACUActionBuildPower(aiBrain, oACU)
                                        --If lots of reclaim, have some mass, and no energy, then also get power
                                    elseif aiBrain:GetEconomyStored('MASS') >= 60 and aiBrain:GetEconomyStored('ENERGY') < 60 then
                                        if bDebugMessages == true then LOG(sFunctionRef..': Have more mass stored than energy so will get power') end
                                        ACUActionBuildPower(aiBrain, oACU)
                                    else
                                        local iMexInLandZone = 0
                                        if AiBotUtilities.IsTableEmpty(tLZOrWZData[AiBotMap.subrefLZOrWZMexLocations]) == false then iMexInLandZone = table.getn(tLZOrWZData[AiBotMap.subrefLZOrWZMexLocations]) end
                                        if bDebugMessages == true then LOG(sFunctionRef..': Checking if want to build more mexes, iMexInLandZone='..iMexInLandZone..'; Mex count for LZ='..tLZOrWZData[AiBotMap.subrefLZOrWZMexCount]..'; Gross mass='..aiBrain[AiBotEconomy.refiGrossMassBaseIncome]..'; iResourceMod='..iResourceMod..'; Is table of unbuilt mexes empty='..tostring(AiBotUtilities.IsTableEmpty(tLZOrWZData[AiBotMap.subrefMexUnbuiltLocations]))..'; Mex count by tech='..repru(tLZOrWZTeamData[AiBotMap.subrefMexCountByTech])..'; iCurLandFactories='..iCurLandFactories..'; iCurAirFactories='..aiBrain:GetCurrentUnits(AiBotUnitInfo.refCategoryAirFactory)) end
                                        if aiBrain[AiBotEconomy.refiGrossMassBaseIncome] < math.min(5, iMexInLandZone) * 0.2 * iResourceMod and (aiBrain:GetEconomyStoredRatio('MASS') <= 0.9 or aiBrain:GetEconomyStored('MASS') < 100) and AiBotUtilities.IsTableEmpty(tLZOrWZData[AiBotMap.subrefMexUnbuiltLocations]) == false and (not(AiBotOverseer.bNoRushActive) or not(AiBotConditions.NoRushPreventingHydroOrMex(tLZOrWZData, true))) then
                                            ACUActionBuildMex(aiBrain, oACU)
                                            if bDebugMessages == true then LOG(sFunctionRef..': Will try building another mex') end
                                            --Third factory if overflowing mass or have quite a bit stored
                                        elseif iCurLandFactories < 3 and (not(tLZOrWZTeamData[AiBotMap.refbBaseInSafePosition]) or tLZOrWZTeamData[AiBotMap.subrefiActiveMexUpgrades] >= 2) and aiBrain[AiBotMap.refbCanPathToEnemyBaseWithLand] and (AiBotMap.iMapSize <= 512 and (AiBotMap.iMapSize <= 256 or AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiActiveAiBotBrainCount] == 1)) and aiBrain:GetEconomyStored('MASS') >= 250 or (aiBrain:GetEconomyStoredRatio('MASS') >= 0.9 and aiBrain:GetEconomyStored('MASS') >= 100) and iCurLandFactories + aiBrain:GetCurrentUnits(AiBotUnitInfo.refCategoryAirFactory) < 4 and AiBotConditions.WantMoreFactories(iTeam, iPlateauOrZero, iLZOrWZ) then
                                            if bDebugMessages == true then LOG(sFunctionRef..': Will get another factory') end
                                            if bWantAirFactory then
                                                ACUActionBuildFactory(aiBrain, oACU, iPlateauOrZero, iLZOrWZ, tLZOrWZData, tLZOrWZTeamData,     AiBotUnitInfo.refCategoryAirFactory, AiBotEngineer.refActionBuildAirFactory)
                                            else
                                                ACUActionBuildFactory(aiBrain, oACU, iPlateauOrZero, iLZOrWZ, tLZOrWZData, tLZOrWZTeamData,     AiBotUnitInfo.refCategoryLandFactory, AiBotEngineer.refActionBuildLandFactory)
                                            end
                                            --If we are overflowing mass and have a unit upgrading in the zone then assist that instead (e.g. intended for maps where loads of reclaim that causes us to overflow)
                                        else
                                            --Check for (rare) case where enemy ACU is getting near our base
                                            local bAbortLogic = false
                                            if AiBotUtilities.IsTableEmpty(tLZOrWZTeamData[AiBotMap.reftoNearestDFEnemies]) == false and iPlateauOrZero > 0 then
                                                local iApproachingACUThreat = AiBotConditions.GetThreatOfApproachingEnemyACUsAndNearestACU(tLZOrWZData, tLZOrWZTeamData, iPlateauOrZero, iLZOrWZ, iTeam)
                                                if bDebugMessages == true then LOG(sFunctionRef..': iApproachingACUThreat='..iApproachingACUThreat) end
                                                if iApproachingACUThreat >= 600 then
                                                    if AiBotConditions.CloseToEnemyUnit(oACU:GetPosition(), tLZOrWZTeamData[AiBotMap.reftoNearestDFEnemies], 15, iTeam, true, nil, nil, nil, nil, nil) then
                                                        bAbortLogic = true
                                                        oACU[refbDoingInitialBuildOrder] = false
                                                        if bDebugMessages == true then LOG(sFunctionRef..': Are close to enemy DF unit so will attack enemy and end early game order') end
                                                        if AttackNearestEnemyWithACU(iPlateauOrZero, iLZOrWZ, tLZOrWZData, tLZOrWZTeamData, oACU, 90) then
                                                            if bDebugMessages == true then LOG(sFunctionRef..': will attack the nearest enemy') end
                                                        else
                                                            --For some reason we dont want to attack, but will have aborted early game order so this should just be a 1s delay
                                                        end
                                                    elseif ACUActionBuildMex(aiBrain, oACU, 15) then
                                                        if bDebugMessages == true then LOG(sFunctionRef..': Have very close mex we can build so will do that instead while waiting for enemy to get closer') end
                                                    elseif AttackNearestEnemyWithACU(iPlateauOrZero, iLZOrWZ, tLZOrWZData, tLZOrWZTeamData, oACU, 90)  then
                                                        if bDebugMessages == true then LOG(sFunctionRef..': will attack nearest enemy and end early game order') end
                                                        bAbortLogic = true
                                                        oACU[refbDoingInitialBuildOrder] = false
                                                    end
                                                end
                                            end
                                            if not(bAbortLogic) then
                                                local oUnitToAssist
                                                if aiBrain:GetEconomyStoredRatio('MASS') >= 0.9 and aiBrain:GetEconomyStored('MASS') >= 100 and tLZOrWZData[AiBotMap.subrefTotalSignificantMassReclaim] >= 1000 and AiBotUtilities.IsTableEmpty(tLZOrWZTeamData[AiBotMap.subreftoActiveUpgrades]) == false then
                                                    local iHighestFractionComplete = -1
                                                    local oUnitToAssist
                                                    for iUpgrading, oUpgrading in  tLZOrWZTeamData[AiBotMap.subreftoActiveUpgrades] do
                                                        if AiBotUnitInfo.IsUnitValid(oUpgrading) then
                                                            if oUpgrading:GetWorkProgress() < 1 and oUpgrading:GetWorkProgress() > iHighestFractionComplete then
                                                                iHighestFractionComplete = oUpgrading:GetWorkProgress()
                                                                oUnitToAssist = oUpgrading
                                                            end
                                                        end
                                                    end
                                                end
                                                if bDebugMessages == true then LOG(sFunctionRef..': oUnitToAssist='..(oUnitToAssist.UnitId or 'nil')..(AiBotUnitInfo.GetUnitLifetimeCount(oUnitToAssist) or 'nil')) end
                                                if AiBotUnitInfo.IsUnitValid(oUnitToAssist) then
                                                    AiBotOrders.IssueTrackedGuard(oACU, oUnitToAssist, false, 'ACUEGAssist', false)
                                                elseif AiBotUtilities.IsTableEmpty(tLZOrWZData[AiBotMap.subrefMexUnbuiltLocations]) == false and tLZOrWZTeamData[AiBotMap.subrefMexCountByTech][1] + tLZOrWZTeamData[AiBotMap.subrefMexCountByTech][2] + tLZOrWZTeamData[AiBotMap.subrefMexCountByTech][3] < iMexInLandZone and (not(AiBotOverseer.bNoRushActive) or not(AiBotConditions.NoRushPreventingHydroOrMex(tLZOrWZData, true))) then
                                                    --If we have 3+ mexes in the zone, and the unclaimed mex is further from the enemy base than we are notably, then dont build the mex and instead just end the build orde
                                                    local bTryBuildingMex = true
                                                    if tLZOrWZTeamData[AiBotMap.subrefMexCountByTech][1] + tLZOrWZTeamData[AiBotMap.subrefMexCountByTech][2] + tLZOrWZTeamData[AiBotMap.subrefMexCountByTech][3] >= 3 and aiBrain[AiBotMap.refbCanPathToEnemyBaseWithLand] then
                                                        bTryBuildingMex = false
                                                        local iDistToEnemyBaseThreshold = AiBotUtilities.GetDistanceBetweenPositions(oACU:GetPosition(), tLZOrWZTeamData[AiBotMap.reftClosestEnemyBase]) + 20
                                                        local iDistToACUOverrideThreshold = 15
                                                        if tLZOrWZTeamData[AiBotMap.subrefMexCountByTech][1] + tLZOrWZTeamData[AiBotMap.subrefMexCountByTech][2] + tLZOrWZTeamData[AiBotMap.subrefMexCountByTech][3] >= 4 then
                                                            iDistToACUOverrideThreshold = iDistToACUOverrideThreshold + 5
                                                            iDistToEnemyBaseThreshold = iDistToEnemyBaseThreshold - 5
                                                        end
                                                        for iMex, tMex in tLZOrWZData[AiBotMap.subrefMexUnbuiltLocations] do
                                                            if AiBotUtilities.GetDistanceBetweenPositions(tMex, oACU:GetPosition()) <= iDistToACUOverrideThreshold then
                                                                bTryBuildingMex = true
                                                                break --proceed with building mex as it is close to ACU
                                                            elseif AiBotUtilities.GetDistanceBetweenPositions(tMex, tLZOrWZTeamData[AiBotMap.reftClosestEnemyBase]) <= iDistToEnemyBaseThreshold then
                                                                bTryBuildingMex = true
                                                                break
                                                            end
                                                        end
                                                    end
                                                    if bTryBuildingMex then
                                                        ACUActionBuildMex(aiBrain, oACU)
                                                        if bDebugMessages == true then LOG(sFunctionRef..': Will try building more mexes') end
                                                    else
                                                        if bDebugMessages == true then LOG(sFunctionRef..': Building mex means we take a detour so leave it for engineers and end our initial build order') end
                                                        oACU[refbDoingInitialBuildOrder] = false
                                                    end
                                                elseif aiBrain[AiBotEconomy.refiGrossEnergyBaseIncome] < 20 and aiBrain:GetEconomyStoredRatio('ENERGY') < 0.99 and (aiBrain[AiBotEconomy.refiGrossEnergyBaseIncome] < 15 or aiBrain:GetEconomyStoredRatio('MASS') >= 0.1) then
                                                    if bDebugMessages == true then LOG(sFunctionRef..': Will get a bit more power') end
                                                    ACUActionBuildPower(aiBrain, oACU)
                                                else
                                                    --Finish the initial BO
                                                    oACU[refbDoingInitialBuildOrder] = false
                                                    if bDebugMessages == true then LOG(sFunctionRef..': Finishing initial build order') end
                                                end
                                            end
                                        end
                                    end
                                else
                                    --Have the power and factories that we want; if there are mexes in the zone and we have built fewer than 5 then build them; if not then finish initial build order
                                    if AiBotUtilities.IsTableEmpty(tLZOrWZData[AiBotMap.subrefMexUnbuiltLocations]) == false and tLZOrWZTeamData[AiBotMap.subrefMexCountByTech][1] + tLZOrWZTeamData[AiBotMap.subrefMexCountByTech][2] + tLZOrWZTeamData[AiBotMap.subrefMexCountByTech][3] < math.min(5, tLZOrWZData[AiBotMap.subrefLZOrWZMexCount]) and (not(AiBotOverseer.bNoRushActive) or not(AiBotConditions.NoRushPreventingHydroOrMex(tLZOrWZData, true))) then
                                        ACUActionBuildMex(aiBrain, oACU)
                                        if bDebugMessages == true then LOG(sFunctionRef..': Low factory BO Will try building more mexes') end
                                    else
                                        --Finish the initial BO
                                        oACU[refbDoingInitialBuildOrder] = false
                                        if bDebugMessages == true then LOG(sFunctionRef..': Low factory BO Finishing initial build order') end
                                    end
                                end
                            end
                        end
                        --backup in case of unit restrictions (campaign) or e.g. far away mex that we dont want to build
                        if bDebugMessages == true then LOG(sFunctionRef..': Campaign redundancy for if ACU has no order, reprs of last orders='..reprs(oACU[AiBotOrders.reftiLastOrders])..'; oACU[refbDoingInitialBuildOrder]='..tostring(oACU[refbDoingInitialBuildOrder])..'; AiBotMap.bIsCampaignMap='..tostring(AiBotMap.bIsCampaignMap)..'; Is table of last orders empty='..tostring(AiBotUtilities.IsTableEmpty(oACU[AiBotOrders.reftiLastOrders]))) end
                        if not(AiBotConditions.DoesACUHaveValidOrder(oACU)) and oACU[refbDoingInitialBuildOrder] and (AiBotOrders.bDontConsiderCombinedArmy or oACU.AiBotActive) and (not(AiBotMap.bIsLowMexMap) or aiBrain:GetEconomyStoredRatio('MASS') >= 0.95) then
                            --Build mex if any available mex locations in zone
                            if AiBotUtilities.IsTableEmpty(tLZOrWZData[AiBotMap.subrefMexUnbuiltLocations]) == false and (not(AiBotOverseer.bNoRushActive) or not(AiBotConditions.NoRushPreventingHydroOrMex(tLZOrWZData, true))) then
                                ACUActionBuildMex(aiBrain, oACU)
                            end
                            if bDebugMessages == true then LOG(sFunctionRef..': Redundancy - Attempted to build mex if there were any unbuilt locations, IsTableEmpty(tLZOrWZData[AiBotMap.subrefMexUnbuiltLocations])='..tostring(AiBotUtilities.IsTableEmpty(tLZOrWZData[AiBotMap.subrefMexUnbuiltLocations]))..', is table of last orders empty='..tostring(AiBotUtilities.IsTableEmpty(oACU[AiBotOrders.reftiLastOrders]))..'; DoesACUHaveValidOrder(oACU)='..tostring(AiBotConditions.DoesACUHaveValidOrder(oACU))) end
                            if not(AiBotConditions.DoesACUHaveValidOrder(oACU)) then
                                if AiBotUtilities.IsTableEmpty(tLZOrWZData[AiBotMap.subrefHydroLocations]) == false then ACUActionAssistHydro(aiBrain, oACU, tLZOrWZData, tLZOrWZTeamData) end
                                if bDebugMessages == true then LOG(sFunctionRef..': Redundancy - Attempted to assist hydro, is table of last orders empty='..tostring(AiBotUtilities.IsTableEmpty(oACU[AiBotOrders.reftiLastOrders]))..'; DoesACUHaveValidOrder(oACU)='..tostring(AiBotConditions.DoesACUHaveValidOrder(oACU))) end
                                if not(AiBotConditions.DoesACUHaveValidOrder(oACU)) then
                                    local iCurPower =  aiBrain:GetCurrentUnits(AiBotUnitInfo.refCategoryPower) + aiBrain:GetCurrentUnits(AiBotUnitInfo.refCategoryHydro) * 5
                                    if iCurPower <= 7 or (iCurPower <= 13 and aiBrain:GetEconomyStoredRatio('MASS') >= 0.25 and aiBrain:GetEconomyStoredRatio('ENERGY') <= 0.95) then
                                        ACUActionBuildPower(aiBrain, oACU)
                                    end
                                    if bDebugMessages == true then LOG(sFunctionRef..': Redundancy - Attempted to build power, is table of last orders empty='..tostring(AiBotUtilities.IsTableEmpty(oACU[AiBotOrders.reftiLastOrders]))..'; DoesACUHaveValidOrder(oACU)='..tostring(AiBotConditions.DoesACUHaveValidOrder(oACU))..'; Cur factory count='..aiBrain:GetCurrentUnits(AiBotUnitInfo.refCategoryFactory)) end
                                    if not(AiBotConditions.DoesACUHaveValidOrder(oACU)) then

                                        if aiBrain:GetCurrentUnits(AiBotUnitInfo.refCategoryFactory) < 3 then
                                            if aiBrain:GetEconomyStoredRatio('MASS') >= 0.2 and aiBrain:GetEconomyStoredRatio('ENERGY') >= 0.8 then
                                                ACUActionBuildFactory(aiBrain, oACU, iPlateauOrZero, iLZOrWZ, tLZOrWZData, tLZOrWZTeamData, AiBotUnitInfo.refCategoryLandFactory, AiBotEngineer.refActionBuildLandFactory)
                                                if bDebugMessages == true then LOG(sFunctionRef..': Redundancy - Attempted to build land factory, is table of last orders empty='..tostring(AiBotUtilities.IsTableEmpty(oACU[AiBotOrders.reftiLastOrders]))..'; DoesACUHaveValidOrder(oACU)='..tostring(AiBotConditions.DoesACUHaveValidOrder(oACU))) end
                                                if not(AiBotConditions.DoesACUHaveValidOrder(oACU)) and (AiBotOrders.bDontConsiderCombinedArmy or oACU.AiBotActive) then
                                                    ACUActionBuildFactory(aiBrain, oACU, iPlateauOrZero, iLZOrWZ, tLZOrWZData, tLZOrWZTeamData, AiBotUnitInfo.refCategoryAirFactory, AiBotEngineer.refActionBuildAirFactory)
                                                    if bDebugMessages == true then LOG(sFunctionRef..': Redundancy - Attempted to build air factory, is table of last orders empty='..tostring(AiBotUtilities.IsTableEmpty(oACU[AiBotOrders.reftiLastOrders]))..'; DoesACUHaveValidOrder(oACU)='..tostring(AiBotConditions.DoesACUHaveValidOrder(oACU))) end
                                                    if not(AiBotConditions.DoesACUHaveValidOrder(oACU)) then
                                                        if iPlateauOrZero == 0 then
                                                            ACUActionBuildFactory(aiBrain, oACU, iPlateauOrZero, iLZOrWZ, tLZOrWZData, tLZOrWZTeamData, AiBotUnitInfo.refCategoryNavalFactory, AiBotEngineer.refActionBuildNavalFactory)
                                                        end
                                                        if bDebugMessages == true then LOG(sFunctionRef..': Redundancy - Attempted to build naval factory if we are in water, iPlateauorZero='..iPlateauOrZero..'; is table of last orders empty='..tostring(AiBotUtilities.IsTableEmpty(oACU[AiBotOrders.reftiLastOrders]))..'; DoesACUHaveValidOrder(oACU)='..tostring(AiBotConditions.DoesACUHaveValidOrder(oACU))) end
                                                        if not(AiBotConditions.DoesACUHaveValidOrder(oACU)) then
                                                            --Are we capable of building a naval factory yet?
                                                            --GetBlueprintThatCanBuildOfCategory(aiBrain, iCategoryCondition,               oFactory, bGetSlowest, bGetFastest, bGetCheapest, iOptionalCategoryThatMustBeAbleToBuild, bIgnoreTechDifferences)
                                                            local sNavalFacBP = AiBotFactory.GetBlueprintThatCanBuildOfCategory(aiBrain, AiBotUnitInfo.refCategoryNavalFactory, oACU)
                                                            if bDebugMessages == true then LOG(sFunctionRef..': Checking if it is possible for us to build a naval factory, sNavalFacBP='..(sNavalFacBP or 'nil')) end
                                                            if sNavalFacBP then

                                                                --Do we have an adjacent water zone? If so then move here as might be Aeon M1 where can only build naval fac)
                                                                if iPlateauOrZero > 0 and AiBotUtilities.IsTableEmpty(tLZOrWZData[AiBotMap.subrefAdjacentWaterZones]) == false then
                                                                    MoveACUToNearbyWaterForFactory(aiBrain, oACU, tLZOrWZData)

                                                                else
                                                                    AiBotUtilities.ErrorHandler('Unable to get any action for ACU owned by brain '..aiBrain.Nickname)
                                                                end
                                                            else
                                                                --Campaign specific - might have strange restrictions early game, so hide this message initially
                                                                if not(AiBotMap.bIsCampaignMap) or GetGameTimeSeconds() >= 300 then
                                                                    AiBotUtilities.ErrorHandler('Unable to get early game action for ACU')
                                                                end
                                                            end
                                                        end
                                                    end
                                                end
                                            end
                                        end
                                    end
                                end
                            end
                        end
                    else
                        --ACU is underwater so presumably water based start position

                        if (iLZOrWZ or 0) == 0 then

                            --Go to the midpoint of the nearest zone that can find
                            --Move to midpoint
                            AiBotOrders.IssueTrackedMove(oACU, tLZOrWZData[AiBotMap.subrefMidpoint], 1, false, 'FindValidLoc', false)
                            AiBotUtilities.ErrorHandler('ACU showing as not being on a land zone, but doesnt have a water zone either, will try moving to midpoint of nearest land or water zone')
                        else
                            oACU[refbStartedUnderwater] = true
                            --Are in a water zone - build a naval fac and build on any unbuilt mexes before marking initial BO as being  complete
                            local iCurNavalFactories = aiBrain:GetCurrentUnits(AiBotUnitInfo.refCategoryNavalFactory)
                            if bDebugMessages == true then LOG(sFunctionRef..': iCurNavalFactories='..iCurNavalFactories..'; Is table of unbuilt mex locations empty='..tostring(AiBotUtilities.IsTableEmpty(tLZOrWZData[AiBotMap.subrefMexUnbuiltLocations]))..'; Gross mass income='..aiBrain[AiBotEconomy.refiGrossMassBaseIncome]..'; Gross energy income='..aiBrain[AiBotEconomy.refiGrossEnergyBaseIncome]..'; Is table of hydro locations empty='..tostring(AiBotUtilities.IsTableEmpty(tLZOrWZData[AiBotMap.subrefHydroLocations]))) end
                            if iCurNavalFactories == 0 then
                                if bDebugMessages == true then LOG(sFunctionRef..': Want ACU to build land factory') end
                                ACUActionBuildFactory(aiBrain, oACU, iPlateauOrZero, iLZOrWZ, tLZOrWZData, tLZOrWZTeamData, AiBotUnitInfo.refCategoryNavalFactory, AiBotEngineer.refActionBuildNavalFactory)
                            else
                                --Build mexes if nearby assuming we have nearby hydr; assist hydro if we have hydro
                                if AiBotUtilities.IsTableEmpty(tLZOrWZData[AiBotMap.subrefMexUnbuiltLocations]) == false and (aiBrain[AiBotEconomy.refiGrossMassBaseIncome] < 0.8 * iResourceMod or aiBrain[AiBotEconomy.refiGrossEnergyBaseIncome] > 10 * iResourceMod) and (not(AiBotOverseer.bNoRushActive) or not(AiBotConditions.NoRushPreventingHydroOrMex(tLZOrWZData, true))) then
                                    if bDebugMessages == true then LOG(sFunctionRef..': We have unbuilt mexes in water zone and our income seems less than 4 mex equiv, so will build mexes') end
                                    ACUActionBuildMex(aiBrain, oACU)
                                elseif AiBotUtilities.IsTableEmpty(tLZOrWZData[AiBotMap.subrefHydroLocations]) == false and aiBrain[AiBotEconomy.refiGrossEnergyBaseIncome] < 10 * iResourceMod then
                                    if bDebugMessages == true then LOG(sFunctionRef..': Will try to assist a hydro nearby') end
                                    ACUActionAssistHydro(aiBrain, oACU, tLZOrWZData, tLZOrWZTeamData)
                                elseif AiBotUtilities.IsTableEmpty(tLZOrWZData[AiBotMap.subrefMexUnbuiltLocations]) == false and (not(AiBotOverseer.bNoRushActive) or not(AiBotConditions.NoRushPreventingHydroOrMex(tLZOrWZData, true))) then
                                    ACUActionBuildMex(aiBrain, oACU)
                                else
                                    oACU[refbDoingInitialBuildOrder] = false
                                end
                            end
                        end

                    end
                end
            else
                --Rare case where ACU and engieners start building pgen at the same time, leading to them both building separately to each other; solution - if ACU fraction complete is <10%, switch to the engi built one if it is in the build range
                local oACUFocusUnit = oACU:GetFocusUnit()
                if bDebugMessages == true then LOG(sFunctionRef..': Are building so wont give any new orders subject to Pgen execption and reclaiming wreck mass exception. is oACUFocusUnit valid='..tostring(AiBotUnitInfo.IsUnitValid(oACUFocusUnit)))
                    if AiBotUnitInfo.IsUnitValid(oACUFocusUnit) then LOG(sFunctionRef..': Focus unit='..oACUFocusUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oACUFocusUnit)..'; Fraction complete='..oACUFocusUnit:GetFractionComplete()..'; ACU work progress='..oACU:GetWorkProgress()) end
                end
                if oNearestEnemy and (not(AiBotUnitInfo.IsUnitValid(oACUFocusUnit)) or oACU:GetWorkProgress() >= 0.8) then --Attack enemy that is almost in range of us
                    if bDebugMessages == true then LOG(sFunctionRef..': Will ahve ACU attack nearby enemy instead') end
                    if AttackNearestEnemyWithACU(iPlateauOrZero, iLZOrWZ, tLZOrWZData, tLZOrWZTeamData, oACU, math.max(10, iClosestEnemyLessRangeDist + oNearestEnemy[AiBotUnitInfo.refiCombatRange])) then
                        if bDebugMessages == true then LOG(sFunctionRef..': Attacking enemy with normal logic') end
                    elseif (not bDualGapAirHomeOnly or tLZOrWZTeamData[AiBotMap.subrefLZbCoreBase]) and oACU[AiBotUnitInfo.refbLastShotBlocked] then
                        AiBotOrders.IssueTrackedMove(oACU, oNearestEnemy:GetPosition(), 5, false, 'EarlyEnBlM', false)
                    elseif not bDualGapAirHomeOnly or tLZOrWZTeamData[AiBotMap.subrefLZbCoreBase] then
                        AiBotOrders.IssueTrackedAttackMove(oACU, oNearestEnemy:GetPosition(), 5, false, 'EarlyEnAM', false)
                    end
                else
                    local iPlateauOrPond = iPlateauOrZero
                    if iPlateauOrPond == 0 then iPlateauOrPond = AiBotMap.tiPondByWaterZone[iLZOrWZ] end

                    --If about to overflow mass, dont have a valid unit being built, and we have at least 1 factory in the zone, then build power or do nothing
                    if not(AiBotUnitInfo.IsUnitValid(oACUFocusUnit)) and aiBrain:GetEconomyStoredRatio('MASS') >= 0.95 and AiBotUtilities.IsTableEmpty(tLZOrWZTeamData[AiBotMap.subreftoLZOrWZAlliedUnits]) == false and AiBotUtilities.IsTableEmpty(EntityCategoryFilterDown(AiBotUnitInfo.refCategoryFactory, tLZOrWZTeamData[AiBotMap.subreftoLZOrWZAlliedUnits])) == false then
                        --Are overflowing mass presumably from trying to build on a wreck - either build power or (if we have lots of power) clear orders
                        if bDebugMessages == true then LOG(sFunctionRef..': Will try either clearing commands or building power') end
                        if aiBrain[AiBotEconomy.refiGrossEnergyBaseIncome] >= 80 then
                            AiBotOrders.IssueTrackedClearCommands(oACU)
                        else
                            --Is there an under construction hydro in this zone? if so assist it, otherwise build a pgen
                            local bHaveUnderConstructionFirstHydro = false
                            local oOptionalUnderConstructionHydro
                            local tHydroInZone = EntityCategoryFilterDown(AiBotUnitInfo.refCategoryHydro, tLZOrWZTeamData[AiBotMap.subreftoLZOrWZAlliedUnits])
                            if AiBotUtilities.IsTableEmpty(tHydroInZone) == false then
                                for iHydro, oHydro in tHydroInZone do
                                    if oHydro:GetFractionComplete() < 1 and oHydro:GetAIBrain() == aiBrain then
                                        bHaveUnderConstructionFirstHydro = true
                                        oOptionalUnderConstructionHydro = oHydro
                                        break
                                    end
                                end
                            end
                            if bHaveUnderConstructionFirstHydro then
                                if bDebugMessages == true then LOG(sFunctionRef..': Want to assist hydro') end
                                ACUActionAssistHydro(aiBrain, oACU, tLZOrWZData, tLZOrWZTeamData, oOptionalUnderConstructionHydro)
                            else
                                ACUActionBuildPower(aiBrain, oACU)
                                if bDebugMessages == true then LOG(sFunctionRef..': Want to build power') end
                            end
                        end
                        --Stalling mass and wreck in our build range - reclaim it
                    elseif aiBrain:GetEconomyStored('MASS') <= 5 and oACU:GetWorkProgress() < 0.9 and (tLZOrWZData[AiBotMap.subrefTotalSignificantMassReclaim] or 0) >= 40 and AiBotEngineer.GetEngineerToReclaimNearbyArea(oACU, 1, tLZOrWZTeamData, iPlateauOrPond, iLZOrWZ, false, true, 15, iPlateauOrZero == 0, true) then
                        if bDebugMessages == true then LOG(sFunctionRef..': Stalling mass so switching to get reclaim') end

                    elseif EntityCategoryContains(AiBotUnitInfo.refCategoryPower * categories.TECH1, oACUFocusUnit.UnitId) and aiBrain:GetEconomyStored('ENERGY') < 1500 and oACUFocusUnit:GetFractionComplete() < 0.1 then
                        local tNearbyPower = aiBrain:GetUnitsAroundPoint(AiBotUnitInfo.refCategoryPower * categories.TECH1, oACU:GetPosition(), oACU:GetBlueprint().Economy.MaxBuildDistance + AiBotUnitInfo.GetBuildingSize(oACUFocusUnit.UnitId), 'Ally')
                        if bDebugMessages == true then LOG(sFunctionRef..': Is table of nearby power empty='..tostring(AiBotUtilities.IsTableEmpty(tNearbyPower))) end
                        if AiBotUtilities.IsTableEmpty(tNearbyPower) == false and table.getn(tNearbyPower) >= 2 then
                            local tEngineers = EntityCategoryFilterDown(AiBotUnitInfo.refCategoryEngineer, tLZOrWZTeamData[AiBotMap.subreftoLZOrWZAlliedUnits])
                            local tPowerBuiltByEngineers = {}
                            local oCurFocusUnit
                            if AiBotUtilities.IsTableEmpty(tEngineers) == false then
                                for iEngineer, oEngineer in tEngineers do
                                    if AiBotUnitInfo.IsUnitValid(oEngineer) and oEngineer[AiBotEngineer.refiAssignedAction] == AiBotEngineer.refActionBuildPower then
                                        oCurFocusUnit = oEngineer:GetFocusUnit()
                                        if EntityCategoryContains(AiBotUnitInfo.refCategoryPower * categories.TECH1, oCurFocusUnit.UnitId) then
                                            table.insert(tPowerBuiltByEngineers, oCurFocusUnit)
                                        end
                                    end
                                end
                            end
                            if bDebugMessages == true then LOG(sFunctionRef..': is table of power built by engineers empty='..tostring(AiBotUtilities.IsTableEmpty(tPowerBuiltByEngineers))) end
                            if AiBotUtilities.IsTableEmpty(tPowerBuiltByEngineers) == false then
                                --Do we have any engineers building the ACU focus unit?
                                local bEngineersBuildingACUPower = false
                                for iUnit, oUnit in tPowerBuiltByEngineers do
                                    if oUnit == oACUFocusUnit then bEngineersBuildingACUPower = true break end
                                end
                                if not(bEngineersBuildingACUPower) then
                                    local bHaveEngineersBuildingThisPower
                                    local iMostCompletePower = 0
                                    local oPowerToSwitchTo
                                    for iUnit, oUnit in tNearbyPower do
                                        if not(oUnit == oACUFocusUnit) then
                                            --Do we have engineers building this power?
                                            bHaveEngineersBuildingThisPower = false
                                            for iPower, oPower in tPowerBuiltByEngineers do
                                                if oPower == oUnit then
                                                    bHaveEngineersBuildingThisPower = true
                                                    break
                                                end
                                            end
                                            if bHaveEngineersBuildingThisPower then
                                                if oUnit:GetFractionComplete() > iMostCompletePower then
                                                    iMostCompletePower = oUnit:GetFractionComplete()
                                                    oPowerToSwitchTo = oUnit
                                                end
                                            end
                                        end
                                    end
                                    if oPowerToSwitchTo then
                                        AiBotOrders.IssueTrackedRepair(oACU, oPowerToSwitchTo, false, 'EGPwrR', false)
                                    end
                                end
                            end
                        end
                        --Hydro and power-stalling and tree reclaim within build area - reclaim trees
                    elseif aiBrain:GetEconomyStored('ENERGY') <= 30 and aiBrain[AiBotEconomy.refiGrossEnergyBaseIncome] < 10 then
                        local iReclaimSegmentX, iReclaimSegmentZ = AiBotMap.GetReclaimSegmentsFromLocation(oACU:GetPosition())
                        if bDebugMessages == true then LOG(sFunctionRef..': Are power stalling, will see if energy reclaim nearby, energy in segment are in='..(AiBotMap.tReclaimAreas[iReclaimSegmentX][iReclaimSegmentZ][AiBotMap.refSegmentReclaimTotalEnergy] or 'nil')) end
                        if (AiBotMap.tReclaimAreas[iReclaimSegmentX][iReclaimSegmentZ][AiBotMap.refSegmentReclaimTotalEnergy] or 0) > 10 then
                            local iBuildRange = oACU:GetBlueprint().Economy.MaxBuildDistance
                            local rNearbyRect = AiBotUtilities.GetRectAroundLocation(oACU:GetPosition(), iBuildRange)
                            local tReclaimables = AiBotMap.GetReclaimInRectangle(4, rNearbyRect, false)
                            if AiBotUtilities.IsTableEmpty(tReclaimables) == false then
                                local tWrecksToReclaim = {}
                                for iWreck, oWreck in tReclaimables do
                                    if (oWreck.MaxEnergyReclaim or 0) >= 10 and AiBotUtilities.GetDistanceBetweenPositions(oACU:GetPosition(), oWreck.CachePosition) <= iBuildRange then
                                        table.insert(tWrecksToReclaim, oWreck)
                                    end
                                end
                                if AiBotUtilities.IsTableEmpty(tWrecksToReclaim) == false then
                                    AiBotOrders.IssueTrackedClearCommands(oACU)
                                    for iWreck, oWreck in tWrecksToReclaim do
                                        AiBotOrders.IssueTrackedReclaim(oACU, oWreck, true, 'ACUTree', false)
                                    end
                                end
                            end
                        end
                    end
                end
            end
        end
    end
    if bDebugMessages == true then LOG(sFunctionRef..': End of code, is ACU table of last orders empty='..tostring(AiBotUtilities.IsTableEmpty(oACU[AiBotOrders.reftiLastOrders]))..'; Does ACU have valid order='..tostring(AiBotConditions.DoesACUHaveValidOrder(oACU))) end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
end

function RemovePreferredUpgradesThatWeAlreadyHave(oACU, oBP)
    local sFunctionRef = 'RemovePreferredUpgradesThatWeAlreadyHave'
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)

    if AiBotUtilities.IsTableEmpty(oACU[reftPreferredUpgrades]) == false and oACU.HasEnhancement then
        local tObsoletePreRequisites = {}
        local bCheckForObsoletePrerequisites
        if bDebugMessages == true then
            LOG(sFunctionRef .. ': Considering upgrades already have for oACU ' .. oACU.UnitId .. AiBotUnitInfo.GetUnitLifetimeCount(oACU) .. ' owned by ' .. oACU:GetAIBrain().Nickname .. '; Upgrade count=' .. (oACU[refiUpgradeCount] or 'nil'))
        end
        if (oACU[refiUpgradeCount] or 0) > 0 then
            for iEntry, sEnhancement in oACU[reftPreferredUpgrades] do
                if oBP.Enhancements[sEnhancement].Prerequisite and oACU:HasEnhancement(sEnhancement) then
                    table.insert(tObsoletePreRequisites, oBP.Enhancements[sEnhancement].Prerequisite)
                    bCheckForObsoletePrerequisites = true
                    --Check for double-prerequisite
                    if oBP.Enhancements[oBP.Enhancements[sEnhancement].Prerequisite].Prerequisite then
                        table.insert(tObsoletePreRequisites, oBP.Enhancements[oBP.Enhancements[sEnhancement].Prerequisite].Prerequisite)
                    end
                end
                if bDebugMessages == true then
                    LOG(sFunctionRef .. ': Considering if sEnhancement ' .. sEnhancement .. ' has prerequisite, BP Preq val=' .. (oBP.Enhancements[sEnhancement].Prerequisite or 'nil')..'; bCheckForObsoletePrerequisites='..tostring(bCheckForObsoletePrerequisites)..'; tObsoletePreRequisites='..repru(tObsoletePreRequisites))
                end
            end
        end
        local bUpgradeIsObsolete

        local iRevisedIndex = 0
        local iTableSize = table.getn(oACU[reftPreferredUpgrades])

        --First check if we have any upgrades that have prerequiites, in which case we want to remove those prerequisites first
        for iOrigIndex = 1, iTableSize do
            if oACU[reftPreferredUpgrades][iOrigIndex] then
                if bDebugMessages == true then LOG(sFunctionRef..': Considering if the upgrade index '..iOrigIndex..' which is '..repru(oACU[reftPreferredUpgrades][iOrigIndex])..' is obsolete; Does ACU have this enhancement='..tostring(oACU:HasEnhancement(oACU[reftPreferredUpgrades][iOrigIndex]))..'; bCheckForObsoletePrerequisites='..tostring(bCheckForObsoletePrerequisites)..'; oACU[AiBotUnitInfo.reftiTimeOfLastEnhancementComplete]='..repru((oACU[AiBotUnitInfo.reftiTimeOfLastEnhancementComplete] or 'nil'))..'; oACU[AiBotUnitInfo.reftiTimeOfLastEnhancementComplete][oACU[reftPreferredUpgrades[iOrigIndex]]]='..(oACU[AiBotUnitInfo.reftiTimeOfLastEnhancementComplete][oACU[reftPreferredUpgrades[iOrigIndex]]] or 'nil')..'; Time='..GetGameTimeSeconds()) end
                if not (oACU:HasEnhancement(oACU[reftPreferredUpgrades][iOrigIndex])) and (not (oACU[AiBotUnitInfo.reftiTimeOfLastEnhancementComplete][oACU[reftPreferredUpgrades[iOrigIndex]]]) or GetGameTimeSeconds() - (oACU[AiBotUnitInfo.reftiTimeOfLastEnhancementComplete][oACU[reftPreferredUpgrades[iOrigIndex]]] or -1) >= 0.5) then
                    --I.e. this should run the logic to decide whether we want to keep this entry of the table or remove it
                    --We dont have this enhancement; however we might have one that supercedes this, in which case also want to remove it
                    bUpgradeIsObsolete = false
                    if bCheckForObsoletePrerequisites then
                        for iEntry, sPreRequisite in tObsoletePreRequisites do
                            if bDebugMessages == true then LOG(sFunctionRef..': Considering sPreRequisite='..sPreRequisite..'; If this equals this upgrade then will mark it as obsolete') end
                            if sPreRequisite == oACU[reftPreferredUpgrades][iOrigIndex] then
                                bUpgradeIsObsolete = true
                                break
                            end
                        end
                    end
                    if bUpgradeIsObsolete then
                        if bDebugMessages == true then LOG(sFunctionRef..': Upgrade is obsolete so will clear '..oACU[reftPreferredUpgrades][iOrigIndex]..'; iOrigIndex='..iOrigIndex..'; iRevisedIndex='..iRevisedIndex) end
                        oACU[reftPreferredUpgrades][iOrigIndex] = nil;
                    else

                        --We want to keep the entry; Move the original index to be the revised index number (so if e.g. a table of 1,2,3 removed 2, then this would've resulted in the revised index being 2 (i.e. it starts at 1, then icnreases by 1 for the first valid entry); this then means we change the table index for orig index 3 to be 2
                        iRevisedIndex = iRevisedIndex + 1; --i.e. this will be the position of where the next value that we keep will be located
                        if (iOrigIndex ~= iRevisedIndex) then
                            if bDebugMessages == true then LOG(sFunctionRef..': setting iRevisedIndex '..iRevisedIndex..' to equal '..oACU[reftPreferredUpgrades][iOrigIndex]) end
                            oACU[reftPreferredUpgrades][iRevisedIndex] = oACU[reftPreferredUpgrades][iOrigIndex];
                            oACU[reftPreferredUpgrades][iOrigIndex] = nil;
                        end
                        if bDebugMessages == true then LOG(sFunctionRef..': We dont have this upgrade yet so will retain it') end
                    end
                else
                    if bDebugMessages == true then LOG(sFunctionRef..': Clearing the upgrade '..oACU[reftPreferredUpgrades][iOrigIndex]) end
                    oACU[reftPreferredUpgrades][iOrigIndex] = nil;
                end
            end
        end
        iTableSize = table.getn(oACU[reftPreferredUpgrades])
        if bDebugMessages == true then LOG(sFunctionRef..': End of removal, iRevisedIndex='..iRevisedIndex..'; iTableSize='..iTableSize..'; repru='..repru(oACU[reftPreferredUpgrades])..'; Entry 1 of table='..(oACU[reftPreferredUpgrades][1] or 'nil')) end
        if iRevisedIndex < iTableSize then
            if iRevisedIndex == 0 then oACU[reftPreferredUpgrades] = {}
            elseif iRevisedIndex == 1 then
                --redundancy (had issue where doing table.remove results in the last entry with a value being removed, i think it was due to separate error with not refreshing iTableSize, but adding this to be safe)
                oACU[reftPreferredUpgrades] = {[1] = oACU[reftPreferredUpgrades][1]}
            else
                --table.setn(oACU[reftPreferredUpgrades], iRevisedIndex - 1)
                for iRemovalEntry = iTableSize, (iRevisedIndex + 1), -1 do
                    if bDebugMessages == true then LOG(sFunctionRef..': About to remove entry '..(iRemovalEntry or 'nil')..' with value='..(oACU[reftPreferredUpgrades][iRemovalEntry] or 'nil')) end
                    table.remove(oACU[reftPreferredUpgrades], iRemovalEntry)
                    if bDebugMessages == true then LOG(sFunctionRef..': repr of table after removal='..repru(oACU[reftPreferredUpgrades])) end
                end
            end
        end
    end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
end

function GetUpgradePathForACU(oACU, bWantToDoTeleSnipe)
    --Records the order of upgrades we will want for the ACU
    local sFunctionRef = 'GetUpgradePathForACU'
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)



    local aiBrain = oACU:GetAIBrain()

    if bDebugMessages == true then LOG(sFunctionRef..': Time='..GetGameTimeSeconds()..'; oACU='..oACU.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oACU)..' owned by brain '..aiBrain.Nickname..'; oACU[refbStartedUnderwater]='..tostring(oACU[refbStartedUnderwater] or false)..'; oACU[refiUpgradeCount='..oACU[refiUpgradeCount]..'; aiBrain[AiBotEconomy.refiGrossEnergyBaseIncome]='..aiBrain[AiBotEconomy.refiGrossEnergyBaseIncome]..'; aiBrain[AiBotEconomy.refiGrossMassBaseIncome]='..aiBrain[AiBotEconomy.refiGrossMassBaseIncome]..'; Is aeon or cybran='..tostring(EntityCategoryContains(categories.AEON + categories.CYBRAN, oACU.UnitId))..'; aiBrain[AiBotEconomy.refiBrainResourceMultiplier]='..aiBrain[AiBotEconomy.refiBrainResourceMultiplier]..'; bWantToDoTeleSnipe='..tostring(bWantToDoTeleSnipe or false)..'; oACU[refbPlanningToGetTeleport]='..tostring(oACU[refbPlanningToGetTeleport] or false)..'; aiBrain[refbPlanningToGetShield]='..tostring(aiBrain[refbPlanningToGetShield] or false)) end
    local oBP = oACU:GetBlueprint()

    oACU[refiTimeLastConsideredUpgradePath] = GetGameTimeSeconds()
    if (bWantToDoTeleSnipe or (oACU[refbPlanningToGetTeleport] and (oACU:HasEnhancement('MicrowaveLaserGenerator') or oACU:HasEnhancement('Teleporter') or oACU:HasEnhancement('BlastAttack')))) and oBP.Enhancements['Teleporter'] then
        if EntityCategoryContains(categories.CYBRAN, oACU.UnitId) then
            oACU[reftPreferredUpgrades] = {'CoolingUpgrade', 'MicrowaveLaserGenerator', 'Teleporter'}
        elseif EntityCategoryContains(categories.SERAPHIM, oACU.UnitId) then
            oACU[reftPreferredUpgrades] = {'RateOfFire', 'BlastAttack', 'Teleporter'}
        else AiBotUtilities.ErrorHandler('Trying to do telesnipe without a cybran or seraphim ACU')
        end
        --Unusually cheap upgrades - get the best possible ones available
    elseif oBP.Enhancements.AdvancedEngineering.BuildCostMass <= 10 and oBP.Enhancements.ResourceAllocation.BuildCostMass <= 10 then
        if EntityCategoryContains(categories.UEF, oACU.UnitId) then
            oACU[reftPreferredUpgrades] = {'AdvancedEngineering', 'T3Engineering', 'ResourceAllocation', 'Shield'}
        elseif EntityCategoryContains(categories.AEON, oACU.UnitId) then
            oACU[reftPreferredUpgrades] = {'AdvancedEngineering', 'T3Engineering', 'ResourceAllocation', 'ResourceAllocationAdvanced', 'HeatSink'}
        elseif EntityCategoryContains(categories.CYBRAN, oACU.UnitId) then
            oACU[reftPreferredUpgrades] = {'AdvancedEngineering', 'T3Engineering', 'ResourceAllocation'}
            --Mod that makes upgrades cost nothing
            if (oBP.Enhancements['MicrowaveLaserGenerator'].BuildCostMass or 10000) <= 1000 then
                table.insert(oACU[reftPreferredUpgrades], 'MicrowaveLaserGenerator')
                if (oBP.Enhancements['MicrowaveLaserGenerator'].BuildCostMass or 10000) <= 100 and oBP.Enhancements['T3Engineering'].BuildCostMass <= 100 then
                    if GetGameTimeSeconds() <= 120 or (aiBrain[AiBotEconomy.refiGrossEnergyBaseIncome] <= 500 and AiBotTeam.tTeamData[aiBrain.AiBotTeam][AiBotTeam.subrefiTeamGrossEnergy] <= 750 and oACU:HasEnhancement('ResourceAllocationAdvanced')) then
                        oACU[reftPreferredUpgrades] = {'AdvancedEngineering', 'T3Engineering', 'ResourceAllocation', 'MicrowaveLaserGenerator'}
                    elseif GetGameTimeSeconds() <= 900 and AiBotTeam.tTeamData[aiBrain.AiBotTeam][AiBotTeam.refiConstructedExperimentalCount] == 0 and not(AiBotTeam.tTeamData[aiBrain.AiBotTeam][AiBotTeam.refbAssassinationOrSimilar]) and AiBotTeam.tTeamData[aiBrain.AiBotTeam][AiBotTeam.subrefiTeamGrossEnergy] >= 750 and oBP.Enhancements['FAF_SelfRepairSystem'] then
                        oACU[reftPreferredUpgrades] = {'CoolingUpgrade', 'StealthGenerator', 'FAF_SelfRepairSystem', 'MicrowaveLaserGenerator', 'CloakingGenerator'}
                    else
                        oACU[reftPreferredUpgrades] = {'AdvancedEngineering', 'T3Engineering', 'ResourceAllocation', 'MicrowaveLaserGenerator'}
                    end
                end
            end
        elseif EntityCategoryContains(categories.SERAPHIM, oACU.UnitId) then
            --Mod that makes upgrades cost nothing
            if (oBP.Enhancements['BlastAttack'].BuildCostMass or 10000) <= 100 and oBP.Enhancements['T3Engineering'].BuildCostMass <= 100 then
                --Cant have T3 and splash, so want to adjust depending on what stage of the game we are at
                if GetGameTimeSeconds() <= 120 or (aiBrain[AiBotEconomy.refiGrossEnergyBaseIncome] <= 500 and AiBotTeam.tTeamData[aiBrain.AiBotTeam][AiBotTeam.subrefiTeamGrossEnergy] <= 750 and oACU:HasEnhancement('ResourceAllocationAdvanced')) then
                    oACU[reftPreferredUpgrades] = {'AdvancedEngineering', 'T3Engineering','ResourceAllocation', 'ResourceAllocationAdvanced', 'DamageStabilization', 'DamageStabilizationAdvanced'}
                elseif GetGameTimeSeconds() <= 900 and AiBotTeam.tTeamData[aiBrain.AiBotTeam][AiBotTeam.refiConstructedExperimentalCount] == 0 and not(AiBotTeam.tTeamData[aiBrain.AiBotTeam][AiBotTeam.refbAssassinationOrSimilar]) then
                    --Wnat to use ACU more aggressively so get splash and gun (range+ROF) instead of RAS
                    oACU[reftPreferredUpgrades] = {'RateOfFire', 'BlastAttack', 'DamageStabilization', 'DamageStabilizationAdvanced'}
                else
                    oACU[reftPreferredUpgrades] = {'ResourceAllocation', 'ResourceAllocationAdvanced', 'BlastAttack', 'DamageStabilization', 'DamageStabilizationAdvanced'}
                end
            else
                oACU[reftPreferredUpgrades] = {'AdvancedEngineering', 'T3Engineering', 'ResourceAllocation', 'ResourceAllocationAdvanced', 'DamageStabilization', 'DamageStabilizationAdvanced'}
            end
        end
        --oACU[refiUpgradeCount] == 0 and (oBP.Enhancements.ResourceAllocation.BuildCostMass or 10000) <= 100 and GetGameTimeSeconds() <= 60 and not(oACU[reftPreferredUpgrades][1] == 'ResourceAllocation') then
    elseif aiBrain[AiBotEconomy.refiBrainResourceMultiplier] >= 1.7 and (AiBotMap.iMapSize >= 1000 or aiBrain[AiBotEconomy.refiBrainResourceMultiplier] >= 4.0) then
        if EntityCategoryContains(categories.UEF, oACU.UnitId) then
            if AiBotTeam.tTeamData[aiBrain.AiBotTeam][AiBotTeam.refbAssassinationOrSimilar] then
                oACU[reftPreferredUpgrades] = {'AdvancedEngineering', 'Shield', 'T3Engineering', 'ResourceAllocation'}
            else
                oACU[reftPreferredUpgrades] = {'AdvancedEngineering', 'T3Engineering', 'ResourceAllocation', 'Shield'}
            end
        elseif EntityCategoryContains(categories.AEON, oACU.UnitId) then
            oACU[reftPreferredUpgrades] = {'AdvancedEngineering', 'T3Engineering', 'ResourceAllocation', 'ResourceAllocationAdvanced'}
        elseif EntityCategoryContains(categories.CYBRAN, oACU.UnitId) then
            oACU[reftPreferredUpgrades] = {'AdvancedEngineering', 'T3Engineering', 'ResourceAllocation'}
            --Mod that makes upgrades cost nothing
            if (oBP.Enhancements['MicrowaveLaserGenerator'].BuildCostMass or 10000) <= 1000 then table.insert(oACU[reftPreferredUpgrades], 'MicrowaveLaserGenerator') end
        elseif EntityCategoryContains(categories.SERAPHIM, oACU.UnitId) then
            --Mod that makes upgrades cost nothing
            if (oBP.Enhancements['BlastAttack'].BuildCostMass or 10000) <= 1000 then
                oACU[reftPreferredUpgrades] = {'BlastAttack', 'DamageStabilization', 'ResourceAllocation', 'ResourceAllocationAdvanced', 'DamageStabilizationAdvanced'}
            elseif AiBotTeam.tTeamData[aiBrain.AiBotTeam][AiBotTeam.refbAssassinationOrSimilar] then
                oACU[reftPreferredUpgrades] = {'AdvancedEngineering', 'DamageStabilization', 'T3Engineering', 'ResourceAllocation', 'ResourceAllocationAdvanced', 'DamageStabilizationAdvanced'}
            else
                oACU[reftPreferredUpgrades] = {'AdvancedEngineering', 'T3Engineering', 'ResourceAllocation', 'ResourceAllocationAdvanced', 'DamageStabilization', 'DamageStabilizationAdvanced'}
            end
        end
    elseif oACU[refbStartedUnderwater] then
        if EntityCategoryContains(categories.UEF, oACU.UnitId) then
            oACU[reftPreferredUpgrades] = {'AdvancedEngineering', 'ResourceAllocation', 'Shield'}
        elseif EntityCategoryContains(categories.AEON, oACU.UnitId) then
            oACU[reftPreferredUpgrades] = {'AdvancedEngineering', 'ResourceAllocation', 'ResourceAllocationAdvanced'}
        elseif EntityCategoryContains(categories.CYBRAN, oACU.UnitId) then
            oACU[reftPreferredUpgrades] = {'NaniteTorpedoTube', 'StealthGenerator'}
        elseif EntityCategoryContains(categories.SERAPHIM, oACU.UnitId) then
            oACU[reftPreferredUpgrades] = {'AdvancedEngineering', 'ResourceAllocation', 'ResourceAllocationAdvanced'}
        end
        --Cybran ACU on naval non-campaign map where enemy isnt at T3 yet
    elseif oACU.UnitId == 'url0001' and not(aiBrain[AiBotMap.refbCanPathToEnemyBaseWithLand]) and not(AiBotMap.bIsCampaignMap) and aiBrain[AiBotMap.refbCanPathToEnemyBaseWithAmphibious] and AiBotTeam.tTeamData[aiBrain.AiBotTeam][AiBotTeam.subrefiHighestFriendlyNavalFactoryTech] < 3 and AiBotTeam.tTeamData[aiBrain.AiBotTeam][AiBotTeam.subrefiHighestEnemyNavyTech] < 3 then
        --Cybran - get torpedo upgrade
        oACU[reftPreferredUpgrades] = {'NaniteTorpedoTube', 'StealthGenerator'}
        if oBP.Enhancements['SelfRepairSystem'] then table.insert( oACU[reftPreferredUpgrades], 'SelfRepairSystem') end
        if oBP.Enhancements['FAF_SelfRepairSystem'] then table.insert( oACU[reftPreferredUpgrades], 'FAF_SelfRepairSystem') end
        if bDebugMessages == true then LOG(sFunctionRef..': Want to use acu torpedo attack') end
        --Campaign where cant path to enemy base with land and have good energy - get gun (to help with early raids) then RAS
    elseif not(aiBrain[AiBotMap.refbCanPathToEnemyBaseWithLand]) and AiBotMap.iMapSize >= 500 and AiBotMap.bIsCampaignMap then
        if EntityCategoryContains(categories.UEF, oACU.UnitId) then
            oACU[reftPreferredUpgrades] = {'AdvancedEngineering', 'ResourceAllocation', 'Shield', 'T3Engineering'}
        elseif EntityCategoryContains(categories.AEON, oACU.UnitId) then
            oACU[reftPreferredUpgrades] = {'CrysalisBeam', 'HeatSink', 'ResourceAllocation', 'ResourceAllocationAdvanced'}
        elseif EntityCategoryContains(categories.CYBRAN, oACU.UnitId) then
            oACU[reftPreferredUpgrades] = {'CoolingUpgrade', 'ResourceAllocation'}
        elseif EntityCategoryContains(categories.SERAPHIM, oACU.UnitId) then
            oACU[reftPreferredUpgrades] = {'RateOfFire', 'AdvancedEngineering', 'ResourceAllocation', 'ResourceAllocationAdvanced', 'T3Engineering'}
        end

        --ACUs that have to choose between RAS and defensive upgrades - at high eco levels switch from getting RAS to getting defensive upgrade
        --UEF can get shield+RAS
        --Sera can get nano+RAS
        --Aeon and Cybran have to choose
    elseif oACU[refiUpgradeCount] >= 2 and (aiBrain[AiBotEconomy.refbBuiltParagon] or (aiBrain[AiBotEconomy.refiGrossMassBaseIncome] >= 100 * aiBrain[AiBotEconomy.refiBrainResourceMultiplier] and aiBrain[AiBotEconomy.refiGrossEnergyBaseIncome] >= 2500) or aiBrain[refbPlanningToGetShield]) and EntityCategoryContains(categories.AEON + categories.CYBRAN, oACU.UnitId) then
        if not(oACU[refbPlanningToGetShield]) then oACU[refbPlanningToGetShield] = true end
        if bDebugMessages == true then LOG(sFunctionRef..': Recording that ACU wants to get shield type upgrades') end
        if EntityCategoryContains(categories.AEON, oACU.UnitId) then
            --Mod that makes all upgrades super cheap
            if (oBP.Enhancements['ResourceAllocation'].BuildCostMass or 10000) <= 100 then
                oACU[reftPreferredUpgrades] = {'ResourceAllocation', 'AdvancedEngineering', 'ResourceAllocationAdvanced', 'T3Engineering', 'HeatSink'}
                if bDebugMessages == true then LOG(sFunctionRef..': Going with eco build due to cheap RAS') end
            else
                oACU[reftPreferredUpgrades] = {'CrysalisBeam', 'HeatSink', 'Shield', 'ShieldHeavy'}
            end
        elseif EntityCategoryContains(categories.CYBRAN, oACU.UnitId) then
            oACU[reftPreferredUpgrades] = {'CoolingUpgrade', 'StealthGenerator'}
            if oBP.Enhancements['SelfRepairSystem'] then table.insert( oACU[reftPreferredUpgrades], 'SelfRepairSystem') end
            if oBP.Enhancements['FAF_SelfRepairSystem'] then table.insert( oACU[reftPreferredUpgrades], 'FAF_SelfRepairSystem') end
            --Mod that makes upgrades cost nothing
            if (oBP.Enhancements['MicrowaveLaserGenerator'].BuildCostMass or 10000) <= 1000 then table.insert(oACU[reftPreferredUpgrades], 'MicrowaveLaserGenerator') end
            table.insert(oACU[reftPreferredUpgrades], 'CloakingGenerator')
        else AiBotUtilities.ErrorHandler('Unrecognised ACU category')
        end
    elseif AiBotTeam.iPlayersAtGameStart > 4 and AiBotMap.iMapSize >= 512 and (AiBotTeam.iPlayersAtGameStart >= 8 or AiBotMap.iMapSize >= 768) then
        if EntityCategoryContains(categories.UEF, oACU.UnitId) then
            if oACU[refiUpgradeCount] >= 2 then
                if oACU[refiUpgradeCount] >= 3 and AiBotUtilities.IsTableEmpty(oACU[reftPreferredUpgrades]) == false then
                    --Do nothing - have already decided what upgrade path to go down
                else
                    if oACU[refbPlanningToGetShield] == nil then
                        if AiBotUnitInfo.GetUnitHealthPercent(oACU) <= 0.85 then
                            oACU[refbPlanningToGetShield] = true
                        end
                    elseif AiBotUnitInfo.GetUnitHealthPercent(oACU) <= 0.6 then
                        oACU[refbPlanningToGetShield] = true
                    end
                    --Also get shield if a good chance we will use ACU in combat for a while
                    if oACU[refbPlanningToGetShield] or AiBotConditions.ACULikelyToWantCombatUpgradeOrShield(oACU) or AiBotTeam.tTeamData[aiBrain.AiBotTeam][AiBotTeam.refbAssassinationOrSimilar] then
                        oACU[reftPreferredUpgrades] = {'Shield', 'ResourceAllocation'}
                    else
                        oACU[reftPreferredUpgrades] = {'ResourceAllocation', 'Shield'}
                    end
                end
            else
                local bWantNanoNotT2 = true
                if AiBotMap.iMapSize >= 1000 or (AiBotMap.iMapSize >= 768 and AiBotTeam.tTeamData[aiBrain.AiBotTeam][AiBotTeam.subrefiActiveAiBotBrainCount] >= 4) then bWantNanoNotT2 = false end
                if bWantNanoNotT2 then
                    if oACU[refiUpgradeCount] >= 1 then
                        if AiBotTeam.tTeamData[aiBrain.AiBotTeam][AiBotTeam.refbAssassinationOrSimilar] then
                            oACU[reftPreferredUpgrades] = {'DamageStabilization', 'Shield', 'ResourceAllocation'}
                        else
                            oACU[reftPreferredUpgrades] = {'DamageStabilization', 'ResourceAllocation', 'Shield'}
                        end
                    else
                        oACU[reftPreferredUpgrades] = {'HeavyAntiMatterCannon', 'DamageStabilization'}
                    end
                else
                    if oACU[refiUpgradeCount] >= 1 then
                        if AiBotTeam.tTeamData[aiBrain.AiBotTeam][AiBotTeam.refbAssassinationOrSimilar] then
                            oACU[reftPreferredUpgrades] = {'AdvancedEngineering', 'Shield', 'ResourceAllocation'}
                        else
                            oACU[reftPreferredUpgrades] = {'AdvancedEngineering', 'ResourceAllocation', 'Shield'}
                        end
                    else
                        oACU[reftPreferredUpgrades] = {'HeavyAntiMatterCannon', 'AdvancedEngineering'}
                    end
                end
            end
        elseif EntityCategoryContains(categories.AEON, oACU.UnitId) then
            if (oBP.Enhancements['ResourceAllocation'].BuildCostMass or 10000) <= 100 then
                oACU[reftPreferredUpgrades] = {'ResourceAllocation', 'AdvancedEngineering', 'ResourceAllocationAdvanced', 'T3Engineering', 'HeatSink'}
                if bDebugMessages == true then LOG(sFunctionRef..': Going with eco build due to cheap RAS2') end
            elseif oACU[refiUpgradeCount] >= 3 then
                if oACU[refiUpgradeCount] >= 4 and AiBotUtilities.IsTableEmpty(oACU[reftPreferredUpgrades]) == false then
                    --Do nothing - already determined upgrade path
                else
                    if oACU[refbPlanningToGetShield] == nil then
                        if AiBotUnitInfo.GetUnitHealthPercent(oACU) <= 0.8 then
                            oACU[refbPlanningToGetShield] = true
                        end
                    elseif AiBotUnitInfo.GetUnitHealthPercent(oACU) <= 0.5 then
                        oACU[refbPlanningToGetShield] = true
                    end

                    --Also get shield if a good chance we will use ACU in combat for a while
                    if oACU[refbPlanningToGetShield] or AiBotConditions.ACULikelyToWantCombatUpgradeOrShield(oACU) or oACU:HasEnhancement('Shield') or oACU:HasEnhancement('ShieldHeavy') then
                        oACU[reftPreferredUpgrades] = {'CrysalisBeam', 'HeatSink', 'Shield', 'ShieldHeavy'}
                    else
                        oACU[reftPreferredUpgrades] = {'CrysalisBeam', 'HeatSink', 'ResourceAllocation', 'ResourceAllocationAdvanced'}
                    end
                end
            else
                if oACU[refbPlanningToGetShield] == nil then
                    if AiBotUnitInfo.GetUnitHealthPercent(oACU) <= 0.8 then
                        oACU[refbPlanningToGetShield] = true
                    end
                elseif AiBotUnitInfo.GetUnitHealthPercent(oACU) <= 0.5 then
                    oACU[refbPlanningToGetShield] = true
                end
                if oACU[refbPlanningToGetShield] or AiBotConditions.ACULikelyToWantCombatUpgradeOrShield(oACU) or oACU:HasEnhancement('Shield') or oACU:HasEnhancement('ShieldHeavy') then
                    oACU[reftPreferredUpgrades] = {'CrysalisBeam', 'HeatSink', 'Shield', 'ShieldHeavy'}
                else
                    oACU[reftPreferredUpgrades] = {'CrysalisBeam', 'HeatSink', 'ResourceAllocation', 'ResourceAllocationAdvanced'}
                end
            end
            if oBP.Enhancements['FAF_CrysalisBeamAdvanced'] then
                local iCurEntries = table.getn(oACU[reftPreferredUpgrades])
                local bHaveAdvancedRange = false
                for iEntry, sEntry in oACU[reftPreferredUpgrades] do
                    if sEntry == 'FAF_CrysalisBeamAdvanced' then
                        bHaveAdvancedRange = true
                        break
                    end
                end
                if not(bHaveAdvancedRange) then
                    --Do we either have the CrysalisBeam upgrade, or is it in preferred upgrades?
                    local bHaveInitialRange = false
                    if oACU:HasEnhancement('CrysalisBeam') then bHaveInitialRange = true
                    else
                        for iEntry, sEntry in oACU[reftPreferredUpgrades] do
                            if sEntry == 'CrysalisBeam' then
                                bHaveInitialRange = true
                                break
                            elseif iEntry >4 then break
                            end
                        end
                    end
                    if bHaveInitialRange then
                        if bDebugMessages == true then LOG(sFunctionRef..': Adding in FAF_CrysalisBeamAdvanced to enhancements wanted') end
                        local iEntryWanted = 4
                        if oACU[reftPreferredUpgrades][3] == 'ResourceAllocation' then iEntryWanted = 3 end
                        if iCurEntries >= iEntryWanted and  not(oACU[reftPreferredUpgrades][iEntryWanted] == 'FAF_CrysalisBeamAdvanced') then table.insert( oACU[reftPreferredUpgrades], iEntryWanted, 'FAF_CrysalisBeamAdvanced')
                        else table.insert(oACU[reftPreferredUpgrades], 'FAF_CrysalisBeamAdvanced')
                        end
                    end
                end
            end
        elseif EntityCategoryContains(categories.CYBRAN, oACU.UnitId) then
            --Mod that makes upgrades cost nothing
            if (oBP.Enhancements['MicrowaveLaserGenerator'].BuildCostMass or 10000) <= 1000 and oBP.Enhancements['ResourceAllocation'].BuildCostMass <= 1000 then
