                    end
                end
            else
                oACU[reftPreferredUpgrades] = {'CoolingUpgrade', 'ResourceAllocation'}
                if bDebugMessages == true then LOG(sFunctionRef..': Will start with default being gun and RAS') end
            end
        elseif EntityCategoryContains(categories.SERAPHIM, oACU.UnitId) then
            if (oBP.Enhancements['BlastAttack'].BuildCostMass or 10000) <= 1000 then
                oACU[reftPreferredUpgrades] = {'BlastAttack', 'DamageStabilization', 'ResourceAllocation', 'ResourceAllocationAdvanced', 'DamageStabilizationAdvanced'}
            elseif oACU[refiUpgradeCount] >= 2 then
                if oACU[refiUpgradeCount] >= 3 and AiBotUtilities.IsTableEmpty( oACU[reftPreferredUpgrades]) == false then
                    --Do nothing - already determined which path to go down
                else
                    if oACU[refbPlanningToGetShield] == nil then
                        if AiBotUnitInfo.GetUnitHealthPercent(oACU) <= 0.6 then
                            oACU[refbPlanningToGetShield] = true
                        end
                    elseif AiBotUnitInfo.GetUnitHealthPercent(oACU) <= 0.4 then
                        oACU[refbPlanningToGetShield] = true
                    end
                    if oACU[refbPlanningToGetShield] or AiBotConditions.ACULikelyToWantCombatUpgradeOrShield(oACU) or AiBotTeam.tTeamData[aiBrain.AiBotTeam][AiBotTeam.refbAssassinationOrSimilar] then
                        oACU[reftPreferredUpgrades] = {'DamageStabilization', 'ResourceAllocation', 'DamageStabilizationAdvanced', 'ResourceAllocationAdvanced'}
                    else
                        oACU[reftPreferredUpgrades] = {'ResourceAllocation', 'ResourceAllocationAdvanced', 'DamageStabilization'}
                    end
                end
            else
                oACU[reftPreferredUpgrades] = {'RateOfFire', 'AdvancedEngineering', 'ResourceAllocation', 'ResourceAllocationAdvanced', 'T3Engineering'}
            end
        end
    else
        if EntityCategoryContains(categories.UEF, oACU.UnitId) then
            oACU[reftPreferredUpgrades] = {'HeavyAntiMatterCannon', 'DamageStabilization', 'Shield'}
        elseif EntityCategoryContains(categories.AEON, oACU.UnitId) then
            oACU[reftPreferredUpgrades] = {'CrysalisBeam', 'HeatSink', 'Shield'}
            if oBP.Enhancements['FAF_CrysalisBeamAdvanced'] then table.insert( oACU[reftPreferredUpgrades], 'FAF_CrysalisBeamAdvanced') end --get shield before advanced range for survivability
            if bDebugMessages == true then LOG(sFunctionRef..': Standard Aeon, with FAF_CrysalisBeamAdvanced added if relevant') end
        elseif EntityCategoryContains(categories.CYBRAN, oACU.UnitId) then
            oACU[reftPreferredUpgrades] = {'CoolingUpgrade', 'StealthGenerator'}
            --FAF balance patch expected 15th July 2023 to introduce nano upgrade for Cybran
            if oBP.Enhancements['SelfRepairSystem'] then table.insert( oACU[reftPreferredUpgrades],'SelfRepairSystem') end
        elseif EntityCategoryContains(categories.SERAPHIM, oACU.UnitId) then
            oACU[reftPreferredUpgrades] = {'RateOfFire', 'AdvancedEngineering', 'DamageStabilization'}
        end
    end

    if bDebugMessages == true then LOG(sFunctionRef..': oACU[reftPreferredUpgrades] before refining to exclude invalid ones='..repru(oACU[reftPreferredUpgrades])) end

    --Check all of these are options (in case a mod has changed them)
    local tRestrictedEnhancements = import("/lua/enhancementcommon.lua").GetRestricted()
    local bCheckForRestrictions = not (AiBotUtilities.IsTableEmpty(tRestrictedEnhancements))
    local bInvalidUpgrade

    if AiBotUtilities.IsTableEmpty(oACU[reftPreferredUpgrades]) == false then
        local tiEntriesToRemove = {}
        if bDebugMessages == true then LOG(sFunctionRef..': oACU[reftPreferredUpgrades] before removing invalid entries='..repru(oACU[reftPreferredUpgrades])..'; bCheckForRestrictions='..tostring(bCheckForRestrictions)..'; tRestrictedEnhancements='..repru(tRestrictedEnhancements)) end
        for iUpgradeWanted, sUpgradeWanted in oACU[reftPreferredUpgrades] do
            bInvalidUpgrade = false
            if AiBotUtilities.IsTableEmpty(oBP.Enhancements[sUpgradeWanted]) then
                bInvalidUpgrade = true
                oACU[reftPreferredUpgrades] = {}
                if bDebugMessages == true then LOG(sFunctionRef..': ACU doesnt have sUpgradeWanted='..sUpgradeWanted..' in its blueprint so aborting') end
                break
            elseif bCheckForRestrictions then
                --If we cant get the first upgrade, then cancel all upgrades; otherwise just remove the later upgrade that we cant get
                if tRestrictedEnhancements[sUpgradeWanted] then
                    if bDebugMessages == true then LOG(sFunctionRef..': sUpgradeWanted '..sUpgradeWanted..' is in the restricted enhancements table so cant get it yet') end
                    bInvalidUpgrade = true
                elseif oBP.Enhancements[sUpgradeWanted].Prerequisite and tRestrictedEnhancements[oBP.Enhancements[sUpgradeWanted].Prerequisite] then
                    if bDebugMessages == true then LOG(sFunctionRef..': Upgrade has a preqrequisite that is restricted, so adding upgrade to the restricted list') end
                    bInvalidUpgrade = true
                    tRestrictedEnhancements[sUpgradeWanted] = true
                end
            end
            if bInvalidUpgrade then
                if bDebugMessages == true then LOG(sFunctionRef..': Considering restricted upgrade='..sUpgradeWanted..'; iUpgradeWanted='..iUpgradeWanted) end
                if iUpgradeWanted <= 1 then
                    if bDebugMessages == true then LOG(sFunctionRef..': We cant get the first planned upgrade so wont get any further upgrades') end
                    oACU[reftPreferredUpgrades] = {}
                    break
                else
                    table.insert(tiEntriesToRemove, iUpgradeWanted)
                end
            end
        end
        if AiBotUtilities.IsTableEmpty(tiEntriesToRemove) == false then
            local iTotalEntriesToRemove = table.getn(tiEntriesToRemove)
            for iCurEntry = iTotalEntriesToRemove, 1, -1 do
                if bDebugMessages == true then LOG(sFunctionRef..': Removing iCurEntry='..iCurEntry..' from preferred upgrades, Upgrade='..(oACU[reftPreferredUpgrades][iCurEntry] or 'nil')) end
                table.remove(oACU[reftPreferredUpgrades], tiEntriesToRemove[iCurEntry])
            end
        end
    end
    if bDebugMessages == true then LOG(sFunctionRef..': Is table of preferred upgrades empty='..tostring(AiBotUtilities.IsTableEmpty(oACU[reftPreferredUpgrades]))..'; repru='..repru(oACU[reftPreferredUpgrades])) end
    if AiBotUtilities.IsTableEmpty(oACU[reftPreferredUpgrades]) and oACU[refiUpgradeCount] == 0 then
        --Find the cheapest upgrade that boosts either rate of fire or range (if didnt start underwater) or that boosts build power (if started underwater)
        if bDebugMessages == true then LOG(sFunctionRef..': Have no preferred upgrades so will try finding a rate of fire or range boost') end
        oACU[reftPreferredUpgrades] = {}
        local iLowestMassCost = 1000000
        local sLowestUpgrade
        if AiBotUtilities.IsTableEmpty(oBP.Enhancements) == false then
            for sUpgrade, tUpgrade in oBP.Enhancements do
                if bDebugMessages == true then
                    LOG(sFunctionRef .. ': Considering sUpgrade=' .. sUpgrade .. '; tUpgrade=' .. reprs(tUpgrade))
                end
                if (oACU[refbStartedUnderwater] and (tUpgrade.NewBuildRate or 0) > 10) or (tUpgrade.NewMaxRadius or tUpgrade.NewRateOfFire) then
                    if tUpgrade.BuildCostMass < iLowestMassCost and not (tUpgrade.Prerequisite) and not (tRestrictedEnhancements[sUpgrade]) then
                        sLowestUpgrade = sUpgrade
                        iLowestMassCost = tUpgrade.BuildCostMass
                        if bDebugMessages == true then
                            LOG(sFunctionRef .. ': Have a new preferred upgrade ' .. sUpgrade .. '; iLowestMassCost=' .. iLowestMassCost)
                        end
                    end
                end
            end
            if bDebugMessages == true then
                LOG(sFunctionRef .. ': Finished considering the cheapest gun improving upgrade, sLowestUpgrade=' .. (sLowestUpgrade or 'nil')..'; Does ACU have RAS, or is RAS nil='..tostring(oBP.Enhancements['ResourceAllocation'] == nil))
            end
            if sLowestUpgrade then
                oACU[reftPreferredUpgrades] = { sLowestUpgrade }
                --Further backup - sometimes (e.g. cmapaign) RAS might be available but gun isnt
            elseif oBP.Enhancements['ResourceAllocation'] and not (tRestrictedEnhancements['ResourceAllocation']) then
                if bDebugMessages == true then LOG(sFunctionRef..': Adding in RAS if the upgrade slot is available') end
                local bSlotAvailable = true
                if oACU[refiUpgradeCount] > 0 then
                    local sSlotWanted = oBP.Enhancements['ResourceAllocation'].Slot
                    for sUpgrade, tUpgrade in oBP.Enhancements do
                        if tUpgrade.Slot == sSlotWanted and oACU:HasEnhancement(sUpgrade) then
                            if bDebugMessages == true then LOG(sFunctionRef..': Already using slot '..sSlotWanted..' for the upgrade '..sUpgrade) end
                            bSlotAvailable = false
                            break
                        end
                    end
                end
                if bSlotAvailable then
                    oACU[reftPreferredUpgrades] = { 'ResourceAllocation' }
                    if oBP.Enhancements['ResourceAllocationAdvanced'] and not (tRestrictedEnhancements['ResourceAllocationAdvanced']) then
                        table.insert(oACU[reftPreferredUpgrades], 'ResourceAllocationAdvanced')
                        if bDebugMessages == true then LOG(sFunctionRef..': Adding in RAS advanced as well') end
                    end
                end
                --LOUD support where ACU upgrades dont show as improving max radius
            else
                local tsOtherUpgradeNames = {
                'EXRipperBooster', --Cybran
                'EXZephyrBooster', --UEF
                'EXChronotronBooster', --Seraphim
                'EXDisruptorrBooster', --Aeon
                }
                for iPotentialUpgrade, sPotentialUpgrade in tsOtherUpgradeNames do
                    if oBP.Enhancements[sPotentialUpgrade] and not(tRestrictedEnhancements[sPotentialUpgrade]) then
                        if bDebugMessages == true then LOG(sFunctionRef..': Found backup gun upgrade so will use it, sPotentialUpgrade='..sPotentialUpgrade) end
                        oACU[reftPreferredUpgrades] = { sPotentialUpgrade}
                        break
                    end
                end
            end

            --Add support for (blackops?) ACU upgrades, e.g. based on LOUD
            local tsModUpgradesToConsider = {
                --Shield (UEF and Aeon)
                'EXShieldBubble', --UEF and Aeon shield (blueprints have the same reference)

                --RH slot:
                'EXL1Lambda', --Seraphim lambda field - Destroys some incoming projectiles (so a defensive buff)
                'EXL2Lambda', --Seraphim lambda field that redirects the projectiles

                --LH slot:
                'EXCombatEngineering', --Gives HP buff and slight regen, although fairly expensive

                --Other weapons (that would replace the main gun so have held off getting)
                --[['EXMasor', --Cybran laser (cheap version)
                'EXEMPArray', --Cybran EMP weapon
                'EXGattlingEnergyCannon', --UEF Gatling weapon
                'EXRapidCannon', --Seraphim gatling weapon
                'EXStormCannon', --Seraphim storm cannon weapon
                'EXBeamPhason', --Aeon laser (cheap version)--]]
            }
            for iPotentialUpgrade, sPotentialUpgrade in  tsModUpgradesToConsider do
                if oBP.Enhancements[sPotentialUpgrade] and not(tRestrictedEnhancements[sPotentialUpgrade]) then
                    if bDebugMessages == true then LOG(sFunctionRef..': Blackops ACU upgrades - adding upgrade '..sPotentialUpgrade..' to ACU owned by player '..oACU:GetAIBrain().Nickname) end
                    table.insert(oACU[reftPreferredUpgrades], sPotentialUpgrade)
                end
            end
        end
    else
        --If can get RAS, and it is cheap, then make it the first upgrade to get
        if oACU[refiUpgradeCount] == 0 and (oBP.Enhancements.ResourceAllocation.BuildCostMass or 10000) <= 100 and GetGameTimeSeconds() <= 60 and not(oACU[reftPreferredUpgrades][1] == 'ResourceAllocation') and not(tRestrictedEnhancements['ResourceAllocation']) then
            table.insert(oACU[reftPreferredUpgrades], 1, 'ResourceAllocation')
            --Remove the other RAS
            for iUpgrade, sUpgrade in oACU[reftPreferredUpgrades] do
                if sUpgrade == 'ResourceAllocation' and iUpgrade > 1 then
                    table.remove(oACU[reftPreferredUpgrades], iUpgrade)
                    break
                end
            end
            if bDebugMessages == true then LOG(sFunctionRef..': The first upgrade entry should be RAS upgrade because of how cheap it is') end
        end
    end
    --Campaign specific - add RAS upgrade if we only have 1 upgrade
    if bDebugMessages == true then
        LOG(sFunctionRef .. ': Campaign specific - considering adding RAS upgrade; is preferred upgrades nil=' .. tostring(oACU[reftPreferredUpgrades]))
        if oACU[reftPreferredUpgrades] and oACU[refiUpgradeCount] == 0 and not(tRestrictedEnhancements['ResourceAllocation']) then
            LOG(sFunctionRef .. ': Upgrade size=' .. table.getn(oACU[reftPreferredUpgrades])..'; repru='..repru(oACU[reftPreferredUpgrades]))
        end
    end
    if (oACU[refiUpgradeCount] or 0) > 0 and oACU[reftPreferredUpgrades] and table.getn(oACU[reftPreferredUpgrades]) <= 2 and (EntityCategoryContains(categories.AEON, oACU.UnitId) or table.getn(oACU[reftPreferredUpgrades]) <= 1) and oBP.Enhancements['ResourceAllocation'] and not (tRestrictedEnhancements['ResourceAllocation']) then
        local bSlotAvailable = true
        if oACU[refiUpgradeCount] > 0 then
            local sSlotWanted = oBP.Enhancements['ResourceAllocation'].Slot
            for sUpgrade, tUpgrade in oBP.Enhancements do
                if tUpgrade.Slot == sSlotWanted and oACU:HasEnhancement(sUpgrade) then
                    if bDebugMessages == true then LOG(sFunctionRef..': Already using slot '..sSlotWanted..' for the upgrade '..sUpgrade) end
                    bSlotAvailable = false
                    break
                end
            end
        end
        if not(tRestrictedEnhancements['ResourceAllocation']) and (bSlotAvailable or (AiBotUnitInfo.GetUnitHealthAndShieldPercent(oACU) == 1 and not(oACU:HasEnhancement('ShieldHeavy')) and AiBotTeam.tTeamData[aiBrain.AiBotTeam][AiBotTeam.refbDangerousForACUs] and AiBotTeam.tTeamData[aiBrain.AiBotTeam][AiBotTeam.refiEnemyAirToGroundThreat] <= 1000 and not(AiBotTeam.tTeamData[aiBrain.AiBotTeam][AiBotTeam.refbAssassinationOrSimilar]) and AiBotMap.tAllPlateaus[oACU[AiBotUnitInfo.reftAssignedPlateauAndLandZoneByTeam][aiBrain.AiBotTeam][1]][AiBotMap.subrefPlateauLandZones][oACU[AiBotUnitInfo.reftAssignedPlateauAndLandZoneByTeam][aiBrain.AiBotTeam][2]][AiBotMap.subrefLZTeamData][aiBrain.AiBotTeam][AiBotMap.refbBaseInSafePosition])) then
            table.insert(oACU[reftPreferredUpgrades], 'ResourceAllocation')
            if bDebugMessages == true then LOG(sFunctionRef..': Adding RAS to table of preferred upgrades') end
            if oBP.Enhancements['ResourceAllocationAdvanced'] and not (tRestrictedEnhancements['ResourceAllocationAdvanced']) then
                table.insert(oACU[reftPreferredUpgrades], 'ResourceAllocationAdvanced')
                if bDebugMessages == true then LOG(sFunctionRef..': Adding in RAS advanced as well') end
            end
        end
    end

    --Remove any upgrades that we already have
    RemovePreferredUpgradesThatWeAlreadyHave(oACU, oBP)

    if bDebugMessages == true then
        LOG(sFunctionRef .. ': End of code, oACU[reftPreferredUpgrades] after removing upgrades we already have=' .. repru(oACU[reftPreferredUpgrades]))
    end
end

function GetACUUpgradeWanted(oACU, bWantToDoTeleSnipe, tLZOrWZData, tLZOrWZTeamData, iPlateauOrZero, bIgnoreEcoCondition)
    --Returns nil if cantr find anything; also returns true as a second variable if we have a low cost upgrade
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    local sFunctionRef = 'GetACUUpgradeWanted'
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)

    

    local sUpgradeWanted, bIgnoreOtherConditions

    if EntityCategoryContains(categories.COMMAND, oACU.UnitId) then
        local aiBrain = oACU:GetAIBrain()
        local iTeam = aiBrain.AiBotTeam
        local bDontConsiderAnyUpgrades = false
        --Norush - dont get if more than 1m until it ends (want to use resources for eco instead) unless are close to overflowing (with slight random element to reduce tendancy of multiple ACUs to ugprade at the same time)
        if bDebugMessages == true then LOG(sFunctionRef..': Checking if norush active first, AiBotOverseer.bNoRushActive='..tostring(AiBotOverseer.bNoRushActive or false)..'; oACU[refbPlanningToGetTeleport]='..tostring(oACU[refbPlanningToGetTeleport] or false)) end
        if AiBotOverseer.bNoRushActive then
            local iTimeUntilNoRushEnds = AiBotOverseer.iNoRushTimer - GetGameTimeSeconds()
            local iDelayAdj = 0
            if iTimeUntilNoRushEnds >= 80 then
                bDontConsiderAnyUpgrades = true
            else
                local iCurACU =  aiBrain:GetCurrentUnits(categories.COMMAND)
                if AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiActiveAiBotBrainCount] > 0 or iCurACU > 0 then
                    iDelayAdj = aiBrain:GetArmyIndex()
                    if iCurACU > 0 then
                        local tACUs = aiBrain:GetListOfUnits(categories.COMMAND, false, true)
                        if AiBotUtilities.IsTableEmpty(tACUs) == false then
                            for iUnit, oUnit in aiBrain:GetListOfUnits(categories.COMMAND, false, true) do
                                if oUnit == oACU then
                                    iDelayAdj = iDelayAdj + iUnit
                                    break
                                end
                            end
                        end
                    end
                end
                if iTimeUntilNoRushEnds >= 60 + iDelayAdj then
                    bDontConsiderAnyUpgrades = true
                end
            end
            if bDebugMessages == true then LOG(sFunctionRef..': iTimeUntilNoRushEnds='..iTimeUntilNoRushEnds..'; iDelayAdj='..iDelayAdj..'; bDontConsiderAnyUpgrades='..tostring(bDontConsiderAnyUpgrades or false)) end
            --In a 'safe' spot and early on - delay getting upgrade so can focus on ecoing instead; also delay in larger teamgames early on if no t2 mex
        elseif GetGameTimeSeconds() <= 420 then
            local tStartPosition = AiBotMap.GetPlayerStartPosition(aiBrain)
            local tStartLZOrWZData, tStartLZOrWZTeamData = AiBotMap.GetLandOrWaterZoneData(tStartPosition, true, iTeam)
            if tStartLZOrWZTeamData[AiBotMap.refbBaseInSafePosition] then
                if tStartLZOrWZTeamData[AiBotMap.subrefMexCountByTech][3] == 0 and tStartLZOrWZTeamData[AiBotMap.subrefMexCountByTech][2] < 3 and (tStartLZOrWZTeamData[AiBotMap.subrefMexCountByTech][2] < 2 or not(AiBotTeam.tTeamData[iTeam][AiBotTeam.refbEnemyHasUpgradedACU]) or AiBotUtilities.GetDistanceBetweenPositions(oACU:GetPosition(), tLZOrWZTeamData[AiBotMap.reftClosestEnemyBase]) > AiBotUtilities.GetDistanceBetweenPositions(tStartLZOrWZData[AiBotMap.subrefMidpoint], tLZOrWZTeamData[AiBotMap.reftClosestEnemyBase])) then
                    bDontConsiderAnyUpgrades = true
                    if bDebugMessages == true then LOG(sFunctionRef..': In a safe spot so will delay ACU upgrade so can get more eco') end
                end
            end
            if not(bDontConsiderAnyUpgrades) and not(AiBotTeam.tTeamData[iTeam][AiBotTeam.refbEnemyHasUpgradedACU]) then
                --Cybran torp upgrade when have enough base eco - ignore normal 'delay upgrade' logic
                if not(aiBrain[AiBotMap.refbCanPathToEnemyBaseWithLand]) and aiBrain[AiBotMap.refbCanPathToEnemyBaseWithAmphibious] and oACU.UnitId == 'url0001' and (tStartLZOrWZTeamData[AiBotMap.subrefMexCountByTech][2] > 0 or aiBrain[AiBotEconomy.refiGrossMassBaseIncome] >= 3) and (iPlateauOrZero == 0 or AiBotUtilities.IsTableEmpty(tLZOrWZData[AiBotMap.subrefAdjacentWaterZones]) == false) and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestEnemyNavyTech] < 3 and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestFriendlyNavalFactoryTech] < 3 then
                    if bDebugMessages == true then LOG(sFunctionRef..': Want to consider getting upgrade for cybran since it can get torpedo upgrade') end
                elseif AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiActiveAiBotBrainCount] >= 3 and tStartLZOrWZTeamData[AiBotMap.subrefMexCountByTech][2] == 0 and tStartLZOrWZTeamData[AiBotMap.subrefMexCountByTech][3] == 0 then
                    if bDebugMessages == true then LOG(sFunctionRef..': Early teamgame, enemy doesnt have upgraded ACU, we lack T2 mex in our core base, so wont consider upgrade yet') end
                    bDontConsiderAnyUpgrades = true
                    --Exception for maps like setons and isis where large value reclaim area we want to go in priority to getting an upgrade early game and we dont have high AIx mod
                elseif aiBrain[AiBotEconomy.refiBrainBuildRateMultiplier] <= 1.5 and aiBrain[AiBotMap.refbCanPathToEnemyBaseWithLand] then
                    --Search for other zones we can path to from here that have lots of reclaim in them that have a mod dist of >=0.25 and <=0.55, and are within 275 of our ACU
                    if AiBotUtilities.IsTableEmpty(tLZOrWZData[AiBotMap.subrefLZPathingToOtherLandZones]) == false then
                        for iEntry, tSubtable in tLZOrWZData[AiBotMap.subrefLZPathingToOtherLandZones] do
                            if tSubtable[AiBotMap.subrefLZTravelDist] >= 300 then break end
                            local tAltLZData = AiBotMap.tAllPlateaus[iPlateauOrZero][AiBotMap.subrefPlateauLandZones][tSubtable[AiBotMap.subrefLZNumber]]
                            if bDebugMessages == true then LOG(sFunctionRef..': Considering if have high value zone to reclaim, iAdjLZ='..tSubtable[AiBotMap.subrefLZNumber]..'; Signif mass Reclaim='..(tAltLZData[AiBotMap.subrefTotalSignificantMassReclaim] or 'nil')) end
                            if tAltLZData[AiBotMap.subrefTotalSignificantMassReclaim] >= 1500 then
                                --Check mod distance
                                local tAltLZTeamData = tAltLZData[AiBotMap.subrefLZTeamData][iTeam]
                                if bDebugMessages == true then LOG(sFunctionRef..': Zone mod dist%='..tAltLZTeamData[AiBotMap.refiModDistancePercent]) end
                                if tAltLZTeamData[AiBotMap.refiModDistancePercent] <= 0.55 and tAltLZTeamData[AiBotMap.refiModDistancePercent] >= 0.15 then
                                    bDontConsiderAnyUpgrades = true
                                end
                            end
                        end
                    end
                end
            end
            --Exception for low cost mod where we are calling this from the early game order
            if bDontConsiderAnyUpgrades and GetGameTimeSeconds() <= 15 then
                bDontConsiderAnyUpgrades = false
            end
            --tLZOrWZTeamData[AiBotMap.subrefMexCountByTech][3] + tLZOrWZTeamData[AiBotMap.subrefMexCountByTech][2] <= 2
        end
        if bDontConsiderAnyUpgrades then
            --Do nothing
            if bDebugMessages == true then LOG(sFunctionRef..': Dont want to consider any upgrades due to norush or being in a safe spot') end
        else
            --If we were to get an upgrade, what upgrade would it be?
            if not(oACU[reftPreferredUpgrades]) or (oACU[reftPreferredUpgrades][1] and oACU.HasEnhancement and oACU:HasEnhancement(oACU[reftPreferredUpgrades][1])) or bWantToDoTeleSnipe or (oACU[refiUpgradeCount] > 0 and GetGameTimeSeconds() - (oACU[refiTimeLastConsideredUpgradePath] or 0) >= 30) then
                GetUpgradePathForACU(oACU, bWantToDoTeleSnipe)
            end

            if bDebugMessages == true then LOG(sFunctionRef..': oACU[reftPreferredUpgrades]='..repru(oACU[reftPreferredUpgrades])..'; Have low power='..tostring(AiBotConditions.HaveLowPower(iTeam))..'; bWantToDoTeleSnipe='..tostring(bWantToDoTeleSnipe or false)) end
            local sPotentialUpgrade = oACU[reftPreferredUpgrades][1]
            if AiBotUtilities.IsTableEmpty(oACU[reftPreferredUpgrades]) == false and sPotentialUpgrade then
                local tEnhancement = oACU:GetBlueprint().Enhancements[sPotentialUpgrade]
                local iTimeLastUpgradeCompleted = 10000
                local iNetEPreviousEnhancementCostPerTick = 0
                local sPreviousEnhancement
                if oACU[refiUpgradeCount] > 0 and AiBotUtilities.IsTableEmpty(oACU[AiBotUnitInfo.reftiTimeOfLastEnhancementComplete]) == false then
                    for sPrevEnhancement, iTimeCompleted in oACU[AiBotUnitInfo.reftiTimeOfLastEnhancementComplete] do
                        if bDebugMessages == true then LOG(sFunctionRef..': Considering sPrevEnhancement='..sPrevEnhancement..'; iTimeCompleted='..iTimeCompleted..'; Cur gametimeseconds='..GetGameTimeSeconds()) end
                        if GetGameTimeSeconds() - iTimeCompleted < iTimeLastUpgradeCompleted then
                            iTimeLastUpgradeCompleted = GetGameTimeSeconds() - iTimeCompleted
                            sPreviousEnhancement = sPrevEnhancement
                        end
                    end
                end
                if sPreviousEnhancement then
                    local tEnhancementDetails = oACU:GetBlueprint().Enhancements[sPreviousEnhancement]
                    if tEnhancementDetails then
                        local iBuildRate = oACU:GetBlueprint().Economy.BuildRate
                        if aiBrain.CheatEnabled then iBuildRate = iBuildRate * AiBotTeam.tTeamData[iTeam][AiBotTeam.refiHighestBrainBuildMultiplier] end
                        if bDebugMessages == true then LOG(sFunctionRef..': Previously completed enhancement: BuildCostEnergy='..tEnhancementDetails.BuildCostEnergy..'; BuildTime='..tEnhancementDetails.BuildTime..'; iBuildRate='..iBuildRate) end
                        iNetEPreviousEnhancementCostPerTick = (tEnhancementDetails.BuildCostEnergy * iBuildRate / tEnhancementDetails.BuildTime) * 0.1
                    end
                end
                if bDebugMessages == true then LOG(sFunctionRef..': iTimeLastUpgradeCompleted='..iTimeLastUpgradeCompleted..'; iNetEPreviousEnhancementCostPerTick='..iNetEPreviousEnhancementCostPerTick..'; brain refiNetEnergyBaseIncome='..aiBrain[AiBotEconomy.refiNetEnergyBaseIncome]) end
                if tEnhancement.BuildCostMass <= 100 and tEnhancement.BuildCostEnergy <= 100 and (oACU:GetAIBrain()[AiBotEconomy.refiGrossEnergyBaseIncome] >= 600 or not(sUpgradeWanted == 'CloakingGenerator' or sUpgradeWanted == 'Sheild')) then
                    sUpgradeWanted = sPotentialUpgrade
                    if tEnhancement.BuildTime <= 100 then
                        bIgnoreOtherConditions = true
                    end
                    if bDebugMessages == true then LOG(sFunctionRef..': Low cost upgrade wanted') end
                elseif (not(AiBotConditions.HaveLowPower(iTeam)) or aiBrain[AiBotEconomy.refbBuiltParagon] or (iTimeLastUpgradeCompleted < 5 and aiBrain[AiBotEconomy.refiNetEnergyBaseIncome] + iNetEPreviousEnhancementCostPerTick > 0) or (aiBrain[AiBotEconomy.refiGrossEnergyBaseIncome] >= 7500 and not(AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefbTeamIsStallingEnergy]))) then
                    if bWantToDoTeleSnipe or bIgnoreEcoCondition then sUpgradeWanted = sPotentialUpgrade
                    else
                        --Do we have the eco to support the upgrade?
                        if bDebugMessages == true then LOG(sFunctionRef..': Considering sPotentialUpgrade='..sPotentialUpgrade..'; for ACU '..oACU.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oACU)..' for brain '..oACU:GetAIBrain().Nickname..'; tEnhancement='..reprs(tEnhancement)) end
                        local iBuildRate = oACU:GetBlueprint().Economy.BuildRate
                        if aiBrain.CheatEnabled then iBuildRate = iBuildRate * AiBotTeam.tTeamData[iTeam][AiBotTeam.refiHighestBrainBuildMultiplier] end
                        local iMassCostPerTick = 0.1 * tEnhancement.BuildCostMass / (tEnhancement.BuildTime / iBuildRate)
                        local iEnergyCostPerTick = 0.1 * tEnhancement.BuildCostEnergy / (tEnhancement.BuildTime / iBuildRate)
                        --Do we have enough gross energy?
                        local iActiveACUUpgrades = 0
                        local iResourceFactor
                        if aiBrain[AiBotMap.refbCanPathToEnemyBaseWithLand] then
                            iResourceFactor = 1
                        elseif aiBrain[AiBotMap.refbCanPathToEnemyBaseWithAmphibious] then
                            iResourceFactor = 2
                        else
                            iResourceFactor = 4 --Cant path to enemy except with air
                        end

                        --If want MMLs then also increase resource requirements
                        local iPlateauOrZero, iLandOrWaterZone = AiBotMap.GetClosestPlateauOrZeroAndZoneToPosition(oACU:GetPosition())
                        if AiBotConditions.SaveMassForMMLOrMobileT3ArtiForFirebase(tLZOrWZData, tLZOrWZTeamData, iPlateauOrZero, iTeam, AiBotConditions.HaveLowMass(aiBrain)) then
                            iResourceFactor = iResourceFactor * 2
                            if AiBotConditions.HaveLowPower(aiBrain.AiBotTeam) then iResourceFactor = iResourceFactor * 2 end
                        end

                        --If enemy has dangerous ACU and the upgrade is combat related and is a T1-T2 stage upgrade (e.g. first nano, shield) and either we lack T3 land or we are UEF or Cybran, then decrease resource requirements
                        if AiBotTeam.tTeamData[iTeam][AiBotTeam.refbEnemyHasDangerousACU] and AiBotUnitInfo.GetUpgradeCombatWeighting(sPotentialUpgrade) >= 1 and tEnhancement.BuildCostMass <= 2500 and tEnhancement.BuildCostEnergy <= 125000 and (aiBrain[AiBotEconomy.refiOurHighestLandFactoryTech] <= 2 or aiBrain:GetFactionIndex() == AiBotUnitInfo.refFactionUEF or aiBrain:GetFactionIndex() == AiBotUnitInfo.refFactionCybran) then
                            iResourceFactor = iResourceFactor * 0.7
                        elseif (oACU[refiUpgradeCount] or 0) >= 2 and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiActiveAiBotBrainCount] >= 2 and tEnhancement.BuildCostMass >= 1500 and (oACU[refiUpgradeCount] >= 3 or not(aiBrain:GetFactionIndex() == AiBotUnitInfo.refFactionAeon)) then iResourceFactor = iResourceFactor * 1.3
                        elseif (oACU[refiUpgradeCount] or 0) == 0 and GetGameTimeSeconds() >= 600 then iResourceFactor = iResourceFactor * 0.5
                        end
                        if AiBotMap.bIsCampaignMap and GetGameTimeSeconds() >= 480 then
                            iResourceFactor = iResourceFactor * 0.5
                            if GetGameTimeSeconds() >= 1200 then
                                iResourceFactor = iResourceFactor * 0.5
                                if (tEnhancement.ProductionPerSecondMass or 0) > 0 and (tEnhancement.ProductionPerSecondEnergy or 0) > 0 and GetGameTimeSeconds() >= 1800 then iResourceFactor = iResourceFactor * 0.2 end --Campaign - even if have really poor eco want to get RAS upgrade
                            end
                        end
                        if oACU[refbStartedUnderwater] and (tEnhancement.ProductionPerSecondEnergy or 0) > 20 then iResourceFactor = 0.5 end
                        local iDistToEnemyBase
                        if iPlateauOrZero == 0 then
                            iDistToEnemyBase = AiBotUtilities.GetDistanceBetweenPositions(oACU:GetPosition(), AiBotMap.tPondDetails[AiBotMap.tiPondByWaterZone[iLandOrWaterZone]][AiBotMap.subrefPondWaterZones][iLandOrWaterZone][AiBotMap.subrefWZTeamData][iTeam][AiBotMap.reftClosestEnemyBase])
                        else
                            iDistToEnemyBase = AiBotUtilities.GetDistanceBetweenPositions(oACU:GetPosition(), AiBotMap.tAllPlateaus[iPlateauOrZero][AiBotMap.subrefPlateauLandZones][iLandOrWaterZone][AiBotMap.subrefLZTeamData][aiBrain.AiBotTeam][AiBotMap.reftClosestEnemyBase])
                        end
                        if iDistToEnemyBase >= 400 then iResourceFactor = iResourceFactor * 1.5 end
                        if (oACU[refiUpgradeCount] or 0) > 0 then
                            if (oACU[refiUpgradeCount] or 0) >= 2 and (oACU[refiUpgradeCount] >= 3 or not(aiBrain:GetFactionIndex() == AiBotUnitInfo.refFactionAeon)) and AiBotConditions.HaveLowMass(aiBrain) then iResourceFactor = iResourceFactor * 2
                            else iResourceFactor = iResourceFactor * 1.25
                            end
                        end
                        if AiBotOverseer.bNoRushActive and AiBotOverseer.iNoRushTimer - GetGameTimeSeconds() > 120 then
                            if AiBotConditions.HaveLowMass(aiBrain) or AiBotConditions.HaveLowPower(aiBrain.AiBotTeam) then
                                iResourceFactor = iResourceFactor * 2.5
                            else iResourceFactor = iResourceFactor * 1.75
                            end
                        end
                        if aiBrain[AiBotFactory.refiHighestFactoryBuildCount] >= 20 + 10 * (oACU[refiUpgradeCount] or 0) then

                            if AiBotMap.bIsCampaignMap then
                                iResourceFactor = iResourceFactor * 0.7
                            else
                                iResourceFactor = iResourceFactor * 0.8
                            end
                            if aiBrain[AiBotFactory.refiHighestFactoryBuildCount] >= 30 + 15 * (oACU[refiUpgradeCount] or 0) then
                                if AiBotMap.bIsCampaignMap then
                                    iResourceFactor = iResourceFactor * 0.7
                                    if aiBrain[AiBotFactory.refiHighestFactoryBuildCount] >= 60 then iResourceFactor = iResourceFactor * 0.75 end
                                else
                                    iResourceFactor = iResourceFactor * 0.85
                                end

                            end
                        end
                        --Reduce factor in smaller maps if lack gun
                        if iActiveACUUpgrades == 0 and not(sPotentialUpgrade == 'T3Engineering') and oACU[refiUpgradeCount] <= 1 and (oACU[AiBotUnitInfo.refiDFRange] <= 25 or oACU[refiUpgradeCount] == 0 or EntityCategoryContains(categories.AEON, oACU.UnitId)) and AiBotUtilities.GetDistanceBetweenPositions(tLZOrWZTeamData[AiBotMap.reftClosestFriendlyBase], tLZOrWZTeamData[AiBotMap.reftClosestEnemyBase]) <= 250 and aiBrain[AiBotMap.refbCanPathToEnemyBaseWithLand] then
                            iResourceFactor = iResourceFactor * 0.8
                        end

                        --If trying to get T3 - check we have T2/T3 power first
                        if sPotentialUpgrade == 'T3Engineering' and aiBrain[AiBotEconomy.refiGrossEnergyBaseIncome] <= 250 and aiBrain:GetCurrentUnits(AiBotUnitInfo.refCategoryPower - categories.TECH1) == 0 then
                            iResourceFactor = iResourceFactor * 3
                        end

                        if AiBotUtilities.IsTableEmpty(AiBotTeam.tTeamData[iTeam][AiBotTeam.subreftTeamUpgradingACUs]) == false then iActiveACUUpgrades = table.getn(AiBotTeam.tTeamData[iTeam][AiBotTeam.subreftTeamUpgradingACUs]) end
                        if bDebugMessages == true then LOG(sFunctionRef..': Considering if we have enough resources to get this upgrade, AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossEnergy]='..AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossEnergy]..'; Gross mass='..AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossMass]..'; Net energy='..AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamNetEnergy]..'; Net mass='..AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamNetMass]..'; Other active upgrades='..iActiveACUUpgrades..'; Is safe to get upgrade='..tostring(AiBotConditions.SafeToUpgradeUnit(oACU) or false)..'; iEnergyCostPerTick='..iEnergyCostPerTick..'; iMassCostPerTick='..iMassCostPerTick..'; iResourceFactor'..iResourceFactor..'; iDistToEnemyBase='..iDistToEnemyBase..'; oACU[refiUpgradeCount]='..(oACU[refiUpgradeCount] or 0)..'; aiBrain[AiBotMap.refbCanPathToEnemyBaseWithLand]='..tostring(aiBrain[AiBotMap.refbCanPathToEnemyBaseWithLand])..'; Have low mass='..tostring(AiBotConditions.HaveLowMass(aiBrain))..'; iResourceFactor='..iResourceFactor..'; aiBrain[AiBotFactory.refiHighestFactoryBuildCount]='..aiBrain[AiBotFactory.refiHighestFactoryBuildCount]) end
                        --Aeon exception - if we have the first gun upgrade, have high health %, and are close to a core base, then consider getting the second upgrade regardless of eco

                        if sPotentialUpgrade == 'HeatSink' and not(AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefbTeamIsStallingMass]) and aiBrain:GetEconomyStoredRatio('ENERGY') >= 0.5 and not(AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefbTeamIsStallingEnergy]) and AiBotUnitInfo.GetUnitHealthPercent(oACU) >= 0.75 then
                            local tLZOrWZData, tLZOrWZTeamData = AiBotMap.GetLandOrWaterZoneData(oACU:GetPosition(), true, iTeam)
                            if bDebugMessages == true then LOG(sFunctionRef..': Aeon already has range so now wants dps, tLZOrWZTeamData[AiBotMap.refiModDistancePercent]='..tLZOrWZTeamData[AiBotMap.refiModDistancePercent]) end
                            if tLZOrWZTeamData[AiBotMap.refiModDistancePercent] <= 0.45 then
                                sUpgradeWanted = sPotentialUpgrade
                            end
                        end
                        local iModifiedBrainCountForEcoConditions = (AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiActiveAiBotBrainCount] - 1) * 0.6 + 1

                        if not(sUpgradeWanted) and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossEnergy] >= (45 * iActiveACUUpgrades * iModifiedBrainCountForEcoConditions + iEnergyCostPerTick * 1.35) * iResourceFactor then
                            --Do we have enough gross mass?
                            if bDebugMessages == true then LOG(sFunctionRef..': Have enough gross energy, do we have enough gross mass? iActiveACUUpgrades='..iActiveACUUpgrades..'; iModifiedBrainCountForEcoConditions='..iModifiedBrainCountForEcoConditions..'; iMassCostPerTick='..iMassCostPerTick..'; iResourceFactor='..iResourceFactor) end
                            if AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossMass] >= (iActiveACUUpgrades * iModifiedBrainCountForEcoConditions * 2.5 + iMassCostPerTick * 2) * iResourceFactor then
                                --Do we have enough net energy?
                                if bDebugMessages == true then LOG(sFunctionRef..': Have enough gross mass, do we have enough net energy? iActiveACUUpgrades='..iActiveACUUpgrades..'; Team is stalling E='..tostring(AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefbTeamIsStallingEnergy])..'; Brain gross energy='..aiBrain[AiBotEconomy.refiGrossEnergyBaseIncome]..'; ACU health%='..AiBotUnitInfo.GetUnitHealthPercent(oACU)..'; enhancement combat factor='..AiBotUnitInfo.GetUpgradeCombatWeighting(sPotentialUpgrade)..'; enemy has dangerous ACU='..tostring(AiBotTeam.tTeamData[iTeam][AiBotTeam.refbEnemyHasDangerousACU])..'; subrefiTeamNetEnergy='..(AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamNetEnergy] or 'nil')..'; iEnergyCostPerTick='..iEnergyCostPerTick) end
                                if (AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossEnergy] >= (iActiveACUUpgrades * iModifiedBrainCountForEcoConditions + 100 * iEnergyCostPerTick * 2) * iResourceFactor and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamNetEnergy] >= 5 * iResourceFactor) or AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamNetEnergy] >= iEnergyCostPerTick * math.min(2.5, iResourceFactor * 0.4) or (iActiveACUUpgrades == 0 and oACU[refiUpgradeCount] == 0 and iEnergyCostPerTick <= 50 and aiBrain[AiBotEconomy.refiGrossEnergyBaseIncome] >= 100 * aiBrain[AiBotEconomy.refiBrainResourceMultiplier] and (aiBrain:GetEconomyStoredRatio('ENERGY') >= 0.9 or AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamNetEnergy] >= 1))
                                        or (iActiveACUUpgrades <= 1 and (iActiveACUUpgrades == 0 or AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiActiveAiBotBrainCount] >= 4) and oACU[refiUpgradeCount] > 0 and not(AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefbTeamIsStallingEnergy]) and AiBotUnitInfo.GetUpgradeCombatWeighting(sPotentialUpgrade) >= 1 and (iActiveACUUpgrades == 0 or AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiActiveAiBotBrainCount] >= 3) and (AiBotTeam.tTeamData[iTeam][AiBotTeam.refbEnemyHasDangerousACU] or AiBotUnitInfo.GetUnitHealthPercent(oACU) <= 0.75) and aiBrain[AiBotEconomy.refiGrossEnergyBaseIncome] >= iEnergyCostPerTick * 2 * iResourceFactor)
                                        or (iActiveACUUpgrades == 0 and oACU[refiUpgradeCount] == 0 and not(AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefbTeamIsStallingEnergy]) and (aiBrain:GetEconomyStoredRatio('ENERGY') >= 0.99 or aiBrain:GetEconomyStored('ENERGY') >= 12000) and aiBrain[AiBotEconomy.refiGrossEnergyBaseIncome] >= math.max(80*aiBrain[AiBotEconomy.refiBrainBuildRateMultiplier], 3 * iEnergyCostPerTick)) then

                                    --Do we have enoguh net mass?
                                    if bDebugMessages == true then LOG(sFunctionRef..': Have enough net energy, do we have enough net mass or so much gross mass that we can still proceed? Brain gross mass income='..aiBrain[AiBotEconomy.refiGrossMassBaseIncome]) end
                                    if (AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossMass] >= (iActiveACUUpgrades * iModifiedBrainCountForEcoConditions * 3.5 + iMassCostPerTick * 3) * iResourceFactor or AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamNetMass] >= iMassCostPerTick * math.min(2.5, iResourceFactor * 0.4) or AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamMassStored] >= math.min(3, iResourceFactor) * tEnhancement.BuildCostMass * 0.5 or (AiBotMap.bIsCampaignMap and aiBrain[AiBotFactory.refiHighestFactoryBuildCount] >= 30))
                                            --e.g. Cybran nano is 1500 mass; if want to start such an upgrade when ahve 40 mass income (if enemy has nano guncom), then means doing roughly a total mass / 375 calculation
                                            or (AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossMass] >= 16 and iActiveACUUpgrades == 0 and aiBrain[AiBotEconomy.refiGrossMassBaseIncome] >= tEnhancement.BuildCostMass / 375 and (AiBotTeam.tTeamData[iTeam][AiBotTeam.refbEnemyHasDangerousACU] or (oACU[refiUpgradeCount] == 0 and aiBrain[AiBotEconomy.refiGrossMassBaseIncome] >= 4*aiBrain[AiBotEconomy.refiBrainBuildRateMultiplier])) and AiBotUnitInfo.GetUpgradeCombatWeighting(sPotentialUpgrade) >= 1)
                                            or (AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamNetMass] >= 0.5 and tEnhancement.BuildCostMass <= 800)
                                    then
                                        --Early game on larger map where we lack 2+ T2 mexes, and dont have a t2 factory yet, and enemy doesnt have upgrades yet
                                        if bDebugMessages == true then LOG(sFunctionRef..': Checking if want to delay upgrade, AiBotTeam.tTeamData[iTeam][AiBotTeam.refbDangerousForACUs]='..tostring(AiBotTeam.tTeamData[iTeam][AiBotTeam.refbDangerousForACUs])..'; AiBotTeam.tTeamData[iTeam][AiBotTeam.refbEnemyHasUpgradedACU]='..tostring(AiBotTeam.tTeamData[iTeam][AiBotTeam.refbEnemyHasUpgradedACU])) end
                                        if not(AiBotTeam.tTeamData[iTeam][AiBotTeam.refbDangerousForACUs]) and (AiBotMap.iMapSize >= 750 or not(aiBrain[AiBotMap.refbCanPathToEnemyBaseWithLand])) and not(AiBotTeam.tTeamData[iTeam][AiBotTeam.refbEnemyHasUpgradedACU]) and (((oACU[refiUpgradeCount] or 0) == 0 and GetGameTimeSeconds() <= 360 and aiBrain[AiBotEconomy.refiOurHighestFactoryTechLevel] <= 1 and aiBrain:GetCurrentUnits(AiBotUnitInfo.refCategoryT2Mex) < 2 and (AiBotTeam.tTeamData[iTeam][AiBotTeam.refiMexCountByTech][3] or 0) == 0 and (GetGameTimeSeconds() <= 270 or AiBotUtilities.IsTableEmpty(AiBotTeam.tTeamData[iTeam][AiBotTeam.reftEnemyACUs]) or (AiBotUtilities.IsTableEmpty(AiBotTeam.tTeamData[iTeam][AiBotTeam.reftEnemyACUs]) == false and AiBotUtilities.GetDistanceBetweenPositions(oACU:GetPosition(), AiBotUtilities.GetNearestUnit(AiBotTeam.tTeamData[iTeam][AiBotTeam.reftEnemyACUs], oACU:GetPosition()):GetPosition()) > 225))
                                                or ((oACU[refiUpgradeCount] or 0) > 0 and aiBrain[AiBotEconomy.refiOurHighestFactoryTechLevel] <= 2 and aiBrain:GetCurrentUnits(AiBotUnitInfo.refCategoryT3Mex) == 0 and (not(EntityCategoryContains(categories.CYBRAN, oACU.UnitId)) or oACU[refiUpgradeCount] >= 2 or (AiBotUtilities.IsTableEmpty(tLZOrWZTeamData[AiBotMap.reftoNearestDFEnemies]) == false and AiBotUtilities.GetDistanceBetweenPositions(oACU:GetPosition(), AiBotUtilities.GetNearestUnit(tLZOrWZTeamData[AiBotMap.reftoNearestDFEnemies], oACU:GetPosition()):GetPosition()) <= 100))))) then
                                            if bDebugMessages == true then
                                                if AiBotUtilities.IsTableEmpty(AiBotTeam.tTeamData[iTeam][AiBotTeam.reftEnemyACUs]) then LOG(sFunctionRef..': Early game, larger map, no enemy ACU table, will delay upgrade')
                                                else
                                                    LOG(sFunctionRef..': Early game on larger map, enemy lacks upgrade, and either we dont have t2, so no rush to get gun, or we have gun so dont need further upgrade urgently, Dist to nearest enemy ACU='..AiBotUtilities.GetDistanceBetweenPositions(oACU:GetPosition(), AiBotUtilities.GetNearestUnit(AiBotTeam.tTeamData[iTeam][AiBotTeam.reftEnemyACUs], oACU:GetPosition()):GetPosition()))
                                                end
                                            end
                                        else
                                            if bDebugMessages == true then LOG(sFunctionRef..': Will get the upgrade unless naval map with noncybran ACU, aiBrain[AiBotMap.refbCanPathToEnemyBaseWithLand]='..tostring(aiBrain[AiBotMap.refbCanPathToEnemyBaseWithLand] or false)..'; AiBotTeam.tLandSubteamData[aiBrain.AiBotLandSubteam][AiBotTeam.refiEnemyMobileDFThreatNearOurSide]='..(AiBotTeam.tLandSubteamData[aiBrain.AiBotLandSubteam][AiBotTeam.refiEnemyMobileDFThreatNearOurSide] or 'nil')..'; Approaching ACU threat='..AiBotConditions.GetThreatOfApproachingEnemyACUsAndNearestACU(tLZOrWZData, tLZOrWZTeamData, iPlateauOrZero, iLandOrWaterZone, iTeam, 150)) end
                                            local bProceedWithUpgrade = aiBrain[AiBotMap.refbCanPathToEnemyBaseWithLand] or AiBotMap.bIsCampaignMap or aiBrain[AiBotEconomy.refbBuiltParagon] or AiBotMap.iMapSize <= 500 or tLZOrWZTeamData[AiBotMap.subrefMexCountByTech][3] >= 3 or aiBrain[AiBotEconomy.refiGrossMassBaseIncome] >= 30 or (AiBotTeam.tTeamData[iTeam][AiBotTeam.refbDangerousForACUs] and AiBotTeam.tTeamData[iTeam][AiBotTeam.refbAssassinationOrSimilar]) or AiBotTeam.tLandSubteamData[aiBrain.AiBotLandSubteam][AiBotTeam.refiEnemyMobileDFThreatNearOurSide] >= 1000 or oACU.UnitId == 'url0001'
                                            if not(bProceedWithUpgrade) and AiBotTeam.tTeamData[iTeam][AiBotTeam.refbEnemyHasDangerousACU] and aiBrain[AiBotEconomy.refiOurHighestFactoryTechLevel] >= 2 and tLZOrWZTeamData[AiBotMap.subrefLZbCoreBase] then
                                                local iApproachingACUThreat, oApproachingACU = AiBotConditions.GetThreatOfApproachingEnemyACUsAndNearestACU(tLZOrWZData, tLZOrWZTeamData, iPlateauOrZero, iLandOrWaterZone, iTeam, 150)
                                                if bDebugMessages == true then LOG(sFunctionRef..': oApproachingACU DF range='..(oApproachingACU[AiBotUnitInfo.refiDFRange] or 'nil')) end
                                                if iApproachingACUThreat >= 1500 and oApproachingACU and oApproachingACU[AiBotUnitInfo.refiDFRange] >= 26 then
                                                    bProceedWithUpgrade = true
                                                end
                                            end
                                            if bProceedWithUpgrade then --AiBotConditions.GetThreatOfApproachingEnemyACUsAndNearestACU(tLZOrWZData, tLZOrWZTeamData, iPlateauOrZero, iLandOrWaterZone, iTeam, 150) >= 1500) then
                                                --Require T3 mex if 3rd+ upgrade and the upgrade has a significant cost
                                                if bDebugMessages == true then LOG(sFunctionRef..': T3 mex count='..aiBrain:GetCurrentUnits(AiBotUnitInfo.refCategoryT3Mex)..'; T2 mex count='..aiBrain:GetCurrentUnits(AiBotUnitInfo.refCategoryT2Mex)) end
                                                if (oACU[refiUpgradeCount] or 0) < 2 or tEnhancement.BuildCostMass <= 800 or aiBrain[AiBotEconomy.refbBuiltParagon] or aiBrain:GetCurrentUnits(AiBotUnitInfo.refCategoryT3Mex) > 1 or (tEnhancement.BuildCostMass <= 2000 and aiBrain[AiBotEconomy.refiGrossMassBaseIncome] >= 4 and (oACU[refiUpgradeCount] or 0) == 2 and AiBotTeam.tTeamData[iTeam][AiBotTeam.refbEnemyHasDangerousACU] and AiBotUnitInfo.GetUpgradeCombatWeighting(sPotentialUpgrade) >= 1 and aiBrain:GetCurrentUnits(AiBotUnitInfo.refCategoryT2Mex) >= 6 * (tEnhancement.BuildCostMass - 1000) / 1000) then
                                                    --Naval maps - delay getting upgrade until have t3 mexes if no threat on our land mass and no appraoching ACU
                                                    sUpgradeWanted = sPotentialUpgrade
                                                end
                                            end
                                        end
                                    end
                                end
                            end
                        end
                    end
                end
            end
            if bDebugMessages == true then
                LOG(sFunctionRef..': End of code, sUpgradeWanted='..(sUpgradeWanted or 'nil'))
                if sUpgradeWanted then
                    LOG(sFunctionRef..': Does ACU have this enhancement='..tostring(oACU:HasEnhancement(sUpgradeWanted)))
                    LOG(sFunctionRef..': Is this restricted='..tostring(import("/lua/enhancementcommon.lua").GetRestricted()[sUpgradeWanted]))
                end
            end
        end
    end
    --Redudnancy for missions where they add enhancement restrictions after we have chosen our upgrade path
    if sUpgradeWanted and import("/lua/enhancementcommon.lua").GetRestricted()[sUpgradeWanted] then
        sUpgradeWanted = nil
        if AiBotUtilities.IsTableEmpty(oACU[reftPreferredUpgrades]) == false then
            local tRestrictions = import("/lua/enhancementcommon.lua").GetRestricted()
            for iCurUpgradeWanted = table.getn(oACU[reftPreferredUpgrades]), 1, -1 do
                if tRestrictions[oACU[reftPreferredUpgrades]] then
                    table.remove(oACU[reftPreferredUpgrades], iCurUpgradeWanted)
                end
            end
        end
    end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
    return sUpgradeWanted, bIgnoreOtherConditions
end

function GetUpgradeForSACU(oSACU, bWantBuildPower, bForceGetNewUpgradePath, bWantShieldField)
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    local sFunctionRef = 'GetUpgradeForSACU'
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)

    --E.g. used when overflowing resources and want engineer upgrade for the SACU
    local sUpgradeWanted
    local aiBrain = oSACU:GetAIBrain()
    local iTeam = aiBrain.AiBotTeam
    --If we were to get an upgrade, what upgrade would it be?
    if bForceGetNewUpgradePath or not(oSACU[reftPreferredUpgrades]) or (oSACU[reftPreferredUpgrades][1] and oSACU.HasEnhancement and oSACU:HasEnhancement(oSACU[reftPreferredUpgrades][1])) then
        --Determine upgrade path
        oSACU[reftPreferredUpgrades] = {}
        --Find build rate and RAS enhancements
        local tUpgradesAvailable = oSACU:GetBlueprint().Enhancements
        local oBP = oSACU:GetBlueprint()
        if AiBotUtilities.IsTableEmpty(tUpgradesAvailable) == false then
            local sBuildRateUpgrade, sBestShieldSizeEnhancement

            --First get what slots are available
            --Check if can get RAS upgrade
            local tbSlotsInUse = {}
            local iBestBuildPowerRate, iBestShieldSize
            if bWantBuildPower then
                iBestBuildPowerRate = (oSACU:GetBlueprint().Economy.BuildRate or 0)
            end
            if bWantShieldField then
                iBestShieldSize = (oSACU:GetBlueprint().Defense.Shield.ShieldSize or 0)
            end

            local iBestEcoRate = 0
            local sBestEcoEnhancement, iCurEcoRate
            for sEnhancement, tEnhancement in tUpgradesAvailable do
                if oSACU:HasEnhancement(sEnhancement) then
                    if bDebugMessages == true then LOG(sFunctionRef..': We already have the enhancement '..sEnhancement..'; ProductionPerSecondMass='..(tEnhancement.ProductionPerSecondMass or 0)..'; NewBuildRate='..(tEnhancement.NewBuildRate or 0)..'; ShieldSize='..(tEnhancement.ShieldSize or 0)) end
                    tbSlotsInUse[tEnhancement.Slot] = true
                    iCurEcoRate = (tEnhancement.ProductionPerSecondEnergy or 0) / 100 + (tEnhancement.ProductionPerSecondMass or 0)
                    if iCurEcoRate > iBestEcoRate then
                        iBestEcoRate = iCurEcoRate
                    end
                    if bWantBuildPower and (tEnhancement.NewBuildRate or 0) > iBestBuildPowerRate then
                        iBestBuildPowerRate = tEnhancement.NewBuildRate
                        sBuildRateUpgrade = nil
                    end
                    if bWantShieldField and (tEnhancement.ShieldSize or 0) > iBestShieldSize then
                        iBestShieldSize = tEnhancement.ShieldSize
                        sBestShieldSizeEnhancement = nil
                    end
                elseif not(tEnhancement.Prerequisite) or (oSACU:HasEnhancement(tEnhancement.Prerequisite)) then
                    iCurEcoRate = (tEnhancement.ProductionPerSecondEnergy or 0) / 100 + (tEnhancement.ProductionPerSecondMass or 0)
                    if iCurEcoRate > iBestEcoRate then
                        iBestEcoRate = iCurEcoRate
                        sBestEcoEnhancement = sEnhancement
                    end
                    if bWantBuildPower and (tEnhancement.NewBuildRate or 0) > iBestBuildPowerRate then
                        iBestBuildPowerRate = tEnhancement.NewBuildRate
                        sBuildRateUpgrade = sEnhancement
                    end
                    if bWantShieldField and (tEnhancement.ShieldSize or 0) > iBestShieldSize then
                        iBestShieldSize = tEnhancement.ShieldSize
                        sBestShieldSizeEnhancement = sEnhancement
                    end
                end
            end

            if bDebugMessages == true then LOG(sFunctionRef..': bWantBuildPower='..tostring(bWantBuildPower)..'; sBuildRateUpgrade='..(sBuildRateUpgrade or 'nil')..'; sBestShieldSizeEnhancement='..(sBestShieldSizeEnhancement or 'nil')) end
            --Shield upgrade if are defending against arti
            if bWantShieldField and sBestShieldSizeEnhancement and AiBotTeam.tTeamData[iTeam][AiBotTeam.refbDefendAgainstArti] and not(tbSlotsInUse[tUpgradesAvailable[sBuildRateUpgrade].Slot]) then
                table.insert(oSACU[reftPreferredUpgrades], sBestShieldSizeEnhancement)
            end
            if bWantBuildPower then
                if sBuildRateUpgrade and (not(sBestEcoEnhancement) or bWantBuildPower or not(tUpgradesAvailable[sBuildRateUpgrade].Slot == tUpgradesAvailable[sBestEcoEnhancement].Slot)) and not(tbSlotsInUse[tUpgradesAvailable[sBuildRateUpgrade].Slot]) then
                    table.insert(oSACU[reftPreferredUpgrades], sBuildRateUpgrade)
                    if bDebugMessages == true then LOG(sFunctionRef..': Included build power enhancement in table of upgrades for the SACU') end
                end
            end
            if sBestEcoEnhancement then
                table.insert(oSACU[reftPreferredUpgrades], sBestEcoEnhancement)
            end
            --Shield upgrade if not defending against arti
            if bWantShieldField and sBestShieldSizeEnhancement and not(AiBotTeam.tTeamData[iTeam][AiBotTeam.refbDefendAgainstArti]) and not(tbSlotsInUse[tUpgradesAvailable[sBuildRateUpgrade].Slot]) then
                table.insert(oSACU[reftPreferredUpgrades], sBestShieldSizeEnhancement)
            end

            if bDebugMessages == true then LOG(sFunctionRef..': oSACU[reftPreferredUpgrades] before refining to exclude invalid ones='..repru(oSACU[reftPreferredUpgrades])) end

            --Check all of these are options (in case a mod has changed them)
            local tRestrictedEnhancements = import("/lua/enhancementcommon.lua").GetRestricted()
            local bCheckForRestrictions = not (AiBotUtilities.IsTableEmpty(tRestrictedEnhancements))
            local bInvalidUpgrade

            if AiBotUtilities.IsTableEmpty(oSACU[reftPreferredUpgrades]) == false then
                local tiEntriesToRemove = {}
                if bDebugMessages == true then LOG(sFunctionRef..': oSACU[reftPreferredUpgrades] before removing invalid entries='..repru(oSACU[reftPreferredUpgrades])) end
                for iUpgradeWanted, sUpgradeWanted in oSACU[reftPreferredUpgrades] do
                    bInvalidUpgrade = false
                    if AiBotUtilities.IsTableEmpty(oBP.Enhancements[sUpgradeWanted]) then
                        bInvalidUpgrade = true
                        oSACU[reftPreferredUpgrades] = {}
                        if bDebugMessages == true then LOG(sFunctionRef..': ACU doesnt have sUpgradeWanted='..sUpgradeWanted..' in its blueprint so aborting') end
                        break
                    elseif bCheckForRestrictions then
                        --If we cant get the first upgrade, then cancel all upgrades; otherwise just remove the later upgrade that we cant get
                        if tRestrictedEnhancements[sUpgradeWanted] then
                            if bDebugMessages == true then LOG(sFunctionRef..': sUpgradeWanted '..sUpgradeWanted..' is in the restricted enhancements table so cant get it yet') end
                            bInvalidUpgrade = true
                        end
                    end
                    if bInvalidUpgrade then
                        if bDebugMessages == true then LOG(sFunctionRef..': Considering restricted upgrade='..sUpgradeWanted..'; iUpgradeWanted='..iUpgradeWanted) end
                        if iUpgradeWanted <= 1 then
                            if bDebugMessages == true then LOG(sFunctionRef..': We cant get the first planned upgrade so wont get any further upgrades') end
                            oSACU[reftPreferredUpgrades] = {}
                            break
                        else
                            table.insert(tiEntriesToRemove, iUpgradeWanted)
                        end
                    end
                end
                if AiBotUtilities.IsTableEmpty(tiEntriesToRemove) == false then
                    local iTotalEntriesToRemove = table.getn(tiEntriesToRemove)
                    for iCurEntry = iTotalEntriesToRemove, 1, -1 do
                        if bDebugMessages == true then LOG(sFunctionRef..': Removing iCurEntry='..iCurEntry..' from preferred upgrades, Upgrade='..(oSACU[reftPreferredUpgrades][iCurEntry] or 'nil')) end
                        table.remove(oSACU[reftPreferredUpgrades], tiEntriesToRemove[iCurEntry])
                    end
                end
            end
            if bDebugMessages == true then LOG(sFunctionRef..': Is table of preferred upgrades empty='..tostring(AiBotUtilities.IsTableEmpty(oSACU[reftPreferredUpgrades]))..'; repru='..repru(oSACU[reftPreferredUpgrades])) end

            --Remove any upgrades that we already have
            RemovePreferredUpgradesThatWeAlreadyHave(oSACU, oBP)

            if bDebugMessages == true then
                LOG(sFunctionRef .. ': End of code, oSACU[reftPreferredUpgrades] after removing upgrades we already have=' .. repru(oSACU[reftPreferredUpgrades]))
            end


            if oSACU[reftPreferredUpgrades][1] and not(oSACU:HasEnhancement(oSACU[reftPreferredUpgrades][1])) then
                sUpgradeWanted = oSACU[reftPreferredUpgrades][1]
            end
        end
    end
    if bDebugMessages == true then
        LOG(sFunctionRef..': End of code, sUpgradeWanted='..(sUpgradeWanted or 'nil'))
        if sUpgradeWanted then
            LOG(sFunctionRef..': Does ACU have this enhancement='..tostring(oSACU:HasEnhancement(sUpgradeWanted)))
        end
    end
    if not(sUpgradeWanted) and bWantBuildPower then oSACU[refbTriedAndFailedToGetBuildRateUpgrade] = true end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
    return sUpgradeWanted
end

function DoesACUWantToRun(iPlateau, iLandZone, tLZData, tLZTeamData, oACU)
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    local sFunctionRef = 'DoesACUWantToRun'
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)



    local bWantToRun = false
    local iTeam = oACU:GetAIBrain().AiBotTeam

    --Dont run if in core base unless low health or close to the rally point
    if bDebugMessages == true then LOG(sFunctionRef..': Start of code for brain '..oACU:GetAIBrain().Nickname..'; Is ACU in core base='..tostring(tLZTeamData[AiBotMap.subrefLZbCoreBase])..' iPlateau='..(iPlateau or 'nil')..'; iLandZone='..(iLandZone or 'nil')..'; oACU='..oACU.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oACU)..'; AiBotTeam.tTeamData[aiBrain.AiBotTeam][AiBotTeam.refbDangerousForACUs]='..tostring(AiBotTeam.tTeamData[oACU:GetAIBrain().AiBotTeam][AiBotTeam.refbDangerousForACUs] or false)..'; Does enemy have sub? count='..(AiBotTeam.tTeamData[oACU:GetAIBrain().AiBotTeam][AiBotTeam.refiEnemySubCount] or 0)..'; Dist to midpoint='..AiBotUtilities.GetDistanceBetweenPositions(oACU:GetPosition(), tLZData[AiBotMap.subrefMidpoint])) end
    --Adjacent water zone with destroyers - run even if are in core base if ACU health low
    if AiBotUtilities.IsTableEmpty(tLZData[AiBotMap.subrefAdjacentWaterZones]) == false and not(oACU[refbUseACUAggressively]) and AiBotUnitInfo.GetUnitHealthPercent(oACU) < 0.95 then
        local iAdjWZ, iPond
        for iEntry, tSubtable in tLZData[AiBotMap.subrefAdjacentWaterZones] do
            iAdjWZ = tSubtable[AiBotMap.subrefAWZRef]
            iPond = AiBotMap.tiPondByWaterZone[iAdjWZ]
            local tWZTeamData = AiBotMap.tPondDetails[iPond][AiBotMap.subrefPondWaterZones][iAdjWZ][AiBotMap.subrefWZTeamData][iTeam]
            local iDFRangeThreshold = 5 + oACU[AiBotUnitInfo.refiDFRange]
            if tWZTeamData[AiBotMap.subrefWZBestEnemyDFRange] > iDFRangeThreshold and AiBotUtilities.IsTableEmpty(tWZTeamData[AiBotMap.subrefTEnemyUnits]) == false and tWZTeamData[AiBotMap.subrefWZThreatEnemyVsSurface] >= 1500 and (tWZTeamData[AiBotMap.subrefWZThreatEnemyVsSurface] > tWZTeamData[AiBotMap.subrefWZTThreatAllyCombatTotal] or tWZTeamData[AiBotMap.subrefWZThreatEnemyVsSurface] >= 5000) then
                --This WZ has enemies that are dangerous to the ACU; dont want ACU to get within 20 of being in range of them
                for iUnit, oUnit in tWZTeamData[AiBotMap.subrefTEnemyUnits] do
                    if not(oUnit.Dead) and (oUnit[AiBotUnitInfo.refiDFRange] or 0) > iDFRangeThreshold then
                        if bDebugMessages == true then LOG(sFunctionRef..': Considering enemy naval unit '..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..'; Dist from unit to ACU='..AiBotUtilities.GetDistanceBetweenPositions(oUnit:GetPosition(), oACU:GetPosition())..'; Unit DF range='..oUnit[AiBotUnitInfo.refiDFRange]) end
                        if AiBotUtilities.GetDistanceBetweenPositions(oUnit:GetPosition(), oACU:GetPosition()) - oUnit[AiBotUnitInfo.refiDFRange] <= 20 then
                            bWantToRun = true
                            break
                        end
                    end
                end
                if bWantToRun then break end
            end
        end
    end
    if bWantToRun then
        if bDebugMessages == true then LOG(sFunctionRef..': Will run due to dangerous adjacent water zone') end
    elseif tLZTeamData[AiBotMap.subrefLZbCoreBase] and (AiBotUnitInfo.GetUnitHealthPercent(oACU) >= 0.2 and (oACU[refbUseACUAggressively] or (AiBotUnitInfo.GetUnitHealthPercent(oACU) >= 0.4 and ((oACU[refiUpgradeCount] or 0) > 0 or not(AiBotTeam.tTeamData[iTeam][AiBotTeam.refbEnemyHasUpgradedACU])) and (AiBotUnitInfo.GetUnitHealthPercent(oACU) >= 0.75 or AiBotUtilities.GetDistanceBetweenPositions(oACU:GetPosition(), tLZData[AiBotMap.subrefMidpoint]) <= 70)) or AiBotUtilities.GetDistanceBetweenPositions(oACU:GetPosition(), tLZData[AiBotMap.subrefMidpoint]) <= 15)) and ((AiBotUnitInfo.GetUnitHealthPercent(oACU) >= 0.5 or AiBotUtilities.GetDistanceBetweenPositions(oACU:GetPosition(), tLZTeamData[AiBotMap.reftClosestEnemyBase]) > 5 + AiBotUtilities.GetDistanceBetweenPositions(tLZData[AiBotMap.subrefMidpoint],tLZTeamData[AiBotMap.reftClosestEnemyBase])))
            --Check we have a base left - being decent level of combat units, or owe have fac or PD that is completed in zone
            and (AiBotUnitInfo.GetUnitHealthPercent(oACU) >= 0.95 or tLZTeamData[AiBotMap.subrefTThreatEnemyCombatTotal] < 300 or tLZTeamData[AiBotMap.subrefLZTThreatAllyCombatTotal] > 200 + AiBotUnitInfo.GetCombatThreatRating({ oACU }, false, false) or AiBotConditions.GetNumberOfConstructedUnitsMeetingCategoryInZone(tLZTeamData, AiBotUnitInfo.refCategoryFactory + AiBotUnitInfo.refCategoryPD + AiBotUnitInfo.refCategoryExperimentalLevel) > 0)

    then
        if bDebugMessages == true then LOG(sFunctionRef..': Are in core base with some health so dont want to run unless approaching experimental or large threat, oACU[refbUseACUAggressively]='..tostring(oACU[refbUseACUAggressively])) end
        --20km type map - be more cautious in assassination
    elseif tLZTeamData[AiBotMap.refiModDistancePercent] >= 0.3 and AiBotTeam.tTeamData[iTeam][AiBotTeam.refbAssassinationOrSimilar] and GetGameTimeSeconds() >= 1000 and AiBotMap.iMapSize >= 756 then
        if bDebugMessages == true then LOG(sFunctionRef..': Large map, cant afford to lose ACU, so will be cautious and stay relatively near base') end
        bWantToRun = true
    else

        local iACUThreat = (AiBotUnitInfo.GetCombatThreatRating({ oACU}, false) or 0)
        --Dont run if building T1 mex and almost done, assuming our health is ok
        if iACUThreat >= 400 and (oACU:IsUnitState('Building') or oACU:IsUnitState('Repairing') or oACU:IsUnitState('Capturing')) and tLZTeamData[AiBotMap.subrefTThreatEnemyCombatTotal] <= math.max(1500, iACUThreat * 1.5) and AiBotUnitInfo.IsUnitValid(oACU:GetFocusUnit()) and EntityCategoryContains(AiBotUnitInfo.refCategoryT1Mex, oACU:GetFocusUnit()) and oACU:GetFocusUnit():GetFractionComplete() >= 0.7 then
            --Dont run - might as well finish mex as a small chance we wont run for long, the mex might absorb some damage, and the mex may generate a small bit of mass before dying
            if bDebugMessages == true then LOG(sFunctionRef..': Will try and complete construciton of mex') end
        else
            --Run if on low health or shield
            local bAgainstEnemyACUAndMightWin = false

            --If we are closer to enemy base then require a greater threat differential
            local iDistToFriendlyBase
            local iDistToEnemyBase
            if AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.reftClosestFriendlyBase]) == false then
                iDistToFriendlyBase = AiBotUtilities.GetDistanceBetweenPositions(tLZTeamData[AiBotMap.reftClosestFriendlyBase], oACU:GetPosition())
                iDistToEnemyBase = AiBotUtilities.GetDistanceBetweenPositions(tLZTeamData[AiBotMap.reftClosestEnemyBase], oACU:GetPosition())
            else
                --May e.g. be underwater and not have a LZ
                iDistToFriendlyBase = AiBotUtilities.GetDistanceBetweenPositions(oACU:GetPosition(), AiBotMap.GetPlayerStartPosition(oACU:GetAIBrain()))
                iDistToEnemyBase = AiBotUtilities.GetDistanceBetweenPositions(oACU:GetPosition(), AiBotMap.GetPrimaryEnemyBaseLocation(oACU:GetAIBrain()))
            end
            local iPercentageToFriendlyBase = iDistToFriendlyBase / (iDistToFriendlyBase + iDistToEnemyBase)

            if iPlateau > 0 and tLZTeamData[AiBotMap.subrefTThreatEnemyCombatTotal] > 0 then
                local tEnemyACU = EntityCategoryFilterDown(categories.COMMAND, tLZTeamData[AiBotMap.subrefTEnemyUnits])
                if AiBotUtilities.IsTableEmpty(tEnemyACU) == false then
                    if table.getn(tEnemyACU) == 1 then
                        if (tLZTeamData[AiBotMap.subrefLZThreatAllyMobileDFTotal] or 0) + iACUThreat > 1.05 * (tLZTeamData[AiBotMap.subrefLZThreatEnemyMobileDFTotal] or 0) then
                            --If we are closer to enemy base then require a greater threat differential
                            if bDebugMessages == true then LOG(sFunctionRef..': tLZTeamData[AiBotMap.subrefTThreatEnemyCombatTotal]='..(tLZTeamData[AiBotMap.subrefTThreatEnemyCombatTotal] or 'nil')..'; iPercentageToFriendlyBase='..(iPercentageToFriendlyBase or 'nil')..'; tLZTeamData[AiBotMap.subrefLZThreatAllyMobileDFTotal]='..(tLZTeamData[AiBotMap.subrefLZThreatAllyMobileDFTotal] or 'nil')..'; iACUThreat='..(iACUThreat or 'nil')..'; iPlateau='..(iPlateau or 'nil')..'; ACU position='..repru(oACU:GetPosition())..'; Surface height of position='..GetSurfaceHeight(oACU:GetPosition()[1], oACU:GetPosition()[3])) end
                            if iPercentageToFriendlyBase < 0.6 or tLZTeamData[AiBotMap.subrefLZThreatAllyMobileDFTotal] + iACUThreat > 1.25 * tLZTeamData[AiBotMap.subrefLZThreatEnemyMobileDFTotal] then
                                --Dont do this if enemy has air to ground threat and we dont have >= this in MAA
                                if tLZTeamData[AiBotMap.refiEnemyAirToGroundThreat] == 0 or tLZTeamData[AiBotMap.subrefLZOrWZThreatAllyGroundAA] >= 0.25 * tLZTeamData[AiBotMap.refiEnemyAirToGroundThreat] then
                                    bAgainstEnemyACUAndMightWin = true
                                end
                            end
                        end
                    end
                end
            end
            if bDebugMessages == true then LOG(sFunctionRef..': iACUThreat='..(iACUThreat or 'nil')..'; LZ enemy combat total='..(tLZTeamData[AiBotMap.subrefTThreatEnemyCombatTotal] or 'nil')..'; bOneEnemyACUInSameLZ='..tostring(bAgainstEnemyACUAndMightWin or false)..'; tLZTeamData[AiBotMap.subrefLZThreatEnemyMobileDFTotal]='..(tLZTeamData[AiBotMap.subrefLZThreatEnemyMobileDFTotal] or 'nil')..'; tLZTeamData[AiBotMap.subrefLZThreatAllyMobileDFTotal]='..(tLZTeamData[AiBotMap.subrefLZThreatAllyMobileDFTotal] or 'nil')..'; iDistToFriendlyBase='..iDistToFriendlyBase..'; tLZTeamData[AiBotMap.refiModDistancePercent]='..tLZTeamData[AiBotMap.refiModDistancePercent]) end
            if (iACUThreat <= 500 or (iACUThreat <= 600 and (tLZTeamData[AiBotMap.subrefTThreatEnemyCombatTotal] or 0) >= 80)) and (not(bAgainstEnemyACUAndMightWin) or (oACU[refbUseACUAggressively] and (iACUThreat + (tLZTeamData[AiBotMap.subrefLZThreatAllyMobileDFTotal] or 0) + 250 < (tLZTeamData[AiBotMap.subrefTThreatEnemyCombatTotal] or 0)))) then
                if bDebugMessages == true then LOG(sFunctionRef..': ACU has low threat so want to run') end
                bWantToRun = true
            else
                local iCurShield, iMaxShield = AiBotUnitInfo.GetCurrentAndMaximumShield(oACU, true)
                if bDebugMessages == true then LOG(sFunctionRef..'; iCurSHield='..iCurShield..'; iMaxShield='..iMaxShield) end
                if iMaxShield > 0 and iCurShield <= (iMaxShield * 0.1) then
                    if bDebugMessages == true then LOG(sFunctionRef..': ACU shield is less than 10% so want to run') end
                    bWantToRun = true
                else
                    local iHealthPercent = AiBotUnitInfo.GetUnitHealthPercent(oACU)
                    local iPercentMod = 1
                    if oACU[refbUseACUAggressively] then iPercentMod = 0.5 end
                    if bDebugMessages == true then LOG(sFunctionRef..': iHealthPercent='..iHealthPercent) end
                    if (iHealthPercent <= 0.6 * iPercentMod or (iHealthPercent <= 0.75 * iPercentMod and (tLZTeamData[AiBotMap.subrefTThreatEnemyCombatTotal] or 0) >= 80)) and (not(bAgainstEnemyACUAndMightWin) or iHealthPercent <= 0.5 * iPercentMod) then
                        if bDebugMessages == true then LOG(sFunctionRef..': ACU is injured so want to run') end
                        bWantToRun = true
                    else
                        --Do we have a land zone?
                        if iPlateau > 0 and iLandZone > 0 then
                            local iEnemyAirToGroundNearbyThreat = tLZTeamData[AiBotMap.refiEnemyAirToGroundThreat]
                            local iFriendlyAAThreat = tLZTeamData[AiBotMap.subrefLZOrWZThreatAllyGroundAA]
                            --If there are big enemy threats then run if we arent adjacnet to a core LZ
                            local bAdjacentToCoreLZ = false
                            if AiBotUtilities.IsTableEmpty(tLZData[AiBotMap.subrefLZAdjacentLandZones]) == false then
                                for _, iAdjLZ in tLZData[AiBotMap.subrefLZAdjacentLandZones] do
                                    local tAdjLZTeamData = AiBotMap.tAllPlateaus[iPlateau][AiBotMap.subrefPlateauLandZones][iAdjLZ][AiBotMap.subrefLZTeamData][iTeam]
                                    if tAdjLZTeamData[AiBotMap.subrefLZbCoreBase] then bAdjacentToCoreLZ = true end
                                    iEnemyAirToGroundNearbyThreat = iEnemyAirToGroundNearbyThreat + tAdjLZTeamData[AiBotMap.refiEnemyAirToGroundThreat]
                                    iFriendlyAAThreat = iFriendlyAAThreat + tAdjLZTeamData[AiBotMap.subrefLZThreatAllyMAA]
                                end
                            end

                            if AiBotTeam.tTeamData[iTeam][AiBotTeam.refbDangerousForACUs] and ((GetGameTimeSeconds() > 1260 and (iACUThreat < 3500 or AiBotTeam.tTeamData[iTeam][AiBotTeam.refbAssassinationOrSimilar])) or not(tLZTeamData[AiBotMap.subrefbEnemiesInThisOrAdjacentLZ]) or (iACUThreat < 3500 and (iACUThreat < 1700 or oACU[refiUpgradeCount] < 3 or AiBotTeam.tTeamData[iTeam][AiBotTeam.refbAssassinationOrSimilar] or AiBotTeam.tTeamData[iTeam][AiBotTeam.refiConstructedExperimentalCount] > 0 or iHealthPercent < 0.9 or AiBotUnitInfo.GetUnitMaxHealthIncludingShield(oACU) < 20000 or (oACU.MyShield.GetHealth and (iHealthPercent < 0.98 or AiBotUnitInfo.GetUnitHealthAndShieldPercent(oACU) <= 0.95))))) then
                                if AiBotUtilities.IsTableEmpty(tLZData[AiBotMap.subrefLZAdjacentLandZones]) then
                                    if bDebugMessages == true then LOG(sFunctionRef..': No adjacent land zones and dangerous for ACU so want to run') end
                                    bWantToRun = true
                                else
                                    if not(bAdjacentToCoreLZ) then
                                        if bDebugMessages == true then LOG(sFunctionRef..': Not adjacent to core LZ so want to run as it is dangerous for ACUs now, and no nearby enemies to consider attacking') end
                                        bWantToRun = true
                                    end
                                end

                            end
                            if not(bWantToRun) then
                                --Run if non-full share or last ACU, are past 15m in-game, mod dist is >=0.4, and we are far from base
                                if bDebugMessages == true then LOG(sFunctionRef..': Considering if want to run when in assassination, moddist%='..(tLZTeamData[AiBotMap.refiModDistancePercent] or 'nil')..'; Upgrade count='..(oACU[refiUpgradeCount] or 'nil')..'; oACU='..(oACU.UnitId or 'nil')..(AiBotUnitInfo.GetUnitLifetimeCount(oACU) or 'nil')..' owned by '..oACU:GetAIBrain().Nickname..'; iPercentageToFriendlyBase='..(iPercentageToFriendlyBase or 'nil')..'; iDistToFriendlyBase='..(iDistToFriendlyBase or 'nil')..'; AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestFriendlyFactoryTech]='..(AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestFriendlyFactoryTech] or 'nil')..'; AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestEnemyGroundTech]='..(AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestEnemyGroundTech] or 'nil')..'; AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestEnemyAirTech]='..(AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestEnemyAirTech] or 'nil')..'; Assassination='..tostring(AiBotTeam.tTeamData[iTeam][AiBotTeam.refbAssassinationOrSimilar] or false)..'; Brain gross mass='..(oACU:GetAIBrain()[AiBotEconomy.refiGrossMassBaseIncome] or 'nil')) end
                                if tLZTeamData[AiBotMap.refiModDistancePercent] >= 0.35 + 0.04*(oACU[refiUpgradeCount] or 0) and AiBotUtilities.IsTableEmpty(AiBotTeam.tTeamData[iTeam][AiBotTeam.toActiveSnipeTargets]) and iPercentageToFriendlyBase >= 0.35 and iDistToFriendlyBase >= (200 + 75 * (oACU[refiUpgradeCount] or 0)) and (AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestFriendlyFactoryTech] >= 3 or AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestEnemyGroundTech] >= 3 or AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestEnemyAirTech] >= 3 or (GetGameTimeSeconds() >= 900 and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestEnemyGroundTech] > 1)) and (not(AiBotTeam.tTeamData[iTeam][AiBotTeam.refbAssassinationOrSimilar]) or oACU:GetAIBrain()[AiBotEconomy.refiGrossMassBaseIncome] >= 25)
                                        --Exception - if enemy isnt at t3 land yet, and we have a mobile shield assigned to guncom ACU with full health
                                        and (oACU[refiUpgradeCount] == 0 or AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestEnemyGroundTech] >= 3 or oACU:GetAIBrain()[AiBotEconomy.refiGrossMassBaseIncome] >= 30 or tLZTeamData[AiBotMap.refiModDistancePercent] >= 0.6 or not(AiBotUnitInfo.IsUnitValid(oACU[AiBotLand.refoAssignedMobileShield])) or AiBotUnitInfo.GetUnitHealthPercent(oACU) <= 0.97) then
                                    bWantToRun = true
                                    if bDebugMessages == true then LOG(sFunctionRef..': ACU owned by '..oACU:GetAIBrain().Nickname..' is getting a bit far from base so want to run, time='..GetGameTimeSeconds()) end
                                end

                                --Assassination mode - be wary of TML snipes if not in combat and not in core base/near it
                                if bDebugMessages == true then LOG(sFunctionRef..': TML snipe check refiModDistancePercent='..tLZTeamData[AiBotMap.refiModDistancePercent]..'; refbAssassinationOrSimilar='..tostring(AiBotTeam.tTeamData[iTeam][AiBotTeam.refbAssassinationOrSimilar])..'; is reftEnemyTML empty='..tostring(AiBotUtilities.IsTableEmpty(AiBotTeam.tTeamData[iTeam][AiBotTeam.reftEnemyTML]))..'; Time since last ACU weapon event='..GetGameTimeSeconds() - (oACU[AiBotUnitInfo.refiLastWeaponEvent] or 0)) end
                                if not(bWantToRun) and not(tLZTeamData[AiBotMap.subrefLZbCoreBase]) and tLZTeamData[AiBotMap.refiModDistancePercent] >= 0.15 and AiBotTeam.tTeamData[iTeam][AiBotTeam.refbAssassinationOrSimilar] and AiBotUtilities.IsTableEmpty(AiBotTeam.tTeamData[iTeam][AiBotTeam.reftEnemyTML]) == false and GetGameTimeSeconds() - (oACU[AiBotUnitInfo.refiLastWeaponEvent] or 0) >= 40 then
                                    local iEnemyTMLDamagePotential = 0
                                    for iTML, oTML in AiBotTeam.tTeamData[iTeam][AiBotTeam.reftEnemyTML] do
                                        if bDebugMessages == true then LOG(sFunctionRef..': Dist from oTML='..oTML.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oTML)..' to ACU='..AiBotUtilities.GetDistanceBetweenPositions(oTML:GetPosition(), oACU:GetPosition())..'; refiManualRange='..(oTML[AiBotUnitInfo.refiManualRange] or 'nil')) end
                                        if not(oTML.Dead) and EntityCategoryContains(AiBotUnitInfo.refCategoryTML, oTML.UnitId) and AiBotUtilities.GetDistanceBetweenPositions(oTML:GetPosition(), oACU:GetPosition()) < (oTML[AiBotUnitInfo.refiManualRange] or oTML[AiBotUnitInfo.refiIndirectRange] or 256) then
                                            iEnemyTMLDamagePotential = iEnemyTMLDamagePotential + (oTML:GetBlueprint().Weapon[1].Damage or 6000)
                                            if bDebugMessages == true then LOG(sFunctionRef..': Increased iEnemyTMLDamagePotential to '..iEnemyTMLDamagePotential..'; ACU shield+health='..iCurShield+ oACU:GetHealth()) end
                                            if iEnemyTMLDamagePotential >= iCurShield + oACU:GetHealth() then
                                                if bDebugMessages == true then LOG(sFunctionRef..': ACU at risk of TML snipe so want to run') end
                                                bWantToRun = true
                                                break
                                            end
                                        end
                                    end
                                end

                            end
                            if not(bWantToRun) then
                                if bDebugMessages == true then LOG(sFunctionRef..': deciding if want to run from air, iEnemyAirToGroundNearbyThreat='..iEnemyAirToGroundNearbyThreat..'; iFriendlyAAThreat='..(iFriendlyAAThreat or 'nil')..'; iPercentageToFriendlyBase='..(iPercentageToFriendlyBase or 'nil')..'; iDistToFriendlyBase='..(iDistToFriendlyBase or 'nil')..'; Enemy team air to ground threat='..(AiBotTeam.tTeamData[oACU:GetAIBrain().AiBotTeam][AiBotTeam.refiEnemyAirToGroundThreat] or 'nil')..'; ACU health percent='..AiBotUnitInfo.GetUnitHealthPercent(oACU)) end
                                --If significant air to ground threat and not in adjacent to core base LZ then also run; however adjust if have nearby MAA
                                if (iEnemyAirToGroundNearbyThreat > (iFriendlyAAThreat or 0) * 2.5 or iEnemyAirToGroundNearbyThreat >= 1000) and not(bAdjacentToCoreLZ) and (iMaxShield == 0 or tLZTeamData[AiBotMap.subrefLZOrWZThreatAllyGroundAA] < tLZTeamData[AiBotMap.refiEnemyAirToGroundThreat] * 0.5) and (iEnemyAirToGroundNearbyThreat > 150 or not(oACU[refbUseACUAggressively])) and (iEnemyAirToGroundNearbyThreat >= 300 or AiBotTeam.tTeamData[iTeam][AiBotTeam.refiEnemyAirToGroundThreat] >= 400 or iDistToFriendlyBase >= 300 or iPercentageToFriendlyBase > 0.5 or AiBotUnitInfo.GetUnitHealthPercent(oACU) <= 0.75) then
                                    if bDebugMessages == true then LOG(sFunctionRef..': Significant air to ground threat so want to run, iFriendlyAAThreat='..(iFriendlyAAThreat or 0)) end
                                    bWantToRun = true
                                else
                                    local bHighHealthWithStealth = false
                                    if bDebugMessages == true then LOG(sFunctionRef..': If high health and stealth will just attack, otherwise will assess nearby enemy threat, ACU upgrade count='..(oACU[refiUpgradeCount] or 'nil')..'; ACU has stealth, nano, cor cloak='..tostring(oACU:HasEnhancement('StealthGenerator') or oACU:HasEnhancement('FAF_SelfRepairSystem') or oACU:HasEnhancement('CloakingGenerator'))..'; Does ACU have a valid assigned mobile stealth='..tostring(AiBotUnitInfo.IsUnitValid(oACU[AiBotLand.refoAssignedMobileStealth]))..';  tLZTeamData[AiBotMap.refiModDistancePercent]='..tLZTeamData[AiBotMap.refiModDistancePercent]..'; AiBotMap.iMapSize='..AiBotMap.iMapSize..'; AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiActiveAiBotBrainCount]='..AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiActiveAiBotBrainCount]..'; AiBotTeam.tTeamData[iTeam][AiBotTeam. refbAssassinationOrSimilar]='..tostring(AiBotTeam.tTeamData[iTeam][AiBotTeam. refbAssassinationOrSimilar])..'; ScenarioInfo.Options.Victory='..ScenarioInfo.Options.Victory..'; ScenarioInfo.Options.Share='..ScenarioInfo.Options.Share..'; Stealth condition combined='..tostring((oACU:HasEnhancement('StealthGenerator') or oACU:HasEnhancement('FAF_SelfRepairSystem') or oACU:HasEnhancement('CloakingGenerator') or (AiBotUnitInfo.IsUnitValid(oACU[AiBotLand.refoAssignedMobileStealth]) and AiBotUtilities.GetDistanceBetweenPositions(oACU:GetPosition(), oACU[AiBotLand.refoAssignedMobileStealth]:GetPosition()) <= (oACU[AiBotLand.refoAssignedMobileStealth]:GetBlueprint().Intel.RadarStealthFieldRadius or 10))))) end
                                    if iHealthPercent >= 0.99 and oACU[refiUpgradeCount] >= 1 and (oACU:HasEnhancement('StealthGenerator') or oACU:HasEnhancement('FAF_SelfRepairSystem') or oACU:HasEnhancement('CloakingGenerator') or (AiBotUnitInfo.IsUnitValid(oACU[AiBotLand.refoAssignedMobileStealth]) and AiBotUtilities.GetDistanceBetweenPositions(oACU:GetPosition(), oACU[AiBotLand.refoAssignedMobileStealth]:GetPosition()) <= (oACU[AiBotLand.refoAssignedMobileStealth]:GetBlueprint().Intel.RadarStealthFieldRadius or 10))) then
                                        bHighHealthWithStealth = true
                                        if bDebugMessages == true then LOG(sFunctionRef..': Are stealthed and on high health so will ignore enemy threat and be aggressive unless in assassination') end
                                    end
                                    if bHighHealthWithStealth and (oACU[refbUseACUAggressively] or not(AiBotTeam.tTeamData[iTeam][AiBotTeam.refbAssassinationOrSimilar])) then
                                        if bDebugMessages == true then LOG(sFunctionRef..': We have stealth so will ignore rest of potential run from enemy logic') end
                                    else
                                        local iEnemyNearbyThreat = (tLZTeamData[AiBotMap.subrefTThreatEnemyCombatTotal] or 0)
                                        local iEnemyMobileNearbyDFThreat = (tLZTeamData[AiBotMap.subrefLZThreatEnemyMobileDFTotal] or 0)
                                        local aiBrain = oACU:GetAIBrain()
                                        local iTeam = aiBrain.AiBotTeam
                                        local iAllyNearbyThreat
                                        if aiBrain[AiBotEconomy.refiOurHighestLandFactoryTech] == 1 then
                                            iAllyNearbyThreat = math.max(0, (tLZTeamData[AiBotMap.subrefLZTThreatAllyCombatTotal] or 0) - iACUThreat)
                                        else
                                            iAllyNearbyThreat = math.max(0, (tLZTeamData[AiBotMap.subrefLZThreatAllyMobileDFTotal] or 0) - iACUThreat)
                                            if tLZTeamData[AiBotMap.subrefLZThreatAllyStructureDFByRange] then
                                                for iRange, iThreat in tLZTeamData[AiBotMap.subrefLZThreatAllyStructureDFByRange] do
                                                    iAllyNearbyThreat = iAllyNearbyThreat + iThreat
                                                end
                                            end
                                        end
                                        local iAllyAdjacentZoneThreat = 0
                                        local iBestEnemyMobileDFRange = (tLZTeamData[AiBotMap.subrefLZThreatEnemyBestMobileDFRange] or 0)
                                        local iMaxLRThreat = (tLZTeamData[AiBotMap.subrefiNearbyEnemyLongRangeDFThreat] or 0)
                                        local tOutrangedACUs = {}
                                        if iEnemyNearbyThreat > 0 and oACU[refiUpgradeCount] > 0 then
                                            if tLZTeamData[AiBotMap.subrefThreatEnemyDFStructures] > 0 and tLZTeamData[AiBotMap.subrefLZThreatEnemyBestStructureDFRange] < oACU[AiBotUnitInfo.refiDFRange] then iEnemyNearbyThreat = iEnemyNearbyThreat - (tLZTeamData[AiBotMap.subrefThreatEnemyDFStructures] or 0) end
                                            local tEnemyACUs = EntityCategoryFilterDown(categories.COMMAND, tLZTeamData[AiBotMap.subrefTEnemyUnits])
                                            if AiBotUtilities.IsTableEmpty(tEnemyACUs) == false then
                                                for iEnemy, oEnemy in tEnemyACUs do
                                                    if AiBotUnitInfo.IsUnitValid(oEnemy) then
                                                        if (oACU[AiBotUnitInfo.refiDFRange] or 0) > (oEnemy[AiBotUnitInfo.refiDFRange] or 0) then
                                                            table.insert(tOutrangedACUs, oEnemy)
                                                        end
                                                    end
                                                end
                                            end
                                        end
                                        if bDebugMessages == true then LOG(sFunctionRef..': About to consider adjacent zones, iEnemyMobileNearbyDFThreat before considering adjzones='..iEnemyMobileNearbyDFThreat) end


                                        if AiBotUtilities.IsTableEmpty(tLZData[AiBotMap.subrefLZAdjacentLandZones]) == false then
                                            --First get best enemy nearby range
                                            local tbZonesConsidered = {}
                                            local iDistUntilInRangeThreshold = 30 + tLZTeamData[AiBotMap.refiModDistancePercent] * 100
                                            local toDetailedCheckMobileDFUnits
                                            local bConsiderDetailedCheck = false
                                            local iCurDist
                                            if bHighHealthWithStealth or (oACU[refiUpgradeCount] >= 2 and (oACU[refiUpgradeCount] >= 3 or not(EntityCategoryContains(categories.AEON, oACU.UnitId)))) then bConsiderDetailedCheck = true end
                                            for _, iAdjLZ in tLZData[AiBotMap.subrefLZAdjacentLandZones] do
                                                tbZonesConsidered[iAdjLZ] = true
                                                local tAdjLZTeamData = AiBotMap.tAllPlateaus[iPlateau][AiBotMap.subrefPlateauLandZones][iAdjLZ][AiBotMap.subrefLZTeamData][iTeam]
                                                iBestEnemyMobileDFRange = math.max(iBestEnemyMobileDFRange, (tAdjLZTeamData[AiBotMap.subrefLZThreatEnemyBestMobileDFRange] or 0))
                                                if bDebugMessages == true then LOG(sFunctionRef..': Adding threat for iAdjLZ='..iAdjLZ..' with threat subrefTThreatEnemyCombatTotal='..AiBotMap.tAllPlateaus[iPlateau][AiBotMap.subrefPlateauLandZones][iAdjLZ][AiBotMap.subrefLZTeamData][iTeam][AiBotMap.subrefTThreatEnemyCombatTotal]..'; subrefLZThreatAllyMobileDFTotal='..(tAdjLZTeamData[AiBotMap.subrefLZThreatAllyMobileDFTotal] or 'nil')..'; Mobile indirect='..(tAdjLZTeamData[AiBotMap.subrefLZThreatEnemyMobileIndirectTotal] or 0)..'; subrefiNearbyEnemyLongRangeDFThreat='..(tAdjLZTeamData[AiBotMap.subrefiNearbyEnemyLongRangeDFThreat] or 'nil')..'; Enemy best mobile DF range in this LZ='..(tAdjLZTeamData[AiBotMap.subrefLZThreatEnemyBestMobileDFRange] or 0)..'; subrefLZThreatEnemyMobileDFTotal='..(tAdjLZTeamData[AiBotMap.subrefLZThreatEnemyMobileDFTotal] or 0)) end
                                                iEnemyNearbyThreat = iEnemyNearbyThreat + (tAdjLZTeamData[AiBotMap.subrefTThreatEnemyCombatTotal] or 0)
                                                if bConsiderDetailedCheck and (tAdjLZTeamData[AiBotMap.subrefLZThreatEnemyMobileDFTotal] or 0) >= 50 and iEnemyMobileNearbyDFThreat <= 6000 then
                                                    --Do more detailed check
                                                    for iUnit, oUnit in tAdjLZTeamData[AiBotMap.subrefTEnemyUnits] do
                                                        if (oUnit[AiBotUnitInfo.refiDFRange] or 0) > 0 and not(oUnit.Dead) then
                                                            iCurDist = AiBotUtilities.GetDistanceBetweenPositions(oUnit:GetPosition(), oACU:GetPosition())
                                                            if iCurDist - oUnit[AiBotUnitInfo.refiDFRange] < iDistUntilInRangeThreshold and EntityCategoryContains(categories.MOBILE, oUnit.UnitId) then
                                                                if bDebugMessages == true then LOG(sFunctionRef..': Including enemy mobile DF unit '..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..' as iCurDist='..iCurDist..'; and iCurDist less its range, i.e. its distance until in range of our ACU='..AiBotUtilities.GetDistanceBetweenPositions(oUnit:GetPosition(), oACU:GetPosition()) - oUnit[AiBotUnitInfo.refiDFRange]..'; iDistUntilInRangeThreshold='..iDistUntilInRangeThreshold) end
                                                                if not(toDetailedCheckMobileDFUnits) then toDetailedCheckMobileDFUnits = {} end
                                                                table.insert(toDetailedCheckMobileDFUnits, oUnit)
                                                            end
                                                        end
                                                    end
                                                else
                                                    iEnemyMobileNearbyDFThreat = iEnemyMobileNearbyDFThreat + (tAdjLZTeamData[AiBotMap.subrefLZThreatEnemyMobileDFTotal] or 0)
                                                end
                                                if tAdjLZTeamData[AiBotMap.subrefThreatEnemyDFStructures] > 0 and tAdjLZTeamData[AiBotMap.subrefLZThreatEnemyBestStructureDFRange] < oACU[AiBotUnitInfo.refiDFRange] then iEnemyNearbyThreat = iEnemyNearbyThreat - (tAdjLZTeamData[AiBotMap.subrefThreatEnemyDFStructures] or 0) end
                                                iMaxLRThreat = math.max(iMaxLRThreat, (tAdjLZTeamData[AiBotMap.subrefiNearbyEnemyLongRangeDFThreat] or 0))
                                                --Include adjacent enemies assuming ACU has enough health that they are likely to be able to arrive
                                                if iHealthPercent >= 0.65 and (iHealthPercent >= 0.8 or oACU[refbUseACUAggressively] or (iHealthPercent >= 0.35 and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiActiveAiBotBrainCount] > 1 and not(AiBotTeam.tTeamData[iTeam][AiBotTeam.refbAssassinationOrSimilar]))) then
                                                    if bDebugMessages == true then LOG(sFunctionRef..': Including mobile DF threat from adjacent zone in ally total force, tAdjLZTeamData[AiBotMap.subrefLZThreatAllyMobileDFTotal]='..(tAdjLZTeamData[AiBotMap.subrefLZThreatAllyMobileDFTotal] or 'nil')) end
                                                    iAllyAdjacentZoneThreat = iAllyAdjacentZoneThreat + (tAdjLZTeamData[AiBotMap.subrefLZThreatAllyMobileDFTotal] or 0) * 0.9
                                                end
                                                if iMaxLRThreat == 0 and oACU[refiUpgradeCount] > 0 and (tAdjLZTeamData[AiBotMap.subrefTThreatEnemyCombatTotal] or 0) <= 10000 then
                                                    if iBestEnemyMobileDFRange < (oACU[AiBotUnitInfo.refiDFRange] or 0) then --this is testing the mobile range
                                                        --Exclude enemy ACU threat
                                                        local tEnemyACUs = EntityCategoryFilterDown(categories.COMMAND, tAdjLZTeamData[AiBotMap.subrefTEnemyUnits])
                                                        if AiBotUtilities.IsTableEmpty(tEnemyACUs) == false then
                                                            for iEnemy, oEnemy in tEnemyACUs do
                                                                if AiBotUnitInfo.IsUnitValid(oEnemy) then
                                                                    table.insert(tOutrangedACUs, oEnemy)
                                                                end
                                                            end
                                                        end
                                                    end
                                                end
                                            end
                                            if toDetailedCheckMobileDFUnits then
                                                if bDebugMessages == true then LOG(sFunctionRef..': Threat of enemy mobile DF units from detailed check='..AiBotUnitInfo.GetCombatThreatRating(toDetailedCheckMobileDFUnits, true)..'; Threat when excluding ACUs='..AiBotUnitInfo.GetCombatThreatRating(EntityCategoryFilterDown(categories.ALLUNITS - categories.COMMAND, toDetailedCheckMobileDFUnits),true)..'; will add to iEnemyMobileNearbyDFThreat before this='..iEnemyMobileNearbyDFThreat) end
                                                iEnemyMobileNearbyDFThreat = iEnemyMobileNearbyDFThreat + AiBotUnitInfo.GetCombatThreatRating(toDetailedCheckMobileDFUnits, true)
                                            end
                                            --Consider nearby nonadjacent zones as well if ACU on less than 95% threat or has at least 5 mass income
                                            if not(oACU[refbUseACUAggressively]) and (iHealthPercent <= 0.95 or oACU:GetAIBrain()[AiBotEconomy.refiGrossMassBaseIncome] >= 5) then
                                                if AiBotUtilities.IsTableEmpty(tLZData[AiBotMap.subrefLZPathingToOtherLandZones]) == false then
                                                    for iEntry, tSubtable in tLZData[AiBotMap.subrefLZPathingToOtherLandZones] do
                                                        if bDebugMessages == true then LOG(sFunctionRef..': Considering other zone='..tSubtable[AiBotMap.subrefLZNumber]..'; Travel dist='..tSubtable[AiBotMap.subrefLZTravelDist]..'; Considered already='..tostring(tbZonesConsidered[tSubtable[AiBotMap.subrefLZNumber]] or false)) end
                                                        if tSubtable[AiBotMap.subrefLZTravelDist] >= 150 then break
                                                        elseif not(tbZonesConsidered[tSubtable[AiBotMap.subrefLZNumber]]) then
                                                            --Is ACU close to this zone midpoint?
                                                            local tAdjLZData = AiBotMap.tAllPlateaus[iPlateau][AiBotMap.subrefPlateauLandZones][tSubtable[AiBotMap.subrefLZNumber]]
                                                            if bDebugMessages == true then LOG(sFunctionRef..': Dist from ACU to zone midpoint='..AiBotUtilities.GetDistanceBetweenPositions(oACU:GetPosition(), tAdjLZData[AiBotMap.subrefMidpoint])) end
                                                            if AiBotUtilities.GetDistanceBetweenPositions(oACU:GetPosition(), tAdjLZData[AiBotMap.subrefMidpoint]) <= 100 then
                                                                local tAdjLZTeamData = tAdjLZData[AiBotMap.subrefLZTeamData][iTeam]
                                                                iEnemyNearbyThreat = iEnemyNearbyThreat + math.max(0, (tAdjLZTeamData[AiBotMap.subrefTThreatEnemyCombatTotal] or 0) - (tAdjLZTeamData[AiBotMap.subrefLZTThreatAllyCombatTotal] or 0))
                                                            end
                                                        end
                                                    end
                                                end
                                            end


                                            if bDebugMessages == true then LOG(sFunctionRef..': iBestEnemyMobileDFRange='..iBestEnemyMobileDFRange..'; oACU[AiBotUnitInfo.refiDFRange]='..oACU[AiBotUnitInfo.refiDFRange]..'; iAllyNearbyThreat pre update for adj='..iAllyNearbyThreat..'; iAllyAdjacentZoneThreat='..iAllyAdjacentZoneThreat) end
                                            --Include ally threat if we arent outranged or our relatively near our base with a gun upgrade
                                            if (iBestEnemyMobileDFRange <= oACU[AiBotUnitInfo.refiDFRange] and (oACU[refbUseACUAggressively] or AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiActiveAiBotBrainCount] > 1)) or (iPercentageToFriendlyBase <= 0.4 and iDistToFriendlyBase <= 275 and (oACU[refiUpgradeCount] or 0) >= 1 and AiBotUnitInfo.GetUnitHealthPercent(oACU) >= 0.75)  then
                                                --Have nearby allies so can be more aggressive
                                                iAllyNearbyThreat = iAllyNearbyThreat + iAllyAdjacentZoneThreat
                                            end
                                        end

                                        --If adjacent water zones then include enemy surface threat units if ACU is damaged
                                        if bDebugMessages == true then LOG(sFunctionRef..': Considering nearby water zone threats, is table of adjacent water zones empty='..tostring(AiBotUtilities.IsTableEmpty(tLZData[AiBotMap.subrefAdjacentWaterZones]))) end
                                        if not(bHighHealthWithStealth) and (iHealthPercent <= 0.95 or AiBotTeam.tTeamData[iTeam][AiBotTeam.refbAssassinationOrSimilar]) and AiBotUtilities.IsTableEmpty(tLZData[AiBotMap.subrefAdjacentWaterZones]) == false then
                                            local tWaterEnemiesNearACU = {}
                                            local iAdjWZ
                                            local iBestEnemyDFWaterUnitRange = 0
                                            for _, tSubtable in tLZData[AiBotMap.subrefAdjacentWaterZones] do
                                                iAdjWZ = tSubtable[AiBotMap.subrefAWZRef]
                                                local tAdjWZTeamData = AiBotMap.tPondDetails[AiBotMap.tiPondByWaterZone[iAdjWZ]][AiBotMap.subrefPondWaterZones][iAdjWZ][AiBotMap.subrefWZTeamData][iTeam]
                                                if bDebugMessages == true then LOG(sFunctionRef..': Considering iAdjWZ='..iAdjWZ..'; Enemy surface threat in this zone='..(tAdjWZTeamData[AiBotMap.subrefWZThreatEnemyVsSurface] or 'nil')) end
                                                if (tAdjWZTeamData[AiBotMap.subrefWZThreatEnemyVsSurface] or 0) > 100 then
                                                    local tEnemiesInWZ = EntityCategoryFilterDown(AiBotUnitInfo.refCategoryNavalSurface + AiBotUnitInfo.refCategoryAmphibiousCombat, tAdjWZTeamData[AiBotMap.subrefTEnemyUnits])
                                                    if AiBotUtilities.IsTableEmpty(tEnemiesInWZ) == false then
                                                        for iEnemy, oEnemy in tEnemiesInWZ do
                                                            if bDebugMessages == true and not(oEnemy.Dead) then LOG(sFunctionRef..': Considering water zone oEnemy='..oEnemy.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oEnemy)..'; Dist to ACU='..AiBotUtilities.GetDistanceBetweenPositions(oEnemy:GetPosition(), oACU:GetPosition())..'; Combat range='..oEnemy[AiBotUnitInfo.refiCombatRange]) end
                                                            if not(oEnemy.Dead) and (oEnemy[AiBotUnitInfo.refiDFRange] or 0) >= 20 and AiBotUtilities.GetDistanceBetweenPositions(oEnemy:GetPosition(), oACU:GetPosition()) - oEnemy[AiBotUnitInfo.refiDFRange] <= 20 then
                                                                table.insert(tWaterEnemiesNearACU, oEnemy)
                                                                iBestEnemyDFWaterUnitRange = math.max(oEnemy[AiBotUnitInfo.refiDFRange], iBestEnemyDFWaterUnitRange)
                                                            end
                                                        end
                                                    end
                                                end
                                            end
                                            if AiBotUtilities.IsTableEmpty(tWaterEnemiesNearACU) == false then
                                                if bDebugMessages == true then LOG(sFunctionRef..': Threat of water enemies near ACU='..AiBotUnitInfo.GetCombatThreatRating(tWaterEnemiesNearACU, true, false)..'; iBestEnemyDFWaterUnitRange='..iBestEnemyDFWaterUnitRange..'; Will increase enemy threat value if they significantly outrange us') end
                                                if iBestEnemyDFWaterUnitRange > math.max(40, (oACU[AiBotUnitInfo.refiDFRange] or 0) + 5) then
                                                    iEnemyNearbyThreat = iEnemyNearbyThreat + AiBotUnitInfo.GetCombatThreatRating(tWaterEnemiesNearACU, true, false) * 1.5
                                                else
                                                    iEnemyNearbyThreat = iEnemyNearbyThreat + AiBotUnitInfo.GetCombatThreatRating(tWaterEnemiesNearACU, true, false) * 1.5
                                                end
                                            end
                                        end
                                        if iMaxLRThreat > 0 then
                                            iEnemyNearbyThreat = iEnemyNearbyThreat + iMaxLRThreat
                                            iEnemyMobileNearbyDFThreat = iEnemyMobileNearbyDFThreat + iMaxLRThreat
                                        end
                                        if bDebugMessages == true then LOG(sFunctionRef..': Considering whether to reduce enemy mobileDF threat for enemy ACU threat, iMaxLRThreat='..iMaxLRThreat..'; Is tOutrangedACUs empty='..tostring(AiBotUtilities.IsTableEmpty(tOutrangedACUs))..'; iBestEnemyMobileDFRange='..iBestEnemyMobileDFRange..'; oACU[AiBotUnitInfo.refiDFRange]='..oACU[AiBotUnitInfo.refiDFRange]) end
                                        if iMaxLRThreat == 0 and AiBotUtilities.IsTableEmpty(tOutrangedACUs) == false and (iBestEnemyMobileDFRange < oACU[AiBotUnitInfo.refiDFRange] or (iHealthPercent >= 0.9 and not(AiBotTeam.tTeamData[iTeam][AiBotTeam.refbAssassinationOrSimilar]))) then
                                            local iAmountToReduceThreatBy
                                            local iCurThreatReduction
                                            for iEnemyACU, oEnemyACU in tOutrangedACUs do
                                                if oEnemyACU:IsUnitState('Building') or (oEnemyACU:IsUnitState('Upgrading') and oEnemyACU:GetWorkProgress() <= 0.95) then
                                                    if AiBotUnitInfo.CanSeeUnit(oACU:GetAIBrain(), oEnemyACU, false) then
                                                        iCurThreatReduction = 0.9
                                                    elseif AiBotUtilities.GetDistanceBetweenPositions(oACU:GetPosition(), oEnemyACU:GetPosition()) > 4 + (oEnemyACU[AiBotUnitInfo.refiDFRange] or 0) and (tLZTeamData[AiBotMap.refiRadarCoverage] >= 30 or (AiBotUnitInfo.IsUnitValid(oACU[AiBotLand.refoAssignedLandScout]) and AiBotUtilities.GetDistanceBetweenPositions(oACU[AiBotLand.refoAssignedLandScout]:GetPosition(), oACU:GetPosition()) <= 25) and (oEnemyACU[refiUpgradeCount] == 0 or not(EntityCategoryContains(categories.CYBRAN, oEnemyACU.UnitId)) or (not(oEnemyACU:HasEnhancement('StealthGenerator')) and not(oEnemyACU:HasEnhancement('CloakingGenerator')) and not(oEnemyACU:HasEnhancement('FAF_SelfRepairSystem'))))) then
                                                        iCurThreatReduction = 0.8
                                                    else
                                                        iCurThreatReduction = 0.7
                                                    end
                                                elseif AiBotUtilities.GetDistanceBetweenPositions(oACU:GetPosition(), oEnemyACU:GetPosition()) > 4 + (oEnemyACU[AiBotUnitInfo.refiDFRange] or 0) then
                                                    if AiBotUnitInfo.CanSeeUnit(oACU:GetAIBrain(), oEnemyACU, false) then
                                                        iCurThreatReduction = 0.8
                                                    elseif tLZTeamData[AiBotMap.refiRadarCoverage] >= 30 or (AiBotUnitInfo.IsUnitValid(oACU[AiBotLand.refoAssignedLandScout]) and AiBotUtilities.GetDistanceBetweenPositions(oACU[AiBotLand.refoAssignedLandScout]:GetPosition(), oACU:GetPosition()) <= 25) and (oEnemyACU[refiUpgradeCount] == 0 or not(EntityCategoryContains(categories.CYBRAN, oEnemyACU.UnitId)) or (not(oEnemyACU:HasEnhancement('StealthGenerator')) and not(oEnemyACU:HasEnhancement('CloakingGenerator')) and not(oEnemyACU:HasEnhancement('FAF_SelfRepairSystem')))) then
                                                        iCurThreatReduction = 0.7
                                                    else iCurThreatReduction = 0.4
                                                    end
                                                else iCurThreatReduction = 0
                                                end
                                                if bDebugMessages == true then LOG(sFunctionRef..': Reducing enemy threat by ACU threat reduction, enemy ACU owner='..oEnemyACU:GetAIBrain().Nickname..'; iCurThreatReduction='..iCurThreatReduction..'; ACU threat (100%)='..AiBotUnitInfo.GetCombatThreatRating({ oEnemyACU}, true, false)..'; Enemy ACU state='..AiBotUnitInfo.GetUnitState(oEnemyACU)) end
                                                if iCurThreatReduction > 0 then
                                                    iAmountToReduceThreatBy = AiBotUnitInfo.GetCombatThreatRating({ oEnemyACU}, true, false) * iCurThreatReduction
                                                    iEnemyNearbyThreat = iEnemyNearbyThreat - iAmountToReduceThreatBy
                                                    iEnemyMobileNearbyDFThreat = iEnemyMobileNearbyDFThreat - iAmountToReduceThreatBy
                                                end
                                            end
                                            --Be more aggressive if enemy ACUs that we outrange (to the point of being dangerous) if not in assassination
                                            if not(AiBotTeam.tTeamData[iTeam][AiBotTeam.refbAssassinationOrSimilar]) and iHealthPercent >= 0.9 then iEnemyNearbyThreat = iEnemyNearbyThreat - AiBotUnitInfo.GetCombatThreatRating(tOutrangedACUs, true, false) * 0.4 end
                                        end

                                        if bDebugMessages == true then LOG(sFunctionRef..': iEnemyNearbyThreat='..iEnemyNearbyThreat..'; iACUThreat='..iACUThreat..'; iEnemyMobileNearbyDFThreat='..iEnemyMobileNearbyDFThreat..'; bAgainstEnemyACUAndMightWin='..tostring(bAgainstEnemyACUAndMightWin or false)..'; iPercentageToFriendlyBase='..iPercentageToFriendlyBase..'; bAdjacentToCoreLZ='..tostring(bAdjacentToCoreLZ)..'; iAllyNearbyThreat='..iAllyNearbyThreat..'; iMaxLRThreat='..iMaxLRThreat..'; ACU cur health+shield='..AiBotUnitInfo.GetUnitCurHealthAndShield(oACU)..'; ACU cur health+shield%='..AiBotUnitInfo.GetUnitHealthAndShieldPercent(oACU)..'; GetHighestOtherTeamT2AndT3MexCount='..AiBotConditions.GetHighestOtherTeamT2AndT3MexCount(iTeam)..'; our refiMexCountByTech: T3='..(AiBotTeam.tTeamData[iTeam][AiBotTeam.refiMexCountByTech][3] or 0)..'; T2='..(AiBotTeam.tTeamData[iTeam][AiBotTeam.refiMexCountByTech][2] or 0)..'; Row1 Cond='..tostring(iEnemyNearbyThreat > math.min(math.max(iACUThreat * 2, iACUThreat * 0.75 + iAllyNearbyThreat), 4000 + 2000 * AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiActiveAiBotBrainCount]) and (iEnemyNearbyThreat > math.max(iACUThreat * 3, iACUThreat + iAllyNearbyThreat) or ((not(bAgainstEnemyACUAndMightWin) and iPercentageToFriendlyBase >= 0.35 and not(bAdjacentToCoreLZ) and not(oACU[refbUseACUAggressively])))))..'; Row2 Cond='..tostring((iACUThreat < iEnemyMobileNearbyDFThreat * 1.1 or iACUThreat * 3 < iEnemyNearbyThreat))..'; Row 3 Cond='..tostring((iACUThreat < 1500 or oACU[refiUpgradeCount] <= 2 or AiBotUnitInfo.GetUnitHealthAndShieldPercent(oACU) <= 0.9 or AiBotTeam.tTeamData[iTeam][AiBotTeam.refbAssassinationOrSimilar] or AiBotUnitInfo.GetUnitCurHealthAndShield(oACU) <= 18000 or GetGameTimeSeconds() >= 1500 or tLZTeamData[AiBotMap.refiModDistancePercent] >= 0.75 or (tLZTeamData[AiBotMap.refiModDistancePercent] >= 0.3 + 0.1 * AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiActiveAiBotBrainCount])))..'; Row4 Cond='..tostring((iACUThreat < 1700 or oACU[refiUpgradeCount] < 3 or AiBotUnitInfo.GetUnitHealthAndShieldPercent(oACU) <= 0.95 or tLZTeamData[AiBotMap.refiModDistancePercent] >= 0.55 or AiBotMap.iMapSize >=700 or AiBotConditions.GetHighestOtherTeamT2AndT3MexCount(iTeam) * 1.3 + 1 < (AiBotTeam.tTeamData[iTeam][AiBotTeam.refiMexCountByTech][3] or 0) + (AiBotTeam.tTeamData[iTeam][AiBotTeam.refiMexCountByTech][2] or 0)))) end
                                        --Run if enemy has a really large threat (regardless of if we think we can beat it) subject to some exceptions
                                        if iEnemyNearbyThreat > math.min(math.max(iACUThreat * 2, iACUThreat * 0.75 + iAllyNearbyThreat), 4000 + 2000 * AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiActiveAiBotBrainCount]) and (iEnemyNearbyThreat > math.max(iACUThreat * 3, iACUThreat + iAllyNearbyThreat) or ((not(bAgainstEnemyACUAndMightWin) and iPercentageToFriendlyBase >= 0.35 and not(bAdjacentToCoreLZ) and not(oACU[refbUseACUAggressively])))) --row1 cond
                                                and (iACUThreat < iEnemyMobileNearbyDFThreat * 1.1 or iACUThreat * 3 < iEnemyNearbyThreat) --row2 cond
                                                --In teamgames want ACU with shield to be more aggressive
                                                and (iACUThreat < 1500 or oACU[refiUpgradeCount] <= 2 or AiBotUnitInfo.GetUnitHealthAndShieldPercent(oACU) <= 0.9 or AiBotTeam.tTeamData[iTeam][AiBotTeam.refbAssassinationOrSimilar] or AiBotUnitInfo.GetUnitCurHealthAndShield(oACU) <= 18000 or GetGameTimeSeconds() >= 1500 or tLZTeamData[AiBotMap.refiModDistancePercent] >= 0.75 or (tLZTeamData[AiBotMap.refiModDistancePercent] >= 0.3 + 0.1 * AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiActiveAiBotBrainCount])) --row3 cond
                                                and (iACUThreat < 1700 or oACU[refiUpgradeCount] < 3 or AiBotUnitInfo.GetUnitHealthAndShieldPercent(oACU) <= 0.95 or tLZTeamData[AiBotMap.refiModDistancePercent] >= 0.55 or AiBotMap.iMapSize >=700 or AiBotConditions.GetHighestOtherTeamT2AndT3MexCount(iTeam) * 1.3 + 1 < (AiBotTeam.tTeamData[iTeam][AiBotTeam.refiMexCountByTech][3] or 0) + (AiBotTeam.tTeamData[iTeam][AiBotTeam.refiMexCountByTech][2] or 0)) --row4 cond
                                        then
                                            if bDebugMessages == true then LOG(sFunctionRef..': Enemy has too large a threat so will run') end
                                            bWantToRun = true
                                        else
                                            --Run if we dont have enough threat to easily beat enemy threat in all adjacent LZs
                                            local iACUFactor = 0.5
                                            if bAgainstEnemyACUAndMightWin then iACUFactor = 1
                                            elseif bAdjacentToCoreLZ then iACUFactor = 0.9
                                            elseif iPercentageToFriendlyBase <= 0.4 then iACUFactor = 0.8
                                            elseif iPercentageToFriendlyBase <= 0.6 then
                                                if AiBotUnitInfo.GetUnitHealthPercent(oACU) >= 0.9 then iACUFactor = 0.7
                                                else iACUFactor = 0.6
                                                end
                                            end
                                            --Increase ACU factor if we have gun and good health, and enemy lacks T3 land/high health units
                                            if bDebugMessages == true then LOG(sFunctionRef..': ACU health%='..AiBotUnitInfo.GetUnitHealthPercent(oACU)..'; Highest enemy ground tech='..AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestEnemyGroundTech]..'; Highest enemy air tech='..AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestEnemyAirTech]..'; Air to gorund threat='..AiBotTeam.tTeamData[iTeam][AiBotTeam.refiEnemyAirToGroundThreat]) end
                                            if AiBotUnitInfo.GetUnitHealthPercent(oACU) >= 0.8 and (oACU[refiUpgradeCount] or 0) >= 1 and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestEnemyGroundTech] < 3 and  AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestEnemyAirTech] < 3 and AiBotTeam.tTeamData[iTeam][AiBotTeam.refiEnemyAirToGroundThreat] <= 1500 then
                                                if bDebugMessages == true then LOG(sFunctionRef..': Guncom with decent health and enemy doesnt have T3 land or air or significant air to ground threat so increasing factor') end
                                                iACUFactor = iACUFactor * 1.1
                                                if iPercentageToFriendlyBase <= 0.45 then
                                                    iACUFactor = iACUFactor * 1.1
                                                end
                                            end

                                            --Decrease ACU factor if we have high mass income and are in assassination and dont have many upgrades
                                            local iAllyNearbyThreatFactor = 1
                                            if oACU:GetAIBrain()[AiBotEconomy.refiGrossMassBaseIncome] >= 10 and AiBotTeam.tTeamData[iTeam][AiBotTeam.refbAssassinationOrSimilar] and oACU[refiUpgradeCount] < 3 then
                                                if bDebugMessages == true then LOG(sFunctionRef..': Reducing ACU factor as are in assassination mode or similar') end
                                                if oACU[refiUpgradeCount] > 0 and AiBotUnitInfo.GetUnitHealthPercent(oACU) >= 0.95 and (AiBotTeam.tTeamData[iTeam][AiBotTeam.refiMexCountByTech][3] or 0) <= 1 and AiBotConditions.GetHighestOtherTeamT3MexCount(iTeam) <= 1 and tLZTeamData[AiBotMap.refiModDistancePercent] <= 0.35 then
                                                    iACUFactor = iACUFactor * 0.85
                                                else
                                                    iACUFactor = iACUFactor * 0.6
                                                    iAllyNearbyThreatFactor = 0.8
                                                end
                                            end

                                            --Increase ACU factor if enemy lacks much mobile threat
                                            if iEnemyMobileNearbyDFThreat < 0.5 * iEnemyNearbyThreat and iEnemyMobileNearbyDFThreat * 1.2 < iACUThreat and not(AiBotTeam.tTeamData[iTeam][AiBotTeam.refbAssassinationOrSimilar]) then iACUFactor = iACUFactor * 1.25 end
                                            if bHighHealthWithStealth then iACUFactor = iACUFactor * 1.2 end

                                            --Increase ACU factor if enemy has ACU but we outrange it and all other mobile DF units (this is in addition to the enemy threat reduction above)
                                            if bDebugMessages == true then LOG(sFunctionRef..': Will adjust ACUFactor if we outrange mobile enemies and they have an outranged ACU in this or adjacent zone, iBestEnemyMobileDFRange='..iBestEnemyMobileDFRange..'; oACU[AiBotUnitInfo.refiDFRange]='..(oACU[AiBotUnitInfo.refiDFRange] or 'nil')..'; Is tOutrangedACUs empty='..tostring(AiBotUtilities.IsTableEmpty(tOutrangedACUs))..'; iHealthPercent='..iHealthPercent) end
                                            if iBestEnemyMobileDFRange < (oACU[AiBotUnitInfo.refiDFRange] or 0) and AiBotUtilities.IsTableEmpty(tOutrangedACUs) == false and iHealthPercent >= 0.8 and not(AiBotTeam.tTeamData[iTeam][AiBotTeam.refbAssassinationOrSimilar]) then
                                                --Double check we arent so close to the enemy ACU that it can soon hit us
                                                local bEnemyACUAlmostAbleToShootUs = false
                                                for iEnemyACU, oEnemyACU in tOutrangedACUs do
                                                    if oEnemyACU[AiBotUnitInfo.refiDFRange] and AiBotUtilities.GetDistanceBetweenPositions(oEnemyACU:GetPosition(), oACU:GetPosition()) - oEnemyACU[AiBotUnitInfo.refiDFRange] <= 4 then
                                                        bEnemyACUAlmostAbleToShootUs = true
                                                        break
                                                    end
                                                end
                                                if not(bEnemyACUAlmostAbleToShootUs) then
                                                    if oACU[refiUpgradeCount] >= 2 and (oACU[refiUpgradeCount] >= 3 or not(EntityCategoryContains(categories.AEON, oACU.UnitId))) and iHealthPercent >= 0.9 then
                                                        iACUFactor = iACUFactor * 1.3
                                                    else
                                                        iACUFactor = iACUFactor * 1.15
                                                    end
                                                end
                                            end

                                            --Increase ACU factor in teamgame or if behind on eco if have shield
                                            if oACU[refiUpgradeCount] >= 3 and iACUThreat >= 1500 and AiBotTeam.tTeamData[iTeam][AiBotTeam.refiConstructedExperimentalCount] == 0 and ((not(AiBotTeam.tTeamData[iTeam][AiBotTeam.refbAssassinationOrSimilar]) and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiActiveAiBotBrainCount] >= 2) or AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossMass] < 1.1 * aiBrain[AiBotEconomy.refiBrainResourceMultiplier] * AiBotConditions.GetEnemyTeamActualMassIncome(iTeam)) and ((oACU.MyShield.GetHealth and iHealthPercent >= 0.98 and AiBotUnitInfo.GetUnitHealthAndShieldPercent(oACU) >= 0.9) or (oACU:GetMaxHealth() >= 26000 and iHealthPercent >= 0.9)) then
                                                iACUFactor = iACUFactor + iACUFactor * 0.4 / iACUFactor
                                                if bDebugMessages == true then LOG(sFunctionRef..': Will be very aggressive due to ACU having shield or very high health') end
                                            end
                                            if bDebugMessages == true then LOG(sFunctionRef..': Will consider if should run, iACUThreat='..iACUThreat..'; iACUFactor='..iACUFactor..'; tLZTeamData[AiBotMap.subrefLZTThreatAllyCombatTotal]='..(tLZTeamData[AiBotMap.subrefLZTThreatAllyCombatTotal] or 'nil')..'; iEnemyNearbyThreat='..iEnemyNearbyThreat..'; Ally mobile DF total='..(tLZTeamData[AiBotMap.subrefLZThreatAllyMobileDFTotal] or 0)..'; iAllyNearbyThreat='..iAllyNearbyThreat..'; iAllyNearbyThreatFactor='..iAllyNearbyThreatFactor) end

                                            --NOTE: subrefLZTThreatAllyCombatTotal includes the ACU threat
                                            if not(oACU[refbUseACUAggressively]) and (iACUThreat * iACUFactor + iAllyNearbyThreat * iAllyNearbyThreatFactor < iEnemyNearbyThreat) and iEnemyMobileNearbyDFThreat >= iACUThreat * iACUFactor
                                                    --Slightly increase ACU factor if have shield/lots of upgrade on a small map with low mod distance and not significantly ahead on eco
                                                    and (iACUThreat < 1700 or oACU[refiUpgradeCount] < 3 or tLZTeamData[AiBotMap.refiModDistancePercent] >= 0.55 or AiBotMap.iMapSize >=700 or iACUThreat * (iACUFactor + 0.3) + iAllyNearbyThreat < iEnemyNearbyThreat or AiBotUnitInfo.GetUnitHealthAndShieldPercent(oACU) <= 0.95 or AiBotConditions.GetHighestOtherTeamT2AndT3MexCount(iTeam) * 1.3 + 1 < (AiBotTeam.tTeamData[iTeam][AiBotTeam.refiMexCountByTech][3] or 0) + (AiBotTeam.tTeamData[iTeam][AiBotTeam.refiMexCountByTech][2] or 0))

                                            then
                                                if bDebugMessages == true then LOG(sFunctionRef..': Will run based on ACUThreat and nearby ally and enemy threat') end
                                                bWantToRun = true
                                                --Be more cautious in assassination mode
                                            elseif iHealthPercent < 0.75 and not(oACU[refbUseACUAggressively]) and not(bWantToRun) and AiBotTeam.tTeamData[iTeam][AiBotTeam.refbAssassinationOrSimilar] and iACUThreat * math.min(1, iACUFactor) < iEnemyNearbyThreat * 1.25 and AiBotUtilities.GetDistanceBetweenPositions(oACU:GetPosition(), tLZTeamData[AiBotMap.reftClosestFriendlyBase]) >= 25 then
                                                bWantToRun = true
                                                if bDebugMessages == true then LOG(sFunctionRef..': We think we can win but our ACU is getting low health and if we lose it we lose the game so will retreat') end
                                            else
                                                --If enemy has an upgrading or upgraded ACU relatively nearby and we dont have any upgrades then run - think we already ahve this covered in earlier step
                                                --[[local bEnemyHasNearbyUpgradedACU = false
                                                local iCurEnemyACUDist
                                                if (oACU[refiUpgradeCount] or 0) == 0 and AiBotTeam.tTeamData[iTeam][AiBotTeam.refbEnemyHasUpgradedACU] then
                                                    local iClosestEnemyACU = 10000

                                                    for iEnemyACU, oEnemyACU in AiBotTeam.tTeamData[iTeam][AiBotTeam.reftEnemyACUs] do
                                                        iCurEnemyACUDist = AiBotUtilities.GetDistanceBetweenPositions(oEnemyACU:GetPosition(), oACU:GetPosition())
                                                        if iCurEnemyACUDist < iClosestEnemyACU then iClosestEnemyACU = iCurEnemyACUDist end
                                                    end
                                                    if iClosestEnemyACU <= 54 then bEnemyHasNearbyUpgradedACU = true end
                                                end
                                                if bDebugMessages == true then LOG(sFunctionRef..': Checking if enemy has nearby guncom, ACU upgrade count='..(oACU[refiUpgradeCount] or 0)..'; Enemy has upgraded ACU='..tostring(AiBotTeam.tTeamData[iTeam][AiBotTeam.refbEnemyHasUpgradedACU])..'; iClosestEnemyACU='..(iClosestEnemyACU or 'nil')..'; bEnemyHasNearbyUpgradedACU='..tostring(bEnemyHasNearbyUpgradedACU)) end
                                                if bEnemyHasNearbyUpgradedACU then
                                                    bWantToRun = true
                                                else--]]

                                                --If enemy units are between us and the closest friendly base then also want to run; also run if enemy has multiple T2+ PD as part of the enemy threat and we lack upgrades
                                                if bDebugMessages == true then LOG(sFunctionRef..': Considering if should run from PD, or if enemies closer to our base than we are, iEnemyNearbyThreat='..(iEnemyNearbyThreat or 'nil')..'; oACU[refbUseACUAggressively]='..tostring(oACU[refbUseACUAggressively] or false)..'; ACU upgrade count='..(oACU[refiUpgradeCount] or 0)..'; tLZTeamData[AiBotMap.subrefLZTThreatAllyCombatTotal] ='..(tLZTeamData[AiBotMap.subrefLZTThreatAllyCombatTotal] or 'nil')) end
                                                if iEnemyNearbyThreat > 800 or (iEnemyNearbyThreat > 400 and not(oACU[refbUseACUAggressively])) then
                                                    --Enemy PD check - if enemy has T2+/long range PD and we lack 3 upgrades, then make it more likely we run
                                                    local bEnemyHasPDOrSignificantACUs = false
                                                    local iAggressiveFactor = 1
                                                    if oACU[refbUseACUAggressively] and iPercentageToFriendlyBase <= 0.3 then iAggressiveFactor = 1.5 end
                                                    --Decrease ACU factor and aggressive factor if enemy has more ACUs than us that have similar range to us and arent close to our base, and has significant nearby threat
                                                    if tLZTeamData[AiBotMap.refiModDistancePercent] >= 0.25 and iEnemyNearbyThreat >= 1200 then
                                                        local iNearbyEnemyACUWithGoodRangeCount = 0
                                                        local iTotalNearbyEnemyACUCount = 0
                                                        if AiBotUtilities.IsTableEmpty(AiBotTeam.tTeamData[iTeam][AiBotTeam.reftEnemyACUs]) == false then
                                                            for iEnemyACU, oEnemyACU in AiBotTeam.tTeamData[iTeam][AiBotTeam.reftEnemyACUs] do
                                                                if AiBotUnitInfo.IsUnitValid(oEnemyACU) then
                                                                    if bDebugMessages == true then LOG(sFunctionRef..': Dist of enemy ACU owned by brain '..oEnemyACU:GetAIBrain().Nickname..' to us='..AiBotUtilities.GetDistanceBetweenPositions(oACU:GetPosition(), oEnemyACU:GetPosition())..'; Their combat range='..oEnemyACU[AiBotUnitInfo.refiCombatRange]) end
                                                                    if AiBotUtilities.GetDistanceBetweenPositions(oACU:GetPosition(), oEnemyACU:GetPosition()) <= 30 + oEnemyACU[AiBotUnitInfo.refiCombatRange] then
                                                                        iTotalNearbyEnemyACUCount = iTotalNearbyEnemyACUCount + 1
                                                                        if oEnemyACU[AiBotUnitInfo.refiCombatRange] >= oACU[AiBotUnitInfo.refiDFRange] - 3 then
                                                                            iNearbyEnemyACUWithGoodRangeCount = iNearbyEnemyACUWithGoodRangeCount + 1
                                                                        end
                                                                    end
                                                                end
                                                            end
                                                            if iTotalNearbyEnemyACUCount >= 2 then
                                                                local iNearbyFriendlyACUWithGoodRangeCount = 0
                                                                local iNearbyFriendlyACUCount = 0
                                                                --Get nearby friendly ACUs
                                                                for iFriendlyACU, oFriendlyACU in AiBotTeam.tTeamData[iTeam][AiBotTeam.reftAiBotACUs] do
                                                                    if AiBotUnitInfo.IsUnitValid(oFriendlyACU) then
                                                                        if bDebugMessages == true then LOG(sFunctionRef..': Dist of friendly ACU owned by brain '..oFriendlyACU:GetAIBrain().Nickname..' to us='..AiBotUtilities.GetDistanceBetweenPositions(oACU:GetPosition(), oFriendlyACU:GetPosition())..'; Their combat range='..oFriendlyACU[AiBotUnitInfo.refiCombatRange]) end
                                                                        if AiBotUtilities.GetDistanceBetweenPositions(oACU:GetPosition(), oFriendlyACU:GetPosition()) <= 20 + oFriendlyACU[AiBotUnitInfo.refiCombatRange] then
                                                                            iNearbyFriendlyACUCount = iNearbyFriendlyACUCount + 1
                                                                            if oFriendlyACU[AiBotUnitInfo.refiCombatRange] >= oACU[AiBotUnitInfo.refiDFRange] - 3 then
                                                                                iNearbyFriendlyACUWithGoodRangeCount = iNearbyFriendlyACUWithGoodRangeCount + 1
                                                                            end
                                                                        end
                                                                    end
                                                                end
                                                                if iNearbyEnemyACUWithGoodRangeCount >= 4 or iNearbyEnemyACUWithGoodRangeCount > iNearbyFriendlyACUCount or (iNearbyEnemyACUWithGoodRangeCount >= iNearbyFriendlyACUWithGoodRangeCount and iTotalNearbyEnemyACUCount > iNearbyFriendlyACUWithGoodRangeCount) then
                                                                    iACUFactor = iACUFactor * 0.8
                                                                    iAggressiveFactor = math.min(0.9, iAggressiveFactor * 0.7)
                                                                    bEnemyHasPDOrSignificantACUs = true
                                                                    if bDebugMessages == true then LOG(sFunctionRef..': will be significantly more cautious given enemy has more ACUs') end
                                                                elseif iTotalNearbyEnemyACUCount > iNearbyFriendlyACUCount then
                                                                    iACUFactor = iACUFactor * 0.9
                                                                    iAggressiveFactor = iAggressiveFactor * 0.85
                                                                    bEnemyHasPDOrSignificantACUs = true
                                                                    if bDebugMessages == true then LOG(sFunctionRef..': Will be a bit more cautious given more enemy ACUs than friendly ACUs') end
                                                                end
                                                                if bDebugMessages == true then LOG(sFunctionRef..': iNearbyFriendlyACUCount='..iNearbyFriendlyACUCount..'; iNearbyEnemyACUWithGoodRangeCount='..iNearbyEnemyACUWithGoodRangeCount..'; iTotalNearbyEnemyACUCount='..iTotalNearbyEnemyACUCount..'; iACUFactor='..iACUFactor..'; iAggressiveFactor='..iAggressiveFactor..'; Adjusted enemy threat='..iEnemyNearbyThreat / iAggressiveFactor..'; Our allied threat='..iACUThreat * iACUFactor + iAllyNearbyThreat) end
                                                            end
                                                        end
                                                        if not(bEnemyHasPDOrSignificantACUs) then
                                                            local iNearbyEnemyLRDFThreat = 0
                                                            if AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.subrefLZThreatEnemyStructureDFByRange]) == false then
                                                                for iRange, iThreat in tLZTeamData[AiBotMap.subrefLZThreatEnemyStructureDFByRange] do
                                                                    if iRange > oACU[AiBotUnitInfo.refiDFRange] then
                                                                        iNearbyEnemyLRDFThreat = iNearbyEnemyLRDFThreat + iThreat
                                                                    end
                                                                end
                                                            end
                                                            if iNearbyEnemyLRDFThreat >= 3000 * iAggressiveFactor and (iACUThreat <= 5000 or iNearbyEnemyLRDFThreat >= iACUThreat * iAggressiveFactor or AiBotTeam.tTeamData[iTeam][AiBotTeam.refbAssassinationOrSimilar]) then
                                                                bEnemyHasPDOrSignificantACUs = true
                                                            elseif iNearbyEnemyLRDFThreat >= 700 and iTotalNearbyEnemyACUCount >= 1 then
                                                                bEnemyHasPDOrSignificantACUs = true
                                                            end
                                                            if bDebugMessages == true then LOG(sFunctionRef..': bEnemyHasPDOrSignificantACUs='..tostring(bEnemyHasPDOrSignificantACUs or false)..'; iNearbyEnemyLRDFThreat='..iNearbyEnemyLRDFThreat..'; iACUThreat='..iACUThreat) end
                                                        end

                                                    elseif iPercentageToFriendlyBase > 0.3 then
                                                        --Alternative T2 check - consider running if lots of T2 PD threat (vs above which just runs if any) - Check how many T2 PD are nearby (if any), along with shields, and dont be aggressive if we are almost in their range
                                                        local iNearbyEnemyLRDFThreat = 0
                                                        if AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.subrefLZThreatEnemyStructureDFByRange]) == false then
                                                            for iRange, iThreat in tLZTeamData[AiBotMap.subrefLZThreatEnemyStructureDFByRange] do
                                                                if iRange > oACU[AiBotUnitInfo.refiDFRange] then
                                                                    iNearbyEnemyLRDFThreat = iNearbyEnemyLRDFThreat + iThreat
                                                                end
                                                            end
                                                        end

                                                        if AiBotUtilities.IsTableEmpty(tLZData[AiBotMap.subrefLZAdjacentLandZones]) == false then
                                                            for _, iAdjLZ in tLZData[AiBotMap.subrefLZAdjacentLandZones] do
                                                                local tAdjLZTeamData = AiBotMap.tAllPlateaus[iPlateau][AiBotMap.subrefPlateauLandZones][iAdjLZ][AiBotMap.subrefLZTeamData][iTeam]
                                                                if AiBotUtilities.IsTableEmpty(tAdjLZTeamData[AiBotMap.subrefLZThreatEnemyStructureDFByRange]) == false then
                                                                    for iRange, iThreat in tAdjLZTeamData[AiBotMap.subrefLZThreatEnemyStructureDFByRange] do
                                                                        iNearbyEnemyLRDFThreat = iNearbyEnemyLRDFThreat + iThreat
                                                                    end
                                                                end
                                                            end
                                                        end
                                                        if bDebugMessages == true then LOG(sFunctionRef..': iNearbyEnemyLRDFThreat='..iNearbyEnemyLRDFThreat..'; bWantToRun='..tostring(bWantToRun or false)..'; iACUThreat='..iACUThreat) end
                                                        if iNearbyEnemyLRDFThreat >= 3000 and (iACUThreat <= 5000 or iNearbyEnemyLRDFThreat >= iACUThreat or AiBotTeam.tTeamData[iTeam][AiBotTeam.refbAssassinationOrSimilar]) then
                                                            bWantToRun = true
                                                        elseif iNearbyEnemyLRDFThreat >= 1750 and iNearbyEnemyLRDFThreat >= iACUThreat * 0.7 then
                                                            --Do more precise check of whether we are in range of the enemy based on nearest enemies in this zone and adjacent zones
                                                            local toLRUnits = {}
                                                            if AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.reftoNearestDFEnemies]) == false then
                                                                for iUnit, oUnit in tLZTeamData[AiBotMap.reftoNearestDFEnemies] do
                                                                    if not(oUnit.Dead) and oUnit[AiBotUnitInfo.refiDFRange] > oACU[AiBotUnitInfo.refiDFRange] then
                                                                        table.insert(toLRUnits, oUnit)
                                                                    end
                                                                end
                                                            end
                                                            if AiBotUtilities.IsTableEmpty(tLZData[AiBotMap.subrefLZAdjacentLandZones]) == false then
                                                                for _, iAdjLZ in tLZData[AiBotMap.subrefLZAdjacentLandZones] do
                                                                    local tAdjLZTeamData = AiBotMap.tAllPlateaus[iPlateau][AiBotMap.subrefPlateauLandZones][iAdjLZ][AiBotMap.subrefLZTeamData][iTeam]
                                                                    if AiBotUtilities.IsTableEmpty(tAdjLZTeamData[AiBotMap.reftoNearestDFEnemies]) == false then
                                                                        for iUnit, oUnit in tAdjLZTeamData[AiBotMap.reftoNearestDFEnemies] do
                                                                            if not(oUnit.Dead) and oUnit[AiBotUnitInfo.refiDFRange] > oACU[AiBotUnitInfo.refiDFRange] then
                                                                                table.insert(toLRUnits, oUnit)
                                                                            end
                                                                        end
                                                                    end
                                                                end
                                                            end
                                                            if bDebugMessages == true then LOG(sFunctionRef..': Size of toLRUnits='..table.getn(toLRUnits)..'; Are we close to these='..tostring(AiBotConditions.CloseToEnemyUnit(oACU:GetPosition(), toLRUnits, 5, iTeam, true, nil, nil, nil, nil, false))) end
                                                            if AiBotConditions.CloseToEnemyUnit(oACU:GetPosition(), toLRUnits, 5, iTeam, true, nil, nil, nil, nil, false) then
                                                                bWantToRun = true
                                                            end
                                                        end
                                                    end
                                                    if bDebugMessages == true then LOG(sFunctionRef..': Deciding if want to run after checking if enemy has PD or significnat ACUs, bEnemyHasPDOrSignificantACUs='..tostring(bEnemyHasPDOrSignificantACUs)..'; iEnemyNearbyThreat='..iEnemyNearbyThreat..'; iAggressiveFactor='..iAggressiveFactor..'; iACUFactor='..iACUFactor..'; iACUThreat='..iACUThreat..'; iAllyNearbyThreat='..iAllyNearbyThreat) end
                                                    local iOptionalNearlyInRangeAlliedDFThreat
                                                    if bEnemyHasPDOrSignificantACUs and iAllyNearbyThreat > 0 and tLZTeamData[AiBotMap.refiModDistancePercent] >= 0.25 and AiBotUnitInfo.GetUnitHealthAndShieldPercent(oACU) <= 0.95 then
                                                        --Be more cautious if enemy has ACUs or tanks - just because we have units nearby they may not be able to help, or may be other friendly ACUs who are retreating
                                                        iOptionalNearlyInRangeAlliedDFThreat = 0
                                                        local toNearbyFriendlyCombatUnits = {}
                                                        if AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.subrefLZTAlliedCombatUnits]) == false then
                                                            for iUnit, oUnit in tLZTeamData[AiBotMap.subrefLZTAlliedCombatUnits] do
                                                                if oUnit[AiBotUnitInfo.refiCombatRange] > 0 and AiBotUtilities.GetDistanceBetweenPositions(oUnit:GetPosition(), oACU:GetPosition()) - oUnit[AiBotUnitInfo.refiCombatRange] <= 10 and (not(oUnit[refiTimeLastWantedToRun]) or GetGameTimeSeconds() - oUnit[refiTimeLastWantedToRun] >= 5) and not(oUnit == oACU) then
                                                                    table.insert(toNearbyFriendlyCombatUnits, oUnit)
                                                                end
                                                            end
                                                        end
                                                        if AiBotUtilities.IsTableEmpty(tLZData[AiBotMap.subrefLZAdjacentLandZones]) == false then
                                                            for _, iAdjLZ in tLZData[AiBotMap.subrefLZAdjacentLandZones] do
                                                                local tAdjLZTeamData = AiBotMap.tAllPlateaus[iPlateau][AiBotMap.subrefPlateauLandZones][iAdjLZ][AiBotMap.subrefLZTeamData][iTeam]
                                                                if AiBotUtilities.IsTableEmpty(tAdjLZTeamData[AiBotMap.subrefLZTAlliedCombatUnits]) == false then
                                                                    for iUnit, oUnit in tAdjLZTeamData[AiBotMap.subrefLZTAlliedCombatUnits] do
                                                                        if oUnit[AiBotUnitInfo.refiCombatRange] > 0 and AiBotUtilities.GetDistanceBetweenPositions(oUnit:GetPosition(), oACU:GetPosition()) - oUnit[AiBotUnitInfo.refiCombatRange] <= 10 and (not(oUnit[refiTimeLastWantedToRun]) or GetGameTimeSeconds() - oUnit[refiTimeLastWantedToRun] >= 5) and not(oUnit == oACU) then
                                                                            table.insert(toNearbyFriendlyCombatUnits, oUnit)
                                                                        end
                                                                    end
                                                                end
                                                            end
                                                        end
                                                        iOptionalNearlyInRangeAlliedDFThreat = AiBotUnitInfo.GetCombatThreatRating(toNearbyFriendlyCombatUnits, false)
                                                        if bDebugMessages == true then LOG(sFunctionRef..': iOptionalNearlyInRangeAlliedDFThreat='..iOptionalNearlyInRangeAlliedDFThreat..'; iAllyNearbyThreat='..iAllyNearbyThreat) end
                                                    end
                                                    if iEnemyNearbyThreat >= 1200 and iACUThreat <= 5000 and ((oACU[refiUpgradeCount] or 0) < 3 or EntityCategoryContains(categories.UEF + categories.AEON, oACU.UnitId) or iEnemyNearbyThreat >= 4000) and iEnemyNearbyThreat / iAggressiveFactor > (iACUThreat * iACUFactor + (iOptionalNearlyInRangeAlliedDFThreat or iAllyNearbyThreat)) then
                                                        if not(bEnemyHasPDOrSignificantACUs) then
                                                            local iBestEnemyThreatRange = 0
                                                            if AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.subrefLZThreatEnemyStructureDFByRange]) == false then
                                                                for iRange, iThreat in tLZTeamData[AiBotMap.subrefLZThreatEnemyStructureDFByRange] do
                                                                    iBestEnemyThreatRange = math.max(iBestEnemyThreatRange, iRange)
                                                                end
                                                            end
                                                            if iBestEnemyThreatRange < 40 and AiBotUtilities.IsTableEmpty(tLZData[AiBotMap.subrefLZAdjacentLandZones]) == false then
                                                                for _, iAdjLZ in tLZData[AiBotMap.subrefLZAdjacentLandZones] do
                                                                    local tAdjLZTeamData = AiBotMap.tAllPlateaus[iPlateau][AiBotMap.subrefPlateauLandZones][iAdjLZ][AiBotMap.subrefLZTeamData][iTeam]
                                                                    if AiBotUtilities.IsTableEmpty(tAdjLZTeamData[AiBotMap.subrefLZThreatEnemyStructureDFByRange]) == false then
                                                                        for iRange, iThreat in tAdjLZTeamData[AiBotMap.subrefLZThreatEnemyStructureDFByRange] do
                                                                            iBestEnemyThreatRange = math.max(iBestEnemyThreatRange, iRange)
                                                                        end
                                                                    end
                                                                end
                                                            end
                                                            if bDebugMessages == true then LOG(sFunctionRef..': Checking highest enemy PD range nearby, iBestEnemyThreatRange='..(iBestEnemyThreatRange or 'nil')) end
                                                            if iBestEnemyThreatRange >= 40 then
                                                                bEnemyHasPDOrSignificantACUs = true
                                                            end
                                                        end
                                                        if bEnemyHasPDOrSignificantACUs then bWantToRun = true end
                                                    end
                                                    if bDebugMessages == true then LOG(sFunctionRef..': Finished checking if want to run due to PD or multiple enemy ACUs, bWantToRun='..tostring(bWantToRun)..'; iAggressiveFactor='..iAggressiveFactor) end
                                                    if not(bWantToRun) then
                                                        local iACUDistToClosestFriendlyBase = AiBotUtilities.GetDistanceBetweenPositions(oACU:GetPosition(), tLZTeamData[AiBotMap.reftClosestFriendlyBase])
                                                        local tEnemyCombatUnits = EntityCategoryFilterDown(AiBotUnitInfo.refCategoryLandCombat,  tLZTeamData[AiBotMap.subrefTEnemyUnits])
                                                        if bDebugMessages == true then LOG(sFunctionRef..': Will check if we have enemy units in this zone that are closer to our base than our ACU and which are in range of our ACU (i.e. suggesting enemy is trying to ambush/kill our ACU - dont want to just run if they are closer to base as zone might be large and ACU could e.g. be approaching the units from another direction so we want acu to attack them), is table of enemy combat units empty='..tostring(AiBotUtilities.IsTableEmpty(tEnemyCombatUnits))) end
                                                        if AiBotUtilities.IsTableEmpty(tEnemyCombatUnits) == false then
                                                            for iUnit, oUnit in tEnemyCombatUnits do
                                                                if AiBotUtilities.GetDistanceBetweenPositions(oUnit:GetPosition(), tLZTeamData[AiBotMap.reftClosestFriendlyBase]) < iACUDistToClosestFriendlyBase and (not(EntityCategoryContains(categories.COMMAND, oUnit.UnitId)) or oUnit[AiBotUnitInfo.refiDFRange] > oACU[AiBotUnitInfo.refiDFRange]) then
                                                                    if bDebugMessages == true then LOG(sFunctionRef..': iEnemyNearbyThreat='..iEnemyNearbyThreat..'; iACUDistToClosestFriendlyBase='..iACUDistToClosestFriendlyBase..'; Nearest enemy threat='..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..'; Dist of that to our base='..AiBotUtilities.GetDistanceBetweenPositions(oUnit:GetPosition(), tLZTeamData[AiBotMap.reftClosestFriendlyBase])) end
                                                                    if AiBotUtilities.GetDistanceBetweenPositions(oUnit:GetPosition(), oACU:GetPosition()) <= oACU[AiBotUnitInfo.refiDFRange] - 3 then
                                                                        if bDebugMessages == true then LOG(sFunctionRef..': Enemy is within 3 of us so want to run') end
                                                                        bWantToRun = true
                                                                        break
                                                                    end
                                                                end
                                                            end
                                                        end
                                                    end
                                                end
                                            end

                                            --Exception if we want to run but enemy has units nearby significantly less threat than us that we can attack without getting into range of main enemy threat
                                            if bDebugMessages == true then LOG(sFunctionRef..': Considering exception to wanting to run if gun ACU with high health, iACUThreat='..iACUThreat..'; iHealthPercent='..iHealthPercent..'; refbUseACUAggressively='..tostring(oACU[refbUseACUAggressively] or false)..'; refbAssassinationOrSimilar='..tostring(AiBotTeam.tTeamData[iTeam][AiBotTeam.refbAssassinationOrSimilar] or false)..'; dist to friendly base='..AiBotUtilities.GetDistanceBetweenPositions(oACU:GetPosition(), tLZTeamData[AiBotMap.reftClosestFriendlyBase])..'; subrefiTeamGrossMass='..AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossMass]..'; GetEnemyTeamActualMassIncome='..AiBotConditions.GetEnemyTeamActualMassIncome(iTeam)) end
                                            if bWantToRun and iHealthPercent >= 0.98 and iACUThreat >= 1300 and oACU[refiUpgradeCount] >= 1 and (oACU[refbUseACUAggressively] or not(AiBotTeam.tTeamData[iTeam][AiBotTeam.refbAssassinationOrSimilar]) or (oACU[refiUpgradeCount] >= 3 and iACUThreat >= 1600 and not(AiBotTeam.tTeamData[aiBrain.AiBotTeam][AiBotTeam.refbDangerousForACUs]) and AiBotUtilities.GetDistanceBetweenPositions(oACU:GetPosition(), tLZTeamData[AiBotMap.reftClosestFriendlyBase]) <= 180 and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossMass] < 1.1 * aiBrain[AiBotEconomy.refiBrainResourceMultiplier] * AiBotConditions.GetEnemyTeamActualMassIncome(iTeam))) then
                                                --Get closest enemy
                                                local oClosestEnemy
                                                local iClosestEnemy = 10000
                                                function GetClosestUnitInZone(tCurLZTeamData)
                                                    if AiBotUtilities.IsTableEmpty(tCurLZTeamData[AiBotMap.subrefTEnemyUnits]) == false then
                                                        local oCurZoneClosestEnemy, iCurZoneClosestEnemy = AiBotUtilities.GetNearestUnit(tCurLZTeamData[AiBotMap.subrefTEnemyUnits], oACU:GetPosition(), false, nil, true)
                                                        if iCurZoneClosestEnemy < iClosestEnemy then
                                                            iClosestEnemy = iCurZoneClosestEnemy
                                                            oClosestEnemy = oCurZoneClosestEnemy
                                                        end
                                                    end
                                                end
                                                GetClosestUnitInZone(tLZTeamData)
                                                if AiBotUtilities.IsTableEmpty(tLZData[AiBotMap.subrefLZAdjacentLandZones]) == false then
                                                    for _, iAdjLZ in tLZData[AiBotMap.subrefLZAdjacentLandZones] do
                                                        GetClosestUnitInZone(AiBotMap.tAllPlateaus[iPlateau][AiBotMap.subrefPlateauLandZones][iAdjLZ][AiBotMap.subrefLZTeamData][iTeam])
                                                    end
                                                end
                                                if bDebugMessages == true then LOG(sFunctionRef..': iClosestEnemy='..iClosestEnemy..'; oClosestEnemy='..(oClosestEnemy.UnitId or 'nil')..(AiBotUnitInfo.GetUnitLifetimeCount(oClosestEnemy) or 'nil')) end
                                                if iClosestEnemy <= 110 and oClosestEnemy and (iClosestEnemy <= 75 or (AiBotUtilities.GetDistanceBetweenPositions(oACU:GetPosition(), tLZTeamData[AiBotMap.reftClosestFriendlyBase]) <= 200 - iClosestEnemy and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossMass] < 1.1 * aiBrain[AiBotEconomy.refiBrainResourceMultiplier] * AiBotConditions.GetEnemyTeamActualMassIncome(iTeam))) then --We are close enough that we could consider attacking nearest enemies, or are close enough to our base that we can risk going a bit further away
                                                    --ACU moves at 1.7 speed vs mantis at 3.7, so assume a 2 speed differential as a rough approximation and reduce by ACU range
                                                    local iMobileDistThreshold = math.max(5, iClosestEnemy * 2 - oACU[AiBotUnitInfo.refiDFRange])
                                                    local iStructureDistThreshold = 15 - oACU[AiBotUnitInfo.refiDFRange]
                                                    local iEnemyThreatNearNearestEnemy = 0
                                                    local iThreatThreshold = iACUThreat * 0.7
                                                    local iCurDistLessRange
                                                    local bTooMuchEnemyThreat = false
                                                    function GetThreatOfEnemiesNearClosestEnemyUnitForCurZone(tCurLZTeamData)
                                                        if AiBotUtilities.IsTableEmpty(tCurLZTeamData[AiBotMap.subrefTEnemyUnits]) == false then
                                                            for iUnit, oUnit in tCurLZTeamData[AiBotMap.subrefTEnemyUnits] do
                                                                if (oUnit[AiBotUnitInfo.refiDFRange] or 0) > 0 and not(oUnit.Dead) then
                                                                    iCurDistLessRange = AiBotUtilities.GetDistanceBetweenPositions(oUnit:GetPosition(), oClosestEnemy:GetPosition()) - oUnit[AiBotUnitInfo.refiDFRange]
                                                                    if bDebugMessages == true then LOG(sFunctionRef..': Considering if want to include enemy oUnit='..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..'; iCurDistLessRange='..iCurDistLessRange..'; threat of htis unit='..AiBotUnitInfo.GetCombatThreatRating({ oUnit }, true, false)) end
                                                                    if iCurDistLessRange < iMobileDistThreshold and (iCurDistLessRange <= iStructureDistThreshold or EntityCategoryContains(categories.MOBILE, oUnit.UnitId)) then
                                                                        iEnemyThreatNearNearestEnemy = iEnemyThreatNearNearestEnemy + AiBotUnitInfo.GetCombatThreatRating({ oUnit }, true, false)
                                                                        if bDebugMessages == true then LOG(sFunctionRef..': iEnemyThreatNearNearestEnemy Threat after inclusion='..iEnemyThreatNearNearestEnemy..'; iThreatThreshold='..iThreatThreshold) end
                                                                        if iEnemyThreatNearNearestEnemy > iThreatThreshold then
                                                                            bTooMuchEnemyThreat = true
                                                                            break
                                                                        end
                                                                    end
                                                                end
                                                            end
                                                        end
                                                    end
                                                    GetThreatOfEnemiesNearClosestEnemyUnitForCurZone(tLZTeamData)
                                                    if not(bTooMuchEnemyThreat) and AiBotUtilities.IsTableEmpty(tLZData[AiBotMap.subrefLZAdjacentLandZones]) == false then
                                                        for _, iAdjLZ in tLZData[AiBotMap.subrefLZAdjacentLandZones] do
                                                            GetThreatOfEnemiesNearClosestEnemyUnitForCurZone(AiBotMap.tAllPlateaus[iPlateau][AiBotMap.subrefPlateauLandZones][iAdjLZ][AiBotMap.subrefLZTeamData][iTeam])
                                                            if bTooMuchEnemyThreat then break end
                                                        end
                                                    end
                                                    if bDebugMessages == true then LOG(sFunctionRef..': Considering if want to no longer run due to ACU being able to attack nearest enemies before they can get support, bTooMuchEnemyThreat='..tostring(bTooMuchEnemyThreat or false)) end
                                                    if not(bTooMuchEnemyThreat) then bWantToRun = false end
                                                end

                                            end
                                        end
                                    end
                                end
                            end
                        else
                            --No land zone - if we have no order then return to base
                            if bDebugMessages == true then LOG(sFunctionRef..': No land zone so will return to base if have no orders, order count='..(oACU[AiBotOrders.refiOrderCount] or 'nil')) end
                            if oACU[AiBotOrders.refiOrderCount] == 0 then
                                bWantToRun = true
                            else
                                --Is this water zone dangerous, and are we trying to travel to water?
                                local tOrderTarget
                                if AiBotUnitInfo.IsUnitValid(oACU[AiBotOrders.reftiLastOrders][1][AiBotOrders.subrefoOrderUnitTarget]) then tOrderTarget = oACU[AiBotOrders.reftiLastOrders][1][AiBotOrders.subrefoOrderUnitTarget]:GetPosition()
                                else tOrderTarget = oACU[AiBotOrders.reftiLastOrders][1][AiBotOrders.subreftOrderPosition]
                                end
                                if AiBotUtilities.IsTableEmpty(tOrderTarget) == false then
                                    if bDebugMessages == true then LOG(sFunctionRef..': Terrain height of target='..NavUtils.GetTerrainHeight(tOrderTarget[1], tOrderTarget[3])..'; Map water height='..AiBotMap.iMapWaterHeight) end
                                    if NavUtils.GetTerrainHeight(tOrderTarget[1], tOrderTarget[3]) < AiBotMap.iMapWaterHeight then
                                        if bDebugMessages == true then LOG(sFunctionRef..': Are trying to move underwater, will run instead if the water is dangerous and we lack antinavy attack') end
                                        local iAntiNavyThreat = (tLZTeamData[AiBotMap.subrefWZThreatEnemyAntiNavy] or 0)
                                        if iAntiNavyThreat >= 800 and (oACU[AiBotUnitInfo.refiAntiNavyRange] or 0) < 10 then
                                            bWantToRun = true
                                        elseif AiBotUtilities.IsTableEmpty(tLZData[AiBotMap.subrefWZAdjacentWaterZones]) == false then
                                            for _, iAdjWZ in tLZData[AiBotMap.subrefWZAdjacentWaterZones] do
                                                local tAdjWZTeamData = AiBotMap.tPondDetails[AiBotMap.tiPondByWaterZone[iAdjWZ]][AiBotMap.subrefPondWaterZones][iAdjWZ][AiBotMap.subrefWZTeamData][iTeam]
                                                iAntiNavyThreat = iAntiNavyThreat + (tAdjWZTeamData[AiBotMap.subrefWZThreatEnemyAntiNavy] or 0)
                                            end
                                            if iAntiNavyThreat >= 1500 and ((oACU[AiBotUnitInfo.refiAntiNavyRange] or 0) < 10 or iAntiNavyThreat >= 9000 or (iAntiNavyThreat >= 6000 and AiBotUnitInfo.GetUnitHealthPercent(oACU) <= 0.9)) then
                                                bWantToRun = true
                                                if bDebugMessages == true then LOG(sFunctionRef..': iAntiNavyThreat in this and adjacent zones='..iAntiNavyThreat) end
                                            end
                                        end
                                        --Are we not underwater, such that nearby enemy land units can fire at us, and we are damaged? in which case keep running
                                        if bDebugMessages == true then LOG(sFunctionRef..': bWantToRun after checking antinavy threat='..tostring(bWantToRun)..'; iAntiNavyThreat='..iAntiNavyThreat..'; iHealthPercent='..iHealthPercent..'; Is underwater='..tostring(AiBotUnitInfo.IsUnitUnderwater(oACU))) end
                                        if not(bWantToRun) and iHealthPercent <= 0.75 and not(AiBotUnitInfo.IsUnitUnderwater(oACU)) and AiBotUtilities.IsTableEmpty(tLZData[AiBotMap.subrefAdjacentLandZones]) == false then
                                            local iEnemyMassInRange = 0
                                            local iMaxEnemyInRange = AiBotUnitInfo.GetCombatThreatRating({ oACU }, false)
                                            for iEntry, tSubtable in tLZData[AiBotMap.subrefAdjacentLandZones] do
                                                local tAltLZData = AiBotMap.tAllPlateaus[tSubtable[AiBotMap.subrefWPlatAndLZNumber][1]][AiBotMap.subrefPlateauLandZones][tSubtable[AiBotMap.subrefWPlatAndLZNumber][2]]
                                                local tAltLZTeamData = tAltLZData[AiBotMap.subrefLZTeamData][iTeam]
                                                if AiBotUtilities.IsTableEmpty(tAltLZTeamData[AiBotMap.reftoNearestDFEnemies]) == false then
                                                    --Will have a bit of double-counting with this, but dont need ti to be precise
                                                    for iEnemy, oEnemy in tAltLZTeamData[AiBotMap.reftoNearestDFEnemies] do
                                                        if not(oEnemy.Dead) and AiBotUtilities.GetDistanceBetweenPositions(oEnemy:GetPosition(), oACU:GetPosition()) - (oEnemy[AiBotUnitInfo.refiDFRange] or 0) <= 3 then
                                                            iEnemyMassInRange = iEnemyMassInRange + AiBotUnitInfo.GetUnitMassCost(oEnemy)
                                                            if iEnemyMassInRange >= iMaxEnemyInRange then bWantToRun = true break end
                                                        end
                                                    end
                                                end
                                                if bDebugMessages == true then LOG(sFunctionRef..': iEnemyMassInRange after considering iAdjLZ='..tSubtable[AiBotMap.subrefWPlatAndLZNumber][2]..'='..iEnemyMassInRange..'; iMaxEnemyInRange threshold='..iMaxEnemyInRange) end
                                            end
                                        end
                                    end
                                end

                            end
                        end
                    end
                end
            end
        end
    end
    if bDebugMessages == true then LOG(sFunctionRef..': bWantToRun before override='..tostring(bWantToRun)..'; oACU[refbUseACUAggressively]='..tostring(oACU[refbUseACUAggressively])..'; Dnagerous for ACUs='..tostring(AiBotTeam.tTeamData[iTeam][AiBotTeam.refbDangerousForACUs])) end
    if not(bWantToRun) and not(oACU[refbUseACUAggressively]) and AiBotTeam.tTeamData[iTeam][AiBotTeam.refbDangerousForACUs] then
        if bDebugMessages == true then LOG(sFunctionRef..': Considering override to make ACU run if enemy has approaching land exp, is table of enemy land exp empty='..tostring(AiBotUtilities.IsTableEmpty(AiBotTeam.tTeamData[iTeam][AiBotTeam.reftEnemyLandExperimentals]))) end
        --Dangerous for ACUs so consider running if approaching enemy experimental threat
        if AiBotUtilities.IsTableEmpty(AiBotTeam.tTeamData[iTeam][AiBotTeam.reftEnemyLandExperimentals]) == false then
            local iClosestExperimentalDist = 100000
            local iCurDist
            for iUnit, oUnit in AiBotTeam.tTeamData[iTeam][AiBotTeam.reftEnemyLandExperimentals] do
                if AiBotUnitInfo.IsUnitValid(oUnit) then
                    iCurDist = AiBotUtilities.GetDistanceBetweenPositions(oACU:GetPosition(), oUnit:GetPosition())
                    if iCurDist < iClosestExperimentalDist then
                        iClosestExperimentalDist = iCurDist
                    end
                end
            end
            if bDebugMessages == true then LOG(sFunctionRef..': iClosestExperimentalDist='..iClosestExperimentalDist) end
            if iClosestExperimentalDist <= math.max(math.min(AiBotMap.iMapSize * 0.4, 250), 150) then
                bWantToRun = true
                if bDebugMessages == true then LOG(sFunctionRef..': Want to run from experimental') end
            end
        end
    end

    if bWantToRun then
        oACU[refiTimeLastWantedToRun] = GetGameTimeSeconds()
        --Record the zone that we are in, and that we were traveling to, as running from
        if not(oACU[reftiTimeLastRanFromZoneByPlateau][iPlateau][iLandZone]) then
            if not(oACU[reftiTimeLastRanFromZoneByPlateau][iPlateau]) then
                if not(oACU[reftiTimeLastRanFromZoneByPlateau]) then oACU[reftiTimeLastRanFromZoneByPlateau] = {} end
                oACU[reftiTimeLastRanFromZoneByPlateau][iPlateau] = {}
            end
        end
        oACU[reftiTimeLastRanFromZoneByPlateau][iPlateau][iLandZone] = GetGameTimeSeconds()
        if oACU[refiTimeLastToldToMoveToZone] and GetGameTimeSeconds() - oACU[refiTimeLastToldToMoveToZone] <= 10 then
            local iTargetPlateau = oACU[refiLastPlateauAndZoneToMoveTo][1]
            local iTargetLZ = oACU[refiLastPlateauAndZoneToMoveTo][2]
            if not(oACU[reftiTimeLastRanFromZoneByPlateau][iTargetPlateau][iTargetLZ]) then
                if not(oACU[reftiTimeLastRanFromZoneByPlateau][iTargetPlateau]) then
                    if not(oACU[reftiTimeLastRanFromZoneByPlateau]) then oACU[reftiTimeLastRanFromZoneByPlateau] = {} end
                    oACU[reftiTimeLastRanFromZoneByPlateau][iTargetPlateau] = {}
                end
            end
            oACU[reftiTimeLastRanFromZoneByPlateau][iTargetPlateau][iTargetLZ] = GetGameTimeSeconds()
        end

    end
    if bDebugMessages == true then LOG(sFunctionRef..': End of code, bWantToRun='..tostring(bWantToRun)) end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
    return bWantToRun
end

function DoesACUWantToReturnToCoreBase(iPlateauOrZero, iLandOrWaterZone, tLZOrWZData, tLZOrWZTeamData, oACU)
    --Returns true if want ACU to return to the core base - to be used when ACU is facing critical threat that could kill it vs the normal 'does acu want to run' where ACU might return to an island sub-base
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    local sFunctionRef = 'DoesACUWantToReturnToCoreBase'
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)



    local iTeam = oACU:GetAIBrain().AiBotTeam
    local iACUHealthPercentage =  AiBotUnitInfo.GetUnitHealthPercent(oACU)

