    if tLZOrWZTeamData[AiBotMap.subrefLZbCoreBase] and iACUHealthPercentage >= 1 and not(tLZOrWZTeamData[AiBotMap.subrefbDangerousEnemiesInThisLZ]) and (tLZOrWZTeamData[AiBotMap.refiEnemyAirToGroundThreat] or 0) == 0 and AiBotTeam.tTeamData[iTeam][AiBotTeam.refiEnemyAirToGroundThreat] <= 500 * AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestEnemyAirTech] then
        if bDebugMessages == true then LOG(sFunctionRef..': ACU is on full health and in the core zone with no major enemy threat so wont try to return to core base') end
        AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
        return false
        --If are in our core base and have more than half health then also dont run if we wouldnt run normally
    elseif tLZOrWZTeamData[AiBotMap.subrefLZbCoreBase] and tLZOrWZTeamData[AiBotMap.refiEnemyAirToGroundThreat] == 0 and iACUHealthPercentage >= 0.6 and not(DoesACUWantToRun(iPlateauOrZero, iLandOrWaterZone, tLZOrWZData, tLZOrWZTeamData, oACU)) then
