    if bDebugMessages == true then LOG(sFunctionRef..': Condition1 (dangerousforACUs): AiBotTeam.tTeamData[iTeam][AiBotTeam.refbDangerousForACUs]='..tostring(AiBotTeam.tTeamData[iTeam][AiBotTeam.refbDangerousForACUs])..'; Cond1a='..tostring(((GetGameTimeSeconds() >= 1080 and (GetGameTimeSeconds() >= 2100 or iACUHealthPercentage < 0.95 or (GetGameTimeSeconds() >= 1380 and AiBotTeam.tTeamData[iTeam][AiBotTeam.refiConstructedExperimentalCount] > 0) or (AiBotTeam.tTeamData[iTeam][AiBotTeam.refbAssassinationOrSimilar] and (oACU[refiUpgradeCount] <= 1 or (oACU[refiUpgradeCount] == 2 and EntityCategoryContains(categories.AEON, oACU.UnitId)) or AiBotUtilities.GetDistanceBetweenPositions(oACU:GetPosition(), tLZOrWZTeamData[AiBotMap.reftClosestFriendlyBase]) >= 140))))))..';Cond1b='..tostring( AiBotTeam.tTeamData[iTeam][AiBotTeam.refiConstructedExperimentalCount] > 0)..'; Cond1c='..tostring((AiBotTeam.tTeamData[iTeam][AiBotTeam.refbAssassinationOrSimilar] and GetGameTimeSeconds() >= 300 and (oACU:GetAIBrain()[AiBotEconomy.refiOurHighestFactoryTechLevel] >= 3 or tLZOrWZTeamData[AiBotMap.refiModDistancePercent] >= 0.45 or (AiBotTeam.tTeamData[iTeam][AiBotTeam.refiMexCountByTech][3] or 0) >= 3 or ((AiBotTeam.tTeamData[iTeam][AiBotTeam.refiMexCountByTech][2] or 0) >= 5 and AiBotConditions.GetHighestOtherTeamT2AndT3MexCount(iTeam) * 1.25 < (AiBotTeam.tTeamData[iTeam][AiBotTeam.refiMexCountByTech][3] or 0) +  (AiBotTeam.tTeamData[iTeam][AiBotTeam.refiMexCountByTech][2] or 0))) and (AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossMass] > 1.1 * oACU:GetAIBrain()[AiBotEconomy.refiBrainResourceMultiplier] * AiBotConditions.GetEnemyTeamActualMassIncome(iTeam) or oACU[refiUpgradeCount] <= 1 or (oACU[refiUpgradeCount] == 2 and EntityCategoryContains(categories.AEON, oACU.UnitId)) or AiBotUtilities.GetDistanceBetweenPositions(oACU:GetPosition(), tLZOrWZTeamData[AiBotMap.reftClosestFriendlyBase]) >= 140)))..'; cond1d='..tostring(iACUHealthPercentage < 0.9)..'; cond1e='..tostring(iACUHealthPercentage < 0.9)..'; cond1f='..tostring((tLZOrWZTeamData[AiBotMap.refiModDistancePercent] >= 0.25 and (tLZOrWZTeamData[AiBotMap.refiModDistancePercent] >= 0.6 or AiBotUtilities.GetDistanceBetweenPositions(oACU:GetPosition(), tLZOrWZTeamData[AiBotMap.reftClosestFriendlyBase]) >= 150) and (AiBotTeam.tTeamData[iTeam][AiBotTeam.refbAssassinationOrSimilar] or AiBotUtilities.GetDistanceBetweenPositions(tLZOrWZData[AiBotMap.subrefMidpoint], tLZOrWZTeamData[AiBotMap.reftClosestFriendlyBase]) >= 150 + 50 * AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiActiveAiBotBrainCount])))..'; cond1c broken out in more detail:refiOurHighestFactoryTechLevel='..oACU:GetAIBrain()[AiBotEconomy.refiOurHighestFactoryTechLevel]..'; Moddist%='..tLZOrWZTeamData[AiBotMap.refiModDistancePercent]..'; T3 mexes='..AiBotTeam.tTeamData[iTeam][AiBotTeam.refiMexCountByTech][3]..';T2 mexes='..AiBotTeam.tTeamData[iTeam][AiBotTeam.refiMexCountByTech][2]..'; Enemy T2+T3 mexes='..AiBotConditions.GetHighestOtherTeamT2AndT3MexCount(iTeam)..'; Our fac and enemy fac or our LC t3='..tostring(oACU:GetAIBrain()[AiBotEconomy.refiOurHighestFactoryTechLevel] >= 3 and (AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestEnemyGroundTech] >= 3 or AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestEnemyAirTech] >= 3 or AiBotConditions.GetTeamLifetimeBuildCount(iTeam, AiBotUnitInfo.refCategoryLandCombat * categories.TECH3) >= 2))..'; Dist to base='..AiBotUtilities.GetDistanceBetweenPositions(tLZOrWZData[AiBotMap.subrefMidpoint], tLZOrWZTeamData[AiBotMap.reftClosestFriendlyBase])..'; Air snipe condition='..tostring(((AiBotTeam.tTeamData[iTeam][AiBotTeam.refiEnemyAirToGroundThreat] >= math.max(500, 500 * AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestEnemyAirTech], (tLZOrWZTeamData[AiBotMap.subrefLZOrWZThreatAllyGroundAA] or 0) + (tLZOrWZTeamData[AiBotMap.subrefLZThreatAllyMAA] or 0))..'; High upgrade ACU new row 1 cond for everything='..tostring((AiBotTeam.tTeamData[iTeam][AiBotTeam.refbAssassinationOrSimilar] or oACU[refiUpgradeCount] < 3 or (oACU[refiUpgradeCount] == 3 and EntityCategoryContains(categories.AEON, oACU.UnitId)) or not(tLZOrWZTeamData[AiBotMap.subrefbDangerousEnemiesInThisLZ]) or iACUHealthPercentage < 0.95 or (AiBotUnitInfo.GetCombatThreatRating({ oACU}, false) or 0) <= 3000 or tLZOrWZTeamData[AiBotMap.refiModDistancePercent] > 0.4 or AiBotUtilities.GetDistanceBetweenPositions(oACU:GetPosition(), tLZOrWZTeamData[AiBotMap.reftClosestFriendlyBase]) > 100 + 40 * AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiActiveAiBotBrainCount] and ((tLZOrWZTeamData[AiBotMap.refiEnemyAirToGroundThreat] or 0) > (tLZOrWZTeamData[AiBotMap.subrefiThreatEnemyGroundAA] or 0)))))))) end
