    if (AiBotTeam.tTeamData[iTeam][AiBotTeam.refbAssassinationOrSimilar] or oACU[refiUpgradeCount] < 3 or (oACU[refiUpgradeCount] == 3 and EntityCategoryContains(categories.AEON, oACU.UnitId)) or (not(tLZOrWZTeamData[AiBotMap.subrefbDangerousEnemiesInThisLZ]) and not(tLZOrWZTeamData[AiBotMap.subrefLZbCoreBase])) or iACUHealthPercentage < 0.95 or (AiBotUnitInfo.GetCombatThreatRating({ oACU}, false) or 0) <= 2300 or tLZOrWZTeamData[AiBotMap.refiModDistancePercent] > 0.4 or AiBotUtilities.GetDistanceBetweenPositions(oACU:GetPosition(), tLZOrWZTeamData[AiBotMap.reftClosestFriendlyBase]) > 100 + 40 * AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiActiveAiBotBrainCount] or ((tLZOrWZTeamData[AiBotMap.refiEnemyAirToGroundThreat] or 0) > (tLZOrWZTeamData[AiBotMap.subrefiThreatEnemyGroundAA] or 0))) and
            ((AiBotTeam.tTeamData[iTeam][AiBotTeam.refbDangerousForACUs] and
                ((GetGameTimeSeconds() >= 1080 and (GetGameTimeSeconds() >= 2100 or iACUHealthPercentage < 0.95 or (GetGameTimeSeconds() >= 1380 and AiBotTeam.tTeamData[iTeam][AiBotTeam.refiConstructedExperimentalCount] > 0) or (AiBotTeam.tTeamData[iTeam][AiBotTeam.refbAssassinationOrSimilar] and (oACU[refiUpgradeCount] <= 1 or (oACU[refiUpgradeCount] == 2 and EntityCategoryContains(categories.AEON, oACU.UnitId)) or AiBotUtilities.GetDistanceBetweenPositions(oACU:GetPosition(), tLZOrWZTeamData[AiBotMap.reftClosestFriendlyBase]) >= 140)))) --1a
