                and not(AiBotUtilities.IsTableEmpty(AiBotTeam.tTeamData[iTeam][AiBotTeam.reftEnemyLandExperimentals]) and not(AiBotTeam.tTeamData[iTeam][AiBotTeam.refbAssassinationOrSimilar]) and GetGameTimeSeconds() <= 1200 and iACUHealthPercentage >= 0.95 and oACU[refiUpgradeCount] >= 2 and (AiBotUnitInfo.GetCombatThreatRating({ oACU}, false) or 0) >= 3500 and AiBotUtilities.GetDistanceBetweenPositions(tLZOrWZData[AiBotMap.subrefMidpoint], tLZOrWZTeamData[AiBotMap.reftClosestFriendlyBase]) <= 250 and AiBotConditions.IsFurthestACUToFriendlyBase(oACU, tLZOrWZTeamData, iTeam)))
