            ) then
        if bDebugMessages == true then LOG(sFunctionRef..': Is dangerous for ACU or low health or large enemy air to ground threat so returning to base; First condition row='..tostring(((AiBotTeam.tTeamData[iTeam][AiBotTeam.refbDangerousForACUs] and (GetGameTimeSeconds() >= 1080 or tLZOrWZTeamData[AiBotMap.refiModDistancePercent] >= 0.35 or AiBotTeam.tTeamData[iTeam][AiBotTeam.refbAssassinationOrSimilar] or AiBotTeam.tTeamData[iTeam][AiBotTeam.refiConstructedExperimentalCount] > 0 or AiBotUtilities.IsTableEmpty(AiBotTeam.tTeamData[iTeam][AiBotTeam.reftEnemyLandExperimentals]) == false or iACUHealthPercentage < 0.9 or (tLZOrWZTeamData[AiBotMap.refiModDistancePercent] >= 0.25 and AiBotUtilities.GetDistanceBetweenPositions(tLZOrWZData[AiBotMap.subrefMidpoint], tLZOrWZTeamData[AiBotMap.reftClosestFriendlyBase]) >= 175))) or iACUHealthPercentage <= 0.4 or (tLZOrWZTeamData[AiBotMap.refiEnemyAirToGroundThreat] or 0) >= 400) or iACUHealthPercentage <= 0.4 or (tLZOrWZTeamData[AiBotMap.refiEnemyAirToGroundThreat] or 0) >= 400)..'; Eception to first row condition='..tostring(not(AiBotUtilities.IsTableEmpty(AiBotTeam.tTeamData[iTeam][AiBotTeam.reftEnemyLandExperimentals]) and not(AiBotTeam.tTeamData[iTeam][AiBotTeam.refbAssassinationOrSimilar]) and GetGameTimeSeconds() <= 1200 and iACUHealthPercentage >= 0.95 and oACU[refiUpgradeCount] >= 2 and (AiBotUnitInfo.GetCombatThreatRating({ oACU}, false) or 0) >= 3500 and AiBotUtilities.GetDistanceBetweenPositions(tLZOrWZData[AiBotMap.subrefMidpoint], tLZOrWZTeamData[AiBotMap.reftClosestFriendlyBase]) <= 250))..'; Is furthest ACU from friendly base='..tostring(AiBotConditions.IsFurthestACUToFriendlyBase(oACU, tLZOrWZTeamData, iTeam))..'; 3rd row condition='..tostring((not(tLZOrWZTeamData[AiBotMap.subrefLZbCoreBase]) and AiBotTeam.tTeamData[iTeam][AiBotTeam.refiEnemyAirToGroundThreat] >= math.max(500, 500 * AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestEnemyAirTech], (tLZOrWZTeamData[AiBotMap.subrefLZOrWZThreatAllyGroundAA] or 0) + (tLZOrWZTeamData[AiBotMap.subrefLZThreatAllyMAA] or 0))))..'; 4th row condition='..tostring((AiBotTeam.tTeamData[iTeam][AiBotTeam.refbAssassinationOrSimilar] or (not(AiBotTeam.tAirSubteamData[oACU:GetAIBrain().AiBotAirSubteam][AiBotTeam.refbHaveAirControl]) and (AiBotTeam.tTeamData[iTeam][AiBotTeam.refiEnemyAirToGroundThreat] > 1200 or AiBotTeam.iPlayersAtGameStart <= 4 or AiBotConditions.GetHighestAirToGroundThreatForIndividualEnemyBrain(iTeam) > 400))))..'; 5th row condition='..tostring((AiBotTeam.tTeamData[iTeam][AiBotTeam.refiEnemyAirToGroundThreat] > 1000 * AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiActiveAiBotBrainCount] or (tLZOrWZTeamData[AiBotMap.refiModDistancePercent] >= 0.45 and (AiBotUtilities.GetDistanceBetweenPositions(oACU:GetPosition(), tLZOrWZTeamData[AiBotMap.reftClosestFriendlyBase]) >= 180 or iACUHealthPercentage <= 0.75) and (tLZOrWZTeamData[AiBotMap.refiModDistancePercent] >= 0.55 or (tLZOrWZTeamData[AiBotMap.refiModDistancePercent] >= 0.45 and AiBotMap.iMapSize >= 1000))) or iACUHealthPercentage <= 0.95 or oACU[refiUpgradeCount] <= 1 or AiBotConditions.GetNearbyEnemyAirToGroundThreat(tLZOrWZData, tLZOrWZTeamData, iTeam, 175, 0) > math.max(100, (tLZOrWZTeamData[AiBotMap.subrefLZOrWZThreatAllyGroundAA] or 0) * 2.5)))..'; MAA in this and adj zone='..AiBotConditions.GetFriendlyMAAInThisAndAdjacentLandZones(tLZOrWZData, tLZOrWZTeamData, iPlateauOrZero, iTeam)..'; Total enemy air to ground threat='..AiBotTeam.tTeamData[iTeam][AiBotTeam.refiEnemyAirToGroundThreat]..'; Mod dist='..tLZOrWZTeamData[AiBotMap.refiModDistancePercent]..'; Enemy air to ground factor for check='..(0.35 + math.min(math.max(-0.15,tLZOrWZTeamData[AiBotMap.refiModDistancePercent] - 0.4), 0.2))..'; Row 7='..tostring(AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestEnemyAirTech] >= 3 or GetGameTimeSeconds() >= 1080 or AiBotTeam.tTeamData[iTeam][AiBotTeam.refiEnemyAirToGroundThreat] >= 3000 or iACUHealthPercentage <= 0.9 or tLZOrWZTeamData[AiBotMap.refiModDistancePercent] >= 0.6 or iPlateauOrZero == 0) and (AiBotTeam.tTeamData[iTeam][AiBotTeam.refbAssassinationOrSimilar] or not(AiBotConditions.IsFurthestACUToFriendlyBase(oACU, tLZOrWZTeamData, iTeam)))..'; En land tech='..AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestEnemyGroundTech]..'; En air tech='..AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestEnemyAirTech]..'; ACU health%='..iACUHealthPercentage..'; Plateau='..iPlateauOrZero..'; Is table of enemy land exp empty='..tostring(AiBotUtilities.IsTableEmpty(AiBotTeam.tTeamData[iTeam][AiBotTeam.reftEnemyLandExperimentals]))) end
        AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
        return true
    else
        --Run if enemy has an ACU with upgrades or is upgrading and we have no upgrades
        if not(tLZOrWZTeamData[AiBotMap.subrefLZbCoreBase]) and AiBotTeam.tTeamData[iTeam][AiBotTeam.refbEnemyHasUpgradedACU] and (oACU[refiUpgradeCount] or 0) == 0 then
            if bDebugMessages == true then LOG(sFunctionRef..': Enemy ACU has upgrade and we dont so return to base unless are in a core expansion or have enemy units we want to try and kill and enemy ACU is far away, tLZOrWZTeamData[AiBotMap.subrefLZCoreExpansion]='..tostring(tLZOrWZTeamData[AiBotMap.subrefLZCoreExpansion] or false)..'; Enemies in adj zone='..tostring(tLZOrWZTeamData[AiBotMap.subrefbEnemiesInThisOrAdjacentLZ])..'; tLZOrWZTeamData[AiBotMap.refiModDistancePercent]='..tLZOrWZTeamData[AiBotMap.refiModDistancePercent]..'; Dist to nearest friendly base='..AiBotUtilities.GetDistanceBetweenPositions(oACU:GetPosition(), tLZOrWZTeamData[AiBotMap.reftClosestFriendlyBase])..'; ACU health %='..iACUHealthPercentage) end
            if (tLZOrWZTeamData[AiBotMap.subrefLZCoreExpansion] or (tLZOrWZTeamData[AiBotMap.refiModDistancePercent] <= 0.35 and GetGameTimeSeconds() <= 600 and iACUHealthPercentage >= 0.8 and (tLZOrWZTeamData[AiBotMap.refiModDistancePercent] <= 0.2 or AiBotUtilities.GetDistanceBetweenPositions(oACU:GetPosition(), tLZOrWZTeamData[AiBotMap.reftClosestFriendlyBase]) <= 125))) and tLZOrWZTeamData[AiBotMap.subrefbEnemiesInThisOrAdjacentLZ] and GetGameTimeSeconds() <= 840 then
                local iClosestEnemyACU = 10000
                local iCurDist
                if AiBotUtilities.IsTableEmpty(AiBotTeam.tTeamData[iTeam][AiBotTeam.reftEnemyACUs]) == false then
                    for iEnemyACU, oEnemyACU in AiBotTeam.tTeamData[iTeam][AiBotTeam.reftEnemyACUs] do
                        if (oEnemyACU[AiBotUnitInfo.refiDFRange] or 0) > (oACU[AiBotUnitInfo.refiDFRange] or 0) then
                            iCurDist = AiBotUtilities.GetDistanceBetweenPositions(oACU:GetPosition(), oEnemyACU:GetPosition())
                            if iCurDist < iClosestEnemyACU and (not(oEnemyACU:IsUnitState('Upgrading')) or iCurDist <= (oEnemyACU[AiBotUnitInfo.refiDFRange] or 0) + 40) then iClosestEnemyACU = iCurDist end
                        end
                    end
                end
                if bDebugMessages == true then LOG(sFunctionRef..': iClosestEnemyACU with better range than us='..iClosestEnemyACU) end
                if iClosestEnemyACU <= 175 then
                    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
                    return true
                else
                    --If not a core expansion, then check there is actually an enemy unit nearby (such that we are liekly going to be attacking)
                    if tLZOrWZTeamData[AiBotMap.subrefLZCoreExpansion] then
                        --Do nothing
                        if bDebugMessages == true then LOG(sFunctionRef..': Etiher core xpansion or closest DF unit is within 50 of us so we dont want to run as it may be better to attack instead') end
                    else
                        local oNearestUnit
                        if AiBotUtilities.IsTableEmpty(tLZOrWZTeamData[AiBotMap.reftoNearestDFEnemies]) == false then
                            oNearestUnit = AiBotUtilities.GetNearestUnit(tLZOrWZTeamData[AiBotMap.reftoNearestDFEnemies], oACU:GetPosition())
                            if AiBotUnitInfo.IsUnitValid(oNearestUnit) then
                                if AiBotUtilities.GetDistanceBetweenPositions(oACU:GetPosition(), oNearestUnit:GetPosition()) <= 50 then
                                    if bDebugMessages == true then LOG(sFunctionRef..': Closest enmy unit is within 50 so dont want to run as it may be better to attack') end
                                else
                                    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
                                    return true
                                end
                            else
                                AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
                                return true
                            end
                        else
                            AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
                            return true
                        end
                    end

                end
            else
                AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
                return true
            end
        end

        --Return to base if enemy has signiifcant air to ground threat and we lack air control, and our mod dist isnt low
        if AiBotTeam.tTeamData[iTeam][AiBotTeam.refiEnemyAirToGroundThreat] >= math.max(math.min(1000, 400 + math.max(250 * (AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiActiveAiBotBrainCount] or 1), (AiBotTeam.iPlayersAtGameStart or 1) * 100)), math.min(750, (tLZOrWZTeamData[AiBotMap.subrefLZOrWZThreatAllyGroundAA] or 0) * 2), math.min(4000, (AiBotTeam.tAirSubteamData[oACU:GetAIBrain().AiBotAirSubteam][AiBotTeam.subrefiOurAirAAThreat] or 0))) and AiBotTeam.tAirSubteamData[oACU:GetAIBrain().AiBotAirSubteam][AiBotTeam.refbFarBehindOnAir] and ((oACU[refiUpgradeCount] or 0) < 3 or not(oACU:GetHealth() >= 15000 - 500 * AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiActiveAiBotBrainCount] or (oACU.MyShield.GetHealth and oACU.MyShield:GetHealth()) >= 7000))
                --Unless ACU is relatively near our base already and has good health and upgrades
                and (tLZOrWZTeamData[AiBotMap.refiModDistancePercent] >= 0.4 or (not(AiBotMap.bIsCampaignMap) and tLZOrWZTeamData[AiBotMap.refiModDistancePercent] >= 0.2 and AiBotUtilities.GetDistanceBetweenPositions(tLZOrWZData[AiBotMap.subrefMidpoint], tLZOrWZTeamData[AiBotMap.reftClosestFriendlyBase]) >= 180 and (oACU[refiUpgradeCount] < 2 or tLZOrWZTeamData[AiBotMap.refiEnemyAirToGroundThreat] > 0 or iACUHealthPercentage <= 0.8 or (AiBotMap.iMapSize >= 1000 and AiBotUtilities.GetDistanceBetweenPositions(tLZOrWZData[AiBotMap.subrefMidpoint], tLZOrWZTeamData[AiBotMap.reftClosestFriendlyBase]) >= 150))))
        then
            if bDebugMessages == true then LOG(sFunctionRef..': Vulnerable to an air snipe so want to retreat, oACU[refiUpgradeCount]='..oACU[refiUpgradeCount]) end
            AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
            return true
        else
            --If ACU is upgrading then we wont have checked if we want to run, so do a check of enemy threat and consider running
            if bDebugMessages == true then LOG(sFunctionRef..': Is ACU upgrading='..tostring(oACU:IsUnitState('Upgrading'))..'; ACU work progress='..(oACU:GetWorkProgress() or 'nil')..'; Core base='..tostring(tLZOrWZTeamData[AiBotMap.subrefLZbCoreBase] or false)..'; Dangerous enemies in this LZ='..tostring(tLZOrWZTeamData[AiBotMap.subrefbDangerousEnemiesInThisLZ] or false)..'; Is table of DF enemies empty='..tostring(AiBotUtilities.IsTableEmpty(tLZOrWZTeamData[AiBotMap.reftoNearestDFEnemies]))..'; Enemy mobile DF total='..(tLZOrWZTeamData[AiBotMap.subrefLZThreatEnemyMobileDFTotal] or 'nil')..'; Dist to LZ Midpoint='..AiBotUtilities.GetDistanceBetweenPositions(oACU:GetPosition(), tLZOrWZData[AiBotMap.subrefMidpoint])) end
            if oACU:IsUnitState('Upgrading') then
                if iPlateauOrZero > 0 and iACUHealthPercentage <= 0.99 and oACU:GetWorkProgress() <= 0.8 and (tLZOrWZTeamData[AiBotMap.subrefbDangerousEnemiesInThisLZ] or oACU:GetWorkProgress() <= 0.6) and (not(tLZOrWZTeamData[AiBotMap.subrefLZbCoreBase]) or AiBotUtilities.GetDistanceBetweenPositions(oACU:GetPosition(), tLZOrWZData[AiBotMap.subrefMidpoint]) >= 35) and AiBotUtilities.IsTableEmpty(tLZOrWZTeamData[AiBotMap.reftoNearestDFEnemies]) == false then
                    if bDebugMessages == true then LOG(sFunctionRef..': ACU is upgrading, will consider if a really large threat such that we should run, safe to get upgrade='..tostring(AiBotConditions.SafeToUpgradeUnit(oACU))) end
                    if not(AiBotConditions.SafeToUpgradeUnit(oACU)) then
                        local toNearbyEnemyUnits = {}
                        local toApproachingEnemies = {}
                        local iNearbyThreshold = 10
                        local iApproachingThreshold = 40
                        local iCurDist
                        function AddNearbyEnemyThreats(tCurLZTeamData, bIsWaterZone)
                            if AiBotUtilities.IsTableEmpty(tCurLZTeamData[AiBotMap.subrefTEnemyUnits]) == false then
                                for iEnemy, oEnemy in tCurLZTeamData[AiBotMap.subrefTEnemyUnits] do
                                    if not(oEnemy.Dead) and oEnemy[AiBotUnitInfo.refiCombatRange] > 10 and (not(bIsWaterZone) or ((oEnemy[AiBotUnitInfo.refiDFRange] or 0) > 0 and not(AiBotUnitInfo.IsUnitUnderwater(oEnemy)))) then
                                        iCurDist = AiBotUtilities.GetDistanceBetweenPositions(oEnemy:GetPosition(), oACU:GetPosition()) - oEnemy[AiBotUnitInfo.refiCombatRange]
                                        if iCurDist <= iNearbyThreshold then
                                            table.insert(toNearbyEnemyUnits, oEnemy)
                                        elseif iCurDist <= iApproachingThreshold then
                                            table.insert(toApproachingEnemies, oEnemy)
                                        end

                                    end
                                end
                            end
                        end
                        AddNearbyEnemyThreats(tLZOrWZTeamData)
                        if AiBotUtilities.IsTableEmpty(tLZOrWZData[AiBotMap.subrefLZAdjacentLandZones]) == false then
                            for _, iAdjLZ in tLZOrWZData[AiBotMap.subrefLZAdjacentLandZones] do
                                local tAdjLZTeamData = AiBotMap.tAllPlateaus[iPlateauOrZero][AiBotMap.subrefPlateauLandZones][iAdjLZ][AiBotMap.subrefLZTeamData][iTeam]
                                AddNearbyEnemyThreats(tAdjLZTeamData)
                            end
                        end
                        if tLZOrWZTeamData[AiBotMap.subrefbDangerousEnemiesInAdjacentWZ] and AiBotUtilities.IsTableEmpty(tLZOrWZData[AiBotMap.subrefAdjacentWaterZones]) == false then
                            for iEntry, tSubtable in tLZOrWZData[AiBotMap.subrefAdjacentWaterZones] do
                                local iAdjWZ = tSubtable[AiBotMap.subrefAWZRef]
                                local tAdjWZTeamData = AiBotMap.tPondDetails[AiBotMap.tiPondByWaterZone[iAdjWZ]][AiBotMap.subrefPondWaterZones][iAdjWZ][AiBotMap.subrefWZTeamData][iTeam]
                                AddNearbyEnemyThreats(tAdjWZTeamData, true)
                            end
                        end
                        local iNearbyEnemyThreat = AiBotUnitInfo.GetCombatThreatRating(toNearbyEnemyUnits, true, false)
                        if bDebugMessages == true then LOG(sFunctionRef..': iNearbyEnemyThreat='..iNearbyEnemyThreat) end
                        if iNearbyEnemyThreat >= 400 then
                            local iApproachingEnemyThreat = AiBotUnitInfo.GetCombatThreatRating(toApproachingEnemies, true, false)
                            if iNearbyEnemyThreat + iApproachingEnemyThreat >= 800 then
                                local iThreatFactor = 1.5 + oACU:GetWorkProgress() * 0.5
                                if not(oACU[refbUseACUAggressively]) and AiBotTeam.tTeamData[iTeam][AiBotTeam.refbAssassinationOrSimilar] then iThreatFactor = iThreatFactor - 0.5 end
                                if bDebugMessages == true then LOG(sFunctionRef..': iApproachingEnemyThreat='..iApproachingEnemyThreat..'; Cur LZ friendly combat='..tLZOrWZTeamData[AiBotMap.subrefLZTThreatAllyCombatTotal]..'; iThreatFactor='..iThreatFactor) end
                                if (iNearbyEnemyThreat + iApproachingEnemyThreat) * iThreatFactor > math.max(tLZOrWZTeamData[AiBotMap.subrefLZTThreatAllyCombatTotal], AiBotUnitInfo.GetCombatThreatRating(oACU)) then
                                    if bDebugMessages == true then LOG(sFunctionRef..': Will return to base if we also want to run') end
                                    if DoesACUWantToRun(iPlateauOrZero, iLandOrWaterZone, tLZOrWZData, tLZOrWZTeamData, oACU) then
                                        if bDebugMessages == true then LOG(sFunctionRef..': Want to cancel upgrade and return to base') end
                                        AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
                                        return true
                                    end
                                end
                            end
                        end
                    end
                end
                --If enemy has approaching experimental also run
                if AiBotUtilities.IsTableEmpty(AiBotTeam.tTeamData[iTeam][AiBotTeam.reftEnemyLandExperimentals]) == false and oACU:GetWorkProgress() <= 0.7 then
                    for iExp, oExp in AiBotTeam.tTeamData[iTeam][AiBotTeam.reftEnemyLandExperimentals] do
                        if not(oExp.Dead) and oExp[AiBotUnitInfo.reftAssignedPlateauAndLandZoneByTeam][iTeam][1] == iPlateauOrZero and AiBotUtilities.GetDistanceBetweenPositions(oACU:GetPosition(), oExp:GetPosition()) <= 100 and DoesACUWantToRun(iPlateauOrZero, iLandOrWaterZone, tLZOrWZData, tLZOrWZTeamData, oACU) then
                            if bDebugMessages == true then LOG(sFunctionRef..': want to cancel upgrade due to approaching enemy experimental') end
                            AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
                            return true
                        end
                    end
                end
            end

            --Run if enemy still has some of an air threat and we have better eco than them and our ACU lacks 3+ upgradews and not early-game
            if (GetGameTimeSeconds() >= 300 or AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestFriendlyFactoryTech] >= 2) and not(oACU[refbUseACUAggressively]) and AiBotTeam.tTeamData[iTeam][AiBotTeam.refiEnemyAirToGroundThreat] >= 400 and AiBotTeam.tTeamData[iTeam][AiBotTeam.refbAssassinationOrSimilar] and tLZOrWZTeamData[AiBotMap.refiModDistancePercent] >= 0.25 and oACU[refiUpgradeCount] < 3 then
                local iEnemyEco = 0
                if AiBotUtilities.IsTableEmpty(AiBotTeam.tTeamData[iTeam][AiBotTeam.subreftoEnemyBrains]) == false then
                    for iBrain, oBrain in AiBotTeam.tTeamData[iTeam][AiBotTeam.subreftoEnemyBrains] do
                        iEnemyEco = iEnemyEco + oBrain:GetEconomyIncome('MASS')
                    end
                end
                --Assume a player would have a reasonable sense of if very far ahead on eco, so will use a much higher eco threshold as a rough proxy of just 'we are ahead on eco
                if bDebugMessages == true then LOG(sFunctionRef..': iEnemyEco='..iEnemyEco..'; Gross mass='..AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossMass]) end
                if iEnemyEco * 1.35 < AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossMass] then
                    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
                    return true
                end
            end



            --Run if we are underwater or on a different island to our core base and enemy has subs
            local bWaterIsDangerous = (AiBotTeam.tTeamData[iTeam][AiBotTeam.refiEnemySubCount] or 0) >= 2
            if not(bWaterIsDangerous) then
                bWaterIsDangerous = not(AiBotUtilities.IsTableEmpty(AiBotTeam.tTeamData[iTeam][AiBotTeam.reftoEnemyTorpBombers]))
                if not(bWaterIsDangerous) then
                    --If enemy has T3 air or T2 navy then treat water as dangerous for ACU
                    if AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestEnemyNavyTech] >= 2 or AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestEnemyAirTech] >= 3 then
                        bWaterIsDangerous = true
                    elseif AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestEnemyAirTech] >= 2 and AiBotTeam.tAirSubteamData[oACU:GetAIBrain().AiBotAirSubteam][AiBotTeam.refbFarBehindOnAir] then
                        bWaterIsDangerous = true
                    end
                end
            end
            if bDebugMessages == true then LOG(sFunctionRef..': bWaterIsDangerous='..tostring(bWaterIsDangerous)..'; Is ACU underwtaer='..tostring(AiBotUnitInfo.IsUnitUnderwater(oACU))) end
            --If ACU has torpedo upgrade and good health dont treat water as dangerous
            if (oACU[AiBotUnitInfo.refiAntiNavyRange] or 0) > 10 and iACUHealthPercentage >= 0.75 and (AiBotTeam.tTeamData[iTeam][AiBotTeam.refiEnemyTorpBombersThreat] <= 600 or (AiBotTeam.tTeamData[iTeam][AiBotTeam.refiEnemyTorpBombersThreat] <= 5000 and AiBotTeam.tAirSubteamData[oACU:GetAIBrain().AiBotAirSubteam][AiBotTeam.refbHaveAirControl])) then
                if bDebugMessages == true then LOG(sFunctionRef..': ACU has torpedo upgrade and decent health so wont retreat to base') end
                bWaterIsDangerous = false
            end
            if bWaterIsDangerous then
                --If ACU has 1+ upgrade, 95% health (80% if on land that is part of a high value island), and its movement target isn't more than 60% away from our base or 200 if higher, then dont run
                local bWantACUToRun = false
                if AiBotUnitInfo.IsUnitUnderwater(oACU) then
                    bWantACUToRun = true --default - will reconsider below
                else
                    local iNearestBaseIsland = NavUtils.GetLabel(AiBotMap.refPathingTypeLand, tLZOrWZTeamData[AiBotMap.reftClosestFriendlyBase])
                    local iCurIsland = NavUtils.GetLabel(AiBotMap.refPathingTypeLand, oACU:GetPosition())
                    if bDebugMessages == true then LOG(sFunctionRef..': iNearestBaseIsland='..(iNearestBaseIsland or 'nil')..'; iCurIsland='..(iCurIsland or 'nil')) end
                    if not(iNearestBaseIsland == iCurIsland) then

                        bWantACUToRun = true --default, will reconsider below
                    end
                end
                if bWantACUToRun and (oACU[refiUpgradeCount] or 0) >= 1 then
                    local iHealthPercent = iACUHealthPercentage
                    if iHealthPercent >= 0.8 then
                        local tLastOrder = oACU[AiBotOrders.reftiLastOrders][oACU[AiBotOrders.refiOrderCount]]
                        if bDebugMessages == true then LOG(sFunctionRef..': repru(tLZData[AiBotMap.subrefMidpoint])='..repru(tLZOrWZData[AiBotMap.subrefMidpoint])..'; iPlateau='..(iPlateauOrZero or 'nil')..'; iLandZone='..(iLandOrWaterZone or 'nil')..'Is ACU underwater='..tostring(AiBotUnitInfo.IsUnitUnderwater(oACU))..'; tLastOrder='..reprs(tLastOrder)) end
                        local iDistToBase
                        --Get nearest base to us
                        local tNearestFriendlyBase
                        local tNearestEnemyBase
                        if tLZOrWZTeamData[AiBotMap.reftClosestFriendlyBase] then
                            tNearestFriendlyBase = {tLZOrWZTeamData[AiBotMap.reftClosestFriendlyBase][1], tLZOrWZTeamData[AiBotMap.reftClosestFriendlyBase][2], tLZOrWZTeamData[AiBotMap.reftClosestFriendlyBase][3]}
                            tNearestEnemyBase = {tLZOrWZTeamData[AiBotMap.reftClosestEnemyBase][1], tLZOrWZTeamData[AiBotMap.reftClosestEnemyBase][2], tLZOrWZTeamData[AiBotMap.reftClosestEnemyBase][3]}
                        else
                            --Use our start position
                            local aiBrain = oACU:GetAIBrain()
                            local iStartPositionX, iStartPositionZ = AiBotMap.GetPlayerStartPosition(aiBrain, true)
                            tNearestFriendlyBase = { iStartPositionX, GetTerrainHeight(iStartPositionX, iStartPositionZ), iStartPositionZ }
                            tNearestEnemyBase = aiBrain[AiBotOverseer.refoNearestEnemyBrain][AiBotOverseer.refoNearestEnemyBrain]
                        end

                        if tLastOrder and AiBotUtilities.IsTableEmpty(tLastOrder[AiBotOrders.subreftOrderPosition]) == false then
                            if bDebugMessages == true then LOG(sFunctionRef..': tNearestFriendlyBase='..repru(tNearestFriendlyBase)..'; tLastOrder[AiBotOrders.subreftOrderPosition]='..repru(tLastOrder[AiBotOrders.subreftOrderPosition])) end
                            iDistToBase = AiBotUtilities.GetDistanceBetweenPositions(tNearestFriendlyBase, tLastOrder[AiBotOrders.subreftOrderPosition])
                        else
                            iDistToBase = AiBotUtilities.GetDistanceBetweenPositions(tNearestFriendlyBase, oACU:GetPosition())
                        end
                        if bDebugMessages == true then LOG(sFunctionRef..': iDistToBase='..iDistToBase..'; iHealthPercent='..iHealthPercent..'; Enemy naval tech='..(AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestEnemyNavyTech] or 0)..'; Enemy sub count='..(AiBotTeam.tTeamData[iTeam][AiBotTeam.refiEnemySubCount] or 0)) end
                        if iDistToBase <= math.max(250, AiBotUtilities.GetDistanceBetweenPositions(tNearestEnemyBase, tNearestFriendlyBase) * 0.5) then
                            if iHealthPercent >= 0.95 or ((AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestEnemyNavyTech] or 0) <= 1 and (AiBotTeam.tTeamData[iTeam][AiBotTeam.refiEnemySubCount] or 0) <= 7) then
                                bWantACUToRun = false
                            end
                        end
                    end
                    if bWantACUToRun and iHealthPercent >= 0.75 then
                        --Exception - ACU has at least 75% health, and doesnt have far to travel underwater to reach its destination
                        local tLastOrder = oACU[AiBotOrders.reftiLastOrders][oACU[AiBotOrders.refiOrderCount]]
                        if tLastOrder[AiBotOrders.subrefiOrderType] == AiBotOrders.refiOrderIssueMove then
                            local iDistUntilIsland = 200
                            local iIslandRefWanted = NavUtils.GetLabel(AiBotMap.refPathingTypeLand,  tLastOrder[AiBotOrders.subreftOrderPosition])
                            local iAngleToTarget = AiBotUtilities.GetAngleFromAToB(oACU:GetPosition(), tLastOrder[AiBotOrders.subreftOrderPosition])
                            local bArePassingEnemyAntiNavyThreat = false
                            for iCurDist = 10, 70, 10 do
                                local tTempMoveLocation = AiBotUtilities.MoveInDirection(oACU:GetPosition(), iAngleToTarget, iCurDist, true, true, false)
                                if bDebugMessages == true then LOG(sFunctionRef..': iCurDist='..iCurDist..'; Island ref='..(NavUtils.GetLabel(AiBotMap.refPathingTypeLand, tTempMoveLocation) or 'nil')..'; iIslandRefWanted='..(iIslandRefWanted or 'nil')) end
                                if not(bArePassingEnemyAntiNavyThreat) then
                                    local tMoveLocationData, tMoveLocationTeamData = AiBotMap.GetLandOrWaterZoneData(tTempMoveLocation, true, iTeam)
                                    if (tMoveLocationTeamData[AiBotMap.subrefWZThreatEnemyAntiNavy] or 0) > 0 then bArePassingEnemyAntiNavyThreat = true end
                                end
                                if tTempMoveLocation and NavUtils.GetLabel(AiBotMap.refPathingTypeLand, tTempMoveLocation) == iIslandRefWanted then
                                    iDistUntilIsland = iCurDist
                                    break
                                end
                            end
                            if bDebugMessages == true then LOG(sFunctionRef..': iDistUntilIsland (defaults to 200 if couldnt find island after 60)='..iDistUntilIsland..'; iHealthPercent='..iHealthPercent..'; 30 +  (iHealthPercent - 0.75) * 30)='..30 +  (iHealthPercent - 0.75) * 30) end
                            if iDistUntilIsland <= 70 and (iDistUntilIsland <= 30 or (not(bArePassingEnemyAntiNavyThreat) and iHealthPercent >= 0.9) or iDistUntilIsland <= 30 +  (iHealthPercent - 0.75) / 0.25 * 40) then
                                bWantACUToRun = false
                            end
                        end
                    end
                end
                if bDebugMessages == true then LOG(sFunctionRef..': Do we want to return to base due to water being dangerous? bWantACUToRun='..tostring(bWantACUToRun)) end
                AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
                return bWantACUToRun
            end
        end
    end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
end

function GiveOverchargeOrderIfRelevant(tLZData, tLZTeamData, oACU, iPlateauOrZero, iLandOrWaterZone)
    --Are there enemies in this LZ or adjacent, and do we have the energy to overcharge?
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    local sFunctionRef = 'GiveOverchargeOrderIfRelevant'
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)



    if bDebugMessages == true then LOG(sFunctionRef..': Time='..GetGameTimeSeconds()..'; DO we have enemies in this or adjacent LZ='..tostring(tLZTeamData[AiBotMap.subrefbEnemiesInThisOrAdjacentLZ])..'; tLZTeamData[AiBotMap.subrefbDangerousEnemiesInAdjacentWZ]='..tostring(tLZTeamData[AiBotMap.subrefbDangerousEnemiesInAdjacentWZ])..'; Can we use overcharge='..tostring(AiBotConditions.CanUnitUseOvercharge(oACU:GetAIBrain(), oACU))..'; iPlateauOrZero='..(iPlateauOrZero or 'nil')..'; iLandOrWaterZone='..(iLandOrWaterZone or 'nil')) end

    if iPlateauOrZero > 0 and ((tLZTeamData[AiBotMap.subrefbEnemiesInThisOrAdjacentLZ] or tLZTeamData[AiBotMap.subrefbDangerousEnemiesInAdjacentWZ]) and AiBotConditions.CanUnitUseOvercharge(oACU:GetAIBrain(), oACU, tLZTeamData)) then
        --Dont overcharge if have teleport as can affect targeting and delay the return jump
        if not(oACU[refbACUHasTeleport]) then
            local bDoesACUWantToRun = DoesACUWantToRun(iPlateauOrZero, iLandOrWaterZone, tLZData, tLZTeamData, oACU)
            local oUnitToOvercharge = AiBotMicro.GetOverchargeTarget(tLZData, oACU:GetAIBrain(), oACU, bDoesACUWantToRun)
            if bDebugMessages == true then LOG(sFunctionRef..': Do we have a valid OC target='..tostring(AiBotUnitInfo.IsUnitValid(oUnitToOvercharge))) end
            if oUnitToOvercharge then
                --Redundancy - in some cases when we want to overcharge (e.g. replay 21026248 at 13m08) we can be stuck and not overcharge; therefore if we were already trying to overcharge this unit, and haven't fired our weapon in 2 seconds, then abort
                local tLastOrder = oACU[AiBotOrders.reftiLastOrders][1]
                if tLastOrder[AiBotOrders.subrefiOrderType] == AiBotOrders.refiOrderOvercharge and tLastOrder[AiBotOrders.subrefoOrderUnitTarget] == oUnitToOvercharge and GetGameTimeSeconds() - (oACU[AiBotUnitInfo.refiLastWeaponEvent] or -100) >= 2.5 then
                    if bDebugMessages == true then LOG(sFunctionRef..': ACU weapon might be stuck so clearing overcharge order') end
                    AiBotOrders.IssueTrackedClearCommands(oACU)
                    oACU[AiBotUnitInfo.refbSpecialMicroActive] = false
                else
                    AiBotOrders.IssueTrackedOvercharge(oACU, oUnitToOvercharge, false, 'OC', true)
                    if bDebugMessages == true then LOG(sFunctionRef..': Have just told ACU '..oACU.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oACU)..' owned by '..oACU:GetAIBrain().Nickname..' to overcharge '..oUnitToOvercharge.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnitToOvercharge)..'; Dist to this unit='..AiBotUtilities.GetDistanceBetweenPositions(oACU:GetPosition(), oUnitToOvercharge:GetPosition())..'; ACU DF range='..oACU[AiBotUnitInfo.refiDFRange]) end
                    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
                    return true
                end
            end
        end
    end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
    return false
end

function AttackNearestEnemyWithACU(iPlateau, iLandZone, tLZData, tLZTeamData, oACU, iOptionalDistThresholdOverride, bReturnClosestOutOfThresholdDistance)
    --Attack move to the nearest enemy if we arent in range of it or retreat if we are in range of it
    --returns true if given order; returns false if not, and optionally returns the closest enemy dist
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    local sFunctionRef = 'AttackNearestEnemyWithACU'
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)
    local aiBrain = oACU:GetAIBrain()
    local bDualGapAirHomeOnly = aiBrain.AiBotDualGapRole == 'top_air' or aiBrain.AiBotDualGapRole == 'bottom_air'
    if bDualGapAirHomeOnly and not tLZTeamData[AiBotMap.subrefLZbCoreBase] then
        AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
        return false
    end



    local oEnemyToTarget
    local iClosestOutOfThresholdDistance = 10000
    if (oACU[AiBotUnitInfo.refiDFRange] or 0) > 0 and iPlateau > 0 then
        local iCurDist

        local tUnitsToTarget
        local iTeam = aiBrain.AiBotTeam
        local iDistThreshold
        if iOptionalDistThresholdOverride then iDistThreshold = iOptionalDistThresholdOverride
        else
            if (oACU[refiUpgradeCount] or 0) > 0 then
                iDistThreshold = 70
                if oACU[refiUpgradeCount] >= 2 and (oACU[refiUpgradeCount] >= 3 or not(EntityCategoryContains(categories.AEON, oACU.UnitId))) and AiBotUnitInfo.GetUnitHealthPercent(oACU) >= 0.95 and (tLZData[AiBotMap.subrefTotalSignificantMassReclaim] or 0) <= 250 then
                    local iMassCostOfEnemyUnits = AiBotUnitInfo.GetMassCostOfUnits(tLZTeamData[AiBotMap.reftoNearestDFEnemies], true)
                    if iMassCostOfEnemyUnits < 200 then
                        iDistThreshold = 80
                    elseif AiBotTeam.tTeamData[iTeam][AiBotTeam.refbAssassinationOrSimilar] then
                        iDistThreshold = 90
                    elseif iMassCostOfEnemyUnits >= 1000 then
                        iDistThreshold = 110
                    else
                        iDistThreshold = 105
                    end
                end
                if bDebugMessages == true then LOG(sFunctionRef..': Finished deciding dist threshold for upgraded ACU, UpgradeCount='..oACU[refiUpgradeCount]..'; Health%='..AiBotUnitInfo.GetUnitHealthPercent(oACU)..'; Mass value of DF enemies='..AiBotUnitInfo.GetMassCostOfUnits(tLZTeamData[AiBotMap.reftoNearestDFEnemies], true)..'; iDistThreshold='..iDistThreshold) end
            else iDistThreshold = 60
            end
        end

        if bDebugMessages == true then LOG(sFunctionRef..': Adding table of enemy units to consider targeting, is table of nearest DF enemies empty='..tostring(AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.reftoNearestDFEnemies]))) end
        local bCheckCurTarget = false
        if AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.reftoNearestDFEnemies]) == false then
            tUnitsToTarget = tLZTeamData[AiBotMap.reftoNearestDFEnemies]
            iDistThreshold = iDistThreshold + 10
            bCheckCurTarget = true
            if bDebugMessages == true then LOG(sFunctionRef..': Will target nearest enemy DF units') end
        elseif AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.subrefTEnemyUnits]) == false then
            tUnitsToTarget = EntityCategoryFilterDown(categories.ALLUNITS - AiBotUnitInfo.refCategoryLandScout + AiBotUnitInfo.refCategoryCombatScout, tLZTeamData[AiBotMap.subrefTEnemyUnits])
            iDistThreshold = iDistThreshold + 10
            bCheckCurTarget = true
            if bDebugMessages == true then LOG(sFunctionRef..': Will target nearest enemy units') end
        end
        --Search adjacent land zones for enemy units if none in this zone (even if we have nearby DF enemies - i.e. want more accurate/detailed check of nearby DF units if therea re no enemies in ACU cur zone), and consider if they are within 60 of ACU position
        if not bDualGapAirHomeOnly and (tLZTeamData[AiBotMap.subrefTThreatEnemyCombatTotal] or 0) < 350 and AiBotUtilities.IsTableEmpty(tLZData[AiBotMap.subrefLZAdjacentLandZones]) == false then
            if not(tUnitsToTarget) then
                tUnitsToTarget = {}
            end
            local bAlreadyRecorded = false
            for _, iAdjLZ in tLZData[AiBotMap.subrefLZAdjacentLandZones] do
                local tAdjLZTeamData = AiBotMap.tAllPlateaus[iPlateau][AiBotMap.subrefPlateauLandZones][iAdjLZ][AiBotMap.subrefLZTeamData][iTeam]
                if bDebugMessages == true then LOG(sFunctionRef..': Checking for enemies in iAdjLZ='..iAdjLZ..'; Is table of enemy units empty='..tostring(AiBotUtilities.IsTableEmpty(tAdjLZTeamData[AiBotMap.subrefTEnemyUnits]))) end
                if AiBotUtilities.IsTableEmpty(tAdjLZTeamData[AiBotMap.subrefTEnemyUnits]) == false then
                    local tEnemiesAlreadyRecorded = tUnitsToTarget
                    for iUnit, oUnit in tAdjLZTeamData[AiBotMap.subrefTEnemyUnits] do
                        if AiBotUnitInfo.IsUnitValid(oUnit) then
                            if bDebugMessages == true then LOG(sFunctionRef..': Considering enemy unit '..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..'; Dist to ACU='..AiBotUtilities.GetDistanceBetweenPositions(oUnit:GetPosition(), oACU:GetPosition())..'; iDistThreshold='..iDistThreshold) end
                            if not(EntityCategoryContains(AiBotUnitInfo.refCategoryLandScout - categories.SERAPHIM, oUnit.UnitId)) then
                                iCurDist = AiBotUtilities.GetDistanceBetweenPositions(oUnit:GetPosition(), oACU:GetPosition())
                                if iCurDist <= iDistThreshold then
                                    bAlreadyRecorded = false
                                    if AiBotUtilities.IsTableEmpty(tEnemiesAlreadyRecorded) then
                                        --Not recorded
                                    else
                                        for iRecorded, oRecorded in tEnemiesAlreadyRecorded do
                                            if oRecorded == oUnit then
                                                bAlreadyRecorded = true
                                                break
                                            end
                                        end
                                    end
                                    if not(bAlreadyRecorded) then
                                        table.insert(tUnitsToTarget, oUnit)
                                    end
                                elseif iCurDist < iClosestOutOfThresholdDistance then
                                    iClosestOutOfThresholdDistance = iCurDist
                                end
                            end
                        end
                    end
                end
            end
        end
        if AiBotUtilities.IsTableEmpty(tUnitsToTarget) then
            tUnitsToTarget = aiBrain:GetUnitsAroundPoint(AiBotUnitInfo.refCategoryMobileLand + AiBotUnitInfo.refCategoryStructure -AiBotUnitInfo.refCategoryLandScout + AiBotUnitInfo.refCategoryCombatScout, oACU:GetPosition(), iDistThreshold, 'Enemy')
        end
        if bCheckCurTarget and AiBotUtilities.IsTableEmpty(oACU.WeaponInstances) == false then
            for iWeapon, oWeapon in oACU.WeaponInstances do
                if oWeapon.GetCurrentTarget then
                    local oCurTarget = oWeapon:GetCurrentTarget()
                    if bDebugMessages == true and oCurTarget then LOG(sFunctionRef..': Cur weapon target='..oCurTarget.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oCurTarget)..'; with combat range='..(oCurTarget[AiBotUnitInfo.refiCombatRange] or 'nil')) end
                    if AiBotUnitInfo.IsUnitValid(oCurTarget) and (oCurTarget[AiBotUnitInfo.refiCombatRange] or 0) > 0 then
                        if not(oCurTarget[AiBotUnitInfo.reftAssignedPlateauAndLandZoneByTeam][iTeam][1] == iPlateau and oCurTarget[AiBotUnitInfo.reftAssignedPlateauAndLandZoneByTeam][iTeam][2] == iLandZone) then
                            if bDebugMessages == true then LOG(sFunctionRef..': Cur target isnt assigned to this zone so will add into table of units to target') end
                            table.insert(tUnitsToTarget, oCurTarget)
                        end
                    end
                end
            end
        end

        local iClosestDist = iDistThreshold + 1
        if bDebugMessages == true then LOG(sFunctionRef..': Time='..GetGameTimeSeconds()..'; Is table of units to target empty='..tostring(AiBotUtilities.IsTableEmpty(tUnitsToTarget))..'; Is tLZTeamData[AiBotMap.reftoNearestDFEnemies] empty='..tostring(AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.reftoNearestDFEnemies]))..'; iClosestDist='..iClosestDist) end
        if AiBotUtilities.IsTableEmpty(tUnitsToTarget) == false then
            local iOurACUHealthPercent = AiBotUnitInfo.GetUnitHealthAndShieldPercent(oACU)
            local bAbortDueToStartingPD = false
            if tLZTeamData[AiBotMap.subrefLZbCoreBase] and tLZTeamData[AiBotMap.subrefLZThreatEnemyBestStructureDFRange] > oACU[AiBotUnitInfo.refiDFRange] and (GetGameTimeSeconds() <= 300 or (GetGameTimeSeconds() <= 600 and AiBotMap.bIsCampaignMap)) then
                local tPDToTarget = EntityCategoryFilterDown(AiBotUnitInfo.refCategoryPD, tUnitsToTarget)
                if AiBotUtilities.IsTableEmpty(tPDToTarget) == false then
                    bAbortDueToStartingPD = true
                end
            end
            --refiTimeCreated
            local sPathing = AiBotMap.refPathingTypeAmphibious
            local iUnitPlateau, iUnitZone
            local bUnitInFurtherAwayZoneWeRanFrom
            local iStartPlateau, iStartZone = AiBotMap.GetClosestPlateauOrZeroAndZoneToPosition(tLZTeamData[AiBotMap.reftClosestFriendlyBase])
            local iACUZoneTravelDistToBase
            if bDebugMessages == true then LOG(sFunctionRef..': iStartPlateau='..(iStartPlateau or 'nil')..'; iStartZone='..(iStartZone or 'nil')..'; bAbortDueToStartingPD='..tostring(bAbortDueToStartingPD or false)) end
            if bAbortDueToStartingPD then
                AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
                return false
            end
            if iStartPlateau > 0 and iStartZone > 0 then
                if iPlateau > 0 then
                    iACUZoneTravelDistToBase = AiBotMap.GetTravelDistanceBetweenLandZones(iPlateau, iLandZone, iStartZone)
                else
                    iACUZoneTravelDistToBase = AiBotUtilities.GetTravelDistanceBetweenPositions(tLZData[AiBotMap.subrefMidpoint], tLZTeamData[AiBotMap.reftClosestFriendlyBase], AiBotMap.refPathingTypeAmphibious)
                end
            end
            local iUnitInZoneRanFromDistThresholdIfOutrange = oACU[AiBotUnitInfo.refiDFRange] + 7
            local iUnitInZoneRanFromDistThresholdIfDontOutrange = oACU[AiBotUnitInfo.refiDFRange] + 2
            local iRanFromDistThreshold
            local iClosestUnshieldedDist = 10000
            local oClosestUnshielded
            function ConsiderUnitsToTarget(tCurUnitsToTarget)
                for iUnit, oUnit in tCurUnitsToTarget do
                    if AiBotUnitInfo.IsUnitValid(oUnit) and not(AiBotUnitInfo.IsUnitUnderwater(oUnit)) then
                        --Is unit in a zone that we have recently run from and that zone is further from our base than our current position?
                        iUnitPlateau, iUnitZone = AiBotMap.GetClosestPlateauOrZeroAndZoneToPosition(oUnit:GetPosition())
                        bUnitInFurtherAwayZoneWeRanFrom = false
                        if bDebugMessages == true then LOG(sFunctionRef..': Checking if unit in zone we recently ran from, oUnit='..(oUnit.UnitId or 'nil')..(AiBotUnitInfo.GetUnitLifetimeCount(oUnit) or 'nil')..'; iUnitPlateau='..(iUnitPlateau or 'nil')..'; iUnitZone='..(iUnitZone or 'nil')) end
                        if iUnitPlateau > 0 and iUnitZone > 0 and not((iUnitZone == iLandZone and iUnitPlateau == iPlateau)) and (oACU[reftiTimeLastRanFromZoneByPlateau][iUnitPlateau][iUnitZone] and GetGameTimeSeconds() - oACU[reftiTimeLastRanFromZoneByPlateau][iUnitPlateau][iUnitZone] < 30) or (oACU[refiLastPlateauAndZoneToAttackUnitIn][2] == iUnitZone and oACU[refiLastPlateauAndZoneToAttackUnitIn][1] == iUnitPlateau and GetGameTimeSeconds() - (oACU[refiTimeLastToldToAttackUnitInOtherZone] or -100) < 30) then
                            --Unit in zone we ran from, dont want to attack it unless zone is closer to our base than our current zone, or enemy is close
                            if iACUZoneTravelDistToBase and not(tLZTeamData[AiBotMap.subrefLZbCoreBase]) then
                                if oUnit[AiBotUnitInfo.refiCombatRange] >= oACU[AiBotUnitInfo.refiDFRange] then
                                    iRanFromDistThreshold = iUnitInZoneRanFromDistThresholdIfDontOutrange
                                else
                                    iRanFromDistThreshold = iUnitInZoneRanFromDistThresholdIfOutrange
                                end

                                if AiBotUtilities.GetDistanceBetweenPositions(oACU:GetPosition(), oUnit:GetPosition()) >= iRanFromDistThreshold and AiBotMap.GetTravelDistanceBetweenLandZones(iPlateau, iLandZone, iUnitZone) > iACUZoneTravelDistToBase then
                                    bUnitInFurtherAwayZoneWeRanFrom = true
                                end
                            end
                        end
                        if bDebugMessages == true then LOG(sFunctionRef..': Considering enemy unit '..(oUnit.UnitId or 'nil')..(AiBotUnitInfo.GetUnitLifetimeCount(oUnit) or 'nil')..'; iCurDist='..(AiBotUtilities.GetTravelDistanceBetweenPositions(oACU:GetPosition(), oUnit:GetPosition(), sPathing) or 'nil')..'; bUnitInFurtherAwayZoneWeRanFrom='..tostring(bUnitInFurtherAwayZoneWeRanFrom or false)..'; iUnitZone='..(iUnitZone or 'nil')..'; refiLastPlateauAndZoneToAttackUnitIn='..reprs(oACU[refiLastPlateauAndZoneToAttackUnitIn])..'; refiTimeLastToldToAttackUnitInOtherZone='..reprs(oACU[refiTimeLastToldToAttackUnitInOtherZone])..'; Is unit under shield='..tostring(AiBotLogic.IsTargetUnderShield(aiBrain, oUnit, 3000, false, false, false, false, false))..'; iUnitPlateau='..iUnitPlateau) end
                        if not(bUnitInFurtherAwayZoneWeRanFrom) then
                            --iCurDist = AiBotUtilities.GetDistanceBetweenPositions(oACU:GetPosition(), oUnit:GetPosition())
                            iCurDist = AiBotUtilities.GetTravelDistanceBetweenPositions(oACU:GetPosition(), oUnit:GetPosition(), sPathing)
                            if iCurDist then
                                --If unit in water and we cant reach it with DF then ignore
                                if iUnitPlateau == 0 and iClosestDist > 1 + oACU[AiBotUnitInfo.refiDFRange] and not(NavUtils.GetLabel(AiBotMap.refPathingTypeLand, AiBotUtilities.MoveInDirection(oUnit:GetPosition(), AiBotUtilities.GetAngleFromAToB(oUnit:GetPosition(), oACU:GetPosition()), oACU[AiBotUnitInfo.refiDFRange], true, true, false)) == (tLZData[AiBotMap.subrefLZIslandRef] or 0)) then
                                    if bDebugMessages == true then LOG(sFunctionRef..': Nearby naval unit, but it doesnt look like we can reach it if we advance, so we will ignore it') end
                                elseif iCurDist < iClosestDist then
                                    iClosestDist = iCurDist
                                    oEnemyToTarget = oUnit
                                    if not(AiBotLogic.IsTargetUnderShield(aiBrain, oUnit, 3000, false, false, false, false, false)) then
                                        oClosestUnshielded = oUnit
                                        iClosestUnshieldedDist = iCurDist
                                    end
                                elseif iCurDist < iClosestUnshieldedDist and not(AiBotLogic.IsTargetUnderShield(aiBrain, oUnit, 3000, false, false, false, false, false)) then
                                    oClosestUnshielded = oUnit
                                    iClosestUnshieldedDist = iCurDist
                                    if bReturnClosestOutOfThresholdDistance and iCurDist < iClosestOutOfThresholdDistance then iClosestOutOfThresholdDistance = iCurDist end
                                elseif bReturnClosestOutOfThresholdDistance and iCurDist < iClosestOutOfThresholdDistance then iClosestOutOfThresholdDistance = iCurDist
                                end
                            end
                        end
                    end
                end
            end
            ConsiderUnitsToTarget(tUnitsToTarget)

            local bNearestEnemyIsShieldedButEnemyToTargetLacksShield = false
            if bDebugMessages == true then LOG(sFunctionRef..': Considering if want to switch to unshielded target, is oClosestUnshielded same as oEnemyToTarget='..tostring(oEnemyToTarget == oClosestUnshielded)..'; iClosestUnshieldedDist='..(iClosestUnshieldedDist or 'nil')..'; iClosestDist='..iClosestDist) end
            if oClosestUnshielded and not(oEnemyToTarget == oClosestUnshielded) and (iClosestUnshieldedDist < oACU[AiBotUnitInfo.refiDFRange] + 2 or iClosestUnshieldedDist - 4 < iClosestDist) then
                bNearestEnemyIsShieldedButEnemyToTargetLacksShield = true
                oEnemyToTarget = oClosestUnshielded
                if bDebugMessages == true then LOG(sFunctionRef..': Switched enemy to target to the closest unshielded enmey') end
            end
            --If we have a friendly ACU near an enemy ACU, and we arent outranged by it, and this is relatively early on (we have T1-T2 tech) then go to help the friendly ACU
            if not(oEnemyToTarget) and not(AiBotTeam.tTeamData[iTeam][AiBotTeam.refbDangerousForACUs]) and not(AiBotTeam.tTeamData[iTeam][AiBotTeam.refbAssassinationOrSimilar]) and aiBrain[AiBotEconomy.refiOurHighestFactoryTechLevel] <= 2 and GetGameTimeSeconds() <= 1200
                    --Also check enemy lacks PD/mobile land units in this zone that outranges us (will check for ACU zone in a bit)
                    and tLZTeamData[AiBotMap.subrefLZThreatEnemyBestMobileDFRange] <= oACU[AiBotUnitInfo.refiDFRange] and tLZTeamData[AiBotMap.subrefLZThreatEnemyBestStructureDFRange] <= oACU[AiBotUnitInfo.refiDFRange] then
                local toNearbyFriendlyACUs = {}
                local iFriendlyACUSearchDistance = 100
                for iFriendlyACU, oFriendlyACU in AiBotTeam.tTeamData[iTeam][AiBotTeam.reftAiBotACUs] do
                    if not(oFriendlyACU == oACU) and not(oFriendlyACU.Dead) and AiBotUtilities.GetDistanceBetweenPositions(oFriendlyACU:GetPosition(), oACU:GetPosition()) <= iFriendlyACUSearchDistance then
                        table.insert(toNearbyFriendlyACUs, oFriendlyACU)
                    end
                end
                if AiBotUtilities.IsTableEmpty(toNearbyFriendlyACUs) == false then
                    local iEnemyACUSearchDistance = iFriendlyACUSearchDistance + 35
                    local iOurDistToACU, iFriendlyDistToACU
                    if AiBotUtilities.IsTableEmpty(AiBotTeam.tTeamData[iTeam][AiBotTeam.reftEnemyACUs]) == false then
                        for iEnemyACU, oEnemyACU in AiBotTeam.tTeamData[iTeam][AiBotTeam.reftEnemyACUs] do
                            if not(oEnemyACU.Dead) then
                                iOurDistToACU = AiBotUtilities.GetDistanceBetweenPositions(oACU:GetPosition(), oEnemyACU:GetPosition())
                                if bDebugMessages == true then LOG(sFunctionRef..': Considering enemy ACU owned by '..oEnemyACU:GetAIBrain().Nickname..'; iOurDistToACU='..iOurDistToACU..'; iEnemyACUSearchDistance='..iEnemyACUSearchDistance) end
                                if iOurDistToACU <= iEnemyACUSearchDistance and not(AiBotUnitInfo.IsUnitUnderwater(oEnemyACU)) then
                                    if oEnemyACU[AiBotUnitInfo.refiDFRange] > oACU[AiBotUnitInfo.refiDFRange] then
                                        if bDebugMessages == true then LOG(sFunctionRef..': enemy has an ACU that outranges us and is relatively close so we wont consider supporting friendly ACUs') end
                                        oEnemyToTarget = nil --redundancy
                                        break
                                    else
                                        --Enemy ACU is close enough to us that we might be able to help in the fight; is it closer to a friendly ACU than to us (and by a notable distance)
                                        for iFriendlyACU, oFriendlyACU in toNearbyFriendlyACUs do
                                            iFriendlyDistToACU = AiBotUtilities.GetDistanceBetweenPositions(oFriendlyACU:GetPosition(), oEnemyACU:GetPosition())
                                            if iFriendlyDistToACU < iOurDistToACU - 5 and iFriendlyDistToACU < math.min(iOurDistToACU - 15, 15 + oACU[AiBotUnitInfo.refiDFRange]) then
                                                iEnemyACUSearchDistance = iOurDistToACU
                                                oEnemyToTarget = oEnemyACU
                                            end
                                        end
                                    end
                                end
                            end
                        end
                    end
                    if oEnemyToTarget then
                        if oEnemyToTarget[AiBotUnitInfo.reftAssignedPlateauAndLandZoneByTeam][iTeam][1] == iPlateau then
                            --Check enemy doesnt have any T2 PD (or T1 PD if we have short range) near the enemy ACU (we have already checked for the zone we are in)
                            if not(oEnemyToTarget[AiBotUnitInfo.reftAssignedPlateauAndLandZoneByTeam][iTeam][2] == iLandZone) then
                                local tEnemyACULZTeamData = AiBotMap.tAllPlateaus[iPlateau][AiBotMap.subrefPlateauLandZones][oEnemyToTarget[AiBotUnitInfo.reftAssignedPlateauAndLandZoneByTeam][iTeam][2]][AiBotMap.subrefLZTeamData][iTeam]
                                if tEnemyACULZTeamData[AiBotMap.subrefLZThreatEnemyBestMobileDFRange] > oACU[AiBotUnitInfo.refiDFRange] or tEnemyACULZTeamData[AiBotMap.subrefLZThreatEnemyBestStructureDFRange] > oACU[AiBotUnitInfo.refiDFRange] then
                                    if bDebugMessages == true then LOG(sFunctionRef..': enemy has DF units that outrange our ACU in the target zone, wont target/assist the ACU fight') end
                                    oEnemyToTarget = nil
                                end
                            end
                        else
                            oEnemyToTarget = nil
                            if bDebugMessages == true then LOG(sFunctionRef..': We cant path to enemy ACU') end
                        end
                    end
                end
                if bDebugMessages == true then LOG(sFunctionRef..': Finsihed considering if we want to go help a friendly ACU fight, Is toNearbyFriendlyACUs empty='..tostring(AiBotUtilities.IsTableEmpty(toNearbyFriendlyACUs))) end
            end
            --Target non-DF units in this zone if we failed to find DF units nearby to target but do have some nearby
            if not(oEnemyToTarget) and AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.subrefTEnemyUnits]) == false and AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.reftoNearestDFEnemies]) == false then
                local tAltUnitsToTarget = EntityCategoryFilterDown(categories.ALLUNITS - AiBotUnitInfo.refCategoryLandScout + AiBotUnitInfo.refCategoryCombatScout - categories.DIRECTFIRE, tLZTeamData[AiBotMap.subrefTEnemyUnits])
                if bDebugMessages == true then LOG(sFunctionRef..': Failed to find normal target from enemy DF units (e.g. they are in zones we have recently retreated from) but have enemies in this zone that we can consider targeting as well, is tAltUnitsToTarget empty='..tostring(AiBotUtilities.IsTableEmpty(tAltUnitsToTarget))) end
                if AiBotUtilities.IsTableEmpty(tAltUnitsToTarget) == false then
                    ConsiderUnitsToTarget(tAltUnitsToTarget)
                end
            end
            if bDebugMessages == true then LOG(sFunctionRef..': oEnemyToTarget='..(oEnemyToTarget.UnitId or 'nil')..(AiBotUnitInfo.GetUnitLifetimeCount(oEnemyToTarget) or 'nil')) end
            if oEnemyToTarget then
                local iUnitPlateau, iUnitZone = AiBotMap.GetClosestPlateauOrZeroAndZoneToPosition(oEnemyToTarget:GetPosition())
                local iMaxDistToBeInRange = 5 --placeholder
                if iUnitZone > 0 then
                    if not(oACU[refiLastPlateauAndZoneToAttackUnitIn]) then oACU[refiLastPlateauAndZoneToAttackUnitIn] = {} end
                    oACU[refiTimeLastToldToAttackUnitInOtherZone] = GetGameTimeSeconds()
                    oACU[refiLastPlateauAndZoneToAttackUnitIn] = {iUnitPlateau, iUnitZone}
                end
                if oACU[AiBotUnitInfo.refbLastShotBlocked] then
                    --Shot blocked, but we must think we can win the fight or we would be running, so move towards enemy, or (if there is an enemy in range we can hit attack that enemy)
                    local oEnemyToAttack
                    if iPlateau > 0 then
                        --Are we akready targeting an enemy? in which case keep targeting if not blocked
                        if oACU[AiBotOrders.reftiLastOrders][1][AiBotOrders.subrefiOrderType] == AiBotOrders.refiOrderIssueAttack and AiBotUnitInfo.IsUnitValid(oACU[AiBotOrders.reftiLastOrders][1][AiBotOrders.subrefoOrderUnitTarget]) and AiBotUtilities.GetDistanceBetweenPositions(oACU:GetPosition(),oACU[AiBotOrders.reftiLastOrders][1][AiBotOrders.subrefoOrderUnitTarget]:GetPosition()) <= oACU[AiBotUnitInfo.refiDFRange] and not(AiBotLogic.IsShotBlocked(oACU, oACU[AiBotOrders.reftiLastOrders][1][AiBotOrders.subrefoOrderUnitTarget], false, nil)) then
                            oEnemyToAttack = oACU[AiBotOrders.reftiLastOrders][1][AiBotOrders.subrefoOrderUnitTarget]
                            if bDebugMessages == true then LOG(sFunctionRef..': Will continue attacking last order target') end
                        else
                            local tEnemiesInRange = aiBrain:GetUnitsAroundPoint(AiBotUnitInfo.refCategoryPD + AiBotUnitInfo.refCategoryLandCombat, oACU:GetPosition(), (oACU[AiBotUnitInfo.refiDFRange] or 2) - 1, 'Enemy')
                            local iClosestEnemyNotBlocked = 10000
                            local iCurDist
                            if bDebugMessages == true then LOG(sFunctionRef..': Is tEnemiesInRange empty='..tostring(AiBotUtilities.IsTableEmpty( tEnemiesInRange))) end
                            if AiBotUtilities.IsTableEmpty( tEnemiesInRange) == false then
                                for iEnemy, oEnemy in tEnemiesInRange do
                                    if bDebugMessages == true then LOG(sFunctionRef..': Considering enemy '..oEnemy.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oEnemy)..'; Is shot blocked='..tostring(AiBotLogic.IsShotBlocked(oACU, oEnemy, false, nil))..'; Dist to our ACU='..AiBotUtilities.GetDistanceBetweenPositions(oEnemy:GetPosition(), oACU:GetPosition())) end
                                    if not(AiBotLogic.IsShotBlocked(oACU, oEnemy, false, nil)) then
                                        iCurDist = AiBotUtilities.GetDistanceBetweenPositions(oEnemy:GetPosition(), oACU:GetPosition())
                                        if iCurDist < iClosestEnemyNotBlocked then
                                            oEnemyToAttack = oEnemy
                                            iClosestEnemyNotBlocked = iCurDist
                                        end
                                    end
                                end
                            end
                        end
                    end
                    if bDebugMessages == true then LOG(sFunctionRef..': Shot is blocked, have chekced if enemy we dont htink will be blocked iwthin our DF range to attack, oEnemyToAttack='..(oEnemyToAttack.UnitId or 'nil')..(AiBotUnitInfo.GetUnitLifetimeCount(oEnemyToAttack) or 'nil')) end
                    if oEnemyToAttack then
                        AiBotOrders.IssueTrackedAttack(oACU, oEnemyToAttack, false, 'ACUBAt', false)
                    else
                        AiBotOrders.IssueTrackedMove(oACU, oEnemyToTarget:GetPosition(), 5, false, 'ACUBl', false)
                        if bDebugMessages == true then LOG(sFunctionRef..': ACU shot blocked so will move to enemy') end
                    end
                else
                    iMaxDistToBeInRange = 1.5
                    local iEnemyHighestDFInThisLZ = 0
                    local bConsiderAttackMoveDueToIntel = false
                    if AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.subrefLZThreatEnemyMobileDFByRange]) == false then
                        for iRange, iThreat in tLZTeamData[AiBotMap.subrefLZThreatEnemyMobileDFByRange] do
                            if iThreat >= 20 then
                                iEnemyHighestDFInThisLZ = math.max(iEnemyHighestDFInThisLZ, iRange)
                            end
                        end
                    end

                    if oACU[AiBotUnitInfo.refiDFRange] <= iEnemyHighestDFInThisLZ then
                        if bDebugMessages == true then LOG(sFunctionRef..': Enemy has same or better range than us so want to be reasonable amount in range, iEnemyHighestDFInThisLZ='..iEnemyHighestDFInThisLZ..'; Radar coverage='..tLZTeamData[AiBotMap.refiRadarCoverage]) end
                        iMaxDistToBeInRange = 3.5
                        if (not(AiBotUnitInfo.CanSeeUnit(aiBrain, oEnemyToTarget, false)) or (tLZTeamData[AiBotMap.refiRadarCoverage] < 30 and not(AiBotUnitInfo.IsUnitValid(oACU[AiBotLand.refoAssignedLandScout])))) then
                            iMaxDistToBeInRange = math.max(iMaxDistToBeInRange, math.min(iMaxDistToBeInRange, 3) + oACU[AiBotUnitInfo.refiDFRange] - (oACU:GetBlueprint().Intel.VisionRadius or oACU[AiBotUnitInfo.refiDFRange]))
                            bConsiderAttackMoveDueToIntel = true
                        end
                    elseif oACU[AiBotUnitInfo.refiDFRange] - 6 >= iEnemyHighestDFInThisLZ then
                        --If nearest enemy unit isnt facing us then increase dist to be in range
                        local iAngleDif = AiBotUtilities.GetAngleDifference(AiBotUnitInfo.GetUnitFacingAngle(oEnemyToTarget), AiBotUtilities.GetAngleFromAToB(oEnemyToTarget:GetPosition(), oACU:GetPosition()))
                        if (EntityCategoryContains(categories.COMMAND + AiBotUnitInfo.refCategoryStructure, oEnemyToTarget.UnitId) and not(oEnemyToTarget:IsUnitState('Attacking')) and not(oEnemyToTarget:IsUnitState('Moving'))) then
                            iMaxDistToBeInRange = math.max(3.5, oACU[AiBotUnitInfo.refiDFRange] - iEnemyHighestDFInThisLZ - 2)
                        elseif iAngleDif >= 55 then
                            iMaxDistToBeInRange = 3.5
                        elseif iAngleDif <= 10 and oEnemyToTarget:IsUnitState('Moving') then
                            iMaxDistToBeInRange = 0.25
                        end
                        if (not(AiBotUnitInfo.CanSeeUnit(aiBrain, oEnemyToTarget, false)) or (tLZTeamData[AiBotMap.refiRadarCoverage] < 30 and not(AiBotUnitInfo.IsUnitValid(oACU[AiBotLand.refoAssignedLandScout])))) then
                            iMaxDistToBeInRange = math.max(iMaxDistToBeInRange, math.min(iMaxDistToBeInRange, 3) + oACU[AiBotUnitInfo.refiDFRange] - (oACU:GetBlueprint().Intel.VisionRadius or oACU[AiBotUnitInfo.refiDFRange]))
                            bConsiderAttackMoveDueToIntel = true
                        end
                        if bDebugMessages == true then LOG(sFunctionRef..': iAngleDif='..iAngleDif..'; iMaxDistToBeInRange='..iMaxDistToBeInRange..'; iEnemyHighestDFInThisLZ range='..iEnemyHighestDFInThisLZ..'; ACU vision range='..oACU:GetBlueprint().Intel.VisionRadius) end
                    end
                    --Be more in range if enemy has stealthed ACU currently in our range; note we have more logic a bit later on which deals with nearest ACU (to help where nearest enemy isnt nearest ACU but is stealthed)
                    if iMaxDistToBeInRange < 10 and oEnemyToTarget[refiUpgradeCount] and EntityCategoryContains(categories.COMMAND * categories.CYBRAN, oEnemyToTarget.UnitId) and oEnemyToTarget.HasEnhancement and (oEnemyToTarget:HasEnhancement('StealthGenerator') or oEnemyToTarget:HasEnhancement('FAF_SelfRepairSystem')) then
                        --If enemy ACU is moving away from us then increase dist threshold to 10 (as 8 proved to not be enough)
                        if bDebugMessages == true then LOG(sFunctionRef..': Enemy ACU speed='..AiBotUnitInfo.GetUnitSpeed(oEnemyToTarget)..'; Facing angle='..AiBotUnitInfo.GetUnitFacingAngle(oEnemyToTarget)..'; Dif between facing angle and angle to us='..AiBotUtilities.GetAngleDifference(AiBotUnitInfo.GetUnitFacingAngle(oEnemyToTarget), AiBotUtilities.GetAngleFromAToB(oEnemyToTarget:GetPosition(), oACU:GetPosition()))) end
                        if AiBotUnitInfo.GetUnitSpeed(oEnemyToTarget) > 0.1 and AiBotUtilities.GetAngleDifference(AiBotUnitInfo.GetUnitFacingAngle(oEnemyToTarget), AiBotUtilities.GetAngleFromAToB(oEnemyToTarget:GetPosition(), oACU:GetPosition())) > 45 then
                            iMaxDistToBeInRange = 10
                        else
                            iMaxDistToBeInRange = math.max(8, iMaxDistToBeInRange)
                        end
                        if bDebugMessages == true then LOG(sFunctionRef..': Increasing iMaxDistToBeInRange to '..iMaxDistToBeInRange..' as up against stealthed ACU') end
                    end
                    local iStraightLineDist = AiBotUtilities.GetDistanceBetweenPositions(oEnemyToTarget:GetPosition(), oACU:GetPosition())
                    local iNearbyMobileEnemyDFThreat = (tLZTeamData[AiBotMap.subrefLZThreatEnemyMobileDFTotal] or 0)
                    if AiBotUtilities.IsTableEmpty(tLZData[AiBotMap.subrefLZAdjacentLandZones]) == false then
                        for _, iAdjLZ in tLZData[AiBotMap.subrefLZAdjacentLandZones] do
                            local tAdjLZTeamData = AiBotMap.tAllPlateaus[iPlateau][AiBotMap.subrefPlateauLandZones][iAdjLZ][AiBotMap.subrefLZTeamData][iTeam]
                            iNearbyMobileEnemyDFThreat = iNearbyMobileEnemyDFThreat + tAdjLZTeamData[AiBotMap.subrefLZThreatEnemyMobileDFTotal]
                        end
                    end
                    local bWantKitingRetreat = false
                    local iEnemyT1ArtiAndDFThreatCloseToOurRange = 0
                    local bEnemyHasLongerRangedUnits
                    local iEnemyThreatThresholdForDetailedCheck = 1750 + oACU[refiUpgradeCount] * 750

                    if iStraightLineDist + iMaxDistToBeInRange <= oACU[AiBotUnitInfo.refiDFRange] and (iOurACUHealthPercent <= 0.75 or iNearbyMobileEnemyDFThreat >= 250 or (tLZTeamData[AiBotMap.subrefTThreatEnemyCombatTotal] or 0) >= 150) then
                        if bDebugMessages == true then LOG(sFunctionRef..': Considering if we want to do a kiting retreat, iStraightLineDist='..iStraightLineDist..'; iMaxDistToBeInRange='..iMaxDistToBeInRange..'; Our DF range='..(oACU[AiBotUnitInfo.refiDFRange] or 'nil')..'; ACU health%='..(iOurACUHealthPercent or 'nil')..'; iNearbyMobileEnemyDFThreat='..iNearbyMobileEnemyDFThreat..'; tLZTeamData[AiBotMap.subrefTThreatEnemyCombatTotal]='..(tLZTeamData[AiBotMap.subrefTThreatEnemyCombatTotal] or 'nil')) end
                        bWantKitingRetreat = true
                        --Exception - we have >= enemy range, and the threat of enemy units within our range + 5 isn't that great, and the mobile threat of enemy units isn't that great
                        local iAdjacentThreatThreshold = 1500 + oACU[refiUpgradeCount] * 750
                        if not(AiBotTeam.tTeamData[iTeam][AiBotTeam. refbAssassinationOrSimilar]) then
                            iAdjacentThreatThreshold = iAdjacentThreatThreshold * 3
                        end
                        local iACUInZone = 1
                        if AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.subrefAlliedACU]) == false then iACUInZone = table.getn(tLZTeamData[AiBotMap.subrefAlliedACU]) end
                        if iACUInZone > 1 then
                            iAdjacentThreatThreshold = iAdjacentThreatThreshold * (1 + (iACUInZone -1) * 0.6)
                        end

                        if iOurACUHealthPercent >= 0.95 then
                            iEnemyThreatThresholdForDetailedCheck = iEnemyThreatThresholdForDetailedCheck + 500 + 250 * oACU[refiUpgradeCount]
                        end

                        if bDebugMessages == true then LOG(sFunctionRef..': Considering if we want to ignore kiting retreat and advance due to low enemy threat, iNearbyMobileEnemyDFThreat (which is mobile DF in this and adjacent zones)='..iNearbyMobileEnemyDFThreat..'; iAdjacentThreatThreshold='..iAdjacentThreatThreshold..'; iACUInZone='..iACUInZone..'; iEnemyThreatThresholdForDetailedCheck='..iEnemyThreatThresholdForDetailedCheck) end
                        if iNearbyMobileEnemyDFThreat <= iEnemyThreatThresholdForDetailedCheck then --will do a more detailed check later on
                            local iCurDist
                            local iACUDistThreshold = (oACU[AiBotUnitInfo.refiDFRange] or 0)
                            local iShortEnemyRangeThreshold = 6
                            local iLongEnemyRangeThreshold = 40
                            local iPDDistThreshold = 10 --i.e. if PD is this much close to being in range of us we will take into account its threat
                            local iEnemyT1PDInRangeOfUs = 0
                            local iEnemyNearbyT2PlusPDThreat = 0
                            local iEnemyFurtherAwayLRPDThreat = 0

                            if AiBotMap.iMapSize >= 1000 or tLZTeamData[AiBotMap.refiModDistancePercent] >= 0.5 then iLongEnemyRangeThreshold = 80 end
                            local iEnemyMobileThreatSlightlyFurtherAway = 0

                            function AddNearbyCombatThreat(tCurLZTeamData)
                                if AiBotUtilities.IsTableEmpty(tCurLZTeamData[AiBotMap.subrefTEnemyUnits]) == false then
                                    --Include all units either close to being in our range, or that are close to being able to fire at us

                                    local tEnemyUnitsOfInterest = EntityCategoryFilterDown(AiBotUnitInfo.refCategoryLandCombat + AiBotUnitInfo.refCategoryPD, tCurLZTeamData[AiBotMap.subrefTEnemyUnits])
                                    if AiBotUtilities.IsTableEmpty(tEnemyUnitsOfInterest) == false then
                                        local iCurThreatRating
                                        for iUnit, oUnit in tEnemyUnitsOfInterest do
                                            if AiBotUnitInfo.IsUnitValid(oUnit) then
                                                if not(bEnemyHasLongerRangedUnits) and (oUnit[AiBotUnitInfo.refiDFRange] or 0) > (oACU[AiBotUnitInfo.refiDFRange] or 0) then
                                                    bEnemyHasLongerRangedUnits = true
                                                end
                                                iCurDist = AiBotUtilities.GetDistanceBetweenPositions(oUnit:GetPosition(), oACU:GetPosition())
                                                if bDebugMessages == true then LOG(sFunctionRef..': Considering if enemy unit is close enough to record threat, iCurDist='..iCurDist..'; iACUDistThreshold='..iACUDistThreshold..'; Unit DF range and  SR threshold='..(oUnit[AiBotUnitInfo.refiDFRange] or 0) + iShortEnemyRangeThreshold..'; Unit threat='..AiBotUnitInfo.GetCombatThreatRating({ oUnit }, false, false)..'; Unit combat range and LR threat='..(oUnit[AiBotUnitInfo.refiCombatRange] or 0) + iLongEnemyRangeThreshold) end
                                                if iCurDist <= iACUDistThreshold or iCurDist <= (oUnit[AiBotUnitInfo.refiDFRange] or 0) + iShortEnemyRangeThreshold then
                                                    iCurThreatRating = AiBotUnitInfo.GetCombatThreatRating({ oUnit }, false, false)
                                                    iEnemyT1ArtiAndDFThreatCloseToOurRange = iEnemyT1ArtiAndDFThreatCloseToOurRange + iCurThreatRating
                                                    if EntityCategoryContains(AiBotUnitInfo.refCategoryPD, oUnit.UnitId) then
                                                        if (oUnit[AiBotUnitInfo.refiDFRange] or 0) <= (oACU[AiBotUnitInfo.refiDFRange] or 0) then
                                                            iEnemyT1PDInRangeOfUs = iEnemyT1PDInRangeOfUs + iCurThreatRating
                                                        elseif (oUnit[AiBotUnitInfo.refiDFRange] or 0) > (oACU[AiBotUnitInfo.refiDFRange] or 0) then
                                                            iEnemyNearbyT2PlusPDThreat = iEnemyNearbyT2PlusPDThreat + iCurThreatRating
                                                        end
                                                    end

                                                elseif iCurDist <= (oUnit[AiBotUnitInfo.refiCombatRange] or 0) + iLongEnemyRangeThreshold then
                                                    iCurThreatRating = AiBotUnitInfo.GetCombatThreatRating({ oUnit }, false, false)
                                                    iEnemyMobileThreatSlightlyFurtherAway = iEnemyMobileThreatSlightlyFurtherAway + iCurThreatRating
                                                    if EntityCategoryContains(AiBotUnitInfo.refCategoryPD, oUnit.UnitId) then
                                                        if iCurDist > (oUnit[AiBotUnitInfo.refiCombatRange] or 0) + iPDDistThreshold then
                                                            --Exclude PD that isn't going to be in our range very soon given its not mobile
                                                            iEnemyMobileThreatSlightlyFurtherAway = iEnemyMobileThreatSlightlyFurtherAway - iCurThreatRating
                                                        elseif (oUnit[AiBotUnitInfo.refiDFRange] or 0) > (oACU[AiBotUnitInfo.refiDFRange] or 0) then
                                                            iEnemyFurtherAwayLRPDThreat = iEnemyFurtherAwayLRPDThreat + iCurThreatRating
                                                        end
                                                    end
                                                end
                                            end
                                        end
                                    end
                                end
                            end
                            AddNearbyCombatThreat(tLZTeamData)
                            if AiBotUtilities.IsTableEmpty(tLZData[AiBotMap.subrefLZAdjacentLandZones]) == false then
                                for _, iAdjLZ in tLZData[AiBotMap.subrefLZAdjacentLandZones] do
                                    AddNearbyCombatThreat(AiBotMap.tAllPlateaus[iPlateau][AiBotMap.subrefPlateauLandZones][iAdjLZ][AiBotMap.subrefLZTeamData][iTeam])
                                end
                            end
                            if iEnemyT1ArtiAndDFThreatCloseToOurRange <= 200 + 100 * oACU[refiUpgradeCount] and iEnemyT1ArtiAndDFThreatCloseToOurRange + iEnemyMobileThreatSlightlyFurtherAway <= 600 + oACU[refiUpgradeCount] * 300 then
                                bWantKitingRetreat = false
                                if bDebugMessages == true then LOG(sFunctionRef..': Dont want to do king retreat after all') end
                            elseif oACU[refiUpgradeCount] >= 2 and (oACU[refiUpgradeCount] >= 3 or not(EntityCategoryContains(categories.AEON, oACU.UnitId))) and iOurACUHealthPercent >= 0.95 and iEnemyT1ArtiAndDFThreatCloseToOurRange <= 1800 and iEnemyT1ArtiAndDFThreatCloseToOurRange + iEnemyMobileThreatSlightlyFurtherAway <= 2700 and iEnemyT1PDInRangeOfUs == 0 and (iEnemyT1ArtiAndDFThreatCloseToOurRange + iEnemyMobileThreatSlightlyFurtherAway <= 1900 or iEnemyNearbyT2PlusPDThreat + iEnemyFurtherAwayLRPDThreat >= 800) then
                                bWantKitingRetreat = false
                                if bDebugMessages == true then LOG(sFunctionRef..': We have high health and are heavily upgraded so want to press a bit more either due to enemy threat not being massive, or because neemy threat includes PD which we could always run from') end
                                --if shot is blocked for the closest enemy unit then dont kite
                            end
                            if bDebugMessages == true then LOG(sFunctionRef..': iEnemyT1ArtiAndDFThreatCloseToOurRange='..iEnemyT1ArtiAndDFThreatCloseToOurRange..'; iEnemyMobileThreatSlightlyFurtherAway='..iEnemyMobileThreatSlightlyFurtherAway..'; iEnemyT1PDInRangeOfUs='..iEnemyT1PDInRangeOfUs..'; iEnemyNearbyT2PlusPDThreat='..iEnemyNearbyT2PlusPDThreat..'; iEnemyFurtherAwayLRPDThreat='..iEnemyFurtherAwayLRPDThreat..'; bEnemyHasLongerRangedUnits='..tostring(bEnemyHasLongerRangedUnits)..'; Is shot blocked='..tostring(AiBotLogic.IsShotBlocked(oACU, oEnemyToTarget, false, nil))) end
                        end
                    end
                    local oUnitToMoveTo
                    --Check for ACUs in our range that we outrange, or that we have a clear 2v1 advantage, or that have stealth meaning we want to stay closer to them
                    local tACUsNearby
                    if AiBotUtilities.IsTableEmpty(tUnitsToTarget) == false then tACUsNearby = EntityCategoryFilterDown(categories.COMMAND, tUnitsToTarget) end
                    local oClosestACU
                    local iClosestACU = 1000
                    local bOutrangeAllACUs = true
                    local bWeHaveMoreACUsInRange = false
                    if AiBotUtilities.IsTableEmpty(tACUsNearby) == false then
                        if oACU[AiBotUnitInfo.refiDFRange] >= 28 then
                            for iEnemyACU, oEnemyACU in tACUsNearby do
                                if oACU[AiBotUnitInfo.refiDFRange] >= oEnemyACU then
                                    bOutrangeAllACUs = false
                                    break
                                end
                                iCurDist = AiBotUtilities.GetDistanceBetweenPositions(oACU:GetPosition(), oEnemyACU:GetPosition())
                                if iCurDist < iClosestACU then
                                    iClosestACU = iCurDist
                                    oClosestACU = oEnemyACU
                                end
                            end
                        end
                        if not(oClosestACU) and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiActiveAiBotBrainCount] > 1 then
                            --Consider if we are in a 2v1 scenario if already in range of enemy ACU (or almost in range and have friendly ACU that is in range)
                            local bEnemyACUWithGunOrPDOrACUs = false
                            for iEnemyACU, oEnemyACU in tACUsNearby do
                                if oACU[AiBotUnitInfo.refiDFRange] < oEnemyACU[AiBotUnitInfo.refiDFRange] and AiBotUtilities.GetDistanceBetweenPositions(oACU:GetPosition(), oEnemyACU:GetPosition()) - oEnemyACU[AiBotUnitInfo.refiDFRange] <= 40 then
                                    bEnemyACUWithGunOrPDOrACUs = true
                                    if bDebugMessages == true then LOG(sFunctionRef..': Have enemy ACU that outranges us and is getting close to being in our range, oEnemyACU owned by '..oEnemyACU:GetAIBrain().Nickname) end
                                    break
                                end
                                iCurDist = AiBotUtilities.GetDistanceBetweenPositions(oACU:GetPosition(), oEnemyACU:GetPosition())
                                if iCurDist < iClosestACU then
                                    iClosestACU = iCurDist
                                    oClosestACU = oEnemyACU
                                end
                            end
                            if bDebugMessages == true then
                                LOG(sFunctionRef..': Considering if we have multiple ACUs that can gang up on enemy, iClosestACU='..iClosestACU..'; bEnemyACUWithGunOrPDOrACUs='..tostring(bEnemyACUWithGunOrPDOrACUs)..'; Our ACU range='..oACU[AiBotUnitInfo.refiDFRange])
                                if oClosestACU then LOG(sFunctionRef..': Have oClosestACU, CanSeeUnit='..tostring(AiBotUnitInfo.CanSeeUnit(aiBrain, oClosestACU))..'; Our health+shield='..AiBotUnitInfo.GetUnitCurHealthAndShield(oACU)..'; Enemy ACU CurHealthAndShield='..AiBotUnitInfo.GetUnitCurHealthAndShield(oClosestACU)) end
                            end
                            local iDistToBeingInRangeToConsider = 20
                            local iMinHealthPercentOfEnemyACURequired = 0.6
                            if not(bEnemyACUWithGunOrPDOrACUs) and oClosestACU and iClosestACU <= oACU[AiBotUnitInfo.refiDFRange] + iDistToBeingInRangeToConsider and AiBotUnitInfo.CanSeeUnit(aiBrain, oClosestACU) and AiBotUnitInfo.GetUnitCurHealthAndShield(oACU) >= iMinHealthPercentOfEnemyACURequired * AiBotUnitInfo.GetUnitCurHealthAndShield(oClosestACU) then
                                --Check no other enemy ACU or completed PD within range of enemy ACU
                                for iEnemyACU, oEnemyACU in tACUsNearby do
                                    if not(oEnemyACU == oClosestACU) then
                                        if AiBotUtilities.GetDistanceBetweenPositions(oClosestACU:GetPosition(), oEnemyACU:GetPosition()) - oEnemyACU[AiBotUnitInfo.refiDFRange] <= 5
                                                or AiBotUtilities.GetDistanceBetweenPositions(oACU:GetPosition(), oEnemyACU:GetPosition()) - oEnemyACU[AiBotUnitInfo.refiDFRange] <= 5 then
                                            bEnemyACUWithGunOrPDOrACUs = true
                                            if bDebugMessages == true then LOG(sFunctionRef..': Enemy has an ACU nearby, owned by '..oEnemyACU:GetAIBrain().Nickname..'; dist to oClosestACU='..AiBotUtilities.GetDistanceBetweenPositions(oClosestACU:GetPosition(), oEnemyACU:GetPosition())..'; Dist to oACU='..AiBotUtilities.GetDistanceBetweenPositions(oACU:GetPosition(), oEnemyACU:GetPosition())) end
                                            break
                                        end
                                    end
                                end
                                if not(bEnemyACUWithGunOrPDOrACUs) then --No other nearby enemy ACUs
                                    local tPDNearby = EntityCategoryFilterDown(AiBotUnitInfo.refCategoryPD, tUnitsToTarget)
                                    if AiBotUtilities.IsTableEmpty(tPDNearby) == false then
                                        for iPD, oPD in tPDNearby do
                                            if not(oPD.Dead) and oPD:GetFractionComplete() >= 0.95 then
                                                if AiBotUtilities.GetDistanceBetweenPositions(oClosestACU:GetPosition(), oPD:GetPosition()) - oPD[AiBotUnitInfo.refiDFRange] <= 5
                                                        or AiBotUtilities.GetDistanceBetweenPositions(oACU:GetPosition(), oPD:GetPosition()) - oPD[AiBotUnitInfo.refiDFRange] <= 5 then
                                                    if bDebugMessages == true then LOG(sFunctionRef..': Enemy has PD near their ACU or ours so will abort, oPD='..oPD.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oPD)..'; Dist to oClosestACU='..AiBotUtilities.GetDistanceBetweenPositions(oClosestACU:GetPosition(), oPD:GetPosition())..'; Dist to our ACU='..AiBotUtilities.GetDistanceBetweenPositions(oACU:GetPosition(), oPD:GetPosition())) end
                                                    bEnemyACUWithGunOrPDOrACUs = true
                                                    break
                                                end
                                            end
                                        end
                                    end
                                    if not(bEnemyACUWithGunOrPDOrACUs) then
                                        --Do we have another friendly ACU nearby?
                                        if AiBotUtilities.IsTableEmpty(AiBotTeam.tTeamData[iTeam][AiBotTeam.reftAiBotACUs]) == false then
                                            local oClosestFriendlyACU
                                            local iClosestFriendlyACUDist = 1000
                                            for iFriendlyACU, oFriendlyACU in AiBotTeam.tTeamData[iTeam][AiBotTeam.reftAiBotACUs] do
                                                if not(oFriendlyACU == oACU) and oFriendlyACU[AiBotUnitInfo.reftAssignedPlateauAndLandZoneByTeam][iTeam][1] == iPlateau then
                                                    iCurDist = AiBotUtilities.GetDistanceBetweenPositions(oFriendlyACU:GetPosition(), oACU:GetPosition())
                                                    if bDebugMessages == true then LOG(sFunctionRef..': Checking for friendly ACU, iCurDist='..iCurDist..'; ACU owned by '..oFriendlyACU:GetAIBrain().Nickname) end
                                                    if iCurDist <= 50 and (iCurDist <= 20 or AiBotUtilities.GetDistanceBetweenPositions(oFriendlyACU:GetPosition(), oClosestACU:GetPosition()) - oFriendlyACU[AiBotUnitInfo.refiDFRange] <= 20) then
                                                        --Check we are in range with either this ACU or our current ACU
                                                        if (iClosestACU <= oACU[AiBotUnitInfo.refiDFRange] or AiBotUtilities.GetDistanceBetweenPositions(oFriendlyACU:GetPosition(), oClosestACU:GetPosition()) - oFriendlyACU[AiBotUnitInfo.refiDFRange] <= 0)
                                                                and AiBotUnitInfo.GetUnitCurHealthAndShield(oFriendlyACU) >= iMinHealthPercentOfEnemyACURequired * AiBotUnitInfo.GetUnitCurHealthAndShield(oClosestACU)
                                                        then
                                                            if bDebugMessages == true then LOG(sFunctionRef..': Friendly ACU is in range') end
                                                            bWeHaveMoreACUsInRange = true
                                                            if iCurDist - oFriendlyACU[AiBotUnitInfo.refiDFRange] < iClosestFriendlyACUDist then
                                                                iClosestFriendlyACUDist = iCurDist - oFriendlyACU[AiBotUnitInfo.refiDFRange]
                                                                oClosestFriendlyACU = oFriendlyACU
                                                            end
                                                        end
                                                    end
                                                end
                                            end
                                            if bWeHaveMoreACUsInRange and oClosestFriendlyACU then
                                                if bDebugMessages == true then LOG(sFunctionRef..': Will record that we have a common ACU target') end
                                                RecordCommonACUTarget(oACU, oClosestFriendlyACU, oClosestACU)
                                            end
                                            if bDebugMessages == true then LOG(sFunctionRef..': bWeHaveMoreACUsInRange='..tostring(bWeHaveMoreACUsInRange)..'; Checking if we still want to kite if we are well within our range, iClosestACU='..iClosestACU..'; refiDFRange='..oACU[AiBotUnitInfo.refiDFRange]..'; VisionRadius='..oACU:GetBlueprint().Intel.VisionRadius) end
                                            if bWeHaveMoreACUsInRange and iClosestACU >= math.min(oACU[AiBotUnitInfo.refiDFRange], oACU:GetBlueprint().Intel.VisionRadius) - 10 then --tried at -6 but still had ACUs getting into range then moving out of range
                                                oUnitToMoveTo = oClosestACU
                                                bWantKitingRetreat = false
                                            end
                                        end
                                    end
                                end
                                if not(bWeHaveMoreACUsInRange) then oClosestACU = nil end
                            end
                        end
                    end
                    if bDebugMessages == true then
                        if oClosestACU then
                            LOG(sFunctionRef..': iClosestACU='..iClosestACU..'; Can see ACU='..tostring(AiBotUnitInfo.CanSeeUnit(aiBrain, oClosestACU))..'; Do we have a valid land scout='..tostring(AiBotUnitInfo.IsUnitValid(oACU[AiBotLand.refoAssignedLandScout]))..'; Closest ACU health%='..AiBotUnitInfo.GetUnitHealthAndShieldPercent(oClosestACU)..'; Our ACU health%='..iOurACUHealthPercent..'; Enemy ACU range='..oClosestACU[AiBotUnitInfo.refiDFRange]..'; tLZTeamData[AiBotMap.subrefLZThreatEnemyBestStructureDFRange]='..tLZTeamData[AiBotMap.subrefLZThreatEnemyBestStructureDFRange]..'; tLZTeamData[AiBotMap.subrefLZThreatEnemyBestMobileDFRange]='..tLZTeamData[AiBotMap.subrefLZThreatEnemyBestMobileDFRange] ..'; iEnemyT1ArtiAndDFThreatCloseToOurRange='..iEnemyT1ArtiAndDFThreatCloseToOurRange..'; Mod dist%='..tLZTeamData[AiBotMap.refiModDistancePercent]..'; ACU shot blocked='..tostring(oACU[AiBotUnitInfo.refbLastShotBlocked] or false))
                            if AiBotUnitInfo.IsUnitValid(AiBotUnitInfo.IsUnitValid(oACU[AiBotLand.refoAssignedLandScout])) then LOG(sFunctionRef..': Dist to assigned land scout='..AiBotUtilities.GetDistanceBetweenPositions(oACU:GetPosition(), oACU[AiBotLand.refoAssignedLandScout]:GetPosition())) end
                        else LOG(sFunctionRef..': No nearby enemy ACU')
                        end
                    end

                    --If within 2 of being in range of enemy ACU that we outrange then keep pressing forwards (we will ignore this if we decide we still want kiting retreat)
                    if not(oUnitToMoveTo) and oClosestACU and iUnitPlateau > 0 and iClosestACU <= oACU[AiBotUnitInfo.refiDFRange] + 2 and (AiBotUnitInfo.CanSeeUnit(aiBrain, oClosestACU) or (AiBotUnitInfo.IsUnitValid(oACU[AiBotLand.refoAssignedLandScout]) and AiBotUtilities.GetDistanceBetweenPositions(oACU:GetPosition(), oACU[AiBotLand.refoAssignedLandScout]:GetPosition()) <= 40) or (iOurACUHealthPercent >= 0.9 and iClosestACU <= oACU[AiBotUnitInfo.refiDFRange] and tLZTeamData[AiBotMap.refiModDistancePercent] <= 0.8 and AiBotUnitInfo.GetUnitHealthAndShieldPercent(oClosestACU) < iOurACUHealthPercent - 0.05)) and iOurACUHealthPercent * 0.95 > AiBotUnitInfo.GetUnitHealthAndShieldPercent(oClosestACU) then
                        local iOurVisualRange = oACU:GetBlueprint().Intel.VisionRadius
                        if bDebugMessages == true then LOG(sFunctionRef..': iOurVisualRange='..iOurVisualRange..'; iClosestACU='..iClosestACU..'; oClosestACU owner='..oClosestACU:GetAIBrain().Nickname) end
                        if iClosestACU > iOurVisualRange - 3 or (oACU[AiBotUnitInfo.refbLastShotBlocked] or iOurACUHealthPercent > 0.4 + AiBotUnitInfo.GetUnitHealthPercent(oClosestACU) or AiBotLogic.IsShotBlocked(oACU, oClosestACU, false, false)) then
                            oUnitToMoveTo = oClosestACU
                            if bDebugMessages == true then LOG(sFunctionRef..': Want to move to enemy ACU unless decide to kite, oClosestACU='..oClosestACU.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oClosestACU)) end
                        end
                    end
                    --If against stealthed ACU that is in our range then move towards it instead of attackmove
                    if bDebugMessages == true then
                        if oClosestACU then LOG(sFunctionRef..': Checking if dealing with stealtehd ACU we want to be closer to, oClosestACU[refiUpgradeCount]='..(oClosestACU[refiUpgradeCount] or 'nil')..'; IsCybran='..tostring(EntityCategoryContains(categories.CYBRAN, oClosestACU.UnitId))..'; Has stealth or nano='..tostring((oClosestACU:HasEnhancement('StealthGenerator') or oClosestACU:HasEnhancement('FAF_SelfRepairSystem')))..'; refiOmniCoverage='.. (tLZTeamData[AiBotMap.refiOmniCoverage] or 0)..'; VisionRadius='..(oACU:GetBlueprint().Intel.VisionRadius or 26)..'; iOurACUHealthPercent='..iOurACUHealthPercent)
                        else LOG(sFunctionRef..': oClosestACU is nil')
                        end
                    end

                    if oClosestACU and iClosestACU <= oACU[AiBotUnitInfo.refiDFRange] and iClosestACU > oACU[AiBotUnitInfo.refiDFRange] - math.max(8, iMaxDistToBeInRange) and oClosestACU[refiUpgradeCount] > 0 and EntityCategoryContains(categories.CYBRAN, oClosestACU.UnitId) and (oClosestACU:HasEnhancement('StealthGenerator') or oClosestACU:HasEnhancement('FAF_SelfRepairSystem')) and (tLZTeamData[AiBotMap.refiOmniCoverage] or 0) < 50
                            and iClosestACU >= (oACU:GetBlueprint().Intel.VisionRadius or 26) - 6 and iOurACUHealthPercent >= 0.6 then
                        if bDebugMessages == true then LOG(sFunctionRef..': Up against cybran acu with stealth so want to stay close to it so we can keep firing') end
                        bWantKitingRetreat = false
                        if not(oUnitToMoveTo) then oUnitToMoveTo = oClosestACU end
                    end

                    --Consider override for kiting retreat if enemy ACU in our range, and we have more health than them, and enemy lacks T2 PD/similar
                    if oUnitToMoveTo and bWantKitingRetreat and oClosestACU and iClosestACU <= oACU[AiBotUnitInfo.refiDFRange] then
                        if bOutrangeAllACUs and oACU[AiBotUnitInfo.refiDFRange]  >= math.max((tLZTeamData[AiBotMap.subrefLZThreatEnemyBestStructureDFRange] or 0), (tLZTeamData[AiBotMap.subrefLZThreatEnemyBestMobileDFRange] or 0)) and (iEnemyT1ArtiAndDFThreatCloseToOurRange <= 1500 or (iOurACUHealthPercent > 0.2 + AiBotUnitInfo.GetUnitHealthPercent(oClosestACU) and AiBotUnitInfo.GetUnitHealthPercent(oClosestACU) <= 0.55 and (not(AiBotTeam.tTeamData[iTeam][AiBotTeam.refbAssassinationOrSimilar]) or oClosestACU:GetHealth() <= 4000))) and (iClosestACU > oClosestACU[AiBotUnitInfo.refiDFRange] or (iOurACUHealthPercent > 0.2 + AiBotUnitInfo.GetUnitHealthPercent(oClosestACU) and (oACU[AiBotUnitInfo.refbLastShotBlocked] or iOurACUHealthPercent > 0.4 + AiBotUnitInfo.GetUnitHealthPercent(oClosestACU)))) then
                            if iOurACUHealthPercent >= AiBotUnitInfo.GetUnitHealthPercent(oClosestACU) then
                                if bDebugMessages == true then LOG(sFunctionRef..': We are in range of an enemy ACU that we outrange, so want to ignore kiting retreat and go for the kill') end
                                bWantKitingRetreat = false
                            end
                        end
                    end

                    --Shot blocked override
                    if bWantKitingRetreat and ((bEnemyHasLongerRangedUnits and iEnemyT1ArtiAndDFThreatCloseToOurRange <= iEnemyThreatThresholdForDetailedCheck * 0.5)
                            or (oACU[refiUpgradeCount] >= 2 and iOurACUHealthPercent >= 0.95 and (oACU[refiUpgradeCount] >= 3 or tLZTeamData[AiBotMap.refiModDistancePercent] <= 0.4 or AiBotUtilities.GetDistanceBetweenPositions(oACU:GetPosition(), tLZTeamData[AiBotMap.reftClosestFriendlyBase]) <= 100 + AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiActiveAiBotBrainCount] * 50))) then
                        if AiBotLogic.IsShotBlocked(oACU, oEnemyToTarget, false, nil) then
                            bWantKitingRetreat = false
                            if bDebugMessages == true then LOG(sFunctionRef..': Our shot is blocked so dont want to kite enemy') end
                        end
                    end

                    if bDebugMessages == true then LOG(sFunctionRef..': oEnemyToTarget='..oEnemyToTarget.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oEnemyToTarget)..'; iClosestDist='..iClosestDist..'; iMaxDistToBeInRange='..iMaxDistToBeInRange..'; ACU DF range='..(oACU[AiBotUnitInfo.refiDFRange] or 0)..'; ACU position='..repru(oACU:GetPosition())..'; Enemy unit to target='..repru(oEnemyToTarget:GetPosition())..'; Dist betweeh tnem straight line='..AiBotUtilities.GetDistanceBetweenPositions(oEnemyToTarget:GetPosition(), oACU:GetPosition())..'; ACU health percent='..iOurACUHealthPercent..'; Enemy combat total based just on this zone='..tLZTeamData[AiBotMap.subrefTThreatEnemyCombatTotal]..'; iNearbyMobileEnemyDFThreat='..iNearbyMobileEnemyDFThreat..'; bWantKitingRetreat='..tostring(bWantKitingRetreat)) end
                    if bWantKitingRetreat then
                        --Retreat temporarily - if aren't in a core zone then retreat to rally point
                        local tRallyPoint
                        if tLZTeamData[AiBotMap.subrefLZbCoreBase] then
                            --Retreat from nearest enemy
                            local iAngleFromEnemyToACU = AiBotUtilities.GetAngleFromAToB(oEnemyToTarget:GetPosition(), oACU:GetPosition())
                            tRallyPoint = AiBotUtilities.MoveInDirection(oACU:GetPosition(), iAngleFromEnemyToACU, 6, true, true, AiBotMap.bIsCampaignMap)
                            --Check this is in the same plateau, otherwise move it
                            local iRallyPlateau = NavUtils.GetTerrainLabel(AiBotMap.refPathingTypeHover, tRallyPoint)
                            if iRallyPlateau == iPlateau then
                                --Do nothing
                            else
                                local bHavePlateauInSameArea = false
                                --Search for position in the same plateau
                                for iAngleAdjust = -20, 20, 20 do
                                    for iDist = 7, 28, 7 do
                                        tRallyPoint = AiBotUtilities.MoveInDirection(oACU:GetPosition(), iAngleAdjust + iAngleFromEnemyToACU, 6, true, true, AiBotMap.bIsCampaignMap)
                                        iRallyPlateau = NavUtils.GetTerrainLabel(AiBotMap.refPathingTypeLand, tRallyPoint)
                                        if iRallyPlateau == iPlateau then
                                            bHavePlateauInSameArea = true
                                            break
                                        end
                                    end
                                    if bHavePlateauInSameArea then break end
                                end
                            end
                            if bDebugMessages == true then LOG(sFunctionRef..': Are in core zone so will move away from nearest enemy, tRallyPoint='..repru(tRallyPoint)) end
                        else
                            if bDebugMessages == true then LOG(sFunctionRef..': Will move to nearest rally point') end
                            tRallyPoint = AiBotLand.GetNearestLandRallyPoint(tLZData, oACU:GetAIBrain().AiBotTeam, iPlateau, iLandZone, 2, true)
                        end
                        AiBotOrders.IssueTrackedMove(oACU, tRallyPoint, 6, false, 'ACUKit', false)
                    else
                        --If near to enemy ACU that we outrange then stay within visual range of it
                        if oUnitToMoveTo then
                            AiBotOrders.IssueTrackedMove(oACU, oUnitToMoveTo:GetPosition(), 0, false, 'ACUMacu', false)
                            oACU[refbOnlyOverchargeHighValueTargets] = true
                            oEnemyToTarget = oUnitToMoveTo --need to set this or else we will think we didnt get an order
                            if bDebugMessages == true then LOG(sFunctionRef..': will move closer to enemy ACU that we outrange, oUnitToMoveTo='..oUnitToMoveTo.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnitToMoveTo)..' owned by '..oUnitToMoveTo:GetAIBrain().Nickname..'; refbOnlyOverchargeHighValueTargets='..tostring(oACU[refbOnlyOverchargeHighValueTargets])..'; Position of enemy='..repru(oUnitToMoveTo:GetPosition())) end
                        elseif bNearestEnemyIsShieldedButEnemyToTargetLacksShield and ((iEnemyT1ArtiAndDFThreatCloseToOurRange or 0) <= 250 or AiBotUnitInfo.GetUnitHealthPercent(oACU) >= 0.8) then
                            local iCurDist = AiBotUtilities.GetDistanceBetweenPositions(oEnemyToTarget:GetPosition(), oACU:GetPosition())
                            if iCurDist > (oACU[AiBotUnitInfo.refiDFRange] or 0) + 2 then
                                AiBotOrders.IssueTrackedMove(oACU, oEnemyToTarget:GetPosition(), 5, false, 'ACUAShlM', false)
                            else
                                AiBotOrders.IssueTrackedAttack(oACU, oEnemyToTarget, false, 'ACUAShlA', false)
                            end
                        elseif iEnemyT1ArtiAndDFThreatCloseToOurRange >= 250 then
                            --Attack-move towards enemy due to significant threat
                            if bDebugMessages == true then LOG(sFunctionRef..': Time='..GetGameTimeSeconds()..'; Will attack-move to enemy target unless have active micro, oEnemyToTarget='..oEnemyToTarget.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oEnemyToTarget)..'; refbSpecialMicroActive='..tostring(oACU[AiBotUnitInfo.refbSpecialMicroActive] or false)) end
                            AiBotOrders.IssueTrackedAggressiveMove(oACU, oEnemyToTarget:GetPosition(), 5, false, 'ACUAtM', false)
                        else
                            local iCurDist = AiBotUtilities.GetDistanceBetweenPositions(oEnemyToTarget:GetPosition(), oACU:GetPosition())
                            --Attack-move if in range of enemy, and either dealing with more dangerous unit, or a greater general enemy threat level
                            if bDebugMessages == true then LOG(sFunctionRef..': iCurDist='..iCurDist..'; iNearbyMobileEnemyDFThreat='..iNearbyMobileEnemyDFThreat..'; Enemy unit range='..(oEnemyToTarget[AiBotUnitInfo.refiDFRange] or 0)..'; Considering whether to attack move or move, iMaxDistToBeInRange='..iMaxDistToBeInRange..'; Are we close enoguh we want to attack under 1 measure='..tostring((iCurDist <= oACU[AiBotUnitInfo.refiDFRange] - math.min(10, math.max(0.25, iMaxDistToBeInRange - 2))))..'; Is enemy an ACU or dangerous or immobile unit='..tostring(EntityCategoryContains(categories.COMMAND + AiBotUnitInfo.refCategoryStructure + AiBotUnitInfo.refCategoryLandCombat * categories.TECH2 + categories.TECH3 - AiBotUnitInfo.refCategoryEngineer, oEnemyToTarget.UnitId))) end
                            if iCurDist <= 8 or ((iCurDist <= oACU[AiBotUnitInfo.refiDFRange] - math.min(10, math.max(0.25, iMaxDistToBeInRange - 2)) or (iCurDist <= oACU[AiBotUnitInfo.refiDFRange] and iCurDist <= 2 + (oEnemyToTarget[AiBotUnitInfo.refiDFRange] or 0))) and (EntityCategoryContains(categories.COMMAND + AiBotUnitInfo.refCategoryStructure + AiBotUnitInfo.refCategoryLandCombat * categories.TECH2 + categories.TECH3 - AiBotUnitInfo.refCategoryEngineer, oEnemyToTarget.UnitId) or (iNearbyMobileEnemyDFThreat >= 500 and iCurDist <= oACU[AiBotUnitInfo.refiDFRange] - 8))) or (bConsiderAttackMoveDueToIntel and iCurDist < oACU[AiBotUnitInfo.refiDFRange] - 3.5) then
                                if bDebugMessages == true then LOG(sFunctionRef..': Want to attack move, bConsiderAttackMoveDueToIntel='..tostring(bConsiderAttackMoveDueToIntel)) end
                                AiBotOrders.IssueTrackedAggressiveMove(oACU, oEnemyToTarget:GetPosition(), 5, false, 'ACUAtcM', false)
                            elseif iUnitPlateau == 0 and iCurDist <= oACU[AiBotUnitInfo.refiDFRange] + 2 then
                                if bDebugMessages == true then LOG(sFunctionRef..': Targeting naval unit so attackmove towards it') end
                                AiBotOrders.IssueTrackedAggressiveMove(oACU, oEnemyToTarget:GetPosition(), 5, false, 'ACUAtcNM', false)
                            else
                                if bDebugMessages == true then LOG(sFunctionRef..': Will move to closest enemy') end
                                if AiBotConditions.GiveAttackMoveAsWeaponStuck(oACU) then
                                    AiBotOrders.IssueTrackedAttackMove(oACU, oEnemyToTarget:GetPosition(), 3, false, 'ACUAT')
                                    if bDebugMessages == true then LOG(sFunctionRef..': Weapon stuck so doing attack move') end
                                else
                                    if EntityCategoryContains(categories.COMMAND, oEnemyToTarget.UnitId) and AiBotUnitInfo.GetUnitHealthAndShieldPercent(oEnemyToTarget) <= 0.5 then
                                        oACU[refbOnlyOverchargeHighValueTargets] = true
                                    end
                                    AiBotOrders.IssueTrackedMove(oACU, oEnemyToTarget:GetPosition(), 5, false, 'ACUAM', false)
                                end
                            end
                        end
                    end
                end
            end
        end
    end

    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)

    if oEnemyToTarget then return true
    else
        if bReturnClosestOutOfThresholdDistance then return false, iClosestOutOfThresholdDistance
        else return false
        end
    end
end

function ConsiderBuildingMex(tLZOrWZData, tLZOrWZTeamData, oACU, iOptionalMaxDistanceFromBuildRangeToConsider)
    --Do we have unclaimed mexes in the LZ? If so then build a mex on them.  However first check we dont alreayd have engineers trying to do this. also exception if we are overflowing mass and are in a core base

    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    local sFunctionRef = 'ConsiderBuildingMex'
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)

    local aiBrain = oACU:GetAIBrain()


    if tLZOrWZTeamData[AiBotMap.subrefLZbCoreBase] and aiBrain:GetEconomyStoredRatio('MASS') >= 0.9 and aiBrain:GetEconomyStored('MASS') >= 100 then
        if bDebugMessages == true then LOG(sFunctionRef..': Mass overflow scenario - dont want to build mex, as would rather get factory or assist something building') end
    else
        if bDebugMessages == true then
            local iPlateau, iLandZone = AiBotMap.GetPlateauAndLandZoneReferenceFromPosition(oACU:GetPosition())
            LOG(sFunctionRef..': Do we have any unbuilt locations for this LZ, iPlateau='..(iPlateau or 'nil')..'; iLandZone='..(iLandZone or 'nil')..' - is table empty='..tostring(AiBotUtilities.IsTableEmpty(tLZOrWZData[AiBotMap.subrefMexUnbuiltLocations]))..'; Is table of part built mexes empty='..tostring(AiBotUtilities.IsTableEmpty(tLZOrWZTeamData[AiBotMap.subreftoPartBuiltMexes])))
        end
        local tPotentialLocations = {}
        if AiBotUtilities.IsTableEmpty(tLZOrWZData[AiBotMap.subrefMexUnbuiltLocations]) == false then
            for iEntry, tLocation in tLZOrWZData[AiBotMap.subrefMexUnbuiltLocations]  do
                table.insert(tPotentialLocations, tLocation)
            end
        end
        if AiBotUtilities.IsTableEmpty(tLZOrWZTeamData[AiBotMap.subreftoPartBuiltMexes]) == false then
            for iEntry, oMex in tLZOrWZTeamData[AiBotMap.subreftoPartBuiltMexes] do
                if bDebugMessages == true then LOG(sFunctionRef..': Adding part build mex at position '..repru(oMex:GetPosition())..' to list of potential locations') end
                table.insert(tPotentialLocations, oMex:GetPosition())
            end
        end
        if AiBotUtilities.IsTableEmpty(tPotentialLocations) == false then
            --Check how close the mexes are - e.g. if calling this for higher priority orders we only want to consider mexes near to our build range
            local bHaveMexesWithinMaxDistanceToConsider = false
            local bHaveMexWithinACUBuildRange = false
            local iSearchRange
            local iACUBuildRange = oACU:GetBlueprint().Economy.MaxBuildDistance
            if iOptionalMaxDistanceFromBuildRangeToConsider then
                iSearchRange = iACUBuildRange + iOptionalMaxDistanceFromBuildRangeToConsider
            else
                iSearchRange = 60
            end
            if not(iOptionalMaxDistanceFromBuildRangeToConsider) then bHaveMexesWithinMaxDistanceToConsider = true
            else
                for iEntry, tLocation in tPotentialLocations do
                    if bDebugMessages == true then LOG(sFunctionRef..': Considering tLocation='..repru(tLocation)..'; iSearchRange='..iSearchRange..'; Distance to ACU='..AiBotUtilities.GetDistanceBetweenPositions(oACU:GetPosition(), tLocation)) end
                    if AiBotUtilities.GetDistanceBetweenPositions(oACU:GetPosition(), tLocation) <= iSearchRange then
                        bHaveMexesWithinMaxDistanceToConsider = true
                        break
                    end
                end
            end
            if bDebugMessages == true then LOG(sFunctionRef..': TIme='..GetGameTimeSeconds()..'; bHaveMexesWithinMaxDistanceToConsider='..tostring(bHaveMexesWithinMaxDistanceToConsider)..'; iSearchRange='..iSearchRange..'; iOptionalMaxDistanceFromBuildRangeToConsider='..(iOptionalMaxDistanceFromBuildRangeToConsider or 'nil')) end
            if bHaveMexesWithinMaxDistanceToConsider then
                for iEntry, tLocation in tPotentialLocations do
                    if bDebugMessages == true then LOG(sFunctionRef..': Considering location '..repru(tLocation)..'; Dist to ACU='..AiBotUtilities.GetDistanceBetweenPositions(oACU:GetPosition(), tLocation)..'; iACUBuildRange='..iACUBuildRange) end
                    if AiBotUtilities.GetDistanceBetweenPositions(oACU:GetPosition(), tLocation) <= iACUBuildRange then
                        if (not(AiBotOverseer.bNoRushActive) or not(AiBotConditions.NoRushPreventingHydroOrMex(tLZOrWZData, true))) then
                            bHaveMexWithinACUBuildRange = true
                            break
                        end
                    end
                end
                if bHaveMexWithinACUBuildRange then
                    iSearchRange = iACUBuildRange + 0.5 --added +0.5 in v117 just in case (but issue were investigating caused by different problem)
                end

                local bHaveEngineersAssignedAlready = false
                local tEngisInLZ = EntityCategoryFilterDown(AiBotUnitInfo.refCategoryEngineer, tLZOrWZTeamData[AiBotMap.subreftoLZOrWZAlliedUnits])

                if AiBotUtilities.IsTableEmpty(tEngisInLZ) == false then
                    for iEngi, oEngi in tEngisInLZ do
                        if oEngi[AiBotEngineer.refiAssignedAction] == AiBotEngineer.refActionBuildMex or oEngi[AiBotEngineer.refiAssignedAction] == AiBotEngineer.refActionCompletePartBuiltMex then
                            bHaveEngineersAssignedAlready = true
                            break
                        end
                    end
                end

                if bDebugMessages == true then LOG(sFunctionRef..': bHaveMexWithinACUBuildRange='..tostring(bHaveMexWithinACUBuildRange)..'; bHaveEngineersAssignedAlready='..tostring(bHaveEngineersAssignedAlready)) end
                if not(bHaveEngineersAssignedAlready) or bHaveMexWithinACUBuildRange or ((AiBotUtilities.bLoudModActive or AiBotUtilities.bQuietModActive) and aiBrain[AiBotEconomy.refiGrossMassBaseIncome] < aiBrain[AiBotEconomy.refiGrossEnergyBaseIncome] / 8) then
                    ACUActionBuildMex(oACU:GetAIBrain(), oACU, iSearchRange)
                    local tLastOrder = oACU[AiBotOrders.reftiLastOrders][oACU[AiBotOrders.refiOrderCount]]
                    if bDebugMessages == true then LOG(sFunctionRef..': Have tried telling ACU to build mex, tLastOrder='..reprs(tLastOrder)) end
                    if tLastOrder and (tLastOrder[AiBotOrders.subrefiOrderType] == AiBotOrders.refiOrderIssueBuild or tLastOrder[AiBotOrders.subrefiOrderType] == AiBotOrders.refiOrderIssueRepair) then
                        if not(AiBotConditions.DoesACUHaveValidOrder(oACU)) and (AiBotOrders.bDontConsiderCombinedArmy or oACU.AiBotActive) then
                            local tLastTarget = {tLastOrder[AiBotOrders.subreftOrderPosition][1], tLastOrder[AiBotOrders.subreftOrderPosition][2], tLastOrder[AiBotOrders.subreftOrderPosition][3]}
                            if bDebugMessages == true then LOG(sFunctionRef..': Trying workaround as for some reason ACU doesnt have valid order, will try building on the next mex, tLastTarget='..repru(tLastTarget)) end
                            if table.getn(tPotentialLocations) > 1 then
                                local iClosestMex = 10000
                                local tClosestMex
                                local iCurDist
                                for iLocation, tLocation in tPotentialLocations do
                                    iCurDist = AiBotUtilities.GetDistanceBetweenPositions(tLocation, oACU:GetPosition())
                                    if iCurDist < iClosestMex then
                                        tClosestMex = {tLocation[1], tLocation[2], tLocation[3]}
                                        iClosestMex = iCurDist
                                    end
                                end
                                if tClosestMex then
                                    if bDebugMessages == true then LOG(sFunctionRef..': Will retry build order at location '..repru(tClosestMex)) end
                                    ACUBuildUnit(aiBrain, oACU, AiBotUnitInfo.refCategoryMex, 30, 100, nil, nil, tClosestMex)
                                    --Track micro temporarily
                                    AiBotMicro.TrackTemporaryUnitMicro(oACU, 2.9, nil, true)
                                end
                            end

                        end
                        AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
                        return true
                    end
                end
            end
        end
    end
    if bDebugMessages == true then LOG(sFunctionRef..': End of code, did not give build mex order') end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
    return false
end

function ConsiderNearbyReclaimForACUOrEngineer(iPlateau, iLandZone, tLZData, tLZTeamData, oEngineer, bOnlyConsiderIfInBuildRange, iIndividualReclaimThresholdOverride, iTotalReclaimFactorOverride, iMassStoredThresholdOverride)
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    local sFunctionRef = 'ConsiderNearbyReclaimForACUOrEngineer'
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)



    if EntityCategoryContains(categories.RECLAIM, oEngineer.UnitId) then

        local iTotalReclaimWanted
        local iIndividualReclaimThreshold
        local bGetEnergy = false
        if bOnlyConsiderIfInBuildRange then
            if (oEngineer[refiUpgradeCount] or 0) > 0 and not(oEngineer.HasEnhancement and oEngineer:HasEnhancement('AdvancedEngineering')) then
                if (tLZTeamData[AiBotMap.subrefbEnemiesInThisOrAdjacentLZ] or tLZTeamData[AiBotMap.subrefbDangerousEnemiesInAdjacentWZ]) or not(AiBotConditions.TeamHasLowMass(oEngineer:GetAIBrain().AiBotTeam)) then
                    iIndividualReclaimThreshold = iIndividualReclaimThresholdOverride or 24
                else
                    iIndividualReclaimThreshold = iIndividualReclaimThresholdOverride or 15
                end
                iTotalReclaimWanted = iIndividualReclaimThreshold * (iTotalReclaimFactorOverride or 4)
                if not(iTotalReclaimFactorOverride) and oEngineer[refiUpgradeCount] >= 2 and (oEngineer[refiUpgradeCount] >= 3 or not(EntityCategoryContains(categories.AEON, oEngineer.UnitId))) then
                    iTotalReclaimWanted = iTotalReclaimWanted * 1.5
                end
            else
                if AiBotConditions.TeamHasLowMass(oEngineer:GetAIBrain().AiBotTeam) then
                    iIndividualReclaimThreshold = iIndividualReclaimThresholdOverride or 10
                    iTotalReclaimWanted = iIndividualReclaimThreshold * (iTotalReclaimFactorOverride or 2.5)
                else
                    iTotalReclaimWanted = 40
                    iIndividualReclaimThreshold = iIndividualReclaimThresholdOverride or 10
                    iTotalReclaimWanted = iIndividualReclaimThreshold * (iTotalReclaimFactorOverride or 4)
                end
            end
            if oEngineer:GetAIBrain():GetEconomyStored('ENERGY') <= 50 then
                bGetEnergy = true
                iIndividualReclaimThreshold = iIndividualReclaimThresholdOverride or 15
                iTotalReclaimWanted = iIndividualReclaimThreshold * (iTotalReclaimFactorOverride or 1)
            end
        else
            if iIndividualReclaimThresholdOverride then
                iIndividualReclaimThreshold = iIndividualReclaimThresholdOverride
            elseif AiBotConditions.TeamHasLowMass(oEngineer:GetAIBrain().AiBotTeam) then
                iIndividualReclaimThreshold = 20
            else
                iIndividualReclaimThreshold = 25
            end
            iTotalReclaimWanted = iIndividualReclaimThreshold * (iTotalReclaimFactorOverride or 5)
            if tLZTeamData[AiBotMap.subrefLZbCoreBase] and (GetGameTimeSeconds() <= 300 and AiBotTeam.tTeamData[oEngineer:GetAIBrain().AiBotTeam][AiBotTeam.subrefiTeamGrossMass]) <= 5 then iTotalReclaimWanted = iTotalReclaimWanted * 2 end
        end
        if bDebugMessages == true then LOG(sFunctionRef..': LZ reclaim mass='..tLZData[AiBotMap.subrefTotalMassReclaim]..'; subrefTotalSignificantMassReclaim='..tLZData[AiBotMap.subrefTotalSignificantMassReclaim]..'; Team mass % stored='..AiBotTeam.tTeamData[oEngineer:GetAIBrain().AiBotTeam][AiBotTeam.subrefiTeamAverageMassPercentStored]..'; iTotalReclaimWanted='..iTotalReclaimWanted..'; iIndividualReclaimThreshold='..iIndividualReclaimThreshold..'; bOnlyConsiderIfInBuildRange='..tostring(bOnlyConsiderIfInBuildRange or false)..'; bGetEnergy='..tostring(bGetEnergy or false)..'; Mass stored threshold='..(iMassStoredThresholdOverride or 'nil')) end

        if (bGetEnergy and tLZData[AiBotMap.subrefLZTotalEnergyReclaim] >= iTotalReclaimWanted) or (not(bGetEnergy) and tLZData[AiBotMap.subrefTotalMassReclaim] >= iTotalReclaimWanted and (tLZData[AiBotMap.subrefTotalSignificantMassReclaim] >= iIndividualReclaimThreshold or iIndividualReclaimThreshold <= AiBotMap.iSignificantMassThreshold * 0.7) and AiBotTeam.tTeamData[oEngineer:GetAIBrain().AiBotTeam][AiBotTeam.subrefiTeamAverageMassPercentStored] <= (iMassStoredThresholdOverride or 0.6)) then
            --If any reclaim of iIndividualReclaimThreshold+ value then get ACU to reclaim
                                          --GetEngineerToReclaimNearbyArea(oEngineer, iPriorityOverride, tLZOrWZTeamData, iPlateauOrPond, iLandOrWaterZone, bWantEnergyNotMass, bOnlyConsiderReclaimInRangeOfEngineer, iMinIndividualValueOverride, bIsWaterZone, bOptionalReturnTrueIfGivenOrder)
            local bGivenOrder = AiBotEngineer.GetEngineerToReclaimNearbyArea(oEngineer, 1,                    tLZTeamData, iPlateau,          iLandZone,      bGetEnergy,         (bOnlyConsiderIfInBuildRange or false), iIndividualReclaimThreshold, false, true)
            if bDebugMessages == true then LOG(sFunctionRef..': ACU last order after checking for reclaim in area='..reprs(oEngineer[AiBotOrders.reftiLastOrders][oEngineer[AiBotOrders.refiOrderCount]])) end
            local tLastOrder = oEngineer[AiBotOrders.reftiLastOrders][oEngineer[AiBotOrders.refiOrderCount]]
            if bGivenOrder and tLastOrder and tLastOrder[AiBotOrders.subrefiOrderType] == AiBotOrders.refiOrderIssueReclaim then
                if bDebugMessages == true then LOG(sFunctionRef..': ACU has a reclaim order so will stop') end
                AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
                return true
            end
        end
    end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
    return false
end

function MoveToOtherLandZone(iPlateau, tLZData, iLandZone, oACU)
    --COnsiders the land zone we want to support with the ACU - get the LZ within 175 travel distance that has the greatest value, wants DF support, and has less than 800 enemy threat in it
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    local sFunctionRef = 'MoveToOtherLandZone'
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)



    local iLZToMoveTo
    local iTeam = oACU:GetAIBrain().AiBotTeam
    local iAdjLZ
    if bDebugMessages == true then LOG(sFunctionRef..': Will consider moving to another LZ for ACU '..oACU.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oACU)..' owned by '..oACU:GetAIBrain().Nickname..'; Is table of pathing to other LZ empty='..tostring(AiBotUtilities.IsTableEmpty(tLZData[AiBotMap.subrefLZPathingToOtherLandZones]))) end
    local iHighValueDistanceThreshold = 175
    local iLowerPriorityDistanceThreshold = 300
    --Increase distance if ACU has upgrade and is near-full health, and we and enemy lack T3
    if (oACU[refiUpgradeCount] > 0 or AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestFriendlyFactoryTech] == 1) and AiBotUnitInfo.GetUnitHealthPercent(oACU) >= 0.95 and ((AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestFriendlyFactoryTech] < 3 and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestEnemyGroundTech] < 3 and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestEnemyAirTech] < 3) or (not(AiBotTeam.tTeamData[iTeam][AiBotTeam.refbDangerousForACUs]) and oACU[refiUpgradeCount] >= 2 and (AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiActiveAiBotBrainCount] >= 2 and not(AiBotTeam.tTeamData[iTeam][AiBotTeam. refbAssassinationOrSimilar])) and not(oACU:HasEnhancement('ResourceAllocation') and not(oACU:HasEnhancement('ResourceAllocationAdvanced')) and (oACU[refiUpgradeCount] >= 3 or (oACU.MyShield.GetHealth and oACU.MyShield:GetHealth() >= 4000) or oACU:GetHealth() >= 15000)))) then
        iLowerPriorityDistanceThreshold = iLowerPriorityDistanceThreshold + 100
        --Increase by another 50 if we are less than half map size and all indicators are ok
        local tLZTeamData = tLZData[AiBotMap.subrefLZTeamData][iTeam]
        if bDebugMessages == true then LOG(sFunctionRef..': Increased lower priority distance threshold, iLowerPriorityDistanceThreshold='..iLowerPriorityDistanceThreshold..'; will consider if want to increase further, upgradecount='..oACU[refiUpgradeCount]..'; In core base='..tostring(tLZTeamData[AiBotMap.subrefLZbCoreBase])..'; Highest enemy ground tech='..AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestEnemyGroundTech]..'; Highest enemy air tech='..AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestEnemyAirTech]..'; Map size='..AiBotMap.iMapSize) end
        if tLZTeamData[AiBotMap.subrefLZbCoreBase] and oACU[refiUpgradeCount] >= 2 and iLowerPriorityDistanceThreshold < math.min(475, AiBotMap.iMapSize * 0.6) and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestEnemyGroundTech] < 3 and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestEnemyAirTech] < 3 and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiActiveAiBotBrainCount] >= 2 and not(AiBotTeam.tTeamData[iTeam][AiBotTeam. refbAssassinationOrSimilar]) then
            if bDebugMessages == true then LOG(sFunctionRef..': Increased lower priority dist by a further 50') end
            iLowerPriorityDistanceThreshold = iLowerPriorityDistanceThreshold + 50
        end
    end
    local iLastPathedZoneTravelDist
    local iRecentLandZoneRef
    local iSecondsToIgnoreZonesRecentlyRunFrom = 30
    if bDebugMessages == true then LOG(sFunctionRef..': Time ACU last had order to move to zone='..(oACU[refiTimeLastToldToMoveToZone] or 'nil')..'; oACU[refiLastPlateauAndZoneToMoveTo]='..repru(oACU[refiLastPlateauAndZoneToMoveTo])..'; iLowerPriorityDistanceThreshold berfore last zone adjust='..iLowerPriorityDistanceThreshold) end
    if GetGameTimeSeconds() - (oACU[refiTimeLastToldToMoveToZone] or -100) <= 10 and not(oACU[refiLastPlateauAndZoneToMoveTo][1] == 0) then
        iRecentLandZoneRef = oACU[refiLastPlateauAndZoneToMoveTo][2]
        iLastPathedZoneTravelDist = AiBotMap.GetTravelDistanceBetweenLandZones(iPlateau, iLandZone, iRecentLandZoneRef)

        iHighValueDistanceThreshold = math.max(iHighValueDistanceThreshold, (iLastPathedZoneTravelDist or 190) + 1)
        iLowerPriorityDistanceThreshold = math.max(iLowerPriorityDistanceThreshold, (iLastPathedZoneTravelDist or 315) + 1)
        if bDebugMessages == true then LOG(sFunctionRef..': Recently tried to travel to land zone '..(iRecentLandZoneRef or 'nil')..'; iHighValueDistanceThreshold='..iHighValueDistanceThreshold..'; iLowerPriorityDistanceThreshold='..iLowerPriorityDistanceThreshold..'; iLastPathedZoneTravelDist='..(iLastPathedZoneTravelDist or 'nil')) end
    end
    local tbIslandsAlreadyConsidered = {}
    local iWaterZoneToConsiderBuildingNavalFactoryInFirst
    local aiBrain = oACU:GetAIBrain()
    --ACUs without torpedo upgrade early game where not had too many failed naval fac attempts and on a naval map - have ACU build naval fac (will consider later on if we find such a wz we want to help)
        --First consider global and cur LZ specific checks for if we want acu to build naval fac:
    if AiBotConditions.DoesACUWantToConsiderGettingNavalFactoryInCurWaterZone(oACU, aiBrain, iTeam, tLZData, tLZData[AiBotMap.subrefLZTeamData][aiBrain.AiBotTeam], iLandZone, true, false) then
        --Consider if we have a nearby naval zone that wants more engineers and send ACU there to help construction, unless have a higher priority target
        local iAdjWZ, iPond, iCurWZDist
        local iClosestWZConsideringDist = 10000
        for iEntry, tSubtable in tLZData[AiBotMap.subrefAdjacentWaterZones] do
            iAdjWZ = tSubtable[AiBotMap.subrefAWZRef]
            iPond = AiBotMap.tiPondByWaterZone[iAdjWZ]
            local tAdjWZData = AiBotMap.tPondDetails[iPond][AiBotMap.subrefPondWaterZones][iAdjWZ]
            local tAdjWZTeamData = tAdjWZData[AiBotMap.subrefWZTeamData][iTeam]
            --next consider zone specific checks for if ACU wants to get naval fac in this zone
            if AiBotConditions.DoesACUWantToConsiderGettingNavalFactoryInCurWaterZone(oACU, aiBrain, iTeam, tAdjWZData, tAdjWZTeamData, iAdjWZ, false, true) then
                iCurWZDist = AiBotUtilities.GetDistanceBetweenPositions(tAdjWZData[AiBotMap.subrefMidpoint], oACU:GetPosition())
                if not(iRecentLandZoneRef) and oACU[refiLastPlateauAndZoneToMoveTo][2] == iAdjWZ and oACU[refiLastPlateauAndZoneToMoveTo][1] == 0 then iCurWZDist = iCurWZDist - 50 end
                if iCurWZDist < iClosestWZConsideringDist then
                    iWaterZoneToConsiderBuildingNavalFactoryInFirst = iAdjWZ
                    iClosestWZConsideringDist = iCurWZDist
                end
            end
        end
    end
    --First consider adjacent zones wanting combat support
    if AiBotUtilities.IsTableEmpty(tLZData[AiBotMap.subrefLZPathingToOtherLandZones]) == false then
        local iHighestValueAmount = 0
        local iCurValue
        for iPathingRef, tPathingDetails in tLZData[AiBotMap.subrefLZPathingToOtherLandZones] do
            iAdjLZ = tPathingDetails[AiBotMap.subrefLZNumber]
            if bDebugMessages == true then LOG(sFunctionRef..': Considering iAdjLZ='..iAdjLZ..'; Travel dist='..tPathingDetails[AiBotMap.subrefLZTravelDist]..'; Does it want DF support='..tostring(AiBotMap.tAllPlateaus[iPlateau][AiBotMap.subrefPlateauLandZones][iAdjLZ][AiBotMap.subrefLZTeamData][iTeam][AiBotMap.subrefbLZWantsDFSupport])) end
            if tPathingDetails[AiBotMap.subrefLZTravelDist] < iHighValueDistanceThreshold then
                local tAdjLZTeamData = AiBotMap.tAllPlateaus[iPlateau][AiBotMap.subrefPlateauLandZones][iAdjLZ][AiBotMap.subrefLZTeamData][iTeam]
                if tAdjLZTeamData[AiBotMap.subrefbLZWantsDFSupport] then
                    iCurValue = tAdjLZTeamData[AiBotMap.subrefLZTValue]
                    if iAdjLZ == iRecentLandZoneRef then iCurValue = iCurValue * 1.05 + 25 end
                    if (tAdjLZTeamData[AiBotMap.subrefTThreatEnemyCombatTotal] or 0) < 50 + 100 * oACU[refiUpgradeCount] then
                        iCurValue = iCurValue * 0.7
                        if bDebugMessages == true then LOG(sFunctionRef..': Reducing value of going to this zone as small enemy combat threat') end
                    end
                    if bDebugMessages == true then LOG(sFunctionRef..': iCurValue='..iCurValue..'; iHighestValueAmount='..iHighestValueAmount..'; subrefLZTValue (i.e. cur value before adjust)='..tAdjLZTeamData[AiBotMap.subrefLZTValue]) end
                    if iCurValue > iHighestValueAmount then
                        --Have we run from this zone recently?
                        if not(oACU[reftiTimeLastRanFromZoneByPlateau][iPlateau][iAdjLZ]) or GetGameTimeSeconds() - oACU[reftiTimeLastRanFromZoneByPlateau][iPlateau][iAdjLZ] > iSecondsToIgnoreZonesRecentlyRunFrom then
                            if not(oACU[refiLastPlateauAndZoneToAttackUnitIn][2] == iAdjLZ) or not(oACU[refiLastPlateauAndZoneToAttackUnitIn][1] == iPlateau) or GetGameTimeSeconds() - (oACU[refiTimeLastToldToAttackUnitInOtherZone] or -100) > 30 then
                                iHighestValueAmount = AiBotMap.tAllPlateaus[iPlateau][AiBotMap.subrefPlateauLandZones][iAdjLZ][AiBotMap.subrefLZTeamData][iTeam][AiBotMap.subrefLZTValue]
                                iLZToMoveTo = iAdjLZ
                            end
                        end
                    end
                end
            else
                break
            end
        end
        if bDebugMessages == true then LOG(sFunctionRef..': Finished considering nearby zones, iLZToMoveTo='..(iLZToMoveTo or 'nil')) end
        if not(iLZToMoveTo) then
            --Are there any LZs nearby with unclaimed mexes, dangerous enemy ground units where we want DF support, or significant reclaim?
            local iNearestPotentialExpansionPoint, iPlannedDistOfPotentialExpansion

            local tLZTeamData = tLZData[AiBotMap.subrefLZTeamData][oACU:GetAIBrain().AiBotTeam]
            local iDistToClosestEnemyFromStart = AiBotUtilities.GetDistanceBetweenPositions(tLZTeamData[AiBotMap.reftClosestFriendlyBase], tLZTeamData[AiBotMap.reftClosestEnemyBase])
            local iCurZoneValue, iBestZoneDist
            local iBestZoneValue = 0
            local iClosestWorthwhileTravelDist
            local bBestZoneHasNearbyEnemies = false
            function GetAdjZoneValueForACU(iAdjLZ, iCurTravelDist, iShortestTravelDist)
                local iCurValue = 0
                local tAdjLZData = AiBotMap.tAllPlateaus[iPlateau][AiBotMap.subrefPlateauLandZones][iAdjLZ]
                local tAdjLZTeamData = tAdjLZData[AiBotMap.subrefLZTeamData][iTeam]
                if bDebugMessages == true then LOG(sFunctionRef..': Considering zone '..iAdjLZ..'; Travel dist='..iCurTravelDist..'; Dangerous enemies here='..tostring(tAdjLZTeamData[AiBotMap.subrefbDangerousEnemiesInThisLZ])..'; tAdjLZTeamData[AiBotMap.subrefbLZWantsDFSupport]='..tostring(tAdjLZTeamData[AiBotMap.subrefbLZWantsDFSupport] or false)..'; Is table of unbuilt mexes empty='..tostring(AiBotUtilities.IsTableEmpty(tAdjLZData[AiBotMap.subrefMexUnbuiltLocations]))..'; Core base='..tostring(tAdjLZTeamData[AiBotMap.subrefLZbCoreBase])..'; iNearestPotentialExpansionPoint='..(iNearestPotentialExpansionPoint or 'nil')..'; Total mass reclaim='..(tAdjLZData[AiBotMap.subrefTotalMassReclaim] or 'nil')..'; subrefTThreatEnemyCombatTotal='..(tAdjLZTeamData[AiBotMap.subrefTThreatEnemyCombatTotal] or 0)..'; Mod dist%='..tAdjLZTeamData[AiBotMap.refiModDistancePercent]) end

                local iFactoryCount = 0
                local iEngiCount = 0
                if AiBotUtilities.IsTableEmpty(tAdjLZTeamData[AiBotMap.subreftoLZOrWZAlliedUnits]) == false then
                    local tFactories = EntityCategoryFilterDown(AiBotUnitInfo.refCategoryFactory, tAdjLZTeamData[AiBotMap.subreftoLZOrWZAlliedUnits])
                    if AiBotUtilities.IsTableEmpty(tFactories) == false then
                        iFactoryCount = table.getn(tFactories)
                    end
                    local tEngineers = EntityCategoryFilterDown(AiBotUnitInfo.refCategoryEngineer, tAdjLZTeamData[AiBotMap.subreftoLZOrWZAlliedUnits])
                    if AiBotUtilities.IsTableEmpty(tEngineers) == false then
                        iEngiCount = table.getn(tEngineers)
                    end
                    if AiBotUtilities.IsTableEmpty(tAdjLZTeamData[AiBotMap.subrefTEngineersTravelingHere]) == false then
                        iEngiCount = 0.3 * table.getn(tAdjLZTeamData[AiBotMap.subrefTEngineersTravelingHere])
                    end
                end
                -- or AiBotUtilities.IsTableEmpty(EntityCategoryFilterDown(AiBotUnitInfo.refCategoryLandFactory + AiBotUnitInfo.refCategoryEngineer, tAdjLZTeamData[AiBotMap.subreftoLZOrWZAlliedUnits]))) and AiBotUtilities.GetDistanceBetweenPositions(tAdjLZData[AiBotMap.subrefMidpoint], tAdjLZTeamData[AiBotMap.reftClosestEnemyBase]) < iDistToClosestEnemyFromStart) then
                if (tAdjLZTeamData[AiBotMap.subrefbDangerousEnemiesInThisLZ] and AiBotUtilities.IsTableEmpty(tAdjLZTeamData[AiBotMap.subrefTEnemyUnits]) == false) and tAdjLZTeamData[AiBotMap.subrefbLZWantsDFSupport] then
                    iCurValue = iCurValue + 250 + math.min(2000, (tAdjLZTeamData[AiBotMap.subrefTThreatEnemyCombatTotal] or 0) * 2)
                    if bDebugMessages == true then LOG(sFunctionRef..': Enemy units so increasing  value to iCurValue='..iCurValue) end
                    --Have ACU be more aggressive if has good combat upgrades (e.g. one scenario is enemy only has PD in the zone so doesnt flag as wanting DF support)
                elseif (tAdjLZTeamData[AiBotMap.subrefTThreatEnemyCombatTotal] or 0) >= 500 and (oACU[AiBotUnitInfo.refiDFMassThreatOverride] or 0) >= math.max(2000, 2 * (tAdjLZTeamData[AiBotMap.subrefTThreatEnemyCombatTotal] or 0)) then
                    iCurValue = iCurValue + math.min(1000, (tAdjLZTeamData[AiBotMap.subrefTThreatEnemyCombatTotal] or 0))
                end
                if AiBotUtilities.IsTableEmpty(tAdjLZData[AiBotMap.subrefMexUnbuiltLocations]) == false and iFactoryCount == 0 and iEngiCount <= 3 then
                    iCurValue = iCurValue + math.max(0, 100 * (tAdjLZData[AiBotMap.subrefLZOrWZMexCount] - iEngiCount * 2))
                end
                if tAdjLZData[AiBotMap.subrefTotalSignificantMassReclaim] >= 500 then iCurValue = iCurValue + math.max(0, tAdjLZData[AiBotMap.subrefTotalSignificantMassReclaim] / 5 - 1000 * iFactoryCount - 250 * iEngiCount) end

                --General value % adjustments (e.g. for core base, travel dist, and dist towards enemy base)
                if iCurValue > 0 then
                    --Reduce value of core base if no enemies in it
                    if tAdjLZTeamData[AiBotMap.subrefLZbCoreBase] and not(tAdjLZTeamData[AiBotMap.subrefbDangerousEnemiesInThisLZ]) then iCurValue = iCurValue * 0.25 end

                    --Reduce value if further from enemy base than our start position
                    if AiBotUtilities.GetDistanceBetweenPositions(tAdjLZData[AiBotMap.subrefMidpoint], tAdjLZTeamData[AiBotMap.reftClosestEnemyBase]) > iDistToClosestEnemyFromStart then
                        iCurValue = iCurValue * 0.1
                        if bDebugMessages == true then LOG(sFunctionRef..': Further from enemy base than our start position so significanlty reducing value') end
                    end

                    --If on enemy side of map reduce value
                    if tAdjLZTeamData[AiBotMap.refiModDistancePercent] > 0.5 then
                        if not(AiBotTeam.tTeamData[iTeam][AiBotTeam.refbAssassinationOrSimilar]) and (oACU[AiBotUnitInfo.refiDFMassThreatOverride] or 0) >= 3000 and AiBotUnitInfo.GetUnitHealthPercent(oACU) >= 0.99 then
                            iCurValue = iCurValue * math.max(0.05, 0.85 * (1 - tAdjLZTeamData[AiBotMap.refiModDistancePercent]))
                            if bDebugMessages == true then LOG(sFunctionRef..': High mod dist but strong ACU threat so reducing iCurValue a bit') end
                        else
                            iCurValue = iCurValue * math.max(0.01, 0.8 * (1 - tAdjLZTeamData[AiBotMap.refiModDistancePercent]))
                            if bDebugMessages == true then LOG(sFunctionRef..': High mod dist so reducing iCurValue') end
                        end
                    end

                    --Adjust based on travel distance
                    iCurValue = iCurValue * (iShortestTravelDist / iCurTravelDist)
                    if iCurTravelDist - iShortestTravelDist >= 125 then
                        iCurValue = iCurValue * (iShortestTravelDist / iCurTravelDist)
                    end
                    if bDebugMessages == true then LOG(sFunctionRef..': iCurValue after mods='..iCurValue) end
                end

                return iCurValue
            end
            for iPathingRef, tPathingDetails in tLZData[AiBotMap.subrefLZPathingToOtherLandZones] do
                iAdjLZ = tPathingDetails[AiBotMap.subrefLZNumber]
                if bDebugMessages == true then LOG(sFunctionRef..': Considering any LZs that have enemies, iAdjLZ='..iAdjLZ..'; tPathingDetails[AiBotMap.subrefLZTravelDist]='..tPathingDetails[AiBotMap.subrefLZTravelDist]..'; Is table of enemy units empty='..tostring(AiBotUtilities.IsTableEmpty(AiBotMap.tAllPlateaus[iPlateau][AiBotMap.subrefPlateauLandZones][iAdjLZ][AiBotMap.subrefLZTeamData][iTeam][AiBotMap.subrefTEnemyUnits]))..'; Is table of unbuilt locations empty='..tostring(AiBotUtilities.IsTableEmpty(AiBotMap.tAllPlateaus[iPlateau][AiBotMap.subrefPlateauLandZones][iAdjLZ][AiBotMap.subrefMexUnbuiltLocations]))..'; time last ran from iAdjZ='..(oACU[reftiTimeLastRanFromZoneByPlateau][iPlateau][iAdjLZ] or 'nil')..'; oACU[refiLastPlateauAndZoneToAttackUnitIn]='..repru(oACU[refiLastPlateauAndZoneToAttackUnitIn])..'; oACU[refiTimeLastToldToAttackUnitInOtherZone]='..(oACU[refiTimeLastToldToAttackUnitInOtherZone] or 'nil')) end
                if tPathingDetails[AiBotMap.subrefLZTravelDist] < iLowerPriorityDistanceThreshold then
                    if bDebugMessages == true then LOG(sFunctionRef..': Time since ran from this zone='..GetGameTimeSeconds() - (oACU[reftiTimeLastRanFromZoneByPlateau][iPlateau][iAdjLZ] or -10000)) end
                    if not(oACU[reftiTimeLastRanFromZoneByPlateau][iPlateau][iAdjLZ]) or GetGameTimeSeconds() - oACU[reftiTimeLastRanFromZoneByPlateau][iPlateau][iAdjLZ] > iSecondsToIgnoreZonesRecentlyRunFrom then
                        if bDebugMessages == true then LOG(sFunctionRef..': Time since last told to attack unit in this one='..(GetGameTimeSeconds() - (oACU[refiTimeLastToldToAttackUnitInOtherZone] or -10000))) end
                        if not(oACU[refiLastPlateauAndZoneToAttackUnitIn][2] == iAdjLZ) or not(oACU[refiLastPlateauAndZoneToAttackUnitIn][1] == iPlateau) or GetGameTimeSeconds() - (oACU[refiTimeLastToldToAttackUnitInOtherZone] or -100) > 30 then
                            iCurZoneValue = GetAdjZoneValueForACU(iAdjLZ, tPathingDetails[AiBotMap.subrefLZTravelDist], (iClosestWorthwhileTravelDist or tPathingDetails[AiBotMap.subrefLZTravelDist]))
                            if bDebugMessages == true then LOG(sFunctionRef..': iCurZoneValue='..iCurZoneValue..'; iBestZoneValue so far='..iBestZoneValue) end
                            if iCurZoneValue > iBestZoneValue then
                                local tAdjLZData = AiBotMap.tAllPlateaus[iPlateau][AiBotMap.subrefPlateauLandZones][iAdjLZ]
                                local tAdjLZTeamData = tAdjLZData[AiBotMap.subrefLZTeamData][iTeam]
                                if tAdjLZTeamData[AiBotMap.subrefbEnemiesInThisOrAdjacentLZ] then bBestZoneHasNearbyEnemies = true end

                                iLZToMoveTo = iAdjLZ
                                iBestZoneValue = iCurZoneValue
                                if iCurZoneValue >= 100 then --equiv to 1 unbuilt t1 mex or a zone with enemies
                                    iBestZoneDist = tPathingDetails[AiBotMap.subrefLZTravelDist]
                                    if iBestZoneDist < iClosestWorthwhileTravelDist then iClosestWorthwhileTravelDist = iBestZoneDist end
                                end
                            end
                        end
                    end
                else
                    --Nearest place of interest is so far away we might as well keep ACU at base
                    break
                end
            end

            --High value islands (we consider islands more generally below) - Consider moving if have high value island that isnt that far with a lot of mexes - do it based on drop locations
            if not(AiBotTeam.tTeamData[iTeam][AiBotTeam.reftiPotentialDropIslandsByPlateau]) then AiBotAir.UpdateTransportPlateauDropLocationShortlist(iTeam, false) end
            local iBackupLZToMoveTo = iLZToMoveTo
            if bDebugMessages == true then LOG(sFunctionRef..': Considering if we have high value islands to consider, iBackupLZToMoveTo='..(iBackupLZToMoveTo or 'nil')..'; Is table of drop islands by plateau empty='..tostring(AiBotUtilities.IsTableEmpty(AiBotTeam.tTeamData[iTeam][AiBotTeam.reftiPotentialDropIslandsByPlateau][iPlateau]))..'; Is table of pathing to other islands empty='..tostring(AiBotUtilities.IsTableEmpty(tLZData[AiBotMap.subrefLZPathingToOtherIslands]))..'; bBestZoneHasNearbyEnemies='..tostring(bBestZoneHasNearbyEnemies)..'; iBestZoneValue='..iBestZoneValue..'; Can path to enemy with land='..tostring(oACU:GetAIBrain()[AiBotMap.refbCanPathToEnemyBaseWithLand] or false)) end
            if not(iWaterZoneToConsiderBuildingNavalFactoryInFirst) and (not(iLZToMoveTo) or (not(bBestZoneHasNearbyEnemies) and (iBestZoneValue <= 300 or not(oACU:GetAIBrain()[AiBotMap.refbCanPathToEnemyBaseWithLand])))) and AiBotUtilities.IsTableEmpty(AiBotTeam.tTeamData[iTeam][AiBotTeam.reftiPotentialDropIslandsByPlateau][iPlateau]) == false and AiBotUtilities.IsTableEmpty(tLZData[AiBotMap.subrefLZPathingToOtherIslands]) == false then
                local iClosestLZRef, iCurTravelDist
                local iClosestLZTravelDist = 1000

                local iTravelDistThreshold = iLowerPriorityDistanceThreshold
                local bIslandHasUnclaimedMexesOrEnemies
                for iEntry, iIsland in AiBotTeam.tTeamData[iTeam][AiBotTeam.reftiPotentialDropIslandsByPlateau][iPlateau] do
                    --Is this a high value island?
                    if bDebugMessages == true then LOG(sFunctionRef..': Considering island '..iIsland..'; Mex count='..(AiBotMap.tAllPlateaus[iPlateau][AiBotMap.subrefPlateauIslandMexCount][iIsland] or 'nil')) end
                    if (AiBotMap.tAllPlateaus[iPlateau][AiBotMap.subrefPlateauIslandMexCount][iIsland] or 0) >= 9 then
                        --How long will it take to travel here, and do we need support on the island?
                        for _, tSubtable in tLZData[AiBotMap.subrefLZPathingToOtherIslands] do
                            if tSubtable[AiBotMap.subrefIslandNumber] == iIsland then
                                if bDebugMessages == true then LOG(sFunctionRef..': Considering iIsland='..iIsland..'; Mex count='..AiBotMap.tAllPlateaus[iPlateau][AiBotMap.subrefPlateauIslandMexCount][iIsland]..'; Travel dist='..tSubtable[AiBotMap.subrefIslandTravelDist]) end
                                if tSubtable[AiBotMap.subrefIslandTravelDist] <= math.min(iTravelDistThreshold, iClosestLZTravelDist) then
                                    tbIslandsAlreadyConsidered[iIsland] = true
                                    --Is this suitable (mod dist <0.5)?
                                    local tIslandLZData = AiBotMap.tAllPlateaus[iPlateau][AiBotMap.subrefPlateauLandZones][tSubtable[AiBotMap.subrefIslandClosestLZRef]]
                                    local tIslandLZTeamData = tIslandLZData[AiBotMap.subrefLZTeamData][iTeam]
                                    if bDebugMessages == true then LOG(sFunctionRef..': Mod dist='..(tIslandLZTeamData[AiBotMap.refiModDistancePercent] or 'nil')) end
                                    if tIslandLZTeamData[AiBotMap.refiModDistancePercent] <= 0.5 then
                                        --Check if this island is suitable - cycle through every zone and check if there is a zone with enemy combat threat and/or unclaimed mexes
                                        bIslandHasUnclaimedMexesOrEnemies = false
                                        if AiBotUtilities.IsTableEmpty(tIslandLZData[AiBotMap.subrefMexUnbuiltLocations]) == false or AiBotUtilities.IsTableEmpty(tIslandLZTeamData[AiBotMap.subrefTEnemyUnits]) == false then
                                            bIslandHasUnclaimedMexesOrEnemies = true
                                            iCurTravelDist = tSubtable[AiBotMap.subrefIslandTravelDist]
                                        else
                                            if AiBotUtilities.IsTableEmpty(tIslandLZData[AiBotMap.subrefLZPathingToOtherLandZones]) == false then
                                                for iPathingRef, tPathingDetails in tIslandLZData[AiBotMap.subrefLZPathingToOtherLandZones] do
                                                    iAdjLZ = tPathingDetails[AiBotMap.subrefLZNumber]
                                                    if bDebugMessages == true then LOG(sFunctionRef..': Considering any LZs on target island that have unclaimed mexes or enemies, Is table of unbuilt locations empty='..tostring(AiBotUtilities.IsTableEmpty(AiBotMap.tAllPlateaus[iPlateau][AiBotMap.subrefPlateauLandZones][iAdjLZ][AiBotMap.subrefMexUnbuiltLocations]))..'; Is table of enemy units empty='..tostring(AiBotUtilities.IsTableEmpty(AiBotMap.tAllPlateaus[iPlateau][AiBotMap.subrefPlateauLandZones][iAdjLZ][AiBotMap.subrefLZTeamData][iTeam][AiBotMap.subrefTEnemyUnits]))) end
                                                    if tPathingDetails[AiBotMap.subrefLZTravelDist] < (iTravelDistThreshold + 150) then
                                                        if AiBotUtilities.IsTableEmpty(AiBotMap.tAllPlateaus[iPlateau][AiBotMap.subrefPlateauLandZones][iAdjLZ][AiBotMap.subrefLZTeamData][iTeam][AiBotMap.subrefTEnemyUnits]) == false or AiBotUtilities.IsTableEmpty(AiBotMap.tAllPlateaus[iPlateau][AiBotMap.subrefPlateauLandZones][iAdjLZ][AiBotMap.subrefMexUnbuiltLocations]) == false then
                                                            iCurTravelDist = tPathingDetails[AiBotMap.subrefLZTravelDist]
                                                            bIslandHasUnclaimedMexesOrEnemies = true
                                                            break
                                                        end
                                                    end
                                                end
                                            end
                                        end
                                        if bIslandHasUnclaimedMexesOrEnemies and iCurTravelDist < iClosestLZTravelDist then
                                            iClosestLZRef = tSubtable[AiBotMap.subrefIslandClosestLZRef]
                                            iClosestLZTravelDist = tSubtable[AiBotMap.subrefIslandTravelDist]
                                            if bDebugMessages == true then LOG(sFunctionRef..': This island '..iIsland..' has unclaimed mexes or enemies and suitable travel distance') end
                                        end
                                    end
                                end
                                break
                            end
                        end
                    end
                end
                if bDebugMessages == true then LOG(sFunctionRef..': Finished going through all potential island drop locations for high value ACU islands, iClosestLZRef='..(iClosestLZRef or 'nil')) end
                if iClosestLZRef then iLZToMoveTo = iClosestLZRef end
            end
            if iBackupLZToMoveTo and not(iLZToMoveTo) then iLZToMoveTo = iBackupLZToMoveTo end



            --[[if not(iLZToMoveTo) and iNearestPotentialExpansionPoint then
                iLZToMoveTo = iNearestPotentialExpansionPoint
                iPlannedTargetDist = iPlannedDistOfPotentialExpansion
                if bDebugMessages == true then LOG(sFunctionRef..': Setting LZ to move to as the pbackup iNearestPotentialExpansionPoint='..iNearestPotentialExpansionPoint..'; iPlannedDistOfPotentialExpansion='..iPlannedDistOfPotentialExpansion) end
            end--]]
            if bDebugMessages == true then LOG(sFunctionRef..': Finished searching for zones with enemies, iLZToMoveTo='..(iLZToMoveTo or 'nil')..'; iRecentLandZoneRef='..(iRecentLandZoneRef or 'nil')) end
            if iLZToMoveTo and iRecentLandZoneRef and not(iRecentLandZoneRef == iLZToMoveTo) then
                --dont change our target if our current target is suitable still - this is to avoid cases where the land zone we move to has another land zone slightly closer to its midpoint but in the opposite direction, leading to the ACU stuck in an infinite loop going back and forth between two conflicting land zones whenever its current LZ changes
                local tPrevLZData = AiBotMap.tAllPlateaus[iPlateau][AiBotMap.subrefPlateauLandZones][iRecentLandZoneRef]
                local tPrevLZTeamData = tPrevLZData[AiBotMap.subrefLZTeamData][iTeam]

                if bDebugMessages == true then LOG(sFunctionRef..': iLZToMoveTo before adj='..iLZToMoveTo..'; iRecentLandZoneRef='..iRecentLandZoneRef..'; iClosestWorthwhileTravelDist='..(iClosestWorthwhileTravelDist or 'nil')..'; iLastPathedZoneTravelDist='..(iLastPathedZoneTravelDist or 'nil')..'; tPrevLZTeamData[AiBotMap.subrefTEnemyUnits]='..tostring(AiBotUtilities.IsTableEmpty(tPrevLZTeamData[AiBotMap.subrefTEnemyUnits]))..'; Mass reclaim='..(tPrevLZData[AiBotMap.subrefTotalMassReclaim] or 0)..'; Is table of unbuilt mexes empty='..tostring(AiBotUtilities.IsTableEmpty(tPrevLZData[AiBotMap.subrefMexUnbuiltLocations]))..'; iBestZoneValue='..iBestZoneValue)
                    if iLastPathedZoneTravelDist then LOG(sFunctionRef..': Prev zone value='..GetAdjZoneValueForACU(iAdjLZ, iLastPathedZoneTravelDist, (iClosestWorthwhileTravelDist or iLastPathedZoneTravelDist))) end
                end
                if iLastPathedZoneTravelDist and (not(iClosestWorthwhileTravelDist) or iClosestWorthwhileTravelDist + 50 >= iLastPathedZoneTravelDist) then
                    if GetAdjZoneValueForACU(iAdjLZ, iLastPathedZoneTravelDist, (iClosestWorthwhileTravelDist or iLastPathedZoneTravelDist)) * 2 >= iBestZoneValue then
                        iLZToMoveTo = iRecentLandZoneRef
                        if bDebugMessages == true then LOG(sFunctionRef..': Will retain previous expansion target as it still seems okish') end
                    end
                end
            end
        end
    end
    if bDebugMessages == true then LOG(sFunctionRef..': Finished considering whether to move to a land zone on the same island, iLZToMoveTo='..(iLZToMoveTo or 'nil')..'; Does enemy have sub? count='..(AiBotTeam.tTeamData[oACU:GetAIBrain().AiBotTeam][AiBotTeam.refiEnemySubCount] or 0)..'; iWaterZoneToConsiderBuildingNavalFactoryInFirst='..(iWaterZoneToConsiderBuildingNavalFactoryInFirst or 'nil')) end

    if not(iLZToMoveTo) and not(iWaterZoneToConsiderBuildingNavalFactoryInFirst) and not(oACU:GetAIBrain()[AiBotMap.refbCanPathToEnemyBaseWithLand]) and AiBotUtilities.IsTableEmpty(tLZData[AiBotMap.subrefLZPathingToOtherIslands]) == false
            and (AiBotTeam.tTeamData[oACU:GetAIBrain().AiBotTeam][AiBotTeam.refiEnemySubCount] or 0) <= 1 then
        local bIslandHasUnclaimedMexesOrEnemies
        local iSearchRange = 300
        if GetGameTimeSeconds() <= 600 and math.max(AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestEnemyGroundTech], AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestEnemyAirTech], AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestEnemyNavyTech]) <= 1 then
            iSearchRange = 400
        end

        for iEntry, tSubtable in tLZData[AiBotMap.subrefLZPathingToOtherIslands] do
            if not(tbIslandsAlreadyConsidered[tSubtable[AiBotMap.subrefIslandNumber]]) and tSubtable[AiBotMap.subrefIslandTravelDist] <= iSearchRange then
                if oACU[reftiTimeLastRanFromZoneByPlateau][iPlateau][tSubtable[AiBotMap.subrefIslandClosestLZRef]] and GetGameTimeSeconds() - oACU[reftiTimeLastRanFromZoneByPlateau][iPlateau][tSubtable[AiBotMap.subrefIslandClosestLZRef]] > iSecondsToIgnoreZonesRecentlyRunFrom then
                    --Are there any unclaimed mexes on the LZ?
                    bIslandHasUnclaimedMexesOrEnemies = false
                    local tIslandLZData = AiBotMap.tAllPlateaus[iPlateau][AiBotMap.subrefPlateauLandZones][tSubtable[AiBotMap.subrefIslandClosestLZRef]]
                    if AiBotUtilities.IsTableEmpty(tIslandLZData[AiBotMap.subrefMexUnbuiltLocations]) == false or AiBotUtilities.IsTableEmpty(tIslandLZData[AiBotMap.subrefLZTeamData][iTeam][AiBotMap.subrefTEnemyUnits]) == false then
                        bIslandHasUnclaimedMexesOrEnemies = true
                    else
                        if AiBotUtilities.IsTableEmpty(tIslandLZData[AiBotMap.subrefLZPathingToOtherLandZones]) == false then
                            for iPathingRef, tPathingDetails in tIslandLZData[AiBotMap.subrefLZPathingToOtherLandZones] do
                                iAdjLZ = tPathingDetails[AiBotMap.subrefLZNumber]
                                if bDebugMessages == true then LOG(sFunctionRef..': Considering any LZs on target island that have unclaimed mexes or enemies, Is table of unbuilt locations empty='..tostring(AiBotUtilities.IsTableEmpty(AiBotMap.tAllPlateaus[iPlateau][AiBotMap.subrefPlateauLandZones][iAdjLZ][AiBotMap.subrefMexUnbuiltLocations]))..'; Is table of enemy units empty='..tostring(AiBotUtilities.IsTableEmpty(AiBotMap.tAllPlateaus[iPlateau][AiBotMap.subrefPlateauLandZones][iAdjLZ][AiBotMap.subrefLZTeamData][iTeam][AiBotMap.subrefTEnemyUnits]))) end
                                if tPathingDetails[AiBotMap.subrefLZTravelDist] < (iSearchRange + 150) then
                                    if AiBotUtilities.IsTableEmpty(AiBotMap.tAllPlateaus[iPlateau][AiBotMap.subrefPlateauLandZones][iAdjLZ][AiBotMap.subrefLZTeamData][iTeam][AiBotMap.subrefTEnemyUnits]) == false or AiBotUtilities.IsTableEmpty(AiBotMap.tAllPlateaus[iPlateau][AiBotMap.subrefPlateauLandZones][iAdjLZ][AiBotMap.subrefMexUnbuiltLocations]) == false then
                                        bIslandHasUnclaimedMexesOrEnemies = true
                                        break
                                    end
                                end
                            end
                        end
                    end
                    if bDebugMessages == true then LOG(sFunctionRef..': Finished considering for land zone '..tSubtable[AiBotMap.subrefIslandClosestLZRef]..'; bIslandHasUnclaimedMexesOrEnemies='..tostring(bIslandHasUnclaimedMexesOrEnemies)) end
                    if bIslandHasUnclaimedMexesOrEnemies then
                        iLZToMoveTo = tSubtable[AiBotMap.subrefIslandClosestLZRef]
                    end
                end
            end
        end
    end
    if iLZToMoveTo then
        if AiBotOverseer.bNoRushActive and not(AiBotConditions.IsLocationInNoRushArea(AiBotMap.tAllPlateaus[iPlateau][AiBotMap.subrefPlateauLandZones][iLZToMoveTo][AiBotMap.subrefMidpoint])) then
            iLZToMoveTo = nil
        else
            AiBotOrders.IssueTrackedMove(oACU, AiBotMap.tAllPlateaus[iPlateau][AiBotMap.subrefPlateauLandZones][iLZToMoveTo][AiBotMap.subrefMidpoint], 6, false, 'ACMLZ'..iLZToMoveTo, false)
            oACU[refiTimeLastToldToMoveToZone] = GetGameTimeSeconds()
            oACU[refiLastPlateauAndZoneToMoveTo] = {iPlateau, iLZToMoveTo}
            if bDebugMessages == true then LOG(sFunctionRef..': Telling ACU to move to zone '..iLZToMoveTo..' at time='..GetGameTimeSeconds()) end
        end
    elseif iWaterZoneToConsiderBuildingNavalFactoryInFirst then
        if AiBotOverseer.bNoRushActive then
            iWaterZoneToConsiderBuildingNavalFactoryInFirst = nil
        else
            local tTargetWZData = AiBotMap.tPondDetails[AiBotMap.tiPondByWaterZone[iWaterZoneToConsiderBuildingNavalFactoryInFirst]][AiBotMap.subrefPondWaterZones][iWaterZoneToConsiderBuildingNavalFactoryInFirst]
            AiBotOrders.IssueTrackedMove(oACU, tTargetWZData[AiBotMap.subrefMidpoint], 6, false, 'ACMWZ'..iWaterZoneToConsiderBuildingNavalFactoryInFirst, false)
            oACU[refiTimeLastToldToMoveToZone] = GetGameTimeSeconds()
            oACU[refiLastPlateauAndZoneToMoveTo] = {0, iWaterZoneToConsiderBuildingNavalFactoryInFirst}
            if bDebugMessages == true then LOG(sFunctionRef..': Telling ACU to move to WZ='..iWaterZoneToConsiderBuildingNavalFactoryInFirst..' at time='..GetGameTimeSeconds()) end
        end
    end

    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
    if iLZToMoveTo or iWaterZoneToConsiderBuildingNavalFactoryInFirst then return true else return false end
end

function UpdateACULandOrWaterZoneAssignment(oACU, iPlateauOrZero, iLandOrWaterZone, tLZOrWZTeamData)
    local sFunctionRef = 'UpdateACULandOrWaterZoneAssignment'
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)

    --Update ACU tracking
    --Is the actual LZ and plateau the same? If not, then need to update tracking
    if oACU[reftiCurAssignedPlateauAndZone][1] == iPlateauOrZero and oACU[reftiCurAssignedPlateauAndZone][iLandOrWaterZone] == iLandOrWaterZone then
        --Do nothing
    else
        local iTeam = oACU:GetAIBrain().AiBotTeam
        if iLandOrWaterZone > 0 then --No point updating if we dont have a valid land zone
            oACU[reftiLastAssignedPlateauAndZone] = {oACU[reftiCurAssignedPlateauAndZone][1], oACU[reftiCurAssignedPlateauAndZone][2]}
            oACU[reftiCurAssignedPlateauAndZone] = {iPlateauOrZero, iLandOrWaterZone}
            if (oACU[reftiLastAssignedPlateauAndZone][2] or 0) > 0 then
                local tPrevLZOrWZTeamData
                if oACU[reftiLastAssignedPlateauAndZone][1] > 0 then
                    tPrevLZOrWZTeamData = AiBotMap.tAllPlateaus[oACU[reftiLastAssignedPlateauAndZone][1]][AiBotMap.subrefPlateauLandZones][oACU[reftiLastAssignedPlateauAndZone][2]][AiBotMap.subrefLZTeamData][iTeam]
                else
                    tPrevLZOrWZTeamData = AiBotMap.tPondDetails[AiBotMap.tiPondByWaterZone[oACU[reftiLastAssignedPlateauAndZone][2]]][AiBotMap.subrefPondWaterZones][oACU[reftiLastAssignedPlateauAndZone][2]][AiBotMap.subrefWZTeamData][iTeam]
                end

                --Check we are in the table
                if AiBotUtilities.IsTableEmpty(tPrevLZOrWZTeamData[AiBotMap.subrefAlliedACU]) == false then
                    for iRecordedACU, oRecordedACU in tPrevLZOrWZTeamData[AiBotMap.subrefAlliedACU] do
                        if oRecordedACU == oACU then
                            table.remove(tPrevLZOrWZTeamData[AiBotMap.subrefAlliedACU], iRecordedACU)
                            break
                        end
                    end
                end
            end
            local bAlreadyRecorded = false --Redundancy - we shouldnt have scenario where we are already recorded
            if AiBotUtilities.IsTableEmpty(tLZOrWZTeamData[AiBotMap.subrefAlliedACU]) == false then
                for iRecordedACU, oRecordedACU in tLZOrWZTeamData[AiBotMap.subrefAlliedACU] do
                    if oRecordedACU == oACU then
                        bAlreadyRecorded = true
                        break
                    end
                end
            end
            if not(bAlreadyRecorded) then
                if not(tLZOrWZTeamData[AiBotMap.subrefAlliedACU]) then tLZOrWZTeamData[AiBotMap.subrefAlliedACU] = {} end
                table.insert(tLZOrWZTeamData[AiBotMap.subrefAlliedACU], oACU)
            end
        end
    end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
end

function ConsiderGettingExtraLandFactory(tLZData, tLZTeamData, oACU, iPlateau, iLandZone)
    local sFunctionRef = 'ConsiderGettingExtraLandFactory'
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)

    if bDebugMessages == true then LOG(sFunctionRef..': Time='..GetGameTimeSeconds()..'; ACU upgrade count='..(oACU[refiUpgradeCount] or 0)..'; Is ACU in core base='..tostring(tLZTeamData[AiBotMap.subrefLZbCoreBase])..'; Plateau-LZ='..iPlateau..'-'..(iLandZone or 'nil')..'; Brain mass stored='..oACU:GetAIBrain():GetEconomyStored('MASS')..'; Want more factories for this LZ='..tostring(AiBotConditions.WantMoreFactories(oACU:GetAIBrain().AiBotTeam, iPlateau, iLandZone))) end

    if (oACU[refiUpgradeCount] or 0) == 0 and tLZTeamData[AiBotMap.subrefLZbCoreBase] and oACU:GetAIBrain():GetEconomyStored('MASS') >= 220 and AiBotConditions.WantMoreFactories(oACU:GetAIBrain().AiBotTeam, iPlateau, iLandZone) then
        --We think we want another land factory; however dont do this if we will use up our current mass in 20s or less, or we have 4+ land factories, or we are at T2
        local iTeam = oACU:GetAIBrain().AiBotTeam
        if AiBotConditions.DoWeWantAirFactoryInsteadOfLandFactory(iTeam, tLZData, tLZTeamData, oACU:GetAIBrain()) then
            --DO nothing for now
        else
            if AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestFriendlyFactoryTech] <= 1 and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamNetMass] >= -0.5 then
                local tExistingFactoriesInLZ = EntityCategoryFilterDown(AiBotUnitInfo.refCategoryFactory, tLZTeamData[AiBotMap.subreftoLZOrWZAlliedUnits])
                local iExistingFactories = 0
                if tExistingFactoriesInLZ then iExistingFactories = table.getn(tExistingFactoriesInLZ) end
                if bDebugMessages == true then LOG(sFunctionRef..': iExistingFactories='..iExistingFactories..'; If < 4 then will try and build another') end
                if iExistingFactories < 4 then
                    ACUActionBuildFactory(oACU:GetAIBrain(), oACU, iPlateau, iLandZone, tLZData, tLZTeamData)
                    --Check if we have an order as a result of this to build something
                    local tLastOrder = oACU[AiBotOrders.reftiLastOrders][oACU[AiBotOrders.refiOrderCount]]
                    if bDebugMessages == true then LOG(sFunctionRef..': Just told ACU to try and build a factory, last order='..reprs(tLastOrder)) end
                    if tLastOrder[AiBotOrders.subrefiOrderType] == AiBotOrders.refiOrderIssueRepair or tLastOrder[AiBotOrders.subrefiOrderType] == AiBotOrders.refiOrderIssueBuild or tLastOrder[AiBotOrders.subrefiOrderType] == AiBotOrders.refiOrderIssueGuard then
                        AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
                        return true
                    end
                end
            end
        end
    end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
    return false
end

function ConsiderAttackingNearbyNavalUnits(tLZData, tLZTeamData, oACU, iRangeThresholdOverride)
    --If can find an enemy that it wants the ACU to attack/move towards, will give the ACU orders and return true
    --Normally called for LZ, but if ACU has toredp attack then the LZData and teamdata may be a waterzone
    local sFunctionRef = 'ConsiderAttackingNearbyNavalUnits'
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)

    --Torpedo upgrade ACU - consider moving into water/towards nearby enemy
    local bAttackingWithTorpedo = false
    if oACU[AiBotUnitInfo.refiAntiNavyRange] and oACU[AiBotUnitInfo.refiAntiNavyRange] > 10 then
        local oNearestNavalEnemy
        local aiBrain = oACU:GetAIBrain()
        local iTeam = aiBrain.AiBotTeam
        local iClosestNavalEnemyDist = 10000
        local iCurDist
        function ConsiderUnitForTorpedoAttack(oUnit)
            if not(oUnit.Dead) and not(EntityCategoryContains(categories.HOVER, oUnit.UnitId)) then
                iCurDist = AiBotUtilities.GetDistanceBetweenPositions(oUnit:GetPosition(), oACU:GetPosition())
                if iCurDist < iClosestNavalEnemyDist then
                    iClosestNavalEnemyDist = iCurDist
                    oNearestNavalEnemy = oUnit
                end
            end
        end
        --If are on land then check adjacent zones
        if AiBotUtilities.IsTableEmpty(tLZData[AiBotMap.subrefAdjacentWaterZones]) == false then
            for iEntry, tSubtable in tLZData[AiBotMap.subrefAdjacentWaterZones] do
                local iAdjWZ = tSubtable[AiBotMap.subrefAWZRef]
                local iPond = AiBotMap.tiPondByWaterZone[iAdjWZ]
                local tWZTeamData = AiBotMap.tPondDetails[iPond][AiBotMap.subrefPondWaterZones][iAdjWZ][AiBotMap.subrefWZTeamData][iTeam]
                if AiBotUtilities.IsTableEmpty(tWZTeamData[AiBotMap.subrefTEnemyUnits]) == false and not(tWZTeamData[AiBotMap.subrefbWZOnlyHoverEnemies]) then
                    for iUnit, oUnit in tWZTeamData[AiBotMap.subrefTEnemyUnits] do
                        ConsiderUnitForTorpedoAttack(oUnit)
                    end
                end
                if not(oNearestNavalEnemy) then
                    --redundancy - use getunitsaroundpoint as sometimes can have nearby WZ that unit isnt showing in
                    local aiBrain = oACU:GetAIBrain()
                    local tNearbyNavalUnits = aiBrain:GetUnitsAroundPoint(AiBotUnitInfo.refCategoryAllAmphibiousAndNavy - categories.HOVER - AiBotUnitInfo.refCategoryAmphibious, oACU:GetPosition(), oACU[AiBotUnitInfo.refiAntiNavyRange] + (iRangeThresholdOverride or 30), 'Enemy')
                    if bDebugMessages == true then LOG(sFunctionRef..': Is table of nearby enemy hover and surface navy empty='..tostring(AiBotUtilities.IsTableEmpty(tNearbyNavalUnits))) end
                    if AiBotUtilities.IsTableEmpty(tNearbyNavalUnits) == false then
                        for iUnit, oUnit in tNearbyNavalUnits do
                            ConsiderUnitForTorpedoAttack(oUnit)
                        end
                    end
                end
            end
            --If we are a water zone then check this zone and adjacent zone
        elseif tLZData[AiBotMap.subrefWZAdjacentWaterZones] or tLZTeamData[AiBotMap.subrefWZThreatEnemyVsSurface] or tLZTeamData[AiBotMap.subrefWZThreatEnemySubmersible] then
            if AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.subrefTEnemyUnits]) == false and not(tLZTeamData[AiBotMap.subrefbWZOnlyHoverEnemies]) then
                for iUnit, oUnit in tLZTeamData[AiBotMap.subrefTEnemyUnits] do
                    ConsiderUnitForTorpedoAttack(oUnit)
                end
            end
            if AiBotUtilities.IsTableEmpty(tLZData[AiBotMap.subrefWZAdjacentWaterZones]) == false then
                for _, iAdjWZ in tLZData[AiBotMap.subrefWZAdjacentWaterZones] do
                    local tAdjWZTeamData = AiBotMap.tPondDetails[AiBotMap.tiPondByWaterZone[iAdjWZ]][AiBotMap.subrefPondWaterZones][iAdjWZ][AiBotMap.subrefWZTeamData][iTeam]
                    if AiBotUtilities.IsTableEmpty(tAdjWZTeamData[AiBotMap.subrefTEnemyUnits]) == false and not(tAdjWZTeamData[AiBotMap.subrefbWZOnlyHoverEnemies]) then
                        for iUnit, oUnit in tAdjWZTeamData[AiBotMap.subrefTEnemyUnits] do
                            ConsiderUnitForTorpedoAttack(oUnit)
                        end
                    end
                end
            end
        end

        if bDebugMessages == true then LOG(sFunctionRef..': oNearestNavalEnemy='..(oNearestNavalEnemy.UnitId or 'nil')..(AiBotUnitInfo.GetUnitLifetimeCount(oNearestNavalEnemy) or 'nil')..'; iClosestNavalEnemyDist='..iClosestNavalEnemyDist..'; refiAntiNavyRange='..oACU[AiBotUnitInfo.refiAntiNavyRange]..'; iRangeThresholdOverride='..(iRangeThresholdOverride or 'nil')) end
        if oNearestNavalEnemy then
            local iDistThreshold
            if not(iRangeThresholdOverride) then
                --Do we have stealth upgrade and are near full health? if so increase range threshold
                if oACU[refiUpgradeCount] >= 2 and (oACU:HasEnhancement('StealthGenerator') or oACU:HasEnhancement('FAF_SelfRepairSystem') or oACU:HasEnhancement('CloakingGenerator')) and AiBotUnitInfo.GetUnitHealthPercent(oACU) >= 0.95 and GetGameTimeSeconds() <= 1200 and (not(AiBotTeam.tTeamData[iTeam][AiBotTeam.refbAssassinationOrSimilar]) or (AiBotTeam.tTeamData[iTeam][AiBotTeam.refbNoAvailableTorpsForEnemies] and (AiBotTeam.tTeamData[iTeam][AiBotTeam.refiEnemyTorpBombersThreat] or 0) == 0)) then
                    iDistThreshold = 110
                elseif GetGameTimeSeconds() <= 900 and AiBotTeam.tTeamData[iTeam][AiBotTeam.refbNoAvailableTorpsForEnemies] and AiBotUnitInfo.GetUnitHealthPercent(oACU) >= 0.9 then
                    iDistThreshold = 70
                else
                    iDistThreshold = 50
                end
            else
                iDistThreshold = iRangeThresholdOverride
            end
            iDistThreshold = oACU[AiBotUnitInfo.refiAntiNavyRange] + iDistThreshold
            if bDebugMessages == true then LOG(sFunctionRef..': iDistThreshold='..iDistThreshold) end
            if iClosestNavalEnemyDist <= iDistThreshold then
                bAttackingWithTorpedo = true
                --If we are already in range and can see the unit, and we outrange its antinavy attack consider kiting
                local bGivenKitingOrder = false
                if iClosestNavalEnemyDist <= oACU[AiBotUnitInfo.refiAntiNavyRange] and AiBotUnitInfo.CanSeeUnit(aiBrain, oNearestNavalEnemy, false) then
                    --If it is a building then just do an attack order
                    local bWantToDoKitingRetreat = false
                    if EntityCategoryContains(AiBotUnitInfo.refCategoryStructure, oNearestNavalEnemy.UnitId) then
                        bGivenKitingOrder = true
                        AiBotOrders.IssueTrackedAttack(oACU, oNearestNavalEnemy, false, 'TrpAtB', false)
                        --Dealing with mobile target within our range - do we want to retreat or do manual attack, or advance?
                    elseif iClosestNavalEnemyDist + 10 <= oACU[AiBotUnitInfo.refiAntiNavyRange] then
                        bWantToDoKitingRetreat = true
                    else
                        --If enemy moving away from us then advance; if it is moving towards us then retreat; if it is barely moving then attack
                        local iCurSpeedX, iCurSpeedY, iCurSpeedZ = oNearestNavalEnemy:GetVelocity()
                        local tCurPosition = oNearestNavalEnemy:GetPosition()
                        if math.abs(iCurSpeedX) + math.abs(iCurSpeedZ) <= 0.2 then
                            bGivenKitingOrder = true
                            AiBotOrders.IssueTrackedAttack(oACU, oNearestNavalEnemy, false, 'TrpAtS', false)
                        else
                            local iDistanceShortly = AiBotUtilities.GetDistanceBetweenPositions({tCurPosition[1] + iCurSpeedX, tCurPosition[2] + iCurSpeedY, tCurPosition[3] + iCurSpeedZ}, oACU:GetPosition())
                            if iDistanceShortly > iClosestNavalEnemyDist + 0.2 then
                                bGivenKitingOrder = true
                                AiBotOrders.IssueTrackedMove(oACU, oNearestNavalEnemy:GetPosition(), 1.5, false, 'TrpMV', false) --dont want attackmove as it references maingun not torp launcher
                            elseif iDistanceShortly < iClosestNavalEnemyDist - 0.2 then
                                bWantToDoKitingRetreat = true
                            end
                        end
                    end
                    if bWantToDoKitingRetreat then
                        --Check we can retreat while still staying underwater so we dont take surface fire and can keep using torpedo attack
                        local iRetreatAngle = AiBotUtilities.GetAngleFromAToB(oACU:GetPosition(), tLZTeamData[AiBotMap.reftClosestFriendlyBase])
                        local tPotentialRetreatPosition = AiBotUtilities.MoveInDirection(oACU:GetPosition(), iRetreatAngle, 10, true, true, AiBotMap.bIsCampaignMap)
                        local iUnderwaterAmountWanted = (oACU:GetBlueprint().SizeY or 0) + 0.1
                        if AiBotUtilities.IsTableEmpty(tPotentialRetreatPosition) == false and GetSurfaceHeight(tPotentialRetreatPosition[1], tPotentialRetreatPosition[3]) - GetTerrainHeight(tPotentialRetreatPosition[1], tPotentialRetreatPosition[3]) >= iUnderwaterAmountWanted then
                            bGivenKitingOrder = true
                            AiBotOrders.IssueTrackedMove(oACU,tPotentialRetreatPosition, 1.5, false, 'TrpKiM', false) --dont want attackmove as it references maingun not torp launcher
                        elseif GetSurfaceHeight(tPotentialRetreatPosition[1], tPotentialRetreatPosition[3]) - GetTerrainHeight(tPotentialRetreatPosition[1], tPotentialRetreatPosition[3]) >= iUnderwaterAmountWanted then
                            --Attack so we dont move closer, provided we are fully underwater
                            bGivenKitingOrder = true
                            AiBotOrders.IssueTrackedAttack(oACU, oNearestNavalEnemy, false, 'TrpAtU', false)
                        end
                    end
                end
                if not(bGivenKitingOrder) then
                    --Move to target
                    AiBotOrders.IssueTrackedMove(oACU, oNearestNavalEnemy:GetPosition(), 1.5, false, 'TrpMV', false) --dont want attackmove as it references maingun not torp launcher
                end
            end
        end
    end
    if not(bAttackingWithTorpedo) and (oACU[AiBotUnitInfo.refiDFRange] or 0) > 0 and AiBotUtilities.IsTableEmpty(tLZData[AiBotMap.subrefAdjacentWaterZones]) == false then
        local iClosestEnemyToAttack = 100000
        local oClosestEnemyToAttack
        local tViaPointForClosestEnemy
        local iTeam = oACU:GetAIBrain().AiBotTeam
        local iDistToACUThreshold = (iRangeThresholdOverride or 50)
        if tLZTeamData[AiBotMap.subrefLZbCoreBase] and not(iRangeThresholdOverride) then iDistToACUThreshold = iDistToACUThreshold + 25 end
        local iDistToLandThreshold = oACU[AiBotUnitInfo.refiDFRange] - 5
        local iCurDistToACU
        local bCanHitFromLand, iAngleFromACUToUnit, iTempSegmentX, iTempSegmentZ
        local tPotentialViaPoint
        local bDontCheckPlayableArea = not(AiBotMap.bIsCampaignMap)

        if bDebugMessages == true then LOG(sFunctionRef..': Start of code at time '..GetGameTimeSeconds()..', iRangeThresholdOverride='..(iRangeThresholdOverride or 'nil')..'; iDistToLandThreshold='..iDistToLandThreshold..'; iDistToACUThreshold='..iDistToACUThreshold) end
        function ConsiderPotentialUnitTarget(oUnit)
            if AiBotUnitInfo.IsUnitValid(oUnit) and not(AiBotUnitInfo.IsUnitUnderwater(oUnit)) and (bDontCheckPlayableArea or AiBotConditions.IsLocationInPlayableArea(oUnit:GetPosition())) then
                iCurDistToACU = AiBotUtilities.GetDistanceBetweenPositions(oACU:GetPosition(), oUnit:GetPosition())
                if bDebugMessages == true then LOG(sFunctionRef..': iCurDistToACU='..iCurDistToACU..'; iDistToACUThreshold='..iDistToACUThreshold..'; iClosestEnemyToAttack='..iClosestEnemyToAttack) end
                if iCurDistToACU <= iDistToACUThreshold and iCurDistToACU < iClosestEnemyToAttack then
                    --If we move from the ACU until we are within ACU range of the unit, are we on land rather than water?
                    bCanHitFromLand = false
                    if iCurDistToACU <= iDistToLandThreshold then
                        bCanHitFromLand = true
                        tPotentialViaPoint = oUnit:GetPosition()
                    else
                        iAngleFromACUToUnit = AiBotUtilities.GetAngleFromAToB(oACU:GetPosition(), oUnit:GetPosition())
                        tPotentialViaPoint = AiBotUtilities.MoveInDirection(oACU:GetPosition(), iAngleFromACUToUnit, iCurDistToACU - iDistToLandThreshold, true, true, true)
                        iTempSegmentX, iTempSegmentZ = AiBotMap.GetPathingSegmentFromPosition(tPotentialViaPoint)
                        if AiBotMap.tLandZoneBySegment[iTempSegmentX][iTempSegmentZ] then
                            bCanHitFromLand = true
                        elseif iCurDistToACU <= oACU[AiBotUnitInfo.refiDFRange] then
                            bCanHitFromLand = true
                            tPotentialViaPoint = oUnit:GetPosition()
                        end
                    end
                    if bCanHitFromLand then
                        iClosestEnemyToAttack = iCurDistToACU
                        oClosestEnemyToAttack = oUnit
                        tViaPointForClosestEnemy = {tPotentialViaPoint[1], tPotentialViaPoint[2], tPotentialViaPoint[3]}
                    end
                end
            end
        end
        for iEntry, tSubtable in tLZData[AiBotMap.subrefAdjacentWaterZones] do
            local iAdjWZ = tSubtable[AiBotMap.subrefAWZRef]
            local iPond = AiBotMap.tiPondByWaterZone[iAdjWZ]
            local tWZTeamData = AiBotMap.tPondDetails[iPond][AiBotMap.subrefPondWaterZones][iAdjWZ][AiBotMap.subrefWZTeamData][iTeam]
            if bDebugMessages == true then LOG(sFunctionRef..': Considering iAdjWZ='..iAdjWZ..'; Enemy surface threat='.. tWZTeamData[AiBotMap.subrefWZThreatEnemyVsSurface]..'; tWZTeamData[AiBotMap.subrefiThreatEnemyGroundAA]='..tWZTeamData[AiBotMap.subrefiThreatEnemyGroundAA]) end
            if (tWZTeamData[AiBotMap.subrefWZThreatEnemyVsSurface] + tWZTeamData[AiBotMap.subrefiThreatEnemyGroundAA]) > 0 and AiBotUtilities.IsTableEmpty(tWZTeamData[AiBotMap.subrefTEnemyUnits]) == false then
                for iUnit, oUnit in tWZTeamData[AiBotMap.subrefTEnemyUnits] do
                    if bDebugMessages == true then if AiBotUnitInfo.IsUnitValid(oUnit) then LOG(sFunctionRef..': Considering enemy unit '..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..'; Is unit undetwater='..tostring(AiBotUnitInfo.IsUnitUnderwater(oUnit))..'; Is in playable area='..tostring(AiBotConditions.IsLocationInPlayableArea(oUnit:GetPosition()))) end end
                    ConsiderPotentialUnitTarget(oUnit)
                end
                if not(oClosestEnemyToAttack) then
                    --redundancy - use getunitsaroundpoint as sometimes can have nearby WZ that unit isnt showing in
                    local aiBrain = oACU:GetAIBrain()
                    local tNearbyNavalUnits = aiBrain:GetUnitsAroundPoint(AiBotUnitInfo.refCategoryAllAmphibiousAndNavy - AiBotUnitInfo.refCategoryAmphibious, oACU:GetPosition(), iDistToACUThreshold, 'Enemy')
                    if bDebugMessages == true then LOG(sFunctionRef..': Is table of nearby enemy hover and surface navy empty='..tostring(AiBotUtilities.IsTableEmpty(tNearbyNavalUnits))) end
                    if AiBotUtilities.IsTableEmpty(tNearbyNavalUnits) == false then
                        for iUnit, oUnit in tNearbyNavalUnits do
                            ConsiderPotentialUnitTarget(oUnit)
                        end
                    end
                end
            end
        end

        if oClosestEnemyToAttack then
            --move towards the enemy unit if we are out of range or only just in range, otherwise attack (or ground attack) the enemy
            if bDebugMessages == true then LOG(sFunctionRef..': oClosestEnemyToAttack='..oClosestEnemyToAttack.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oClosestEnemyToAttack)..'; iClosestEnemyToAttack='..iClosestEnemyToAttack..'; ACU range='..oACU[AiBotUnitInfo.refiDFRange]..'; Can see unit='..tostring(AiBotUnitInfo.CanSeeUnit(oACU:GetAIBrain(), oClosestEnemyToAttack))..'; Time since last weapon event='..GetGameTimeSeconds() - (oACU[AiBotUnitInfo.refiLastWeaponEvent] or -10)) end
            if iClosestEnemyToAttack <= iDistToLandThreshold then

                if AiBotUnitInfo.CanSeeUnit(oACU:GetAIBrain(), oClosestEnemyToAttack) and GetGameTimeSeconds() - (oACU[AiBotUnitInfo.refiLastWeaponEvent] or -10) <= 3 then
                    AiBotOrders.IssueTrackedAttack(oACU, oClosestEnemyToAttack, false, 'NUAt', false)
                else
                    AiBotOrders.IssueTrackedAggressiveMove(oACU, oClosestEnemyToAttack:GetPosition(), 1, false, 'NUAM', false)
                    --AiBotOrders.IssueTrackedGroundAttack(oACU, oClosestEnemyToAttack:GetPosition(), 1, false, 'NuGA', false) --tried ground attack but on frigates it just means shotting the water
                end
            else
                if AiBotUtilities.GetDistanceBetweenPositions(oACU:GetPosition(), tViaPointForClosestEnemy) >= 2 or GetGameTimeSeconds() - (oACU[AiBotUnitInfo.refiLastWeaponEvent] or -10) <= 2 then
                    AiBotOrders.IssueTrackedMove(oACU, tViaPointForClosestEnemy, 1.5, false, 'NuMV', false) --Tried doing attack move but often ACU would just stand there with attackmove slightly infront of it, and do nothing while it takes fire, e.g. if enemy isnt visible
                else
                    AiBotOrders.IssueTrackedMove(oACU, oClosestEnemyToAttack:GetPosition(), 1.5, false, 'NuMU', false) --Tried doing attack move but often ACU would just stand there with attackmove slightly infront of it, and do nothing while it takes fire, e.g. if enemy isnt visible
                end
            end
            AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
            return true
        end
    elseif bAttackingWithTorpedo then
        AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
        return true
    end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
end

function ConsiderRunningToNearestShield(oACU, tLZOrWZData, tLZOrWZTeamData, iTeam, iPlateauOrZero, iLandOrWaterZone)
    --If it's dangerous for ACUs and the current zone isnt a core zone with a shield, but there is a nearby core zone with a shield, then send the ACU there and returns true
    --Also includes logic for ACU to assist the shield and/or flag it for other engineers to assist
    local sFunctionRef = 'ConsiderRunningToNearestShield'
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)

    --No point looking for other core bases if we were the only AiBot on the team originally, or if not dangerous for ACU
    if bDebugMessages == true then LOG(sFunctionRef..': AiBotTeam.tTeamData[iTeam][AiBotTeam.refbDangerousForACUs]='..tostring(AiBotTeam.tTeamData[iTeam][AiBotTeam.refbDangerousForACUs] or false)..'; Orig brain count='..AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiOrigAiBotBrainCount]..'; tLZOrWZTeamData[AiBotMap.refiModDistancePercent]='..tLZOrWZTeamData[AiBotMap.refiModDistancePercent]) end
    if AiBotTeam.tTeamData[iTeam][AiBotTeam.refbDangerousForACUs] and (AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiOrigAiBotBrainCount] > 1 or tLZOrWZTeamData[AiBotMap.refiModDistancePercent] <= 0.3) then
        --If we have shields in this zone dont leave it
        if bDebugMessages == true then LOG(sFunctionRef..': Considering if it is safe for ACU owend by brain '..oACU:GetAIBrain().Nickname..' to be in zone '..iLandOrWaterZone..'; tLZOrWZTeamData[AiBotMap.subrefiT3FixedShieldConstructedCount]='..(tLZOrWZTeamData[AiBotMap.subrefiT3FixedShieldConstructedCount] or 'nil')..'; Is core base='..tostring(tLZOrWZTeamData[AiBotMap.subrefLZbCoreBase] or false)..'; Time='..GetGameTimeSeconds()) end
        if (tLZOrWZTeamData[AiBotMap.subrefiT3FixedShieldConstructedCount] or 0) > 0 and (tLZOrWZTeamData[AiBotMap.subrefLZbCoreBase] or (AiBotTeam.tTeamData[iTeam][AiBotTeam.refiEnemyNovaxCount] > 0 and AiBotUnitInfo.GetUnitHealthPercent(oACU) < 1)) then
            if bDebugMessages == true then LOG(sFunctionRef..': Want to go to the nearest constructed shield in this zone') end
            --If we arent already under shield coverage and ACU is sub-100% health move to be under it
            if AiBotUtilities.IsTableEmpty(tLZOrWZTeamData[AiBotMap.subreftoLZOrWZAlliedUnits]) == false and (AiBotUnitInfo.GetUnitHealthPercent(oACU) < 1 or (AiBotTeam.tTeamData[iTeam][AiBotTeam.refiEnemyNovaxCount] > 0 and tLZOrWZTeamData[AiBotMap.subrefLZbCoreBase] and oACU:GetMaxHealth() < 20000 and (not(oACU.MyShield.GetHealth) or oACU.MyShield:GetHealth() <= 5000) and (not(oACU[AiBotUnitInfo.refCategoryMobileLandShield]) or AiBotTeam.tTeamData[iTeam][AiBotTeam.refiEnemyNovaxCount] > 1) and AiBotUtilities.IsTableEmpty(oACU:GetAIBrain():GetUnitsAroundPoint(AiBotUnitInfo.refCategoryNovax, oACU:GetPosition(), 70, 'Enemy')) == false)) then
                local tFriendlyFixedShields = EntityCategoryFilterDown(AiBotUnitInfo.refCategoryFixedShield, tLZOrWZTeamData[AiBotMap.subreftoLZOrWZAlliedUnits])
                if AiBotUtilities.IsTableEmpty(tFriendlyFixedShields) == false then
                    local oNearestShieldWithHealth
                    local iNearestShieldWithHealthDist = 1000
                    local iCurDist
                    for iShield, oShield in tFriendlyFixedShields do
                        if AiBotUnitInfo.IsUnitValid(oShield) and oShield.MyShield.GetHealth and oShield.MyShield:GetHealth() >= 100 then
                            iCurDist = AiBotUtilities.GetDistanceBetweenPositions(oShield:GetPosition(), oACU:GetPosition())
                            if iCurDist < iNearestShieldWithHealthDist then
                                iNearestShieldWithHealthDist = iCurDist
                                oNearestShieldWithHealth = oShield
                            end
                        end
                    end
                    if oNearestShieldWithHealth then
                        oACU[refoShieldRallyTarget] = oNearestShieldWithHealth
                        --Are we not comfortably within the shield coverage?
                        if iNearestShieldWithHealthDist > (oNearestShieldWithHealth:GetBlueprint().Defense.Shield.ShieldSize or 0) * 0.45 - 4 then
                            AiBotOrders.IssueTrackedMove(oACU, oNearestShieldWithHealth:GetPosition(), 1, false, 'RetrCSh', false)
                            if bDebugMessages == true then LOG(sFunctionRef..': Will retreat ACU to the nearest shield '..oNearestShieldWithHealth.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oNearestShieldWithHealth)..'; Special micro active='..tostring(oACU[AiBotUnitInfo.refbSpecialMicroActive] or false)) end
                            AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
                            return true
                        else
                            --Do we want to assist the shield if it isnt at full health?
                            local iShieldCurHealth, iShieldMaxHealth = AiBotUnitInfo.GetCurrentAndMaximumShield(oNearestShieldWithHealth, true)
                            if bDebugMessages == true then LOG(sFunctionRef..': Considering if we want ACU to assist the shield it is currently assigned to, shield health%='..iShieldCurHealth / iShieldMaxHealth) end
                            if iShieldCurHealth / iShieldMaxHealth <= 0.85 then
                                AiBotOrders.IssueTrackedGuard(oACU, oNearestShieldWithHealth, false, 'RetrAsSh', false)
                                if not(oNearestShieldWithHealth[AiBotBuilding.reftArtiTemplateRefs]) and iShieldCurHealth / iShieldMaxHealth <= 0.8 then
                                    --Add shield to table of priority shields to assist for engineers
                                    local bAlreadyRecorded = false
                                    if AiBotUtilities.IsTableEmpty(tLZOrWZTeamData[AiBotMap.reftPriorityShieldsToAssist]) == false then
                                        for iRecorded, oRecorded in tLZOrWZTeamData[AiBotMap.reftPriorityShieldsToAssist] do
                                            if oRecorded == oNearestShieldWithHealth then bAlreadyRecorded = true break end
                                        end
                                    end
                                    if not(bAlreadyRecorded) then
                                        if not(tLZOrWZTeamData[AiBotMap.reftPriorityShieldsToAssist]) then tLZOrWZTeamData[AiBotMap.reftPriorityShieldsToAssist] = {} end
                                        table.insert(tLZOrWZTeamData[AiBotMap.reftPriorityShieldsToAssist], oNearestShieldWithHealth)
                                        oNearestShieldWithHealth[AiBotBuilding.refbRemoveShieldFromPriorityTableWhenFullHealth] = true
                                    end
                                end
                            end
                        end
                    end

                end
            end
            if bDebugMessages == true then LOG(sFunctionRef..': We have a shield in this zone, but ACU is on full health and/or is already under shield coverage or the shield lacks sufficient health so wont retreat to this shield') end
        else
            --Find out closest zone on a plateau that has a shield
            local iClosestCoreZoneWithShield = 275 --no point trying to move to a zone further away than this
            local iCurDist
            local iClosestZoneWithShieldRef
            local tMoveDestination
            local iMinShieldsWanted = 2
            if AiBotUnitInfo.GetUnitHealthPercent(oACU) < 1 or tLZOrWZTeamData[AiBotMap.subrefbDangerousEnemiesInThisLZ] then iMinShieldsWanted = 1 end
            if AiBotUtilities.IsTableEmpty(AiBotTeam.tTeamData[iTeam][AiBotTeam.reftiCoreZonesByPlateau][iPlateauOrZero]) == false then
                for iZone, bCoreZone in AiBotTeam.tTeamData[iTeam][AiBotTeam.reftiCoreZonesByPlateau][iPlateauOrZero] do
                    if not(iZone == iLandOrWaterZone) then
                        local tAltLZData = AiBotMap.tAllPlateaus[iPlateauOrZero][AiBotMap.subrefPlateauLandZones][iZone]
                        local tAltLZTeamData = tAltLZData[AiBotMap.subrefLZTeamData][iTeam]
                        --Require at least 1 more shield at the target zone than in this zone, otherwise hte first zone to get a shield will have all ACUs going towards it
                        if (tAltLZTeamData[AiBotMap.subrefiT3FixedShieldConstructedCount] or 0) >= iMinShieldsWanted and tAltLZTeamData[AiBotMap.subrefLZbCoreBase] and not(tAltLZTeamData[AiBotMap.subrefbDangerousEnemiesInThisLZ]) then
                            if tAltLZData[AiBotMap.subrefLZIslandRef] == tLZOrWZData[AiBotMap.subrefLZIslandRef] then
                                iCurDist = AiBotMap.GetTravelDistanceBetweenLandZones(iPlateauOrZero, iLandOrWaterZone, iZone, true)
                            else
                                if bDebugMessages == true then LOG(sFunctionRef..': Zone on dif island so significantly increasing the distance') end
                                iCurDist = 100 + AiBotUtilities.GetDistanceBetweenPositions(tAltLZData[AiBotMap.subrefMidpoint], tLZOrWZData[AiBotMap.subrefMidpoint])
                            end
                            if bDebugMessages == true then LOG(sFunctionRef..': Alternative zone '..iZone..' has shield constructed count '..(tAltLZTeamData[AiBotMap.subrefiT3FixedShieldConstructedCount] or 0)..'; iCurDist='..repru(iCurDist)..'; iMinShieldsWanted='..iMinShieldsWanted..'; iPlateauOrZero='..(iPlateauOrZero or 'nil')..'; iLandOrWaterZone='..(iLandOrWaterZone or 'nil')) end
                            if iCurDist < iClosestCoreZoneWithShield then
                                --Is the target zone not significantly closer to the nearest enemy base?
                                if bDebugMessages == true then LOG(sFunctionRef..': Dist to nearest base from target zone='..AiBotUtilities.GetDistanceBetweenPositions(tAltLZData[AiBotMap.subrefMidpoint], tAltLZTeamData[AiBotMap.reftClosestEnemyBase])..'; Dist to enemy base from cur zone='..AiBotUtilities.GetDistanceBetweenPositions(tLZOrWZData[AiBotMap.subrefMidpoint], tLZOrWZTeamData[AiBotMap.reftClosestEnemyBase])) end
                                if AiBotUtilities.GetDistanceBetweenPositions(tAltLZData[AiBotMap.subrefMidpoint], tAltLZTeamData[AiBotMap.reftClosestEnemyBase]) + 30 >= AiBotUtilities.GetDistanceBetweenPositions(tLZOrWZData[AiBotMap.subrefMidpoint], tLZOrWZTeamData[AiBotMap.reftClosestEnemyBase]) then
                                    iClosestCoreZoneWithShield = iCurDist
                                    iClosestZoneWithShieldRef = iZone
                                    tMoveDestination = {tAltLZData[AiBotMap.subrefMidpoint][1], tAltLZData[AiBotMap.subrefMidpoint][2], tAltLZData[AiBotMap.subrefMidpoint][3]}
                                end
                            end
                        end
                    end
                end
            end
            if bDebugMessages == true then LOG(sFunctionRef..': iClosestZoneWithShieldRef='..(iClosestZoneWithShieldRef or 'nil')..'; iClosestCoreZoneWithShield='..iClosestCoreZoneWithShield) end
            if iClosestZoneWithShieldRef then
                AiBotOrders.IssueTrackedMove(oACU, tMoveDestination, 5, false, 'RetrSh', false)
                if bDebugMessages == true then LOG(sFunctionRef..': Will retreat ACU to the zone') end
                AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
                return true
            else
                if bDebugMessages == true then LOG(sFunctionRef..': Considering if are any T2 plus shields nearby if vulnerable to novax, since since last novax tLZOrWZTeamData[AiBotMap.refiTimeOfNearbyEnemyNovax]='..GetGameTimeSeconds() - (tLZOrWZTeamData[AiBotMap.refiTimeOfNearbyEnemyNovax] or 0)..'; ACU health percent='..AiBotUnitInfo.GetUnitHealthPercent(oACU)..'; iPlateauOrZero='..iPlateauOrZero..'; Novax count='..AiBotTeam.tTeamData[iTeam][AiBotTeam.refiEnemyNovaxCount]) end
                if AiBotUnitInfo.GetUnitHealthPercent(oACU) <= 0.95 and iPlateauOrZero > 0 and AiBotTeam.tTeamData[iTeam][AiBotTeam.refiEnemyNovaxCount] > 0 and tLZOrWZTeamData[AiBotMap.refiTimeOfNearbyEnemyNovax] and GetGameTimeSeconds() - tLZOrWZTeamData[AiBotMap.refiTimeOfNearbyEnemyNovax] <= 5 then
                    --Do we have any allied Fixed T2 non-Cybran shields nearby? if so try heading here instead
                    local aiBrain = oACU:GetAIBrain()
                    local tNearbyFixedShields = aiBrain:GetUnitsAroundPoint(AiBotUnitInfo.refCategoryFixedShield - categories.CYBRAN * categories.TECH2 -categories.TECH1, oACU:GetPosition(), 120, 'Ally')
                    if bDebugMessages == true then LOG(sFunctionRef..': Is table of nearby fixed shields empty='..tostring(AiBotUtilities.IsTableEmpty(tNearbyFixedShields) == false)) end
                    if AiBotUtilities.IsTableEmpty(tNearbyFixedShields) == false then
                        --Assist the closest fixed shield with health, or just the closest under construction
                        local iClosestWithHealthShieldDist = 10000
                        local iClosestShieldOfAnyTypeDist = 10000
                        local oClosestWithHealthShield
                        local oClosestShieldOfAnyType
                        local iCurDist, iCurShield, iMaxShield


                        for iShield, oShield in tNearbyFixedShields do
                            iCurDist = AiBotUtilities.GetDistanceBetweenPositions(oShield:GetPosition(), oACU:GetPosition())
                            if iCurDist < iClosestWithHealthShieldDist then
                                if NavUtils.GetTerrainLabel(AiBotMap.refPathingTypeHover, oShield:GetPosition()) == iPlateauOrZero then
                                    if iCurDist < iClosestShieldOfAnyTypeDist then
                                        oClosestShieldOfAnyType = oShield
                                        iClosestShieldOfAnyTypeDist = iCurDist
                                    end
                                    if oShield:GetFractionComplete()== 1 then
                                        iCurShield, iMaxShield = AiBotUnitInfo.GetCurrentAndMaximumShield(oShield, true)
                                        if iCurShield >= 100 then
                                            iClosestWithHealthShieldDist = iCurDist
                                            oClosestWithHealthShield = oShield
                                        end
                                    end
                                end
                            end
                        end
                        local oShieldToAssist = oClosestWithHealthShield or oClosestShieldOfAnyType
                        if bDebugMessages == true then LOG(sFunctionRef..': oShieldToAssist='..(oShieldToAssist.UnitId or 'nil')..(AiBotUnitInfo.GetUnitLifetimeCount(oShieldToAssist) or 'nil')) end
                        if oShieldToAssist then
                            oACU[refoShieldRallyTarget] = oShieldToAssist
                            AiBotOrders.IssueTrackedGuard(oACU, oShieldToAssist, false, 'BkcupAsSh', false)
                            AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
                            return true
                        end
                    end
                end
            end
        end
    end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
    return false
end

function ReturnACUToCoreBase(oACU, tLZOrWZData, tLZOrWZTeamData, aiBrain, iTeam, iPlateauOrZero, iLandOrWaterZone)
    local sFunctionRef = 'ReturnACUToCoreBase'
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)


    oACU[refiTimeLastWantedToRun] = GetGameTimeSeconds()

    --Go to core base
    local tRallyPoint

    if tLZOrWZTeamData[AiBotMap.subrefLZbCoreBase] and AiBotUtilities.IsTableEmpty(tLZOrWZTeamData[AiBotMap.subreftoLZOrWZAlliedUnits]) == false then
        local tFixedShields = EntityCategoryFilterDown(AiBotUnitInfo.refCategoryFixedShield, tLZOrWZTeamData[AiBotMap.subreftoLZOrWZAlliedUnits])
        if AiBotUtilities.IsTableEmpty(tFixedShields) == false then
            local iNearestDist = 10000
            local iCurDist
            local oNearestUnit
            local bCheckIfOtherACUsUnderShield = false
            local bAddAsNearestShield
            if AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiActiveAiBotBrainCount] > 1 then
                bCheckIfOtherACUsUnderShield = true
                if AiBotUnitInfo.GetUnitHealthPercent(oACU) < 0.9 then bCheckIfOtherACUsUnderShield = false end
            end
            for iUnit, oUnit in tFixedShields do
                if AiBotUnitInfo.IsUnitValid(oUnit) and oUnit:GetFractionComplete() == 1 then
                    iCurDist = AiBotUtilities.GetDistanceBetweenPositions(oUnit:GetPosition(), oACU:GetPosition())
                    if iCurDist < iNearestDist then
                        bAddAsNearestShield = true
                        --Check not already assigned to an ACU (unless we are low health)
                        if bCheckIfOtherACUsUnderShield then
                            for iFriendlyACU, oFriendlyACU in AiBotTeam.tTeamData[iTeam][AiBotTeam.reftAiBotACUs] do
                                if not(oFriendlyACU == oACU) then
                                    if oFriendlyACU[refoShieldRallyTarget] and oFriendlyACU[refoShieldRallyTarget] == oUnit then
                                        if bDebugMessages == true then LOG(sFunctionRef..': Wont go to nearest shield as it is already a rally target for another ACU') end
                                        iCurDist = iCurDist + 400
                                        if iCurDist > iNearestDist then
                                            bAddAsNearestShield = false
                                            break
                                        end
                                    end
                                end
                            end
                        end
                        if bAddAsNearestShield then
                            iNearestDist = iCurDist
                            oNearestUnit = oUnit
                        end
                    end
                end
            end

            if oNearestUnit then
                oACU[refoShieldRallyTarget] = oNearestUnit
                if bDebugMessages == true then LOG(sFunctionRef..': Will set rally point to the nearest fixed shield, position='..repru(oNearestUnit:GetPosition())..'; Nearest unit='..oNearestUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oNearestUnit)) end
                tRallyPoint = oNearestUnit:GetPosition()
            end
        end
    end
    if not(tRallyPoint) then
        tRallyPoint = AiBotMap.GetPlayerStartPosition(oACU:GetAIBrain())
        --If this isn't a core base then get the nearest core base (e.g. helps in campaign where start position is unreliable)
        local tStartLZData, tStartLZTeamData = AiBotMap.GetLandOrWaterZoneData(tRallyPoint, true, iTeam)
        if bDebugMessages == true then LOG(sFunctionRef..': No shields so will move ACU to start point, subrefLZbCoreBase='..tostring(tStartLZTeamData[AiBotMap.subrefLZbCoreBase] or false)..'; subrefWZbCoreBase='..tostring(tStartLZTeamData[AiBotMap.subrefWZbCoreBase] or false)) end
        if (not(tStartLZTeamData[AiBotMap.subrefLZbCoreBase]) and not(tStartLZTeamData[AiBotMap.subrefWZbCoreBase])) or (AiBotMap.bIsCampaignMap and tStartLZTeamData[AiBotMap.subrefLZSValue] < 200) then
            tRallyPoint = {tStartLZTeamData[AiBotMap.reftClosestFriendlyBase][1], tStartLZTeamData[AiBotMap.reftClosestFriendlyBase][2], tStartLZTeamData[AiBotMap.reftClosestFriendlyBase][3]}
            local tClosestBaseLZData, tClosestBaseLZTeamData = AiBotMap.GetLandOrWaterZoneData(tRallyPoint, true, iTeam)
            if bDebugMessages == true then LOG(sFunctionRef..': Switched rally point to closest friendly base, subrefLZbCoreBase='..tostring(tClosestBaseLZTeamData[AiBotMap.subrefLZbCoreBase] or false)..'; subrefWZbCoreBase='..tostring(tClosestBaseLZTeamData[AiBotMap.subrefWZbCoreBase] or false)..'; subrefLZSValue='..(tClosestBaseLZTeamData[AiBotMap.subrefLZSValue] or 'nil')..'; Not core base combined condition='..tostring((not(tClosestBaseLZTeamData[AiBotMap.subrefLZbCoreBase]) and not(tClosestBaseLZTeamData[AiBotMap.subrefWZbCoreBase])))..'; Campaign with low S value='..tostring((AiBotMap.bIsCampaignMap and (tClosestBaseLZTeamData[AiBotMap.subrefLZSValue] or 0) < 200))) end
            if (not(tClosestBaseLZTeamData[AiBotMap.subrefLZbCoreBase]) and not(tClosestBaseLZTeamData[AiBotMap.subrefWZbCoreBase])) or (AiBotMap.bIsCampaignMap and (tClosestBaseLZTeamData[AiBotMap.subrefLZSValue] or 0) < 200) then
                --Find the closest zone that has SValue in it, if any
                AiBotAir.RecordOtherLandAndWaterZonesByDistance(tLZOrWZData)
                if bDebugMessages == true then LOG(sFunctionRef..': Is table of other zones empty='..tostring(AiBotUtilities.IsTableEmpty(tLZOrWZData[AiBotMap.subrefOtherLandAndWaterZonesByDistance]))) end
                if AiBotUtilities.IsTableEmpty(tLZOrWZData[AiBotMap.subrefOtherLandAndWaterZonesByDistance]) then
                    AiBotUtilities.ErrorHandler('No other zones found')
                else
                    tRallyPoint = nil
                    local iPlateauWanted
                    if iPlateauOrZero > 0 then iPlateauWanted = iPlateauOrZero
                    else iPlateauWanted = NavUtils.GetLabel(AiBotMap.refPathingTypeHover, oACU:GetPosition())
                    end
                    if iPlateauWanted then
                        for iEntry, tSubtable in tLZOrWZData[AiBotMap.subrefOtherLandAndWaterZonesByDistance] do
                            if bDebugMessages == true then LOG(sFunctionRef..': Considering subrefiPlateauOrPond='..tSubtable[AiBotMap.subrefiPlateauOrPond]..'Z'..tSubtable[AiBotMap.subrefiLandOrWaterZoneRef]..'; subrefbIsWaterZone='..tostring(tSubtable[AiBotMap.subrefbIsWaterZone] or false)..'; iPlateauOrZero='..iPlateauOrZero..'; iPlateauWanted='..(iPlateauWanted or 'nil')) end
                            if tSubtable[AiBotMap.subrefiPlateauOrPond] == iPlateauWanted and not(tSubtable[AiBotMap.subrefbIsWaterZone]) then
                                local tAltLZOrWZData = AiBotMap.tAllPlateaus[tSubtable[AiBotMap.subrefiPlateauOrPond]][AiBotMap.subrefPlateauLandZones][tSubtable[AiBotMap.subrefiLandOrWaterZoneRef]]
                                local tAltLZOrWZTeamData = tAltLZOrWZData[AiBotMap.subrefLZTeamData][iTeam]
                                if bDebugMessages == true then LOG(sFunctionRef..': Considering whether to go to land zone on same plateau instead, currently considering P'..tSubtable[AiBotMap.subrefiPlateauOrPond]..'Z'..tSubtable[AiBotMap.subrefiLandOrWaterZoneRef]..'; SValue='..(tAltLZOrWZTeamData[AiBotMap.subrefLZSValue] or 'nil')) end
                                if tAltLZOrWZTeamData[AiBotMap.subrefLZSValue] > 200 and AiBotUtilities.IsTableEmpty(EntityCategoryFilterDown(AiBotUnitInfo.refCategoryAllHQFactories, tAltLZOrWZTeamData[AiBotMap.subreftoLZOrWZAlliedUnits])) == false then
                                    if bDebugMessages == true then LOG(sFunctionRef..': Will set this as the revised rally point for ACU to run to') end
                                    tRallyPoint = {tAltLZOrWZData[AiBotMap.subrefMidpoint][1], tAltLZOrWZData[AiBotMap.subrefMidpoint][2], tAltLZOrWZData[AiBotMap.subrefMidpoint][3]}
                                    break
                                end
                            end
                        end
                    end
                    if not(tRallyPoint) then
                        if bDebugMessages == true then LOG(sFunctionRef..': Will just get nearest rally point') end
                        if iPlateauOrZero == 0 then
                            tRallyPoint = AiBotNavy.GetNearestWaterRallyPoint(tLZOrWZData, iTeam, AiBotMap.tiPondByWaterZone[iLandOrWaterZone], iLandOrWaterZone)
                        else
                            tRallyPoint = AiBotLand.GetNearestLandRallyPoint(tLZOrWZData, iTeam, iPlateauOrZero, iLandOrWaterZone, 10, true)
                        end
                    end
                end
            end
        end
    end

    local iNearestEnemyExperimental = 1000
    local oNearestEnemyExperimental
    local iCurDist
    if AiBotUtilities.IsTableEmpty(AiBotTeam.tTeamData[iTeam][AiBotTeam.reftEnemyLandExperimentals]) == false then
        for iUnit, oUnit in AiBotTeam.tTeamData[iTeam][AiBotTeam.reftEnemyLandExperimentals] do
            iCurDist = AiBotUtilities.GetDistanceBetweenPositions(oUnit:GetPosition(), oACU:GetPosition())
            if iCurDist < iNearestEnemyExperimental then
                iNearestEnemyExperimental = iCurDist
                oNearestEnemyExperimental = oUnit
            end
        end
    end
    local iAngleThreshold = 115
    --Consider running from the experimental if we arent in its range yet
    if oNearestEnemyExperimental and iNearestEnemyExperimental > (oNearestEnemyExperimental[AiBotUnitInfo.refiDFRange] or 30) + 1 and iNearestEnemyExperimental <= 160 then
        --Would moving towards the closest base take us in a similar direction to this experimental?
        local iAngleToExperimental = AiBotUtilities.GetAngleFromAToB(oACU:GetPosition(), oNearestEnemyExperimental:GetPosition())
        local iAngleToRally = AiBotUtilities.GetAngleFromAToB(oACU:GetPosition(), tRallyPoint)
        local iAngleDif = AiBotUtilities.GetAngleDifference(iAngleToExperimental, iAngleToRally)
        if bDebugMessages == true then LOG(sFunctionRef..': iAngleToExperimental='..iAngleToExperimental..'; iAngleToRally='..iAngleToRally..'; iAngleDif='..iAngleDif..'; iNearestEnemyExperimental='..iNearestEnemyExperimental) end
        if iAngleDif < iAngleThreshold then
            --What if we just go to a land rally point?
            local tAltRallyPoint
            if iPlateauOrZero == 0 then
                tAltRallyPoint = oACU[AiBotOrders.reftiLastOrders][1][AiBotOrders.subreftOrderPosition] or AiBotNavy.GetNearestWaterRallyPoint(tLZOrWZData, iTeam, AiBotMap.tiPondByWaterZone[iLandOrWaterZone], iLandOrWaterZone)
            else
                tAltRallyPoint = AiBotLand.GetNearestLandRallyPoint(tLZOrWZData, iTeam, iPlateauOrZero, iLandOrWaterZone, 3, true)
            end
            local iAngleToAltRally = AiBotUtilities.GetAngleFromAToB(oACU:GetPosition(), tAltRallyPoint)
            local iAltRallyAngleDif = AiBotUtilities.GetAngleDifference(iAngleToExperimental, iAngleToAltRally)
            if bDebugMessages == true then LOG(sFunctionRef..': Angle to alt rally='..iAltRallyAngleDif) end
            if iAltRallyAngleDif >= iAngleThreshold or (iAltRallyAngleDif >= 90 and iAltRallyAngleDif > iAngleDif) then
                tRallyPoint = tAltRallyPoint
            elseif iNearestEnemyExperimental <= 100 then
                --Try moving away from the enemy unit if it is getting close to us
                local tTempPosition
                local bHaveValidRunAwayPosition = false
                for iDistance = 10, 30, 10 do
                    for iAngleSize = 0, 45, 15 do
                        for iAngleMod = -1, 1, 2 do
                            tTempPosition = AiBotUtilities.MoveInDirection(oACU:GetPosition(), iAngleToExperimental + 180 + iAngleSize * iAngleMod, iDistance, true, true, AiBotMap.bIsCampaignMap)
                            if AiBotUtilities.IsTableEmpty(tTempPosition) == false and NavUtils.GetLabel(AiBotMap.refPathingTypeHover, tTempPosition) == iPlateauOrZero then
                                tRallyPoint = tTempPosition
                                bHaveValidRunAwayPosition = true
                                if bDebugMessages == true then LOG(sFunctionRef..': will try running in opposite direction to approaching enemy experimental, iDistance='..iDistance..'; iAngleSize='..iAngleSize..'; iAngleMod='..iAngleMod) end
                                break
                            end
                        end
                        if bHaveValidRunAwayPosition then break end
                    end
                    if bHaveValidRunAwayPosition then break end
                end
                if bDebugMessages == true then LOG(sFunctionRef..': bHaveValidRunAwayPosition='..tostring(bHaveValidRunAwayPosition)..'; tRallyPoint='..repru(tRallyPoint)) end
            end
        end
    end

    if not(tLZOrWZTeamData[AiBotMap.subrefLZbCoreBase]) and not(tLZOrWZTeamData[AiBotMap.subrefWZbContainsUnderwaterStart]) then
        if iPlateauOrZero > 0 and AiBotUtilities.IsTableEmpty(tLZOrWZTeamData[AiBotMap.reftoNearestDFEnemies]) == false and AiBotConditions.GiveAttackMoveAsWeaponStuck(oACU) and AiBotConditions.CloseToEnemyUnit(oACU:GetPosition(), tLZOrWZTeamData[AiBotMap.reftoNearestDFEnemies], oACU[AiBotUnitInfo.refiCombatRange], iTeam, false, nil, nil, nil, nil, nil) then
            AiBotOrders.IssueTrackedAttackMove(oACU, tRallyPoint, 3, false, 'RunT')
        else
            --if not(ACUStuckAndGivenIntermediateMovePoint(oACU, tRallyPoint)) then --Function didnt actually help ACU get unstuck in one replay where it got stuck, but might in other scenario
            AiBotOrders.IssueTrackedMove(oACU, tRallyPoint, 3, false, 'Runa')
            --end
        end
        if bDebugMessages == true then LOG(sFunctionRef..': Sending ACU to core base') end
    else
        --Consider attacking nearby enemies if no enemy experimental
        if bDebugMessages == true then LOG(sFunctionRef..': iNearestEnemyExperimental='..iNearestEnemyExperimental..'; ACU range='..oACU[AiBotUnitInfo.refiDFRange]..'; ACU health='..AiBotUnitInfo.GetUnitHealthPercent(oACU)..'; ACU dist to rally='..AiBotUtilities.GetDistanceBetweenPositions(tRallyPoint, oACU:GetPosition())) end
        if (iNearestEnemyExperimental <= 150 and iNearestEnemyExperimental >= (oACU[AiBotUnitInfo.refiDFRange] or 0) + 5) or (AiBotUnitInfo.GetUnitHealthPercent(oACU) <= 0.6 and AiBotUtilities.GetDistanceBetweenPositions(tRallyPoint, oACU:GetPosition()) > 10) then
            if bDebugMessages == true then LOG(sFunctionRef..': Will move ACU to rally point instead of base, unless it means moving close to the exp, in which case will try moving in the opposite direction if we can') end
            if oNearestEnemyExperimental then
                local iAngleToNearestExp = AiBotUtilities.GetAngleFromAToB(oACU:GetPosition(), oNearestEnemyExperimental:GetPosition())
                local iAngleToRally = AiBotUtilities.GetAngleFromAToB(oACU:GetPosition(), tRallyPoint)
                local iAngleThreshold = 115
                if AiBotUtilities.GetAngleDifference(iAngleToNearestExp, iAngleToRally) <= iAngleThreshold then
                    --We aren't moving away from the experimental by much
                    local tPotentialAltLocation
                    local iClosestAltLocation = 10000
                    --If we have ot her core bases we can retreat to them, otherwise try moving in the opposite direction
                    if AiBotUtilities.IsTableEmpty(AiBotTeam.tTeamData[iTeam][AiBotTeam.reftiCoreZonesByPlateau][iPlateauOrZero]) == false then
                        for iLandZone, _ in AiBotTeam.tTeamData[iTeam][AiBotTeam.reftiCoreZonesByPlateau][iPlateauOrZero] do
                            if not(iLandZone == iLandOrWaterZone) then
                                local tAltLZData = AiBotMap.tAllPlateaus[iPlateauOrZero][AiBotMap.subrefPlateauLandZones][iLandZone]
                                local iAngleToAltMidpoint = AiBotUtilities.GetAngleFromAToB(oACU:GetPosition(), tAltLZData[AiBotMap.subrefMidpoint])
                                if AiBotUtilities.GetAngleDifference(iAngleToNearestExp, iAngleToAltMidpoint) > iAngleThreshold then
                                    local iCurDist = AiBotUtilities.GetDistanceBetweenPositions(oACU:GetPosition(), tAltLZData[AiBotMap.subrefMidpoint])
                                    if iCurDist < iClosestAltLocation then
                                        iClosestAltLocation = iCurDist
                                        tPotentialAltLocation = { tAltLZData[AiBotMap.subrefMidpoint][1], tAltLZData[AiBotMap.subrefMidpoint][2], tAltLZData[AiBotMap.subrefMidpoint][3]}
                                    end
                                end
                            end
                        end
                    end
                    if not(tPotentialAltLocation) then
                        local iAmphibiousLabelWanted = NavUtils.GetTerrainLabel(AiBotMap.refPathingTypeAmphibious, oACU:GetPosition())
                        if iAmphibiousLabelWanted then
                            for iMoveDist = 10, 30, 5 do
                                tPotentialAltLocation = AiBotUtilities.MoveInDirection(oACU:GetPosition(), iAngleToNearestExp + 180, iMoveDist, true, true, AiBotMap.bIsCampaignMap)
                                if AiBotUtilities.IsTableEmpty(tPotentialAltLocation) == false and NavUtils.GetTerrainLabel(AiBotMap.refPathingTypeAmphibious, tPotentialAltLocation) == iAmphibiousLabelWanted then
                                    break
                                else
                                    tPotentialAltLocation = nil
                                end
                            end
                        end
                    end
                    if bDebugMessages == true then LOG(sFunctionRef..': Angle to rally is too close to exp, so tried searching for alt locations, tPotentialAltLocation='..repru(tPotentialAltLocation)) end
                    if AiBotUtilities.IsTableEmpty(tPotentialAltLocation) == false then
                        tRallyPoint = {tPotentialAltLocation[1], tPotentialAltLocation[2], tPotentialAltLocation[3]}
                    end
                end
            end

            AiBotOrders.IssueTrackedMove(oACU, tRallyPoint, 5, false, 'Runb')

        else
            if tLZOrWZTeamData[AiBotMap.subrefbDangerousEnemiesInThisLZ] and AttackNearestEnemyWithACU(iPlateauOrZero, iLandOrWaterZone, tLZOrWZData, tLZOrWZTeamData, oACU) then
                --Do nothing
                if bDebugMessages == true then LOG(sFunctionRef..': Will attack nearby enemy units with ACU') end
            else
                --Are there nearby enemy naval units to attack?
                if bDebugMessages == true then LOG(sFunctionRef..': Considering if are nearby naval threats to attack, is table of adjacent WZs empty='..tostring(AiBotUtilities.IsTableEmpty(tLZOrWZData[AiBotMap.subrefAdjacentWaterZones]))..'; Do we lack torp bombers for enemy naval='..tostring(AiBotTeam.tAirSubteamData[oACU:GetAIBrain().AiBotAirSubteam][AiBotTeam.refbNoAvailableTorpsForEnemies])) end
                if (oACU[AiBotUnitInfo.refiDFRange] or 0) > 0 and AiBotUtilities.IsTableEmpty(tLZOrWZData[AiBotMap.subrefAdjacentWaterZones]) == false and AiBotTeam.tAirSubteamData[oACU:GetAIBrain().AiBotAirSubteam][AiBotTeam.refbNoAvailableTorpsForEnemies] and ConsiderAttackingNearbyNavalUnits(tLZOrWZData, tLZOrWZTeamData, oACU, oACU[AiBotUnitInfo.refiDFRange] + 10) then
                    if bDebugMessages == true then LOG(sFunctionRef..': Will attack nearby naval threats') end
                else
                    if bDebugMessages == true then LOG(sFunctionRef..': No naval threats close enough to attack so will consider nearby reclaim') end
                    if not(ConsiderNearbyReclaimForACUOrEngineer(iPlateauOrZero, iLandOrWaterZone, tLZOrWZData, tLZOrWZTeamData, oACU, true)) then
                        local sUpgradeToGet, bIgnoreOtherUpgradeConditions = GetACUUpgradeWanted(oACU, nil, tLZOrWZData, tLZOrWZTeamData, iPlateauOrZero)

                        if sUpgradeToGet and (bIgnoreOtherUpgradeConditions or (not(AiBotConditions.HaveLowMass(aiBrain)) and not(AiBotConditions.HaveLowPower(aiBrain)))) then
                            --Are we safe to get the upgrade here? if not then retreat
                            if bIgnoreOtherUpgradeConditions or AiBotConditions.SafeToUpgradeUnit(oACU) then
                                if GetGameTimeSeconds() - (AiBotTeam.tTeamData[iTeam][AiBotTeam.refiTimeLastIssuedACUEnhancementOrder] or -100) >= 2 or oACU[AiBotOrders.refiTimeOfLastRemovalUpgrade] or oACU[AiBotOrders.reftiLastOrders][oACU[AiBotOrders.refiOrderCount]][AiBotOrders.subrefsOrderBlueprint] == sUpgradeToGet then
                                    if bDebugMessages == true then LOG(sFunctionRef..': Safe to get upgrade so will proceed with upgrading ACU, sUpgradeToGet='..(sUpgradeToGet or 'nil')..' brain='..oACU:GetAIBrain().Nickname) end
                                    AiBotOrders.IssueTrackedEnhancement(oACU, sUpgradeToGet, false, 'ACUUpg')
                                end
                            else
                                AiBotOrders.IssueTrackedMove(oACU, tRallyPoint, 5, false, 'Runc')
                            end
                        else
                            if bDebugMessages == true then LOG(sFunctionRef..': Dont want upgrade or reclaim, will look for buildings to assist. Is table of ugprades empty='..tostring(AiBotUtilities.IsTableEmpty(tLZOrWZTeamData[AiBotMap.subreftoActiveUpgrades]))..'; Have low mass='..tostring(AiBotConditions.HaveLowMass(aiBrain))..'; Have low power='..tostring(AiBotConditions.HaveLowPower(iTeam))) end
                            local oUnitToAssist
                            if (not(AiBotConditions.HaveLowPower(iTeam)) or (aiBrain:GetEconomyStoredRatio('ENERGY') >= 1 and aiBrain[AiBotEconomy.refiGrossEnergyBaseIncome] >= 25 and not(AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefbTeamIsStallingEnergy]))) then
                                local bOnlyGetMexToAssist = AiBotConditions.HaveLowMass(aiBrain)
                                local iHighestFractionComplete = -1

                                if AiBotUtilities.IsTableEmpty(tLZOrWZTeamData[AiBotMap.subreftoActiveUpgrades]) == false then
                                    for iUpgrading, oUpgrading in  tLZOrWZTeamData[AiBotMap.subreftoActiveUpgrades] do
                                        if AiBotUnitInfo.IsUnitValid(oUpgrading) then
                                            if oUpgrading:GetWorkProgress() < 1 and oUpgrading:GetWorkProgress() > iHighestFractionComplete then
                                                if not(bOnlyGetMexToAssist) or EntityCategoryContains(AiBotUnitInfo.refCategoryMex, oUpgrading.UnitId) then
                                                    iHighestFractionComplete = oUpgrading:GetWorkProgress()
                                                    oUnitToAssist = oUpgrading
                                                end
                                            end
                                        end
                                    end
                                end
                                if not(oUnitToAssist) and not(bOnlyGetMexToAssist) then
                                    --Do we have any part-complete buildings and dont have low mass? if so assist these
                                    if AiBotUtilities.IsTableEmpty(tLZOrWZTeamData[AiBotMap.subreftoLZOrWZAlliedUnits]) == false then
                                        local tStructures = EntityCategoryFilterDown(AiBotUnitInfo.refCategoryStructure + AiBotUnitInfo.refCategoryExperimentalLevel, tLZOrWZTeamData[AiBotMap.subreftoLZOrWZAlliedUnits])
                                        if AiBotUtilities.IsTableEmpty(tStructures) == false then
                                            for iUnit, oUnit in tStructures do
                                                if AiBotUnitInfo.IsUnitValid(oUnit) and oUnit:GetFractionComplete() < 1 and oUnit:GetFractionComplete() > iHighestFractionComplete and not(oUnit[AiBotEngineer.refbDontIncludeAsPartCompleteBuildingForConstruction]) then
                                                    iHighestFractionComplete = oUnit:GetFractionComplete()
                                                    oUnitToAssist = oUnit
                                                end
                                            end
                                        end
                                    end
                                end
                                if bDebugMessages == true then LOG(sFunctionRef..': oUnitToAssist='..(oUnitToAssist.UnitId or 'nil')..(AiBotUnitInfo.GetUnitLifetimeCount(oUnitToAssist) or 'nil')..'; ACU last order reprs='..reprs(oACU[AiBotOrders.reftiLastOrders])) end
                            end
                            if oUnitToAssist then
                                if oUnitToAssist:GetFractionComplete() < 1 then
                                    AiBotOrders.IssueTrackedRepair(oACU, oUnitToAssist, false, 'ACUTR', false)
                                    if bDebugMessages == true then LOG(sFunctionRef..': Just given repair order to oUnitToAssist') end
                                else
                                    AiBotOrders.IssueTrackedGuard(oACU, oUnitToAssist, false, 'ACUGB', false)
                                    if bDebugMessages == true then LOG(sFunctionRef..': Just given guard order to oUnitToAssist') end
                                end
                            else
                                if AiBotUtilities.GetDistanceBetweenPositions(oACU:GetPosition(), tRallyPoint) <= 25 then
                                    local bFactoryInWay = AiBotConditions.IsPositionInWayOfFactory(tRallyPoint)


                                    if bDebugMessages == true then LOG(sFunctionRef..': RTB Will retreat to base unless would be blocking a factory, bFactoryInWay='..tostring(bFactoryInWay)) end
                                    if bFactoryInWay then
                                        local iAngleFromEnemyBase = AiBotUtilities.GetAngleFromAToB(tLZOrWZTeamData[AiBotMap.reftClosestEnemyBase], tRallyPoint)
                                        local tPositionToRunTo
                                        local iPlateauWanted
                                        if iPlateauOrZero == 0 then iPlateauWanted = NavUtils.GetTerrainLabel(AiBotMap.refPathingTypeHover, oACU:GetPosition())
                                        else iPlateauWanted = iPlateauOrZero end

                                        for iDist = 4, 24, 4 do
                                            tPositionToRunTo = AiBotUtilities.MoveInDirection(tRallyPoint, iAngleFromEnemyBase, iDist, true, true, AiBotMap.bIsCampaignMap)
                                            if bDebugMessages == true then LOG(sFunctionRef..': RTB Trying to find position on same plateau not blocked by factory, iDist='..iDist..'; Plateau of tPositionToRunTo='..(NavUtils.GetTerrainLabel(AiBotMap.refPathingTypeHover, tPositionToRunTo) or 'nil')..'; iPlateauWanted='..(iPlateauWanted or 'nil')..'; Is it in way of  factory='..tostring(AiBotConditions.IsPositionInWayOfFactory(tPositionToRunTo) or false)) end
                                            if tPositionToRunTo and NavUtils.GetTerrainLabel(AiBotMap.refPathingTypeHover, tPositionToRunTo) == iPlateauWanted then
                                                bFactoryInWay = AiBotConditions.IsPositionInWayOfFactory(tPositionToRunTo)
                                                if not(bFactoryInWay) then break end
                                            end
                                        end
                                        if bDebugMessages == true then LOG(sFunctionRef..': RTB bFactoryInWay after trying to find alternative location='..tostring(bFactoryInWay)) end
                                        if not(bFactoryInWay) then tRallyPoint = {tPositionToRunTo[1], tPositionToRunTo[2], tPositionToRunTo[3]} end
                                    end
                                end
                                AiBotOrders.IssueTrackedMove(oACU, tRallyPoint, 5, false, 'Rund')
                            end

                        end
                    end
                end
            end
        end
    end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
end

function GetBestTeleSnipeUnitTarget(oACU, iTeam)
    --Make sure we have a relatively recent target list since we are proceeding to teleport
    local sFunctionRef = 'GetBestTeleSnipeUnitTarget'
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)

    AiBotTeam.RefreshPotentialTeleSnipeTargets(iTeam, 1)
    local oTargetWanted
    if bDebugMessages == true then LOG(sFunctionRef..': Is table of targets empty after forced refresh every 1s='..tostring(AiBotUtilities.IsTableEmpty(AiBotTeam.tTeamData[iTeam][AiBotTeam.reftoPotentialTeleSnipeTargets]))) end
    if AiBotUtilities.IsTableEmpty(AiBotTeam.tTeamData[iTeam][AiBotTeam.reftoPotentialTeleSnipeTargets]) == false then
        local iHighestValueTarget = 0
        local iCurTargetValue
        for iUnit, oUnit in AiBotTeam.tTeamData[iTeam][AiBotTeam.reftoPotentialTeleSnipeTargets] do
            if AiBotUnitInfo.IsUnitValid(oUnit) then
                if EntityCategoryContains(categories.COMMAND, oUnit.UnitId) then
                    iCurTargetValue = 20000 --will only have an ACU if in assassination mode
                    if table.getn(AiBotTeam.tTeamData[iTeam][AiBotTeam.reftEnemyACUs]) == 1 and AiBotTeam.tTeamData[oUnit:GetAIBrain().AiBotTeam][AiBotTeam.refbAssassinationOrSimilar] and AiBotUnitInfo.GetCombatThreatRating({AiBotTeam.tTeamData[iTeam][AiBotTeam.reftEnemyACUs][1]}, true) <= 4000 then
                        iCurTargetValue = 250000 --i.e. if we kill the ACU then it is better than killing a game ender (although will reduce to less than a gameender if it has high health)
                    end
                    local iUnitHealth = oUnit:GetHealth()
                    local iCurShield, iMaxShield = AiBotUnitInfo.GetCurrentAndMaximumShield(oUnit, true)
                    iUnitHealth = iUnitHealth + iCurShield
                    if iUnitHealth >= 15000 then
                        iCurTargetValue = 180000 --likely better to target a gameender than ACU if acu is high health
                        iCurTargetValue = iCurTargetValue - math.min(iCurTargetValue * 0.6, math.max((iUnitHealth - 15000) * 0.3))
                    end
                else
                    iCurTargetValue = (oUnit[AiBotUnitInfo.refiUnitMassCost] or AiBotUnitInfo.GetUnitMassCost(oUnit)) * oUnit:GetFractionComplete()
                end
                if bDebugMessages == true then LOG(sFunctionRef..': Considering unit '..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..'; iCurTargetValue before shield adjust='..iCurTargetValue) end
                if iCurTargetValue > iHighestValueTarget then
                    --Reduce value by shields in the zone
                    local tUnitLZData, tUnitLZTeamData = AiBotMap.GetLandOrWaterZoneData(oUnit:GetPosition(), true, iTeam)
                    iCurTargetValue = iCurTargetValue - math.min(iCurTargetValue * 0.3, (tUnitLZTeamData[AiBotMap.subrefThreatEnemyShield] or 0))
                    if iCurTargetValue > iHighestValueTarget then
                        iHighestValueTarget = iCurTargetValue
                        oTargetWanted = oUnit
                        if bDebugMessages == true then LOG(sFunctionRef..': Recording unit as oTargetWanted subject to any better ones, iHighestValueTarget='..iHighestValueTarget) end
                    end
                end
            end
        end
    end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
    return oTargetWanted
end

function GetBestLocationForTeleSnipeTarget(oACU, oSnipeTarget, iTeam, bJustCheckIfLocationWithLowPDThreat)
    --oACU - if nil then will assume has a range of 30
    --bJustCheckIfLocationWithLowPDThreat - if this is true, then returns true if think there is a low PD threat location to teleport to


    local sFunctionRef = 'GetBestLocationForTeleSnipeTarget'
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)

    --We ahve a valid oSnipeTarget for oACU to teleport to and try and kill, now we want to refine the teleport destination, e.g. to avoid volatile units and PD
    local tBestTarget
    local bConsiderAvoidingVolatileUnits = true
    local iMinDistanceAway = 0
    local iDistFromAOEWanted = 2
    local iMaxDistFromTarget = (oACU[AiBotUnitInfo.refiDFRange] or 30) - 2
    if EntityCategoryContains(categories.MOBILE - AiBotUnitInfo.refCategoryScathis, oSnipeTarget.UnitId) then iMaxDistFromTarget = iMaxDistFromTarget - 8 end

    local iTargetPlateau, iTargetLandZone = AiBotMap.GetClosestPlateauOrZeroAndZoneToPosition(oSnipeTarget:GetPosition())

    if bDebugMessages == true then LOG(sFunctionRef..': Near start of code, oSnipeTarget='..oSnipeTarget.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oSnipeTarget)..' owned by brain '..oSnipeTarget:GetAIBrain().Nickname..'; Position='..repru(oSnipeTarget:GetPosition())..'; iTargetPlateau='..(iTargetPlateau or 'nil')..'; iTargetLandZone='..(iTargetLandZone or 'nil')) end
    if iTargetPlateau > 0 and (iTargetLandZone or 0) > 0 then
        local tTargetLZData = AiBotMap.tAllPlateaus[iTargetPlateau][AiBotMap.subrefPlateauLandZones][iTargetLandZone]
        local tTargetLZTeamData = tTargetLZData[AiBotMap.subrefLZTeamData][iTeam]

        local tNearbyPD = {}
        local tCurZonePD = EntityCategoryFilterDown(AiBotUnitInfo.refCategoryPD, tTargetLZTeamData[AiBotMap.subrefTEnemyUnits])
        if AiBotUtilities.IsTableEmpty(tCurZonePD) == false then
            for iUnit, oUnit in tCurZonePD do
                if AiBotUnitInfo.IsUnitValid(oUnit) and oUnit:GetFractionComplete() == 1 then
                    table.insert(tNearbyPD, oUnit)
                end
            end
        end
        if AiBotUtilities.IsTableEmpty(tTargetLZData[AiBotMap.subrefLZAdjacentLandZones]) == false then
            for _, iAdjLZ in tTargetLZData[AiBotMap.subrefLZAdjacentLandZones] do
                local tAdjLZData = AiBotMap.tAllPlateaus[iTargetPlateau][AiBotMap.subrefPlateauLandZones][iAdjLZ]
                local tAdjLZTeamData = tAdjLZData[AiBotMap.subrefLZTeamData][iTeam]
                if AiBotUtilities.IsTableEmpty(tAdjLZTeamData[AiBotMap.subrefTEnemyUnits]) == false then
                    local tAdjPD = EntityCategoryFilterDown(AiBotUnitInfo.refCategoryPD, tAdjLZTeamData[AiBotMap.subrefTEnemyUnits])
                    if AiBotUtilities.IsTableEmpty(tAdjPD) == false then
                        for iPD, oPD in tAdjPD do
                            if AiBotUnitInfo.IsUnitValid(oPD) then
                                table.insert(tNearbyPD, oPD)
                            end
                        end
                    end
                end
            end
        end


        local tiApproxPDDPSByTech = {[1]=167,[2]=132,[3]=273, [4]=1000}
        local iCurDistToTarget
        function EstimatePDDPSNearLocation(tLocation, iDistanceThreshold)
            local iPDApproxDPS = 0
            if AiBotUtilities.IsTableEmpty(tNearbyPD) == false then
                for iUnit, oUnit in tNearbyPD do
                    iCurDistToTarget = AiBotUtilities.GetDistanceBetweenPositions(oUnit:GetPosition(), tLocation)
                    if iCurDistToTarget - oUnit[AiBotUnitInfo.refiDFRange] <= (iDistanceThreshold or 2) then
                        iPDApproxDPS = iPDApproxDPS + tiApproxPDDPSByTech[AiBotUnitInfo.GetUnitTechLevel(oUnit)]
                    end
                end
            end
            return iPDApproxDPS
        end

        --Get volatile units and PD in this and adjacent land zones so can factor in if alternative locations are more dangerous
        local tVolatileUnits = {}
        if not(bJustCheckIfLocationWithLowPDThreat) then
            local tPotentialVolatileUnits = EntityCategoryFilterDown(AiBotUnitInfo.refCategoryVolatile * categories.STRUCTURE, tTargetLZTeamData[AiBotMap.subrefTEnemyUnits])
            if AiBotUtilities.IsTableEmpty(tPotentialVolatileUnits) == false then
                for iUnit, oUnit in tPotentialVolatileUnits do
                    if AiBotUnitInfo.IsUnitValid(oUnit) and oUnit:GetFractionComplete() == 1 then
                        local iDeathDamage, iDeathAOE, tDeathWeapon = AiBotUnitInfo.GetDeathWeaponDamageAOEAndTable(oUnit)
                        if bDebugMessages == true then LOG(sFunctionRef..': Considering volatile units in zone, oUnit='..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..'; iDeathDamage='..iDeathDamage) end
                        if iDeathDamage >= 1250 then
                            table.insert(tVolatileUnits, oUnit)
                        end
                    end
                end
            end
        end

        function EstimateVolatileDamageNearLocation(tPotentialLocation, iOptionalAOEAdjust)
            local iVolatileDamage = 0
            if AiBotUtilities.IsTableEmpty(tVolatileUnits) == false then
                for iUnit, oUnit in tVolatileUnits do
                    iCurDistToTarget = AiBotUtilities.GetDistanceBetweenPositions(oUnit:GetPosition(), tPotentialLocation)
                    local iDeathDamage, iDeathAOE, tDeathWeapon = AiBotUnitInfo.GetDeathWeaponDamageAOEAndTable(oUnit)
                    if bDebugMessages == true then LOG(sFunctionRef..': iCurDistToTarget='..iCurDistToTarget..'; iDeathDamage='..(iDeathDamage or 'nil')..'; iDeathAOE='..(iDeathAOE or 'nil')..'; iOptionalAOEAdjust='..(iOptionalAOEAdjust or 'nil')) end
                    if iCurDistToTarget <= 1 + iDeathAOE + (iOptionalAOEAdjust or 0) then
                        iVolatileDamage = iVolatileDamage + iDeathDamage
                    end
                end
            end
            return iVolatileDamage
        end
        local iBaseTargetPDDPS = EstimatePDDPSNearLocation(oSnipeTarget:GetPosition(), 6)
        local iBaseTargetVolatileDamage = 0

        local bKeepToCampaignPlayableArea = AiBotMap.bIsCampaignMap

        function IsPotentialAlternativeLocationTooDangerous(tPotentialLocation, iDistThreshold, iPDDPSThreshold, iOptionalVolatileTarget)
            --factors in tVolatileUnits, tPD, and general zone stats re dangerous units if the zone is different to the target unit (air to ground and mobile DF) to decide whether it is safe to teleport to a location
            local bDangerous = true
            local iPDDPS = EstimatePDDPSNearLocation(tPotentialLocation, iDistThreshold)
            if iPDDPS <= iPDDPSThreshold then
                if not(iOptionalVolatileTarget) then
                    bDangerous = false
                else
                    if EstimateVolatileDamageNearLocation(tPotentialLocation, iDistThreshold) <= iOptionalVolatileTarget then
                        bDangerous = false
                    end
                end
            end
            return bDangerous, iPDDPS
        end

        function UpdateBestTargetIfSafeLocationNearTargetUnit(oTargetUnit, iDistanceAwayMin, iDistanceAwayMax, iMaxPDDPS, iOptionalMaxVolatileDamage)
            --Try 8 different points around target to see if any of them are safer
            local iAngleInterval = 360 / 8
            local iDistFromSnipeTarget
            local bTargetWithinRange
            local iLeewayUntilOutOfRange
            local iPDDistThreshold
            local iDistanceInterval = iDistanceAwayMax - iDistanceAwayMin
            local iPDDPSThreshold = iMaxPDDPS
            if iDistanceInterval >= 4 then iDistanceInterval = 4 end
            if bDebugMessages == true then LOG(sFunctionRef..': Searching for safer locations to target oTargetUnit '..oTargetUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oTargetUnit)..'; iDistanceAwayMin='..iDistanceAwayMin..'; iDistanceAwayMax='..iDistanceAwayMax..'; iOptionalMaxVolatileDamage='..(iOptionalMaxVolatileDamage or 'nil')) end
            for iDistanceAway = iDistanceAwayMin, iDistanceAwayMax, iDistanceInterval do
                for iCurAngle = iAngleInterval, 360, iAngleInterval do
                    local tPotentialTarget = AiBotUtilities.MoveInDirection(oTargetUnit:GetPosition(), iAngleInterval, iDistanceAway, true, false, bKeepToCampaignPlayableArea)
                    --Is this location actually within range of the snipe target?
                    iDistFromSnipeTarget = AiBotUtilities.GetDistanceBetweenPositions(tPotentialTarget, oSnipeTarget:GetPosition())
                    if bDebugMessages == true then LOG(sFunctionRef..': Considering tPotentialTarget='..repru(tPotentialTarget)..'; iDistanceAway='..iDistanceAway..'; iCurAngle='..iCurAngle..'; iDistFromSnipeTarget='..iDistFromSnipeTarget..'; iMaxDistFromTarget='..iMaxDistFromTarget) end
                    if iDistFromSnipeTarget < iMaxDistFromTarget then
                        bTargetWithinRange = false
                        iLeewayUntilOutOfRange = (oACU[AiBotUnitInfo.refiDFRange] or 30) - iDistFromSnipeTarget
                        iPDDistThreshold = 2
                        local tNearbyUnits = GetUnitsInRect(tPotentialTarget[1] - 1, tPotentialTarget[3] - 1, tPotentialTarget[1] + 1, tPotentialTarget[3] + 1)
                        if AiBotUtilities.IsTableEmpty(tNearbyUnits) == false then
                            local tNearbyStructures = EntityCategoryFilterDown(categories.STRUCTURE, tNearbyUnits)
                            if AiBotUtilities.IsTableEmpty(tNearbyStructures) == false then
                                for iUnit, oUnit in tNearbyStructures do
                                    iPDDistThreshold = math.max(iPDDistThreshold, AiBotUnitInfo.GetBuildingSize(oUnit.UnitId))
                                end
                            end
                        end

                        if iPDDistThreshold < iLeewayUntilOutOfRange then
                            bTargetWithinRange = true
                        end
                        if bDebugMessages == true then LOG(sFunctionRef..': iPDDistThreshold='..iPDDistThreshold..'; iLeewayUntilOutOfRange='..iLeewayUntilOutOfRange..'; bTargetWithinRange='..tostring(bTargetWithinRange)) end
                        if bTargetWithinRange then
                            --Is PD threat from this location less than before?
                            local bAlternativeLocationDangerous, iPotentialPDDPS = IsPotentialAlternativeLocationTooDangerous(tPotentialTarget, iPDDistThreshold, iPDDPSThreshold, iOptionalMaxVolatileDamage)
                            if not(bAlternativeLocationDangerous) then
                                if bDebugMessages == true then LOG(sFunctionRef..': Have a new best target') end
                                tBestTarget = {tPotentialTarget[1], tPotentialTarget[2], tPotentialTarget[3]}
                                if iPotentialPDDPS <= 400 then
                                    break
                                else
                                    --Keep looking in case are locations with even less PD threat
                                    iPDDPSThreshold = math.min(iPotentialPDDPS, iPDDPSThreshold * 0.8)
                                end
                            else
                                if bDebugMessages == true then LOG(sFunctionRef..': Target not safe enough') end
                            end
                        end
                    end
                end
                if iDistanceInterval <= 0 or (tBestTarget and iPDDPSThreshold <= 400) then break end
            end
        end

        local bConsiderVolatileHealth = false
        if AiBotTeam.tTeamData[iTeam][AiBotTeam. refbAssassinationOrSimilar] then bConsiderVolatileHealth = true end
        if bDebugMessages == true then LOG(sFunctionRef..': iBaseTargetPDDPS='..iBaseTargetPDDPS) end
        if iBaseTargetPDDPS >= 700 then
            --Want to search for locations with lower PD threat, if there are any
            local iTargetBuildingSize = AiBotUnitInfo.GetBuildingSize(oSnipeTarget.UnitId)
            if bDebugMessages == true then LOG(sFunctionRef..': Will look for targets that avoid PD, tBestTarget before change='..repru(tBestTarget)..'; iTargetBuildingSize='..iTargetBuildingSize..'; ACU DF range='..(oACU[AiBotUnitInfo.refiDFRange] or 30)) end
            local iMaxDPSWanted
            if bJustCheckIfLocationWithLowPDThreat then iMaxDPSWanted = 690 --Roughly 4 T1 pd
            else
                iMaxDPSWanted = iBaseTargetPDDPS * 0.8
            end
            local iVolatileHealthLevel = nil
            if bConsiderVolatileHealth then iVolatileHealthLevel = 9000 end
            UpdateBestTargetIfSafeLocationNearTargetUnit(oSnipeTarget, iTargetBuildingSize, math.min(iMaxDistFromTarget, iTargetBuildingSize + 4 * 4, (oACU[AiBotUnitInfo.refiDFRange] or 30) - 6), iMaxDPSWanted, iVolatileHealthLevel)
            if bDebugMessages == true then LOG(sFunctionRef..': Attempted to change target to avoid PD, tBestTarget after change='..repru(tBestTarget)) end
            if bJustCheckIfLocationWithLowPDThreat and tBestTarget then
                AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
                return true
            end
        else
            if bJustCheckIfLocationWithLowPDThreat then
                AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
                return true
            else
                --avoid aoe on the target itself unless iti s a game ender with heavy shielding, or it doesnt matter if we die
                if bConsiderVolatileHealth and not(EntityCategoryContains(categories.MOBILE - AiBotUnitInfo.refCategoryScathis, oSnipeTarget.UnitId)) then --(dont want to mvoe away from mobile units such as ACUs in case they then move out of our range; exceptino for scathis due to how slow it is and itneeding to pack up)
                    if not(EntityCategoryContains(AiBotUnitInfo.refCategoryGameEnder, oSnipeTarget.UnitId)) or (tTargetLZTeamData[AiBotMap.subrefThreatEnemyShield] or 0) <= 5000 or AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiActiveAiBotBrainCount] == 1 then
                        --First move away if targeting a highly volatile unit that could kill us, and we outrange the volatile radius (e.g. paragon and yolona)
                        local iBaseTargetVolatileDamage, iDeathAOE, tDeathWeapon = AiBotUnitInfo.GetDeathWeaponDamageAOEAndTable(oSnipeTarget)
                        if tDeathWeapon and iBaseTargetVolatileDamage >= 1250 then
                            if iDeathAOE + iDistFromAOEWanted < (oACU[AiBotUnitInfo.refiDFRange] or 30) then --Energy storage is 1k damage; also no point avoiding if outside our range

                                iMinDistanceAway = iDeathAOE + iDistFromAOEWanted
                                if bDebugMessages == true then LOG(sFunctionRef..': Snipe target has death aoe we want to avoid, iMinDistanceAway='..iMinDistanceAway..'; iDeathAOE='..iDeathAOE..'; iBaseTargetVolatileDamage='..iBaseTargetVolatileDamage) end
                            else
                                bConsiderAvoidingVolatileUnits = false --No point avoiding things like t3 pgens if the target itself will kill us when it dies
                                if bDebugMessages == true then LOG(sFunctionRef..': We cant dodge target volatile explosion so will not bother trying to dodge other volatile units') end
                            end
                        end
                    end
                end


                if bConsiderAvoidingVolatileUnits then
                    if iMinDistanceAway > 0 then
                        --Snipe target is volatile, so try and avoid
                        if bDebugMessages == true then LOG(sFunctionRef..': Snipe target is volatile so will try and avoid') end
                        UpdateBestTargetIfSafeLocationNearTargetUnit(oSnipeTarget, iMinDistanceAway, math.min(iMinDistanceAway + 4, iMaxDistFromTarget), iBaseTargetPDDPS * 0.25, iBaseTargetVolatileDamage * 0.5)

                    else
                        --We arent trying to avoid explosion from the target itself so consider avoiding explosion from nearby T3 pgens
                        local iTargetBuildingSize = AiBotUnitInfo.GetBuildingSize(oSnipeTarget.UnitId)
                        iBaseTargetVolatileDamage = EstimateVolatileDamageNearLocation(oSnipeTarget:GetPosition(), iTargetBuildingSize)
                        if bDebugMessages == true then LOG(sFunctionRef..': Considering if we want to try and avoid nearby volatile units, iBaseTargetVolatileDamage='..iBaseTargetVolatileDamage..'; iTargetBuildingSize='..iTargetBuildingSize) end
                        if iBaseTargetVolatileDamage > 0 then
                            if bDebugMessages == true then LOG(sFunctionRef..': Will try searching for safer locations') end
                            UpdateBestTargetIfSafeLocationNearTargetUnit(oSnipeTarget, iTargetBuildingSize, math.min(iMaxDistFromTarget, iTargetBuildingSize + 4 * 2, (oACU[AiBotUnitInfo.refiDFRange] or 30) - 6), iBaseTargetPDDPS * 0.25, 2000)
                        end
                    end
                end
            end
        end
    end
    if bDebugMessages == true then LOG(sFunctionRef..': Near end of code, tBestTarget before applying default if it is nil='..repru(tBestTarget)..'; will consider adjusting if close to mobile target, bJustCheckIfLocationWithLowPDThreat='..tostring(bJustCheckIfLocationWithLowPDThreat or false)) end
    if not(tBestTarget) then
        if bDebugMessages == true then LOG(sFunctionRef..': No safe targets, will just try teleporting to the snipe target') end
        tBestTarget = oSnipeTarget:GetPosition()
    end
    if bDebugMessages == true then LOG(sFunctionRef..': dist to snipe target='..AiBotUtilities.GetDistanceBetweenPositions(oSnipeTarget:GetPosition(), tBestTarget)..'; Does ACU have laser upgrade='..tostring(oACU:HasEnhancement('MicrowaveLaserGenerator'))..'; oSnipeTarget='..(oSnipeTarget.UnitId or 'nil')..(AiBotUnitInfo.GetUnitLifetimeCount(oSnipeTarget) or 'nil')) end
    --Issue - laser doesnt fire if are too close (which can happen if try to teleport right ontop of the enemy ACU)
    if EntityCategoryContains(categories.MOBILE, oSnipeTarget.UnitId) and oACU.HasEnhancement and oACU:HasEnhancement('MicrowaveLaserGenerator') and AiBotUtilities.GetDistanceBetweenPositions(tBestTarget, oSnipeTarget:GetPosition()) <= 4 then
        local iLandLabelWanted = NavUtils.GetTerrainLabel(AiBotMap.refPathingTypeLand, oSnipeTarget:GetPosition())
        local bHaveAltTarget = false
        if (iLandLabelWanted or 0) > 0 then
            for iDistFromTarget = 4, 16, 2 do
                for iAngleFromTarget = 0, 360, 15 do
                    local tPossibleTarget = AiBotUtilities.MoveInDirection(oSnipeTarget:GetPosition(), iAngleFromTarget, iDistFromTarget, true, true, true)
                    if tPossibleTarget and NavUtils.GetTerrainLabel(AiBotMap.refPathingTypeLand, tPossibleTarget) == iLandLabelWanted then
                        bHaveAltTarget = true
                        tBestTarget = {tPossibleTarget[1], tPossibleTarget[2], tPossibleTarget[3]}
                        break
                    end
                end
                if bHaveAltTarget then break end
            end

        end
        if bDebugMessages == true then LOG(sFunctionRef..': Targeting mobile unit, bHaveAltTarget='..tostring(bHaveAltTarget)..'; tBestTarget='..repru(tBestTarget)) end
    end

    if bDebugMessages == true then LOG(sFunctionRef..': End of code, bJustCheckIfLocationWithLowPDThreat='..tostring(bJustCheckIfLocationWithLowPDThreat or false)..'; if this is true then will return false; tBestTarget='..repru(tBestTarget)) end

    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
    if bJustCheckIfLocationWithLowPDThreat then return false
    else return tBestTarget
    end


end

function HaveTelesnipeAction(oACU, tLZOrWZData, tLZOrWZTeamData, aiBrain, iTeam, iPlateauOrZero, iLandOrWaterZone)
    local sFunctionRef = 'HaveTelesnipeAction'
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)

    local bGivenACUOrder = false

    if bDebugMessages == true then LOG(sFunctionRef..': Start of code for brain '..aiBrain.Nickname..'; Does ACU have special micro active='..tostring(oACU[AiBotUnitInfo.refbSpecialMicroActive] or false)) end
    if not(oACU[AiBotUnitInfo.refbSpecialMicroActive]) then

        --First check if we want to get upgrades to enable a tele-snipe
        local sUpgradeWanted
        if not(oACU[refbACUHasTeleport]) and EntityCategoryContains(categories.CYBRAN + categories.SERAPHIM, oACU.UnitId) then
            if AiBotTeam.tTeamData[iTeam][AiBotTeam.refbDefendAgainstArti] and AiBotTeam.tTeamData[iTeam][AiBotTeam.refiEnemyT3ArtiCount] + AiBotTeam.tTeamData[iTeam][AiBotTeam.refiEnemyNovaxCount] * 0.5 >= 1 and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossEnergy] >= 600 + 450 * AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiActiveAiBotBrainCount] then
                local bConsiderSniping = false
                function GetArtiEquivValue(oUnit)
                    local iArtiValue = 0
                    if EntityCategoryContains(AiBotUnitInfo.refCategoryGameEnder - AiBotUnitInfo.refCategorySML, oUnit.UnitId) then
                        iArtiValue = 3
                    elseif EntityCategoryContains(AiBotUnitInfo.refCategorySML * categories.EXPERIMENTAL, oUnit.UnitId) then
                        iArtiValue = 2
                    elseif EntityCategoryContains(AiBotUnitInfo.refCategoryNovaxCentre + AiBotUnitInfo.refCategorySatellite, oUnit.UnitId) then
                        iArtiValue = 0.6
                    else
                        iArtiValue = 1
                    end
                    return iArtiValue * oUnit:GetFractionComplete()
                end
                local iEnemyArtiCount = 0
                if AiBotUtilities.IsTableEmpty(AiBotTeam.tTeamData[iTeam][AiBotTeam.reftEnemyArtiAndExpStructure]) == false then
                    for iUnit, oUnit in AiBotTeam.tTeamData[iTeam][AiBotTeam.reftEnemyArtiAndExpStructure] do
                        if AiBotUnitInfo.IsUnitValid(oUnit) and oUnit:GetFractionComplete() >= 0.85 then
                            iEnemyArtiCount = iEnemyArtiCount + GetArtiEquivValue(oUnit)
                        end
                    end
                end
                if AiBotUtilities.IsTableEmpty(AiBotTeam.tTeamData[iTeam][AiBotTeam.reftEnemyMobileSatellites]) == false then
                    local iNovaxCount = 0
                    for iUnit, oUnit in AiBotTeam.tTeamData[iTeam][AiBotTeam.reftEnemyMobileSatellites] do
                        iNovaxCount = iNovaxCount + GetArtiEquivValue(oUnit)
                    end
                    iEnemyArtiCount = math.max(iEnemyArtiCount, iNovaxCount)
                end
                if bDebugMessages == true then LOG(sFunctionRef..': Considering for ACU '..oACU.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oACU)..' owned by brain '..oACU:GetAIBrain().Nickname..'; iEnemyArtiCount='..iEnemyArtiCount) end
                if EntityCategoryContains(categories.CYBRAN, oACU.UnitId) or iEnemyArtiCount > 1 then
                    local bWeHaveRAS = false
                    if oACU:HasEnhancement('ResourceAllocation') or oACU:HasEnhancement('ResourceAllocationAdvanced') then bWeHaveRAS = true end

                    if not(AiBotTeam.tTeamData[iTeam][AiBotTeam.refbAssassinationOrSimilar]) and not(bWeHaveRAS) and (iEnemyArtiCount >= 2 or (iEnemyArtiCount >= 0.8 and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossEnergy] >= 2250)) then
                        if bDebugMessages == true then LOG(sFunctionRef..': Arent in assassination mode so will consider sniping') end
                        bConsiderSniping = true
                    elseif not(bWeHaveRAS) and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiActiveAiBotBrainCount] > 1 and (iEnemyArtiCount >= 2 or (AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiActiveAiBotBrainCount] > 2 and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossEnergy] >= 2250 and (iEnemyArtiCount >= 0.8 or AiBotTeam.tTeamData[iTeam][AiBotTeam.refiMexCountByTech][3] < AiBotConditions.GetHighestOtherTeamT3MexCount(iTeam)))) and (AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiActiveAiBotBrainCount] > 3 or iEnemyArtiCount >= 2 or AiBotTeam.tTeamData[iTeam][AiBotTeam.refiMexCountByTech][3] * 0.8 < AiBotConditions.GetHighestOtherTeamT3MexCount(iTeam)) then
                        bConsiderSniping = true
                    else
                        --Assassination, and down to last ACU, only go for telesnipe as a last resort
                        if iEnemyArtiCount >= 3 then
                            local iFriendlyArtiCount = 0
                            for iBrain, oBrain in AiBotTeam.tTeamData[iTeam][AiBotTeam.subreftoFriendlyActiveAiBotBrains] do
                                local tFriendlyExperimentals = oBrain:GetListOfUnits(AiBotUnitInfo.refCategoryGameEnder + AiBotUnitInfo.refCategoryNovaxCentre + AiBotUnitInfo.refCategoryFixedT3Arti, false, false)
                                for iUnit, oUnit in tFriendlyExperimentals do
                                    if oUnit:GetFractionComplete() >= 0.4 then
                                        iFriendlyArtiCount = iFriendlyArtiCount + GetArtiEquivValue(oUnit)
                                    end
                                end
                            end
                            if iFriendlyArtiCount < 2 and iEnemyArtiCount - iFriendlyArtiCount >= 3 and (iEnemyArtiCount >= 4 or AiBotTeam.tTeamData[iTeam][AiBotTeam.refiMexCountByTech][3] < AiBotConditions.GetHighestOtherTeamT3MexCount(iTeam)) then
                                bConsiderSniping = true
                            end
                        end
                    end
                end

                if bConsiderSniping then
                    --Only get teleport on seraphim if we have no cybran ACU and enemy has a friendly arti count; dont get teleport on either if we are already getting teleport (or have it) on another ACU
                    for iBrain, oBrain in AiBotTeam.tTeamData[iTeam][AiBotTeam.subreftoFriendlyActiveAiBotBrains] do
                        local tFriendlyACUs = oBrain:GetListOfUnits(categories.COMMAND * categories.CYBRAN + categories.COMMAND * categories.SERAPHIM, true, false)
                        if AiBotUtilities.IsTableEmpty(tFriendlyACUs) == false then
                            for iFriendlyACU, oFriendlyACU in tFriendlyACUs do
                                if not(oFriendlyACU == oACU) then
                                    if bDebugMessages == true then LOG(sFunctionRef..': Checking if other ACUs are planning on getting teleport, ACU owned by brain '..oBrain.Nickname..': oFriendlyACU[refbPlanningToGetTeleport]='..tostring(oFriendlyACU[refbPlanningToGetTeleport] or false)..'; oFriendlyACU[refbACUHasTeleport]='..tostring(oFriendlyACU[refbACUHasTeleport])) end
                                    if oFriendlyACU[refbPlanningToGetTeleport] or oFriendlyACU[refbACUHasTeleport] then
                                        bConsiderSniping = false
                                        break
                                    elseif EntityCategoryContains(categories.CYBRAN, oFriendlyACU.UnitId) and EntityCategoryContains(categories.SERAPHIM, oACU.UnitId) then
                                        bConsiderSniping = false
                                        break
                                    end
                                end
                            end
                        end
                        if not(bConsiderSniping) then break end
                    end
                end

                if bDebugMessages == true then LOG(sFunctionRef..': bConsiderSniping='..tostring(bConsiderSniping)) end
                if bConsiderSniping then
                    --Do we have any viable targets?
                    AiBotTeam.RefreshPotentialTeleSnipeTargets(iTeam)
                    if bDebugMessages == true then LOG(sFunctionRef..': Deciding whether to get teleport upgrade, Is table of potentail snipe targets empty='..tostring(AiBotUtilities.IsTableEmpty(AiBotTeam.tTeamData[iTeam][AiBotTeam.reftoPotentialTeleSnipeTargets]))) end
                    if AiBotUtilities.IsTableEmpty(AiBotTeam.tTeamData[iTeam][AiBotTeam.reftoPotentialTeleSnipeTargets]) == false then
                        sUpgradeWanted = GetACUUpgradeWanted(oACU, true, tLZOrWZData, tLZOrWZTeamData, iPlateauOrZero)
                    end
                end
            end
        end
        if bDebugMessages == true then LOG(sFunctionRef..': sUpgradeWanted='..(sUpgradeWanted or 'nil')) end
        if sUpgradeWanted then
            oACU[refbPlanningToGetTeleport] = true
            bGivenACUOrder = true
            --Are we under a fixed shield or underwater? If not, and we have a fixed shield that we own, then move to it

            local oClosestFixedShield
            local iClosestFixedShield = 100000
            local bUnderShieldOrWater = false
            local iCurDist, iCurShield, iMaxShield
            function ConsiderShield(oShield)
                if AiBotUnitInfo.IsUnitValid(oShield) and oShield:GetFractionComplete() == 1 then
                    iCurShield, iMaxShield = AiBotUnitInfo.GetCurrentAndMaximumShield(oShield, true)
                    if iCurShield > 0 and iCurShield > iMaxShield * 0.5 and iMaxShield >= 12000 and NavUtils.GetLabel(AiBotMap.refPathingTypeHover, oShield:GetPosition()) == iPlateauOrZero then
                        iCurDist = AiBotUtilities.GetDistanceBetweenPositions(oShield:GetPosition(), oACU:GetPosition())
                        if iCurDist < iClosestFixedShield then
                            iClosestFixedShield = iCurDist
                            oClosestFixedShield = oShield
                        end
                    end
                end
            end
            if AiBotUnitInfo.IsUnitUnderwater(oACU) then bUnderShieldOrWater = true

            elseif AiBotUtilities.IsTableEmpty(tLZOrWZTeamData[AiBotMap.subreftoLZOrWZAlliedUnits]) == false then
                local tFixedShieldsInLZ = EntityCategoryFilterDown(AiBotUnitInfo.refCategoryFixedShield, tLZOrWZTeamData[AiBotMap.subreftoLZOrWZAlliedUnits])
                if AiBotUtilities.IsTableEmpty(tFixedShieldsInLZ) == false then
                    for iShield, oShield in tFixedShieldsInLZ do
                        ConsiderShield(oShield)
                    end
                end
            end
            if not(oClosestFixedShield) then
                local tNearbyShields = aiBrain:GetUnitsAroundPoint(AiBotUnitInfo.refCategoryFixedShield, oACU:GetPosition(), 120, 'Ally')
                if AiBotUtilities.IsTableEmpty(tNearbyShields) == false then
                    for iShield, oShield in tNearbyShields do
                        ConsiderShield(oShield)
                    end
                end
            end
            if oClosestFixedShield and iClosestFixedShield + 1 < (oClosestFixedShield:GetBlueprint().Defense.Shield.ShieldSize or 0) * 0.5 then
                bUnderShieldOrWater = true
            end

            if bUnderShieldOrWater then
                --Upgrade to telesnipe
                if bDebugMessages == true then LOG(sFunctionRef..': Will get telesnipe upgrade as under shield') end
                AiBotOrders.IssueTrackedEnhancement(oACU, sUpgradeWanted, false, 'ACUTeleU')
            elseif oClosestFixedShield then
                --Move to the closest shield
                AiBotOrders.IssueTrackedMove(oACU, oClosestFixedShield:GetPosition(), 5, false, 'ACUTelSh', false)
            else
                if not(tLZOrWZTeamData[AiBotMap.subrefLZbCoreBase]) then
                    if bDebugMessages == true then LGO(sFunctionRef..': Will return ACU to core base unless want shield instead') end
                    if not(ConsiderRunningToNearestShield(oACU, tLZOrWZData, tLZOrWZTeamData, iTeam, iPlateauOrZero, iLandOrWaterZone)) then
                        ReturnACUToCoreBase(oACU, tLZOrWZData, tLZOrWZTeamData, aiBrain, iTeam, iPlateauOrZero, iLandOrWaterZone)
                        if bDebugMessages == true then LOG(sFunctionRef..': Going to core base') end
                    end
                else

                    --Upgrade to telesnipe
                    if bDebugMessages == true then LOG(sFunctionRef..': Will get telesnipe upgrade as in core base') end
                    AiBotOrders.IssueTrackedEnhancement(oACU, sUpgradeWanted, false, 'ACUTeleU')
                end
            end

        else
            if bDebugMessages == true then LOG(sFunctionRef..': Dont want to get upgrade, does ACU already have teleport='..tostring(oACU[refbACUHasTeleport] or false)) end
            if oACU[refbACUHasTeleport] then
                --Are we not in core base? Teleport to core base
                if bDebugMessages == true then LOG(sFunctionRef..': Are we in a core base='..tostring(tLZOrWZTeamData[AiBotMap.subrefLZbCoreBase])) end
                if not(tLZOrWZTeamData[AiBotMap.subrefLZbCoreBase]) then
                    if bDebugMessages == true then LOG(sFunctionRef..': Will teleport back to base') end
                    bGivenACUOrder = true
                    if AiBotConditions.BaseIsSafeToRetreatTo(tLZOrWZTeamData[AiBotMap.reftClosestFriendlyBase], iTeam) or AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiActiveAiBotBrainCount] <= 1 then
                        AiBotOrders.IssueTrackedTeleport(oACU, tLZOrWZTeamData[AiBotMap.reftClosestFriendlyBase], 5, true, 'ACUTelB', true)
                    else
                        --Find a safe base
                        local iClosestSafeBaseDist = 100000
                        local tPotentialBase
                        local tTeleportBaseTarget, iCurDist
                        for iBrain, oBrain in AiBotTeam.tTeamData[iTeam][AiBotTeam.subreftoFriendlyActiveAiBotBrains] do
                            tPotentialBase = AiBotMap.GetPlayerStartPosition(aiBrain)
                            if tPotentialBase and AiBotConditions.BaseIsSafeToRetreatTo(tLZOrWZTeamData[AiBotMap.reftClosestFriendlyBase], iTeam) then
                                iCurDist = AiBotUtilities.GetDistanceBetweenPositions(oACU:GetPosition(), tPotentialBase)
                                if iCurDist < iClosestSafeBaseDist then
                                    iClosestSafeBaseDist = iCurDist
                                    tTeleportBaseTarget = {tPotentialBase[1], tPotentialBase[2], tPotentialBase[3]}
                                end
                            end
                        end
                        if not(tTeleportBaseTarget) then tTeleportBaseTarget = {tLZOrWZTeamData[AiBotMap.reftClosestFriendlyBase][1],tLZOrWZTeamData[AiBotMap.reftClosestFriendlyBase][2],tLZOrWZTeamData[AiBotMap.reftClosestFriendlyBase][3]} end
                        AiBotOrders.IssueTrackedTeleport(oACU, tTeleportBaseTarget, 5, true, 'ACUTelC', true)
                    end
                else
                    --Do we have enough health to target
                    if AiBotUnitInfo.GetUnitHealthPercent(oACU) < 0.95 then
                        if bDebugMessages == true then LOG(sFunctionRef..': Want to heal up first, health percent='..AiBotUnitInfo.GetUnitHealthPercent(oACU)) end
                        bGivenACUOrder = false --redundancy
                    else
                        AiBotTeam.RefreshPotentialTeleSnipeTargets(iTeam)
                        if bDebugMessages == true then LOG(sFunctionRef..': Is table of telesnipe targets empty after refresh='..tostring(AiBotUtilities.IsTableEmpty(AiBotTeam.tTeamData[iTeam][AiBotTeam.reftoPotentialTeleSnipeTargets]))) end
                        if AiBotUtilities.IsTableEmpty(AiBotTeam.tTeamData[iTeam][AiBotTeam.reftoPotentialTeleSnipeTargets]) == false then
                            local oSnipeTarget = GetBestTeleSnipeUnitTarget(oACU, iTeam)
                            if bDebugMessages == true then LOG(sFunctionRef..': oSnipeTarget='..(oSnipeTarget.UnitId or 'nil')..(AiBotUnitInfo.GetUnitLifetimeCount(oSnipeTarget) or 'nil')..'; Is target valid='..tostring(AiBotUnitInfo.IsUnitValid(oSnipeTarget))) end
                            if not(AiBotUnitInfo.IsUnitValid(oSnipeTarget)) then
                                bGivenACUOrder = false --redundancy
                            else
                                local tTeleportTarget = GetBestLocationForTeleSnipeTarget(oACU, oSnipeTarget, iTeam)
                                local bAddToExistingQueue = true
                                if not(oACU:IsUnitState('Teleporting')) and not(oACU:IsUnitState('Upgrading')) then bAddToExistingQueue = false end

                                AiBotOrders.IssueTrackedTeleport(oACU, tTeleportTarget, 5, bAddToExistingQueue, 'ACUTelA', true)
                                if bDebugMessages == true then LOG(sFunctionRef..': Just tried to give ACU a teleport order') end
                                bGivenACUOrder = true
                            end
                        end
                    end
                end
            end
        end
    end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
    return bGivenACUOrder
end

function AssistBuildingUpgradeOrStorageConstruction(iPlateauOrZero, iLandOrWaterZone, tLZOrWZData, tLZOrWZTeamData, oACU)
    --Looks for nearby upgrading mex, under construction mass storage, or factory, if there are any, and assists it, returning true if it finds something to assist
    local sFunctionRef = 'AssistBuildingUpgradeOrStorageConstruction'
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)

    --Consider assisting experimental if approaching enemy threat and experimental is a land or air experimental

    local oUnitToAssist
    local aiBrain = oACU:GetAIBrain()
    local iTeam = aiBrain.AiBotTeam
    if not(AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefbTeamIsStallingMass]) and (AiBotTeam.tLandSubteamData[aiBrain.AiBotLandSubteam][AiBotTeam.refiEnemyMobileDFThreatNearOurSide] or 0) >= 8000 then
        if AiBotUtilities.IsTableEmpty(tLZOrWZTeamData[AiBotMap.subreftoLZOrWZAlliedUnits]) == false then
            local tLandOrAirExperimentals = EntityCategoryFilterDown(AiBotUnitInfo.refCategoryLandExperimental + AiBotUnitInfo.refCategoryAirNonScout * categories.EXPERIMENTAL, tLZOrWZTeamData[AiBotMap.subreftoLZOrWZAlliedUnits])
            if AiBotUtilities.IsTableEmpty(tLandOrAirExperimentals) == false then
                local iHighestCompletion = 0
                for iUnit, oUnit in tLandOrAirExperimentals do
                    if AiBotUnitInfo.IsUnitValid(oUnit) and oUnit:GetAIBrain().AiBotAI and oUnit:GetFractionComplete() < 1 then
                        if oUnit:GetFractionComplete() > iHighestCompletion then
                            iHighestCompletion = oUnit:GetFractionComplete()
                            oUnitToAssist = oUnit
                            if bDebugMessages == true then LOG(sFunctionRef..': Will get ACU to assist experimental under construction, oUnit='..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..'; Fraction complete='..oUnit:GetFractionComplete()) end
                        end
                    end
                end
            end
        end
    end
    if not(oUnitToAssist) and AiBotConditions.IsTableOfUnitsStillValid(tLZOrWZTeamData[AiBotMap.subreftoActiveUpgrades]) then
        local iHighestCompletion = 0
        local iHighestLowPriorityCompletion = 0
        local iCurCompletion
        local oLowPriorityUnit
        local bWantToImproveMassIncome = AiBotConditions.HaveLowMass(oACU:GetAIBrain())

        function ConsiderCurUnitPriority(oUnit)
            if oUnit:GetFractionComplete() < 1 then
                iCurCompletion = oUnit:GetFractionComplete()
            else
                iCurCompletion = oUnit:GetWorkProgress()
            end
            if bDebugMessages == true then LOG(sFunctionRef..': Considering if we want to assist unit '..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..'; iCurCompletion='..iCurCompletion..'; iHighestCompletion='..iHighestCompletion..'; bWantToImproveMassIncome='..tostring(bWantToImproveMassIncome)) end
            if iCurCompletion > iHighestCompletion and (not(bWantToImproveMassIncome) or EntityCategoryContains(AiBotUnitInfo.refCategoryMex + AiBotUnitInfo.refCategoryMassStorage, oUnit.UnitId)) then
                oUnitToAssist = oUnit
                iHighestCompletion = iCurCompletion
            elseif iHighestCompletion == 0 and iCurCompletion > iHighestLowPriorityCompletion then
                iHighestLowPriorityCompletion = iCurCompletion
                oLowPriorityUnit = oUnit
            end
        end

        for iUnit, oUnit in tLZOrWZTeamData[AiBotMap.subreftoActiveUpgrades] do
            ConsiderCurUnitPriority(oUnit)
        end
        local tStorageInZone = EntityCategoryFilterDown(AiBotUnitInfo.refCategoryMassStorage + AiBotUnitInfo.refCategoryMassFab, tLZOrWZTeamData[AiBotMap.subreftoLZOrWZAlliedUnits])
        if AiBotUtilities.IsTableEmpty(tStorageInZone) == false then
            for iUnit, oUnit in tStorageInZone do
                if AiBotUnitInfo.IsUnitValid(oUnit) and oUnit:GetFractionComplete() < 1 then
                    ConsiderCurUnitPriority(oUnit)
                end
            end
        end
    end
    if bDebugMessages == true then LOG(sFunctionRef..': end of code, oUnitToAssist='..(oUnitToAssist.UnitId or 'nil')..(AiBotUnitInfo.GetUnitLifetimeCount(oUnitToAssist) or 'nil')..'; aiBrain='..oACU:GetAIBrain().Nickname..'; Time='..GetGameTimeSeconds()) end
    if oUnitToAssist then
        if oUnitToAssist:GetFractionComplete() < 1 then
            AiBotOrders.IssueTrackedRepair(oACU, oUnitToAssist, false, 'ACUAstR', false)
        else
            AiBotOrders.IssueTrackedGuard(oACU, oUnitToAssist, false, 'ACUAstG', false)
        end
        return true
    end
    return false
end

function RunFromEnemyTeleport(oACU, iTeam, tLZOrWZData)
    --Returns true if we have given an order to run from a nearby enemy teleport
    local sFunctionRef = 'RunFromEnemyTeleport'
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)
    if AiBotUtilities.IsTableEmpty(AiBotTeam.tTeamData[iTeam][AiBotTeam.reftRecentEnemyTeleportDetails]) == false then
        --Are any teleport targets within 60 of us? If so then run in the opposite direction unless we are underwater or have a powerufl gun upgrade
        if bDebugMessages == true then LOG(sFunctionRef..': Checking if we need to run from enemy teleport') end
        if not(AiBotUnitInfo.IsUnitUnderwater(oACU)) and (oACU[refiUpgradeCount] <= 2 or not(oACU:HasEnhancement('MicrowaveLaserGenerator') or oACU:HasEnhancement('BlastAttack'))) then
            local iClosestTeleportDist = 50
            local iCurTeleportDist
            local tClosestTeleport
            local oNearestTeleportUnit
            local iCurTeleportUnitDist
            local iNearestTeleportUnitDist = 1000
            for iEntry, tTeleportData in AiBotTeam.tTeamData[iTeam][AiBotTeam.reftRecentEnemyTeleportDetails] do
                if AiBotUnitInfo.IsUnitValid(tTeleportData[AiBotTeam.subrefoTeleportUnit]) and (tTeleportData[AiBotTeam.subrefoTeleportUnit][AiBotUnitInfo.refiDFRange] or 0) > 0 then
                    iCurTeleportDist = AiBotUtilities.GetDistanceBetweenPositions(tTeleportData[AiBotTeam.subreftTeleportTarget], oACU:GetPosition())
                    if bDebugMessages == true then LOG(sFunctionRef..': iCurTeleportDist='..iCurTeleportDist..'; iClosestTeleportDist threshold='..iClosestTeleportDist) end
                    if iCurTeleportDist < iClosestTeleportDist then
                        iClosestTeleportDist = iCurTeleportDist
                        tClosestTeleport = {tTeleportData[AiBotTeam.subreftTeleportTarget][1], tTeleportData[AiBotTeam.subreftTeleportTarget][2], tTeleportData[AiBotTeam.subreftTeleportTarget][3]}
                    end
                    iCurTeleportUnitDist = AiBotUtilities.GetDistanceBetweenPositions(tTeleportData[AiBotTeam.subrefoTeleportUnit]:GetPosition(), oACU:GetPosition())
                    if iCurTeleportUnitDist < iNearestTeleportUnitDist then
                        iNearestTeleportUnitDist = iCurTeleportUnitDist
                        oNearestTeleportUnit = tTeleportData[AiBotTeam.subrefoTeleportUnit]
                    end
                end
            end

            --Cover off the following scenarios:
            --1 - enemy has teleported and is now moving closer to us
            --2 - enemy teleported, and then teleports again (while in range of us) to just infront of where we would be trying to run (so we run back towards them/into their range)
            local tRunToLocation
            if bDebugMessages == true then LOG(sFunctionRef..': tClosestTeleport='..repru(tClosestTeleport)..'; oNearestTeleportUnit='..(oNearestTeleportUnit.UnitId or 'nil')..(AiBotUnitInfo.GetUnitLifetimeCount(oNearestTeleportUnit) or 'nil')..'; iNearestTeleportUnitDist='..iNearestTeleportUnitDist..'; oNearestTeleportUnit[AiBotUnitInfo.refiDFRange]='..(oNearestTeleportUnit[AiBotUnitInfo.refiDFRange] or 'nil')) end
            local iAngleToRun
            if oNearestTeleportUnit and (iNearestTeleportUnitDist <= oNearestTeleportUnit[AiBotUnitInfo.refiDFRange] + 3 or iNearestTeleportUnitDist <= 50) then
                --Want to run from nearest teleport unit; check if also want to run from a teleport location
                if bDebugMessages == true then LOG(sFunctionRef..': Unit state of oNearestTeleportUnit='..AiBotUnitInfo.GetUnitState(oNearestTeleportUnit)) end
                if oNearestTeleportUnit:IsUnitState('Teleporting') and tClosestTeleport then
                    iAngleToRun = (AiBotUtilities.GetAngleFromAToB(oNearestTeleportUnit:GetPosition(), oACU:GetPosition()) + AiBotUtilities.GetAngleFromAToB(tClosestTeleport, oACU:GetPosition())) / 2
                else
                    iAngleToRun = AiBotUtilities.GetAngleFromAToB(oNearestTeleportUnit:GetPosition(), oACU:GetPosition())
                end
            elseif tClosestTeleport then
                iAngleToRun = AiBotUtilities.GetAngleFromAToB(tClosestTeleport, oACU:GetPosition())
            end
            if bDebugMessages == true then LOG(sFunctionRef..': iANgleToRun='..(iAngleToRun or 'nil')) end
            if iAngleToRun then
                local iPlateauWanted = NavUtils.GetLabel(AiBotMap.refPathingTypeHover, oACU:GetPosition())
                for iDist = 30, 5, -5 do
                    tRunToLocation = AiBotUtilities.MoveInDirection(oACU:GetPosition(), iAngleToRun, 30, true)
                    if AiBotUtilities.IsTableEmpty(tRunToLocation) == false and NavUtils.GetLabel(AiBotMap.refPathingTypeHover, tRunToLocation) == iPlateauWanted then
                        break
                    end
                end
                if AiBotUtilities.IsTableEmpty(tRunToLocation) == false then
                    --IssueTrackedMove(oUnit, tOrderPosition, iDistanceToReissueOrder, bAddToExistingQueue, sOptionalOrderDesc, bOverrideMicroOrder)
                    AiBotOrders.IssueTrackedMove(oACU, tRunToLocation, 1, false, 'RunFrTel', true)
                    --Make sure we dont dodge shots or do something that causes us to stop
                    AiBotMicro.TrackTemporaryUnitMicro(oACU, 1, nil, false)
                    if bDebugMessages == true then LOG(sFunctionRef..': Given ACU order to move away from enemy teleport, iAngleToRun='..iAngleToRun..'; tRunToLocation='..repru(tRunToLocation)) end
                    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
                    return true
                end
            end
        end
    end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
end

function GetACUOrder(aiBrain, oACU)
    local sFunctionRef = 'GetACUOrder'
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)



    if oACU[refbUseACUAggressively] then
        oACU[refbUseACUAggressively] = DoWeStillWantToBeAggressiveWithACU(oACU)
    end

    if bDebugMessages == true then LOG(sFunctionRef..': Start of code, oACU.Nickname='..aiBrain.Nickname..'; oACU.AiBotActive='..tostring(oACU.AiBotActive or false)..'; Brain type='..aiBrain.BrainType..'; bDontConsiderCombinedArmy='..tostring(AiBotOrders.bDontConsiderCombinedArmy)..'; Special micro active for ACU='..tostring(oACU[AiBotUnitInfo.refbSpecialMicroActive] or false)..'; ACU upgrade count='..(oACU[refiUpgradeCount] or 'nil')..'; Time='..GetGameTimeSeconds()) end
    local iPlateauOrZero, iLandOrWaterZone = AiBotMap.GetClosestPlateauOrZeroAndZoneToPosition(oACU:GetPosition())

    local tLZOrWZData
    local tLZOrWZTeamData
    local iTeam = oACU:GetAIBrain().AiBotTeam

    if iPlateauOrZero == 0 then
        tLZOrWZData = AiBotMap.tPondDetails[AiBotMap.tiPondByWaterZone[iLandOrWaterZone]][AiBotMap.subrefPondWaterZones][iLandOrWaterZone]
        tLZOrWZTeamData = tLZOrWZData[AiBotMap.subrefWZTeamData][iTeam]
    else
        tLZOrWZData = AiBotMap.tAllPlateaus[iPlateauOrZero][AiBotMap.subrefPlateauLandZones][iLandOrWaterZone]
        tLZOrWZTeamData = tLZOrWZData[AiBotMap.subrefLZTeamData][iTeam]
    end

    tLZOrWZTeamData[AiBotMap.refbACUInTrouble] = false --will set to true later (if want ACU to run)
    oACU[refbACUAvailableToDoSnipeAttack] = false --will set to true later

    --local iPlateau, iLandZone = AiBotMap.GetPlateauAndLandZoneReferenceFromPosition(oACU:GetPosition(), true, oACU)
    --local tLZData = AiBotMap.tAllPlateaus[iPlateau][AiBotMap.subrefPlateauLandZones][iLandZone]
    --local tLZTeamData = tLZData[AiBotMap.subrefLZTeamData][aiBrain.AiBotTeam]
    UpdateACULandOrWaterZoneAssignment(oACU, iPlateauOrZero, iLandOrWaterZone, tLZOrWZTeamData)

    --Refresh ACU last orders as some functions will check last order to decide if it was given an order
    AiBotOrders.UpdateRecordedOrders(oACU)

    if bDebugMessages == true then LOG(sFunctionRef..': Near start of code for brain '..oACU:GetAIBrain().Nickname..', ACU='..oACU.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oACU)..'; time='..GetGameTimeSeconds()..'; oACU[refbDoingInitialBuildOrder]='..tostring(oACU[refbDoingInitialBuildOrder])..'; ACU unit state='..AiBotUnitInfo.GetUnitState(oACU)..'; work progress='..oACU:GetWorkProgress()..'; iPlateau='..(iPlateauOrZero or 'nil')..'; iLandZone='..(iLandOrWaterZone or 'nil')..'; Can ACU use overcharge='..tostring(AiBotConditions.CanUnitUseOvercharge(oACU:GetAIBrain(), oACU))..'; ACU position='..repru(oACU:GetPosition())..'; ACU Orders (before updates)='..reprs(oACU[AiBotOrders.reftiLastOrders])..'; Is special micro active='..tostring(oACU[AiBotUnitInfo.refbSpecialMicroActive] or false)..'; Time to stop micro='..(oACU[AiBotUnitInfo.refiGameTimeToResetMicroActive] or 'nil')..'; Brian nickname='..aiBrain.Nickname..'; reftSpecialObjectiveMoveLocation='..repru(oACU[reftSpecialObjectiveMoveLocation])..'; Enemy combat threat='..(tLZOrWZTeamData[AiBotMap.subrefTThreatEnemyCombatTotal] or 'nil')..'; Is table of unbuilt mexes empty='..tostring(AiBotUtilities.IsTableEmpty(tLZOrWZTeamData[AiBotMap.subrefMexUnbuiltLocations]))..'; refbFocusOnT1Spam='..tostring(AiBotTeam.tTeamData[iTeam][AiBotTeam.refbFocusOnT1Spam])..'; oACU[AiBotUnitInfo.refbUsingDefaultWeaponPriority]='..tostring(oACU[AiBotUnitInfo.refbUsingDefaultWeaponPriority] or false)..'; Is table of snipe targets empty='..tostring(AiBotUtilities.IsTableEmpty(AiBotTeam.tTeamData[iTeam][AiBotTeam.toActiveSnipeTargets])))
        local oFocusUnit = oACU:GetFocusUnit()
        if oFocusUnit.UnitId then LOG('Focus unit='..oFocusUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oFocusUnit))
        else LOG('No focus unit')
        end
    end

    --Check weapon priority
    if not(oACU[AiBotUnitInfo.refbUsingDefaultWeaponPriority]) then
        if AiBotUtilities.IsTableEmpty(AiBotTeam.tTeamData[iTeam][AiBotTeam.toActiveSnipeTargets]) then
            AiBotUnitInfo.SetUnitWeaponTargetPriorities(oACU, AiBotUnitInfo.refWeaponPriorityACU, false)
            oACU[AiBotUnitInfo.refbUsingDefaultWeaponPriority] = true
        end
    elseif AiBotUtilities.IsTableEmpty(AiBotTeam.tTeamData[iTeam][AiBotTeam.toActiveSnipeTargets]) == false then
        --Double-check if have nearby snipe target that is enemy ACU since we are using default priority
        local iClosestSnipeTarget = 10000
        local iCurSnipeTargetDist
        local oClosestSnipeTarget
        for iSnipeTarget, oSnipeTarget in AiBotTeam.tTeamData[iTeam][AiBotTeam.toActiveSnipeTargets] do
            if AiBotUnitInfo.IsUnitValid(oSnipeTarget) then
                iCurSnipeTargetDist = AiBotUtilities.GetDistanceBetweenPositions(oACU:GetPosition(), oSnipeTarget:GetPosition())
                if iCurSnipeTargetDist < iClosestSnipeTarget then
                    iClosestSnipeTarget = iCurSnipeTargetDist
                    oClosestSnipeTarget = oSnipeTarget
                end
            end
        end

        if iClosestSnipeTarget <= oACU[AiBotUnitInfo.refiCombatRange] + 1 then
            local iTargetHealthPercent = AiBotUnitInfo.GetUnitHealthPercent(oClosestSnipeTarget)
            if iTargetHealthPercent <= 0.5 or (iTargetHealthPercent <= AiBotUnitInfo.GetUnitHealthPercent(oACU) - 0.2) then
                AiBotUnitInfo.SetUnitWeaponTargetPriorities(oACU, AiBotUnitInfo.refWeaponPriorityACUSnipe, false)
                oACU[AiBotUnitInfo.refbUsingDefaultWeaponPriority] = false
            end
        end
    end

    --Check for mobile shields
    CheckForNearbyMobileShieldToRequisition(oACU, tLZOrWZData, tLZOrWZTeamData, iTeam, iPlateauOrZero)

    --Is the ACU busy with something?
    if oACU:IsUnitState('Upgrading') then
        UpdateACUUpgradingHealth(oACU)
        --Do nothing unless in a very dangerous situation
        if bDebugMessages == true then LOG(sFunctionRef..': ACU upgrading so will only cancel if in dangerous situation. is ACU doing initial BO='..tostring(oACU[refbDoingInitialBuildOrder])) end
        if not(oACU[refbDoingInitialBuildOrder]) then
            if bDebugMessages == true then LOG(sFunctionRef..': ACU is upgrading') end
            local bCanceledUpgrade = false
            if DoesACUWantToReturnToCoreBase(iPlateauOrZero, iLandOrWaterZone, tLZOrWZData, tLZOrWZTeamData, oACU) then
                if bDebugMessages == true then LOG(sFunctionRef..': ACU wants to run to core base, considering if need emergency support and, if ACU health is low, will consider cancelling, ACU health%='..AiBotUnitInfo.GetUnitHealthPercent(oACU)..'; use acu aggressively='..tostring(oACU[refbUseACUAggressively] or false)..'; ACU expected to die before completing='..tostring(ACUExpectedToDieBeforeCompletingUpgrade(oACU))) end
                ConsiderIfACUNeedsEmergencySupport(iPlateauOrZero, iLandOrWaterZone, tLZOrWZData, tLZOrWZTeamData, oACU)
                local iACUHealthPercent = AiBotUnitInfo.GetUnitHealthPercent(oACU)
                --Core base - more restrictive than if not in core base
                if tLZOrWZTeamData[AiBotMap.subrefLZbCoreBase] and iACUHealthPercent <= 0.9 and (1 - iACUHealthPercent) + 0.05 > oACU:GetWorkProgress() and ACUExpectedToDieBeforeCompletingUpgrade(oACU) then
                    if bDebugMessages == true then LOG(sFunctionRef..': In core base but still want to cancel ACU upgrade') end
                    AiBotOrders.IssueTrackedMove(oACU, AiBotMap.GetPlayerStartPosition(oACU:GetAIBrain()), 5, false, 'CCRun')
                    bCanceledUpgrade = true

                    --Are we in a different LZ to core base, and have enemy threat or are on <60% health with less health than our upgrade progress?
                elseif not(tLZOrWZTeamData[AiBotMap.subrefWZbContainsUnderwaterStart]) and (not(tLZOrWZTeamData[AiBotMap.subrefLZbCoreBase]) or (iACUHealthPercent <= 0.99 and tLZOrWZTeamData[AiBotMap.subrefbEnemiesInThisOrAdjacentLZ] and AiBotUtilities.GetDistanceBetweenPositions(oACU:GetPosition(), tLZOrWZData[AiBotMap.subrefMidpoint]) >= 35 and DoesACUWantToRun(iPlateauOrZero, iLandOrWaterZone, tLZOrWZData, tLZOrWZTeamData, oACU))) then

                    if (iACUHealthPercent <= 0.99 and ((1 - iACUHealthPercent) + 0.1 > oACU:GetWorkProgress()) or AiBotTeam.tTeamData[iTeam][AiBotTeam.refbAssassinationOrSimilar]) or ACUExpectedToDieBeforeCompletingUpgrade(oACU)  then
                        --Do we no longer consider this location safe?
                        if bDebugMessages == true then LOG(sFunctionRef..': ACU health relatively low, iACUHealthPercent='..iACUHealthPercent..'; Work progress='..oACU:GetWorkProgress()..'; woudl it be safe to start an ugprade here='..tostring(AiBotConditions.SafeToUpgradeUnit(oACU))) end
                        if not(AiBotConditions.SafeToUpgradeUnit(oACU)) then
                            --Cancel upgrade
                            if bDebugMessages == true then LOG(sFunctionRef..': Want to cancel ACU upgrade') end
                            AiBotOrders.IssueTrackedMove(oACU, AiBotMap.GetPlayerStartPosition(oACU:GetAIBrain()), 5, false, 'CURun')
                            bCanceledUpgrade = true
                        end
                    end
                end
            else
                if bDebugMessages == true then LOG(sFunctionRef..': Dont want to return to base so wont cancel upgrade except in a few niche cases, safe to upgrade='..tostring(AiBotConditions.SafeToUpgradeUnit(oACU))) end
            end
            if not(bCanceledUpgrade) and not(AiBotConditions.SafeToUpgradeUnit(oACU)) and AiBotUtilities.IsTableEmpty(AiBotTeam.tTeamData[iTeam][AiBotTeam.reftEnemyLandExperimentals]) == false then
                local iClosestExp
                local iWorkProgress = oACU:GetWorkProgress()
                if iWorkProgress <= 0.3 then iClosestExp = 135
                elseif iWorkProgress <= 0.7 then iClosestExp = 115
                elseif iWorkProgress <= 0.9 then iClosestExp = 95
                else iClosestExp = 75
                end
                local oClosestExp
                local iCurDist
                for iExp, oExp in AiBotTeam.tTeamData[iTeam][AiBotTeam.reftEnemyLandExperimentals] do
                    if not(oExp.Dead) and oExp[AiBotUnitInfo.reftAssignedPlateauAndLandZoneByTeam][iTeam][1] == iPlateauOrZero then
                        iCurDist = AiBotUtilities.GetDistanceBetweenPositions(oACU:GetPosition(), oExp:GetPosition())
                        if bDebugMessages == true then LOG(sFunctionRef..': Dist of oExp='..oExp.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oExp)..' to ACU='..iCurDist..'; iClosestExp (or threshold at which ignore)='..iClosestExp) end
                        if iCurDist < iClosestExp then
                            oClosestExp = oExp
                            iClosestExp = iCurDist
                        end
                    end
                end
                if oClosestExp then
                    --Just return to base, as normal 'no-upgrade' logic will kick in next cycle
                    AiBotOrders.IssueTrackedMove(oACU, AiBotMap.GetPlayerStartPosition(oACU:GetAIBrain()), 5, false, 'CUExRun')
                    if bDebugMessages == true then LOG(sFunctionRef..': will cancel upgrade and reun to base') end
                    bCanceledUpgrade = true
                end
            end

            if bDebugMessages == true then LOG(sFunctionRef..': bCanceledUpgrade='..tostring(bCanceledUpgrade or false)) end
            if not(bCanceledUpgrade) and tLZOrWZTeamData[AiBotMap.subrefLZbCoreBase] and not(tLZOrWZTeamData[AiBotMap.subrefWZbContainsUnderwaterStart]) and AiBotUnitInfo.GetUnitHealthPercent(oACU) <= 0.7 and tLZOrWZTeamData[AiBotMap.subrefbEnemiesInThisOrAdjacentLZ] and AiBotUtilities.GetDistanceBetweenPositions(oACU:GetPosition(), tLZOrWZData[AiBotMap.subrefMidpoint]) >= 35 and DoesACUWantToRun(iPlateauOrZero, iLandOrWaterZone, tLZOrWZData, tLZOrWZTeamData, oACU) then
                local iACUHealthPercent = AiBotUnitInfo.GetUnitHealthPercent(oACU)
                if iACUHealthPercent < 0.6 and (1 - iACUHealthPercent) + math.max(0.1, math.min(0.4, 1 - iACUHealthPercent)) > oACU:GetWorkProgress() and ((1 - iACUHealthPercent) + 0.1 > oACU:GetWorkProgress() or ACUExpectedToDieBeforeCompletingUpgrade(oACU)) then
                    --Do we no longer consider this location safe?
                    if bDebugMessages == true then LOG(sFunctionRef..': ACU health relatively low, iACUHealthPercent='..iACUHealthPercent..'; Work progress='..oACU:GetWorkProgress()..'; woudl it be safe to start an ugprade here='..tostring(AiBotConditions.SafeToUpgradeUnit(oACU))) end
                    if not(AiBotConditions.SafeToUpgradeUnit(oACU)) and AiBotUtilities.GetDistanceBetweenPositions(AiBotMap.GetPlayerStartPosition(oACU:GetAIBrain()), oACU:GetPosition()) >= 35 then
                        --Cancel upgrade
                        if bDebugMessages == true then LOG(sFunctionRef..': Want to cancel ACU upgrade') end
                        AiBotOrders.IssueTrackedMove(oACU, AiBotMap.GetPlayerStartPosition(oACU:GetAIBrain()), 5, false, 'CURun')
                        bCanceledUpgrade = true
                    end
                end
            elseif bDebugMessages == true then LOG(sFunctionRef..': ACU doesnt want to return to core base')
            end
            if bCanceledUpgrade then
                oACU[AiBotUnitInfo.refiTimeLastCanceledUpgrade] = GetGameTimeSeconds()
                oACU[AiBotUnitInfo.refiDistToEnemyBaseWhenLastCanceledUpgrade] = AiBotUtilities.GetDistanceBetweenPositions(oACU:GetPosition(), tLZOrWZTeamData[AiBotMap.reftClosestEnemyBase])
            end
        end
    elseif oACU:IsUnitState('Teleporting') then
        --Do nothing
        if bDebugMessages == true then LOG(sFunctionRef..': ACU is teleporting') end
    elseif AiBotMap.bIsCampaignMap and (oACU:IsUnitState('TransportLoading') or oACU:IsUnitState('Attached')) then
        --Liekly campaign wants to do something special with ACU
        if bDebugMessages == true then LOG(sFunctionRef..': campaign and ACU is loading or attached') end
    elseif GiveOverchargeOrderIfRelevant(tLZOrWZData, tLZOrWZTeamData, oACU, iPlateauOrZero, iLandOrWaterZone) then
        --when an overcharge shot is fired it triggers this code to run again so no need to queue things up afterwards
        if bDebugMessages == true then LOG(sFunctionRef..': Have just givne overcharge order') end
    else
        oACU[refbOnlyOverchargeHighValueTargets] = oACU[refbACUSnipeModeActive] --will also set to true if we are trying to run down an enemy ACU
        oACU[refoShieldRallyTarget] = nil
        oACU[refbACUHasBeenGivenABuildOrderRecently] = false
        local bProceedWithLogic = true
        if oACU[refbDoingInitialBuildOrder] then
            if not(tLZOrWZTeamData[AiBotMap.subrefLZbCoreBase]) and GetGameTimeSeconds() >= 20 and DoesACUWantToReturnToCoreBase(iPlateauOrZero, iLandOrWaterZone, tLZOrWZData, tLZOrWZTeamData, oACU) and (not(AiBotMap.bIsCampaignMap) or aiBrain:GetCurrentUnits(AiBotUnitInfo.refCategoryFactory) > 0) then
                ConsiderIfACUNeedsEmergencySupport(iPlateauOrZero, iLandOrWaterZone, tLZOrWZData, tLZOrWZTeamData, oACU)
                if bDebugMessages == true then LOG(sFunctionRef..': Want to return to core base (or core zone with shield), subrefLZbCoreBase='..tostring(tLZOrWZTeamData[AiBotMap.subrefLZbCoreBase] or false)) end
                if not(ConsiderRunningToNearestShield(oACU, tLZOrWZData, tLZOrWZTeamData, iTeam, iPlateauOrZero, iLandOrWaterZone)) then
                    ReturnACUToCoreBase(oACU, tLZOrWZData, tLZOrWZTeamData, aiBrain, iTeam, iPlateauOrZero, iLandOrWaterZone)
                    if bDebugMessages == true then LOG(sFunctionRef..': Will go to core base') end
                end
                bProceedWithLogic = false

            elseif AiBotUtilities.IsTableEmpty(tLZOrWZTeamData[AiBotMap.subrefTEnemyUnits]) then
                bProceedWithLogic = false
                GetACUEarlyGameOrders(aiBrain, oACU) --Avoid some scenarios where ACU might get stuck in 'run to core zone' mode
                if bDebugMessages == true then LOG(sFunctionRef..': No enemies in LZ and ACU doing initial order so referred to early game order logic') end
            elseif (iLandOrWaterZone or 0) == 0 then
                bProceedWithLogic = false
                GetACUEarlyGameOrders(aiBrain, oACU) --backup which should ahve ACU move if it doesnt seem to be on a land or water zone
                if bDebugMessages == true then LOG(sFunctionRef..': ACU not in land zone and is doing initial order so referred to early game order logic') end
            elseif (iLandOrWaterZone or 0) > 0 and AiBotUtilities.IsTableEmpty(tLZOrWZTeamData[AiBotMap.subrefTEnemyUnits]) == false then
                --Are enemies in this zone, decide if we want to attack them - get closest enemy to ACU, and ignore any structures that are more than 10 from being in range of ACU
                --Exception - we have no factory in this zone, and the enemy isn't a combat unit
                local iClosestDist = 100000
                local iClosestUntilInRange = 100000
                local iClosestMobileThreatUntilInRange = 100000
                local iCurDist, iCurDistUntilInRange, iCurRange
                local oClosestEnemyByDist
                local oClosestEnemyUntilInRange
                local oClosestMobileThreatUntilInRange
                local bEnemyInACURange = false
                for iUnit, oUnit in tLZOrWZTeamData[AiBotMap.subrefTEnemyUnits] do
                    iCurDist = AiBotUtilities.GetDistanceBetweenPositions(oUnit:GetPosition(), oACU:GetPosition())
                    iCurRange = math.max((oUnit[AiBotUnitInfo.refiDFRange] or 0), (oUnit[AiBotUnitInfo.refiIndirectRange] or 0))
                    if iCurDist < iClosestDist then
                        iClosestDist = iCurDist
                        oClosestEnemyByDist = oUnit
                    end
                    iCurDistUntilInRange = iCurDist - iCurRange
                    if iCurDistUntilInRange < iClosestUntilInRange then
                        iClosestUntilInRange = iCurDistUntilInRange
                        oClosestEnemyUntilInRange = oUnit
                    end
                    if iCurDistUntilInRange < iClosestMobileThreatUntilInRange and iCurRange > 0 and EntityCategoryContains(categories.MOBILE, oUnit.UnitId) and not(EntityCategoryContains(AiBotUnitInfo.refCategoryLandScout - AiBotUnitInfo.refCategoryCombatScout, oUnit.UnitId)) then
                        iClosestMobileThreatUntilInRange = iCurDistUntilInRange
                        oClosestMobileThreatUntilInRange = oUnit
                    end
                    if iCurDist <= (oACU[AiBotUnitInfo.refiDFRange] or 0) then bEnemyInACURange = true end
                end
                local iOurRange = (oACU[AiBotUnitInfo.refiDFRange] or 0)
                local bCampaignRetreatInstead = false
                if AiBotMap.bIsCampaignMap then
                    --Consider retreating to build, or just building, in some cases
                    local tFriendlyFactories = aiBrain:GetListOfUnits(AiBotUnitInfo.refCategoryFactory, false, true)
                    local oNearestFactory
                    local iCurDist
                    local iClosestDist = 10000
                    if AiBotUtilities.IsTableEmpty(tFriendlyFactories) == false then
                        for iUnit, oUnit in tFriendlyFactories do
                            iCurDist = AiBotUtilities.GetDistanceBetweenPositions(oUnit:GetPosition(), oACU:GetPosition())
                            if iCurDist < iClosestDist then
                                iClosestDist = iCurDist
                                oNearestFactory = oUnit
                            end
                        end
                    end
                    if oNearestFactory and iClosestDist >= 10 and DoesACUWantToRun(iPlateauOrZero, iLandOrWaterZone, tLZOrWZData, tLZOrWZTeamData, oACU) then
                        AiBotOrders.IssueTrackedMove(oACU, oNearestFactory:GetPosition(), 3, false, 'ACUCampFacR', false)
                        bCampaignRetreatInstead = true
                        bProceedWithLogic = false
                    end
                end
                if bDebugMessages == true then LOG(sFunctionRef..': Deciding whether to go with early game orders despite enemy having units in this zone, subrefTThreatEnemyCombatTotal='..(tLZOrWZTeamData[AiBotMap.subrefTThreatEnemyCombatTotal] or 'nil')..'; iOurRange='..iOurRange..'; iClosestUntilInRange='..iClosestUntilInRange..'; iClosestMobileThreatUntilInRange='..iClosestMobileThreatUntilInRange..'; bCampaignRetreatInstead='..tostring(bCampaignRetreatInstead)) end
                --Ignore nearby enemy if will be a while before in our range, with the threshold depending on if it is is a mobile threat or not
                if not(bCampaignRetreatInstead) then
                    local tFactoriesOwned = aiBrain:GetListOfUnits(AiBotUnitInfo.refCategoryFactory, false, true)
                    local bHaveNoFactory = true
                    if AiBotUtilities.IsTableEmpty(tFactoriesOwned) == false then
                        for iFactory, oFactory in tFactoriesOwned do
                            if oFactory:GetFractionComplete() == 1 then bHaveNoFactory = false break end
                        end
                    end

                    if ((iClosestMobileThreatUntilInRange > 25 or (bHaveNoFactory and (iClosestMobileThreatUntilInRange > 20 or (AiBotMap.bIsCampaignMap and iClosestMobileThreatUntilInRange >= 10)))) and ((iClosestUntilInRange > (iOurRange + 15) and iCurDistUntilInRange > 15) or (iCurDistUntilInRange >= 10 and AiBotMap.bIsCampaignMap))) or (bHaveNoFactory and not(bEnemyInACURange) and (oACU:IsUnitState('Building') or oACU:IsUnitState('Repairing') or oACU:IsUnitState('Capturing')) and oACU:GetWorkProgress() >= 0.85) then
                        bProceedWithLogic = false
                        GetACUEarlyGameOrders(aiBrain, oACU) --Avoid some scenarios where ACU might get stuck in 'run to core zone' mode
                        --Special maps might have major enemy threats, so consider running in some cases
                    elseif AiBotUnitInfo.GetUnitHealthPercent(oACU) <= 0.75 and AiBotUtilities.IsTableEmpty(tLZOrWZTeamData[AiBotMap.reftoNearestDFEnemies]) == false and  AiBotConditions.GetEnemyMobileCombatThreatAndRangeInCurrentAndAdjacentZones(tLZOrWZData, tLZOrWZTeamData, iPlateauOrZero, iTeam, aiBrain) >= 1700 and DoesACUWantToRun(iPlateauOrZero, iLandOrWaterZone, tLZOrWZData, tLZOrWZTeamData, oACU) and (GetGameTimeSeconds() - (oACU[refiTimeLastWantedToRun] or 0) <= 30 or AiBotConditions.CloseToEnemyUnit(oACU:GetPosition(), tLZOrWZTeamData[AiBotMap.reftoNearestDFEnemies], 1, iTeam, true, nil, nil, oACU)) then
                        --Run from nearest enemy unit
                        if bDebugMessages == true then LOG(sFunctionRef..': Will try to run or return to core base despite not doing early game orders due to high nearby threat levels') end
                        oACU[refiTimeLastWantedToRun] = GetGameTimeSeconds()
                        ReturnACUToCoreBase(oACU, tLZOrWZData, tLZOrWZTeamData, aiBrain, iTeam, iPlateauOrZero, iLandOrWaterZone)
                    elseif iClosestMobileThreatUntilInRange > 25 or (aiBrain[AiBotEconomy.refiBrainBuildRateMultiplier] >= 3 and iClosestMobileThreatUntilInRange > 1) or aiBrain[AiBotEconomy.refiBrainBuildRateMultiplier] >= 6 then
                        if bHaveNoFactory then
                            bProceedWithLogic = false
                            GetACUEarlyGameOrders(aiBrain, oACU) --Avoid some scenarios where ACU might get stuck in 'run to core zone' mode
                        else
                            local bCompleteCurrentConstruction = false
                            if oACU:IsUnitState('Building') or oACU:IsUnitState('Repairing') or oACU:IsUnitState('Capturing') then
                                local oFocusUnit = oACU:GetFocusUnit()
                                if oFocusUnit and oACU:GetWorkProgress() >= 0.8 then
                                    bCompleteCurrentConstruction = true
                                    bProceedWithLogic = false
                                    if oACU:GetWorkProgress() >= 0.95 then
                                        --Complete construction
                                    elseif AttackNearestEnemyWithACU(iPlateauOrZero, iLandOrWaterZone, tLZOrWZData, tLZOrWZTeamData, oACU, (oACU[AiBotUnitInfo.refiDFRange] or 0) + 3) then
                                        if bDebugMessages == true then LOG(sFunctionRef..': Enemy almost in our range so will attack even though almost complete') end
                                    else
                                        --Complete construction
                                    end
                                end
                            end
                            if not(bCompleteCurrentConstruction) then
                                if bDebugMessages == true then LOG(sFunctionRef..': About to consider attacking nearest enemy ACU, iPlateauOrZero='..(iPlateauOrZero or 'nil')..'; iLandOrWaterZone='..(iLandOrWaterZone or 'nil')) end
                                if AttackNearestEnemyWithACU(iPlateauOrZero, iLandOrWaterZone, tLZOrWZData, tLZOrWZTeamData, oACU, 35) then
                                    bProceedWithLogic = false
                                    if bDebugMessages == true then LOG(sFunctionRef..': Have enemies fairly close in this zone and have land fac so will attack') end
                                else
                                    if bDebugMessages == true then LOG(sFunctionRef..': Have a facotry, but nearby enemies arent close enough to attack with ACU using 45 distane threshold, will proceed with non-early game logic temporarily unless we are building') end
                                    if oACU:IsUnitState('Building') or oACU:IsUnitState('Repairing') or oACU:IsUnitState('Capturing') then
                                        bProceedWithLogic = false
                                    end
                                end
                            end
                            if bDebugMessages == true then LOG(sFunctionRef..': bCompleteCurrentConstruction (true if enemy in our range and we are attacking as well)='..tostring(bCompleteCurrentConstruction)..'; bProceedWithLogic='..tostring(bProceedWithLogic)) end
                        end
                    elseif AttackNearestEnemyWithACU(iPlateauOrZero, iLandOrWaterZone, tLZOrWZData, tLZOrWZTeamData, oACU, 45) then
                        bProceedWithLogic = false
                        if bDebugMessages == true then LOG(sFunctionRef..': Have enemies close in this zone so will attack') end
                    end
                end
            end
            --Override to doing build order - clear off if have had 1m and have access to tech 3
            if oACU[refbDoingInitialBuildOrder] and GetGameTimeSeconds() >= 60 and aiBrain[AiBotEconomy.refiOurHighestFactoryTechLevel] >= 3 and aiBrain[AiBotEconomy.refiGrossEnergyBaseIncome] >= 15 and aiBrain[AiBotEconomy.refiGrossMassBaseIncome] >= 1.5 then
                oACU[refbDoingInitialBuildOrder] = false
                if bDebugMessages == true then LOG(sFunctionRef..': Clearing the initial build order flag for ACU earlier than normal as we already have tech 3') end
            end
            if not(oACU[refbDoingInitialBuildOrder]) then bProceedWithLogic = true end
        elseif oACU[reftSpecialObjectiveMoveLocation] then
            AiBotOrders.IssueTrackedMove(oACU, oACU[reftSpecialObjectiveMoveLocation], 3, false, 'ACUObj', false)
            bProceedWithLogic = false
        elseif oACU[AiBotUnitInfo.refbSpecialMicroActive] and not(oACU[refbACUSnipeModeActive]) then
            --Do nothing unless are in range of PD in which case retreat despite the special micro
            if bDebugMessages == true then LOG(sFunctionRef..': ACU has special micro active, Time remaining='..(oACU[AiBotUnitInfo.refiGameTimeToResetMicroActive] or 0) - GetGameTimeSeconds()..'; Does ACU want to run='..tostring(DoesACUWantToRun(iPlateauOrZero, iLandOrWaterZone, tLZOrWZData, tLZOrWZTeamData, oACU))) end
            if RunFromEnemyTeleport(oACU, iTeam, tLZOrWZData) then
                if bDebugMessages == true then LOG(sFunctionRef..': Are running from a nearby enemy teleport attempt') end
            elseif DoesACUWantToRun(iPlateauOrZero, iLandOrWaterZone, tLZOrWZData, tLZOrWZTeamData, oACU) then
                if bDebugMessages == true then LOG(sFunctionRef..': have flagged that acu wants to run, iPlateauOrZero='..iPlateauOrZero..'; Enemy DF structure threat='..(tLZOrWZTeamData[AiBotMap.subrefThreatEnemyDFStructures] or 0)..'; ACU health%='..AiBotUnitInfo.GetUnitHealthPercent(oACU)..'; Is table of enemy units empty='..tostring( AiBotUtilities.IsTableEmpty(tLZOrWZTeamData[AiBotMap.subrefTEnemyUnits]))) end
                ConsiderIfACUNeedsEmergencySupport(iPlateauOrZero, iLandOrWaterZone, tLZOrWZData, tLZOrWZTeamData, oACU)
                if iPlateauOrZero > 0 and AiBotUnitInfo.GetUnitHealthPercent(oACU) <= 0.8 then
                    local oNearestPD
                    local iClosestDistUntilInRange = 10000
                    local iCurDist
                    function ConsiderNearestPDInZone(tLZTeamData)
                        if AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.subrefTEnemyUnits]) == false then
                            local tEnemyPD = EntityCategoryFilterDown(AiBotUnitInfo.refCategoryPD, tLZTeamData[AiBotMap.subrefTEnemyUnits])
                            if AiBotUtilities.IsTableEmpty(tEnemyPD) == false then
                                for iUnit, oUnit in tEnemyPD do
                                    if AiBotUnitInfo.IsUnitValid(oUnit) and oUnit:GetFractionComplete() == 1 then
                                        iCurDist = AiBotUtilities.GetDistanceBetweenPositions(oUnit:GetPosition(), oACU:GetPosition()) - (oUnit[AiBotUnitInfo.refiDFRange] or 0)
                                        if iCurDist < iClosestDistUntilInRange then
                                            iClosestDistUntilInRange = iCurDist
                                            oNearestPD = oUnit
                                            if iClosestDistUntilInRange < 0 then break end
                                        end
                                    end
                                end
                            end
                        end
                    end
                    ConsiderNearestPDInZone(tLZOrWZTeamData)
                    if AiBotUtilities.IsTableEmpty(tLZOrWZData[AiBotMap.subrefLZAdjacentLandZones]) == false then
                        for _, iAdjLZ in tLZOrWZData[AiBotMap.subrefLZAdjacentLandZones] do
                            local tAdjLZTeamData = AiBotMap.tAllPlateaus[iPlateauOrZero][AiBotMap.subrefPlateauLandZones][iAdjLZ][AiBotMap.subrefLZTeamData][iTeam]
                            ConsiderNearestPDInZone(tAdjLZTeamData)
                        end
                    end
                    if bDebugMessages == true then LOG(sFunctionRef..'; Considering ignoring special micro, iClosestDistUntilInRange='..iClosestDistUntilInRange..'; oNearestPD='..(oNearestPD.UnitId or 'nil')..(AiBotUnitInfo.GetUnitLifetimeCount(oNearestPD) or 'nil')) end
                    if iClosestDistUntilInRange <= 1 and oNearestPD then
                        --We want to run
                        local tRallyPoint = AiBotLand.GetNearestLandRallyPoint(tLZOrWZData, iTeam, iPlateauOrZero, iLandOrWaterZone, 2, true)
                        if AiBotUtilities.IsTableEmpty(tRallyPoint) == false then
                            if bDebugMessages == true then LOG(sFunctionRef..': Angle to rally point tRallyPoint='..AiBotUtilities.GetAngleFromAToB(oACU:GetPosition(), tRallyPoint)..'; Angle to nearest enemy PD='..AiBotUtilities.GetAngleFromAToB(oACU:GetPosition(), oNearestPD:GetPosition())) end
                            if AiBotUtilities.GetAngleDifference(AiBotUtilities.GetAngleFromAToB(oACU:GetPosition(), tRallyPoint), AiBotUtilities.GetAngleFromAToB(oACU:GetPosition(), oNearestPD:GetPosition())) > 90 then
                                if bDebugMessages == true then LOG(sFunctionRef..': Will consider running to shield or rally point') end
                                if not(ConsiderRunningToNearestShield(oACU, tLZOrWZData, tLZOrWZTeamData, iTeam, iPlateauOrZero, iLandOrWaterZone)) then
                                    if bDebugMessages == true then LOG(sFunctionRef..': Will override micro logic and retreat') end
                                    AiBotOrders.IssueTrackedMove(oACU, tRallyPoint, 5, false, 'ACUIgnMRetr', true)
                                end
                            end
                        end
                    end
                end
            end
            if GetGameTimeSeconds() > (oACU[AiBotUnitInfo.refiGameTimeToResetMicroActive] or 0) then
                oACU[AiBotUnitInfo.refbSpecialMicroActive] = false
            end
            bProceedWithLogic = false
            --Low cost and build time upgrades - ensure we always have the desired upgrades
            --Move away from a teleport
        elseif RunFromEnemyTeleport(oACU, iTeam, tLZOrWZData) then
            bProceedWithLogic = false
        end
        if bDebugMessages == true then LOG(sFunctionRef..': oACU[refbDoingInitialBuildOrder]='..tostring(oACU[refbDoingInitialBuildOrder] or false)..'; bProceedWithLogic='..tostring(bProceedWithLogic or false)..'; Is table of enemy units for this LZ empty='..tostring(AiBotUtilities.IsTableEmpty(tLZOrWZTeamData[AiBotMap.subrefTEnemyUnits]))) end
        if bProceedWithLogic and oACU[refiUpgradeCount] >= 3 and not(tLZOrWZTeamData[AiBotMap.subrefLZbCoreBase]) and not(oACU[AiBotUnitInfo.refbSpecialMicroActive]) and oACU[reftPreferredUpgrades][1] and oACU:GetBlueprint()[oACU[reftPreferredUpgrades][1]].BuildCostMass <= 10 and not(oACU:IsUnitState('Upgrading')) then
            if bDebugMessages == true then LOG(sFunctionRef..': Havent got all preferred upgrades') end
            --Are there enemies in the same LZ as the ACU? If so then consider action for these
            local sUpgradeWanted = GetACUUpgradeWanted(oACU, false, tLZOrWZData, tLZOrWZTeamData, iPlateauOrZero)
            if sUpgradeWanted then
                if AiBotConditions.SafeToUpgradeUnit(oACU) then
                    if GetGameTimeSeconds() - (AiBotTeam.tTeamData[iTeam][AiBotTeam.refiTimeLastIssuedACUEnhancementOrder] or -100) > 1.5 or oACU[AiBotOrders.reftiLastOrders][oACU[AiBotOrders.refiOrderCount]][AiBotOrders.subrefsOrderBlueprint] == sUpgradeWanted then
                        AiBotOrders.IssueTrackedEnhancement(oACU, sUpgradeWanted, false, 'ACULCUpr')
                        bProceedWithLogic = false
                        if bDebugMessages == true then LOG(sFunctionRef..': sUpgradeWanted='..sUpgradeWanted..'; will proceed with getting it due to its low cost') end
                    end
                else
                    if bDebugMessages == true then LOG(sFunctionRef..': We want to get upgrade but it isnt safe, so return to base') end
                    ReturnACUToCoreBase(oACU, tLZOrWZData, tLZOrWZTeamData, aiBrain, iTeam, iPlateauOrZero, iLandOrWaterZone)
                    bProceedWithLogic = false
                end
            end
        end
        if bProceedWithLogic then
            --Special case - rebuilding destroyed base (relevant for teamgame) - if ACU at core base, and has no factories, then build a factory
            --Cant just use factory count in case we have plateaus/islands that have factories on them
            if bDebugMessages == true then LOG(sFunctionRef..': Considerinb brain '..aiBrain.Nickname..' at time '..GetGameTimeSeconds()..'; Current factories='..aiBrain:GetCurrentUnits(AiBotUnitInfo.refCategoryFactory)..'; In core LZ='..tostring(tLZOrWZTeamData[AiBotMap.subrefLZbCoreBase])..'; Enemies in this LZ='..tostring(tLZOrWZTeamData[AiBotMap.subrefbDangerousEnemiesInThisLZ])..'; aiBrain[AiBotEconomy.refiOurHighestAirFactoryTech]='..(aiBrain[AiBotEconomy.refiOurHighestAirFactoryTech] or 'nil')..'; brain mass %='..aiBrain:GetEconomyStoredRatio('MASS')..'; Brain energy%='..aiBrain:GetEconomyStoredRatio('ENERGY')..'; Gross energy='..aiBrain[AiBotEconomy.refiGrossEnergyBaseIncome]..'; gross mass='..aiBrain[AiBotEconomy.refiGrossMassBaseIncome]..'; iPlateauOrZero='..(iPlateauOrZero or 'nil')..'; tLZOrWZTeamData[AiBotMap.subrefbEnemiesInThisOrAdjacentLZ]='..tostring((tLZOrWZTeamData[AiBotMap.subrefbEnemiesInThisOrAdjacentLZ] or false))..'; aiBrain[AiBotEconomy.refiOurHighestLandFactoryTech]='..(aiBrain[AiBotEconomy.refiOurHighestLandFactoryTech] or 'nil')..'; aiBrain[AiBotEconomy.refiNetMassBaseIncome]='..aiBrain[AiBotEconomy.refiNetMassBaseIncome]..'; Energy % stored='..aiBrain:GetEconomyStoredRatio('ENERGY')..'; LZ S value='..(tLZOrWZTeamData[AiBotMap.subrefLZSValue] or 'nil')..'; Time last built at facotry based on refiTimeLastBuiltAtFactory='..GetGameTimeSeconds() - (tLZOrWZTeamData[AiBotMap.refiTimeLastBuiltAtFactory] or 0)) end
            if (iPlateauOrZero > 0 and not(tLZOrWZTeamData[AiBotMap.subrefbDangerousEnemiesInThisLZ]) and (tLZOrWZTeamData[AiBotMap.subrefLZbCoreBase] or not(tLZOrWZTeamData[AiBotMap.subrefbEnemiesInThisOrAdjacentLZ]))) and (AiBotUtilities.IsTableEmpty(tLZOrWZTeamData[AiBotMap.reftoNearestDFEnemies]) or not(DoesACUWantToRun(iPlateauOrZero, iLandOrWaterZone, tLZOrWZData, tLZOrWZTeamData, oACU))) then
                --Consider getting another factory if either have none of a particular type, or we are close to overflowing
                local bWantAnotherFactory
                local iFactoryCategoryToGet = AiBotUnitInfo.refCategoryLandFactory
                local iFactoryEngineerAction = AiBotEngineer.refActionBuildLandFactory
                if aiBrain[AiBotEconomy.refiOurHighestLandFactoryTech] == 0 or (aiBrain[AiBotEconomy.refiOurHighestAirFactoryTech] == 0 and (aiBrain[AiBotEconomy.refiGrossMassBaseIncome] >= 6 * aiBrain[AiBotEconomy.refiBrainBuildRateMultiplier] or aiBrain:GetCurrentUnits(AiBotUnitInfo.refCategoryMex - categories.TECH1) >= 2)) or (not(tLZOrWZTeamData[AiBotMap.subrefbDangerousEnemiesInThisLZ]) and aiBrain:GetEconomyStoredRatio('MASS') >= 0.8 and (aiBrain[AiBotEconomy.refiGrossEnergyBaseIncome] > 150 or (aiBrain:GetEconomyStoredRatio('ENERGY') >= 0.99 and aiBrain[AiBotEconomy.refiNetEnergyBaseIncome] > 0)) and (aiBrain[AiBotEconomy.refiGrossMassBaseIncome] > 2 or aiBrain[AiBotEconomy.refiNetMassBaseIncome] > 0) and aiBrain:GetEconomyStoredRatio('ENERGY') >= 0.95 and (GetGameTimeSeconds() <= 360 or AiBotConditions.WantMoreFactories(iTeam, iPlateauOrZero, iLandOrWaterZone, true))) then
                    if bDebugMessages == true then LOG(sFunctionRef..': Do we have factories of any type in this LZ? Is table empty='..tostring(AiBotUtilities.IsTableEmpty(tLZOrWZTeamData[AiBotMap.subreftoLZOrWZAlliedUnits]) or AiBotUtilities.IsTableEmpty(EntityCategoryFilterDown(AiBotUnitInfo.refCategoryFactory, tLZOrWZTeamData[AiBotMap.subreftoLZOrWZAlliedUnits])))..'; aiBrain[AiBotEconomy.refiOurHighestLandFactoryTech]='..aiBrain[AiBotEconomy.refiOurHighestLandFactoryTech]) end

                    if aiBrain[AiBotEconomy.refiOurHighestLandFactoryTech] == 0 then bWantAnotherFactory = true
                        --elseif AiBotUtilities.IsTableEmpty(tLZOrWZTeamData[AiBotMap.subreftoLZOrWZAlliedUnits]) then bWantAnotherFactory = true
                    elseif AiBotUtilities.IsTableEmpty(tLZOrWZTeamData[AiBotMap.subreftoLZOrWZAlliedUnits]) == false then
                        local iLandFacHQCount = 0
                        local iAirFacHQCount = 0
                        --local bHaveHQFactoriesWeOwnInZone = false

                        local tFactoriesInLZ = EntityCategoryFilterDown(AiBotUnitInfo.refCategoryFactory - categories.SUPPORTFACTORY, tLZOrWZTeamData[AiBotMap.subreftoLZOrWZAlliedUnits])

                        if AiBotUtilities.IsTableEmpty(tFactoriesInLZ) == false then
                            for iFactory, oFactory in tFactoriesInLZ do
                                if oFactory:GetFractionComplete() >= 1 then
                                    if EntityCategoryContains(AiBotUnitInfo.refCategoryLandFactory, oFactory.UnitId) then iLandFacHQCount = iLandFacHQCount + 1
                                    elseif EntityCategoryContains(AiBotUnitInfo.refCategoryAirFactory, oFactory.UnitId) then iAirFacHQCount = iAirFacHQCount + 1
                                    end
                                    --if oFactory:GetAIBrain() == aiBrain then bHaveHQFactoriesWeOwnInZone = true
                                end
                            end
                        end
                        if iLandFacHQCount == 0 then
                            bWantAnotherFactory = true
                        elseif iAirFacHQCount == 0 then
                            bWantAnotherFactory = true
                            iFactoryCategoryToGet = AiBotUnitInfo.refCategoryAirFactory
                            iFactoryEngineerAction = AiBotEngineer.refActionBuildAirFactory
                        elseif AiBotConditions.WantMoreFactories(iTeam, iPlateauOrZero, iLandOrWaterZone) then
                            bWantAnotherFactory = true
                            if AiBotConditions.DoWeWantAirFactoryInsteadOfLandFactory(iTeam, tLZOrWZData, tLZOrWZTeamData, aiBrain) then
                                iFactoryCategoryToGet = AiBotUnitInfo.refCategoryAirFactory
                                iFactoryEngineerAction = AiBotEngineer.refActionBuildAirFactory
                            end
                        else
                            bWantAnotherFactory = false
                        end
                        if bDebugMessages == true then LOG(sFunctionRef..': iLandFacHQCount='..iLandFacHQCount..'; iAirFacHQCount='..iAirFacHQCount..'; iFactoryEngineerAction='..(iFactoryEngineerAction or 'nil')) end
                    end
                end
                if bDebugMessages == true then LOG(sFunctionRef..': Do we want another factory='..tostring(bWantAnotherFactory)..'; want more factories condition result='..tostring(AiBotConditions.WantMoreFactories(iTeam, iPlateauOrZero, iLandOrWaterZone))..'; iFactoryEngineerAction='..(iFactoryEngineerAction or 'nil')) end
                if bWantAnotherFactory then
                    bProceedWithLogic = false
                    --If enemies are almost in range of us then attack them first instead, as otherwise will just keep building factory
                    local oNearestEnemy
                    local iClosestEnemyLessRangeDist = 10
                    local iCurEnemyLessRangeDist
                    function ConsiderEnemies(tEnemyUnits)
                        if tEnemyUnits[1] then
                            for iUnit, oUnit in tEnemyUnits do
                                if not(oUnit.Dead) and (oUnit[AiBotUnitInfo.refiCombatRange] or 0) >= 4 then
                                    iCurEnemyLessRangeDist = AiBotUtilities.GetDistanceBetweenPositions(oUnit:GetPosition(), oACU:GetPosition()) - oUnit[AiBotUnitInfo.refiCombatRange]
                                    if iCurEnemyLessRangeDist < iClosestEnemyLessRangeDist then
                                        iClosestEnemyLessRangeDist = iCurEnemyLessRangeDist
                                        oNearestEnemy = oUnit
                                    end
                                end
                            end
                        end
                    end
                    ConsiderEnemies(tLZOrWZTeamData[AiBotMap.subrefTEnemyUnits])
                    if not(oNearestEnemy) and AiBotUtilities.IsTableEmpty(tLZOrWZData[AiBotMap.subrefLZAdjacentLandZones]) == false then
                        for _, iAdjLZ in tLZOrWZData[AiBotMap.subrefLZAdjacentLandZones] do
                            local tAdjLZTeamData = AiBotMap.tAllPlateaus[iPlateauOrZero][AiBotMap.subrefPlateauLandZones][iAdjLZ][AiBotMap.subrefLZTeamData][iTeam]
                            ConsiderEnemies(tAdjLZTeamData[AiBotMap.subrefTEnemyUnits])
                        end
                    end

                    if bDebugMessages == true then LOG(sFunctionRef..': Wont try building factory if enemy almost in range of us, oNearestEnemy='..(oNearestEnemy.UnitId or 'nil')..(AiBotUnitInfo.GetUnitLifetimeCount(oNearestEnemy) or 'nil')) end
                    if oNearestEnemy then
                        if not(oACU[AiBotUnitInfo.refbLastShotBlocked]) then
                            AiBotOrders.IssueTrackedAttackMove(oACU, oNearestEnemy:GetPosition(), 3, false, 'RebuildEnAM', false)
                        else
                            AiBotOrders.IssueTrackedMove(oACU, oNearestEnemy:GetPosition(), 3, false, 'RebuildEnM', false)
                        end
                    else

                        ACUActionBuildFactory(aiBrain, oACU, iPlateauOrZero, iLandOrWaterZone, tLZOrWZData, tLZOrWZTeamData, iFactoryCategoryToGet, iFactoryEngineerAction)
                        oACU[refbDoingInitialBuildOrder] = true --reset flag so we get some mexes and pgens

                        if bDebugMessages == true then LOG(sFunctionRef..': WIll try and rebuild base by building a factory') end
                        if not(AiBotConditions.DoesACUHaveValidOrder(oACU)) and (AiBotOrders.bDontConsiderCombinedArmy or oACU.AiBotActive) then
                            --Try building land if we failed to build air, and vice versa, provided we have decent power, and we lack any factories of the other type, and we want more factories
                            local bWantMoreFactories = AiBotConditions.WantMoreFactories(iTeam, iPlateauOrZero, iLandOrWaterZone)
                            if bDebugMessages == true then LOG(sFunctionRef..': We dont have a valid order, bWantMoreFactories='..tostring(bWantMoreFactories)..'; Energy stored ratio='..aiBrain:GetEconomyStoredRatio('ENERGY')) end
                            if bWantMoreFactories and aiBrain:GetEconomyStoredRatio('ENERGY') >= 0.95 then
                                if iFactoryEngineerAction == AiBotEngineer.refActionBuildLandFactory then
                                    iFactoryEngineerAction = AiBotEngineer.refActionBuildAirFactory
                                    iFactoryCategoryToGet = AiBotUnitInfo.refCategoryAirFactory
                                else
                                    iFactoryEngineerAction = AiBotEngineer.refActionBuildLandFactory
                                    iFactoryCategoryToGet = AiBotUnitInfo.refCategoryLandFactory
                                end
                                ACUActionBuildFactory(aiBrain, oACU, iPlateauOrZero, iLandOrWaterZone, tLZOrWZData, tLZOrWZTeamData, iFactoryCategoryToGet, iFactoryEngineerAction)
                                if bDebugMessages == true then LOG(sFunctionRef..': Just tried another factory type with iFactoryEngineerAction='..iFactoryEngineerAction..'; do we have a valid order='..tostring(AiBotConditions.DoesACUHaveValidOrder(oACU))) end
                            end

                            if bWantMoreFactories and not(AiBotConditions.DoesACUHaveValidOrder(oACU)) and (AiBotOrders.bDontConsiderCombinedArmy or oACU.AiBotActive) then
                                --Move to WZ to build a naval factory if we have none and are adjacent to water
                                if AiBotUtilities.IsTableEmpty(tLZOrWZData[AiBotMap.subrefAdjacentWaterZones]) == false and aiBrain:GetCurrentUnits(AiBotUnitInfo.refCategoryNavalFactory) == 0 then
                                    MoveACUToNearbyWaterForFactory(aiBrain, oACU, tLZOrWZData)
                                    --Do we want more power?
                                elseif AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossEnergy] <= 50 * AiBotTeam.tTeamData[iTeam][AiBotTeam.refiHighestBrainResourceMultiplier] and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamAverageMassPercentStored] >= 0.3 and not(AiBotConditions.HaveLowMass(aiBrain)) and (AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestFriendlyFactoryTech] == 1 or (AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestFriendlyFactoryTech] == 2 and oACU.HasEnhancement and oACU:HasEnhancement('AdvancedEngineering'))) and (AiBotConditions.WantMorePower(iTeam) or AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamAverageMassPercentStored] >= 0.7) then
                                    ACUActionBuildPower(aiBrain, oACU)
                                end
                            end
                            if not(AiBotConditions.DoesACUHaveValidOrder(oACU)) and (AiBotOrders.bDontConsiderCombinedArmy or oACU.AiBotActive) then
                                --Do we want more power?
                                if AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossEnergy] <= 50 and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamAverageMassPercentStored] >= 0.3 and not(AiBotConditions.HaveLowMass(aiBrain)) and (AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestFriendlyFactoryTech] == 1 or (AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestFriendlyFactoryTech] == 2 and oACU.HasEnhancement and oACU:HasEnhancement('AdvancedEngineering'))) and (AiBotConditions.WantMorePower(iTeam) or AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamAverageMassPercentStored] >= 0.7) then
                                    ACUActionBuildPower(aiBrain, oACU)
                                else
                                    bProceedWithLogic = true
                                end
                            end
                        end

                        if bDebugMessages == true then LOG(sFunctionRef..': We want to build factory or power, so wont proceed with logic, unless we werent able to build eg due to unit restrictions, bProceedWithLogic='..tostring(bProceedWithLogic)) end
                    end
                end
            elseif iPlateauOrZero == 0 and (tLZOrWZTeamData[AiBotMap.subrefWZbContainsUnderwaterStart] or AiBotMap.bIsCampaignMap) and aiBrain[AiBotEconomy.refiOurHighestNavalFactoryTech] == 0 and AiBotUtilities.IsTableEmpty(tLZOrWZTeamData[AiBotMap.subrefTEnemyUnits]) then
                --Check if have adjacent land zone with enemy units with a decent range, so we dont get stuck building factory that they kill
                local bNearbyDangerousLandUnits = false
                local tNearestZoneWithEnemies
                if AiBotUtilities.IsTableEmpty(tLZOrWZData[AiBotMap.subrefAdjacentLandZones]) == false and AiBotUnitInfo.GetUnitHealthPercent(oACU) > 0.75 then

                    for iEntry, tSubtable in tLZOrWZData[AiBotMap.subrefAdjacentLandZones] do
                        local tAdjLZData = AiBotMap.tAllPlateaus[tSubtable[AiBotMap.subrefWPlatAndLZNumber][1]][AiBotMap.subrefPlateauLandZones][tSubtable[AiBotMap.subrefWPlatAndLZNumber][2]]
                        local tAdjLZTeamData = tAdjLZData[AiBotMap.subrefLZTeamData][iTeam]
                        if bDebugMessages == true then LOG(sFunctionRef..': Considering adjacent land zone LZ='..tSubtable[AiBotMap.subrefWPlatAndLZNumber][2]..'; subrefLZThreatEnemyBestMobileIndirectRange='..(tAdjLZTeamData[AiBotMap.subrefLZThreatEnemyBestMobileIndirectRange] or 0)..'; subrefLZThreatEnemyBestMobileDFRange='..(tAdjLZTeamData[AiBotMap.subrefLZThreatEnemyBestMobileDFRange] or 0)) end
                        if (tAdjLZTeamData[AiBotMap.subrefiNearbyEnemyLongRangeDFThreat] or 0) > 0 or (tAdjLZTeamData[AiBotMap.subrefiNearbyEnemyLongRangeIFThreat] or 0) > 0 or (tAdjLZTeamData[AiBotMap.subrefLZThreatEnemyBestMobileIndirectRange] or 0) > 30 or (tAdjLZTeamData[AiBotMap.subrefLZThreatEnemyBestMobileDFRange] or 0) > 30 then
                            bNearbyDangerousLandUnits = true
                            tNearestZoneWithEnemies = AiBotMap.tAllPlateaus[tSubtable[AiBotMap.subrefWPlatAndLZNumber][1]][AiBotMap.subrefPlateauLandZones][tSubtable[AiBotMap.subrefWPlatAndLZNumber][2]]
                            if bDebugMessages == true then LOG(sFunctionRef..': Setting bNearbyDangerousLandUnits=true due to iAdjLZ='..tSubtable[AiBotMap.subrefWPlatAndLZNumber][2]..' having land units with decent range') end
                            break
                        end
                    end
                end
                if not(bNearbyDangerousLandUnits) then
                    ACUActionBuildFactory(aiBrain, oACU, iPlateauOrZero, iLandOrWaterZone, tLZOrWZData, tLZOrWZTeamData, AiBotUnitInfo.refCategoryNavalFactory, AiBotEngineer.refActionBuildNavalFactory)
                    bProceedWithLogic = false
                    --Attack enemies on land if we have no factories so we can try and clear a space or go out with a bang
                elseif tNearestZoneWithEnemies and aiBrain[AiBotEconomy.refiOurHighestFactoryTechLevel] == 0 and AiBotUnitInfo.GetUnitHealthPercent(oACU) > 0.9 then
                    if bDebugMessages == true then LOG(sFunctionRef..': Will try attacking nearest zone with enemies') end
                    bProceedWithLogic = false
                    AiBotOrders.IssueTrackedMove(oACU, tNearestZoneWithEnemies[AiBotMap.subrefMidpoint], 6, false, 'ACSuicLZ', false)
                end
            end
            if bDebugMessages == true then LOG(sFunctionRef..': bProceedWithLogic='..tostring(bProceedWithLogic or false)) end
            if bProceedWithLogic then
                --Special telesnipe logic (takes priorioty over running)
                if HaveTelesnipeAction(oACU, tLZOrWZData, tLZOrWZTeamData, aiBrain, iTeam, iPlateauOrZero, iLandOrWaterZone) then
                    if bDebugMessages == true then LOG(sFunctionRef..': ACU is proceeding with a telesnipe action') end
                else
                    oACU[refbACUAvailableToDoSnipeAttack] = true
                    if bDebugMessages == true then LOG(sFunctionRef..': Checking if ACU wants to run, Does it want to return to core base='..tostring(DoesACUWantToReturnToCoreBase(iPlateauOrZero, iLandOrWaterZone, tLZOrWZData, tLZOrWZTeamData, oACU) or false)..'; ACU unit state='..AiBotUnitInfo.GetUnitState(oACU)..'; Is this core base='..tostring(tLZOrWZTeamData[AiBotMap.subrefLZbCoreBase] or false)..'; Dist to midpoint='..AiBotUtilities.GetDistanceBetweenPositions(oACU:GetPosition(), tLZOrWZData[AiBotMap.subrefMidpoint])..'; Does ACU want to run='..tostring(DoesACUWantToRun(iPlateauOrZero, iLandOrWaterZone, tLZOrWZData, tLZOrWZTeamData, oACU) or false)..'; Is Enemy snipe target table empty='..tostring(AiBotUtilities.IsTableEmpty(AiBotTeam.tTeamData[iTeam][AiBotTeam.toActiveSnipeTargets]))..'; oACU[refbACUSnipeModeActive]='..tostring(oACU[refbACUSnipeModeActive] or false)..'; Enemy team mass income='..AiBotConditions.GetEnemyTeamActualMassIncome(iTeam)..'; Our team mass income='..AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossMass]) end
                    function GetPositionToRunFromNearestEnemy()
                        local tPositionToRunTo
                        local oClosestEnemy, iCurDist
                        local iClosestEnemy = 1000
                        for iEnemy, oEnemy in tLZOrWZTeamData[AiBotMap.reftoNearestDFEnemies] do
                            if not(oEnemy.Dead) then
                                iCurDist = AiBotUtilities.GetDistanceBetweenPositions(oEnemy:GetPosition(), oACU:GetPosition()) - (oEnemy[AiBotUnitInfo.refiDFRange] or 0)
                                if iCurDist < iClosestEnemy then
                                    iClosestEnemy = iCurDist
                                    oClosestEnemy = oEnemy
                                end
                            end
                        end
                        local tPositionToRunFrom
                        if oClosestEnemy then tPositionToRunFrom = oClosestEnemy:GetPosition() else tPositionToRunFrom = tLZOrWZTeamData[AiBotMap.reftClosestEnemyBase] end
                        local iAngleToMove = AiBotUtilities.GetAngleFromAToB(tPositionToRunFrom, oACU:GetPosition())
                        for iDistToMove = 20, 10, -5 do
                            tPositionToRunTo = AiBotUtilities.MoveInDirection(oACU:GetPosition(), iAngleToMove, iDistToMove, true, true, AiBotMap.bIsCampaignMap)
                            if AiBotUtilities.IsTableEmpty(tPositionToRunTo) == false and NavUtils.GetLabel(AiBotMap.refPathingTypeHover, tPositionToRunTo) == iPlateauOrZero then
                                break
                            else
                                tPositionToRunTo = nil
                            end
                        end
                        if not(tPositionToRunTo) then tPositionToRunTo = AiBotLand.GetNearestLandRallyPoint(tLZOrWZData, iTeam, iPlateauOrZero, iLandOrWaterZone, 2, true) end
                        return tPositionToRunTo, oClosestEnemy
                    end
                    --Potential snipe target if we are in range of an enemy ACU and it is low enough health that we can just go for a kill
                    if oACU[refbACUSnipeModeActive] or DoesACUWantToSuicideIntoEnemyACU(oACU, iTeam, iPlateauOrZero, iLandOrWaterZone, tLZOrWZTeamData) then
                        if bDebugMessages == true then LOG(sFunctionRef..': Will try and kill enemy ACU (via special micro logic)') end
                    elseif not(oACU:IsUnitState('Building')) and DoesACUWantToReturnToCoreBase(iPlateauOrZero, iLandOrWaterZone, tLZOrWZData, tLZOrWZTeamData, oACU) then
                        if  tLZOrWZTeamData[AiBotMap.subrefLZbCoreBase] and AiBotUtilities.IsTableEmpty(tLZOrWZTeamData[AiBotMap.reftoNearestDFEnemies]) == false then
                            if not(ConsiderRunningToGETemplate(oACU, tLZOrWZData, tLZOrWZTeamData, iPlateauOrZero)) then
                                local tRallyPoint, oClosestEnemy = GetPositionToRunFromNearestEnemy()
                                local iDistUntilACUCanAttackNearestEnemy
                                if oClosestEnemy then iDistUntilACUCanAttackNearestEnemy = AiBotUtilities.GetDistanceBetweenPositions(oClosestEnemy:GetPosition(), oACU:GetPosition()) - (oACU[AiBotUnitInfo.refiDFRange] or 0)
                                else iDistUntilACUCanAttackNearestEnemy = 1000
                                end
                                if bDebugMessages == true then LOG(sFunctionRef..': Will run from enarest enemy as are in core base unless we have run out of places to run and want to attack the enemy as it is almost in our range, Dist to closest enemy='..AiBotUtilities.GetDistanceBetweenPositions(oClosestEnemy:GetPosition(), oACU:GetPosition())..'; iDistUntilACUCanAttackNearestEnemy='..iDistUntilACUCanAttackNearestEnemy..'; Dist to rally='..AiBotUtilities.GetDistanceBetweenPositions(oACU:GetPosition(), tRallyPoint)) end
                                if iDistUntilACUCanAttackNearestEnemy < 6 and iDistUntilACUCanAttackNearestEnemy >= -1 and AiBotUtilities.GetDistanceBetweenPositions(oACU:GetPosition(), tRallyPoint) < 12 - iDistUntilACUCanAttackNearestEnemy then
                                    AiBotOrders.IssueTrackedAggressiveMove(oACU, oClosestEnemy:GetPosition(), 3, false, 'CantRun')
                                else
                                    AiBotOrders.IssueTrackedMove(oACU, tRallyPoint, 5, false, 'RunNrEcb')
                                end
                            end
                        else
                            ConsiderIfACUNeedsEmergencySupport(iPlateauOrZero, iLandOrWaterZone, tLZOrWZData, tLZOrWZTeamData, oACU)
                            if not(ConsiderRunningToGETemplate(oACU, tLZOrWZData, tLZOrWZTeamData, iPlateauOrZero)) then
                                if bDebugMessages == true then LOG(sFunctionRef..': ACU more than 10 from core base midpoint so will retreat there, ACU dist to this midpoint='..AiBotUtilities.GetDistanceBetweenPositions(oACU:GetPosition(), tLZOrWZData[AiBotMap.subrefMidpoint])..'; Is this core base='..tostring(tLZOrWZTeamData[AiBotMap.subrefLZbCoreBase])) end
                                if not(ConsiderRunningToNearestShield(oACU, tLZOrWZData, tLZOrWZTeamData, iTeam, iPlateauOrZero, iLandOrWaterZone)) then
                                    ReturnACUToCoreBase(oACU, tLZOrWZData, tLZOrWZTeamData, aiBrain, iTeam, iPlateauOrZero, iLandOrWaterZone)
                                    if bDebugMessages == true then LOG(sFunctionRef..': Going to core base') end
                                end
                            elseif bDebugMessages == true then LOG(sFunctionRef..': Will run to GE template')
                            end
                        end
                    elseif DoesACUWantToRun(iPlateauOrZero, iLandOrWaterZone, tLZOrWZData, tLZOrWZTeamData, oACU) and
                            (not(tLZOrWZTeamData[AiBotMap.subrefLZbCoreBase]) or AiBotUnitInfo.GetUnitHealthPercent(oACU) <= 0.7
                                    or (AiBotTeam.tTeamData[iTeam][AiBotTeam.refbAssassinationOrSimilar] and (AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiActiveAiBotBrainCount] >= 2 or AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossMass] >= 1.3 * AiBotConditions.GetEnemyTeamActualMassIncome(iTeam)))
                                    or (AiBotUtilities.IsTableEmpty(AiBotTeam.tTeamData[iTeam][AiBotTeam.reftEnemyLandExperimentals]) == false and AiBotTeam.tLandSubteamData[aiBrain.AiBotLandSubteam][AiBotTeam.refiEnemyMobileDFThreatNearOurSide] >= 5000 and AiBotConditions.CloseToEnemyUnit(oACU:GetPosition(), AiBotTeam.tTeamData[iTeam][AiBotTeam.reftEnemyLandExperimentals], 80, iTeam, true, nil, nil, nil, nil, nil)))

                    then --and AiBotUtilities.GetDistanceBetweenPositions(oACU:GetPosition(), tLZOrWZData[AiBotMap.subrefMidpoint]) <= 10) then
                        local tRallyPoint
                        local bConsiderMexesAndReclaim = false
                        if not(ConsiderRunningToGETemplate(oACU, tLZOrWZData, tLZOrWZTeamData, iPlateauOrZero)) then
                            ConsiderIfACUNeedsEmergencySupport(iPlateauOrZero, iLandOrWaterZone, tLZOrWZData, tLZOrWZTeamData, oACU)
                            oACU[refiTimeLastWantedToRun] = GetGameTimeSeconds()

                            --If are in core zone then run from nearest enemy
                            if bDebugMessages == true then LOG(sFunctionRef..': Is table of nearest DF enemies empty='..tostring(AiBotUtilities.IsTableEmpty(tLZOrWZTeamData[AiBotMap.reftoNearestDFEnemies]))..'; Core base='..tostring(tLZOrWZTeamData[AiBotMap.subrefLZbCoreBase])) end
                            local bGoToWaterRally = false
                            if tLZOrWZTeamData[AiBotMap.subrefLZbCoreBase] and AiBotUtilities.IsTableEmpty(tLZOrWZTeamData[AiBotMap.reftoNearestDFEnemies]) == false and (AiBotUnitInfo.GetUnitHealthPercent(oACU) < 0.9 or AiBotTeam.tTeamData[iTeam][AiBotTeam.refbAssassinationOrSimilar]) then
                                tRallyPoint = GetPositionToRunFromNearestEnemy()
                                if bDebugMessages == true then LOG(sFunctionRef..'; Rally point is based on running from the nearest enemy, angle to rally point='..AiBotUtilities.GetAngleFromAToB(oACU:GetPosition(), tRallyPoint)) end
                            else
                                --Retreat to nearest rally (unless we arent in a land zone in which case head towards core base)

                                if iLandOrWaterZone > 0 and iPlateauOrZero > 0 then
                                    --Are we on a different island to our base, and want to move back there?

                                    tRallyPoint = AiBotLand.GetNearestLandRallyPoint(tLZOrWZData, iTeam, iPlateauOrZero, iLandOrWaterZone, 2, true)
                                    --If the rally point takes us further away from the closest friendly base, and is more than 50 from the closest friendly base, then head towards the base (exception if rally point is a core base or is a location with friendly PD and/or factories or significantly friendly combat)
                                    if bDebugMessages == true then LOG(sFunctionRef..': tRallyPoint='..repru(tRallyPoint)..' for P'..iPlateauOrZero..'Z'..iLandOrWaterZone..'; ACU position='..repru(oACU:GetPosition())..'; ACU angle to rally='..AiBotUtilities.GetAngleFromAToB(oACU:GetPosition(), tRallyPoint)..'; Dist from rally to closest friendly base='..AiBotUtilities.GetDistanceBetweenPositions(tRallyPoint, tLZOrWZTeamData[AiBotMap.reftClosestFriendlyBase])) end
                                    if AiBotUtilities.GetDistanceBetweenPositions(tRallyPoint, tLZOrWZTeamData[AiBotMap.reftClosestFriendlyBase]) >= 50 then
                                        local iDistToBase = AiBotUtilities.GetDistanceBetweenPositions(tLZOrWZData[AiBotMap.subrefMidpoint], tLZOrWZTeamData[AiBotMap.reftClosestFriendlyBase])
                                        if bDebugMessages == true then LOG(sFunctionRef..': Will switch to running to base if base relatively close and rally point a dif angle, iDistToBase='..iDistToBase..'; Mod dist%='..tLZOrWZTeamData[AiBotMap.refiModDistancePercent]..'; Angle dif='..AiBotUtilities.GetAngleDifference(AiBotUtilities.GetAngleFromAToB(oACU:GetPosition(), tRallyPoint), AiBotUtilities.GetAngleFromAToB(oACU:GetPosition(), tLZOrWZTeamData[AiBotMap.reftClosestFriendlyBase]))) end
                                        if iDistToBase <= 250 and tLZOrWZTeamData[AiBotMap.refiModDistancePercent] <= 0.6 and AiBotUtilities.GetAngleDifference(AiBotUtilities.GetAngleFromAToB(oACU:GetPosition(), tRallyPoint), AiBotUtilities.GetAngleFromAToB(oACU:GetPosition(), tLZOrWZTeamData[AiBotMap.reftClosestFriendlyBase])) >= 35 then
                                            if AiBotUnitInfo.GetUnitHealthPercent(oACU) >= 0.8 then bConsiderMexesAndReclaim = true end

                                            --Consider friendly base if it isnt dangerous
                                            if AiBotConditions.BaseIsSafeToRetreatTo(tLZOrWZTeamData[AiBotMap.reftClosestFriendlyBase], iTeam) then
                                                tRallyPoint = {tLZOrWZTeamData[AiBotMap.reftClosestFriendlyBase][1], tLZOrWZTeamData[AiBotMap.reftClosestFriendlyBase][2], tLZOrWZTeamData[AiBotMap.reftClosestFriendlyBase][3]}
                                                if bDebugMessages == true then LOG(sFunctionRef..': Will have ACU retreat to closest friendly base, angle to closest friendly base='..AiBotUtilities.GetAngleFromAToB(oACU:GetPosition(), tRallyPoint)) end
                                            end
                                        else

                                            local tRallyLZData, tRallyLZTeamData = AiBotMap.GetLandOrWaterZoneData(tRallyPoint, true, iTeam)

                                            if not(tRallyLZTeamData[AiBotMap.subrefLZbCoreBase]) then
                                                local iRallyThreat = (tRallyLZTeamData[AiBotMap.subrefLZTThreatAllyCombatTotal] or 0)
                                                if tRallyLZTeamData == tLZOrWZTeamData then iRallyThreat = iRallyThreat - AiBotUnitInfo.GetCombatThreatRating({oACU}, false, false, false, false, false, false, false, false) end
                                                if bDebugMessages == true then LOG(sFunctionRef..': Rally point is more than 50 from closest friendly base, checking if threat is too low, iRallyThreat='..iRallyThreat..'; Is rally in a core expansion='..tostring(tRallyLZTeamData[AiBotMap.subrefLZCoreExpansion])) end
                                                if iRallyThreat <= 500 and (not(tRallyLZTeamData[AiBotMap.subrefLZCoreExpansion]) or tRallyLZTeamData[AiBotMap.subrefLZSValue] < 220) then --Only consider core expansion if it has significant structure value, e.g. similar to having 1 land factory
                                                    if bDebugMessages == true then LOG(sFunctionRef..': Dist from rally to closest base='..AiBotUtilities.GetDistanceBetweenPositions(tRallyLZTeamData[AiBotMap.reftClosestFriendlyBase], tRallyLZData[AiBotMap.subrefMidpoint])..'; Dist from ACU to closest base='..AiBotUtilities.GetDistanceBetweenPositions(tLZOrWZTeamData[AiBotMap.reftClosestFriendlyBase], oACU:GetPosition())) end
                                                    if AiBotUtilities.GetDistanceBetweenPositions(tRallyLZTeamData[AiBotMap.reftClosestFriendlyBase], tRallyLZData[AiBotMap.subrefMidpoint]) > AiBotUtilities.GetDistanceBetweenPositions(tLZOrWZTeamData[AiBotMap.reftClosestFriendlyBase], oACU:GetPosition()) then
                                                        bConsiderMexesAndReclaim = false
                                                        --Is our closest friendly base in the same plateau?
                                                        local iClosestBasePlateauOrZero, iClosestBaseLandOrWaterZone = AiBotMap.GetClosestPlateauOrZeroAndZoneToPosition(tLZOrWZTeamData[AiBotMap.reftClosestFriendlyBase])
                                                        if iClosestBasePlateauOrZero == iPlateauOrZero and AiBotConditions.BaseIsSafeToRetreatTo(tLZOrWZTeamData[AiBotMap.reftClosestFriendlyBase], iTeam)  then
                                                            tRallyPoint = {tLZOrWZTeamData[AiBotMap.reftClosestFriendlyBase][1], tLZOrWZTeamData[AiBotMap.reftClosestFriendlyBase][2], tLZOrWZTeamData[AiBotMap.reftClosestFriendlyBase][3]}
                                                            if bDebugMessages == true then LOG(sFunctionRef..': Changed rally point to be the closest friendly base, angle to this='..AiBotUtilities.GetAngleFromAToB(oACU:GetPosition(), tRallyPoint)) end
                                                        end
                                                    end
                                                else
                                                    if bDebugMessages == true then LOG(sFunctionRef..': Checking if rally LZ is same as ACU LZ, are they equal='..tostring(tRallyLZData == tLZOrWZData)) end
                                                    if tRallyLZData == tLZOrWZData then
                                                        if bDebugMessages == true then LOG(sFunctionRef..': ACU health%='..AiBotUnitInfo.GetUnitHealthPercent(oACU)..'; iRallyThreat='..iRallyThreat) end
                                                        if AiBotUnitInfo.GetUnitHealthPercent(oACU) >= 0.5 and iRallyThreat < 100 then
                                                            if bDebugMessages == true then LOG(sFunctionRef..': Want to consider mexes and reclaim') end
                                                            bConsiderMexesAndReclaim= true
                                                        end
                                                    end
                                                end
                                            end
                                        end
                                        if bConsiderMexesAndReclaim then
                                            --If have DF enemies in our range or their range then dont consider reclaim
                                            local iCurEnemyDist
                                            if AiBotUtilities.IsTableEmpty(tLZOrWZTeamData[AiBotMap.reftoNearestDFEnemies]) == false then
                                                for iEnemy, oEnemy in tLZOrWZTeamData[AiBotMap.reftoNearestDFEnemies] do
                                                    if AiBotUnitInfo.IsUnitValid(oEnemy) then
                                                        iCurEnemyDist = AiBotUtilities.GetDistanceBetweenPositions(oEnemy:GetPosition(), oACU:GetPosition())
                                                        if iCurEnemyDist < math.max((oACU[AiBotUnitInfo.refiDFRange] or 0), oEnemy[AiBotUnitInfo.refiDFRange] or 0) then
                                                            if bDebugMessages == true then LOG(sFunctionRef..': Enemy '..oEnemy.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oEnemy)..' is only '..iCurEnemyDist..' away from us so wont consider mex building or reclaim after all') end
                                                            bConsiderMexesAndReclaim = false
                                                            break
                                                        end
                                                    end
                                                end
                                            end
                                            if bConsiderMexesAndReclaim and AiBotUtilities.IsTableEmpty(tLZOrWZTeamData[AiBotMap.subrefoNearbyEnemyLongRangeDFThreats]) == false then
                                                for iEnemy, oEnemy in tLZOrWZTeamData[AiBotMap.subrefoNearbyEnemyLongRangeDFThreats] do
                                                    if AiBotUnitInfo.IsUnitValid(oEnemy) then
                                                        iCurEnemyDist = AiBotUtilities.GetDistanceBetweenPositions(oEnemy:GetPosition(), oACU:GetPosition())
                                                        if iCurEnemyDist < math.max((oACU[AiBotUnitInfo.refiDFRange] or 0), oEnemy[AiBotUnitInfo.refiDFRange] or 0) + 5 then
                                                            if bDebugMessages == true then LOG(sFunctionRef..': Enemy '..oEnemy.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oEnemy)..' is only '..iCurEnemyDist..' away from us so wont consider mex building or reclaim after all') end
                                                            bConsiderMexesAndReclaim = false
                                                            break
                                                        end
                                                    end
                                                end
                                            end
                                        end
                                    end
                                    --[[GetTravelDistanceBetweenPositions(tStart, tEnd, sPathing)
                                    local iTravelDistFromRallyToClosestFriendlyBase

                                     = AiBotUtilities.GetTravelDist--]]


                                else
                                    --Are in water - if we make landfall will we just die, and are better staying in water? Check for nearby enemy antinavy first as if enemy has antinavy then should surface
                                    if AiBotUtilities.IsTableEmpty(tLZOrWZData[AiBotMap.subrefAdjacentLandZones]) == false and AiBotUnitInfo.GetUnitHealthPercent(oACU) < 0.75 then
                                        local iNearbyAntiNavy = (tLZOrWZTeamData[AiBotMap.subrefWZThreatEnemyAntiNavy] or 0)
                                        if iNearbyAntiNavy == 0 and AiBotUtilities.IsTableEmpty(tLZOrWZData[AiBotMap.subrefWZAdjacentWaterZones]) == false then
                                            for iEntry, tSubtable in tLZOrWZData[AiBotMap.subrefWZAdjacentWaterZones] do
                                                local iAdjWZ = tSubtable[AiBotMap.subrefAWZRef]
                                                iNearbyAntiNavy = iNearbyAntiNavy + (AiBotMap.tPondDetails[AiBotMap.tiPondByWaterZone[iAdjWZ]][AiBotMap.subrefPondWaterZones][iAdjWZ][AiBotMap.subrefWZTeamData][iTeam][AiBotMap.subrefWZThreatEnemyAntiNavy] or 0)
                                                if iNearbyAntiNavy > 0 then break end
                                            end
                                        end
                                        if bDebugMessages == true then LOG(sFunctionRef..': iNearbyAntiNavy='..iNearbyAntiNavy..'; is subrefAdjacentLandZones empty (it will be if this is a LZ)='..tostring(AiBotUtilities.IsTableEmpty(tLZOrWZData[AiBotMap.subrefAdjacentLandZones]))) end
                                        if iNearbyAntiNavy == 0 then
                                            --Does enemy have combat on an adjacent land zone
                                            if AiBotUtilities.IsTableEmpty(tLZOrWZData[AiBotMap.subrefAdjacentLandZones]) == false then
                                                local iNearbyEnemyNetLandThreat = 0
                                                for iEntry, tSubtable in tLZOrWZData[AiBotMap.subrefAdjacentLandZones] do
                                                    local tAdjLZ = AiBotMap.tAllPlateaus[tSubtable[AiBotMap.subrefWPlatAndLZNumber][1]][AiBotMap.subrefPlateauLandZones][tSubtable[AiBotMap.subrefWPlatAndLZNumber][2]]
                                                    local tAdjLZTeamData = tAdjLZ[AiBotMap.subrefLZTeamData][iTeam]
                                                    iNearbyEnemyNetLandThreat = iNearbyEnemyNetLandThreat + (tAdjLZTeamData[AiBotMap.subrefLZThreatEnemyMobileDFTotal] or 0) + (tAdjLZTeamData[AiBotMap.subrefThreatEnemyDFStructures] or 0) - (tAdjLZTeamData[AiBotMap.subrefLZTThreatAllyCombatTotal] or 0)
                                                end
                                                if bDebugMessages == true then LOG(sFunctionRef..': iNearbyEnemyNetLandThreat='..iNearbyEnemyNetLandThreat..'; Our ACU threat='..AiBotUnitInfo.GetCombatThreatRating({ oACU}, false, false)) end
                                                if iNearbyEnemyNetLandThreat > 500 and iNearbyEnemyNetLandThreat > AiBotUnitInfo.GetCombatThreatRating({ oACU}, false, false) then
                                                    if bDebugMessages == true then LOG(sFunctionRef..': Will go to water rally instead as worried ACU will die if it makes landfall') end
                                                    bGoToWaterRally = true
                                                end
                                            end
                                        end
                                    end
                                    if bGoToWaterRally then
                                        tRallyPoint = (AiBotNavy.GetNearestWaterRallyPoint(tLZOrWZData, iTeam, AiBotMap.tiPondByWaterZone[iLandOrWaterZone], iLandOrWaterZone) or AiBotMap.GetPlayerStartPosition(oACU:GetAIBrain()))
                                        if bDebugMessages == true then LOG(sFunctionRef..': Will retreat to nearest water rally instead of base, angle to this='..AiBotUtilities.GetAngleFromAToB(oACU:GetPosition(), tRallyPoint)) end
                                    else

                                        tRallyPoint = AiBotMap.GetPlayerStartPosition(oACU:GetAIBrain())
                                        if bDebugMessages == true then LOG(sFunctionRef..': Will retreat to ACU start position, angle to this='..AiBotUtilities.GetAngleFromAToB(oACU:GetPosition(), tRallyPoint)) end
                                    end
                                end
                            end

                            --If enemy has nearby exp then run in opposite direction (rather tahn going to rally point) if rally point isn't much further away from the exp, unless we are already in range of the EXP (since we might as well then consider overcharging it)
                            local bHaveNearbyExperimentalOrder = false
                            if bDebugMessages == true then LOG(sFunctionRef..': Is table of enemy land exp empty='..tostring(AiBotUtilities.IsTableEmpty(AiBotTeam.tTeamData[iTeam][AiBotTeam.reftEnemyLandExperimentals]))) end
                            if AiBotUtilities.IsTableEmpty(AiBotTeam.tTeamData[iTeam][AiBotTeam.reftEnemyLandExperimentals]) == false then
                                local iClosestEnemyExp = 165
                                if tLZOrWZTeamData[AiBotMap.subrefLZTThreatAllyCombatTotal] >= 20000 then iClosestEnemyExp = 140 end
                                local oClosestEnemyExp, iCurDist
                                for iExp, oExp in AiBotTeam.tTeamData[iTeam][AiBotTeam.reftEnemyLandExperimentals] do
                                    if AiBotUnitInfo.IsUnitValid(oExp) then
                                        iCurDist = AiBotUtilities.GetDistanceBetweenPositions(oExp:GetPosition(), oACU:GetPosition())
                                        if bDebugMessages == true then LOG(sFunctionRef..': Considering enemy land exp '..oExp.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oExp)..'; iCurDist='..iCurDist..'; Unit range='..(oExp[AiBotUnitInfo.refiDFRange] or 0)) end
                                        if iCurDist < iClosestEnemyExp then
                                            iClosestEnemyExp = iCurDist
                                            oClosestEnemyExp = oExp
                                        end
                                    end
                                end
                                --If enemy has land exp near us but we arent already in range of it then run in the opopsite direction
                                if oClosestEnemyExp then
                                    if iClosestEnemyExp > math.max((oACU[AiBotUnitInfo.refiDFRange] or 0), (oClosestEnemyExp[AiBotUnitInfo.refiDFRange] or 0) + 2) then
                                        --Is the rally point taking us further away from this?
                                        local iRallyPointDist = AiBotUtilities.GetDistanceBetweenPositions(oClosestEnemyExp:GetPosition(), tRallyPoint)
                                        local iAngleFromACUToExp = AiBotUtilities.GetAngleFromAToB(oACU:GetPosition(), oClosestEnemyExp:GetPosition())
                                        local iAngleToRally = AiBotUtilities.GetAngleFromAToB(oACU:GetPosition(), tRallyPoint)
                                        local iAngleDif = AiBotUtilities.GetAngleDifference(iAngleFromACUToExp, iAngleToRally)
                                        if bDebugMessages == true then LOG(sFunctionRef..': Considering if we want ACU to run from enemy EXP, oClosestEnemyExp='..oClosestEnemyExp.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oClosestEnemyExp)..'; iClosestEnemyExp='..iClosestEnemyExp..'; iAngleFromACUToExp='..iAngleFromACUToExp..'; iRallyPointDist='..iRallyPointDist..'; Angle to rally='..AiBotUtilities.GetAngleFromAToB(oACU:GetPosition(), tRallyPoint)..'; Dist to rally='..AiBotUtilities.GetDistanceBetweenPositions(oACU:GetPosition(), tRallyPoint)..'; iAngleDif='..iAngleDif) end
                                        if (iRallyPointDist <= 30 + iClosestEnemyExp and (AiBotUtilities.GetDistanceBetweenPositions(oACU:GetPosition(), tRallyPoint) <= 30 or iAngleDif <= 110))
                                                or (iAngleDif <= 130 and iClosestEnemyExp <= 95) then
                                            local tAltRallyPoint = AiBotUtilities.MoveInDirection(oACU:GetPosition(), iAngleFromACUToExp-180, 15, true, true, true)
                                            if AiBotUtilities.IsTableEmpty(tAltRallyPoint) == false and NavUtils.GetLabel(AiBotMap.refPathingTypeHover, tAltRallyPoint) == NavUtils.GetLabel(AiBotMap.refPathingTypeHover, oACU:GetPosition()) then
                                                bHaveNearbyExperimentalOrder = true
                                                if bDebugMessages == true then LOG(sFunctionRef..': Will run to alt rally point') end
                                                AiBotOrders.IssueTrackedMove(oACU, tAltRallyPoint, 5, false, 'RunExp')
                                            end
                                        elseif iAngleDif <= 150 and iClosestEnemyExp <= 105 then
                                            --Go halfway between opposite direction to enemy Exp, and the angle to rally point
                                            local iInitialAngleWanted = iAngleFromACUToExp-180
                                            local iAngleMod =  AiBotUtilities.GetAngleDifference(iAngleToRally, iInitialAngleWanted) * 0.5
                                            if iInitialAngleWanted > iAngleToRally then
                                                if iInitialAngleWanted < iAngleToRally + 180 then
                                                    --Want to decrease by iAngleMod as we are larger but not so much so that we should reduce angle
                                                    iAngleMod = iAngleMod * -1
                                                else
                                                    --Increase by angle - we are larger, and by so much that incresing makes us get closer
                                                end
                                            else
                                                if iInitialAngleWanted + 180 < iAngleToRally then
                                                    iAngleMod = iAngleMod * -1
                                                end
                                            end
                                            if bDebugMessages == true then LOG(sFunctionRef..': iInitialAngleWanted='..iInitialAngleWanted..'; iAngleMod='..iAngleMod) end
                                            local tAltRallyPoint = AiBotUtilities.MoveInDirection(oACU:GetPosition(), iInitialAngleWanted + iAngleMod, 15, true, true, true)
                                            if AiBotUtilities.IsTableEmpty(tAltRallyPoint) == false and NavUtils.GetLabel(AiBotMap.refPathingTypeHover, tAltRallyPoint) == NavUtils.GetLabel(AiBotMap.refPathingTypeHover, oACU:GetPosition()) then
                                                bHaveNearbyExperimentalOrder = true
                                                if bDebugMessages == true then LOG(sFunctionRef..': Will run to alternative rally point inbetween opposite direction to exp and cur rally point') end
                                                AiBotOrders.IssueTrackedMove(oACU, tAltRallyPoint, 5, false, 'RunExp')
                                            end
                                        end
                                    else
                                        if not(ConsiderRunningToNearestShield(oACU, tLZOrWZData, tLZOrWZTeamData, iTeam, iPlateauOrZero, iLandOrWaterZone)) then
                                            bHaveNearbyExperimentalOrder = true
                                            if bDebugMessages == true then LOG(sFunctionRef..': Will run to nearby shield') end
                                        else
                                            if iClosestEnemyExp <= (oACU[AiBotUnitInfo.refiDFRange] or 0) + 17 and AiBotConditions.CanUnitUseOvercharge(oACU:GetAIBrain(), oACU, tLZOrWZTeamData) then --e.g. up against ythotha, gc or monkeylord - want to try and get in range to overcharge since we are now in range
                                                --We dont have nearby shield to retreat to, and are in range of the enemy EXP, but we can overcharge it
                                                bHaveNearbyExperimentalOrder = true
                                                AiBotOrders.IssueTrackedMove(oACU, oClosestEnemyExp:GetPosition(), 5, false, 'RnAtkExp')
                                                if bDebugMessages == true then LOG(sFunctionRef..': Will attack Exp in case we can overcharge it') end
                                            end
                                        end
                                    end
                                end
                            end


                            --If we are already in the zone for the rally point and it has unbuilt mexes or significant reclaim then want to consider getting them; otherwise go to nearest friendly base
                            if not(bHaveNearbyExperimentalOrder) and (not(bConsiderMexesAndReclaim) or (not(ConsiderBuildingMex(tLZOrWZData, tLZOrWZTeamData, oACU, 15)) and not(ConsiderNearbyReclaimForACUOrEngineer(iPlateauOrZero, iLandOrWaterZone, tLZOrWZData, tLZOrWZTeamData, oACU, AiBotUnitInfo.GetUnitHealthPercent(oACU) < 0.75, 20)))) then

                                --Consider using old rally point if new one is further from base and <60s since we have retreated
                                if oACU[reftLastRallyPointRanTo] and oACU[refiTimeLastWantedToRun] and GetGameTimeSeconds() - oACU[refiTimeLastWantedToRun] <= 60 then
                                    local iCurDistToBase = AiBotUtilities.GetDistanceBetweenPositions(tRallyPoint, tLZOrWZTeamData[AiBotMap.reftClosestFriendlyBase])
                                    local iPreviousDistToBase = AiBotUtilities.GetDistanceBetweenPositions(oACU[reftLastRallyPointRanTo], tLZOrWZTeamData[AiBotMap.reftClosestFriendlyBase])
                                    if bDebugMessages == true then LOG(sFunctionRef..': Considering using old rally point if its closer to our base than current rally point, iCurDistToBase='..iCurDistToBase..'; iPreviousDistToBase='..iPreviousDistToBase) end
                                    if iCurDistToBase - 5 > iPreviousDistToBase then
                                        local tOldRallyLZData, tOldRallyLZTeamData = AiBotMap.GetLandOrWaterZoneData(oACU[reftLastRallyPointRanTo], true, iTeam)
                                        if tOldRallyLZTeamData and not(tOldRallyLZTeamData[AiBotMap.subrefbDangerousEnemiesInThisLZ]) then
                                            tRallyPoint = {oACU[reftLastRallyPointRanTo][1], oACU[reftLastRallyPointRanTo][2], oACU[reftLastRallyPointRanTo][3]}
                                            if bDebugMessages == true then LOG(sFunctionRef..': Switching to old rally point') end
                                        end
                                    end
                                end
                                if not(bGoToWaterRally) and AiBotTeam.tTeamData[iTeam][AiBotTeam.refbDangerousForACUs] and AiBotConditions.BaseIsSafeToRetreatTo(tLZOrWZTeamData[AiBotMap.reftClosestFriendlyBase], iTeam) then
                                    if bDebugMessages == true then LOG(sFunctionRef..': Dangerous for ACUs and base is safe to retreat to, so changing rally point to the closest friendly base') end
                                    tRallyPoint = {tLZOrWZTeamData[AiBotMap.reftClosestFriendlyBase][1], tLZOrWZTeamData[AiBotMap.reftClosestFriendlyBase][2], tLZOrWZTeamData[AiBotMap.reftClosestFriendlyBase][3]}
                                end
                                local bFactoryInWay = false
                                if AiBotUtilities.GetDistanceBetweenPositions(oACU:GetPosition(), tRallyPoint) <= 25 then
                                    bFactoryInWay = AiBotConditions.IsPositionInWayOfFactory(tRallyPoint)
                                end
                                if bDebugMessages == true then LOG(sFunctionRef..': Will retreat to base unless would be blocking a factory, bFactoryInWay='..tostring(bFactoryInWay)) end
                                if bFactoryInWay then
                                    local iAngleFromEnemyBase = AiBotUtilities.GetAngleFromAToB(tLZOrWZTeamData[AiBotMap.reftClosestEnemyBase], tRallyPoint)
                                    local tPositionToRunTo
                                    local iPlateauWanted
                                    if iPlateauOrZero == 0 then iPlateauWanted = NavUtils.GetTerrainLabel(AiBotMap.refPathingTypeHover, oACU:GetPosition())
                                    else iPlateauWanted = iPlateauOrZero end

                                    for iDist = 4, 24, 4 do
                                        tPositionToRunTo = AiBotUtilities.MoveInDirection(tRallyPoint, iAngleFromEnemyBase, iDist, true, true, AiBotMap.bIsCampaignMap)
                                        if bDebugMessages == true then LOG(sFunctionRef..': Trying to find position on same plateau not blocked by factory, iDist='..iDist..'; Plateau of tPositionToRunTo='..(NavUtils.GetTerrainLabel(AiBotMap.refPathingTypeHover, tPositionToRunTo) or 'nil')..'; iPlateauWanted='..(iPlateauWanted or 'nil')..'; Is it in way of  factory='..tostring(AiBotConditions.IsPositionInWayOfFactory(tPositionToRunTo) or false)) end
                                        if tPositionToRunTo and NavUtils.GetTerrainLabel(AiBotMap.refPathingTypeHover, tPositionToRunTo) == iPlateauWanted then
                                            bFactoryInWay = AiBotConditions.IsPositionInWayOfFactory(tPositionToRunTo)
                                            if not(bFactoryInWay) then break end
                                        end
                                    end
                                    if bDebugMessages == true then LOG(sFunctionRef..': bFactoryInWay after trying to find alternative location='..tostring(bFactoryInWay)) end
                                    if not(bFactoryInWay) then tRallyPoint = {tPositionToRunTo[1], tPositionToRunTo[2], tPositionToRunTo[3]} end
                                end


                                if not(AiBotTeam.tTeamData[iTeam][AiBotTeam.refbDangerousForACUs]) and iPlateauOrZero > 0 and AiBotUtilities.IsTableEmpty(tLZOrWZTeamData[AiBotMap.reftoNearestDFEnemies]) == false and AiBotConditions.GiveAttackMoveAsWeaponStuck(oACU) and AiBotConditions.CloseToEnemyUnit(oACU:GetPosition(), tLZOrWZTeamData[AiBotMap.reftoNearestDFEnemies], oACU[AiBotUnitInfo.refiCombatRange], iTeam, false, nil, nil, nil, nil, nil) then
                                    AiBotOrders.IssueTrackedAttackMove(oACU, tRallyPoint, 5, false, 'RunARP')
                                else
                                    --if not(ACUStuckAndGivenIntermediateMovePoint(oACU, tRallyPoint)) then --Function didnt actually help ACU get unstuck in one replay where it got stuck, but might in other scenario
                                    AiBotOrders.IssueTrackedMove(oACU, tRallyPoint, 5, false, 'RunRP')
                                    --end

                                end
                                oACU[reftLastRallyPointRanTo] = {tRallyPoint[1], tRallyPoint[2], tRallyPoint[3]}
                                if bDebugMessages == true then LOG(sFunctionRef..': Telling ACU to run; aACU orders after this='..reprs(oACU[AiBotOrders.reftiLastOrders])..'; Is micro active='..tostring(oACU[AiBotUnitInfo.refbSpecialMicroActive])..'; Nearest land rally point='..repru(AiBotLand.GetNearestLandRallyPoint(tLZOrWZData, iTeam, iPlateauOrZero, iLandOrWaterZone, 2, true))..'; P'..iPlateauOrZero..'Z'..iLandOrWaterZone..'; Rally point='..repru(tRallyPoint)..'; Nearest friendly base='..repru(AiBotMap.GetPlayerStartPosition(oACU:GetAIBrain()))..'; Dist from rally point to friendly base='..AiBotUtilities.GetDistanceBetweenPositions(tRallyPoint, AiBotMap.GetPlayerStartPosition(oACU:GetAIBrain()))..'; Dist from ACU to rally point='..AiBotUtilities.GetDistanceBetweenPositions(oACU:GetPosition(), tRallyPoint)) end
                            end
                        elseif bDebugMessages == true then LOG(sFunctionRef..': Will run to GE template')
                        end
                    else
                        --ACU is being used as an engineer?
                        if oACU[refiBuildTech] > 1 and ((oACU[refiBuildTech] >= aiBrain[AiBotEconomy.refiOurHighestFactoryTechLevel] and ((oACU[refiBuildTech] > aiBrain[AiBotEconomy.refiOurHighestFactoryTechLevel] and AiBotUtilities.IsTableEmpty(tLZOrWZTeamData[AiBotMap.reftoNearestDFEnemies])) or not(tLZOrWZTeamData[AiBotMap.subrefbEnemiesInThisOrAdjacentLZ]))) or (oACU[AiBotUnitInfo.refiDFRange] or 0) <= 24) and HaveActionForACUAsEngineer(oACU, tLZOrWZData, tLZOrWZTeamData, iPlateauOrZero, iLandOrWaterZone) then
                            if bDebugMessages == true then LOG(sFunctionRef..': Are using ACU more as an engineer') end
                        else
                            --Snipe mode
                            if bDebugMessages == true then LOG(sFunctionRef..': Considering if we want to use ACU to attack a snipe target, is table of snipe targets empty='..tostring(AiBotUtilities.IsTableEmpty(AiBotTeam.tTeamData[iTeam][AiBotTeam.toActiveSnipeTargets]))..'; HaveRecentCommonACUTarget='..tostring(HaveRecentCommonACUTarget(oACU))) end
                            if (AiBotUtilities.IsTableEmpty(AiBotTeam.tTeamData[iTeam][AiBotTeam.toActiveSnipeTargets]) or not(HaveACUSnipeAction(oACU, iTeam, iPlateauOrZero, iLandOrWaterZone, tLZOrWZData, tLZOrWZTeamData))) and not(HaveRecentCommonACUTarget(oACU)) and not(AttackNearestEnemyWithACU(iPlateauOrZero, iLandOrWaterZone, tLZOrWZData, tLZOrWZTeamData, oACU)) then
                                --Nearby enemy naval units
                                if bDebugMessages == true then LOG(sFunctionRef..': Considering if nearby naval units that should send ACU to try and fight; AiBotTeam.tAirSubteamData[aiBrain.AiBotAirSubteam][AiBotTeam.refbNoAvailableTorpsForEnemies] ='..tostring(AiBotTeam.tAirSubteamData[aiBrain.AiBotAirSubteam][AiBotTeam.refbNoAvailableTorpsForEnemies])..'; ACU health='..AiBotUnitInfo.GetUnitHealthPercent(oACU)..'; Is table of adjacent WZs empty='..tostring(AiBotUtilities.IsTableEmpty(tLZOrWZData[AiBotMap.subrefAdjacentWaterZones]))) end
                                local iWaterZoneEnemyRangeOverride
                                if AiBotUnitInfo.GetUnitHealthPercent(oACU) <= 0.3 then iWaterZoneEnemyRangeOverride = 10 end
                                --if ACU has torp upgrade but lacks stealth, then consider getting stealth upgrade when in water
                                if oACU[refiUpgradeCount] == 1 and oACU[AiBotUnitInfo.refiAntiNavyRange] and iPlateauOrZero == 0 and AiBotUnitInfo.IsUnitUnderwater(oACU) and not(AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefbTeamIsStallingEnergy]) and (AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiActiveAiBotBrainCount] >= 2 or (oACU[AiBotUnitInfo.refiLastWeaponEvent] and GetGameTimeSeconds() - oACU[AiBotUnitInfo.refiLastWeaponEvent] <= 5)) and tLZOrWZTeamData[AiBotMap.subrefWZThreatEnemyAntiNavy] <= 2000 and GetACUUpgradeWanted(oACU, nil, tLZOrWZData, tLZOrWZTeamData, iPlateauOrZero, true) == 'StealthGenerator' and (GetGameTimeSeconds() - (AiBotTeam.tTeamData[iTeam][AiBotTeam.refiTimeLastIssuedACUEnhancementOrder] or -100) >= 2 or oACU[AiBotOrders.reftiLastOrders][oACU[AiBotOrders.refiOrderCount]][AiBotOrders.subrefsOrderBlueprint] == 'StealthGenerator' or (oACU[AiBotOrders.refiTimeOfLastRemovalUpgrade] and GetGameTimeSeconds() - oACU[AiBotOrders.refiTimeOfLastRemovalUpgrade] <= 2)) then
                                    if bDebugMessages == true then LOG(sFunctionRef..': Get priority stealth upgrade as are underwater and can hopefully fire at enemy with torpedo while getting it') end
                                    AiBotOrders.IssueTrackedEnhancement(oACU, 'StealthGenerator', false, 'ACUWtSUpr')
                                elseif oACU[AiBotUnitInfo.refiAntiNavyRange] and oACU[AiBotUnitInfo.refiAntiNavyRange] > 10 and not(aiBrain[AiBotMap.refbCanPathToEnemyBaseWithLand]) and AiBotUnitInfo.GetUnitHealthPercent(oACU) >= 0.6 and ConsiderAttackingNearbyNavalUnits(tLZOrWZData, tLZOrWZTeamData, oACU) then
                                    if bDebugMessages == true then LOG(sFunctionRef..': ACU has torpedo upgrade so want to attack nearby enemy navla units') end
                                elseif iPlateauOrZero > 0 and AiBotTeam.tAirSubteamData[aiBrain.AiBotAirSubteam][AiBotTeam.refbNoAvailableTorpsForEnemies] and AiBotUtilities.IsTableEmpty(tLZOrWZData[AiBotMap.subrefAdjacentWaterZones]) == false and ConsiderAttackingNearbyNavalUnits(tLZOrWZData, tLZOrWZTeamData, oACU, iWaterZoneEnemyRangeOverride) then
                                    if bDebugMessages == true then LOG(sFunctionRef..': Telling ACU to attack nearby enemy navla units') end

                                else
                                    --Priority gun upgrade due to enemy getting upgrade (intended for 1v1 on smaller maps)
                                    local bGettingPriorityUpgrade = false
                                    if oACU[refbWantsPriorityUpgrade] and (not(oACU:IsUnitState('Building')) and not(oACU:IsUnitState('Capturing')) and (not(oACU:IsUnitState('Repairing')) or (oACU:IsUnitState('Guarding') and oACU:GetWorkProgress() > 0 and not(EntityCategoryContains(categories.MOBILE - categories.COMMAND - AiBotUnitInfo.categories.SUBCOMMANDER, oACU:GetFocusUnit().UnitId)))) and (not(oACU:IsUnitState('Reclaiming')) or aiBrain:GetEconomyStoredRatio('MASS') >= 0.8) and not(oACU:IsUnitState('Capturing'))) then
                                        --Do we want to get an upgrade?
                                        local sUpgradeToGet, bIgnoreOtherUpgradeConditions = GetACUUpgradeWanted(oACU, nil, tLZOrWZData, tLZOrWZTeamData, iPlateauOrZero, not(AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefbTeamIsStallingEnergy]))
                                        if bDebugMessages == true then LOG(sFunctionRef..': Do we have a priority upgrade we want to get? sUpgradeToGet='..(sUpgradeToGet or 'nil')) end
                                        if sUpgradeToGet then
                                            bGettingPriorityUpgrade = true
                                            --Do we have a friendly nearby ugprading ACU? If so then assist its upgrade first before getting ours
                                            if bIgnoreOtherUpgradeConditions or not(AssistNearbyUpgradingACU(iPlateauOrZero, iLandOrWaterZone, tLZOrWZData, tLZOrWZTeamData, oACU, 40)) then
                                                --Are we safe to get the upgrade here? if not then retreat
                                                if bDebugMessages == true then LOG(sFunctionRef..': Will check if safe to get priority upgrade for oACU, oACU='..(oACU.UnitId or 'nil')..(AiBotUnitInfo.GetUnitLifetimeCount(oACU) or 'nil')..'; Brain='..oACU:GetAIBrain().Nickname) end
                                                if bIgnoreOtherUpgradeConditions or AiBotConditions.SafeToUpgradeUnit(oACU) then
                                                    if bDebugMessages == true then LOG(sFunctionRef..': Safe to get priority upgrade here so will proceed with upgrading ACU, sUpgradeToGet='..(sUpgradeToGet or 'nil')..' brain='..oACU:GetAIBrain().Nickname..'; Has enhancement='..tostring(oACU:HasEnhancement(sUpgradeToGet))) end
                                                    if GetGameTimeSeconds() - (AiBotTeam.tTeamData[iTeam][AiBotTeam.refiTimeLastIssuedACUEnhancementOrder] or -100) >= 2 or (oACU[AiBotOrders.refiTimeOfLastRemovalUpgrade] and GetGameTimeSeconds() - oACU[AiBotOrders.refiTimeOfLastRemovalUpgrade] <= 10) or oACU[AiBotOrders.reftiLastOrders][oACU[AiBotOrders.refiOrderCount]][AiBotOrders.subrefsOrderBlueprint] == sUpgradeToGet then
                                                        AiBotOrders.IssueTrackedEnhancement(oACU, sUpgradeToGet, false, 'ACUUpr')
                                                    end
                                                else
                                                    --Retreat
                                                    local tRallyPoint = AiBotLand.GetNearestLandRallyPoint(tLZOrWZData, oACU:GetAIBrain().AiBotTeam, iPlateauOrZero, iLandOrWaterZone, 2)
                                                    if bDebugMessages == true then LOG(sFunctionRef..': Not safe to get priority upgrade so want to retreat until it is, going to nearest land rally point, P'..iPlateauOrZero..'Z'..iLandOrWaterZone..'; tRallyPoint='..repru(tRallyPoint)..'; ACU position='..repru(oACU:GetPosition())..'; Angle to this='..AiBotUtilities.GetAngleFromAToB(oACU:GetPosition(), tRallyPoint)) end
                                                    AiBotOrders.IssueTrackedMove(oACU, tRallyPoint, 5, false, 'R4UeNg')
                                                end
                                            end
                                        end
                                    end
                                    if not(bGettingPriorityUpgrade) then
                                        --Part-built or unbuilt mex in build range of ACU when no enemies in the LZ
                                        if bDebugMessages == true then LOG(sFunctionRef..': Will consider building mex if one is almost in build range and no enemy combat threat in this LZ/WZ, or we outrange enemy and enemy isnt in our range; threat='..tLZOrWZTeamData[AiBotMap.subrefTThreatEnemyCombatTotal]) end
                                        local bConsiderBuildingNearbyMex = true
                                        local iNearbyMexRangeThreshold = 2
                                        if tLZOrWZTeamData[AiBotMap.subrefTThreatEnemyCombatTotal] == 0 then
                                            --Do nothing - want to consider building mex
                                        elseif tLZOrWZTeamData[AiBotMap.subrefTThreatEnemyCombatTotal] > 200 then
                                            bConsiderBuildingNearbyMex = false
                                            if bDebugMessages == true then LOG(sFunctionRef..':Too much threat in this zone') end
                                        else
                                            --Enemy has small threat, so might want to build mex rather than attack
                                            if math.max((tLZOrWZTeamData[AiBotMap.subrefLZThreatEnemyBestMobileDFRange] or 0), (tLZOrWZTeamData[AiBotMap.subrefLZThreatEnemyBestStructureDFRange] or 0), (tLZOrWZTeamData[AiBotMap.subrefLZThreatEnemyBestMobileIndirectRange] or 0)) >= (oACU[AiBotUnitInfo.refiDFRange] or 0) then
                                                bConsiderBuildingNearbyMex = false
                                                if bDebugMessages == true then LOG(sFunctionRef..'; We dont outrange enemy so wont consider building mex') end
                                            else
                                                --We outrange enemy, which is a small threat, so consider building mex instead of pursuing enemy
                                                local tClosestMex
                                                local iClosestMex = 10000
                                                local iCurDist
                                                if (oACU:IsUnitState('Building') or oACU:IsUnitState('Repairing') or oACU:IsUnitState('Capturing')) and EntityCategoryContains(AiBotUnitInfo.refCategoryMex, oACU:GetFocusUnit().UnitId) then
                                                    if AiBotUtilities.IsTableEmpty(aiBrain:GetUnitsAroundPoint(AiBotUnitInfo.refCategoryLandCombat, oACU:GetPosition(), oACU[AiBotUnitInfo.refiDFRange], 'Enemy')) == false then
                                                        bConsiderBuildingNearbyMex = false
                                                    end
                                                elseif AiBotUtilities.IsTableEmpty(tLZOrWZData[AiBotMap.subrefMexUnbuiltLocations]) then
                                                    bConsiderBuildingNearbyMex = false
                                                    if bDebugMessages == true then LOG(sFunctionRef..': No unbuilt locations for this zone') end
                                                else
                                                    for iMex, tMex in tLZOrWZData[AiBotMap.subrefMexUnbuiltLocations] do
                                                        iCurDist = AiBotUtilities.GetDistanceBetweenPositions(tMex, oACU:GetPosition())
                                                        if iCurDist < iClosestMex then
                                                            iClosestMex = iCurDist
                                                            tClosestMex = {tMex[1], tMex[2], tMex[3]}
                                                        end
                                                    end
                                                    if iClosestMex <= oACU[AiBotUnitInfo.refiDFRange] + iNearbyMexRangeThreshold then
                                                        --Have an unbuilt mex in or near our build range, so now check if enemy is closer to the mex than we are/is in range of the mex
                                                        local bEnemyAlmostInRangeOfMex = false
                                                        for iUnit, oUnit in tLZOrWZTeamData[AiBotMap.subrefTEnemyUnits] do
                                                            if AiBotUnitInfo.IsUnitValid(oUnit) then
                                                                iCurDist = AiBotUtilities.GetDistanceBetweenPositions(tClosestMex, oUnit:GetPosition())
                                                                if iCurDist - (oUnit[AiBotUnitInfo.refiCombatRange] or 0) <= 2 then
                                                                    bEnemyAlmostInRangeOfMex = true
                                                                    break
                                                                end
                                                            end
                                                        end
                                                        if bDebugMessages == true then LOG(sFunctionRef..': bEnemyAlmostInRangeOfMex='..tostring(bEnemyAlmostInRangeOfMex)) end
                                                        if bEnemyAlmostInRangeOfMex then
                                                            bConsiderBuildingNearbyMex = false
                                                        end
                                                    else
                                                        bConsiderBuildingNearbyMex = false
                                                    end
                                                end


                                            end
                                        end
                                        --Adjust - if land zone and we want to consider building a mex, but there are DF enemies, then check if we are close to them, if we are then dont want to build (as dont want to build a mex while taking fire or where the mex will just die)
                                        if bConsiderBuildingNearbyMex and AiBotUtilities.IsTableEmpty(tLZOrWZTeamData[AiBotMap.reftoNearestDFEnemies]) == false and AiBotConditions.CloseToEnemyUnit(oACU:GetPosition(), tLZOrWZTeamData[AiBotMap.reftoNearestDFEnemies], 6, iTeam, true, nil, nil, nil, nil, nil) then
                                            bConsiderBuildingNearbyMex = false
                                            if bDebugMessages == true then LOG(sFunctionRef..': Are close to enemy so dont want to consdier getting mex') end
                                        end

                                        --Part-built or unbuilt mex in build range of ACU when no enemies in the LZ
                                        if bDebugMessages == true then LOG(sFunctionRef..': Finished consider building mex if one is almost in build range and no enemy combat threat in this LZ/WZ, threat='..tLZOrWZTeamData[AiBotMap.subrefTThreatEnemyCombatTotal]..'; bConsiderBuildingNearbyMex='..tostring(bConsiderBuildingNearbyMex)) end
                                        if not(bConsiderBuildingNearbyMex) or not(ConsiderBuildingMex(tLZOrWZData, tLZOrWZTeamData, oACU, 2)) then
                                            if not(ConsiderRunningToGETemplate(oACU, tLZOrWZData, tLZOrWZTeamData, iPlateauOrZero)) then
                                                --ACU damaged and we have a T3 shield in the zone - make sure we are underneath shield coverage
                                                local bHaveMovedToBeUnderShield = false
                                                if AiBotUnitInfo.GetUnitHealthPercent(oACU) <= 0.8 and AiBotUtilities.IsTableEmpty(tLZOrWZTeamData[AiBotMap.subreftoLZOrWZAlliedUnits]) == false then
                                                    local tFriendlyShields = EntityCategoryFilterDown(AiBotUnitInfo.refCategoryFixedShield - categories.TECH2 - categories.TECH1, tLZOrWZTeamData[AiBotMap.subreftoLZOrWZAlliedUnits])
                                                    if AiBotUtilities.IsTableEmpty(tFriendlyShields) == false then
                                                        local iCurShieldHealth, iMaxShieldHealth, iCurShieldDist
                                                        local iClosestShield = 150 --No point trying to move to a shield further away
                                                        local oClosestShield
                                                        for iShield, oShield in tFriendlyShields do
                                                            if AiBotUnitInfo.IsUnitValid(oShield) then
                                                                iCurShieldHealth, iMaxShieldHealth = AiBotUnitInfo.GetCurrentAndMaximumShield(oShield, false)
                                                                if iCurShieldHealth >= 6000 then
                                                                    iCurShieldDist = AiBotUtilities.GetDistanceBetweenPositions(oShield:GetPosition(), oACU:GetPosition())
                                                                    if iCurShieldDist < iClosestShield then
                                                                        iClosestShield = iCurShieldDist
                                                                        oClosestShield = oShield
                                                                    end
                                                                end
                                                            end
                                                        end
                                                        if oClosestShield and iClosestShield < 4 + oClosestShield:GetBlueprint().Defense.Shield.ShieldSize * 0.5 then
                                                            bHaveMovedToBeUnderShield = true
                                                            AiBotOrders.IssueTrackedMove(oACU, oClosestShield:GetPosition(), 4, false, 'ACUUnSh', false)
                                                        end
                                                    end
                                                end
                                                if not(bHaveMovedToBeUnderShield) then

                                                    --Priority reclaim - if reclaim that is in ACU build radius and have <30% mass stored even if nearby enemies (provided arent in range, unless shot is blocked), if have no upgrade or T2 upgrade
                                                    local bAreBuildingOrReclaiming = false
                                                    if oACU:IsUnitState('Building') or oACU:IsUnitState('Repairing') or oACU:IsUnitState('Capturing') then bAreBuildingOrReclaiming = true end
                                                    if bDebugMessages == true then LOG(sFunctionRef..': About to check for priority reclaim, mass stored%='..aiBrain:GetEconomyStoredRatio('MASS')..'; ACU upgrade count='..(oACU[refiUpgradeCount] or 0)..'; Does ACU have adanced engineering='..tostring(oACU:HasEnhancement('AdvancedEngineering'))..'; ACU health %='..AiBotUnitInfo.GetUnitHealthPercent(oACU)..'; bAreBuildingOrReclaiming='..tostring(bAreBuildingOrReclaiming)..'; Is ACU in T1 spam mode='..tostring(AiBotTeam.tTeamData[iTeam][AiBotTeam.refbFocusOnT1Spam])) end

                                                    if aiBrain:GetEconomyStoredRatio('MASS') < 0.3 and (not(bAreBuildingOrReclaiming) or aiBrain:GetEconomyStored('MASS') < 25) and ((oACU[refiUpgradeCount] or 0) == 0 or oACU:HasEnhancement('AdvancedEngineering')) and AiBotUnitInfo.GetUnitHealthPercent(oACU) >= 0.9 and
                                                            (oACU[AiBotUnitInfo.refbLastShotBlocked] or AiBotUtilities.IsTableEmpty(aiBrain:GetUnitsAroundPoint(AiBotUnitInfo.refCategoryMobileLand + AiBotUnitInfo.refCategoryStructure + AiBotUnitInfo.refCategoryNavalSurface, oACU:GetPosition(), (oACU[AiBotUnitInfo.refiDFRange] or 0), 'Enemy'))) and
                                                            ConsiderNearbyReclaimForACUOrEngineer(iPlateauOrZero, iLandOrWaterZone, tLZOrWZData, tLZOrWZTeamData, oACU, true) then
                                                        --ACU wants to get reclaim
                                                        if bDebugMessages == true then LOG(sFunctionRef..': ACU will get reclaim') end
                                                    else
                                                        --Consider building emergency AA
                                                        local bNoNearbyLRThreats = (iPlateauOrZero == 0 or AiBotUtilities.IsTableEmpty(tLZOrWZTeamData[AiBotMap.subreftoAllNearbyEnemyT2ArtiUnits])) and (tLZOrWZTeamData[AiBotMap.subrefiNearbyEnemyLongRangeDFThreat] or 0) == 0
                                                        if (tLZOrWZTeamData[AiBotMap.refiEnemyAirToGroundThreat] or 0) >= 150 and bNoNearbyLRThreats and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestEnemyAirTech] < 3 and (not(bAreBuildingOrReclaiming) or oACU:GetWorkProgress() >= 0.9 or (oACU:GetFocusUnit().UnitId and not(EntityCategoryContains(categories.ANTIAIR, oACU:GetFocusUnit().UnitId)))) then
                                                            if bDebugMessages == true then LOG(sFunctionRef..': Will try building fixed AA, even if already building something else') end
                                                            ACUActionBuildAA(aiBrain, oACU, iPlateauOrZero, iLandOrWaterZone, tLZOrWZData, tLZOrWZTeamData)
                                                        elseif not(bAreBuildingOrReclaiming) then
                                                            --Consider building power if in core zone with lots of mass, and either we lack gun upgrade, or it is late game with no adjacent enemies; however require our stored actual energy to be less then 4k (since we may have just built energy storage)
                                                            local bBuildingOrAssistingPowerOrFactory = false
                                                            if bDebugMessages == true then LOG(sFunctionRef..': About to consider getting power or factories if in core base and have lots of mass stored, AiBotTeam.tTeamData[iTeam][AiBotTeam.refbFocusOnT1Spam]='..tostring(AiBotTeam.tTeamData[iTeam][AiBotTeam.refbFocusOnT1Spam])..'; tLZOrWZTeamData[AiBotMap.subrefLZbCoreBase]='..tostring(tLZOrWZTeamData[AiBotMap.subrefLZbCoreBase])..'; Energy%='..aiBrain:GetEconomyStoredRatio('ENERGY')..'; Mass %='..aiBrain:GetEconomyStoredRatio('MASS')..'; Gross energy='..aiBrain[AiBotEconomy.refiGrossEnergyBaseIncome]..'; Enemeis in this or adj='..tostring(tLZOrWZTeamData[AiBotMap.subrefbEnemiesInThisOrAdjacentLZ])) end

                                                            if bNoNearbyLRThreats and not(tLZOrWZTeamData[AiBotMap.subrefbEnemiesInThisOrAdjacentLZ]) and aiBrain:GetEconomyStoredRatio('MASS') >= 0.2 and aiBrain[AiBotEconomy.refiGrossEnergyBaseIncome] < 3000 and (aiBrain:GetEconomyStoredRatio('MASS') >= 0.5 or not(aiBrain[AiBotOverseer.refbPrioritiseAir] or aiBrain[AiBotOverseer.refbPrioritiseHighTech] or aiBrain[AiBotOverseer.refbPrioritiseDefence] or aiBrain[AiBotOverseer.refbPrioritiseNavy]) or aiBrain[AiBotEconomy.refiOurHighestFactoryTechLevel] >= 3 or (aiBrain:GetEconomyStoredRatio('MASS') >= 0.3 and aiBrain:GetCurrentUnits(AiBotUnitInfo.refCategoryFactory) < 3 and AiBotConditions.GetNumberOfUnitsMeetingCategoryUnderConstructionInLandOrWaterZone(tLZOrWZTeamData, AiBotUnitInfo.refCategoryFactory * categories.TECH1) == 0)) then
                                                                --First consider factories if a t1 spam mode and enemy lacks gun
                                                                if bDebugMessages == true then LOG(sFunctionRef..': About to check if want to build more factories, iPlateauOrZero='..(iPlateauOrZero or 'nil')..'; iLandOrWaterZone='..(iLandOrWaterZone or 'nil')..'; AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestFriendlyAirFactoryTech]='..(AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestFriendlyAirFactoryTech] or 'nil')..'; tLZTeamData[AiBotMap.subrefMexCountByTech][3]='..(tLZOrWZTeamData[AiBotMap.subrefMexCountByTech][3] or 'nil')) end
                                                                if GetGameTimeSeconds() <= 600 and iPlateauOrZero > 0 and (aiBrain[AiBotEconomy.refiOurHighestFactoryTechLevel] <= 1 or oACU[refiBuildTech] >= 2) and not(AiBotOverseer.bLikelyGunUpgrade) and aiBrain:GetEconomyStoredRatio('MASS') >= 0.35 and (aiBrain:GetEconomyStoredRatio('ENERGY') >= 0.8 or aiBrain[AiBotEconomy.refiNetEnergyBaseIncome] > 0 and aiBrain:GetEconomyStoredRatio('ENERGY') >= 0.5) and AiBotConditions.WantMoreFactories(iTeam, iPlateauOrZero, iLandOrWaterZone) and not(AiBotConditions.DoWeWantAirFactoryInsteadOfLandFactory(iTeam, tLZOrWZData, tLZOrWZTeamData, aiBrain)) then
                                                                    --No enemies in this or adj zone, consider building fac unless mod dist is high
                                                                    if tLZOrWZTeamData[AiBotMap.refiModDistancePercent] <= 0.3 or tLZOrWZTeamData[AiBotMap.subrefLZbCoreBase] then
                                                                        --If cant path to enemy with land, or are tech or turtle or navy, then be less likely
                                                                        if (aiBrain:GetEconomyStoredRatio('MASS') >= 0.5 and aiBrain:GetEconomyStoredRatio('ENERGY') >= 0.95)
                                                                                or not(aiBrain[AiBotOverseer.refbPrioritiseHighTech] or aiBrain[AiBotOverseer.refbPrioritiseNavy] or aiBrain[AiBotOverseer.refbPrioritiseDefence] or aiBrain[AiBotOverseer.refbPrioritiseAir])
                                                                                or aiBrain:GetCurrentUnits(AiBotUnitInfo.refCategoryLandFactory + AiBotUnitInfo.refCategoryAirFactory) < 3 or (tLZOrWZTeamData[AiBotMap.subrefLZbCoreBase] and AiBotConditions.GetNumberOfConstructedUnitsMeetingCategoryInZone(tLZOrWZTeamData, AiBotUnitInfo.refCategoryLandFactory + AiBotUnitInfo.refCategoryAirFactory) < 3) then
                                                                            bBuildingOrAssistingPowerOrFactory = true
                                                                            ACUActionBuildFactory(aiBrain, oACU, iPlateauOrZero, iLandOrWaterZone, tLZOrWZData, tLZOrWZTeamData, nil, nil)
                                                                        end
                                                                    end
                                                                end


                                                                if tLZOrWZTeamData[AiBotMap.subrefLZbCoreBase] and aiBrain:GetEconomyStoredRatio('ENERGY') < 0.95 and
                                                                        (((oACU[refiUpgradeCount] == 0 or (oACU[AiBotUnitInfo.refiDFRange] or 0) < 26) and aiBrain[AiBotEconomy.refiGrossEnergyBaseIncome] <= 80*aiBrain[AiBotEconomy.refiBrainBuildRateMultiplier])
                                                                                or (oACU[refiBuildTech] >= 2 and ((oACU[AiBotUnitInfo.refiDFRange] or 0) < 26 or aiBrain[AiBotEconomy.refiGrossEnergyBaseIncome] <= 150 * aiBrain[AiBotEconomy.refiBrainBuildRateMultiplier]))
                                                                                or (GetGameTimeSeconds() >= 720 and not(tLZOrWZTeamData[AiBotMap.subrefbEnemiesInThisOrAdjacentLZ]) and (AiBotTeam.tTeamData[iTeam][AiBotTeam.refbDangerousForACUs] or GetGameTimeSeconds() >= 840))) then
                                                                    if (aiBrain:GetEconomyStoredRatio('ENERGY') <= 0.8 or AiBotConditions.HaveLowPower(aiBrain.AiBotTeam)) and (not(AiBotConditions.ZoneWantsT1Spam(tLZOrWZTeamData, iTeam)) or (aiBrain:GetEconomyStored('ENERGY') < 3500 and (aiBrain[AiBotEconomy.refiNetEnergyBaseIncome] < 0 or AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamNetEnergy] < 0))) and ((oACU[AiBotUnitInfo.refiDFMassThreatOverride] or 0) <= 3000 or AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossEnergy] <= 150) then
                                                                        --Do we have no power of a higher tech level than our ACU in this core zone?
                                                                        local tFriendlyPower = EntityCategoryFilterDown(AiBotUnitInfo.refCategoryPower, tLZOrWZTeamData[AiBotMap.subreftoLZOrWZAlliedUnits])
                                                                        local oNearestUnderConstructionPower, iCurDist
                                                                        local iNearestUnderConstructionPower = 10000
                                                                        local iHighestTechConstructed = 0
                                                                        if AiBotConditions.IsTableOfUnitsStillValid(tFriendlyPower) then
                                                                            for iUnit, oUnit in tFriendlyPower do
                                                                                if oUnit:GetFractionComplete() < 1 then
                                                                                    iCurDist = AiBotUtilities.GetDistanceBetweenPositions(oACU:GetPosition(), oUnit:GetPosition())
                                                                                    if iCurDist < iNearestUnderConstructionPower then
                                                                                        iNearestUnderConstructionPower = iCurDist
                                                                                        oNearestUnderConstructionPower = oUnit
                                                                                    end
                                                                                else
                                                                                    if iHighestTechConstructed < 3 then iHighestTechConstructed = math.max(iHighestTechConstructed, AiBotUnitInfo.GetUnitTechLevel(oUnit)) end
                                                                                end
                                                                            end
                                                                        end
                                                                        if oNearestUnderConstructionPower then
                                                                            --Build own power if ACU is far away and it's T1 power
                                                                            bBuildingOrAssistingPowerOrFactory = true
                                                                            if EntityCategoryContains(AiBotUnitInfo.refCategoryT1Power, oNearestUnderConstructionPower.UnitId) and iNearestUnderConstructionPower >= 30 then
                                                                                ACUActionBuildPower(aiBrain, oACU)
                                                                            else
                                                                                AiBotOrders.IssueTrackedRepair(oACU, oNearestUnderConstructionPower, false, 'ACUAsPwr')
                                                                            end
                                                                        else
                                                                            --build our own power if we have equal or better tech
                                                                            if iHighestTechConstructed <= 1 then
                                                                                bBuildingOrAssistingPowerOrFactory = true
                                                                                ACUActionBuildPower(aiBrain, oACU)
                                                                            else
                                                                                local sPowerBlueprintToBuild = AiBotFactory.GetBlueprintThatCanBuildOfCategory(aiBrain, AiBotUnitInfo.refCategoryPower, oACU)
                                                                                if sPowerBlueprintToBuild and AiBotUnitInfo.GetBlueprintTechLevel(sPowerBlueprintToBuild) >= iHighestTechConstructed then
                                                                                    bBuildingOrAssistingPowerOrFactory = true
                                                                                    ACUActionBuildPower(aiBrain, oACU)
                                                                                end
                                                                            end
                                                                        end

                                                                    end
                                                                end
                                                            end

                                                            --Check if our economy is so good that we want to run next cycle if enemy has T3 land or air to keep our ACU safe
                                                            if not(AiBotTeam.tTeamData[iTeam][AiBotTeam.refbDangerousForACUs]) and (AiBotTeam.tTeamData[aiBrain.AiBotTeam][AiBotTeam.subrefiTeamGrossMass] >= 30 or aiBrain[AiBotEconomy.refiGrossMassBaseIncome] >= 16 or (aiBrain[AiBotEconomy.refiGrossMassBaseIncome] >= 11 + (oACU[refiUpgradeCount] or 0) and (AiBotTeam.tTeamData[aiBrain.AiBotTeam][AiBotTeam.subrefiHighestEnemyAirTech] >= 3 or AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiActiveAiBotBrainCount] > 1 or AiBotUnitInfo.GetUnitHealthPercent(oACU) < 0.8))) then
                                                                --Consider running if enemy is at T3 or has large air to ground threat, or we have built ltos of T3
                                                                if AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestEnemyGroundTech] >= 3 or AiBotTeam.tTeamData[aiBrain.AiBotTeam][AiBotTeam.subrefiHighestEnemyAirTech] >= 3 or AiBotTeam.tTeamData[aiBrain.AiBotTeam][AiBotTeam.refbBuiltLotsOfT3Combat] or AiBotUtilities.IsTableEmpty(AiBotTeam.tTeamData[aiBrain.AiBotTeam][AiBotTeam.subreftTeamEngineersBuildingExperimentals]) == false then
                                                                    if not(AiBotTeam.tTeamData[iTeam][AiBotTeam. refbAssassinationOrSimilar]) and AiBotTeam.tTeamData[aiBrain.AiBotTeam][AiBotTeam.subrefiTeamGrossMass] <= 40 * AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiActiveAiBotBrainCount] and (not(AiBotTeam.tTeamData[aiBrain.AiBotTeam][AiBotTeam.refbBuiltLotsOfT3Combat]) or AiBotTeam.tTeamData[aiBrain.AiBotTeam][AiBotTeam.subrefiActiveAiBotBrainCount] >= 3) and AiBotTeam.tTeamData[iTeam][AiBotTeam.refiConstructedExperimentalCount] == 0 then
                                                                        if bDebugMessages == true then LOG(sFunctionRef..': Although it is quite dangerous for ACUs we wont flag that it is very dangerous just yet due to full share') end
                                                                    else
                                                                        AiBotTeam.tTeamData[iTeam][AiBotTeam.refbDangerousForACUs] = true
                                                                        if bDebugMessages == true then LOG(sFunctionRef..': refbDangerousForACUs true for ACU due to general mass income level so will retreat with ACU if not in adjacent LZ from now on. AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestEnemyGroundTech]='..AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestEnemyGroundTech]..'; AiBotTeam.tTeamData[aiBrain.AiBotTeam][AiBotTeam.subrefiHighestEnemyAirTech]='..AiBotTeam.tTeamData[aiBrain.AiBotTeam][AiBotTeam.subrefiHighestEnemyAirTech]..'; AiBotTeam.tTeamData[aiBrain.AiBotTeam][AiBotTeam.refbBuiltLotsOfT3Combat]='..tostring(AiBotTeam.tTeamData[aiBrain.AiBotTeam][AiBotTeam.refbBuiltLotsOfT3Combat])..'; Is table of engis building experimetnals empty='..tostring(AiBotUtilities.IsTableEmpty(AiBotTeam.tTeamData[aiBrain.AiBotTeam][AiBotTeam.subreftTeamEngineersBuildingExperimentals]))) end
                                                                    end
                                                                end
                                                            end
                                                            --Consider building naval fac or torp launcher in this zone if in water zone and lack torpedo upgrade and it is early game
                                                            if bNoNearbyLRThreats and iPlateauOrZero == 0 and not(bBuildingOrAssistingPowerOrFactory) and (oACU[AiBotUnitInfo.refiAntiNavyRange] or 0) < 10 then
                                                                --Consider torp launcher if this zone wants one and not campaign map
                                                                local bWantTorpLauncher = AiBotConditions.DoesACUWantToConsiderGettingNavalFactoryInCurWaterZone(oACU, aiBrain, iTeam, tLZOrWZData, tLZOrWZTeamData, iLandOrWaterZone, false, false, true)
                                                                --Further check due to delay between ACU completing torp launcher and it being updated in the LZ
                                                                if bWantTorpLauncher and AiBotUtilities.IsTableEmpty(tLZOrWZTeamData[AiBotMap.subreftoLZOrWZAlliedUnits]) == false then
                                                                    local tFriendlyTorpLauncher = EntityCategoryFilterDown(AiBotUnitInfo.refCategoryTorpedoLauncher, tLZOrWZTeamData[AiBotMap.subreftoLZOrWZAlliedUnits])
                                                                    if AiBotUtilities.IsTableEmpty(tFriendlyTorpLauncher) == false then
                                                                        for iTorp, oTorp in tFriendlyTorpLauncher do
                                                                            if not(oTorp.Dead) and oTorp:GetFractionComplete() == 1 then
                                                                                if bDebugMessages == true then LOG(sFunctionRef..': We already have torp launcher and presumably just not updated threat yet so wont get another') end
                                                                                bWantTorpLauncher = false
                                                                                break
                                                                            end
                                                                        end
                                                                    end
                                                                end
                                                                if bWantTorpLauncher and (tLZOrWZTeamData[AiBotMap.subreftiBPWantedByAction][AiBotEngineer.refActionBuildTorpLauncher] or 0) > 0 and (tLZOrWZTeamData[AiBotMap.subrefWZTThreatAllyLauncherDefenceTotal] or 0) == 0 and ((AiBotTeam.tTeamData[iTeam][AiBotTeam.refiEnemySubCount] or 0) > 0 or tLZOrWZTeamData[AiBotMap.subrefbEnemiesInThisOrAdjacentWZ]) and not(AiBotMap.bIsCampaignMap) then
                                                                    if bDebugMessages == true then LOG(sFunctionRef..': Want to build torp launcher with ACU to protect naval fac') end
                                                                    bBuildingOrAssistingPowerOrFactory = true
                                                                    ACUBuildUnit(aiBrain, oACU, AiBotEngineer.tiActionCategory[AiBotEngineer.refActionBuildT1TorpLauncher], 30, 30, nil, nil, nil)
                                                                end


                                                                if not(bBuildingOrAssistingPowerOrFactory) and AiBotConditions.DoesACUWantToConsiderGettingNavalFactoryInCurWaterZone(oACU, aiBrain, iTeam, tLZOrWZData, tLZOrWZTeamData, iLandOrWaterZone, false, false) then
                                                                    if bDebugMessages == true then LOG(sFunctionRef..': Want ACU to build naval fac in this zone') end
                                                                    ACUActionBuildFactory(aiBrain, oACU, iPlateauOrZero, iLandOrWaterZone, tLZOrWZData, tLZOrWZTeamData, AiBotUnitInfo.refCategoryNavalFactory, AiBotEngineer.refActionBuildNavalFactory)
                                                                    bBuildingOrAssistingPowerOrFactory = true
                                                                end

                                                                --If already in water zone and have naval fac on naval map then get preemptive torp launcher
                                                                if bWantTorpLauncher and not(bBuildingOrAssistingPowerOrFactory) and AiBotUtilities.IsTableEmpty(tLZOrWZTeamData[AiBotMap.subreftoLZOrWZAlliedUnits]) == false and AiBotUtilities.IsTableEmpty(EntityCategoryFilterDown(AiBotUnitInfo.refCategoryNavalFactory, tLZOrWZTeamData[AiBotMap.subreftoLZOrWZAlliedUnits])) == false then
                                                                    if bDebugMessages == true then LOG(sFunctionRef..': Want to build pre-emptive torp launcher with ACU to protect naval fac, subrefWZTThreatAllyLauncherDefenceTotal='..tLZOrWZTeamData[AiBotMap.subrefWZTThreatAllyLauncherDefenceTotal]..'; iLandOrWaterZone='..iLandOrWaterZone) end
                                                                    bBuildingOrAssistingPowerOrFactory = true
                                                                    ACUBuildUnit(aiBrain, oACU, AiBotEngineer.tiActionCategory[AiBotEngineer.refActionBuildT1TorpLauncher], 30, 30, nil, nil, nil)
                                                                end
                                                            end


                                                            if bDebugMessages == true then LOG(sFunctionRef..': Finished checking if we want ACU to build power, bBuildingOrAssistingPowerOrFactory='..tostring(bBuildingOrAssistingPowerOrFactory)) end

                                                            if not(bBuildingOrAssistingPowerOrFactory) then

                                                                --If have orders for ACU but no land zone then wait until it is in a land zone again assuming it is moving
                                                                if not(iLandOrWaterZone) or (iPlateauOrZero == 0 and not(tLZOrWZTeamData[AiBotMap.subrefWZbContainsUnderwaterStart])) then
                                                                    if bDebugMessages == true then LOG(sFunctionRef..': ACU isnt in a land zone, if has no orders will tell it to retreat to start position, oACU[AiBotOrders.refiOrderCount]='..(oACU[AiBotOrders.refiOrderCount] or 'nil')..'; ACU unit state='..AiBotUnitInfo.GetUnitState(oACU)..'; reprs of last order='..reprs(oACU[AiBotOrders.reftiLastOrders][oACU[AiBotOrders.refiOrderCount]])..'; ACU speed='..AiBotUnitInfo.GetUnitSpeed(oACU)) end
                                                                    --If ACU is guarding it might be assisiting a naval fac, so this is to stop it staying assisting that naval fac forever (i.e. whenever naval fac finishes a unit should get to here, but with acu still in guarding unit state)
                                                                    if (oACU[AiBotOrders.refiOrderCount] or 0) == 0 or (oACU:IsUnitState('Guarding') and AiBotUnitInfo.GetUnitSpeed(oACU) <= 0.1)  then

                                                                        AiBotOrders.IssueTrackedMove(oACU, AiBotMap.GetPlayerStartPosition(oACU:GetAIBrain()), 5, false, 'NLZRun')
                                                                    elseif oACU:IsUnitState('Attacking') and AiBotUnitInfo.IsUnitUnderwater(oACU) and not(tLZOrWZTeamData[AiBotMap.subrefWZbContainsUnderwaterStart]) then
                                                                        --Came across rare issue where ACU has attack-move order, that doesnt get refreshed, but ACU gets stuck not moving in the water, its unit state when this happened was attacking, and its last order was refiOrderIssueAggressiveMove; the below is a workaround as in some cases want ACU to advance where this is the case, in others want it to retreat
                                                                        local iCurWaterZone = AiBotMap.GetWaterZoneFromPosition(oACU:GetPosition())
                                                                        if AiBotUnitInfo.GetUnitHealthPercent(oACU) < 0.95 or not(iCurWaterZone) then

                                                                            AiBotOrders.IssueTrackedMove(oACU, AiBotMap.GetPlayerStartPosition(oACU:GetAIBrain()), 5, false, 'NLZRn')
                                                                        else
                                                                            --Look for nearest land zone and move here
                                                                            local iPond = AiBotMap.tiPondByWaterZone[iCurWaterZone]
                                                                            local tWZData = AiBotMap.tPondDetails[iPond][AiBotMap.subrefPondWaterZones][iCurWaterZone]
                                                                            local tLZMidpointToMoveTo
                                                                            if AiBotUtilities.IsTableEmpty(tWZData[AiBotMap.subrefAdjacentLandZones]) == false then
                                                                                for iEntry, tSubtable in tWZData[AiBotMap.subrefAdjacentLandZones] do
                                                                                    local tAltLZ = AiBotMap.tAllPlateaus[tSubtable[AiBotMap.subrefWPlatAndLZNumber][1]][AiBotMap.subrefPlateauLandZones][tSubtable[AiBotMap.subrefWPlatAndLZNumber][2]]
                                                                                    if tAltLZ[AiBotMap.subrefLZTeamData][iTeam][AiBotMap.subrefbLZWantsSupport] then
                                                                                        tLZMidpointToMoveTo = tAltLZ[AiBotMap.subrefMidpoint]
                                                                                        break
                                                                                    end
                                                                                end
                                                                            end
                                                                            if bDebugMessages == true then LOG(sFunctionRef..': tLZMidpointToMoveTo after checking if have adjacent land zones that want support='..repru(tLZMidpointToMoveTo)) end

                                                                            if not(tLZMidpointToMoveTo) then tLZMidpointToMoveTo = AiBotMap.GetPlayerStartPosition(oACU:GetAIBrain()) end

                                                                            AiBotOrders.IssueTrackedMove(oACU, tLZMidpointToMoveTo, 5, false, 'ACUWtr')

                                                                        end
                                                                    end
                                                                else
                                                                    --Are there enemies in this LZ? If so then attack them
                                                                    if bDebugMessages == true then LOG(sFunctionRef..': Is table of enemy units for this LZ empty='..tostring(AiBotUtilities.IsTableEmpty(tLZOrWZTeamData[AiBotMap.subrefTEnemyUnits]))) end
                                                                    if AiBotUtilities.IsTableEmpty(tLZOrWZTeamData[AiBotMap.subrefTEnemyUnits]) == false and iPlateauOrZero > 0 and AttackNearestEnemyWithACU(iPlateauOrZero, iLandOrWaterZone, tLZOrWZData, tLZOrWZTeamData, oACU) then
                                                                        --(Do nothing further - will ahve given the order)
                                                                        --If enemy ACU in this zone, then consider getting emergency support
                                                                        ConsiderIfACUNeedsEmergencySupport(iPlateauOrZero, iLandOrWaterZone, tLZOrWZData, tLZOrWZTeamData, oACU)
                                                                    else
                                                                        if oACU[refbDoingInitialBuildOrder] and (AiBotUtilities.IsTableEmpty(AiBotTeam.tTeamData[iTeam][AiBotTeam.reftEnemyLandExperimentals]) or not(DoesACUWantToRun(iPlateauOrZero, iLandOrWaterZone, tLZOrWZData, tLZOrWZTeamData, oACU))) then
                                                                            GetACUEarlyGameOrders(aiBrain, oACU)

                                                                            --Have we finished our initial build order? (even if we stil lahve some early game orders)
                                                                            if bDebugMessages == true then LOG(sFunctionRef..': Checking if have finished initial build order, Economy stored mass='..aiBrain:GetEconomyStored('MASS')..'; Gross mass income='..aiBrain[AiBotEconomy.refiGrossMassBaseIncome]..'; Gross energy income='..aiBrain[AiBotEconomy.refiGrossEnergyBaseIncome]) end
                                                                            if not(oACU:IsUnitState('Building')) and aiBrain:GetEconomyStored('MASS') == 0 and aiBrain[AiBotEconomy.refiGrossMassBaseIncome] >= 0.3 and aiBrain[AiBotEconomy.refiGrossEnergyBaseIncome] >= 15 then
                                                                                bDoingInitialBuildOrder = false
                                                                            end
                                                                        else
                                                                            --If we are reclaiming or building then dont do anything
                                                                            if bDebugMessages == true then
                                                                                LOG(sFunctionRef..': Arent doing initial build order and dont want to run, ACU unit state='..AiBotUnitInfo.GetUnitState(oACU)..'; Brain mass stored%='..aiBrain:GetEconomyStoredRatio('MASS')..'; If are nearby enemies then will list out, is table of nearby enemies empty='..tostring(AiBotUtilities.IsTableEmpty(tLZOrWZTeamData[AiBotMap.reftoNearestDFEnemies]))..'; oACU[AiBotUnitInfo.refiDFRange]='..(oACU[AiBotUnitInfo.refiDFRange] or 'nil')..'; ACU position='..repru(oACU:GetPosition())..'; ACU team='..oACU:GetAIBrain().AiBotTeam)
                                                                                if AiBotUtilities.IsTableEmpty(tLZOrWZTeamData[AiBotMap.reftoNearestDFEnemies]) == false then
                                                                                    --CloseToEnemyUnit(tStartPosition, tUnitsToCheck,                               iDistThreshold, iTeam, bIncludeEnemyDFRange, iAltThresholdToDFRange, oUnitIfConsideringAngleAndLastShot, oOptionalFriendlyUnitToRecordClosestEnemy, iOptionalDistThresholdForStructure, bIncludeEnemyAntiNavyRange)
                                                                                    LOG(sFunctionRef..': are we close to nearby units='..tostring(AiBotConditions.CloseToEnemyUnit(oACU:GetPosition(), tLZOrWZTeamData[AiBotMap.reftoNearestDFEnemies], 12 , aiBrain.AiBotTeam, true, math.max(25, oACU[AiBotUnitInfo.refiDFRange] + 12))))
                                                                                    for iUnit, oUnit in tLZOrWZTeamData[AiBotMap.reftoNearestDFEnemies] do
                                                                                        LOG(sFunctionRef..': Entry '..iUnit..' is unit '..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..' which is '..AiBotUtilities.GetDistanceBetweenPositions(oACU:GetPosition(), oUnit:GetPosition())..' with range '..(oUnit[AiBotUnitInfo.refiDFRange] or 'nil'))
                                                                                    end
                                                                                end
                                                                            end
                                                                            local iNearbyEnemyAttackRangeThreshold = 12
                                                                            if tLZOrWZTeamData[AiBotMap.subrefbDangerousEnemiesInThisLZ] and (oACU:IsUnitState('Building') or oACU:IsUnitState('Capturing') or oACU:IsUnitState('Repairing') or (oACU:IsUnitState('Guarding') and oACU:GetWorkProgress() > 0 and not(EntityCategoryContains(categories.MOBILE - categories.COMMAND - AiBotUnitInfo.categories.SUBCOMMANDER, oACU:GetFocusUnit().UnitId))) or (oACU:IsUnitState('Reclaiming') and aiBrain:GetEconomyStoredRatio('MASS') <= 0.6)) then iNearbyEnemyAttackRangeThreshold = 4
                                                                            elseif tLZOrWZTeamData[AiBotMap.subrefLZbCoreBase] or tLZOrWZTeamData[AiBotMap.subrefLZSValue] >= 200 then
                                                                                iNearbyEnemyAttackRangeThreshold = 20
                                                                            end
                                                                            --Be more aggressive if have several upgrades already
                                                                            if oACU[refiUpgradeCount] >= 2 and (oACU[refiUpgradeCount] >= 3 or not(EntityCategoryContains(categories.AEON, oACU.UnitId))) and AiBotUnitInfo.GetUnitHealthPercent(oACU) >= 0.95 and not(AiBotTeam.tTeamData[iTeam][AiBotTeam.refbAssassinationOrSimilar]) then iNearbyEnemyAttackRangeThreshold = iNearbyEnemyAttackRangeThreshold + 15 end
                                                                            --Check adjacent zones for closest enemy in case are any within range
                                                                            local oClosestEnemy, oCurEnemy
                                                                            local iClosestEnemy = (oACU[AiBotUnitInfo.refiDFRange] or 0) + iNearbyEnemyAttackRangeThreshold
                                                                            local iCurDist
                                                                            if iPlateauOrZero > 0 and AiBotUtilities.IsTableEmpty(tLZOrWZData[AiBotMap.subrefLZAdjacentLandZones]) == false then
                                                                                for _, iAdjLZ in tLZOrWZData[AiBotMap.subrefLZAdjacentLandZones] do
                                                                                    local tAdjLZTeamData = AiBotMap.tAllPlateaus[iPlateauOrZero][AiBotMap.subrefPlateauLandZones][iAdjLZ][AiBotMap.subrefLZTeamData][iTeam]
                                                                                    if AiBotUtilities.IsTableEmpty(tAdjLZTeamData[AiBotMap.subrefTEnemyUnits]) == false then
                                                                                        oCurEnemy, iCurDist = AiBotUtilities.GetNearestUnit(tAdjLZTeamData[AiBotMap.subrefTEnemyUnits], oACU:GetPosition(), false, nil, true)
                                                                                        if iCurDist < iClosestEnemy then
                                                                                            iClosestEnemy = iCurDist
                                                                                            oClosestEnemy = oCurEnemy
                                                                                        end
                                                                                    end
                                                                                end
                                                                            end
                                                                            --No nearby enemies subject to oClosestEnemy, consider building power if have low level of it and lots of mass
                                                                            if bDebugMessages == true then LOG(sFunctionRef..': Considering if we want more power for high mass levels, or want to attack nearby enemies, or get nearby reclaim, Is table of nearest DF enemies empty='..tostring(AiBotUtilities.IsTableEmpty(tLZOrWZTeamData[AiBotMap.reftoNearestDFEnemies]))..'; AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossEnergy]='..AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossEnergy]..'; not(AiBotConditions.HaveLowMass(aiBrain)='..tostring(not(AiBotConditions.HaveLowMass(aiBrain)))..'; Want more power='..tostring(AiBotConditions.WantMorePower(iTeam))..'; tLZOrWZData[AiBotMap.subrefTotalSignificantMassReclaim]='..(tLZOrWZData[AiBotMap.subrefTotalSignificantMassReclaim] or 'nil')..'; oClosestEnemy='..(oClosestEnemy.UnitId or 'nil')..(AiBotUnitInfo.GetUnitLifetimeCount(oClosestEnemy) or 'nil')..'; iNearbyEnemyAttackRangeThreshold='..iNearbyEnemyAttackRangeThreshold) end
                                                                            --Ignore scouts that arent in range
                                                                            if oClosestEnemy and (iClosestEnemy <= oACU[AiBotUnitInfo.refiDFRange] or not(EntityCategoryContains(AiBotUnitInfo.refCategoryLandScout - AiBotUnitInfo.refCategoryCombatScout, oClosestEnemy.UnitId))) and AttackNearestEnemyWithACU(iPlateauOrZero, iLandOrWaterZone, tLZOrWZData, tLZOrWZTeamData, oACU) then
                                                                                if bDebugMessages == true then LOG(sFunctionRef..': Attacking nearby closest enemy') end
                                                                                --Closetoenemy check - in theory shouldnt trigger, but left in as a redundancy
                                                                                --CloseToEnemyUnit(tStartPosition, tUnitsToCheck,                       iDistThreshold, iTeam, bIncludeEnemyDFRange, iAltThresholdToDFRange)
                                                                            elseif (oACU[AiBotUnitInfo.refiDFRange] or 0) > 0 and AiBotUtilities.IsTableEmpty(tLZOrWZTeamData[AiBotMap.reftoNearestDFEnemies]) == false and AiBotConditions.CloseToEnemyUnit(oACU:GetPosition(), tLZOrWZTeamData[AiBotMap.reftoNearestDFEnemies], iNearbyEnemyAttackRangeThreshold , aiBrain.AiBotTeam, true, math.max(25, oACU[AiBotUnitInfo.refiDFRange] + iNearbyEnemyAttackRangeThreshold)) and AttackNearestEnemyWithACU(iPlateauOrZero, iLandOrWaterZone, tLZOrWZData, tLZOrWZTeamData, oACU) then
                                                                                if bDebugMessages == true then LOG(sFunctionRef..': Are close to enemy units so will attack rather than considering upgrades or building mexes etc.') end
                                                                            elseif bNoNearbyLRThreats and AiBotUtilities.IsTableEmpty(tLZOrWZTeamData[AiBotMap.reftoNearestDFEnemies]) and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossEnergy] <= 50 and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamAverageMassPercentStored] >= 0.3 and not(AiBotConditions.HaveLowMass(aiBrain)) and (AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestFriendlyFactoryTech] == 1 or (AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestFriendlyFactoryTech] == 2 and oACU.HasEnhancement and oACU:HasEnhancement('AdvancedEngineering'))) and (AiBotConditions.WantMorePower(iTeam) or AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamAverageMassPercentStored] >= 0.7) then
                                                                                ACUActionBuildPower(aiBrain, oACU)
                                                                                --Is there an enemy unit nearby that we want to attack?
                                                                                --If lots of reclaim in this zone consider getting it
                                                                            elseif oACU[refiUpgradeCount] > 0 and AiBotUtilities.IsTableEmpty(tLZOrWZTeamData[AiBotMap.reftoNearestDFEnemies]) == false and iPlateauOrZero > 0 and HaveNearbyVulnerableEnemyACUToAttack(oACU, iTeam, tLZOrWZData, tLZOrWZTeamData, iPlateauOrZero, iLandOrWaterZone) then
                                                                                if bDebugMessages == true then LOG(sFunctionRef..': Are going to try and attack nearby vulnerable enemy ACU') end
                                                                            elseif tLZOrWZData[AiBotMap.subrefTotalSignificantMassReclaim] >= 300 and not(tLZOrWZTeamData[AiBotMap.subrefLZbCoreBase]) and aiBrain:GetEconomyStoredRatio('MASS') <= 0.9 and ((oACU[AiBotUnitInfo.refiDFMassThreatOverride] or 0) <= 5000 or not(tLZOrWZTeamData[AiBotMap.subrefbEnemiesInThisOrAdjacentLZ]) or tLZOrWZData[AiBotMap.subrefTotalSignificantMassReclaim] >= 1.5*oACU[AiBotUnitInfo.refiDFMassThreatOverride] or 0) and (tLZOrWZTeamData[AiBotMap.refiModDistancePercent] >= 0.45 or tLZOrWZData[AiBotMap.subrefTotalSignificantMassReclaim] >= 3500 or not(tLZOrWZTeamData[AiBotMap.subrefbEnemiesInThisOrAdjacentLZ]) or (AiBotConditions.GetNumberOfConstructedUnitsMeetingCategoryInZone(tLZOrWZTeamData, AiBotUnitInfo.refCategoryLandFactory) == 0 and AiBotConditions.GetNumberOfConstructedUnitsMeetingCategoryInZone(tLZOrWZTeamData, AiBotUnitInfo.refCategoryEngineer) <= math.max(1, tLZOrWZData[AiBotMap.subrefTotalSignificantMassReclaim] / 1000))) and ConsiderNearbyReclaimForACUOrEngineer(iPlateauOrZero, iLandOrWaterZone, tLZOrWZData, tLZOrWZTeamData, oACU, false, nil, nil, nil) then
                                                                                if bDebugMessages == true then LOG(sFunctionRef..': Lots of reclaim so will stay here, signif reclaim='..tLZOrWZData[AiBotMap.subrefTotalSignificantMassReclaim]..'; Mod dist%='..tLZOrWZTeamData[AiBotMap.refiModDistancePercent]..'; Enemies in this or adjacent zone='..tostring(tLZOrWZTeamData[AiBotMap.subrefbEnemiesInThisOrAdjacentLZ] or false)) end
                                                                            elseif tLZOrWZData[AiBotMap.subrefTotalSignificantMassReclaim] >= 40 and ConsiderNearbyReclaimForACUOrEngineer(iPlateauOrZero, iLandOrWaterZone, tLZOrWZData, tLZOrWZTeamData, oACU, true, nil, nil, nil) then
                                                                                if bDebugMessages == true then LOG(sFunctionRef..': Getting reclaim in build radius') end
                                                                            else
                                                                                if bDebugMessages == true then LOG(sFunctionRef..': Checking if ACU unit state not important so we can consider doing other things, ACU state='..AiBotUnitInfo.GetUnitState(oACU)..'; Mass stored ratio='..aiBrain:GetEconomyStoredRatio('MASS')..'; Is unit state building='..tostring(oACU:IsUnitState('Building'))..'; Is unit state repairing='..tostring(oACU:IsUnitState('Repairing'))..'; Is unit state reclaiming='..tostring(oACU:IsUnitState('Reclaiming'))..'; Is unit state guarding='..tostring(oACU:IsUnitState('Guarding'))) end
                                                                                if not(oACU:IsUnitState('Building')) and not(oACU:IsUnitState('Capturing')) and (not(oACU:IsUnitState('Repairing')) or (oACU:IsUnitState('Guarding') and oACU:GetWorkProgress() > 0 and not(EntityCategoryContains(categories.MOBILE - categories.COMMAND - AiBotUnitInfo.categories.SUBCOMMANDER, oACU:GetFocusUnit().UnitId)))) and (not(oACU:IsUnitState('Reclaiming')) or aiBrain:GetEconomyStoredRatio('MASS') >= 0.8) then
                                                                                    --Do we want to get an upgrade?

                                                                                    local sUpgradeToGet, bIgnoreOtherUpgradeConditions
                                                                                    if bNoNearbyLRThreats then sUpgradeToGet, bIgnoreOtherUpgradeConditions = GetACUUpgradeWanted(oACU, nil, tLZOrWZData, tLZOrWZTeamData, iPlateauOrZero) end
                                                                                    if bDebugMessages == true then LOG(sFunctionRef..': Do we have an upgrade we want to get? sUpgradeToGet='..(sUpgradeToGet or 'nil')..'; bNoNearbyLRThreats='..tostring(bNoNearbyLRThreats or false)) end
                                                                                    if sUpgradeToGet then
                                                                                        --Do we have a friendly nearby ugprading ACU? If so then assist its upgrade first before getting ours
                                                                                        if bIgnoreOtherUpgradeConditions or not(AssistNearbyUpgradingACU(iPlateauOrZero, iLandOrWaterZone, tLZOrWZData, tLZOrWZTeamData, oACU, 40)) then
                                                                                            --Are we safe to get the upgrade here? if not then retreat
                                                                                            if bDebugMessages == true then LOG(sFunctionRef..': Will check if safe to get upgrade for oACU, oACU='..(oACU.UnitId or 'nil')..(AiBotUnitInfo.GetUnitLifetimeCount(oACU) or 'nil')..'; Brain='..oACU:GetAIBrain().Nickname) end
                                                                                            if bIgnoreOtherUpgradeConditions or AiBotConditions.SafeToUpgradeUnit(oACU) then
                                                                                                if bDebugMessages == true then LOG(sFunctionRef..': Safe to get upgrade here so will proceed with upgrading ACU, sUpgradeToGet='..(sUpgradeToGet or 'nil')..' brain='..oACU:GetAIBrain().Nickname..'; Has enhancement='..tostring(oACU:HasEnhancement(sUpgradeToGet))) end
                                                                                                if GetGameTimeSeconds() - (AiBotTeam.tTeamData[iTeam][AiBotTeam.refiTimeLastIssuedACUEnhancementOrder] or -100) >= 2 or (oACU[AiBotOrders.refiTimeOfLastRemovalUpgrade] and GetGameTimeSeconds() - oACU[AiBotOrders.refiTimeOfLastRemovalUpgrade] <= 10) or oACU[AiBotOrders.reftiLastOrders][oACU[AiBotOrders.refiOrderCount]][AiBotOrders.subrefsOrderBlueprint] == sUpgradeToGet then
                                                                                                    AiBotOrders.IssueTrackedEnhancement(oACU, sUpgradeToGet, false, 'ACUUpr')
                                                                                                end
                                                                                            else
                                                                                                --Retreat
                                                                                                local tRallyPoint = AiBotLand.GetNearestLandRallyPoint(tLZOrWZData, oACU:GetAIBrain().AiBotTeam, iPlateauOrZero, iLandOrWaterZone, 2)
                                                                                                if bDebugMessages == true then LOG(sFunctionRef..': Not safe to get upgrade so want to retreat until it is. tRallyPoint='..repru(tRallyPoint)..'; ACU position='..repru(oACU:GetPosition())) end
                                                                                                AiBotOrders.IssueTrackedMove(oACU, tRallyPoint, 5, false, 'R4UGen')
                                                                                            end
                                                                                        end
                                                                                    else
                                                                                        --We dont want an upgrade, and have no enemies in this LZ, but there might be enemies nearby (e.g. in an adjacent land zone); there might also be mexes to build or reclaim to get in this LZ - decide on what we want to do
                                                                                        --Does the LZ have uncalimed mexes?
                                                                                        if bDebugMessages == true then LOG(sFunctionRef..': Will consider if we want to build a mex if there are any unclaimed') end
                                                                                        local iMaxSearchRange = 40
                                                                                        if tLZOrWZTeamData[AiBotMap.subrefLZbCoreBase] and GetGameTimeSeconds() >= 900 then iMaxSearchRange = 50
                                                                                        elseif oACU[refiUpgradeCount] > 0 then iMaxSearchRange = 30
                                                                                        end
                                                                                        if tLZOrWZTeamData[AiBotMap.subrefbEnemiesInThisOrAdjacentLZ] then iMaxSearchRange = iMaxSearchRange - 15 end
                                                                                        if iMaxSearchRange >= 5 and not(tLZOrWZTeamData[AiBotMap.subrefLZbCoreBase]) and oACU[refiUpgradeCount] > 0 and tLZOrWZTeamData[AiBotMap.subrefbEnemiesInThisOrAdjacentLZ] then
                                                                                            if AiBotConditions.HaveEngineersOrFactoriesInZone(tLZOrWZTeamData) then
                                                                                                iMaxSearchRange = 5
                                                                                            end
                                                                                        end

                                                                                        if not(ConsiderBuildingMex(tLZOrWZData, tLZOrWZTeamData, oACU, iMaxSearchRange)) then
                                                                                            --Water zone specific - if underwater and is an underwater start position then do nothing
                                                                                            if iPlateauOrZero > 0 or not(tLZOrWZTeamData[AiBotMap.subrefWZbContainsUnderwaterStart]) then

                                                                                                --Do we want another land factory?
                                                                                                if bDebugMessages == true then LOG(sFunctionRef..': No mexes to build ni this LZ, seeing if we want another land factory') end
                                                                                                if bNoNearbyLRThreats and not(ConsiderGettingExtraLandFactory(tLZOrWZData, tLZOrWZTeamData, oACU, iPlateauOrZero, iLandOrWaterZone)) then
                                                                                                    --Are there enemies in an adjacent LZ? in which case want to consider attacking them
                                                                                                    if ConsiderNearbyReclaimForACUOrEngineer(iPlateauOrZero, iLandOrWaterZone, tLZOrWZData, tLZOrWZTeamData, oACU, true) or (AiBotUtilities.IsTableEmpty(tLZOrWZTeamData[AiBotMap.subrefTEnemyUnits]) == false and AttackNearestEnemyWithACU(iPlateauOrZero, iLandOrWaterZone, tLZOrWZData, tLZOrWZTeamData, oACU)) then
                                                                                                        if bDebugMessages == true then LOG(sFunctionRef..': Will try getting reclaim in range or attacking enemy in this zone') end
                                                                                                    else
                                                                                                        --ACU is in a zone with lots of reclaim - consider prioritising this over attacking nearby enemies

                                                                                                        --Only consider reclaim if min value of a wreck is 40 - dont want to waste ACU time on harder to get reclaim
                                                                                                        local iMinIndivReclaimThreshold = 40
                                                                                                        local iMinTotalReclaimThreshold = 300
                                                                                                        if tLZOrWZTeamData[AiBotMap.subrefLZbCoreBase] or (tLZOrWZTeamData[AiBotMap.refiModDistancePercent] <= 0.2 and tLZOrWZTeamData[AiBotMap.refiTimeLastBuiltAtFactory] and GetGameTimeSeconds() - tLZOrWZTeamData[AiBotMap.refiTimeLastBuiltAtFactory] <= 60 and tLZOrWZTeamData[AiBotMap.subrefLZSValue] >= 500 and (tLZOrWZTeamData[AiBotMap.subrefLZSValue] >= 5000 or AiBotConditions.GetNumberOfConstructedUnitsMeetingCategoryInZone(tLZOrWZTeamData, AiBotUnitInfo.refCategoryFactory + AiBotUnitInfo.refCategoryEngineer) >= 4)) then
                                                                                                            iMinIndivReclaimThreshold = 100
                                                                                                            iMinTotalReclaimThreshold = 900
                                                                                                        elseif AiBotConditions.ZoneWantsT1Spam(tLZOrWZTeamData, iTeam) then
                                                                                                            if aiBrain:GetEconomyStored('MASS') < 50 then iMinIndivReclaimThreshold = 60 else
                                                                                                                iMinIndivReclaimThreshold = 100
                                                                                                                iMinTotalReclaimThreshold = 400
                                                                                                            end
                                                                                                        end
                                                                                                        if bDebugMessages == true then LOG(sFunctionRef..': Considering if reclaim in this zone valuable enough to focus on it instead of enemies; Cur mass stored='..aiBrain:GetEconomyStoredRatio('MASS')..'; Signif Reclaim in zone='..tLZOrWZData[AiBotMap.subrefTotalSignificantMassReclaim]..'; S value of zone='..tLZOrWZTeamData[AiBotMap.subrefLZSValue]..'; iMinTotalReclaimThreshold='..iMinTotalReclaimThreshold) end
                                                                                                        if tLZOrWZData[AiBotMap.subrefTotalSignificantMassReclaim] >= iMinTotalReclaimThreshold and not(tLZOrWZTeamData[AiBotMap.subrefLZbCoreBase]) and tLZOrWZTeamData[AiBotMap.subrefLZSValue] <= 200 and aiBrain:GetEconomyStoredRatio('MASS') <= 0.6 and ConsiderNearbyReclaimForACUOrEngineer(iPlateauOrZero, iLandOrWaterZone, tLZOrWZData, tLZOrWZTeamData, oACU, false, iMinIndivReclaimThreshold) then
                                                                                                            if bDebugMessages == true then LOG(sFunctionRef..': Lots of reclaim in area so will focus on that') end
                                                                                                        else
                                                                                                            local bAttackNearestEnemy, iClosestOutOfThresholdEnemy = AttackNearestEnemyWithACU(iPlateauOrZero, iLandOrWaterZone, tLZOrWZData, tLZOrWZTeamData, oACU, nil, true)
                                                                                                            if bAttackNearestEnemy then
                                                                                                                if bDebugMessages == true then LOG(sFunctionRef..': Attacking enemies in adjacent zone') end
                                                                                                            else
                                                                                                                local bOnlyConsiderInBuildRange = false
                                                                                                                if tLZOrWZTeamData[AiBotMap.subrefLZbCoreBase] and (tLZOrWZTeamData[AiBotMap.subrefbEnemiesInThisOrAdjacentLZ] or (oACU[refiUpgradeCount] > 0 and not(AiBotTeam.tTeamData[iTeam][AiBotTeam.refbDangerousForACUs])) or (GetGameTimeSeconds() <= 300 and aiBrain[AiBotEconomy.refiGrossMassBaseIncome] <= 4)) then bOnlyConsiderInBuildRange = true
                                                                                                                elseif oACU[refiUpgradeCount] > 0 and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestEnemyGroundTech] <= 2 and not(AiBotTeam.tTeamData[iTeam][AiBotTeam.refbDangerousForACUs]) and tLZOrWZTeamData[AiBotMap.refiModDistancePercent] <= 0.55 and AiBotUnitInfo.GetUnitHealthPercent(oACU) >= 0.9 then
                                                                                                                    bOnlyConsiderInBuildRange = true
                                                                                                                elseif AiBotConditions.ZoneWantsT1Spam(tLZOrWZTeamData, iTeam) then bOnlyConsiderInBuildRange = true
                                                                                                                elseif iClosestOutOfThresholdEnemy <= 120 and oACU[refiUpgradeCount] >= 2 and AiBotUnitInfo.GetUnitHealthPercent(oACU) >= 0.98 and tLZOrWZData[AiBotMap.subrefTotalSignificantMassReclaim] <= 150 then
                                                                                                                    if bDebugMessages == true then LOG(sFunctionRef..': Dont want to look for reclaim outside of our build range as have nearby enemy that is outside normal range but close enough we want to attack') end
                                                                                                                    bOnlyConsiderInBuildRange = true
                                                                                                                end
                                                                                                                if bDebugMessages == true then LOG(sFunctionRef..': Dont want to build mex, will cehck if want to get reclaim, bOnlyConsiderInBuildRange='..tostring(bOnlyConsiderInBuildRange)..'; Mod dist='..tLZOrWZTeamData[AiBotMap.refiModDistancePercent]..'; Enemy ground tech='..AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestEnemyGroundTech]) end
                                                                                                                if ( tLZOrWZData[AiBotMap.subrefTotalSignificantMassReclaim] < 40 or not(ConsiderNearbyReclaimForACUOrEngineer(iPlateauOrZero, iLandOrWaterZone, tLZOrWZData, tLZOrWZTeamData, oACU, true))) and ( (tLZOrWZData[AiBotMap.subrefTotalSignificantMassReclaim] >= 40 or not(ConsiderNearbyReclaimForACUOrEngineer(iPlateauOrZero, iLandOrWaterZone, tLZOrWZData, tLZOrWZTeamData, oACU, bOnlyConsiderInBuildRange))) or (not(bOnlyConsiderInBuildRange) and not(ConsiderNearbyReclaimForACUOrEngineer(iPlateauOrZero, iLandOrWaterZone, tLZOrWZData, tLZOrWZTeamData, oACU, false))))  then
                                                                                                                    if bDebugMessages == true then LOG(sFunctionRef..': Dont want to get reclaim, will see if want to attack adjacent enemies; are there adjacent enemies='..tostring(tLZOrWZTeamData[AiBotMap.subrefbEnemiesInThisOrAdjacentLZ])..'; tLZTeamData[AiBotMap.subrefbDangerousEnemiesInAdjacentWZ]='..tostring(tLZOrWZTeamData[AiBotMap.subrefbDangerousEnemiesInAdjacentWZ])) end
                                                                                                                    --Is a friendly ACU getting an upgrade in this or an adjacent zone? If so then assist it
                                                                                                                    if bDebugMessages == true then LOG(sFunctionRef..': Checking if we want to assist a friendly nearby upgrading ACU if there is one') end
                                                                                                                    if not(AssistNearbyUpgradingACU(iPlateauOrZero, iLandOrWaterZone, tLZOrWZData, tLZOrWZTeamData, oACU)) then
                                                                                                                        --Search for any mexes nearby
                                                                                                                        if bDebugMessages == true then LOG(sFunctionRef..': Will search for unbuilt mexes in the zone with no search radius (unless have a big gun and not early on), oACU[AiBotUnitInfo.refiDFMassThreatOverride]='..(oACU[AiBotUnitInfo.refiDFMassThreatOverride] or 'nil')..'; subrefbEnemiesInThisOrAdjacentLZ='..tostring(tLZOrWZTeamData[AiBotMap.subrefbEnemiesInThisOrAdjacentLZ] or false)) end
                                                                                                                        if AiBotConditions.HaveEngineersOrFactoriesInZone(tLZOrWZTeamData) or (oACU[refiUpgradeCount] >= 2 and not(tLZOrWZTeamData[AiBotMap.subrefLZbCoreBase]) and tLZOrWZTeamData[AiBotMap.subrefbEnemiesInThisOrAdjacentLZ] and GetGameTimeSeconds() >= 180 and (oACU[AiBotUnitInfo.refiDFMassThreatOverride]) >= 4000) or not(ConsiderBuildingMex(tLZOrWZData, tLZOrWZTeamData, oACU)) then
                                                                                                                            if tLZOrWZTeamData[AiBotMap.subrefbEnemiesInThisOrAdjacentLZ] and (iClosestOutOfThresholdEnemy or 1000) <= 120 and AttackNearestEnemyWithACU(iPlateauOrZero, iLandOrWaterZone, tLZOrWZData, tLZOrWZTeamData, oACU, iClosestOutOfThresholdEnemy) then
                                                                                                                                --Do nothing - will have given the order
                                                                                                                                if bDebugMessages == true then LOG(sFunctionRef..':Attacking slightly further away enemies') end
                                                                                                                            else
                                                                                                                                if bDebugMessages == true then LOG(sFunctionRef..': Will consider moving to another land zone as nothing to do in this one') end
                                                                                                                                if not(MoveToOtherLandZone(iPlateauOrZero, tLZOrWZData, iLandOrWaterZone, oACU)) then
                                                                                                                                    --Do we have any reclaim nearby?
                                                                                                                                    if bDebugMessages == true then LOG(sFunctionRef..': Very low priority and threshold reclaim checker about to be checked') end
                                                                                                                                    if not(ConsiderNearbyReclaimForACUOrEngineer(iPlateauOrZero, iLandOrWaterZone, tLZOrWZData, tLZOrWZTeamData, oACU, false, 0.1, 0.1, 0.8)) then
                                                                                                                                        --Assist any upgrading mex or under construction storage if we have power but low mass

                                                                                                                                        if aiBrain:GetEconomyStoredRatio('ENERGY') >= 0.99 and AssistBuildingUpgradeOrStorageConstruction(iPlateauOrZero, iLandOrWaterZone, tLZOrWZData, tLZOrWZTeamData, oACU) then
                                                                                                                                            if bDebugMessages == true then LOG(sFunctionRef..': Are assisting am ex upgrade or storage construction') end
                                                                                                                                            --Backup - assist nearest factory
                                                                                                                                        else
                                                                                                                                            if bDebugMessages == true then LOG(sFunctionRef..': ACU no longer doing iniitial BO; Will give backup assist factory order if not building or guarding, ACU unit state='..AiBotUnitInfo.GetUnitState(oACU)) end
                                                                                                                                            if not(oACU:IsUnitState('Building')) and not(oACU:IsUnitState('Guarding')) and not(oACU:IsUnitState('Capturing')) then
                                                                                                                                                local tAllFactories = aiBrain:GetListOfUnits(AiBotUnitInfo.refCategoryFactory, false, true)
                                                                                                                                                if AiBotUtilities.IsTableEmpty(tAllFactories) == false then
                                                                                                                                                    local oNearestFactory = AiBotUtilities.GetNearestUnit(tAllFactories, oACU:GetPosition(), true, AiBotMap.refPathingTypeHover)
                                                                                                                                                    if AiBotUnitInfo.IsUnitValid(oNearestFactory) then
                                                                                                                                                        AiBotOrders.IssueTrackedGuard(oACU, oNearestFactory, false)
                                                                                                                                                    end
                                                                                                                                                end
                                                                                                                                            end
                                                                                                                                        end
                                                                                                                                    end
                                                                                                                                end
                                                                                                                            end
                                                                                                                        end
                                                                                                                    end
                                                                                                                end
                                                                                                            end
                                                                                                        end
                                                                                                    end
                                                                                                end
                                                                                            end
                                                                                        end
                                                                                    end
                                                                                end
                                                                            end
                                                                        end
                                                                    end
                                                                end
                                                            end
                                                        end
                                                    end
                                                end
                                            end
                                        end
                                    end
                                end
                            end
                        end
                    end
                end
            end
        end
    end
    if oACU[refbACUHasBeenGivenABuildOrderRecently] and not(AiBotConditions.DoesACUHaveValidOrder(oACU)) and (AiBotOrders.bDontConsiderCombinedArmy or oACU.AiBotActive) then AiBotEngineer.ClearEngineerTracking(oACU) end
    if bDebugMessages == true then LOG(sFunctionRef..': End of code, does ACU have valid order='..tostring(AiBotConditions.DoesACUHaveValidOrder(oACU))..'; reprs of last order='..reprs(oACU[AiBotOrders.reftiLastOrders])) end

    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
end

function DoWeStillWantToBeAggressiveWithACU(oACU)
    --Intended for early game mostly on smaller maps to make ACU more aggressive, or teamgames where we have 3+ ACUs alive
    local sFunctionRef = 'DoWeStillWantToBeAggressiveWithACU'
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)

    local bStillBeAggressive = true
    local aiBrain = oACU:GetAIBrain()
    local iTeam = aiBrain.AiBotTeam

    --Still be aggressive if are attempting a snipe
    if bDebugMessages == true then LOG(sFunctionRef..': Is table of enemy snipe targets empty='..tostring(AiBotUtilities.IsTableEmpty(AiBotTeam.tTeamData[iTeam][AiBotTeam.toActiveSnipeTargets]))) end
    local bNotCloseToSnipeTarget = true
    if AiBotUtilities.IsTableEmpty(AiBotTeam.tTeamData[iTeam][AiBotTeam.toActiveSnipeTargets]) == false then
        for iTarget, oTarget in AiBotTeam.tTeamData[iTeam][AiBotTeam.toActiveSnipeTargets] do
            if AiBotUnitInfo.IsUnitValid(oTarget) and AiBotUtilities.GetDistanceBetweenPositions(oTarget:GetPosition(), oACU:GetPosition()) <= 60 then
                bNotCloseToSnipeTarget = false
                break
            end
        end
    end
    if bNotCloseToSnipeTarget then
        if AiBotTeam.tTeamData[iTeam][AiBotTeam.refbDangerousForACUs] then
            bStillBeAggressive = false
        else
            --If we are going all-in on T1 spam then want to be aggressive with ACU if it has a gun
            local tLZOrWZData, tLZOrWZTeamData = AiBotMap.GetLandOrWaterZoneData(oACU:GetPosition(), true, oACU:GetAIBrain().AiBotTeam)
            if oACU[refiUpgradeCount] > 0 and AiBotConditions.ZoneWantsT1Spam(tLZOrWZTeamData, iTeam) and AiBotUnitInfo.GetUnitHealthPercent(oACU) >= 0.7 and GetGameTimeSeconds() <= 1000 and tLZOrWZTeamData[AiBotMap.refiModDistancePercent] < 0.6 then
                --Will remain aggressive
            elseif AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiActiveAiBotBrainCount] >= 3 and AiBotUnitInfo.GetUnitHealthPercent(oACU) >= 0.9 and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestFriendlyFactoryTech] < 3 and (AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestEnemyGroundTech] or 0) < 3 and (AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestEnemyAirTech] or 0) < 2 and (AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestEnemyNavyTech] or 0) < 2 and not(AiBotTeam.tTeamData[iTeam][AiBotTeam. refbAssassinationOrSimilar]) then
                bStillBeAggressive = true --redundancy
            else
                --If significant time elapsed then remove this flag
                if GetGameTimeSeconds() >= 900 then
                    bStillBeAggressive = false
                else
                    local iThresholdFactor = 1 + ((AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiActiveAiBotBrainCount] or 1) - 1) * 0.25
                    if tLZOrWZData[AiBotMap.subrefTotalSignificantMassReclaim] > 350 then iThresholdFactor = iThresholdFactor + 0.4 end
                    if AiBotUnitInfo.GetUnitHealthPercent(oACU) <= 0.3 then bStillBeAggressive = false
                    elseif aiBrain[AiBotEconomy.refiGrossMassBaseIncome] >= 5 * iThresholdFactor or (aiBrain[AiBotEconomy.refiOurHighestFactoryTechLevel] >= 2 and AiBotConditions.GetLifetimeBuildCount(aiBrain, AiBotUnitInfo.refCategoryEngineer + AiBotUnitInfo.refCategoryAllAir + AiBotUnitInfo.refCategoryLandCombat - categories.TECH1) >= 4) then
                        bStillBeAggressive = false
                    elseif AiBotMap.iMapSize > 512 and tLZOrWZTeamData[AiBotMap.refiModDistancePercent] >= 0.4 then
                        bStillBeAggressive = false
                    elseif not(aiBrain[AiBotMap.refbCanPathToEnemyBaseWithLand]) then
                        bStillBeAggressive = false
                    elseif AiBotTeam.tTeamData[iTeam][AiBotTeam.refbEnemyHasUpgradedACU] and (oACU[refiUpgradeCount] or 0) == 0 then
                        bStillBeAggressive = false
                    elseif AiBotConditions.GetLifetimeBuildCount(aiBrain, AiBotUnitInfo.refCategoryLandCombat) >= 50 * iThresholdFactor then
                        bStillBeAggressive = false
                    elseif AiBotMap.bIsCampaignMap then
                        bStillBeAggressive = false
                    elseif AiBotTeam.tTeamData[iTeam][AiBotTeam.refiMexCountByTech][3] > 0 or AiBotConditions.GetHighestOtherTeamT3MexCount(iTeam) > 0 then
                        bStillBeAggressive = false
                    end
                end
            end
        end
    end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
    return bStillBeAggressive
end

function ManageACU(aiBrain, oACUOverride)
    local sFunctionRef = 'ManageACU'
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)
    --First get our ACU
    local oACU = oACUOverride
    local iWaitCount = 0
    local iACUSearchCategory = categories.COMMAND
    while not(oACU) do
        local tOurACU = aiBrain:GetListOfUnits(iACUSearchCategory, false, true)
        if bDebugMessages == true then LOG(sFunctionRef..': Searching for ACUs at time='..GetGameTimeSeconds()..'; Is tOurACU empty='..tostring(AiBotUtilities.IsTableEmpty(tOurACU))) end
        if AiBotUtilities.IsTableEmpty(tOurACU) == false then
            for _, oUnit in tOurACU do
                if bDebugMessages == true then LOG(sFunctionRef..': Considering oUnit='..(oUnit.UnitId or 'nil')..(AiBotUnitInfo.GetUnitLifetimeCount(oUnit) or 'nil')..'; Is unit valid='..tostring(AiBotUnitInfo.IsUnitValid(oUnit))) end
                if AiBotUnitInfo.IsUnitValid(oUnit) then
                    if bDebugMessages == true then LOG(sFunctionRef..': Have an ACU so will break') end
                    oACU = oUnit
                    break
                end
            end
        end
        if bDebugMessages == true then LOG(sFunctionRef..': Looking for ACU that we own, is oACU valid='..tostring(AiBotUnitInfo.IsUnitValid(oACU))..'; oACU='..(oACU.UnitId or 'nil')..(AiBotUnitInfo.GetUnitLifetimeCount(oACU) or 'nil')) end
        if oACU then
            oACU[refbDoingInitialBuildOrder] = true
            break
        end
        iWaitCount = iWaitCount + 1
        AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
        WaitTicks(1)
        AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)
        if iWaitCount >= 360 then --No ACU after 6m, see if we have any SACU we could use instead
            iACUSearchCategory = iACUSearchCategory + categories.SUBCOMMANDER
            -- if iWaitCount >= 480 then
            --iACUSearchCategory = iACUSearchCategory + AiBotUnitInfo.refCategoryEngineer
            if iWaitCount >= 600 then
                AiBotUtilities.ErrorHandler('No ACU or SACU after '..iWaitCount..' ticks so will abort')
                break
            end
            --end
        end
    end
    if bDebugMessages == true then LOG(sFunctionRef..': Checking if have oACU, oACU='..(oACU.UnitId or 'nil')..(AiBotUnitInfo.GetUnitLifetimeCount(oACU) or 'nil')) end
    if oACU then

        --Wait until ok for us to give orders
        if bDebugMessages == true then LOG(sFunctionRef..': Will wait until after 4.5s before giving ACU orders, gametime='..GetGameTimeSeconds()) end
        while (GetGameTimeSeconds() <= 4.5) do
            AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
            WaitTicks(1)
            AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)
        end

        --Campaign specific - check if friendly units should gift to AiBotAI if near start of game (to avoid e.g. fletcher gating in on M5 and being gifted AiBot player units)
        if AiBotMap.bIsCampaignMap and GetGameTimeSeconds() <= 180 then
            ForkThread(AiBotOverseer.CheckForAlliedCampaignUnitsToShareAtGameStart, oACU:GetAIBrain())
        end

        if AiBotUnitInfo.IsUnitValid(oACU) and not(AiBotUnitInfo.IsUnitValid(aiBrain[refoPrimaryACU])) then
            aiBrain[refoPrimaryACU] = oACU
        end

        --Make sure ACU is recorded
        AiBotTeam.AssignUnitToLandZoneOrPond(aiBrain, oACU, false, false, true)

        --Make sure we have recorded this zone as a core zone
        --[[local iPlateauOrZero, iLandOrWaterZone = AiBotMap.GetClosestPlateauOrZeroAndZoneToPosition(oACU:GetPosition())
        local tLZTeamData
        if iPlateauOrZero > 0 and (iLandOrWaterZone or 0) > 0 and GetGameTimeSeconds() <= 10 then
            tLZTeamData = AiBotMap.tAllPlateaus[iPlateauOrZero][AiBotMap.subrefPlateauLandZones][iLandOrWaterZone][AiBotMap.subrefLZTeamData][oACU:GetAIBrain().AiBotTeam]
        end--]]

        oACU[refiUpgradeCount] = 0
        oACU[refbUseACUAggressively] = true
        oACU[refiBuildTech] = 1
        if EntityCategoryContains(categories.SUBCOMMANDER * categories.TECH3, oACU.UnitId) or EntityCategoryContains(AiBotUnitInfo.refCategoryEngineer, oACU.UnitId) then
            oACU[refiBuildTech] = AiBotUnitInfo.GetUnitTechLevel(oACU)
        elseif oACU.HasEnhancement then
            if oACU:HasEnhancement('AdvancedEngineering') then oACU[refiBuildTech] = 2
            elseif oACU:HasEnhancement('T3Engineering') then oACU[refiBuildTech] = 3
            end
        end

        if aiBrain.HostileCampaignAI and tonumber(ScenarioInfo.Options.CmpAIDelay) > GetGameTimeSeconds() then
            AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
            WaitSeconds(tonumber(ScenarioInfo.Options.CmpAIDelay) - GetGameTimeSeconds())
            AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)
        end

        --If this is an ACU then add to table of friendly ACUs, and set weapon prioritisation
        if EntityCategoryContains(categories.COMMAND, oACU.UnitId) then
            table.insert(AiBotTeam.tTeamData[aiBrain.AiBotTeam][AiBotTeam.reftAiBotACUs], oACU)
            AiBotUnitInfo.SetUnitWeaponTargetPriorities(oACU, AiBotUnitInfo.refWeaponPriorityACU, false)
            oACU[AiBotUnitInfo.refbUsingDefaultWeaponPriority] = true
        end

        if oACU[AiBotUnitInfo.refbEasyBrain] and oACU.SetAutoOvercharge then
            --Enable autoovercharge if have easy mode ACU
            local bHaveAutoOvercharge = false
            for iWeapon, tWeapon in oACU:GetBlueprint() do
                if tWeapon.Label == 'AutoOverCharge' then
                    bHaveAutoOvercharge = true
                    break
                end
            end
            if bHaveAutoOvercharge then
                oACU:SetAutoOvercharge(true)
            end
        end

        if oACU and oACU:GetAIBrain().AiBotSCTA then
            if oACU:GetBlueprint().Intel.JamRadius then
                AiBotUnitInfo.DisableUnitJamming(oACU)
            end
        end

        while AiBotUnitInfo.IsUnitValid(oACU) do
            oACU[refbTreatingAsACU] = true

            ForkThread(GetACUOrder, aiBrain, oACU)
            AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
            WaitSeconds(1)
            AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)
        end
    end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
end


function ConsiderIfACUNeedsEmergencySupport(iPlateauOrZero, iLandOrWaterZone, tLZOrWZData, tLZOrWZTeamData, oACU)
    --Updates flag on the zone ACU is in to indicate it needs help from tanks (i.e. it's facing a ground based threat)
    local sFunctionRef = 'ConsiderIfACUNeedsEmergencySupport'
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)

    if bDebugMessages == true then LOG(sFunctionRef..': Start of code, iPlateauOrZero='..iPlateauOrZero..'; iLandOrWaterZone='..iLandOrWaterZone..'; Health percent='..AiBotUnitInfo.GetUnitHealthPercent(oACU)..'; Enemies in this or adjacent LZ='..tostring(tLZOrWZTeamData[AiBotMap.subrefbEnemiesInThisOrAdjacentLZ] or false)..'; Core bse='..tostring(tLZOrWZTeamData[AiBotMap.subrefLZbCoreBase] or false)) end
    if iPlateauOrZero > 0 and tLZOrWZTeamData[AiBotMap.subrefbEnemiesInThisOrAdjacentLZ] and AiBotUnitInfo.GetUnitHealthPercent(oACU) < 0.98 and (not(tLZOrWZTeamData[AiBotMap.subrefLZbCoreBase]) or ((tLZOrWZTeamData[AiBotMap.subrefLZThreatEnemyMobileDFTotal] or 0) >= 200 and GetGameTimeSeconds() - (oACU[AiBotUnitInfo.refiLastWeaponEvent] or 0) <= 10)) then
        --ACU is damaged to some extent, outside core zone (or in core zone with enemies and in combat), and there are enemy ground units nearby
        local iEnemyCombatThreat = (tLZOrWZTeamData[AiBotMap.subrefTThreatEnemyCombatTotal] or 0)
        local iTeam = oACU:GetAIBrain().AiBotTeam
        if AiBotUtilities.IsTableEmpty(tLZOrWZData[AiBotMap.subrefLZAdjacentLandZones]) == false then
            --Include enemy combat units in adjacent zones if they are close to the ACU
            local tEnemyUnitsNearby = {}
            local iDistThreshold = 30 --This much dist until the unit will be in range of ACU for it to be included
            for iEntry, iAdjLZ in tLZOrWZData[AiBotMap.subrefLZAdjacentLandZones] do
                local tAdjLZTeamData = AiBotMap.tAllPlateaus[iPlateauOrZero][AiBotMap.subrefPlateauLandZones][iAdjLZ][AiBotMap.subrefLZTeamData][iTeam]
                if (tAdjLZTeamData[AiBotMap.subrefTThreatEnemyCombatTotal] or 0) > 50 and AiBotUtilities.IsTableEmpty(tAdjLZTeamData[AiBotMap.reftoNearestCombatEnemies]) == false then
                    for iUnit, oUnit in tAdjLZTeamData[AiBotMap.reftoNearestCombatEnemies] do
                        if AiBotUnitInfo.IsUnitValid(oUnit) then
                            if bDebugMessages == true then LOG(sFunctionRef..': Considering if enemy unit '..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..'; oUnit[AiBotUnitInfo.refiDFRange]='..(oUnit[AiBotUnitInfo.refiDFRange] or 'nil')..'; Dist to ACU='..AiBotUtilities.GetDistanceBetweenPositions(oACU:GetPosition(), oUnit:GetPosition())) end
                            if (oUnit[AiBotUnitInfo.refiDFRange] or 0) > 0 and EntityCategoryContains(categories.MOBILE, oUnit.UnitId) then
                                if AiBotUtilities.GetDistanceBetweenPositions(oACU:GetPosition(), oUnit:GetPosition()) - oUnit[AiBotUnitInfo.refiDFRange] <= iDistThreshold then
                                    table.insert(tEnemyUnitsNearby, oUnit)
                                end
                            end
                        end
                    end
                end
            end

            if AiBotUtilities.IsTableEmpty(tEnemyUnitsNearby) == false then
                iEnemyCombatThreat = iEnemyCombatThreat + AiBotUnitInfo.GetCombatThreatRating(tEnemyUnitsNearby, true, false, false, false, false, false, false)
            end
        end
        local iThreatRatio = 0.8
        if oACU[refbUseACUAggressively] then iThreatRatio = 1.1 end
        if AiBotUnitInfo.GetUnitHealthPercent(oACU) >= 0.75 then iThreatRatio = iThreatRatio * 1.26 end --i.e. if just us vs enemy ACU with similar stats shouldnt trigger unless our healt his getting low
        if bDebugMessages == true then LOG(sFunctionRef..': ACU threat='..AiBotUnitInfo.GetCombatThreatRating({oACU}, false, false)..'; iThreatRatio='..iThreatRatio..'; iEnemyCombatThreat='..iEnemyCombatThreat..'; Is table of ACUs in the LZ empty='..tostring(AiBotUtilities.IsTableEmpty(tLZOrWZTeamData[AiBotMap.subrefAlliedACU]))) end
        if AiBotUnitInfo.GetCombatThreatRating({oACU}, false, false) * iThreatRatio < iEnemyCombatThreat then
            tLZOrWZTeamData[AiBotMap.refbACUInTrouble] = true
            local iACUValueIncrease = GetValueIncreaseForACUInTrouble(iTeam)
            tLZOrWZTeamData[AiBotMap.subrefLZTValue] = math.max((tLZOrWZTeamData[AiBotMap.subrefLZTValue] or 0), iACUValueIncrease)
            if bDebugMessages == true then LOG(sFunctionRef..': Flagging that ACU is in trouble, tLZTeamData[AiBotMap.subrefLZTValue]='..(tLZOrWZTeamData[AiBotMap.subrefLZTValue] or 'nil')) end
            if AiBotUtilities.IsTableEmpty(tLZOrWZTeamData[AiBotMap.subrefAlliedACU]) then AiBotUtilities.ErrorHandler('ACU in trouble but not recorded against this LZ') end
            --Consider chat message if ACU health <75% and are in the first 20m
            if GetGameTimeSeconds() <= 1200 and AiBotUnitInfo.GetUnitHealthPercent(oACU) <= 0.7 then
                if AiBotOrders.bDontConsiderCombinedArmy or oACU.AiBotActive then
                    ForkThread(AiBotChat.ConsiderMessageForACUInTrouble, oACU, oACU:GetAIBrain())
                end
            end

        end
    end
    if bDebugMessages == true then LOG(sFunctionRef..': End of code, tLZOrWZTeamData[AiBotMap.refbACUInTrouble]='..tostring(tLZOrWZTeamData[AiBotMap.refbACUInTrouble] or false)..'; P'..iPlateauOrZero..'Z'..iLandOrWaterZone) end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
end

function GetValueIncreaseForACUInTrouble(iTeam)
    local iCurValue = 1000
    --Increase by more if in noshare or assassination
    if AiBotTeam.tTeamData[iTeam][AiBotTeam.refbAssassinationOrSimilar] then
        iCurValue = iCurValue + 20000
    end
    return iCurValue
end

function AssistNearbyUpgradingACU(iPlateauOrZero, iLandOrWaterZone, tLZOrWZData, tLZOrWZTeamData, oACU, iOptionalMaxDistOverride)
    local iTeam = oACU:GetAIBrain().AiBotTeam
    if AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiActiveAiBotBrainCount] > 1 and AiBotConditions.IsTableOfUnitsStillValid(AiBotTeam.tTeamData[iTeam][AiBotTeam.subreftTeamUpgradingACUs]) then
        local iCurDist
        local iClosestDist = (iOptionalMaxDistOverride or 80) --dont want to assist ACU further away than this
        if oACU[refiUpgradeCount] > 0 and not(oACU:HasEnhancement('AdvancedEngineering')) then iClosestDist = math.min(10, iClosestDist) end

        local oClosestUpgradingACU
        for iUpgradingACU, oUpgradingACU in AiBotTeam.tTeamData[iTeam][AiBotTeam.subreftTeamUpgradingACUs] do
            if not(oUpgradingACU == oACU) then
                iCurDist = AiBotUtilities.GetDistanceBetweenPositions(oUpgradingACU:GetPosition(), oACU:GetPosition())
                if iCurDist < iClosestDist then
                    if NavUtils.GetLabel(AiBotMap.refPathingTypeHover, oUpgradingACU:GetPosition()) == iPlateauOrZero or (iPlateauOrZero == 0 and NavUtils.GetLabel(AiBotMap.refPathingTypeHover, oUpgradingACU:GetPosition()) == NavUtils.GetLabel(AiBotMap.refPathingTypeHover, oACU:GetPosition())) then
                        if oUpgradingACU:GetWorkProgress() <= 0.75 or iCurDist <= 40 then
                            iClosestDist = iCurDist
                            oClosestUpgradingACU = oUpgradingACU
                        end
                    end
                end
            end

        end
        if oClosestUpgradingACU then
            AiBotOrders.IssueTrackedGuard(oACU, oClosestUpgradingACU, false, 'ACUAstU', false)
            return true
        end
    end
end

function CheckForNearbyMobileShieldToRequisition(oACU, tLZOrWZData, tLZOrWZTeamData, iTeam, iPlateauOrZero)
    local sFunctionRef = 'CheckForNearbyMobileShieldToRequisition'
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)
    
    if not(AiBotUnitInfo.IsUnitValid(oACU[AiBotLand.refoAssignedMobileShield])) and iPlateauOrZero > 0 then
        oACU[AiBotLand.refoAssignedMobileShield] = nil
        --Do we have access to T2 land, and aren't in our core base (hiding)?
        if bDebugMessages == true then LOG(sFunctionRef..': Considering ACU owned by brain '..oACU:GetAIBrain().Nickname..'; Is in core base='..tostring(tLZOrWZTeamData[AiBotMap.subrefLZbCoreBase])..'; Highest team factory tech='..AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestFriendlyLandFactoryTech]..'; Cur mobile shields on team='..AiBotConditions.GetCurrentAiBotUnitsOfCategoryInTeam(AiBotUnitInfo.refCategoryMobileLandShield, iTeam)) end
        if not(tLZOrWZTeamData[AiBotMap.subrefLZbCoreBase]) and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestFriendlyLandFactoryTech] >= 2 then
            if AiBotConditions.GetCurrentAiBotUnitsOfCategoryInTeam(AiBotUnitInfo.refCategoryMobileLandShield, iTeam) > 0 then
                --Cycle through this zone and adjacent zones looking for mobile shields
                local bSearchForShield = true
                local iCurDist
                local iClosestDist = 100000
                local oClosestShield
                local iCurShield, iMaxShield
                function CheckZoneForShields(tCurLZTeamData)
                    local tShieldsInZone = EntityCategoryFilterDown(AiBotUnitInfo.refCategoryMobileLandShield, tCurLZTeamData[AiBotMap.subreftoLZOrWZAlliedUnits])
                    if AiBotUtilities.IsTableEmpty(tShieldsInZone) == false then
                        for iShield, oShield in tShieldsInZone do
                            if AiBotUnitInfo.IsUnitValid(oShield) and oShield:GetFractionComplete() == 1 then
                                iCurShield, iMaxShield = AiBotUnitInfo.GetCurrentAndMaximumShield(oShield, true)
                                if bDebugMessages == true then LOG(sFunctionRef..': Considering if we want to requisition shield '..oShield.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oShield)..'; Dist to ACU='.. AiBotUtilities.GetDistanceBetweenPositions(oShield:GetPosition(), oACU:GetPosition())..'; iClosestDist='..iClosestDist) end
                                if iCurShield > 0 and iCurShield > iMaxShield * 0.6 and (not(oShield[AiBotLand.refoMobileShieldTarget].UnitId) or not(EntityCategoryContains(categories.COMMAND, oShield[AiBotLand.refoMobileShieldTarget].UnitId))) then
                                    iCurDist = AiBotUtilities.GetDistanceBetweenPositions(oShield:GetPosition(), oACU:GetPosition())
                                    if AiBotUnitInfo.IsUnitValid(oShield[AiBotLand.refoMobileShieldTarget]) then iCurDist = iCurDist + 15 end --want to favour an unassigned nearby shield in the unlikely event we have one
                                    if iCurDist < iClosestDist then
                                        iClosestDist = iCurDist
                                        oClosestShield = oShield
                                    end
                                end
                            end
                        end
                    end
                    if bDebugMessages == true then LOG(sFunctionRef..': oClosestShield='..(oClosestShield.UnitId or 'nil')..(AiBotUnitInfo.GetUnitLifetimeCount(oClosestShield) or 'nil')) end
                    if oClosestShield then
                        bSearchForShield = false
                        if AiBotUnitInfo.IsUnitValid(oClosestShield[AiBotLand.refoMobileShieldTarget]) then
                            oClosestShield[AiBotLand.refoMobileShieldTarget][AiBotLand.refoAssignedMobileShield] = nil
                        end
                        oClosestShield[AiBotLand.refoMobileShieldTarget] = oACU
                        oACU[AiBotLand.refoAssignedMobileShield] = oClosestShield
                        AiBotLand.MoveToShieldTarget(oClosestShield, tCurLZTeamData[AiBotMap.reftClosestEnemyBase])
                    end
                end
                CheckZoneForShields(tLZOrWZTeamData)
                if bSearchForShield and AiBotUtilities.IsTableEmpty(tLZOrWZData[AiBotMap.subrefLZAdjacentLandZones]) == false then
                    for _, iAdjLZ in tLZOrWZData[AiBotMap.subrefLZAdjacentLandZones] do
                        if bDebugMessages == true then LOG(sFunctionRef..': Searching in iAdjLZ='..iAdjLZ..' for mobile shields') end
                        CheckZoneForShields(AiBotMap.tAllPlateaus[iPlateauOrZero][AiBotMap.subrefPlateauLandZones][iAdjLZ][AiBotMap.subrefLZTeamData][iTeam])
                        if not(bSearchForShield) then break end
                    end
                end
            end

        end
    end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
end


function HaveActionForACUAsEngineer(oACU, tLZOrWZData, tLZOrWZTeamData, iPlateauOrZero, iLandOrWaterZone)
    --Intended where ACU has >=T2, returns true if we are giving the ACU a build order
    local sFunctionRef = 'HaveActionForACUAsEngineer'
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)



    local bGivenOrder = false
    if oACU[refiBuildTech] >= 2 then
        local aiBrain = oACU:GetAIBrain()
        local iTeam = aiBrain.AiBotTeam
        --Simple logic for now - only build more like an engineer if in core zone, and only if not stalling
        if bDebugMessages == true then LOG(sFunctionRef..': Checking if have at least some mass stored, and arent stalling mass, and are in core base, mass stored='..aiBrain:GetEconomyStored('MASS')..'; Are stalling mass='..tostring(AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefbTeamIsStallingMass])..'; In core base='..tostring(tLZOrWZTeamData[AiBotMap.subrefLZbCoreBase])) end
        if iPlateauOrZero > 0 and aiBrain:GetEconomyStored('MASS') > 0 and not(AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefbTeamIsStallingMass]) and (tLZOrWZTeamData[AiBotMap.subrefLZbCoreBase] or tLZOrWZTeamData[AiBotMap.subrefMexCountByTech][2] + tLZOrWZTeamData[AiBotMap.subrefMexCountByTech][3] >= 4) then
            --Emergency T2 PD if nearby enemies and we lack at least 2 (unless we have gun ACU)
            if tLZOrWZTeamData[AiBotMap.subrefbEnemiesInThisOrAdjacentLZ] and (oACU[AiBotUnitInfo.refiDFRange] < 30 or (oACU[refiBuildTech] >= 3 and not(AiBotConditions.HaveLowPower(iTeam)) and not(AiBotConditions.TeamHasLowMass(iTeam)))) then
                local iExistingLRPDThreat = 0
                if AiBotUtilities.IsTableEmpty(tLZOrWZTeamData[AiBotMap.subrefLZThreatAllyStructureDFByRange]) == false then
                    for iRange, iThreat in tLZOrWZTeamData[AiBotMap.subrefLZThreatAllyStructureDFByRange] do
                        if iRange >= 40 then
                            iExistingLRPDThreat = iExistingLRPDThreat + iThreat
                        end
                    end
                end
                if bDebugMessages == true then LOG(sFunctionRef..': Considering if we want to build PD, iExistingLRPDThreat='..iExistingLRPDThreat) end
                if iExistingLRPDThreat <= 1500 or (iExistingLRPDThreat <= 3000 and not(AiBotConditions.HaveLowPower(iTeam)) and not(AiBotConditions.TeamHasLowMass(iTeam))) then
                    --Check it is a significant enough enemy threat
                    local iNearbyEnemyThreat = (tLZOrWZTeamData[AiBotMap.subrefTThreatEnemyCombatTotal] or 0)
                    if AiBotUtilities.IsTableEmpty(tLZOrWZData[AiBotMap.subrefLZAdjacentLandZones]) == false then
                        for _, iAdjLZ in tLZOrWZData[AiBotMap.subrefLZAdjacentLandZones] do
                            local tAdjLZTeamData = AiBotMap.tAllPlateaus[iPlateauOrZero][AiBotMap.subrefPlateauLandZones][iAdjLZ][AiBotMap.subrefLZTeamData][iTeam]
                            iNearbyEnemyThreat = iNearbyEnemyThreat + (tAdjLZTeamData[AiBotMap.subrefLZThreatEnemyMobileDFTotal] or 0)
                        end
                    end
                    if AiBotUtilities.IsTableEmpty(tLZOrWZData[AiBotMap.subrefAdjacentWaterZones]) == false then
                        for iEntry, tSubtable in tLZOrWZData[AiBotMap.subrefAdjacentWaterZones] do
                            local iAdjWZ = tSubtable[AiBotMap.subrefAWZRef]
                            local tAdjWZTeamData = AiBotMap.tPondDetails[AiBotMap.tiPondByWaterZone[iAdjWZ]][AiBotMap.subrefPondWaterZones][iAdjWZ][AiBotMap.subrefWZTeamData][iTeam]
                            iNearbyEnemyThreat = iNearbyEnemyThreat + math.max(0, (tAdjWZTeamData[AiBotMap.subrefWZThreatEnemyVsSurface] or 0) - (tAdjWZTeamData[AiBotMap.subrefWZThreatEnemyAntiNavy] or 0))
                        end
                    end
                    if bDebugMessages == true then LOG(sFunctionRef..': iNearbyEnemyThreat='..iNearbyEnemyThreat..'; Gross mass='..aiBrain[AiBotEconomy.refiGrossMassBaseIncome]) end
                    if iNearbyEnemyThreat >= 500 or (iNearbyEnemyThreat >= math.max(150, iExistingLRPDThreat * 0.5) and (iExistingLRPDThreat == 0 or not(AiBotConditions.TeamHasLowMass(iTeam)) or aiBrain[AiBotEconomy.refiGrossMassBaseIncome] >= 10)) then
                        if not(tLZOrWZTeamData[AiBotMap.refbBaseInSafePosition]) or AiBotUtilities.IsTableEmpty(aiBrain:GetUnitsAroundPoint(AiBotUnitInfo.refCategoryLandCombat, oACU:GetPosition(), 100, 'Enemy')) == false then
                            bGivenOrder = true
                            ACUBuildUnit(aiBrain, oACU, AiBotUnitInfo.refCategoryPD, 50, 60, nil, nil)
                            if bDebugMessages == true then LOG(sFunctionRef..': Will try and build PD') end
                        end
                    end
                end
            end
            --Do we have low power? If so then build some
            if not(bGivenOrder) then
                if bDebugMessages == true then LOG(sFunctionRef..': Checking if want to build power, have low power='..tostring(AiBotConditions.HaveLowPower(iTeam))..'; Highest factory tech='..AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestFriendlyFactoryTech]..'; Want more power='..tostring(AiBotConditions.WantMorePower(iTeam))..'; have low mass='..tostring(AiBotConditions.TeamHasLowMass(iTeam))) end
                if AiBotConditions.HaveLowPower(iTeam) or (oACU[refiBuildTech] >= AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestFriendlyFactoryTech] and AiBotConditions.WantMorePower(iTeam) and not(AiBotConditions.TeamHasLowMass(iTeam))) then
                    --If we dont have highest tech level then look to just assist power
                    if oACU[refiBuildTech] >= aiBrain[AiBotEconomy.refiOurHighestFactoryTechLevel] then
                        ACUActionBuildPower(aiBrain, oACU)
                        bGivenOrder = true
                        if bDebugMessages == true then LOG(sFunctionRef..': We have highest tech available on acu so will build power') end
                    else
                        local oPowerToAssist = AiBotEngineer.GetPartCompleteBuildingInZone(iTeam, iPlateauOrZero, iLandOrWaterZone, AiBotUnitInfo.refCategoryPower)
                        if bDebugMessages == true then LOG(sFunctionRef..': Only want to assist an under construction power, oPowerToAssist='..(oPowerToAssist.UnitId or 'nil')..(AiBotUnitInfo.GetUnitLifetimeCount(oPowerToAssist) or 'nil')) end
                        if oPowerToAssist then
                            bGivenOrder = true
                            AiBotOrders.IssueTrackedRepair(oACU, oPowerToAssist, false, 'ACUAstP', false)
                            if bDebugMessages == true then LOG(sFunctionRef..': Will assist pgen') end
                        end
                    end
                    --Get experimental if T3 and dont have low power and have all t3 mexes in zone, subject to normal overrides
                elseif oACU[refiBuildTech] >= 3 and tLZOrWZTeamData[AiBotMap.subrefMexCountByTech][3] >= tLZOrWZData[AiBotMap.subrefLZOrWZMexCount] and (tLZOrWZTeamData[AiBotMap.subrefLZbCoreBase] or (AiBotTeam.tTeamData[iTeam][AiBotTeam.refiConstructedExperimentalCount] > 2 and tLZOrWZTeamData[AiBotMap.refiModDistancePercent] <= 0.15 and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamAverageMassPercentStored] >= 0.7 and not(AiBotConditions.HaveLowPower(iTeam))))
                        and (AiBotTeam.tTeamData[iTeam][AiBotTeam.refiConstructedExperimentalCount] > 0 or AiBotConditions.GetTeamLifetimeBuildCount(iTeam, AiBotUnitInfo.refCategoryLandCombat + AiBotUnitInfo.refCategoryAirNonScout * categories.TECH3) >= 50)
                then
                    local tbEngineersOfFaction = {}
                    tbEngineersOfFaction[AiBotUnitInfo.GetUnitFaction(oACU)] = true
                    local iExperimentalCategory = AiBotEngineer.DecideOnExperimentalToBuild(AiBotEngineer.refActionReclaimFriendlyUnit, aiBrain, tbEngineersOfFaction, tLZOrWZData, tLZOrWZTeamData, iPlateauOrZero, iLandOrWaterZone)
                    if iExperimentalCategory then
                        if not(iExperimentalCategory == AiBotEngineer.refActionManageGameEnderTemplate) then
                            bGivenOrder = true
                            local oExpToAssist = AiBotEngineer.GetPartCompleteBuildingInZone(iTeam, iPlateauOrZero, iLandOrWaterZone, iExperimentalCategory)
                            if oExpToAssist then
                                AiBotOrders.IssueTrackedRepair(oACU, oExpToAssist, false, 'ACUAstEx', false)
                            else
                                ACUBuildUnit(aiBrain, oACU, iExperimentalCategory, 50, 60, nil, nil)
                            end
                        else
                            local oExpToAssist = AiBotEngineer.GetPartCompleteBuildingInZone(iTeam, iPlateauOrZero, iLandOrWaterZone, AiBotUnitInfo.refCategoryExperimentalLevel + AiBotUnitInfo.refCategoryFixedShield)
                            if oExpToAssist then
                                bGivenOrder = true
                                AiBotOrders.IssueTrackedRepair(oACU, oExpToAssist, false, 'ACUAstGEx', false)
                            end
                        end
                    end
                end

                if not(bGivenOrder) then
                    --Consider assisting a nearby upgrading unti as a high priority if lots of mass
                    if bDebugMessages == true then LOG(sFunctionRef..': If have lots of mass will consider assisting nearby construction, stored%='..aiBrain:GetEconomyStoredRatio('MASS')) end
                    if aiBrain:GetEconomyStoredRatio('MASS') >= 0.4 and not(AiBotConditions.HaveLowPower(iTeam)) and AiBotUtilities.IsTableEmpty(tLZOrWZTeamData[AiBotMap.subreftoActiveUpgrades]) == false then
                        --If are at T2 and next upgrade is for T3 then consider getting this
                        if  oACU[refiBuildTech] == 2 and tLZOrWZTeamData[AiBotMap.subrefMexCountByTech][3] >= 1 and aiBrain[AiBotEconomy.refiGrossEnergyBaseIncome] >= 150 then
                            local sUpgradeWanted, bIgnoreOtherUpgradeConditions
                            if tLZOrWZTeamData[AiBotMap.subrefMexCountByTech][3] >= 3 and aiBrain[AiBotEconomy.refiGrossEnergyBaseIncome] >= 300 then
                                --Ignore eco checks
                                sUpgradeWanted, bIgnoreOtherUpgradeConditions = GetACUUpgradeWanted(oACU, false, tLZOrWZData, tLZOrWZTeamData, iPlateauOrZero, true)
                            else
                                sUpgradeWanted, bIgnoreOtherUpgradeConditions = GetACUUpgradeWanted(oACU, false, tLZOrWZData, tLZOrWZTeamData, iPlateauOrZero, false)
                            end

                            if sUpgradeWanted then
                                if bDebugMessages == true then LOG(sFunctionRef..': Want to get T3 on ACU') end
                                bGivenOrder = true
                                if bIgnoreOtherUpgradeConditions or AiBotConditions.SafeToUpgradeUnit(oACU) then
                                    if bDebugMessages == true then LOG(sFunctionRef..': ACU Eng Safe to get upgrade here so will proceed with upgrading ACU, sUpgradeWanted='..(sUpgradeWanted or 'nil')..' brain='..oACU:GetAIBrain().Nickname..'; Has enhancement='..tostring(oACU:HasEnhancement(sUpgradeWanted))) end
                                    if GetGameTimeSeconds() - (AiBotTeam.tTeamData[iTeam][AiBotTeam.refiTimeLastIssuedACUEnhancementOrder] or -100) >= 2 or (oACU[AiBotOrders.refiTimeOfLastRemovalUpgrade] and GetGameTimeSeconds() - oACU[AiBotOrders.refiTimeOfLastRemovalUpgrade] <= 10) or oACU[AiBotOrders.reftiLastOrders][oACU[AiBotOrders.refiOrderCount]][AiBotOrders.subrefsOrderBlueprint] == sUpgradeWanted then
                                        AiBotOrders.IssueTrackedEnhancement(oACU, sUpgradeWanted, false, 'ACUEUpr')
                                    end
                                else
                                    --Retreat
                                    local tRallyPoint = AiBotLand.GetNearestLandRallyPoint(tLZOrWZData, oACU:GetAIBrain().AiBotTeam, iPlateauOrZero, iLandOrWaterZone, 2)
                                    if bDebugMessages == true then LOG(sFunctionRef..': ACU Eng Not safe to get upgrade so want to retreat until it is. tRallyPoint='..repru(tRallyPoint)..'; ACU position='..repru(oACU:GetPosition())) end
                                    AiBotOrders.IssueTrackedMove(oACU, tRallyPoint, 5, false, 'RE4U')
                                end
                            end
                        end
                        if not(bGivenOrder) then

                            bGivenOrder = AssistBuildingUpgradeOrStorageConstruction(iPlateauOrZero, iLandOrWaterZone, tLZOrWZData, tLZOrWZTeamData, oACU)
                            if bDebugMessages == true then LOG(sFunctionRef..': bGivenOrder after checking if want to assist an upgrade='..tostring(bGivenOrder)) end
                        end
                    end
                end
            end
        end

    end
    if bDebugMessages == true then LOG(sFunctionRef..': End of code for ACU owned by brain '..oACU:GetAIBrain().Nickname..'; oACU[refiBuildTech]='..(oACU[refiBuildTech] or 'nil')..', bGivenOrder='..tostring(bGivenOrder)..'; Time='..GetGameTimeSeconds()) end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
    return bGivenOrder
end

function HaveACUSnipeAction(oACU, iTeam, iPlateauOrZero, iLandOrWaterZone, tLZOrWZData, tLZOrWZTeamData)
    local sFunctionRef = 'HaveACUSnipeAction'
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)


    if AiBotConditions.IsTableOfUnitsStillValid(AiBotTeam.tTeamData[iTeam][AiBotTeam.toActiveSnipeTargets]) and (oACU[AiBotUnitInfo.refiDFRange] or 0) >= 20 then
        local oClosestEnemyTarget
        local iClosestEnemyTarget = oACU[AiBotUnitInfo.refiDFRange] + 30 --dont want ACU to try and attack if its further away than this
        local iCurDist
        for iUnit, oUnit in AiBotTeam.tTeamData[iTeam][AiBotTeam.toActiveSnipeTargets] do
            if NavUtils.GetTerrainLabel(AiBotMap.refPathingTypeHover, oUnit:GetPosition()) == iPlateauOrZero then
                iCurDist = AiBotUtilities.GetDistanceBetweenPositions(oUnit:GetPosition(), oACU:GetPosition())
                if iCurDist < iClosestEnemyTarget then
                    iClosestEnemyTarget = iCurDist
                    oClosestEnemyTarget = oUnit
                end
            end
        end
        if bDebugMessages == true then LOG(sFunctionRef..': oClosestEnemyTarget='..(oClosestEnemyTarget.UnitId or 'nil')..(AiBotUnitInfo.GetUnitLifetimeCount(oClosestEnemyTarget) or 'nil')..'; iClosestEnemyTarget='..(iClosestEnemyTarget or 'nil')..'; Our ACU range='..(oACU[AiBotUnitInfo.refiDFRange] or 'nil')) end
        if oClosestEnemyTarget then
            if bDebugMessages == true then LOG(sFunctionRef..': Our ACU health%='..AiBotUnitInfo.GetUnitHealthPercent(oACU)..'; Target ACU health%='..AiBotUnitInfo.GetUnitHealthPercent(oClosestEnemyTarget)) end
            if iClosestEnemyTarget < oACU[AiBotUnitInfo.refiDFRange] - 6 then
                AiBotOrders.IssueTrackedAggressiveMove(oACU, oClosestEnemyTarget:GetPosition(), 6, false, 'ACUSni', false)
            else
                AiBotOrders.IssueTrackedMove(oACU, oClosestEnemyTarget:GetPosition(), 6, false, 'ACUSni', false)
            end
        end
    end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
    return false
end

function ConsiderRunningToGETemplate(oACU, tLZOrWZData, tLZOrWZTeamData, iPlateauOrZero)
    local sFunctionRef = 'ConsiderRunningToGETemplate'
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)

    local iTeam = oACU:GetAIBrain().AiBotTeam
    --Do we want to run to GE template? only consider if enemy has multiple land exp, large air to ground threat, or we have built lots of experimentals
    if bDebugMessages == true then LOG(sFunctionRef..': start of code for ACU owned by brain '..oACU:GetAIBrain().Nickname..', is it dangerous for ACUs='..tostring(AiBotTeam.tTeamData[iTeam][AiBotTeam.refbDangerousForACUs])..'; Defend vs arti='..tostring(AiBotTeam.tTeamData[iTeam][AiBotTeam.refbDefendAgainstArti])..'; Our constructed exp count='..AiBotTeam.tTeamData[iTeam][AiBotTeam.refiConstructedExperimentalCount]..'; Enemy Air to ground threat='..AiBotTeam.tTeamData[iTeam][AiBotTeam.refiEnemyAirToGroundThreat]..'; Time='..GetGameTimeSeconds()) end
    if AiBotTeam.tTeamData[iTeam][AiBotTeam.refbDangerousForACUs] and ((AiBotTeam.tTeamData[iTeam][AiBotTeam.refbDefendAgainstArti] and (AiBotTeam.tTeamData[iTeam][AiBotTeam.refiEnemyT3ArtiCount] > 0 or AiBotTeam.tTeamData[iTeam][AiBotTeam.refiEnemyNovaxCount] > 1)) or AiBotTeam.tTeamData[iTeam][AiBotTeam.refiConstructedExperimentalCount] >= 3 or AiBotTeam.tTeamData[iTeam][AiBotTeam.refiEnemyAirToGroundThreat] >= 25000) then

        local iClosestShield = 1000 --(i.e. ignoring distance check for shields in this zone itself)
        local oClosestShield, iCurDist
        local bCheckIfOtherACUsUnderShield = false
        if AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiActiveAiBotBrainCount] > 1 then
            bCheckIfOtherACUsUnderShield = true
            if AiBotUnitInfo.GetUnitHealthPercent(oACU) < 0.9 then bCheckIfOtherACUsUnderShield = false end
        end
        if bDebugMessages == true then LOG(sFunctionRef..': Is table of GE templates for this zone empty='..tostring(AiBotUtilities.IsTableEmpty(tLZOrWZTeamData[AiBotMap.reftActiveGameEnderTemplates]))) end

        local bAlreadyHaveFriendlyACU
        if AiBotUtilities.IsTableEmpty(tLZOrWZTeamData[AiBotMap.reftActiveGameEnderTemplates]) == false then

            for iTemplate, tSubtable in tLZOrWZTeamData[AiBotMap.reftActiveGameEnderTemplates] do
                if tSubtable[AiBotMap.subrefGEbActiveShieldMonitor] and AiBotUtilities.IsTableEmpty(tSubtable[AiBotMap.subrefGEShieldUnits]) == false then
                    for iShield, oShield in tSubtable[AiBotMap.subrefGEShieldUnits] do
                        if AiBotUnitInfo.IsUnitValid(oShield) and oShield:GetFractionComplete() == 1 then
                            iCurDist = AiBotUtilities.GetDistanceBetweenPositions(oShield:GetPosition(), oACU:GetPosition())
                            if iCurDist < iClosestShield then
                                iClosestShield = iCurDist
                                oClosestShield = oShield
                            end
                        end
                    end
                end
            end
        end
        local tiPlateauAndZoneACUCount = {}
        if bCheckIfOtherACUsUnderShield then
            local iShieldPlateau, iShieldZone
            for iFriendlyACU, oFriendlyACU in AiBotTeam.tTeamData[iTeam][AiBotTeam.reftAiBotACUs] do
                if not(oFriendlyACU == oACU) then
                    if bDebugMessages == true then LOG(sFunctionRef..': oFriendlyACU owned by '..oFriendlyACU:GetAIBrain().Nickname..' has oFriendlyACU[refoShieldRallyTarget]='..(oFriendlyACU[refoShieldRallyTarget].UnitId or 'nil')..(AiBotUnitInfo.GetUnitLifetimeCount(oFriendlyACU[refoShieldRallyTarget]) or 'nil')..'; iShieldPlateau='..(oFriendlyACU[refoShieldRallyTarget][AiBotUnitInfo.reftAssignedPlateauAndLandZoneByTeam][iTeam][1] or 'nil')..'; iShieldZone='..(oFriendlyACU[refoShieldRallyTarget][AiBotUnitInfo.reftAssignedPlateauAndLandZoneByTeam][iTeam][2] or 'nil')) end
                    if oFriendlyACU[refoShieldRallyTarget] then
                        if oClosestShield and oFriendlyACU[refoShieldRallyTarget] == oClosestShield then
                            if bAlreadyHaveFriendlyACU then --means have 2+ ACUs already here
                                oClosestShield = nil
                                if bDebugMessages == true then LOG(sFunctionRef..': Nearest shield is a rally target for multiple ACUs so will clear it') end
                            else
                                if bDebugMessages == true then LOG(sFunctionRef..':nearest shield is already a rally target for another ACU') end
                                iClosestShield = iClosestShield + 250
                                bAlreadyHaveFriendlyACU = true
                            end
                        end
                        iShieldPlateau = oFriendlyACU[refoShieldRallyTarget][AiBotUnitInfo.reftAssignedPlateauAndLandZoneByTeam][iTeam][1]
                        iShieldZone = oFriendlyACU[refoShieldRallyTarget][AiBotUnitInfo.reftAssignedPlateauAndLandZoneByTeam][iTeam][2]
                        if iShieldPlateau and iShieldZone then
                            if not(tiPlateauAndZoneACUCount[iShieldPlateau]) then
                                tiPlateauAndZoneACUCount[iShieldPlateau] = {}
                            end
                            tiPlateauAndZoneACUCount[iShieldPlateau][iShieldZone] = (tiPlateauAndZoneACUCount[iShieldPlateau][iShieldZone] or 0) + 1
                        end
                    end

                end
            end
            if oClosestShield and (tiPlateauAndZoneACUCount[oClosestShield[AiBotUnitInfo.reftAssignedPlateauAndLandZoneByTeam][iTeam][1]][oClosestShield[AiBotUnitInfo.reftAssignedPlateauAndLandZoneByTeam][iTeam][2]] or 0) >= 2 then
                if bDebugMessages == true then LOG(sFunctionRef..': We already have 2 ACUs in this zone so want to consider a further away shield') end
                oClosestShield = nil
                bAlreadyHaveFriendlyACU = true
            end
        end
        if not(oClosestShield) or bAlreadyHaveFriendlyACU then
            --Do we have any active GE templates nearby in a zone with fewer than 2 assigned ACUs?
            if bDebugMessages == true then LOG(sFunctionRef..': dont have shield in GE template for this zone, is table of potentially active GE templates empty='..tostring(AiBotUtilities.IsTableEmpty(AiBotTeam.tTeamData[iTeam][AiBotTeam.tPotentiallyActiveGETemplates]))) end
            if AiBotUtilities.IsTableEmpty(AiBotTeam.tTeamData[iTeam][AiBotTeam.tPotentiallyActiveGETemplates]) == false then
                iClosestShield = math.min(iClosestShield, 300) --dont want to consider travelling further away than this
                for iEntry, tTemplateTable in AiBotTeam.tTeamData[iTeam][AiBotTeam.tPotentiallyActiveGETemplates] do
                    if bDebugMessages == true then LOG(sFunctionRef..': Considering entry '..iEntry..'; Active shield monitor='..tostring(tTemplateTable[AiBotMap.subrefGEbActiveShieldMonitor])..'; Is table of shield units empty='..tostring(AiBotUtilities.IsTableEmpty(tTemplateTable[AiBotMap.subrefGEShieldUnits]))..'; ACU count for this zone='..((tiPlateauAndZoneACUCount[tTemplateTable[AiBotMap.subrefGEShieldUnits][1][AiBotUnitInfo.reftAssignedPlateauAndLandZoneByTeam][iTeam][1]][tTemplateTable[AiBotMap.subrefGEShieldUnits][1][AiBotUnitInfo.reftAssignedPlateauAndLandZoneByTeam][iTeam][2]] or 0))) end
                    if tTemplateTable[AiBotMap.subrefGEbActiveShieldMonitor] and AiBotUtilities.IsTableEmpty(tTemplateTable[AiBotMap.subrefGEShieldUnits]) == false then
                        --Can we path here, and do we have fewer than 2 assigned ACUs?
                        if tTemplateTable[AiBotMap.subrefGEShieldUnits][1][AiBotUnitInfo.reftAssignedPlateauAndLandZoneByTeam][iTeam][1] == iPlateauOrZero and AiBotUnitInfo.IsUnitValid(tTemplateTable[AiBotMap.subrefGEShieldUnits][1])
                                and (tiPlateauAndZoneACUCount[tTemplateTable[AiBotMap.subrefGEShieldUnits][1][AiBotUnitInfo.reftAssignedPlateauAndLandZoneByTeam][iTeam][1]][tTemplateTable[AiBotMap.subrefGEShieldUnits][1][AiBotUnitInfo.reftAssignedPlateauAndLandZoneByTeam][iTeam][2]] or 0) < 2
                        then
                            iCurDist = AiBotUtilities.GetDistanceBetweenPositions(tTemplateTable[AiBotMap.subrefGEShieldUnits][1]:GetPosition(), oACU:GetPosition())
                            if bDebugMessages == true then LOG(sFunctionRef..': dist to shield '..tTemplateTable[AiBotMap.subrefGEShieldUnits][1].UnitId..AiBotUnitInfo.GetUnitLifetimeCount(tTemplateTable[AiBotMap.subrefGEShieldUnits][1])..'='..iCurDist) end
                            if iCurDist < iClosestShield then
                                if bCheckIfOtherACUsUnderShield then
                                    for iFriendlyACU, oFriendlyACU in AiBotTeam.tTeamData[iTeam][AiBotTeam.reftAiBotACUs] do
                                        if not(oFriendlyACU == oACU) then
                                            if oFriendlyACU[refoShieldRallyTarget] and oFriendlyACU[refoShieldRallyTarget] == tTemplateTable[AiBotMap.subrefGEShieldUnits][1] then
                                                if bDebugMessages == true then LOG(sFunctionRef..': Wont go to nearest shield as it is already a rally target for another ACU') end
                                                iClosestShield = iClosestShield + 250
                                            end
                                        end
                                    end
                                end
                                if iCurDist < iClosestShield then
                                    oClosestShield = tTemplateTable[AiBotMap.subrefGEShieldUnits][1]
                                    iClosestShield = iCurDist
                                end
                            end
                        end
                    end
                end
            end
        end
        if bDebugMessages == true then LOG(sFunctionRef..': Finished searching for shield to run to in GE template, oClosestShield='..(oClosestShield.UnitId or 'nil')..(AiBotUnitInfo.GetUnitLifetimeCount(oClosestShield) or 'nil')..'; bAlreadyHaveFriendlyACU='..tostring(bAlreadyHaveFriendlyACU or false)..'; bCheckIfOtherACUsUnderShield='..tostring(bCheckIfOtherACUsUnderShield)..'; oClosestShield assigned plateau and Zone=P'..(oClosestShield[AiBotUnitInfo.reftAssignedPlateauAndLandZoneByTeam][iTeam][1] or 'nil')..'Z'..(oClosestShield[AiBotUnitInfo.reftAssignedPlateauAndLandZoneByTeam][iTeam][2] or 'nil')) end
        if bAlreadyHaveFriendlyACU and not(oClosestShield) then
            --Get the ACU core base; If it doesnt have too many ACUs in it, and has shielding, then go here
            local iOrigBasePlateauOrZero, iOrigBaseLZOrWZ = AiBotMap.GetClosestPlateauOrZeroAndZoneToPosition(AiBotMap.GetPlayerStartPosition(oACU:GetAIBrain()))
            if bDebugMessages == true then LOG(sFunctionRef..': iOrigBasePlateauOrZero='..(iOrigBasePlateauOrZero or 'nil')..'; iOrigBaseLZOrWZ='..(iOrigBaseLZOrWZ or 'nil')..'; tiPlateauAndZoneACUCount='..repru(tiPlateauAndZoneACUCount))
                if iOrigBasePlateauOrZero and iOrigBaseLZOrWZ and (tiPlateauAndZoneACUCount[iOrigBasePlateauOrZero][iOrigBaseLZOrWZ] or 0) < 2 and iOrigBasePlateauOrZero > 0 then
                    local tOrigBaseLZData = AiBotMap.tAllPlateaus[iOrigBasePlateauOrZero][AiBotMap.subrefPlateauLandZones][iOrigBaseLZOrWZ]
                    local tOrigBaseLZTeamData = tOrigBaseLZData[AiBotMap.subrefLZTeamData][iTeam]
                    if AiBotUtilities.GetDistanceBetweenPositions(oACU:GetPosition(), tOrigBaseLZData[AiBotMap.subrefMidpoint]) <= 350 and tOrigBaseLZTeamData[AiBotMap.refiEnemyAirToGroundThreat] == 0 and tOrigBaseLZTeamData[AiBotMap.subrefTThreatEnemyCombatTotal] == 0 and tOrigBaseLZTeamData[AiBotMap.subrefiT3FixedShieldConstructedCount] > 0 and tOrigBaseLZTeamData[AiBotMap.subrefLZSValue] >= 5000 then
                        local tShieldsInOrigBase = EntityCategoryFilterDown(AiBotUnitInfo.refCategoryFixedShield - categories.TECH1 - categories.TECH2, tOrigBaseLZTeamData[AiBotMap.subreftoLZOrWZAlliedUnits])
                        if AiBotUtilities.IsTableEmpty(tShieldsInOrigBase) == false then
                            iClosestShield = 350
                            for iOrigShield, oOrigShield in tShieldsInOrigBase do
                                if not(oOrigShield.Dead) then
                                    iCurDist = AiBotUtilities.GetDistanceBetweenPositions(oOrigShield:GetPosition(), oACU:GetPosition())
                                    if bDebugMessages == true then LOG(sFunctionRef..': Considering dist to oOrigShield in core base='..oOrigShield.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oOrigShield)..'; iCurDist='..iCurDist) end
                                    if iCurDist < iClosestShield then
                                        oClosestShield = oOrigShield
                                        iClosestShield = iCurDist
                                    end
                                end
                            end
                        end
                    end
                end
            end
            if bDebugMessages == true then LOG(sFunctionRef..': Finished searching for shield in our original base and if we want to run to it, oClosestShield='..(oClosestShield.Unitid or 'nil')..(AiBotUnitInfo.GetUnitLifetimeCount(oClosestShield) or 'nil')..'; bAlreadyHaveFriendlyACU='..tostring(bAlreadyHaveFriendlyACU or false)) end
        end

        if oClosestShield then
            oACU[refoShieldRallyTarget] = oClosestShield
            if bDebugMessages == true then LOG(sFunctionRef..': iClosestShield='..iClosestShield..'; Shield radius='..(oClosestShield:GetBlueprint().Defense.Shield.ShieldSize or 0)..'; Shield health='..oClosestShield.MyShield:GetHealth()..'; brain'..oACU:GetAIBrain().Nickname..'; oClosestShield[AiBotBuilding.reftArtiTemplateRefs]='..repru(oClosestShield[AiBotBuilding.reftArtiTemplateRefs])..'; Assigned Plateau and Zone for oClosestShield=P'..oClosestShield[AiBotUnitInfo.reftAssignedPlateauAndLandZoneByTeam][iTeam][1]..'Z'..oClosestShield[AiBotUnitInfo.reftAssignedPlateauAndLandZoneByTeam][iTeam][2]..'; tiPlateauAndZoneACUCount='..repru(tiPlateauAndZoneACUCount)) end
            if iClosestShield <= 6 or (iClosestShield < math.min((oClosestShield:GetBlueprint().Defense.Shield.ShieldSize or 0) * 0.5 - 3.5, 26) and oClosestShield.MyShield.GetHealth and oClosestShield.MyShield:GetHealth() >= 5000) then
                --We want to be positioned inbetween the shield and the GE arti being shielded, to make sure if the shield is destroyed we are covered by other shields (as for some templates they only cover the midpoint of each shield)
                local tPositionToBeCloserTo

                if oClosestShield[AiBotBuilding.reftArtiTemplateRefs] then
                    local tTemplate = AiBotMap.tAllPlateaus[oClosestShield[AiBotBuilding.reftArtiTemplateRefs][1]][AiBotMap.subrefPlateauLandZones][oClosestShield[AiBotBuilding.reftArtiTemplateRefs][2]][AiBotMap.subrefLZTeamData][iTeam][AiBotMap.reftActiveGameEnderTemplates][oClosestShield[AiBotBuilding.reftArtiTemplateRefs][3]]
                    if bDebugMessages == true then LOG(sFunctionRef..': Is tTemplate[AiBotMap.subrefGEArtiLocations][1] nil='..tostring((tTemplate[AiBotMap.subrefGEArtiLocations][1] == nil))..'; is tTemplate nil='..tostring(tTemplate == nil)) end
                    if tTemplate[AiBotMap.subrefGEArtiLocations][1] then
                        local iACUDistToArti = AiBotUtilities.GetDistanceBetweenPositions(tTemplate[AiBotMap.subrefGEArtiLocations][1], oACU:GetPosition())
                        local iShieldDistToArti = AiBotUtilities.GetDistanceBetweenPositions(tTemplate[AiBotMap.subrefGEArtiLocations][1], oClosestShield:GetPosition())
                        if iACUDistToArti + 2 >= iShieldDistToArti then
                            tPositionToBeCloserTo = AiBotUtilities.MoveInDirection(oClosestShield:GetPosition(), AiBotUtilities.GetAngleFromAToB(oClosestShield:GetPosition(), tTemplate[AiBotMap.subrefGEArtiLocations][1]), 4)
                        end
                        if bDebugMessages == true then LOG(sFunctionRef..': iACUDistToArti='..iACUDistToArti..'; iShieldDistToArti='..iShieldDistToArti..'; tPositionToBeCloserTo='..repru(tPositionToBeCloserTo)) end

                    end
                end
                if tPositionToBeCloserTo then
                    if bDebugMessages == true then LOG(sFunctionRef..': Will move to be inbetween shield and the arti being protected') end
                    AiBotOrders.IssueTrackedMove(oACU, tPositionToBeCloserTo, 3, false, 'RunToGEAr')
                    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
                    return true
                else

                    local sUpgradeToGet, bIgnoreOtherUpgradeConditions = GetACUUpgradeWanted(oACU, false, tLZOrWZData, tLZOrWZTeamData, iPlateauOrZero, false)
                    if bDebugMessages == true then LOG(sFunctionRef..': Considering if want upgrade, sUpgradeToGet='..(sUpgradeToGet or 'nil')..'; Have low mass='..tostring(AiBotConditions.HaveLowMass(oACU:GetAIBrain()))..'; Have low power='..tostring(AiBotConditions.HaveLowPower(oACU:GetAIBrain()))..'; Stalling mass='..tostring(AiBotTeam.tTeamData[oACU:GetAIBrain().AiBotTeam][AiBotTeam.subrefbTeamIsStallingMass])..'; Gross brain mass='..oACU:GetAIBrain()[AiBotEconomy.refiGrossMassBaseIncome]) end
                    if sUpgradeToGet and (bIgnoreOtherUpgradeConditions or (not(AiBotConditions.HaveLowPower(oACU:GetAIBrain())) or oACU:GetAIBrain()[AiBotEconomy.refbBuiltParagon]) and not(AiBotTeam.tTeamData[oACU:GetAIBrain().AiBotTeam][AiBotTeam.subrefbTeamIsStallingMass]) and (not(AiBotConditions.HaveLowMass(oACU:GetAIBrain())) or oACU:GetAIBrain()[AiBotEconomy.refiGrossMassBaseIncome] >= 50)) then
                        AiBotOrders.IssueTrackedEnhancement(oACU, sUpgradeToGet, false, 'ACUUpLg')
                        if bDebugMessages == true then LOG(sFunctionRef..': Are under shield already but want to get an upgrade so will get upgrade') end
                        AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
                        return true
                    elseif iClosestShield <= 3 or (oClosestShield.MyShield.GetHealth and oClosestShield.MyShield:GetHealth() >= 5000) then
                        if bDebugMessages == true then LOG(sFunctionRef..': Are under the shield already so will consider normal ACU logic') end
                        AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
                        return false
                    end
                end
            elseif bDebugMessages == true then LOG(sFunctionRef..': want to move closer to the shield')
            end

            AiBotOrders.IssueTrackedMove(oACU, oClosestShield:GetPosition(), 4, false, 'RunToGESh')

            AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
            return true
        end
    end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
    return false
end

function HaveNearbyVulnerableEnemyACUToAttack(oACU, iTeam, tLZData, tLZTeamData, iPlateau, iStartLandZone)
    --Idea - if we have gun, and outrange enemy ACU in an adjacent zone with no upgrades, and enemy has no nearby units with same range as us, then will try attacking the ACU
    --Assumed we only call this if we are in a land zone, and have already called logic to attack enemies if we are almost in range of them

    local sFunctionRef = 'HaveNearbyVulnerableEnemyACUToAttack'
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)

    local bAttackNearestACU = false
    --Ignore if at core base (mainly for optimisation reasons)
    if not(tLZTeamData[AiBotMap.subrefLZbCoreBase]) and AiBotConditions.IsTableOfUnitsStillValid(AiBotTeam.tTeamData[iTeam][AiBotTeam.reftEnemyACUs]) then
        --Get closest enemy ACU
        local oClosestEnemyACU, iCurDist
        local iDistThreshold = 175
        local iClosestEnemyACU = iDistThreshold --Ignore ACUs further away than this (but still record dist, so if closest ACU is a guncom then we wont bother trying to kill one further away that lacks gun)
        for iEnemyACU, oEnemyACU in AiBotTeam.tTeamData[iTeam][AiBotTeam.reftEnemyACUs] do
            iCurDist = AiBotUtilities.GetDistanceBetweenPositions(oACU:GetPosition(), oEnemyACU:GetPosition())
            if iCurDist < iClosestEnemyACU then
                iClosestEnemyACU = iCurDist
                if oEnemyACU[AiBotUnitInfo.refiDFRange] < oACU[AiBotUnitInfo.refiDFRange] and ((oEnemyACU[refiUpgradeCount] or 0) == 0 or iCurDist <= 70) then
                    oClosestEnemyACU = oEnemyACU
                end
            end
        end
        if oClosestEnemyACU then
            --Have a nearby enemy ACU that we outrange; now check that the enemy has no threats with at least our range in any zones between us and them
            local iTargetPlateau, iTargetLandZone = AiBotMap.GetClosestPlateauOrZeroAndZoneToPosition(oClosestEnemyACU:GetPosition())
            if iTargetPlateau == iPlateau and NavUtils.GetTerrainLabel(AiBotMap.refPathingTypeLand, oClosestEnemyACU:GetPosition()) == tLZData[AiBotMap.subrefLZIslandRef] then
                --We are both on the same island; now record all zones between us and them
                local tLandZonesBetweenACUs = {}
                table.insert(tLandZonesBetweenACUs, iStartLandZone)
                if not(iStartLandZone==iTargetLandZone) then
                    table.insert(tLandZonesBetweenACUs, iTargetLandZone)
                    --Check if we are adjacent, if not then need to do more detailed pathing check
                    local bAreAdjacent = false
                    if AiBotUtilities.IsTableEmpty(tLZData[AiBotMap.subrefLZAdjacentLandZones]) == false then
                        for _, iAdjLZ in tLZData[AiBotMap.subrefLZAdjacentLandZones] do
                            if iAdjLZ == iTargetLandZone then
                                bAreAdjacent = true
                                break
                            end
                        end
                    end
                    if not(bAreAdjacent) then
                        if AiBotMap.GetTravelDistanceBetweenLandZones(iPlateau, iStartLandZone, iTargetLandZone, true) > iDistThreshold then
                            AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
                            return false
                        else
                            if not(tLZData[AiBotMap.subrefLZPathingToOtherLZEntryRef][iTargetLandZone]) then
                                AiBotMap.ConsiderAddingTargetLandZoneToDistanceFromBaseTable(iPlateau, iStartLandZone, iTargetLandZone, tLZData[AiBotMap.subrefMidpoint])
                            end
                            local iEntryNumber = tLZData[AiBotMap.subrefLZPathingToOtherLZEntryRef][iTargetLandZone]

                            if iEntryNumber then
                                --Change closest LZ to run to to be 2 along the path from cur LZ to the target LZ
                                for iEntry, iLZPointInPath in tLZData[AiBotMap.subrefLZPathingToOtherLandZones][iEntryNumber][AiBotMap.subrefLZPath] do
                                    local bAlreadyIncluded = false
                                    for iEntry, iZone in tLandZonesBetweenACUs do
                                        if iLZPointInPath == iZone then bAlreadyIncluded = true break end
                                    end
                                    if not(bAlreadyIncluded) then table.insert(tLandZonesBetweenACUs, iLZPointInPath) end
                                end
                            end
                        end
                    end
                end
                for iEntry, iAltLZ in tLandZonesBetweenACUs do
                    local tAltLZTeamData = AiBotMap.tAllPlateaus[iPlateau][AiBotMap.subrefPlateauLandZones][iAltLZ][AiBotMap.subrefLZTeamData][iTeam]
                    if tAltLZTeamData[AiBotMap.subrefbDangerousEnemiesInThisLZ] then
                        if tAltLZTeamData[AiBotMap.subrefLZThreatEnemyBestMobileDFRange] >= oACU[AiBotUnitInfo.refiDFRange] or tAltLZTeamData[AiBotMap.subrefLZThreatEnemyBestStructureDFRange] >= oACU[AiBotUnitInfo.refiDFRange] then
                            if bDebugMessages == true then LOG(sFunctionRef..': Zone has enemies with at least as much range as us so wont attack ACU') end
                            AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
                            return false
                        end
                    end
                end
                --If we have got here then we outrange all enemy threats in every zone between here and enemy
                if oACU[refbUseACUAggressively] or iTargetLandZone == iStartLandZone then
                    if bDebugMessages == true then LOG(sFunctionRef..': Using ACU aggressively, or enemy ACU is in same zone as us') end
                    bAttackNearestACU = true
                else
                    --Check enemy threat vs ours, and if we aren't significantly outmatched then advance (we will already be doing this in the check of if ACU should run from earlier, so this is to reduce instances where we advance to an enemy ACU and then retreat almost straight away
                    local iTotalFriendlyCombat = 0
                    local iTotalEnemyCombat = 0
                    for iEntry, iAltLZ in tLandZonesBetweenACUs do
                        local tAltLZTeamData = AiBotMap.tAllPlateaus[iPlateau][AiBotMap.subrefPlateauLandZones][iAltLZ][AiBotMap.subrefLZTeamData][iTeam]
                        iTotalFriendlyCombat = iTotalFriendlyCombat + tAltLZTeamData[AiBotMap.subrefLZTThreatAllyCombatTotal]
                        iTotalEnemyCombat = iTotalEnemyCombat + tAltLZTeamData[AiBotMap.subrefTThreatEnemyCombatTotal]
                    end
                    if iTotalEnemyCombat * 0.8 < iTotalFriendlyCombat or iTotalEnemyCombat < 800 then
                        bAttackNearestACU = true
                    end
                    if bDebugMessages == true then LOG(sFunctionRef..': iTotalEnemyCombat='..iTotalEnemyCombat..'; iTotalFriendlyCombat='..iTotalFriendlyCombat) end
                end
                if bDebugMessages == true then LOG(sFunctionRef..': Deciding if we want to attack nearest enemy ACU, oACU[refbUseACUAggressively]='..tostring(oACU[refbUseACUAggressively])..'; iTargetLandZone='..iTargetLandZone..'; iStartLandZone='..iStartLandZone..'; bAttackNearestACU='..tostring(bAttackNearestACU)) end
            end
            if bAttackNearestACU then
                --We have already checked in the condition immediately preciding this if we want to attack enemies we are in range of, so we can just go and move towards the enemy ACU
                if iClosestEnemyACU < (oClosestEnemyACU[AiBotUnitInfo.refiDFRange] or 0) + 2 then
                    --Redundancy - check not too close to the ACU - Attack-move as almost within their ACUs firing range
                    AiBotOrders.IssueTrackedAggressiveMove(oACU, oClosestEnemyACU:GetPosition(), 2, false, 'AtckACUAM')
                else
                    AiBotOrders.IssueTrackedMove(oACU, oClosestEnemyACU:GetPosition(), 2, false, 'AtckACUM')
                end
            end
        end
    end
    if bDebugMessages == true then LOG(sFunctionRef..': End of code, bAttackNearestACU='..tostring(bAttackNearestACU)) end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
    return bAttackNearestACU
end

function IsTargetSuitableSnipeTarget(oACU, oSnipeTarget, iOurACUPlateauOrZero, iDistanceThreshold, bMustBeWithinExplosionThreshold, bCalledFromUpgradingSnipeLogic, iOptionalHealthAdvantageAtStart)
    --Returns true/false if the target is suitable for an all-in ACU attack, and if returns how close the unit is
    local sFunctionRef = 'IsTargetSuitableSnipeTarget'
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)



    local iClosestDist
    local bIsSuitable
    if AiBotUnitInfo.IsUnitValid(oSnipeTarget) then
        local iDistAdjust = 0
        if oSnipeTarget:IsUnitState('Upgrading') then iDistAdjust = iACUAssassinationUpgradingRangeAdjust end
        if oACU[refbSupportFriendlyACUAttack] then iDistAdjust = iDistAdjust + 25 end
        if bDebugMessages == true then LOG(sFunctionRef..': Considering oSnipeTarget='..oSnipeTarget.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oSnipeTarget)..' owned by '..oSnipeTarget:GetAIBrain().Nickname..'; iOurACUPlateauOrZero='..iOurACUPlateauOrZero..'; iDistanceThreshold='..iDistanceThreshold..'; Enemy plateau='..(NavUtils.GetLabel(AiBotMap.refPathingTypeHover, oSnipeTarget:GetPosition()) or 'nil')..'; iCurDist='..AiBotUtilities.GetDistanceBetweenPositions(oSnipeTarget:GetPosition(), oACU:GetPosition())..'; oACU[refbACUSnipeModeActive]='..tostring(oACU[refbACUSnipeModeActive] or false)..'; bMustBeWithinExplosionThreshold='..tostring(bMustBeWithinExplosionThreshold or false)..'; iDistanceThreshold='..iDistanceThreshold..'; iDistAdjust='..iDistAdjust..'; refbSupportFriendlyACUAttack='..tostring(oACU[refbSupportFriendlyACUAttack] or false)..'; iOptionalHealthAdvantageAtStart='..(iOptionalHealthAdvantageAtStart or 'nil')) end
        if NavUtils.GetLabel(AiBotMap.refPathingTypeHover, oSnipeTarget:GetPosition()) == iOurACUPlateauOrZero then
            local iCurDist = AiBotUtilities.GetDistanceBetweenPositions(oSnipeTarget:GetPosition(), oACU:GetPosition())
            if iCurDist <= iDistanceThreshold + iDistAdjust then
                --We are in range of enemy ACU, check how many ACUs we have in range
                local iACUsInRange = 1
                local aiBrain = oACU:GetAIBrain()
                local tFriendlyACUs = aiBrain:GetUnitsAroundPoint(categories.COMMAND, oSnipeTarget:GetPosition(), 40, 'Ally')
                local bUpgradingSnipeLogic = bCalledFromUpgradingSnipeLogic
                if AiBotUtilities.IsTableEmpty(tFriendlyACUs) == false then
                    for iFriendlyACU, oFriendlyACU in tFriendlyACUs do
                        if oFriendlyACU[refbSupportFriendlyACUAttack] then bUpgradingSnipeLogic = true end
                        if not(oFriendlyACU == oACU) and AiBotUtilities.GetDistanceBetweenPositions(oFriendlyACU:GetPosition(), oSnipeTarget:GetPosition()) <= oFriendlyACU[AiBotUnitInfo.refiDFRange] + iDistAdjust then
                            if oFriendlyACU[refbACUSnipeModeActive] or AiBotUnitInfo.GetUnitCurHealthAndShield(oFriendlyACU) >= 4000 then
                                if iACUsInRange >= 2 then
                                    iACUsInRange = iACUsInRange + 0.5
                                else
                                    iACUsInRange = iACUsInRange + 1
                                end
                            else
                                iACUsInRange = iACUsInRange + 0.1
                            end
                        end
                    end
                end
                if bDebugMessages == true then LOG(sFunctionRef..': Is tFriendlyACUs empty='..tostring(AiBotUtilities.IsTableEmpty(tFriendlyACUs))..'; iACUsInRange='..iACUsInRange..'; Snipe target health='..AiBotUnitInfo.GetUnitCurHealthAndShield(oSnipeTarget)..'; Nearby shield value='..AiBotLogic.IsTargetUnderShield(aiBrain, oSnipeTarget, 0, true, false, false, true, false)) end
                --Check enemy doesnt have mobile or fixed shield
                local iEnemyACUHealth = AiBotUnitInfo.GetUnitCurHealthAndShield(oSnipeTarget) + AiBotLogic.IsTargetUnderShield(aiBrain, oSnipeTarget, 0, true, false, false, true, false)
                --death nuke does 2k damage; however are likely able to get a couple of shots off if enemy is just above this level
                if (iEnemyACUHealth < iACUsInRange * 3000 and not(AiBotUnitInfo.IsUnitUnderwater(oSnipeTarget)) and (not(bMustBeWithinExplosionThreshold) or (iEnemyACUHealth <= 2200 and iCurDist <= 28)))
                        or (oSnipeTarget:IsUnitState('Upgrading') and bUpgradingSnipeLogic and (not(iOptionalHealthAdvantageAtStart) or not(bMustBeWithinExplosionThreshold) or oACU[AiBotUnitInfo.refiDFRange] > oSnipeTarget[AiBotUnitInfo.refiDFRange] or iEnemyACUHealth <= 3000 or oACU:GetHealth() - AiBotUnitInfo.GetUnitCurHealthAndShield(oSnipeTarget) > math.max(iOptionalHealthAdvantageAtStart -1000, -500))) then
                    iClosestDist = iCurDist
                    bIsSuitable = true
                    if bDebugMessages == true then LOG(sFunctionRef..': Suitable snipe target, Cur health advantage='..oACU:GetHealth() - AiBotUnitInfo.GetUnitCurHealthAndShield(oSnipeTarget)..'; iOptionalHealthAdvantageAtStart='..(iOptionalHealthAdvantageAtStart or 'nil')) end
                end
            end
        end
    end
    if bDebugMessages == true then LOG(sFunctionRef..': End of code, bIsSuitable='..tostring(bIsSuitable)..'; iClosestDist='..(iClosestDist or 'nil')) end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
    return bIsSuitable, iClosestDist
end

function DoesACUWantToSuicideIntoEnemyACU(oACU, iTeam, iPlateauOrZero, iLandOrWaterZone, tLZOrWZTeamData)
    local sFunctionRef = 'DoesACUWantToSuicideIntoEnemyACU'
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)



    if bDebugMessages == true then LOG(sFunctionRef..': Start of code, oACU[refbACUSnipeModeActive]='..tostring(oACU[refbACUSnipeModeActive])..'; oACU brain='..oACU:GetAIBrain().Nickname..'; iPlateauOrZero='..iPlateauOrZero..'; Cur health='..AiBotUnitInfo.GetUnitCurHealthAndShield(oACU)) end
    local oClosestEnemyACU
    if not(oACU[refbACUSnipeModeActive]) and AiBotUtilities.IsTableEmpty(AiBotTeam.tTeamData[iTeam][AiBotTeam.toActiveSnipeTargets]) == false and iPlateauOrZero > 0 then
        local iACUHealth = AiBotUnitInfo.GetUnitCurHealthAndShield(oACU)
        if iACUHealth >= 4000 or not(AiBotTeam.tTeamData[iTeam][AiBotTeam.refbAssassinationOrSimilar]) then
            local bEnemyACUMustBeInExplosionRange = DoesACUOnlyWantToSuicideIfInExplosionRange(oACU, tLZOrWZTeamData, iTeam)

            local iClosestEnemyACUDist = oACU[AiBotUnitInfo.refiDFRange]
            local iCurDist, aiBrain, bIsSuitableForSnipe
            for iSnipeTarget, oSnipeTarget in  AiBotTeam.tTeamData[iTeam][AiBotTeam.toActiveSnipeTargets] do
                bIsSuitableForSnipe, iCurDist = IsTargetSuitableSnipeTarget(oACU, oSnipeTarget, iPlateauOrZero, iClosestEnemyACUDist, bEnemyACUMustBeInExplosionRange)
                if bDebugMessages == true then LOG(sFunctionRef..': Considering if want '..oSnipeTarget:GetAIBrain().Nickname..' unit as a snipe target, bIsSuitableForSnipe='..tostring(bIsSuitableForSnipe)..'; iCurDist='..(iCurDist or 'nil')..'; iClosestEnemyACUDist='..iClosestEnemyACUDist) end
                if bIsSuitableForSnipe and iCurDist <= iClosestEnemyACUDist then
                    iClosestEnemyACUDist = iCurDist
                    oClosestEnemyACU = oSnipeTarget
                    if bDebugMessages == true then LOG(sFunctionRef..': Updating oClosestEnemyACU to oSnipeTarget='..oSnipeTarget.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oSnipeTarget)..' owned by '..oSnipeTarget:GetAIBrain().Nickname..'; iClosestEnemyACUDist='..iClosestEnemyACUDist) end
                end
            end
            if bDebugMessages == true then LOG(sFunctionRef..': Finished checking for potential enemy snipe targets, is oClosestEnemyACU valid='..tostring(oClosestEnemyACU)) end
            if oClosestEnemyACU then
                oACU[refbACUSnipeModeActive] = true
                ForkThread(SuicideACUIntoSnipeTarget, oACU, oClosestEnemyACU)
                if bDebugMessages == true then LOG(sFunctionRef..': Will suicide ACU into this target (via forked thread') end
            end
        end
    end
    --Special case - we have no upgrades, enemy ACU is nearby getting an upgrade, and it is relatively early on, and we have multiple friendly ACUs - consider pushing in to force them to cancel the upgrade
    if oACU[refiUpgradeCount] == 0 and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestFriendlyFactoryTech] < 3 and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestEnemyGroundTech] < 3 and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestEnemyNavyTech] < 2 and not(oACU[refbACUSnipeModeActive]) and iPlateauOrZero > 0 and not(AiBotTeam.tTeamData[iTeam][AiBotTeam.refbAssassinationOrSimilar]) and AiBotTeam.tTeamData[iTeam][AiBotTeam.refbEnemyHasUpgradedACU] and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiActiveAiBotBrainCount] >= 2 and AiBotUtilities.IsTableEmpty(AiBotTeam.tTeamData[iTeam][AiBotTeam.reftEnemyACUs]) == false and AiBotUtilities.IsTableEmpty(AiBotTeam.tTeamData[iTeam][AiBotTeam.reftAiBotACUs]) == false and (tLZOrWZTeamData[AiBotMap.subrefTThreatEnemyCombatTotal] or 0) <= 2000 and oACU:GetHealth() >= 5000 then
        --Get nearest enemy ACU, and number of total nearby enemy ACUs
        if bDebugMessages == true then LOG(sFunctionRef..': Checking if enemy has nearby upgrading ACU, and none nearby that have completed the upgrade, and we have multiple friendly ACUs, refbSupportFriendlyACUAttack='..tostring(oACU[refbSupportFriendlyACUAttack] or false)) end
        local iMaxDistToEnemyACU = oACU[AiBotUnitInfo.refiDFRange] + iACUAssassinationUpgradingRangeAdjust --NOTE: Have an issue where it also needs to be a valid snipe target or else we dont actually try and snipe it
        local iSearchDistEnemyACUs = 100
        local iNearbyEnemyACUCount = 0
        local iFriendlyACUSearchRange = 40
        local bEnemyHasNearbyUpgradedACU = false
        local iCurDist
        local oClosestACUToConsiderAttacking
        if oACU[refbSupportFriendlyACUAttack] then iMaxDistToEnemyACU = iMaxDistToEnemyACU + 25 end
        --First see if we have a nearby enemy ACU that is either upgrading or unupgraded, and dont have many enemy ACUs
        for iEnemyACU, oEnemyACU in AiBotTeam.tTeamData[iTeam][AiBotTeam.reftEnemyACUs] do
            iCurDist = AiBotUtilities.GetDistanceBetweenPositions(oACU:GetPosition(), oEnemyACU:GetPosition())
            if bDebugMessages == true then LOG(sFunctionRef..': Considering ACU owned by '..oEnemyACU:GetAIBrain().Nickname..' and how close it is to oACU owned by '..oACU:GetAIBrain().Nickname..'; iCurDist='..iCurDist..'; Is enemy ACU upgrading='..tostring(oEnemyACU:IsUnitState('Upgrading'))..'; iSearchDistEnemyACUs='..iSearchDistEnemyACUs..'; iMaxDistToEnemyACU='..iMaxDistToEnemyACU) end
            if iCurDist <= iSearchDistEnemyACUs then
                iNearbyEnemyACUCount = iNearbyEnemyACUCount + 1
                if (oEnemyACU[refiUpgradeCount] or 0) > 0 or (oACU:IsUnitState('Upgrading') and oACU:GetWorkProgress() >= 0.8 and (oACU:GetHealth() >= 2500 or iCurDist >= 30)) then
                    if bDebugMessages == true then LOG(sFunctionRef..': ACU is almost done with its upgrade or already has upgrade, so will assume it has gun') end
                    bEnemyHasNearbyUpgradedACU = true
                    break
                end
                if bDebugMessages == true then LOG(sFunctionRef..': Enemy ACU plateau='..(NavUtils.GetLabel(AiBotMap.refPathingTypeHover, oEnemyACU:GetPosition()) or 'nil')..'; our ACU iPlateauOrZero='..iPlateauOrZero..'; Land label for enemy ACU='..(NavUtils.GetLabel(AiBotMap.refPathingTypeLand, oEnemyACU:GetPosition()) or 'nil')) end
                if iCurDist <= iMaxDistToEnemyACU and NavUtils.GetLabel(AiBotMap.refPathingTypeHover, oEnemyACU:GetPosition()) == iPlateauOrZero and (NavUtils.GetLabel(AiBotMap.refPathingTypeLand, oEnemyACU:GetPosition()) or 0) > 0 then
                    --Check it is either upgrading (so vulnerable to us pushing in) or we are almost in range
                    if oEnemyACU:IsUnitState('Upgrading') or iCurDist <= (oACU[AiBotUnitInfo.refiDFRange] or 0) + 2 or oACU[refbSupportFriendlyACUAttack] then
                        iMaxDistToEnemyACU = iCurDist
                        oClosestACUToConsiderAttacking = oEnemyACU
                        if bDebugMessages == true then LOG(sFunctionRef..': Recording as enemy ACU to consider attacking') end
                    end
                end
            end
        end
        if bDebugMessages == true then LOG(sFunctionRef..': Deciding if want to try and attack an ACU e.g. that is stuck upgrading, oClosestACUToConsiderAttacking='..(oClosestACUToConsiderAttacking.UnitId or 'nil')..(AiBotUnitInfo.GetUnitLifetimeCount(oClosestACUToConsiderAttacking) or 'nil')..'; bEnemyHasNearbyUpgradedACU='..tostring(bEnemyHasNearbyUpgradedACU)..'; iNearbyEnemyACUCount='..iNearbyEnemyACUCount) end
        if oClosestACUToConsiderAttacking and not(bEnemyHasNearbyUpgradedACU) and iNearbyEnemyACUCount == 1 then
            --Only 1 enemy ACU, and it either lacks an upgrade or is trying to get one, so consider attacking to force a cancellation if either we have multiple ACUs, or we have significantly more health
            local bHaveMuchMoreHealthOrFriendlyACUs = false
            local toFriendlyACUsToConsiderSupportingAttack = {}

            if oACU:GetHealth() >= oClosestACUToConsiderAttacking:GetHealth() + math.max(2000, oClosestACUToConsiderAttacking:GetHealth() * 0.5) then
                bHaveMuchMoreHealthOrFriendlyACUs = true
            else
                --Do we have nearby friendly ACUs?
                for iFriendlyACU, oFriendlyACU in AiBotTeam.tTeamData[iTeam][AiBotTeam.reftAiBotACUs] do
                    if not(oFriendlyACU == oACU) and not(oFriendlyACU:IsUnitState('Upgrading')) and (oFriendlyACU:GetHealth() >= 4000 or not(oFriendlyACU[refiTimeLastWantedToRun] or GetGameTimeSeconds() - oFriendlyACU[refiTimeLastWantedToRun] > 1.01)) and AiBotUtilities.GetDistanceBetweenPositions(oFriendlyACU:GetPosition(), oACU:GetPosition()) <= iFriendlyACUSearchRange then
                        table.insert(toFriendlyACUsToConsiderSupportingAttack, oFriendlyACU)
                        bHaveMuchMoreHealthOrFriendlyACUs = true
                    end
                end
            end
            table.insert(toFriendlyACUsToConsiderSupportingAttack, oACU)
            if bDebugMessages == true then LOG(sFunctionRef..': Is closest ACU a potential snipe target='..tostring(IsTargetSuitableSnipeTarget(oACU, oClosestACUToConsiderAttacking, iPlateauOrZero, oACU[AiBotUnitInfo.refiDFRange], false, true))..'; oClosestACUToConsiderAttacking owner='..oClosestACUToConsiderAttacking:GetAIBrain().Nickname..'; bHaveMuchMoreHealthOrFriendlyACUs='..tostring(bHaveMuchMoreHealthOrFriendlyACUs)..'; oACU health='..oACU:GetHealth()..'; oClosestACUToConsiderAttacking health='..oClosestACUToConsiderAttacking:GetHealth()) end
            --Note-  we will adjust the distance threshold by iACUAssassinationUpgradingRangeAdjust in IsTargetSuitableSnipeTarget if target is upgrading
            if bHaveMuchMoreHealthOrFriendlyACUs and IsTargetSuitableSnipeTarget(oACU, oClosestACUToConsiderAttacking, iPlateauOrZero, oACU[AiBotUnitInfo.refiDFRange], false, true) then
                --We have a nearby enemy ACU without gun that we either have much more health than, or we have multiple ACUs to attack it with
                local iNearbyEnemyDF = 0
                local iNearbyFriendlyDF = 0
                local iEnemySearchLessRangeDist = 45
                local iFriendlySearchLessRangeDist = 20
                local tLZData = AiBotMap.tAllPlateaus[iPlateauOrZero][AiBotMap.subrefPlateauLandZones][iLandOrWaterZone]
                local tbZoneConsidered = {}
                local toEnemyUnitsNearRange = {}
                local toFriendlyUnitsNearRange = {}
                local toFriendlyACUsInLZCombatUnits = {}
                function ConsiderEnemyAndFriendlyUnits(iCurZone, tCurLZTeamData)
                    if bDebugMessages == true then LOG(sFunctionRef..': Considering iCurZone='..iCurZone..'; Have we already considered this='..tostring(tbZoneConsidered[iCurZone])) end
                    if not(tbZoneConsidered[iCurZone]) then
                        tbZoneConsidered[iCurZone] = true
                        if AiBotUtilities.IsTableEmpty(tCurLZTeamData[AiBotMap.subrefTEnemyUnits]) == false then
                            local tEnemyCombatUnits = EntityCategoryFilterDown(categories.DIRECTFIRE + AiBotUnitInfo.refCategoryIndirect * categories.TECH1, tCurLZTeamData[AiBotMap.subrefTEnemyUnits])
                            if AiBotUtilities.IsTableEmpty(tEnemyCombatUnits) == false then
                                for iUnit, oUnit in tEnemyCombatUnits do
                                    if not(oUnit.Dead) then
                                        iCurDist = AiBotUtilities.GetDistanceBetweenPositions(oUnit:GetPosition(), oACU:GetPosition())
                                        if iCurDist > iEnemySearchLessRangeDist then
                                            iCurDist = math.min(iCurDist, AiBotUtilities.GetDistanceBetweenPositions(oUnit:GetPosition(), oClosestACUToConsiderAttacking:GetPosition()))
                                        end
                                        if iCurDist <= iEnemySearchLessRangeDist or iCurDist - oUnit[AiBotUnitInfo.refiCombatRange] <= iEnemySearchLessRangeDist then
                                            table.insert(toEnemyUnitsNearRange, oUnit)
                                            if bDebugMessages == true then LOG(sFunctionRef..': Including enemy unit '..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..' owned by '..oUnit:GetAIBrain().Nickname..', enemy unit dist to our ACU='..AiBotUtilities.GetDistanceBetweenPositions(oUnit:GetPosition(), oACU:GetPosition())..'; Dist to enemy ACU='..AiBotUtilities.GetDistanceBetweenPositions(oUnit:GetPosition(), oClosestACUToConsiderAttacking:GetPosition())..'; Combat range='..oUnit[AiBotUnitInfo.refiCombatRange]..'; Threat of enemy unit='..AiBotUnitInfo.GetCombatThreatRating({ oUnit}, true)) end
                                        end
                                    end
                                end
                            end
                        end
                        if bDebugMessages == true then LOG(sFunctionRef..': Is table of allied combat units empty='..tostring(AiBotUtilities.IsTableEmpty(tCurLZTeamData[AiBotMap.subrefLZTAlliedCombatUnits]))..'; subrefLZTThreatAllyCombatTotal='..tCurLZTeamData[AiBotMap.subrefLZTThreatAllyCombatTotal]..'; subrefLZThreatAllyMobileDFTotal='..tCurLZTeamData[AiBotMap.subrefLZThreatAllyMobileDFTotal]) end
                        if AiBotUtilities.IsTableEmpty(tCurLZTeamData[AiBotMap.subrefLZTAlliedCombatUnits]) == false then
                            for iUnit, oUnit in tCurLZTeamData[AiBotMap.subrefLZTAlliedCombatUnits] do
                                if not(oUnit.Dead) then
                                    iCurDist = AiBotUtilities.GetDistanceBetweenPositions(oUnit:GetPosition(), oACU:GetPosition())
                                    if iCurDist > iFriendlySearchLessRangeDist then
                                        iCurDist = math.min(iCurDist, AiBotUtilities.GetDistanceBetweenPositions(oUnit:GetPosition(), oClosestACUToConsiderAttacking:GetPosition()))
                                    end
                                    if bDebugMessages == true then LOG(sFunctionRef..': Considering friendly unit '..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..'; Dist to our ACU='..AiBotUtilities.GetDistanceBetweenPositions(oUnit:GetPosition(), oACU:GetPosition())..'; Dist to enemy ACU='..AiBotUtilities.GetDistanceBetweenPositions(oUnit:GetPosition(), oClosestACUToConsiderAttacking:GetPosition())..'; Combat range='..oUnit[AiBotUnitInfo.refiCombatRange]..'; iFriendlySearchLessRangeDist='..iFriendlySearchLessRangeDist..'; DF range='..(oUnit[AiBotUnitInfo.refiDFRange] or 'nil')) end
                                    if iCurDist <= iFriendlySearchLessRangeDist or iCurDist - oUnit[AiBotUnitInfo.refiCombatRange] <= iFriendlySearchLessRangeDist then
                                        if (oUnit[AiBotUnitInfo.refiDFRange] or 0) > 0 or EntityCategoryContains(categories.TECH1, oUnit.UnitId) then
                                            table.insert(toFriendlyUnitsNearRange, oUnit)
                                            if EntityCategoryContains(categories.COMMAND, oUnit.UnitId) then table.insert(toFriendlyACUsInLZCombatUnits, oUnit) end
                                        end
                                    end
                                end
                            end
                        end
                    end
                end
                --search this zone and adjacent zones for DF enemies, and consider pushing attack if total threat isnt too great; will do a precise check (since fairly rare we call this logic)
                ConsiderEnemyAndFriendlyUnits(iLandOrWaterZone, tLZOrWZTeamData)
                local iEnemyACUZone = oClosestACUToConsiderAttacking[AiBotUnitInfo.reftAssignedPlateauAndLandZoneByTeam][iTeam][2]
                tbZoneConsidered[iLandOrWaterZone] = true
                if not(iEnemyACUZone == iLandOrWaterZone) then
                    local tEnemyLZData = AiBotMap.tAllPlateaus[iPlateauOrZero][AiBotMap.subrefPlateauLandZones][iEnemyACUZone]
                    ConsiderEnemyAndFriendlyUnits(iEnemyACUZone, tEnemyLZData[AiBotMap.subrefLZTeamData][iTeam])
                    if AiBotUtilities.IsTableEmpty(tEnemyLZData[AiBotMap.subrefLZAdjacentLandZones]) == false then
                        for _, iAdjLZ in tEnemyLZData[AiBotMap.subrefLZAdjacentLandZones] do
                            ConsiderEnemyAndFriendlyUnits(iAdjLZ, AiBotMap.tAllPlateaus[iPlateauOrZero][AiBotMap.subrefPlateauLandZones][iAdjLZ][AiBotMap.subrefLZTeamData][iTeam])
                        end
                    end
                end

                if AiBotUtilities.IsTableEmpty(tLZData[AiBotMap.subrefLZAdjacentLandZones]) == false then
                    for _, iAdjLZ in tLZData[AiBotMap.subrefLZAdjacentLandZones] do
                        ConsiderEnemyAndFriendlyUnits(iAdjLZ, AiBotMap.tAllPlateaus[iPlateauOrZero][AiBotMap.subrefPlateauLandZones][iAdjLZ][AiBotMap.subrefLZTeamData][iTeam])
                    end
                end
                local bIncludeCurACU = false
                for iFriendlyACU, oFriendlyACU in toFriendlyACUsToConsiderSupportingAttack do
                    bIncludeCurACU = true
                    if AiBotUtilities.IsTableEmpty(toFriendlyACUsInLZCombatUnits) == false then
                        for iRecordedACU, oRecordedACU in toFriendlyACUsInLZCombatUnits do
                            if oRecordedACU == oFriendlyACU then
                                bIncludeCurACU = false
                                break
                            end
                        end
                    end
                    if bIncludeCurACU then
                        table.insert(toFriendlyUnitsNearRange, oFriendlyACU)
                    end
                end
                iNearbyEnemyDF = AiBotUnitInfo.GetCombatThreatRating(toEnemyUnitsNearRange, true)
                iNearbyFriendlyDF = AiBotUnitInfo.GetCombatThreatRating(toFriendlyUnitsNearRange, false)
                if bDebugMessages == true then LOG(sFunctionRef..': iNearbyEnemyDF='..iNearbyEnemyDF..'; iNearbyFriendlyDF='..iNearbyFriendlyDF) end
                if iNearbyFriendlyDF > iNearbyEnemyDF and iNearbyFriendlyDF > 1.2 * iNearbyEnemyDF then
                    if bDebugMessages == true then LOG(sFunctionRef..': Want to press the attack with our ACU, oClosestACUToConsiderAttacking owned by brain '..oClosestACUToConsiderAttacking:GetAIBrain().Nickname) end
                    if AiBotUtilities.IsTableEmpty(toFriendlyUnitsNearRange) == false then
                        for iFriendlyACU, oFriendlyACU in toFriendlyUnitsNearRange do
                            oFriendlyACU[refbSupportFriendlyACUAttack] = true
                        end
                    end
                    oClosestEnemyACU = oClosestACUToConsiderAttacking
                    ForkThread(SuicideACUIntoSnipeTarget, oACU, oClosestEnemyACU)
                end
            end
        end
    end

    if bDebugMessages == true then LOG(sFunctionRef..': End of code, is oClosestEnemyACU valid='..tostring(AiBotUnitInfo.IsUnitValid(oClosestEnemyACU))) end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
    if oClosestEnemyACU then return true
    elseif oACU[refbSupportFriendlyACUAttack] then oACU[refbSupportFriendlyACUAttack] = nil
    end
end

function SuicideACUIntoSnipeTarget(oACU, oSnipeTarget)
    local sFunctionRef = 'SuicideACUIntoSnipeTarget'
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)

    oACU[refbACUSnipeModeActive] = true
    AiBotMicro.EnableUnitMicroUntilManuallyTurnOff(oACU, false)
    AiBotUnitInfo.SetUnitWeaponTargetPriorities(oACU, AiBotUnitInfo.refWeaponPriorityACUSnipe, false)
    local iCurDist
    if bDebugMessages == true then LOG(sFunctionRef..': About to start main loop, is oACU valid='..tostring(AiBotUnitInfo.IsUnitValid(oACU))..'; Time='..GetGameTimeSeconds()) end
    local bOnlyAttackIfInExplosionRange = false
    local iTimeOriginallyInSnipeMode = GetGameTimeSeconds()
    local aiBrain = oACU:GetAIBrain()
    local iDeathNukeDamage = 500
    local iDeathNukeRange = 30
    local iTicksBetweenCycle = 11 --11 is equiv to 1 second I think? However if its above 9 will just wait 1 second to be safe re interaction with ACU general logic
    local iTeam = 1
    local iHealthAdvantageAtStart = oACU:GetHealth() - AiBotUnitInfo.GetUnitCurHealthAndShield(oSnipeTarget)
    if AiBotUnitInfo.IsUnitValid(oACU) then
        iTeam = oACU:GetAIBrain().AiBotTeam
        local tWeapons = oACU:GetBlueprint().Weapon
        for iWeapon, tWeapon in tWeapons do
            if tWeapon.DamageType == 'Deathnuke' then
                iDeathNukeDamage = (tWeapon.NukeInnerRingDamage or iDeathNukeDamage)
                iDeathNukeRange = (tWeapon.NukeInnerRingRadius or iDeathNukeRange)
                break
            end
        end
    end
    if bDebugMessages == true then LOG(sFunctionRef..': About to start main loop, iHealthAdvantageAtStart='..iHealthAdvantageAtStart..'; Time='..GetGameTimeSeconds()) end
    while AiBotUnitInfo.IsUnitValid(oACU) do
        bOnlyAttackIfInExplosionRange = false
        iTicksBetweenCycle = 11 --default
        if not(oSnipeTarget.Dead) and GetGameTimeSeconds() - iTimeOriginallyInSnipeMode >= 5 then --5s delay in case could get into a cycle where we say we shoudl suicide in the main logic, then we abort immediately in this loop. at least this way we have 5s of trying to kill them first
            local tLZOrWZData, tLZOrWZTeamData = AiBotMap.GetLandOrWaterZoneData(oACU:GetPosition(), true, aiBrain.AiBotTeam)
            bOnlyAttackIfInExplosionRange = DoesACUOnlyWantToSuicideIfInExplosionRange(oACU, tLZOrWZTeamData, aiBrain.AiBotTeam, oSnipeTarget, iHealthAdvantageAtStart)
        end
        --IsTargetSuitableSnipeTarget(oACU, oSnipeTarget, iOurACUPlateauOrZero, iDistanceThreshold, bMustBeWithinExplosionThreshold, bCalledFromUpgradingSnipeLogic)
        if IsTargetSuitableSnipeTarget(oACU, oSnipeTarget, NavUtils.GetLabel(AiBotMap.refPathingTypeHover, oACU:GetPosition()), oACU[AiBotUnitInfo.refiDFRange], bOnlyAttackIfInExplosionRange, false, iHealthAdvantageAtStart) then
            --Move towards enemy unless well within range
            iCurDist = AiBotUtilities.GetDistanceBetweenPositions(oSnipeTarget:GetPosition(), oACU:GetPosition())
            if bDebugMessages == true then LOG(sFunctionRef..': Deciding if we want to move closer to target or attackmove, oSnipeTarget owner='..oSnipeTarget:GetAIBrain().Nickname..'; iCurDist='..iCurDist..'; Is shot blocked='..tostring(AiBotLogic.IsShotBlocked(oACU, oSnipeTarget, false, nil))) end
            if iCurDist <= 10 and not(AiBotLogic.IsShotBlocked(oACU, oSnipeTarget, false, nil)) then
                --Attack target
                AiBotOrders.IssueTrackedAggressiveMove(oACU, oSnipeTarget:GetPosition(), 3, false, 'ACUSnipAM', true)
                if bDebugMessages == true then LOG(sFunctionRef..'L Will attackmove to enemy ACU') end

            else
                --Move to target
                AiBotOrders.IssueTrackedMove(oACU, oSnipeTarget:GetPosition(), 3, false, 'ACUSnipM', true)
                if bDebugMessages == true then LOG(sFunctionRef..': Will move to enemy ACU, enemy ACU position='..repru(oSnipeTarget:GetPosition())..'; Will also consider if we want to ctrlk to kill the target, iDeathNukeRange='..iDeathNukeRange..'; iDeathNukeDamage='..iDeathNukeDamage..'; Target health+shield='..AiBotUnitInfo.GetUnitCurHealthAndShield(oSnipeTarget)) end
                if iCurDist < iDeathNukeRange and iCurDist + 6 > iDeathNukeRange and AiBotUnitInfo.GetUnitCurHealthAndShield(oSnipeTarget) < iDeathNukeDamage and (AiBotTeam.tTeamData[iTeam][AiBotTeam.iTotalTeamCount] > 2 or AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiActiveAiBotBrainCount] > 1 or AiBotTeam.tTeamData[oSnipeTarget:GetAIBrain().AiBotTeam][AiBotTeam.refbAssassinationOrSimilar]) then
                    --Monitor every tick if we want to ctrlk
                    iTicksBetweenCycle = 1
                    --ctrl-k if enemy is almost about to go outside our range and we want to
                    if iCurDist + 0.8 > iDeathNukeRange then
                        local bSelfDestruct = false
                        --Behind on eco? then ctrlk
                        if AiBotConditions.GetEnemyTeamActualMassIncome(iTeam) > AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossMass] then
                            bSelfDestruct = true
                        else
                            --About to die to enemy tanks even if we have more health than their ACU? (do longer range for allies than enemy, and include only mobile enemies, and include friendly PD)
                            local tNearbyEnemyUnits = aiBrain:GetUnitsAroundPoint(AiBotUnitInfo.refCategoryMobileDFLand + AiBotUnitInfo.refCategoryDestroyer - categories.COMMAND, oACU:GetPosition(), 40, 'Enemy')
                            if AiBotUtilities.IsTableEmpty(tNearbyEnemyUnits) == false then
                                local tNearbyAlliedUnits = aiBrain:GetUnitsAroundPoint(AiBotUnitInfo.refCategoryMobileDFLand + AiBotUnitInfo.refCategoryDestroyer + AiBotUnitInfo.refCategoryPD, oACU:GetPosition(), 60, 'Ally')
                                local iNearbyAlliedUnitThreat = AiBotUnitInfo.GetCombatThreatRating(tNearbyAlliedUnits, false, false, false)
                                local iNearbyEnemyUnitThreat = AiBotUnitInfo.GetCombatThreatRating(tNearbyEnemyUnits, true, false, false)
                                --Do we have gunships who can save us?
                                if AiBotUnitInfo.IsUnitValid(AiBotTeam.tAirSubteamData[aiBrain.AiBotAirSubteam][AiBotTeam.refoFrontGunship]) and AiBotUtilities.GetDistanceBetweenPositions(oACU:GetPosition(), AiBotTeam.tAirSubteamData[aiBrain.AiBotAirSubteam][AiBotTeam.refoFrontGunship]:GetPosition()) <= 110 then
                                    iNearbyAlliedUnitThreat = iNearbyAlliedUnitThreat + AiBotTeam.tAirSubteamData[aiBrain.AiBotAirSubteam][AiBotTeam.subrefiOurGunshipThreat] * 2
                                    if bDebugMessages == true then LOG(sFunctionRef..': Near front gunship so treating it as available to help us') end
                                end
                                if bDebugMessages == true then LOG(sFunctionRef..': iNearbyEnemyUnitThreat='..iNearbyEnemyUnitThreat..'; iNearbyAlliedUnitThreat='..iNearbyAlliedUnitThreat..'; ACU health%='..AiBotUnitInfo.GetUnitHealthPercent(oACU)) end
                                if iNearbyEnemyUnitThreat > 400 and iNearbyEnemyUnitThreat > iNearbyAlliedUnitThreat then --(for future ref in case change the threhsold - in one scenario AiBot was surrounded by tanks, which had a threat of 837, and was quickly killed)
                                    --If we are significantly ahead on eco then be less likely to ctrlk
                                    if AiBotTeam.tTeamData[iTeam][AiBotTeam.refbAssassinationOrSimilar] and AiBotConditions.GetEnemyTeamActualMassIncome(iTeam) * 1.4 < AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossMass] and (iNearbyEnemyUnitThreat < 2000 or iNearbyEnemyUnitThreat < iNearbyAlliedUnitThreat * 1.5 or oACU:GetHealth() >= 4000) then
                                        if bDebugMessages == true then LOG(sFunctionRef..': Far enough ahead on eco that we should gamble on making it out alive') end
                                    elseif iNearbyEnemyUnitThreat > iNearbyAlliedUnitThreat * 1.1 or AiBotUnitInfo.GetUnitHealthPercent(oACU) <= 0.5 then
                                        bSelfDestruct = true
                                        if bDebugMessages == true then LOG(sFunctionRef..': Enemy has stronger threat than us nearby, or we are getting low on health %, so want to ctrlk') end
                                    end
                                end
                            end
                        end
                        if bDebugMessages == true then LOG(sFunctionRef..': bSelfDestruct='..tostring(bSelfDestruct)..'; Time='..GetGameTimeSeconds()) end
                        if bSelfDestruct then
                            AiBotChat.SendMessage(aiBrain, 'CtrlK', 'You can\'t escape the inevitable', 0, 60, false, false)
                            aiBrain[AiBotChat.refiTimeSentCustomEndOfGameMessage] = GetGameTimeSeconds()
                            AiBotOrders.IssueTrackedKillUnit(oACU)
                            if bDebugMessages == true then LOG(sFunctionRef..': Sent ACU self destruct order') end
                        end
                    end
                end
            end
            AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
            if iTicksBetweenCycle >= 10 and iTicksBetweenCycle <= 11 then
                WaitSeconds(1)
            else
                WaitTicks(iTicksBetweenCycle)
            end

            AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)
            if bDebugMessages == true and AiBotUnitInfo.IsUnitValid(oACU) and AiBotUnitInfo.IsUnitValid(oSnipeTarget) then LOG(sFunctionRef..': About to start new loop at time='..GetGameTimeSeconds()..'; oACU owner='..oACU:GetAIBrain().Nickname..'; oSnipeTarget owner='..oSnipeTarget:GetAIBrain().Nickname) end
        else
            break
        end
    end
    if AiBotUnitInfo.IsUnitValid(oACU) then
        oACU[refbACUSnipeModeActive] = false
        oACU[AiBotUnitInfo.refbSpecialMicroActive] = false
        AiBotUnitInfo.SetUnitWeaponTargetPriorities(oACU, AiBotUnitInfo.refWeaponPriorityACU, false)
    end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
end

function DoesACUOnlyWantToSuicideIfInExplosionRange(oACU, tLZOrWZTeamData, iTeam, oOptionalSnipeTarget, iOptionalHealthAdvantageAtStart)
    local sFunctionRef = 'DoesACUOnlyWantToSuicideIfInExplosionRange'
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)

    local iACUHealth = AiBotUnitInfo.GetUnitCurHealthAndShield(oACU)
    if bDebugMessages == true then LOG(sFunctionRef..': iACUHealth='..iACUHealth..'; Target health='..AiBotUnitInfo.GetUnitCurHealthAndShield(oOptionalSnipeTarget)..'; iHealthAdvantageAtStart='..iOptionalHealthAdvantageAtStart) end
    if iACUHealth >= 8000 then
        AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
        return false
    elseif iACUHealth <= 3000 then
        AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
        return true
    else
        if oOptionalSnipeTarget and iOptionalHealthAdvantageAtStart then
            local iTargetHealth = AiBotUnitInfo.GetUnitCurHealthAndShield(oOptionalSnipeTarget)
            local iCurHealthAdvantage = iACUHealth - iTargetHealth
            if bDebugMessages == true then LOG(sFunctionRef..': If health advantage much worse will return true, iCurHealthAdvantage='..iCurHealthAdvantage..'; iTargetHealth='..iTargetHealth..'; iCurHealthAdvantage - iHealthAdvantageAtStart='..iCurHealthAdvantage - iOptionalHealthAdvantageAtStart) end
            if iCurHealthAdvantage < -500 and iTargetHealth > 3000 and iCurHealthAdvantage - iOptionalHealthAdvantageAtStart < -1000 then
                --The situation has got significantly worse from when we first decided to try and suicide into them
                if bDebugMessages == true then LOG(sFunctionRef..': Will return true') end
                AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
                return true
            end
        end
        --ACU is between 3k and 8k health, so be more cautious if enemy has T2 PD within our range
        local iEnemyT2PDInOurRange = 0
        if AiBotUtilities.IsTableEmpty(tLZOrWZTeamData[AiBotMap.reftoNearestDFEnemies]) == false then
            local tEnemyPD = EntityCategoryFilterDown(AiBotUnitInfo.refCategoryPD, tLZOrWZTeamData[AiBotMap.reftoNearestDFEnemies])
            if AiBotUtilities.IsTableEmpty(tEnemyPD) == false then
                for iPD, oPD in tEnemyPD do
                    if AiBotUnitInfo.IsUnitValid(oPD) and oPD:GetFractionComplete() == 1 and AiBotUtilities.GetDistanceBetweenPositions(oPD:GetPosition(), oACU:GetPosition()) < oPD[AiBotUnitInfo.refiDFRange] then
                        iEnemyT2PDInOurRange = iEnemyT2PDInOurRange + 1
                    end
                end
            end
        end
        if bDebugMessages == true then LOG(sFunctionRef..': iEnemyT2PDInOurRange (includes t1 pd if we lack gun)='..iEnemyT2PDInOurRange) end
        if iEnemyT2PDInOurRange == 0 then
            AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
            return false
        elseif iEnemyT2PDInOurRange >= 4 then
            AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
            return true
        elseif iACUHealth > 3000 + 1500 * iEnemyT2PDInOurRange then
            AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
            return false
        else
            AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
            return true
        end

    end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
end

function UpdateUnitUpgradeCountTrackingIfNotSet(oUnit)
    --E.g. for SACUs that are transferred on player death
    if not(oUnit[refiUpgradeCount]) then
        if __blueprints[oUnit.UnitId].Enhancements then
            for sEnhancement, tEnhancement in __blueprints[oUnit.UnitId].Enhancements do
                if oUnit:HasEnhancement(sEnhancement) then
                    oUnit[refiUpgradeCount] = (oUnit[refiUpgradeCount] or 0) + 1
                    if tEnhancement.Prerequisite then oUnit[refiUpgradeCount] = oUnit[refiUpgradeCount] + 1 end
                end
            end
        end
    end
end

function ACUExpectedToDieBeforeCompletingUpgrade(oACU)
    local sFunctionRef = 'ACUExpectedToDieBeforeCompletingUpgrade'
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)

    if AiBotUtilities.IsTableEmpty(oACU[reftiUpgradingHealthData]) or not(oACU[refiHealthWhenStartedUpgrade]) or not(oACU[AiBotUnitInfo.refsLastEnhancementStarted]) then
        if bDebugMessages == true then LOG(sFunctionRef..': Lack data so returning false') end
        AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
        return false --redundancy
    else
        local iTotalRecordedCycles = table.getn(oACU[reftiUpgradingHealthData])
        if oACU[reftiUpgradingHealthData][iTotalRecordedCycles] + 100 <= oACU[refiHealthWhenStartedUpgrade] then
            local iHealthLoss = oACU[reftiUpgradingHealthData][1] - oACU[reftiUpgradingHealthData][iTotalRecordedCycles]
            if iHealthLoss > 100 then
                --How fast have we lost health?
                local iHealthLossPerCycle = iHealthLoss / math.max(5, (iTotalRecordedCycles - 1))
                --How long for us to complete the upgrade if we dont pause?
                local iTimeToCompleteUpgrade = 250 --redundancy
                local tUpgrades = oACU:GetBlueprint().Enhancements
                if tUpgrades[oACU[AiBotUnitInfo.refsLastEnhancementStarted]].BuildTime then
                    local iBuildRate = (oACU:GetBlueprint().Economy.BuildRate or 10)
                    if oACU.HasEnhancement then
                        if oACU:HasEnhancement('AdvancedEngineering') then
                            iBuildRate = (oACU:GetBlueprint().Enhancements.AdvancedEngineering.BuildRate or 42)
                        elseif oACU:HasEnhancement('T3Engineering') then
                            iBuildRate = (oACU:GetBlueprint().Enhancements.T3Engineering.BuildRate or 100)
                        end
                    end
                    iBuildRate = iBuildRate * (oACU:GetAIBrain()[AiBotEconomy.refiBrainBuildRateMultiplier] or 1)
                    iTimeToCompleteUpgrade = (tUpgrades[oACU[AiBotUnitInfo.refsLastEnhancementStarted]].BuildTime * (1 - oACU:GetWorkProgress())) / iBuildRate
                end
                --Will we complete with a few seconds to spare?
                if bDebugMessages == true then LOG(sFunctionRef..': iHealthLossPerCycle='..iHealthLossPerCycle..'; iTimeToCompleteUpgrade='..iTimeToCompleteUpgrade..'; oACU[reftiUpgradingHealthData][iTotalRecordedCycles]='..oACU[reftiUpgradingHealthData][iTotalRecordedCycles]..'; Health at record 1='..oACU[reftiUpgradingHealthData][1]) end
                if iHealthLossPerCycle * (iTimeToCompleteUpgrade + math.min(30, iTimeToCompleteUpgrade * 0.2)) >= oACU[reftiUpgradingHealthData][iTotalRecordedCycles] then
                    if bDebugMessages == true then LOG(sFunctionRef..': We think we will die or come close so want to abort') end
                    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
                    return true
                end
            end
        elseif bDebugMessages == true then LOG(sFunctionRef..': Health isnt lower than when we first started upgrade so will continue')
        end

    end
    if bDebugMessages == true then LOG(sFunctionRef..': We dont expect to die before completing the upgrade') end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
    return false
end

function UpdateACUUpgradingHealth(oACU)
    if AiBotUtilities.IsTableEmpty(oACU[reftiUpgradingHealthData]) or table.getn(oACU[reftiUpgradingHealthData]) < 6 then
        --Nothing to remove
    else
        table.remove(oACU[reftiUpgradingHealthData], 1)
    end
    if not(oACU[reftiUpgradingHealthData]) then oACU[reftiUpgradingHealthData] = {} end
    table.insert(oACU[reftiUpgradingHealthData], AiBotUnitInfo.GetUnitCurHealthAndShield(oACU))
end

function RecordCommonACUTarget(oOurACU, oClosestFriendlyACU, oClosestEnemyACU, bJustRecordForOurACU)
    local sFunctionRef = 'RecordCommonACUTarget'
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)

    local iEntryRef
    if AiBotUtilities.IsTableEmpty(oOurACU[reftCommonACUTarget]) == false then
        for iExistingEntry, tSubtable in oOurACU[reftCommonACUTarget] do
            if tSubtable[subrefoEnemyACU] == oClosestEnemyACU and tSubtable[subrefoFriendlyACU] == oClosestFriendlyACU then
                iEntryRef = iExistingEntry
                break
            end
        end
    else
        oOurACU[reftCommonACUTarget] = {}
    end
    if not(iEntryRef) then
        table.insert(oOurACU[reftCommonACUTarget], {[subrefoEnemyACU] = oClosestEnemyACU, [subrefoFriendlyACU] = oClosestFriendlyACU})
        iEntryRef = table.getn(oOurACU[reftCommonACUTarget])
    end
    oOurACU[reftCommonACUTarget][iEntryRef][subrefiTimeLastRecorded] = GetGameTimeSeconds()
    if not(bJustRecordForOurACU) then
        --Record for closestfriendlyACU as well
        RecordCommonACUTarget(oClosestFriendlyACU, oOurACU, oClosestEnemyACU, true)

        --And record for enemy
        iEntryRef = nil
        if AiBotUtilities.IsTableEmpty(oClosestEnemyACU[reftCommonACUTarget]) == false then
            for iExistingEntry, tSubtable in oClosestEnemyACU[reftCommonACUTarget] do
                if (tSubtable[subrefoEnemyACU] == oOurACU and tSubtable[subrefoSecondEnemyACU] == oClosestFriendlyACU) or (tSubtable[subrefoEnemyACU] == oClosestFriendlyACU and tSubtable[subrefoSecondEnemyACU] == oOurACU) then
                    iEntryRef = iExistingEntry
                    break
                end
            end
        else
            oClosestEnemyACU[reftCommonACUTarget] = {}
        end
        if not(iEntryRef) then
            table.insert(oClosestEnemyACU[reftCommonACUTarget], {[subrefoEnemyACU] = oOurACU, [subrefoSecondEnemyACU] = oClosestFriendlyACU})
            iEntryRef = table.getn(oClosestEnemyACU[reftCommonACUTarget])
        end
        oClosestEnemyACU[reftCommonACUTarget][iEntryRef][subrefiTimeLastRecorded] = GetGameTimeSeconds()
    end
    if bDebugMessages == true then LOG(sFunctionRef..': Finished recording, oClosestFriendlyACU owner='..oClosestFriendlyACU:GetAIBrain().Nickname..'; oClosestEnemyACU owner='..oClosestEnemyACU:GetAIBrain().Nickname..'; Time='..GetGameTimeSeconds()) end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
end

function HaveRecentCommonACUTarget(oOurACU)
    local sFunctionRef = 'RecordCommonACUTarget'
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)

    if bDebugMessages == true then LOG(sFunctionRef..': Start of code, is reftCommonACUTarget empty='..tostring(AiBotUtilities.IsTableEmpty(oOurACU[reftCommonACUTarget]))..'; Time='..GetGameTimeSeconds()) end
    if oOurACU[reftCommonACUTarget] and AiBotUtilities.IsTableEmpty(oOurACU[reftCommonACUTarget]) == false then
        local iLastCommonTargetTime = 1000
        local iCurCommonTargetTime
        for iExistingEntry, tSubtable in oOurACU[reftCommonACUTarget] do
            iCurCommonTargetTime = GetGameTimeSeconds() - (tSubtable[subrefiTimeLastRecorded] or 0)
            if bDebugMessages == true then LOG(sFunctionRef..': Considering iExistingEntry='..iExistingEntry..'; iCurCommonTargetTime='..iCurCommonTargetTime) end
            if iCurCommonTargetTime <= 10 and not(tSubtable[subrefoSecondEnemyACU]) and AiBotUnitInfo.IsUnitValid(tSubtable[subrefoFriendlyACU]) then
                AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
                return true
            elseif iCurCommonTargetTime < iLastCommonTargetTime then iLastCommonTargetTime = iCurCommonTargetTime
            end
        end
        if iLastCommonTargetTime > 20 then
            --Clear all entries
            if bDebugMessages == true then LOG(sFunctionRef..': Clearing all entries for common target') end
            oOurACU[reftCommonACUTarget] = nil
        end
    end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
    return false
end
function IsEnemyACUBeingTargetedByMultipleOfOurACUs(oEnemyACU, iTeam)
    local sFunctionRef = 'RecordCommonACUTarget'
