    if oEnemyACU[reftCommonACUTarget] and AiBotUtilities.IsTableEmpty(oEnemyACU[reftCommonACUTarget]) == false then
        local iLastCommonTargetTime = 1000
        local iCurCommonTargetTime
        for iExistingEntry, tSubtable in oEnemyACU[reftCommonACUTarget] do
            iCurCommonTargetTime = GetGameTimeSeconds() - (tSubtable[subrefiTimeLastRecorded] or 0)
            if bDebugMessages == true then LOG(sFunctionRef..': Considering iExistingEntry='..iExistingEntry..'; iCurCommonTargetTime='..iCurCommonTargetTime) end
            if iCurCommonTargetTime <= 10 and AiBotUnitInfo.IsUnitValid(tSubtable[subrefoSecondEnemyACU]) and tSubtable[subrefoSecondEnemyACU]:GetAIBrain().AiBotTeam == iTeam and AiBotUnitInfo.IsUnitValid(tSubtable[subrefoEnemyACU]) then
                AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
