            elseif iCurCommonTargetTime < iLastCommonTargetTime then iLastCommonTargetTime = iCurCommonTargetTime
            end
        end
        if iLastCommonTargetTime > 20 then
            --Clear all entries
            if bDebugMessages == true then LOG(sFunctionRef..': Clearing all entries for common target') end
            oEnemyACU[reftCommonACUTarget] = nil
        end
    end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
    return false
end

function ACUStuckAndGivenIntermediateMovePoint(oACU, tMovePoint)
    --If ACU appears stuck and not moving then will give it a shorter move point - decided not to use this for now as it didnt help in the replay where ACU got stuck (no matter what order it was given)

    local sFunctionRef = 'ACUStuckAndGivenIntermediateMovePoint'
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)

    if bDebugMessages == true then LOG(sFunctionRef..': Considering if ACU is stuck, Last order subrefiOrderType='..(oACU[AiBotOrders.reftiLastOrders][1][AiBotOrders.subrefiOrderType] or 'nil')..'; AiBotOrders.refiOrderIssueMove='..AiBotOrders.refiOrderIssueMove..'; refbSpecialMicroActive='..tostring(oACU[AiBotUnitInfo.refbSpecialMicroActive] or false)..'; Speed='..AiBotUnitInfo.GetUnitSpeed(oACU)..'; ACU owned by '..oACU:GetAIBrain().Nickname..'; Time='..GetGameTimeSeconds()) end
    if (oACU[AiBotOrders.reftiLastOrders][1][AiBotOrders.subrefiOrderType] or AiBotOrders.refiOrderIssueMove) == AiBotOrders.refiOrderIssueMove and not(oACU[AiBotUnitInfo.refbSpecialMicroActive]) and AiBotUnitInfo.GetUnitSpeed(oACU) < 0.1 then
        local iCurDistToTarget = AiBotUtilities.GetDistanceBetweenPositions(oACU:GetPosition(), tMovePoint)
        if iCurDistToTarget >= 30 and (not(oACU[AiBotOrders.reftiLastOrders][1]) or AiBotUtilities.GetDistanceBetweenPositions(oACU[AiBotOrders.reftiLastOrders][1][AiBotOrders.subreftOrderPosition], tMovePoint) <= 0.5) then
            if bDebugMessages == true then LOG(sFunctionRef..': iCurDistToTarget='..iCurDistToTarget..'; refiACUStuckCount='..(oACU[refiACUStuckCount] or 'nil')..'; ACU owned by '..oACU:GetAIBrain().Nickname) end
            if (oACU[refiACUStuckCount] or 2) >= 1 then
                --Get interim move point
                local tFullPath, iPathSize, iDistance = NavUtils.PathTo(AiBotMap.refPathingTypeAmphibious, oACU:GetPosition(), tMovePoint, nil)
                local tNewMovePoint
                if bDebugMessages == true then LOG(sFunctionRef..': tFullPath='..repru(tFullPath)..'; iDistance='..(iDistance or 'nil')) end
                if tFullPath[1] then
                    tNewMovePoint = tFullPath[1]
                else
                    local iAngleToMovePoint = AiBotUtilities.GetAngleFromAToB(oACU:GetPosition(), tMovePoint)
                    local tPotentialNewPoint
                    local iIslandWanted = NavUtils.GetTerrainLabel(AiBotMap.refPathingTypeAmphibious, tMovePoint)
                    if iIslandWanted then
                        for iDistance = 5, math.min(60, iCurDistToTarget), 5 do
                            tPotentialNewPoint = AiBotUtilities.MoveInDirection(oACU:GetPosition(), iAngleToMovePoint, iDistance, true, true, AiBotMap.bIsCampaignMap)

                            if bDebugMessages == true then LOG(sFunctionRef..': iDistance='..iDistance..'; iIslandWanted='..iIslandWanted..'; Amphibious ref of tPotentialNewPoint='..(NavUtils.GetTerrainLabel(AiBotMap.refPathingTypeAmphibious, tPotentialNewPoint) or 'nil')) end
                            if AiBotUtilities.IsTableEmpty(tPotentialNewPoint) == false and NavUtils.GetTerrainLabel(AiBotMap.refPathingTypeAmphibious, tPotentialNewPoint) == iIslandWanted then
                                tNewMovePoint = {tPotentialNewPoint[1], tPotentialNewPoint[2], tPotentialNewPoint[3]}
                                break
                            end
                        end
                    else
                        --Just try moving in the direction slightly
                        tPotentialNewPoint = AiBotUtilities.MoveInDirection(oACU:GetPosition(), iAngleToMovePoint, 2, true, true, AiBotMap.bIsCampaignMap)
                        if bDebugMessages == true then LOG(sFunctionRef..': Will try moving a few small steps in the direction wanted') end
                    end
                end

                if tNewMovePoint then
                    AiBotOrders.IssueTrackedMove(oACU, tNewMovePoint, 0, false, 'ACUStuck', false)
                    AiBotMicro.TrackTemporaryUnitMicro(oACU, 2, nil, true)
                    oACU[refiACUStuckCount] = 0
                    if bDebugMessages == true then
                        LOG(sFunctionRef..': Given ACU temporary move order towards ultimate destination, oACU[AiBotUnitInfo.refbSpecialMicroActive]='..tostring(oACU[AiBotUnitInfo.refbSpecialMicroActive] or false))
                        AiBotUtilities.DrawLocation(tNewMovePoint)
                    end
                    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
                    return true
                else
                    oACU[refiACUStuckCount] = (oACU[refiACUStuckCount] or 0) + 1
                end
            else
                oACU[refiACUStuckCount] = (oACU[refiACUStuckCount] or 0) + 1
            end
        end

    end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)--]]
end
